local P = LoreForeverPacks.Begin("LoreForever_Lang_ptBR")
P.entries["item:notched-rib"] = {n="Costela Carcomida",s="Uma Costela Carcomida é um troféu ósseo colhido das fileiras dos mortos-vivos irracionais que vagam pelas Clareiras de Tirisfal. O Necroguarda Dinis em Montalvo coleta esses restos marcados como prova dos esforços para quebrar o domínio do Flagelo nos Moinhos dos Agamand.",h="Uma Costela Carcomida é um troféu ósseo colhido das fileiras dos mortos-vivos irracionais que vagam pelas...",kw={"moinhos dos agamand","montalvo","cracked skull soldier","necroguarda dinis","costela carcomida","rattlecage soldier","flagelo","clareiras de tirisfal"},ang={["race:Undead"]="Para os Renegados, coletar esses ossos despedaçados é parte de uma guerra contínua pela sobrevivência contra os lacaios irracionais do Lich Rei, que pretendem arrastá-los de volta à servidão."},sec={{t="Sombria Prova de Batalha",b="As forças do Flagelo que se aglomeram nos campos ao norte das Clareiras de Tirisfal consistem em esqueletos reanimados vestidos com armaduras arruinadas. Em suas fileiras, Cracked Skull Soldiers e Rattlecage Soldiers se lançam contra qualquer ser vivo ou de livre arbítrio que encontrem. Golpear suas estruturas frágeis deixa sua estrutura óssea perfurada e marcada. Para garantir que os batedores e voluntários Renegados realmente eliminem esses invasores irracionais, em vez de apenas observá-los, os Necroguardas exigem evidências tangíveis. Uma costela carcomida e marcada pelo combate serve como prova inconfundível de que mais um servo do Lich Rei foi despedaçado."},{t="Protegendo os Moinhos",b="Os Moinhos dos Agamand representam uma posição estratégica crítica a noroeste de Montalvo. Se o Flagelo se entrincheirasse com firmeza entre as fazendas e moinhos de vento arruinados, eles teriam uma base de operações direta para lançar ataques bem no coração de Tirisfal. O Necroguarda Dinis monitora as estradas que levam ao norte, enviando campeões para esmagar as coortes de esqueletos antes que possam se consolidar. Pilhas de costelas carcomidas levadas de volta a Montalvo demonstram que as linhas dos Renegados estão resistindo, desgastando lentamente a vanguarda do Flagelo, osso por osso."}},faq={{q="O que é uma Costela Carcomida?",a="É um osso esquelético marcado retirado dos soldados reanimados do Flagelo que ocupam o norte das Clareiras de Tirisfal. Ele é levado ao Necroguarda Dinis como confirmação física de inimigos destruídos.",al={"costela carcomida","o que e costela carcomida","item costela carcomida"}},{q="De onde vêm as Costelas Carcomidas?",a="Elas são obtidas de Cracked Skull Soldiers e Rattlecage Soldiers encontrados patrulhando as terras dos Moinhos dos Agamand, a noroeste de Montalvo.",al={"onde encontrar costela carcomida","quem saqueia costela carcomida","fonte da costela carcomida"}},{q="Quem quer esses ossos?",a="O Necroguarda Dinis, posicionado ao longo da estrada nos arredores de Montalvo, coleta-os juntamente com Blackened Skulls para confirmar que o avanço do Flagelo foi repelido.",al={"quem aceita costela carcomida","entregar costela carcomida","quem precisa de costela carcomida"}},{q="Por que o Flagelo está se reunindo nos Moinhos dos Agamand?",a="Os mortos-vivos irracionais estão tentando estabelecer uma base de operações nos moinhos. Dessa posição vantajosa, as forças do Flagelo poderiam lançar ataques facilmente por todas as Clareiras de Tirisfal e ameaçar os assentamentos dos Renegados.",al={"flagelo nos moinhos dos agamand","por que ha esqueletos nos moinhos","ameaca do flagelo nos moinhos dos agamand"}}},fp="11,94,20.425.0,18.445.0,22.169.0,32.119.0,22.142.0,46.155.0"}
P.entries["item:nugget-slug"] = {n="Chumbalheira",s="Chumbalheiras são fixadores mecânicos especializados de calibre 17,5 usados na engenharia industrial. Estocadas em baldes de ferramentas pela Empreendimentos S.A. no Charco de Lodo, elas são cobiçadas por engenhocas que tentam consertar maquinários voláteis.",h="Chumbalheiras são fixadores mecânicos especializados de calibre 17,5 usados na engenharia industrial.",kw={"sertões","chumbalheira","samoflange","charco de lodo","balde de ferramentas","empreendimentos s.a.","juntatudy jogafora"},ang={["profession:Engineering"]="Todo engenheiro sabe que misturar ferragens proprietárias de calibre dezessete e meio com um samoflange instável de engenharia gúbica é um convite para um desmantelamento rápido e explosivo."},sec={{t="Fixadores Industriais do Charco de Lodo",b="Chumbalheiras são fixadores metálicos de alta resistência fabricados para montagens industriais exigentes. Com o tamanho específico de calibre 17,5, esses componentes são uma parte essencial dos equipamentos pesados mobilizados nos locais de extração da Empreendimentos S.A. Embora sejam inúteis como mercadorias comuns de comércio, são indispensáveis para engenhocas lidando com equipamentos gúbicos personalizados."},{t="Engenhando com o Samoflange",b="Juntatudy Jogafora precisa de uma coleção substancial de chumbalheiras para reformar um samoflange instável recuperado nos Sertões. Como a Empreendimentos S.A. costuma deixar baldes de ferramentas espalhados por suas operações de perfuração no Charco de Lodo, as operações de resgate mostram-se lucrativas para saqueadores — mesmo que os eventuais reparos de Juntatudy resultem em uma falha repentina e explosiva."}},faq={{q="O que é uma chumbalheira?",a="Uma chumbalheira é um fixador metálico especializado de calibre 17,5 usado em maquinários pesados. Elas servem como componentes estruturais dentro de mecanismos industriais complexos, como perfuratrizes de petróleo e samoflanges.",al={"o que são chumbalheiras","história da chumbalheira","fixador de chumbalheira"}},{q="Onde as chumbalheiras são encontradas?",a="Elas ficam guardadas em baldes de ferramentas espalhados pelo Charco de Lodo, um acampamento de perfuração da Empreendimentos S.A. localizado no nordeste dos Sertões.",al={"onde encontrar chumbalheiras","localização da chumbalheira","baldes de ferramentas do charco de lodo"}},{q="Por que Juntatudy Jogafora precisa delas?",a="Juntatudy Jogafora quer mexer e consertar um samoflange recuperado. Tendo ficado sem fixadores de calibre dezessete e meio, ela envia aventureiros para resgatá-los do acampamento próximo da Empreendimentos S.A.",al={"quem precisa de chumbalheiras","por que juntatudy quer chumbalheiras","conserto do samoflange"}},{q="O uso das chumbalheiras conserta o samoflange?",a="Não com sucesso. Assim que Juntatudy instala os componentes recuperados na máquina e começa seu trabalho de manutenção, o samoflange detona abruptamente na frente dela.",al={"a máquina funciona","explosão do samoflange","resultado do reparo de juntatudy"}}},fx={f3aea894={q="De onde vêm as Nugget Slugs e quem as faz?",a="Estas balas específicas de calibre dezessete vírgula cinco são ferragens industriais utilizadas pela Empreendimentos S.A. no Charco de Lodo. Seus trabalhadores e engenheiros as mantêm estocadas em baldes de ferramentas espalhados por suas obras de perfuração e escavação nos Sertões orientais.",al={"de onde vêm as nugget slugs","quem faz as nugget slugs","origem da nugget slug"}}},fp="11,185,38.263.0,30.327.1,22.174.0,29.131.0,38.228.0,48.115.1"}
P.entries["item:oathstone-of-ysera-s-dragonflight"] = {n="Oathstone of Ysera's Dragonflight",s="O Oathstone of Ysera's Dragonflight guarda as palavras de Itharius sobre Eranikus. Ele chama você a escolher no Pântano das Mágoas.",h="O Oathstone of Ysera's Dragonflight guarda as palavras de Itharius sobre Eranikus.",kw={"chained essence","revoada dragônica","eranikus","itharius","oathstone","redenção","pântano das mágoas","ysera"},sec={{t="Uma incumbência",b="No Pântano das Mágoas, Itharius lhe entrega o Oathstone depois de conversar com você sobre Eranikus. Ao ativar a pedra, a voz dele alcança sua mente. Ele pede que você aceite uma incumbência a serviço de Ysera's Dragonflight."},{t="A escolha",b="A incumbência de Itharius pede que você ajude a redimir a alma corrompida de Eranikus. Para começar, você precisa abrir mão de Chained Essence of Eranikus, que guarda o que resta do livre-arbítrio de Eranikus. Itharius chama isso de o primeiro de muitos sacrifícios. Cabe a você decidir se ajudará Ysera's Dragonflight."}},faq={{q="O que o Oathstone faz?",a="Ao ativar o Oathstone, Itharius fala à sua mente e pede que você ajude Ysera's Dragonflight a redimir Eranikus.",al={"para que serve o oathstone","propósito do oathstone"}},{q="Quem lhe entrega o Oathstone?",a="Itharius lhe entrega o Oathstone depois de conversar com você sobre Eranikus no Pântano das Mágoas.",al={"quem entrega o oathstone","pedra de itharius"}},{q="Que escolha a pedra oferece?",a="O Oathstone pede que você escolha se ajudará Ysera's Dragonflight a redimir Eranikus.",al={"escolha do oathstone","ajudar ysera ou não"}},{q="De que você precisa abrir mão?",a="Itharius pede que você abra mão de Chained Essence of Eranikus, que mantém acorrentado o que resta do livre-arbítrio de Eranikus.",al={"qual sacrifício","chained essence"}}},fp="33,128,14.215.0,10.280.1,27.123.1,28.96.0,33.91.1,22.115.1"}
P.entries["item:ogre-s-monocle"] = {n="Monóculo do Ogro",s="O Monóculo do Ogro é uma lente avantajada usada por Zzarc'Vul, um ogro que habita a Gruta de Vul'Gol, no sul da Floresta do Crepúsculo. Sua imensa lente de vidro fornece as dimensões exatas necessárias para que Vitório Prismado, em Vila Sombria, monte um elaborado telescópio de observação astronômica.",h="O Monóculo do Ogro é uma lente avantajada usada por Zzarc'Vul, um ogro que habita a Gruta de Vul'Gol, no sul...",kw={"cog","vila sombria","look to the stars","monóculo do ogro","telescópio","vitório prismado","gruta de vul'gol","zzarc'vul"},ang={["faction:Alliance"]="Recuperar a lente dos ogros de Vul'Gol remove um bruto perigoso dos bosques do sul, enquanto ajuda os cidadãos acuados de Vila Sombria a encontrarem consolo nas estrelas.",["profession:Engineering"]="A planta feita por Cog demonstra a ambição típica dos gnomos: utilizar componentes fora do padrão, como óculos gigantes, quando lentes polidas de precisão não estão disponíveis em campo."},sec={{t="Uma Lente Curiosa",b="Embora os ogros raramente sejam conhecidos por sua erudição refinada, Zzarc'Vul de alguma forma tomou posse de um monóculo enorme, feito sob medida para sua estatura imensa. Quando o morador de Vila Sombria, Vitório Prismado, decidiu construir um instrumento de observação estelar usando plantas projetadas pelo engenheiro gnomo Cog, ele descobriu que as lentes padrão eram pequenas demais. Os óculos de Zzarc'Vul revelaram-se a única peça de vidro polido na região com a curvatura e o tamanho necessários para focalizar a luz através do dispositivo concluído."},{t="Arrancando-o de Vul'Gol",b="Adquirir o monóculo exige desbravar a Gruta de Vul'Gol à sombra do sul da Floresta do Crepúsculo. Zzarc'Vul reside entre seus irmãos brutamontes, demonstrando pouca disposição para se desfazer voluntariamente de seu acessório peculiar. Reivindicar a lente significa derrotar o bruto em seu próprio território antes de devolver o vidro a Vila Sombria, para que Vitório possa finalmente voltar seu olhar para os céus noturnos."}},faq={{q="Quem carrega o Monóculo do Ogro?",a="O monóculo está em posse de Zzarc'Vul, um ogro notável encontrado perambulando na Gruta de Vul'Gol, no sul da Floresta do Crepúsculo.",al={"quem dropa o monóculo","quem tem o monóculo do ogro","item de zzarc'vul"}},{q="Por que Vitório Prismado precisa de uma lente de ogro?",a="Vitório está construindo um telescópio com base em plantas desenhadas pelo gnomo Cog. O dispositivo requer uma lente óptica excepcionalmente grande, e o enorme monóculo de Zzarc'Vul é a única peça de vidro na Floresta do Crepúsculo que atende às especificações.",al={"por que precisa do monóculo","para que serve o monóculo","lente de telescópio"}},{q="Como um ogro conseguiu um monóculo gigante?",a="A fonte não explica como Zzarc'Vul adquiriu o monóculo. Ela apenas estabelece que ele possui um grande o suficiente para o telescópio de Vitório.",al={"por que um ogro tem um monóculo","lore dos óculos de leitura de ogro"}},{q="Onde fica a Gruta de Vul'Gol?",a="A Gruta de Vul'Gol fica nas colinas do sul da Floresta do Crepúsculo, ao sul da estrada principal que liga Vila Sombria à fronteira oeste.",al={"onde fica vul'gol","gruta dos ogros floresta do crepúsculo"}}},fx={["94fbe42d"]={q="O que é o Monóculo do Ogro?",a="O Monóculo do Ogro é uma lente óptica superdimensionada usada como uma ocular por Zzarc'Vul, um ogro proeminente que reside dentro da Gruta de Vul'Gol na Floresta do Crepúsculo do sul. Embora tal acessório óptico fino seja extremamente raro entre os ogros, sua lente de vidro massiva a torna singularmente adequada para maquinário óptico pesado.",al={"o que é o monóculo do ogro","item monóculo do ogro","ocular de ogro"}}},fp="14,186,14.351.0,22.286.0,31.87.0,54.175.0,36.131.0,40.127.0"}
P.entries["item:okra"] = {n="Quiabo",s="O quiabo é um vegetal cultivado que cresce nos canteiros arados de Cerro Oeste. Muito apreciado pelos colonos locais, ele serve como um agente espessante crucial nos ensopados fartos e improvisados da região.",h="O quiabo é um vegetal cultivado que cresce nos canteiros arados de Cerro Oeste.",kw={"plantação","fazenda","quiabo","saldanha","salma saldanha","vegetal","ensopado de cerro oeste"},ang={["faction:Alliance"]="Enquanto os nobres de Ventobravo jantam carnes importadas, os colonos da fronteira da Aliança sobrevivem cultivando plantações resistentes como o quiabo em meio às ruínas de Cerro Oeste.",["profession:Cooking"]="Qualquer cozinheiro errante sabe que um bom ensopado precisa de mais do que carne crua; o quiabo fornece o amido e a consistência necessários para transformar a caça dura da natureza em uma refeição quente de verdade."},sec={{t="Um Alimento Básico da Fazenda dos Saldanha",b="Embora grande parte de Cerro Oeste permaneça em pousio sob a ameaça dos bandidos Defias e ataques de golens da colheita rebeldes, fazendeiros obstinados como os Saldanha ainda conseguem extrair vegetais resistentes do solo. O quiabo cresce baixo e verde na terra arada ao redor da Fazenda dos Saldanha. Apesar das duras condições do campo, a plantação persiste, fornecendo aos colonos locais volume e nutrição essenciais quando o comércio externo e os suprimentos de Ventobravo secam por completo."},{t="Ensopado de Cerro Oeste",b="O quiabo é mais conhecido como a base indispensável para o famoso Ensopado de Cerro Oeste de Salma Saldanha. Combinado com qualquer carne que possa ser caçada pelas planícies poeirentas — como carne de abutre, focinhos de presanegra e olhos de murlocs costeiros —, as vagens fatiadas desmancham com o calor para engrossar caldos ralos em uma refeição substanciosa e revigorante. Para os colonos em dificuldades que se apegam às suas propriedades, vagens frescas de quiabo transformam coletas escassas e selvagens em um jantar quente e farto."}},faq={{q="Onde o quiabo cresce em Cerro Oeste?",a="O quiabo cresce nos canteiros de cultivo arados na Fazenda dos Saldanha, situada ao longo da estrada central de Cerro Oeste. Os viajantes podem encontrar as distintas plantas verdes vicejando nos sulcos próximos à propriedade do Fazendeiro Saldanha.",al={"localização do quiabo","onde encontrar quiabo","onde o quiabo cresce"}},{q="Para que serve o quiabo?",a="O quiabo é colhido para Salma Saldanha na Fazenda dos Saldanha para preparar seu emblemático Ensopado de Cerro Oeste. Seu amido natural engrossa o caldo, misturando ingredientes rústicos como carne de abutre, focinhos de javali e olhos de murloc em uma refeição farta.",al={"usos do quiabo","para que serve o quiabo","por que preciso de quiabo"}},{q="Por que o quiabo é importante para os Saldanha?",a="Com as rotas de comércio interrompidas e o reino prestando pouco auxílio, os colonos precisam depender inteiramente do que conseguem cultivar e caçar por conta própria. O quiabo é uma das poucas culturas remanescentes na Fazenda dos Saldanha, mantendo a família e viajantes que passam por ali bem alimentados.",al={"quiabo saldanha","importância do quiabo"}}},fx={["301f0b5e"]={q="O que é o quiabo?",a="O quiabo é um vegetal comestível que cresce no solo cultivado de Cerro Oeste. Cultivado em propriedades rurais como a Fazenda Saldanha, suas vagens são resistentes o suficiente para sobreviver ao clima conturbado da região e se tornam uma cultura básica confiável para os fazendeiros que lutam para sobreviver.",al={"o que é quiabo","item quiabo","planta quiabo"}},["5bbd3a8c"]={q="De onde vem o quiabo?",a="O quiabo é cultivado localmente nas fazendas de Cerro Oeste, notadamente por Salma e pelo Fazendeiro Saldanha na Fazenda Saldanha. Embora grande parte do campo tenha caído em ruínas e abandono, culturas resistentes como o quiabo continuam a crescer nos campos cultivados que restaram.",al={"de onde vem o quiabo","quem cultiva quiabo","origem do quiabo"}},b45f6830={q="Por que Salma Saldanha quer quiabo?",a="Salma Saldanha precisa de quiabo fresco como ingrediente essencial para seu famoso Westfall Stew. Quando fatiado e cozido em fogo brando junto com caça selvagem e carnes locais, o vegetal ajuda a engrossar o caldo saboroso, proporcionando uma refeição rica e farta para sustentar as pessoas das planícies.",al={"por que o quiabo é procurado","por que salma quer quiabo","quem quer quiabo"}}},fp="4,136,26.306.0,13.393.0,33.147.0,22.188.0,38.219.0"}
P.entries["item:or-kalar-s-head"] = {n="Or'Kalar's Head",s="Or'Kalar's Head prova que os ataques à Ruína do Martelo têm uma origem perigosa. Korin Fel pede que você leve a cabeça até ela no posto avançado.",h="Or'Kalar's Head prova que os ataques à Ruína do Martelo têm uma origem perigosa.",kw={"planalto arathi","ruína do martelo","korin fel","mug'thol","or'kalar","or'kalar's head","stromgarde","torre de arathor"},ang={["faction:Horde"]="Como integrante da Horda, você pode ajudar a proteger a Ruína do Martelo e o marido de Korin Fel do ataque de Or'Kalar."},sec={{t="Uma ameaça à Ruína do Martelo",b="Korin Fel envia você para encontrar Or'Kalar perto da Torre de Arathor. O ogro serve a Mug'thol em Stromgarde e nutre um ódio feroz pelo marido de Korin, que o derrotou há anos. Korin acredita que Or'Kalar armou uma cilada para o marido. Ela pede que você o mate e leve a cabeça dele para Ruína do Martelo."}},faq={{q="Quem é Or'Kalar?",a="Or'Kalar é um ogro em Stromgarde que serve a Mug'thol e odeia o marido de Korin Fel por tê-lo derrotado há anos.",al={"or kalar","identidade de or'kalar"}},{q="Por que Korin Fel quer Or'Kalar morto?",a="Korin acredita que Or'Kalar armou uma cilada para o marido e quer que o ogro seja morto para protegê-lo e proteger a Ruína do Martelo.",al={"por que matar or'kalar","pedido de korin"}},{q="Onde posso encontrar Or'Kalar?",a="Or'Kalar fica perto da Torre de Arathor, no Planalto Arathi.",al={"localização de or'kalar","ogro da torre"}},{q="Quem recebe Or'Kalar's Head?",a="Korin Fel recebe Or'Kalar's Head no posto avançado da Ruína do Martelo.",al={"onde levar a cabeça","cabeça de korin fel"}}},fp="15,129,22.293.0,16.112.0,38.111.0,26.62.0,29.61.0"}
P.entries["item:oracle-crystal"] = {n="Cristal de Oráculo",s="O Cristal de Oráculo é um artefato naga usado por seus oráculos no litoral da Desolação. Maurin Rachaosso procura um ao voltar sua atenção para um senhor demoníaco.",h="O Cristal de Oráculo é um artefato naga usado por seus oráculos no litoral da Desolação.",kw={"azrethoc","desolação","maurin rachaosso","naga","oráculo","cristal de oráculo","slitherblade"},sec={{t="Artesanato naga",b="Maurin Rachaosso quer um Cristal de Oráculo dos naga Slitherblade, no litoral noroeste da Desolação. Os naga fazem esses cristais para seus oráculos, que vivem no vasto recife de coral em alto-mar. Maurin valoriza o cristal e pretende usá-lo enquanto procura o senhor demoníaco Azrethoc."}},faq={{q="O que é um Cristal de Oráculo?",a="Um Cristal de Oráculo é um objeto artesanal que os naga fazem para seus oráculos usarem.",al={"cristal de oráculo","o que é o cristal","cristal naga"}},{q="Quem quer o Cristal de Oráculo?",a="Maurin Rachaosso pede um Cristal de Oráculo enquanto persegue o senhor demoníaco Azrethoc.",al={"quem precisa do cristal","cristal de maurin","rachaosso quer"}},{q="Onde posso encontrar um Cristal de Oráculo?",a="Os oráculos Slitherblade vivem no mar, ao longo do litoral noroeste da Desolação.",al={"onde encontrar o cristal","localização do cristal de oráculo","encontrar o cristal naga"}},{q="Quem usa os Cristais de Oráculo?",a="Os naga fazem Cristais de Oráculo para seus oráculos usarem.",al={"quem usa o cristal","oráculos naga","finalidade do cristal"}}},fp="14,164,10.291.0,26.77.0,29.85.0,35.81.0,25.56.0"}
P.entries["item:ordanus-head"] = {n="Cabeça de Ornanos",s="Cabeça de Ornanos é o troféu macabro tomado do Guardião Ordanus no Refúgio Bosque Real, no Vale Gris. Reivindicada em nome da maga elfa sangrenta Braelyn Manígnea, serve como prova incontestável de que um dos filhos mais antigos de Cenarius caiu diante da vingança arcana.",h="Cabeça de Ornanos é o troféu macabro tomado do Guardião Ordanus no Refúgio Bosque Real, no Vale Gris.",kw={"vale gris","braelyn manígnea","cenarius","guardião do bosque","ordanus","cabeça de ornanos","refúgio bosque real","cordilheira das torres de pedra","sunrock retreat"},ang={["class:Druid"]="Para um druida, carregar a cabeça decepada de um dos filhos mais velhos de Cenarius serve como um lembrete contundente da amarga e sangrenta animosidade que os feiticeiros arcanos ainda nutrem pelos protetores da natureza.",["faction:Horde"]="Derrotar Ordanus e entregar sua cabeça a Braelyn ajuda a consolidar a posição da Horda nas fronteiras disputadas da Cordilheira das Torres de Pedra e do Vale Gris, enfraquecendo a liderança local dos elfos noturnos."},sec={{t="Um Rancor do Passado",b="O Guardião Ordanus era um antigo guardião do bosque, um dos descendentes mais velhos do deus da floresta Cenarius. Quando Braelyn Manígnea escalou as alturas da Cordilheira das Torres de Pedra a mando de sua mestra, ela buscava pôr fim à repressão dos druidas à magia no pico e se vingar de Ordanus. No entanto, o guardião foi levado às pressas para o coração do Vale Gris antes que ela pudesse atacar. Usando adivinhação arcana para espiar através da copa da floresta, Manígnea localizou seu santuário nos galhos do Refúgio Bosque Real e exigiu sua cabeça decepada como prova de que a arrogância do semideus selvagem finalmente havia sido respondida."},{t="O Preço da Húbris",b="Braelyn guarda um antigo ressentimento contra Ordanus, que conheceu há muito tempo, e odeia os druidas que tentam reprimir o fluxo de magia. Em vida, Ordanus se considerava superior até mesmo à antiga nobreza dos Altaneiros. Ao tomar sua cabeça, Manígnea ataca simbolicamente o legado de Cenarius, declarando que nenhum guardião da natureza pode conter o retorno do poder mágico bruto."}},faq={{q="Quem era o Guardião Ordanus?",a="O Guardião Ordanus era um antigo guardião do bosque e um dos filhos mais velhos de Cenarius. Há muito tempo, ele entrou em conflito com os praticantes arcanos da nobreza dos elfos noturnos e tinha fama de ser profundamente arrogante com aqueles que praticavam as artes arcanas.",al={"quem é ordanus","história de ordanus","o que é ordanus"}},{q="Onde esta cabeça é coletada?",a="A cabeça é tomada do Guardião Ordanus no alto da plataforma elevada de madeira no Refúgio Bosque Real, um enclave fortificado de elfos noturnos instalado na copa das árvores, no centro do Vale Gris.",al={"onde encontrar a cabeça de ordanus","localização de ordanus","refúgio bosque real ordanus"}},{q="Por que Braelyn Manígnea quer a cabeça dele?",a="Braelyn Manígnea conhecia Ordanus há muito tempo e desprezava sua arrogância, pois ele se considerava superior até mesmo aos Altaneiros. Ela também odeia os druidas e os filhos de Cenarius por tentarem deter o fluxo de magia e por terem levado Ordanus para longe do pico antes que ela pudesse alcançá-lo.",al={"por que braelyn quer a cabeça de ordanus","rancor de braelyn","por que matar ordanus"}},{q="O que acontece após a entrega da cabeça?",a="Entregar a Cabeça de Ornanos a Braelyn no Refúgio Sunrock satisfaz sua dívida de sangue, e ela recompensa o mercenário com o poderoso presente que prometeu.",al={"entrega da cabeça de ordanus","depois que ordanus morre","recompensa da missão de braelyn manígnea"}}},fx={e1459048={q="De onde vem a Cabeça de Ornanos?",a="Este troféu sombrio é retirado diretamente do Guardião Ornanos, um dos filhos mais velhos do semideus da floresta Cenarius. Embora outrora considerado seguro no topo do Morro das Torres de Pedra, Ornanos fugiu para Vale Gris e refugiou-se no alto do Refúgio Bosque Real antes de ser caçado.",al={"origem da cabeça de ornanos","de onde veio a cabeça de ornanos","a quem pertence a cabeça de ornanos"}}},fp="13,146,22.579.0,19.368.1,23.225.0,29.161.0,40.265.0,41.141.1"}
P.entries["item:orendil-s-cure"] = {n="Cura de Orendil",s="A Cura de Orendil é uma poção medicinal preparada pelo herborista Orendil Folharga no norte de Vale Gris. Criada a partir da rara erva Cabelo-de-bathran, ela se destina a tratar a doença misteriosa e mortal que aflige Relara Whitemoon em Astranaar.",h="A Cura de Orendil é uma poção medicinal preparada pelo herborista Orendil Folharga no norte de Vale Gris.",kw={"vale gris","astranaar","cabelo-de-bathran","orendil folharga","cura de orendil","pelturas lunalva","relara"},ang={["profession:Herbalism"]="O remédio evidencia o profundo poder medicinal da flora nativa de Vale Gris, em particular o Cabelo-de-bathran, que prospera apenas em recantos sombrios específicos da floresta.",["race:NightElf"]="Para os elfos noturnos de Astranaar, salvar Relara é um assunto comunitário urgente, unindo o conhecimento florestal de eremitas como Orendil à fé divina em Eluna."},sec={{t="A Esperança de um Pai",b="Quando a jovem Relara Whitemoon adoeceu gravemente em Astranaar, os remédios convencionais se mostraram ineficazes contra seu mal. Seu desesperado pai, Pelturas Lunalva, recorreu a Orendil Folharga, um eremita e mestre da medicina natural que vive nos confins do norte de Vale Gris. Utilizando feixes da rara planta Cabelo-de-bathran, colhidos nas ruínas assombradas do Refúgio de Bathran, Orendil preparou esta beberagem sob medida. A chegada do frasco traz esperança a Pelturas onde antes havia pouca, embora a cura apenas retarde a doença, forçando Pelturas a buscar outros remédios sugeridos por Orendil."}},faq={{q="Para que serve a Cura de Orendil?",a="A cura é formulada para aliviar e tratar Relara Whitemoon, uma jovem criança elfa noturna em Astranaar que foi acometida por uma enfermidade súbita e grave.",al={"propósito da cura de orendil","o que a cura faz","para quem é a cura"}},{q="Quem criou a cura?",a="Ela foi preparada por Orendil Folharga, um recluso herborista elfo noturno que vive nos bosques do norte de Vale Gris e é renomado pelo domínio sobre a flora e os remédios da floresta.",al={"quem fez a cura de orendil","criador da cura de orendil"}},{q="Quais ingredientes foram usados para fazê-la?",a="O ingrediente vital é o Cabelo-de-bathran, uma planta delicada e incomum colhida entre as ruínas do Refúgio de Bathran, no norte de Vale Gris.",al={"ingredientes da cura","o que tem na cura de orendil"}},{q="Esta poção cura a criança completamente?",a="Não completamente. Pelturas descobre mais tarde que a cura de Orendil apenas retardou a enfermidade que acomete sua filha, então ele busca um remédio mais forte que Orendil havia sugerido: a Lágrima de Eluna.",al={"curou relara","relara está curada"}}},fx={["8e86537e"]={q="O que é a Cura de Orendil?",a="A Cura de Orendil é uma mistura medicinal preparada pelo herbalista Orendil Folharga no norte de Vale Gris. Projetada como um tratamento especializado para uma doença súbita e grave, ela representa um esforço urgente para salvar a vida de uma jovem criança elfa noturna que sofre de uma aflição misteriosa.",al={"conhecimento sobre a cura de orendil","o que é a cura de orendil","remédio de orendil"}},["6add91d1"]={q="Por que a Cura de Orendil é necessária?",a="Em Astranaar, a jovem filha de Pelturas Lunalva, Relara, está mortalmente doente. Desesperado por um remédio quando os tratamentos padrão se mostraram ineficazes, seu pai buscou a experiência de Orendil Folharga. O herbalista preparou esta mistura específica na esperança de estabilizar a criança antes que a doença tire sua vida.",al={"por que precisar da cura de orendil","quem precisa da cura de orendil","por que entregar a cura de orendil"}}},fp="14,163,15.497.0,32.142.0,21.161.0,38.126.0,43.152.1"}
P.entries["item:orwin-s-shovel"] = {n="Orwin's Shovel",s="Orwin Sheiduztruc empresta sua pá na Aldeia Mojache para buscar cobalto Gordunni. O mineral de brilho azulado está enterrado no Assentamento Gordunni, onde os ogros o guardam de perto.",h="Orwin Sheiduztruc empresta sua pá na Aldeia Mojache para buscar cobalto Gordunni.",kw={"aldeia mojache","feralas","cobalto gordunni","assentamento gordunni","orwin sheiduztruc","pá de orwin","pá"},ang={["profession:Mining"]="Como minerador, você sabe o valor de um veio enterrado. A pá de Orwin aponta o caminho até o cobalto escondido entre os ogros Gordunni."},sec={{t="Uma ferramenta de prospector",b="Orwin Sheiduztruc acabou de chegar a Feralas, e o mineral enterrado pelos ogros Gordunni chamou sua atenção. Da Aldeia Mojache, ele envia você para o norte com sua pá, para coletar cobalto no assentamento deles. O brilho azul indica onde cavar. Orwin pretende levar as amostras adiante e encontrar um comprador."}},faq={{q="Quem é o dono de Orwin's Shovel?",a="Orwin Sheiduztruc empresta a pá dele a você na Aldeia Mojache, para que possa cavar em busca de cobalto Gordunni.",al={"pá de orwin","pá do orwin","quem tem a pá"}},{q="Para que serve Orwin's Shovel?",a="Orwin's Shovel serve para desenterrar cobalto Gordunni no Assentamento Gordunni, em Feralas.",al={"uso da pá","com o que cavar","pá de cobalto"}},{q="Onde uso Orwin's Shovel?",a="Você usa Orwin's Shovel no Assentamento Gordunni, ao norte da Aldeia Mojache, onde o cobalto está enterrado.",al={"onde fica a pá","pá do assentamento gordunni","onde cavar cobalto"}},{q="Por que Orwin quer cobalto Gordunni?",a="Orwin espera encontrar alguém que pague bem pelo cobalto enquanto continua suas viagens.",al={"por que cobalto","orwin quer cobalto","comprador de cobalto"}}},fp="14,175,19.298.0,24.89.0,27.84.0,30.97.0,36.89.0"}
P.entries["item:oslow-s-toolbox"] = {n="Caixa de Ferramentas do Oslow",s="A Caixa de Ferramentas do Oslow contém as ferramentas essenciais de construção necessárias para o Encarregado Oslow em Vila Plácida. A caminho de Vila d'Ouro, os mantimentos estavam sendo transportados pelo Lago Plácido até serem afundados por um bombardeio de catapulta órquica.",h="A Caixa de Ferramentas do Oslow contém as ferramentas essenciais de construção necessárias para o Encarregado...",kw={"encarregado oslow","lago plácido","vila plácida","oslow","montanhas cristarrubra","bau submerso","as ferramentas perdidas","caixa de ferramentas"},ang={["faction:Alliance"]="Com Vila Plácida quase isolada sob o cerco dos Blackrock, recuperar os mantimentos de Oslow é crucial para manter intactas as obras defensivas da cidade."},sec={{t="Uma Travessia Fadada ao Desastre",b="Manter as defesas e a infraestrutura de Vila Plácida é um desafio extenuante, especialmente com os orcs Blackrock sitiando as Montanhas Cristarrubra. O Encarregado Oslow encomendou um conjunto vital de ferramentas de construção trazido de Vila d'Ouro. Como a ponte principal que leva a Vila Plácida havia sido destruída por ação inimiga, a remessa precisou ser colocada em um barco a remo para atravessar o Lago Plácido. A travessia foi interrompida abruptamente quando as forças Blackrock atingiram a embarcação com um disparo de catapulta, afundando o barco e o baú pesado de Oslow diretamente nas profundezas infestadas de murlocs."}},faq={{q="Por que a Caixa de Ferramentas do Oslow está no fundo do lago?",a="A remessa de ferramentas estava sendo transportada de Vila d'Ouro. Como a ponte de Vila Plácida havia sido destruída durante o cerco, os mantimentos precisavam atravessar o Lago Plácido de barco. Os orcs Blackrock bombardearam o barco a remo com uma catapulta, afundando a embarcação e levando a caixa de ferramentas para o leito do lago.",al={"por que a caixa de ferramentas esta na agua","como oslow perdeu suas ferramentas","historia da caixa de ferramentas afundada"}},{q="A quem pertence esta caixa de ferramentas?",a="A caixa de ferramentas pertence ao Encarregado Oslow, o supervisor responsável pelas construções e reparos em Vila Plácida. Sem o equipamento adequado, manter as fortificações da cidade contra os ataques contínuos é praticamente impossível.",al={"quem e oslow","dono oslow","ferramentas do encarregado oslow"}},{q="Onde no Lago Plácido as ferramentas afundaram?",a="As ferramentas repousam dentro de um baú submerso perto dos destroços do barco a remo destruído no Lago Plácido, aninhadas entre pedregulhos subaquáticos ao sul de um acampamento murloc de destaque na margem.",al={"localizacao da caixa de ferramentas","onde fica o bau submerso","onde o barco afundou"}},{q="Quais ameaças guardam o baú submerso?",a="As águas que cercam os destroços estão infestadas de murlocs hostis e feras aquáticas predadoras, incluindo perigosos Lake Threshers que rondam as áreas mais profundas do lago.",al={"perigos perto da caixa de ferramentas","inimigos do lago placido","o que esta guardando as ferramentas de oslow"}}},fx={["543d5407"]={q="Por que o Encarregado Oslow precisa que sua caixa de ferramentas seja recuperada?",a="Vila Plácida está sob cerco pesado, deixando a cidade isolada e desesperadamente carente de suprimentos essenciais. Como encarregado da cidade, Oslow precisa de seu equipamento para manter e reparar as estruturas e defesas de Vila Plácida. Como a carroça de entrega de Vila d'Ouro não pôde atravessar a ponte destruída, perder as ferramentas de reposição no lago atrasou o trabalho de construção crítico, tornando sua recuperação vital para a sobrevivência da cidade.",al={"por que oslow quer caixa de ferramentas","por que oslow precisa de ferramentas","por que recuperar caixa de ferramentas de oslow"}}},fp="15,106,18.372.0,49.208.0,22.198.0,43.173.0,36.144.0"}
P.entries["item:osric-s-crate"] = {n="Caixote de Larso",s="O Caixote de Larso é um pacote pesado de armaduras recém-fabricadas enviado de Ventobravo para os defensores em apuros do Morro da Sentinela. Transportado a bordo de um grifo através da rede de voo do reino, ele fornece equipamentos vitais para ajudar a Milícia do Povo a manter Cerro Oeste contra bandos de foras da lei.",h="O Caixote de Larso é um pacote pesado de armaduras recém-fabricadas enviado de Ventobravo para os defensores...",kw={"dungar tragolongo","grifo","larso","caixote de larso","milícia do povo","intendente ludovico","morro da sentinela","cerro oeste"},ang={["faction:Alliance"]="Cada remessa de armas e armaduras que chega ao Morro da Sentinela ajuda a evitar que as fronteiras ocidentais do reino caiam completamente nas mãos da Irmandade Défias."},sec={{t="Suprimentos para a Frente de Batalha",b="Cerro Oeste sofre com as depredações da Irmandade Défias e de gnolls saqueadores, enquanto o exército de Ventobravo permanece ausente. Os defensores locais, organizados como a Milícia do Povo no Morro da Sentinela, carecem do apoio formal da coroa e precisam depender de suprimentos fragmentados. O Caixote de Larso contém um novo lote de armaduras de proteção enviado da capital para o Intendente Ludovico, com o objetivo de ser distribuído diretamente aos combatentes voluntários da milícia em campo."},{t="Rede de Mensageiros Alados",b="O transporte terrestre de equipamentos a partir de Ventobravo, através da Floresta de Elwynn e cruzando a fronteira de Cerro Oeste, é lento e repleto de emboscadas de bandidos. Para contornar as estradas, o caixote é confiado a um aventureiro que voa do Gryphon Roost de Dungar Tragolongo, no Distrito Comercial de Ventobravo, até Thor no Morro da Sentinela. Essa entrega rápida demonstra o papel crucial que os grifos desempenham em manter as guarnições de fronteira abastecidas em tempos de guerra."}},faq={{q="O que há dentro do Caixote de Larso?",a="O caixote contém armaduras de proteção fabricadas em Ventobravo. O Intendente Ludovico inspeciona sua entrega e se prepara imediatamente para distribuir as armaduras entre os combatentes que defendem o Morro da Sentinela.",al={"o que tem no caixote","conteúdo do caixote de larso","conteúdo caixote de larso"}},{q="Quem é Larso?",a="Larso é um armeiro baseado em Ventobravo que preparou este carregamento de equipamentos para a Milícia do Povo que mantém Cerro Oeste.",al={"quem é larso","quem enviou o caixote de larso"}},{q="Quem recebe o caixote?",a="A remessa é endereçada ao Intendente Ludovico, o oficial encarregado dos suprimentos e equipamentos da Milícia do Povo no Morro da Sentinela, em Cerro Oeste.",al={"para onde vai o caixote","a quem entregar o caixote de larso","destinatário do caixote"}},{q="Por que o caixote é entregue por grifo?",a="Bandidos e foras da lei tornam perigosas as estradas que ligam Ventobravo, a Floresta de Elwynn e Cerro Oeste. Voar de grifo de Dungar Tragolongo em Ventobravo diretamente até Thor no Morro da Sentinela garante que a armadura chegue com rapidez e segurança.",al={"por que levar o caixote voando","por que usar grifos","voo do caixote de larso"}}},fx={["34d354cb"]={q="O que é o Caixote de Larso?",a="O Caixote de Larso é um carregamento de armaduras enviado da Cidade de Ventobravo. Ele foi preparado para os defensores estacionados no Morro da Sentinela em Cerro Oeste, que estão desesperadamente carentes de equipamentos enquanto resistem contra a The Defias Brotherhood.",al={"o que é o caixote de larso","item caixote de larso","o que há no caixote de larso"}},["091b5cbb"]={q="De onde vem o Caixote de Larso e quem o fabricou?",a="O caixote vem da Cidade de Ventobravo, preparado e enviado por Larso para suprir a The People's Militia. O Mestre dos Grifos Dungar Longdrink confia a você a tarefa de levá-lo de grifo através do reino até Cerro Oeste.",al={"quem fez o caixote de larso","de onde veio o caixote de larso","origem do caixote de larso"}},["11fb3015"]={q="Por que alguém quer o Caixote de Larso?",a="O Intendente Ludovico e a The People's Militia no Morro da Sentinela precisam urgentemente da armadura que está dentro. Com Cerro Oeste abandonado pelas forças reais e dominado por bandidos, cada pedaço de equipamento de proteção é vital para manter os defensores vivos.",al={"por que entregar o caixote de larso","por que ludovico quer o caixote de larso","propósito do caixote de larso"}}},fp="13,181,22.237.0,22.301.0,29.174.0,13.101.0,23.128.0,38.199.0"}
P.entries["item:overdue-package"] = {n="Overdue Package",s="O Overdue Package é uma das mercadorias que Rugov A. Massoaço procura para seu trabalho em Geringontzan. O livro-caixa dele lista itens de vários lugares distantes.",h="O Overdue Package é uma das mercadorias que Rugov A.",kw={"destroços de beezil","caixa danificada","pântano vadeoso","geringontzan","livro-caixa de massoaço","rugov a. massoaço","overdue package"},sec={{t="Entre as mercadorias",b="Rugov A. Massoaço está reunindo mercadorias da Garganta Abrasadora e de outros lugares para seu trabalho em Geringontzan. O livro-caixa dele cita o Overdue Package, um eixo de perna de cristal e uma flameberge equilibrada. O pacote está em uma caixa danificada nos Destroços de Beezil, no Pântano Vadeoso."}},faq={{q="O que é o Overdue Package?",a="O Overdue Package é uma das mercadorias citadas no livro-caixa de Rugov A. Massoaço para seu trabalho em Geringontzan.",al={"overdue package","pacote para rugov","pacote de massoaço"}},{q="Onde está o pacote?",a="O Overdue Package está em uma caixa danificada nos Destroços de Beezil, no Pântano Vadeoso.",al={"onde está o pacote","local do pacote","encontrar overdue package"}},{q="Quem quer o pacote?",a="Rugov A. Massoaço, em Geringontzan, procura o Overdue Package e as outras mercadorias de seu livro-caixa.",al={"quem quer o pacote","pacote de rugov","pacote para quem"}},{q="Por que está atrasado?",a="O nome indica que está atrasado, mas não há explicação para a demora.",al={"por que está atrasado","pacote atrasado","o que está atrasado"}}},fp="15,166,15.262.0,28.102.0,21.80.0,22.98.0,18.67.0"}
P.entries["item:package-of-empty-ooze-containers"] = {n="Pacote de Recipientes Vazios de Gosma",s="Este pacote é um kit de potes de espécimes especializados e vazios, fornecido pelo pesquisador gnomo Laris Vagarroda em Altaforja. Destinado à perigosa amostragem de campo nas florestas assoladas de Selva Maleva, ele contém potes projetados para armazenar com segurança extratos de gosma mácula e amaldiçoada sem se dissolverem.",h="Este pacote é um kit de potes de espécimes especializados e vazios, fornecido pelo pesquisador gnomo Laris...",kw={"recipientes","amaldiçoada","selva maleva","altaforja","potes","laris vagarroda","gosma","pacote","limo","mácula"},ang={["faction:Alliance"]="Coletar essas amostras ajuda a Aliança a acompanhar o ritmo das pesquisas perturbadoras conduzidas pela Real Sociedade de Boticários dos Renegados.",["race:Gnome"]="Laris Vagarroda vê esta pesquisa com gosmas como uma oportunidade vital para mostrar aos anões de Altaforja que acolher os gnomos refugiados valeu muito a pena."},sec={{t="Equipamento de Pesquisa de Campo",b="Contendo uma dúzia de potes vazios — divididos entre recipientes destinados a gosmas amaldiçoadas e máculas —, este kit foi montado por Laris Vagarroda para viajantes intrépidos a caminho de Selva Maleva. Como os espécimes brutos de gosma são notoriamente cáusticos e propensos a corroer bagagens comuns, um vidro resistente e selado é essencial para transportar os resíduos ácidos através dos continentes de volta à bancada de trabalho do engenhoqueiro em Altaforja."},{t="O Mistério da Gosma",b="O interesse de Vagarroda por gosmas está longe de ser um mero passatempo excêntrico. Ao notar que pesquisadores Renegados da Real Sociedade de Boticários coletam rotineiramente esses organismos bizarros por toda Azeroth, ele suspeita que as gosmas possam guardar segredos profundos sobre a origem do mundo. Vagarroda teoriza que os limos podem ser secreções primordiais ligadas à própria criação do planeta, e depende de agentes de campo usando este kit para coletar as evidências necessárias para conquistar renome na Liga dos Exploradores."}},faq={{q="O que há dentro do pacote de recipientes vazios de gosma?",a="O pacote contém doze potes de espécimes: seis potes vazios calibrados para gosma amaldiçoada e seis destinados a gosma mácula.",al={"conteúdo do pacote","o que contém o pacote","potes de gosma dentro"}},{q="Quem fornece este pacote?",a="Ele é entregue aos aventureiros da Aliança por Laris Vagarroda, um estudioso e pesquisador gnômico que atua em Altaforja.",al={"quem entrega os potes","item de missão de laris vagarroda","onde conseguir o pacote de gosma"}},{q="Onde esses recipientes devem ser usados?",a="Eles devem ser usados nas terras ermas corrompidas de Selva Maleva, onde os aventureiros precisam derrotar gosmas máculas e amaldiçoadas para colher amostras de resíduos diretamente das criaturas derrotadas.",al={"onde usar os potes de gosma","qual zona para gosmas","localização dos potes de gosma"}},{q="Por que Laris Vagarroda quer essas amostras de gosma?",a="Laris notou que a Real Sociedade de Boticários dos Renegados anda coletando gosma pelo mundo e quer desvendar seus segredos. Ele também mantém a teoria heterodoxa de que os limos podem ser secreções primordiais ligadas à criação de Azeroth, e espera que provar isso lhe renda prestígio na Liga dos Exploradores.",al={"por que coletar limo","pesquisa de vagarroda","por que laris quer gosma"}}},fx={d8bf9111={q="O que é o Pacote de Recipientes Vazios de Gosma?",a="É um kit de campo montado pelo pesquisador gnomo Laris Vagarroda em Altaforja. O pacote contém um conjunto de frascos especialmente preparados, projetados para coletar e armazenar com segurança amostras colhidas das gosmas e lodos corrompidos encontrados por toda a Selva Maleva.",al={"o que é o pacote de recipientes vazios de gosma","pacote de recipientes de gosma","conjunto de recipientes vazios de gosma"}}},fp="32,181,24.324.0,23.402.0,52.91.0,26.110.0,44.137.0,50.260.0"}
P.entries["item:painted-gnoll-armband"] = {n="Braçadeiras Pintadas dos Gnolls",s="Braçadeiras Pintadas dos Gnolls são adornos rústicos usados pelos gnolls Riverpaw que rondam os arredores da Floresta de Elwynn. A Guarnição da Ribeira d'Oeste coleta essas braçadeiras marcadas como prova física de recompensas cumpridas contra os bandos invasores.",h="Braçadeiras Pintadas dos Gnolls são adornos rústicos usados pelos gnolls Riverpaw que rondam os arredores da...",kw={"recompensa","delegado ranieri","floresta de elwynn","gnolls","braçadeiras pintadas dos gnolls","riverpaw","lago do monumento","guarnição da ribeira d'oeste"},ang={["faction:Alliance"]="Coletar essas braçadeiras ajuda diretamente a Guarnição da Ribeira d'Oeste, fortalecendo a fronteira ocidental de Ventobravo enquanto o exército permanente da cidade é desviado para outro lugar."},sec={{t="Símbolos dos Riverpaw",b="O bando Riverpaw marca seus guerreiros e saqueadores com braçadeiras rústicas pintadas em padrões tribais grosseiros. As faixas pintadas são coletadas dos gnolls Riverpaw ao longo das fronteiras selvagens da Floresta de Elwynn. Para os defensores de Ventobravo, no entanto, elas representam uma ameaça territorial crescente que avança perto do Lago do Monumento e dos bosques ao sul da Guarnição da Ribeira d'Oeste."},{t="Recompensa para a Guarnição da Ribeira d'Oeste",b="Com o exército de Ventobravo sobrecarregado por todo o reino, a Guarnição da Ribeira d'Oeste luta para manter a fronteira ocidental segura contra ameaças invasoras. O Delegado Ranieri estabeleceu uma recompensa permanente pelos bandos invasores, orientando aventureiros a abater Riverpaw Outrunners e Riverpaw Runts. As braçadeiras pintadas servem como prova irrefutável do abate, permitindo que os delegados da guarnição contabilizem as recompensas e reduzam a população de gnolls que invade as fazendas vizinhas."}},faq={{q="Por que a Guarnição da Ribeira d'Oeste quer essas braçadeiras?",a="O Delegado Ranieri na Guarnição da Ribeira d'Oeste coleta as braçadeiras como prova de gnolls Riverpaw abatidos. Como as tropas da guarnição não conseguem conter os bandos invasores sozinhas, Ventobravo paga recompensas a qualquer aventureiro que trouxer de volta esses símbolos.",al={"por que braçadeiras","quem quer braçadeiras pintadas dos gnolls","recompensa delegado ranieri"}},{q="Quais gnolls usam essas braçadeiras pintadas?",a="Elas são carregadas pelos gnolls Riverpaw na Floresta de Elwynn, especificamente os Riverpaw Outrunners e Riverpaw Runts que infestam os bosques ao sul da Guarnição da Ribeira d'Oeste e as margens ao redor do Lago do Monumento.",al={"onde caem braçadeiras","quem derruba braçadeiras pintadas dos gnolls","quais gnolls têm braçadeiras"}},{q="Por que há gnolls Riverpaw na Floresta de Elwynn?",a="Os bandos Riverpaw avançaram para o leste pelas fronteiras da Floresta de Elwynn, estabelecendo acampamentos perto do Lago do Monumento e das margens da floresta. Eles se aproveitam da reduzida presença militar do reino para caçar, saquear e ameaçar assentamentos próximos.",al={"por que os gnolls estão aqui","invasão de gnolls elwynn","riverpaw elwynn"}},{q="Qual é o significado da pintura nas braçadeiras?",a="As braçadeiras identificam troféus obtidos dos gnolls Riverpaw e servem como prova para o Delegado Ranieri. A fonte não atribui postos ou significados específicos aos padrões pintados.",al={"por que são pintadas","marcas das braçadeiras de gnoll"}}},fx={["586b453e"]={q="O que são Braçadeiras Pintadas dos Gnolls?",a="As Braçadeiras Pintadas dos Gnolls são uma peça rudimentar de adorno pessoal usada pelos gnolls da Alcateia do Pata-do-Rio. Feitas e pintadas pelo bando, essas braçadeiras marcam sua presença nas terras fronteiriças da Floresta de Elwynn. Para o Exército de Ventobravo, elas servem como prova física inegável de que um gnoll saqueador foi morto.",al={"o que são braçadeiras pintadas dos gnolls","história das braçadeiras pintadas dos gnolls","braçadeiras de gnoll"}}},fp="21,142,22.279.0,29.306.0,48.226.0,41.166.0,41.226.0,54.140.0"}
P.entries["item:panther-cage-key"] = {n="Chave da Jaula da Pantera",s="A Chave da Jaula da Pantera é uma pequena chave de metal guardada por Vizlo Limpajunta no Posto Confinalvo. Ela destranca uma jaula reforçada que prende um predador enfurecido nos destroços de uma caravana emboscada em Mil Agulhas.",h="A Chave da Jaula da Pantera é uma pequena chave de metal guardada por Vizlo Limpajunta no Posto Confinalvo.",kw={"centauro","dispositivo hipercapacitador","chave da jaula da pantera","mil agulhas","posto confinalvo","vizlo limpajunta"},ang={["faction:Horde"]="Ajudar Wizlo colabora para proteger as estradas de Mil Agulhas ao redor do Posto Confinalvo do rastro volátil deixado pelos ataques dos centauros.",["profession:Engineering"]="A chave destranca a jaula que guarda o protótipo volátil de um engenhoqueiro, provando que inventores excêntricos guardam seus mecanismos mais delicados nos lugares mais perigosos que se possa imaginar."},sec={{t="Uma Fechadura Precária",b="Quando uma caravana itinerante foi atacada e saqueada por invasores centauros ao norte do Posto Confinalvo, o engenhoqueiro gnomo Vizlo Limpajunta mal escapou com vida. Em meio às ruínas das carroças e à carga pilhada, os saqueadores deixaram uma coisa totalmente intocada: uma jaula resistente que abrigava uma pantera feroz e rara. Ao redor do pescoço do predador estava pendurada a invenção premiada de Wizlo, um Dispositivo hipercapacitador. Sem disposição para se aproximar da fera rosnante, os centauros mantiveram distância da jaula, deixando a chave de Wizlo como a única maneira de abrir a porta e recuperar o dispositivo."}},faq={{q="Quem fornece a Chave da Jaula da Pantera?",a="A chave é entregue a aventureiros por Vizlo Limpajunta, um engenhoqueiro gnomo que descansa no Posto Confinalvo, no noroeste de Mil Agulhas.",al={"quem dá chave da pantera","onde conseguir chave da jaula da pantera","fonte da chave da jaula da pantera"}},{q="O que a chave destranca?",a="Ela destranca uma jaula de ferro encontrada entre as carroças quebradas de uma caravana destruída logo ao norte do Posto Confinalvo, a qual prende uma pantera enfurecida e perigosa.",al={"o que a chave da pantera abre","localização da jaula da pantera","onde fica a jaula"}},{q="Por que os centauros não saquearam a jaula?",a="Os centauros saquearam o restante da caravana, mas a pantera cativa lá dentro era tão feroz e ameaçadora que até os invasores se recusaram a mexer em sua jaula.",al={"por que centauros deixaram pantera","centauros com medo da pantera"}},{q="O que há dentro da jaula além da fera?",a="O precioso Dispositivo hipercapacitador de Wizlo está preso ao pescoço da pantera, forçando qualquer um que deseje recuperar a invenção a destrancar a jaula e confrontar o predador diretamente.",al={"por que abrir a jaula","o que está na pantera"}}},fx={b335554a={q="Por que Wizlo Bearingshiner quer a Chave da Jaula da Pantera de volta?",a="Wizlo Bearingshiner confia a você a chave apenas para que você possa abrir a jaula em sua caravana destruída e matar a fera feroz dentro dela. A besta usa seu precioso Dispositivo Hipercapacitador ao redor do pescoço. Ele quer que a chave seja devolvida junto com sua invenção assim que o serviço estiver feito, garantindo que os restos da caravana e sua propriedade perigosa sejam totalmente contabilizados.",al={"por que chave da jaula da pantera","por que wizlo precisa da chave","por que querer chave da jaula da pantera"}}},fp="16,160,17.423.0,34.115.0,25.142.0,37.137.0,42.139.0"}
P.entries["item:parker-s-lunch"] = {n="Almoço do Florestan",s="Almoço do Florestan é uma refeição fresca preparada e embalada por Darcy em Vila Plácida. Destinada ao Guarda Florestan em patrulha, ela oferece um vislumbre singelo dos laços cotidianos e dos confortos modestos dos defensores de Cristarrubra.",h="Almoço do Florestan é uma refeição fresca preparada e embalada por Darcy em Vila Plácida.",kw={"almoço grátis","darcy","guarda florestan","vila plácida","almoço do florestan","montanhas cristarrubra"},ang={["faction:Alliance"]="Com a capital demorando a enviar reforços, a solidariedade local entre os habitantes da cidade e os poucos guardas restantes é o que mantém Vila Plácida de pé.",["profession:Cooking"]="Uma refeição quente e bem embalada costuma ser o único conforto que sustenta os guardas da fronteira durante longas horas e contra feras hostis na natureza selvagem."},sec={{t="Uma Refeição para o Caminho",b="Enquanto as Montanhas Cristarrubra sofrem sob ataques de gnolls e orcs Blackrock, os pequenos gestos da vida diária persistem. Darcy, uma garçonete da estalagem em Vila Plácida, prepara esta refeição saudável para o Guarda Florestan, que patrulha a estrada exposta que segue para o sul em direção à Floresta do Crepúsculo. A guarnição de Cristarrubra está sobrecarregada e isolada do auxílio de Ventobravo, deixando os guardas por conta própria em vigílias longas e solitárias. Entregar este embrulho não apenas mantém um sentinela alimentado, mas também dá início a um romance duradouro e tímido entre os dois moradores."}},faq={{q="Quem preparou o Almoço do Florestan?",a="O almoço foi preparado por Darcy, garçonete da estalagem de Vila Plácida. Preocupada com o Guarda Florestan enquanto ele cumpre uma patrulha perigosa, ela conta com aventureiros viajantes para entregá-lo em segurança a ele.",al={"quem fez o almoço do florestan","quem me deu o almoço do florestan","almoço darcy cristarrubra"}},{q="Onde o Guarda Florestan pode ser encontrado?",a="O Guarda Florestan patrulha a estrada de terra principal que sai de Vila Plácida a sudoeste em direção à fronteira da Floresta do Crepúsculo. Ele marcha de um lado para o outro ao longo dessa rota, atento a gnolls errantes.",al={"localização do guarda florestan","onde fica o guarda florestan","encontrar o guarda florestan"}},{q="O que o Guarda Florestan faz após receber seu almoço?",a="Florestan fica profundamente comovido com a gentileza de Darcy. Grato pela comida quente durante sua patrulha difícil, ele logo procura uma forma de retribuir o carinho, pedindo ajuda para enviar a ela narcisos frescos do herbalista.",al={"continuação almoço do florestan","darcy e florestan","reação do florestan ao almoço"}},{q="Por que a Darcy não entrega o almoço pessoalmente?",a="As estradas fora de Vila Plácida estão repletas de gnolls agressivos de Cristarrubra e invasores Blackrock. Embora o Guarda Florestan tenha o treinamento de combate e a armadura necessários para sobreviver em patrulha, moradores comuns como Darcy não podem se arriscar na viagem sozinhos com segurança.",al={"por que darcy nao leva o almoço","por que entregar o almoço em cristarrubra"}}},fx={["2351e721"]={q="O que é o Almoço do Florestan?",a="O Almoço do Florestan é uma refeição embalada preparada por Darcy, assistente de um estalajadeiro em Vila Plácida. Ela a preparou especificamente para sustentar o Guarda Florestan, que passa longas e exaustivas horas patrulhando as estradas traiçoeiras ao sul da cidade em direção à Floresta do Crepúsculo.",al={"o que é o almoço do florestan","item almoço do florestan"}},b73a829b={q="Por que o Guarda Florestan precisa que seu almoço seja entregue?",a="O Guarda Florestan está estacionado muito longe da relativa segurança de Vila Plácida, vigiando contra gnolls errantes e orcs Rocha Negra ao longo da estrada da fronteira. Incapaz de abandonar seu posto para retornar à estalagem, ele depende da bondade dos habitantes locais como Darcy — e viajantes de passagem — para se manter alimentado em serviço.",al={"por que entregar almoço do florestan","por que o guarda florestan quer almoço","por que guarda florestan precisa de almoço"}}},fp="14,154,19.382.0,28.143.0,32.148.0,52.147.1,44.158.0"}
P.entries["item:partially-filled-vessel"] = {n="Recipiente Parcialmente Cheio",s="O Recipiente Parcialmente Cheio é um recipiente encantado usado para transportar água abençoada de poço lunar por Teldrassil. Entregue a jovens iniciados elfos noturnos por Tenaron Fortagarras em Aldrassil, ele transporta a água retirada de Umbravale em direção ao povoado de Dolanaar.",h="O Recipiente Parcialmente Cheio é um recipiente encantado usado para transportar água abençoada de poço lunar...",kw={"aldrassil","corithras lunafúria","coroa da terra","dolanaar","poço lunar","recipiente parcialmente cheio","umbravale","tenaron fortagarras","recipiente"},ang={["class:Druid"]="Transportar as águas santificadas é um dever essencial a serviço do esforço contínuo do Círculo Cenariano para nutrir e inspecionar a saúde da Árvore do Mundo.",["race:NightElf"]="Carregar este recipiente representa um rito de passagem, levando jovens elfos noturnos para longe do santuário de Umbravale e em direção às responsabilidades mais amplas de cuidar de Teldrassil."},sec={{t="Uma Entrega Sagrada",b="Entre os galhos de Aldrassil, iniciados dos kaldorei coletam águas abençoadas do poço lunar isolado de Umbravale. Tenaron Fortagarras despeja essa amostra pura neste recipiente especial, preparando-o para a viagem pela Árvore do Mundo. O recipiente permanece apenas parcialmente cheio porque sua jornada está apenas começando; mais águas sagradas de toda a Teldrassil devem eventualmente ser reunidas para cuidar da saúde da ilha."},{t="Rumo a Dolanaar",b="Transportar o recipiente requer viajar para o sul pelos portões do vale e seguir as estradas de paralelepípedos para o oeste até Dolanaar. A jornada marca a partida de um jovem aventureiro do berçário protegido de Umbravale em direção às terras selvagens mais amplas de Teldrassil. No poço lunar central de Dolanaar, Corithras Lunafúria assume a custódia do recipiente para orientar a próxima fase do ritual."}},faq={{q="O que há dentro do recipiente?",a="Ele contém água pura de poço lunar coletada do lago sagrado em Umbravale, despejada no recipiente pelo druida Tenaron Fortagarras.",al={"o que está no recipiente","conteúdo do recipiente","qual água está nele"}},{q="Por que ele está apenas parcialmente cheio?",a="O poço lunar de Umbravale fornece apenas a primeira amostra. Os esforços contínuos para cuidar de Teldrassil exigem a coleta de água de vários poços lunares pela árvore antes que o recipiente fique cheio.",al={"por que parcialmente cheio","por que não está cheio"}},{q="Para quem devo levar este recipiente?",a="Leve o recipiente para o sul, saindo de Umbravale, e siga a estrada de paralelepípedos a oeste até Dolanaar. Lá, entregue-o a Corithras Lunafúria, que cuida do poço lunar da cidade.",al={"quem recebe o recipiente","onde devo levar","entrega do recipiente"}},{q="Por que a água do poço lunar está sendo transportada por Teldrassil?",a="Os druidas e as sacerdotisas monitoram e nutrem Teldrassil por meio das águas de seus poços lunares. Transportar água entre os poços ajuda a manter suas bênçãos pelos galhos conturbados da recém-crescida Árvore do Mundo.",al={"por que transportar água do poço lunar","propósito da água","por que mover água"}}},fx={["5f4a3df1"]={q="O que é o Recipiente Parcialmente Cheio?",a="O Recipiente Parcialmente Cheio é um recipiente encantado usado por druidas elfos noturnos para coletar e transportar as águas sagradas dos poços da lua de Teldrassil. Quando Tenaron Fortagarras envia você de Umbravale, ele combina seu frasco coletado de água benta do poço da lua neste recipiente para que o trabalho sagrado possa continuar pelos ramos da Árvore do Mundo.",al={"conhecimento sobre o recipiente parcialmente cheio","o que é este recipiente","o que é o recipiente parcialmente cheio"}},["4f920d4c"]={q="De onde veio o Recipiente Parcialmente Cheio e quem o fez?",a="Tenaron Fortagarras, um dos druidas anciãos estacionados no topo de Aldrassil em Umbravale, fornece este recipiente a você. Depois que você retira água do poço da lua de Umbravale, Tenaron despeja seu frasco no recipiente para iniciar a coleta, confiando a você a tarefa de levá-lo adiante para as partes mais amplas de Teldrassil.",al={"quem fez o recipiente","de onde veio o recipiente","origem do recipiente"}},["089d2d88"]={q="Por que Corithras Lunafúria quer o Recipiente Parcialmente Cheio?",a="Corithras Lunafúria aguarda o recipiente no poço da lua em Dolanaar para continuar uma tarefa druídica vital conhecida como Crown of the Earth. Reunir as águas de Teldrassil é essencial para inspecionar e cuidar da jovem Árvore do Mundo, e Corithras precisa da água que você trouxe de Aldrassil antes que ele possa orientá-lo em direção às próximas etapas do ritual.",al={"por que corithras quer isso","por que levar o recipiente para dolanaar","por que levar recipiente para corithras"}}},fp="23,159,17.262.0,18.309.0,26.93.0,32.142.0,29.159.0,52.198.0"}
P.entries["item:paw-of-sin-dall"] = {n="Paw of Sin'Dall",s="Merília Ceireles pede que você rastreie Sin'Dall, uma tigresa esquiva da Selva do Espinhaço, e traga uma prova da caçada.",h="Merília Ceireles pede que você rastreie Sin'Dall, uma tigresa esquiva da Selva do Espinhaço, e traga uma...",kw={"merília ceireles","expedição do rosarães","paw of sin'dall","sin'dall","selva do espinhaço","tigre","tiger mastery"},ang={["class:Hunter"]="Como Caçador, você recebe o desafio de Merília Ceireles: rastrear e matar Sin'Dall, depois trazer uma prova da caçada."},sec={{t="Prova da Caçada",b="Na Expedição do Rosarães, Merília Ceireles manda você atrás de Sin'Dall, uma tigresa esquiva que é rastreada há semanas. Ela pede que você volte com a pata dela como prova da caçada. Traga-a de volta, e ela o reconhecerá como um verdadeiro Mestre Caçador de Tigres."}},faq={{q="Quem é Sin'Dall?",a="Sin'Dall é uma tigresa esquiva da Selva do Espinhaço, caçada por Merília Ceireles e pelos rastreadores da Expedição do Rosarães.",al={"tigre sin'dall","quem é sin'dall"}},{q="Por que Merília quer a pata de Sin'Dall?",a="Merília Ceireles pede que você traga a pata de Sin'Dall como prova de que a caçou e matou.",al={"prova da pata","por que a pata"}},{q="Onde levo Paw of Sin'Dall?",a="Leve Paw of Sin'Dall para Merília Ceireles, na Expedição do Rosarães.",al={"onde levar a pata","pata merília ceireles"}},{q="O que a pata comprova?",a="A pata comprova para Merília Ceireles que você concluiu a caçada a Sin'Dall.",al={"significado da pata","prova de sin'dall"}}},fp="15,114,17.225.0,16.119.0,35.86.1,36.69.0,24.72.1"}
P.entries["item:pendant-of-shadow"] = {n="Pingente das Sombras",s="O Pingente das Sombras é um talismã sombrio usado pelo bruxo renegado Morganth no topo da Torre de Ilgalar, nas Montanhas Cristarrubra. Levado ao mago Teócrito na Torre de Azora, ele serve como prova irrefutável de que o conjurador rebelde foi eliminado antes que suas ambições sinistras dessem frutos.",h="O Pingente das Sombras é um talismã sombrio usado pelo bruxo renegado Morganth no topo da Torre de Ilgalar...",kw={"morganth","pingente das sombras","montanhas cristarrubra","a foice de eluna","teócrito","torre de azora","torre de ilgalar"},ang={["class:Mage"]="Recuperar o talismã sombrio a mando de Teócrito destaca a responsabilidade contínua que os magos têm de policiar conjuradores rebeldes e imprudentes que ameaçam o reino.",["class:Warlock"]="Morganth representa o perigo de atrair atenção demais da Torre de Azora ao buscar artefatos proibidos e voláteis como A foice de Eluna."},sec={{t="Emblema de um Bruxo Sombrio",b="Guardado pelo bruxo rebelde Morganth em seu refúgio na Torre de Ilgalar, o Pingente das Sombras está impregnado de feitiçaria sombria. Morganth buscava desvendar os mistérios d'A foice de Eluna, uma relíquia antiga de poder imenso e volátil. Temendo a devastação que o bruxo poderia causar nas Montanhas Cristarrubra e no reino de Ventobravo, o mago Teócrito encarregou aventureiros de se infiltrarem em Ilgalar, porem um fim aos planos de Morganth e arrancarem o talismã de suas mãos como prova de sua morte."}},faq={{q="Onde encontro o Pingente das Sombras?",a="O pingente está em posse do bruxo Morganth, que reside no topo da Torre de Ilgalar, no nordeste das Montanhas Cristarrubra.",al={"localização do pingente das sombras","onde fica o pingente das sombras","como obter o pingente das sombras"}},{q="Quem quer o Pingente das Sombras?",a="O talismã deve ser levado ao mago Teócrito, que reside na Torre de Azora, localizada no leste da Floresta de Elwynn.",al={"quem aceita o pingente das sombras","entregar o pingente das sombras","pingente de teócrito"}},{q="Por que Teócrito precisa deste pingente?",a="Teócrito precisa do pingente como prova tangível de que Morganth foi derrotado e de que sua busca pela perigosa Foice de Eluna chegou ao fim.",al={"por que teócrito quer isso","propósito do pingente das sombras"}},{q="Que ameaça Morganth representava com o pingente?",a="Morganth estava caçando a esquiva Foice de Eluna. Teócrito temia que, se o bruxo sombrio conseguisse obter o artefato, ele desencadearia um poder catastrófico por Cristarrubra e pelo reino ao redor.",al={"o que morganth estava fazendo","história de morganth"}}},fx={d0e37f9a={q="O que é o Pingente das Sombras?",a="O Pingente das Sombras é um talismã sombrio usado pelo bruxo ladino Morganth no topo da Torre de Ilgalar nas Montanhas Cristarrubra. Ligado diretamente às ambições sinistras e artes das trevas de Morganth, o pingente serve como prova de sua derrota para o mago Teócrito, que teme o caos que Morganth poderia desencadear sobre Ventobravo se não fosse contido.",al={"o que é o pingente das sombras","história do pingente das sombras","informações do pingente das sombras"}}},fp="17,180,23.403.1,38.99.0,32.92.0,38.121.1,47.171.1"}
P.entries["item:pendant-of-the-sea-lion"] = {n="Pingente do Leão Marinho",s="O Pingente do Leão Marinho é um talismã druídico sagrado que representa a união da agilidade e da resistência aquáticas. Montado no Santuário de Remulos na Clareira da Lua, ele serve como prova de que um iniciado está pronto para dominar sua Forma aquática.",h="O Pingente do Leão Marinho é um talismã druídico sagrado que representa a união da agilidade e da resistência...",kw={"forma aquática","dendrite stellardor","mathrengyl ursivagus","clareira da lua","pingente do leão marinho","remulos","turak runa totem"},ang={["class:Druid"]="Montar este talismã marca um marco crucial no treinamento de um druida, desbloqueando a habilidade de respirar debaixo d'água e nadar com extrema rapidez como um leão-marinho.",["race:Tauren"]="Para os Shu'halo que trilham o caminho do Círculo Cenariano, levar o pingente de volta a Turak Runa Totem honra tanto os ancestrais quanto os ensinamentos da Clareira da Lua."},sec={{t="Um Símbolo das Profundezas",b="Para reivindicar o aspecto aquático do leão-marinho, o druida deve provar seu domínio sobre os maiores perigos da água. O pingente é criado recuperando duas metades distintas: uma que personifica a agilidade necessária para passar por predadores aquáticos, e a outra que concede a resistência necessária para suportar a submersão prolongada. Levadas ao Santuário de Remulos na Clareira da Lua, as duas partes se unem em um todo."},{t="Prova de Maestria",b="Uma vez forjado, o pingente completo é levado aos mentores anciãos — como Turak Runa Totem nos altos platôs do Penhasco do Trovão ou Mathrengyl Ursivagus em Darnassus. O talismã oferece uma prova irrefutável dos testes do iniciado sob a tutela de Dendrite Stellardor, permitindo que os anciãos concedam os segredos de assumir a Forma aquática."}},faq={{q="Qual é o propósito do Pingente do Leão Marinho?",a="Ele serve como prova de que um iniciado druida concluiu as provações de agilidade e resistência aquáticas, demonstrando prontidão para aprender sua Forma aquática.",al={"o que faz o pingente do leao marinho","uso do pingente do leao marinho","por que obter o pingente do leao marinho"}},{q="Onde o pingente é montado?",a="As duas metades — representando agilidade e resistência — devem ser unidas no Santuário de Remulos, situado no refúgio sagrado da Clareira da Lua.",al={"como fazer pingente do leao marinho","onde juntar metades do pingente"}},{q="A quem apresento o pingente no Penhasco do Trovão?",a="Druidas taurens apresentam o pingente concluído a Turak Runa Totem no Platô dos Anciãos no Penhasco do Trovão para concluir seu treinamento.",al={"quem recebe o pingente penhasco do trovao","turak runa totem pingente","entrega forma aquatica horda"}},{q="Elfos Noturnos também podem obter este pingente?",a="Sim. Druidas Elfos Noturnos passam pela mesma provação na Clareira da Lua, levando seu pingente montado a Mathrengyl Ursivagus em Darnassus.",al={"pingente do leao marinho alianca","pingente do leao marinho darnassus"}}},fx={["203d1c94"]={q="O que é o Pingente do Leão Marinho?",a="O Pingente do Leão Marinho é um talismã druídico sagrado que simboliza o domínio sobre a água. Ele incorpora a agilidade necessária para escapar de predadores aquáticos perigosos, juntamente com a profunda resistência necessária para permanecer submerso sem precisar emergir. Os druidas carregam esta relíquia unida como prova tangível de que entendem o equilíbrio selvagem da natureza antes de adotar um aspecto aquático.",al={"o que é o pingente do leão marinho","informações do pingente do leão marinho","história do pingente do leão marinho"}},ad633d46={q="De onde vem o Pingente do Leão Marinho e quem o fez?",a="O talismã é forjado por jovens druidas durante o Teste do Leão Marinho. Ele é criado recuperando duas peças separadas — o Meio-pingente da Agilidade Aquática e o Meio-pingente da Resistência Aquática — de locais de teste e unindo-as diante do Santuário de Remulos, na Clareira da Lua, combinando os aspectos em um único emblema sagrado.",al={"quem fez o pingente do leão marinho","origem do pingente do leão marinho","como é criado o pingente do leão marinho"}},["384283bf"]={q="Por que alguém quer o Pingente do Leão Marinho?",a="Mentores druidas exigem ver o pingente completo como prova inegável do seu treinamento. No Penhasco do Trovão, Turak Runa Totem exige o medalhão para verificar se você completou os testes da Clareira da Lua antes de transmitir os segredos da Aquatic Form. Dendrite Stellardor, na Clareira da Lua, também inspeciona a relíquia unida para confirmar a conclusão do teste.",al={"por que querer o pingente do leão marinho","quem quer o pingente do leão marinho","por que mostrar o pingente do leão marinho"}}},fp="23,154,19.299.0,16.307.0,51.119.0,31.128.0,49.89.0,39.130.0"}
P.entries["item:perenolde-tiara"] = {n="Tiara de Perenolde",s="A Tiara de Perenolde é uma relíquia de família cravada de esmeraldas da decaída casa real de Alterac, criada originalmente por artífices anões de Altaforja. Perdida em meio à destruição do reino, ela acabou caindo nas mãos gananciosas de um ogro que vagava pelas ruínas, antes de atrair o interesse de colecionadores em Ventobravo.",h="A Tiara de Perenolde é uma relíquia de família cravada de esmeraldas da decaída casa real de Alterac, criada...",kw={"alterac","esmeraldas","grel'borg","altaforja","avarento","perenolde","remington","espargosa","tiara"},ang={["faction:Alliance"]="O artefato é uma lembrança amarga da Casa de Perenolde, cuja traição durante a Segunda Guerra quase destruiu a Aliança de Lordaeron original.",["race:Dwarf"]="A tiara serve como testemunho da renomada lapidação de Altaforja, cujos mestres joalheiros lapidaram e cravaram as esmeraldas para a realeza humana do norte."},sec={{t="Uma Relíquia de um Reino em Ruínas",b="Antes de o reino montanhoso de Alterac ruir em infâmia e escombros durante a Segunda Guerra, sua casa governante era a família Perenolde. Entre seus tesouros estava esta delicada tiara, encomendada a mestres joalheiros de Altaforja e incrustada de esmeraldas brilhantes. Quando Alterac caiu em ruína após a traição do Rei Aiden Perenolde, a joia da coroa desapareceu na devastação caótica dos penhascos elevados."},{t="O Prêmio do Avarento",b="Em vez de permanecer sepultada para sempre sob a neve, a tiara foi desenterrada por Grel'borg, o Avarento, um ogro mago que vasculha as ruínas de Alterac em busca de riquezas abandonadas. As notícias da relíquia sobrevivente chegaram ao Conde Capistrano de Espargosa, um nobre abastado de Ventobravo ansioso por adquirir relíquias famosas para o museu de sua família, desencadeando uma busca para arrancar a tiara das mãos ávidas do ogro."}},faq={{q="O que é a Tiara de Perenolde?",a="É uma relíquia de família que outrora pertenceu à família real Perenolde de Alterac. Foi fabricada por mestres joalheiros anões de Altaforja e adornada com finas esmeraldas antes de se perder durante a queda de Alterac.",al={"história da tiara de perenolde","o que é esta tiara","tiara de alterac"}},{q="Quem possui a tiara agora?",a="Um ogro mago conhecido como Grel'borg, o Avarento, descobriu a tiara em meio às ruínas cobertas de neve de Alterac. Ele a protege zelosamente enquanto vasculha o reino arruinado em busca de mais tesouros perdidos.",al={"onde está a tiara","quem saqueia a tiara","tiara de grelborg"}},{q="Por que o Conde Capistrano de Espargosa a quer?",a="O Conde Capistrano de Espargosa coleciona antiguidades históricas e de grande prestígio para o museu de sua família em Ventobravo. Recuperar uma joia da coroa genuína de um reino humano decaído oferece uma peça central impressionante para a sua coleção.",al={"quem quer a tiara","por que remington quer a tiara","motivo de capistrano de espargosa"}},{q="Quem eram os Perenolde?",a="Os Perenolde eram a dinastia governante do reino de Alterac. Durante a Segunda Guerra, o Rei Aiden Perenolde traiu a Aliança a favor da Horda Órquica, levando ao colapso e à ruína do seu reino soberano.",al={"família perenolde","casa de perenolde","governantes de alterac"}}},fx={da959daa={q="De onde vem a Tiara de Perenolde e quem a fez?",a="A tiara vem do reino arruinado de Alterac, ao norte, onde serviu como uma valiosa herança de família da casa real de Perenolde. Em vez de ter sido forjada por artesãos humanos, dizem que foi criada por mestres joalheiros anões em Altaforja, que adornaram a peça ornamentada com as melhores esmeraldas.",al={"quem fez a tiara de perenolde","origem da tiara de perenolde","onde a tiara foi fabricada"}}},fp="15,167,27.319.0,17.295.0,28.187.0,28.152.0,43.172.0,24.161.0"}
P.entries["item:pestlezugg-s-un-goro-report"] = {n="Pestlezugg's Un'Goro Report",s="O relatório de Un'Goro de Pestlezugg leva suas descobertas mais recentes de Geringontzan aos líderes de Darnassus ou Orgrimmar. Ele espera que deem ouvidos à ameaça dos silitídeos e ajudem a enfrentá-la.",h="O relatório de Un'Goro de Pestlezugg leva suas descobertas mais recentes de Geringontzan aos líderes de...",kw={"calm before the storm","darnassus","geringontzan","gracinha forçânima","orgrimmar","pestlezugg","silitídeo","relatório de un'goro","zilzibin tamborleiro"},ang={["faction:Alliance"]="Como viajante da Aliança, você leva o alerta de Pestlezugg a Gracinha Forçânima, em Darnassus, onde ela espera que seus líderes levem a ameaça dos silitídeos a sério.",["faction:Horde"]="Como viajante da Horda, você leva o alerta de Pestlezugg a Zilzibin Tamborleiro, em Orgrimmar, na esperança de que Thrall ouça os fatos."},sec={{t="Um relatório de Geringontzan",b="Em Geringontzan, Pestlezugg envia suas descobertas mais recentes sobre os silitídeos a alguém que possa chegar até os líderes. O relatório segue para Gracinha Forçânima, no Templo da Lua, em Darnassus, ou para Zilzibin Tamborleiro, em Orgrimmar. Pestlezugg acredita que o perigo é grande demais para Geringontzan enfrentar sozinha."},{t="Dar ouvidos ao alerta",b="Pestlezugg teme que o ódio entre a Aliança e a Horda cegue os dois lados para a ameaça dos silitídeos. Gracinha diz que a Aliança descarta perigos que não vêm da Horda, enquanto os líderes da Horda estão divididos por conselhos conflitantes. Os dois destinatários defendem que os esforços contra os silitídeos continuem."}},faq={{q="Quem escreveu o relatório?",a="Pestlezugg, que trabalha em Geringontzan, escreveu o relatório sobre suas descobertas mais recentes a respeito dos silitídeos.",al={"quem é pestlezugg","relatório de pestlezugg","autor do relatório"}},{q="O que há no relatório de Pestlezugg?",a="O relatório traz as descobertas mais recentes de Pestlezugg sobre a ameaça dos silitídeos.",al={"o que diz o relatório","relatório sobre silitídeos","conteúdo do relatório"}},{q="Para onde o relatório é enviado?",a="O relatório é levado a Gracinha Forçânima, no Templo da Lua, em Darnassus, ou a Zilzibin Tamborleiro, em Orgrimmar.",al={"onde levar o relatório","destino do relatório","para onde vai o relatório"}},{q="Por que Pestlezugg o envia?",a="Pestlezugg acredita que Geringontzan não pode enfrentar sozinha a ameaça dos silitídeos e espera que os líderes ajam com base em suas descobertas.",al={"por que enviar o relatório","por que pestlezugg precisa de ajuda","geringontzan precisa de ajuda"}},{q="O que Gracinha pensa do alerta?",a="Gracinha diz que a Aliança ignora ameaças que não vêm da Horda e defende que os esforços contra os silitídeos continuem.",al={"gracinha sobre silitídeos","resposta da aliança","por que a aliança ignora a ameaça"}},{q="Como a Horda reage?",a="Zilzibin diz que a Horda está distraída por conselhos conflitantes, embora acredite que Thrall talvez aja se os fatos chegarem até ele.",al={"resposta da horda","thrall e os silitídeos","relatório de zilzibin"}}},fp="27,174,23.300.0,19.299.1,21.95.0,31.71.0,25.122.0,28.110.0,39.129.0,27.122.0"}
P.entries["item:phial-of-scrying"] = {n="Frasco de Vidência",s="O Frasco de Vidência é um recipiente encantado fornecido pelo ancestral da tradição Onu em Costa Negra. Quando usado, ele manifesta uma bacia de vidência que permite comunhão distante através dos bosques corrompidos.",h="O Frasco de Vidência é um recipiente encantado fornecido pelo ancestral da tradição Onu em Costa Negra.",kw={"costa negra","glaive do mestre","onu","frasco de vidência","bacia de vidência","twilight's hammer"},ang={["class:Druid"]="Druidas reconhecem as bacias de vidência como uma combinação harmoniosa de água natural e magia de comunhão, permitindo que os guardiões da floresta troquem sussurros através do solo corrompido.",["race:NightElf"]="Para os elfos noturnos de Costa Negra, ferramentas antigas de adivinhação como águas de vidência são vitais para manter a vigilância sobre os bosques sagrados invadidos por cultos alienígenas."},sec={{t="Uma Lente Através de Costa Negra",b="Confiado a batedores que investigam as profundezas de Costa Negra, o Frasco de Vidência contém águas místicas que conjuram uma bacia de vidência temporária sobre a terra. Esta ferramenta possibilita adivinhação a longa distância, permitindo que viajantes que se aventuram em regiões perigosas como a Glaive do Mestre entrem em comunhão diretamente com Onu sem precisar retornar imediatamente ao seu bosque."},{t="Descobrindo o Culto",b="Onu fornece o frasco especificamente para monitorar a presença perturbadora dos cultistas do Martelo do Crepúsculo. Ao estabelecer um elo de vidência no local do antigo mestre caído empalado por uma glaive enorme, o batedor confirma que cultistas sombrios estão se reunindo ativamente ao redor dos restos ancestrais, em busca de fragmentos de poder esquecido que perduram mesmo na morte."}},faq={{q="O que o Frasco de Vidência faz?",a="Quando destampado, o frasco manifesta uma bacia de vidência mágica no chão, permitindo que um aventureiro em campo contate e fale com o ancestral da tradição Onu através de vastas distâncias.",al={"usar frasco de vidência","função da bacia de vidência","para que serve este frasco"}},{q="Quem fornece o Frasco de Vidência?",a="O antigo arvoreso Onu confia o frasco a batedores em Costa Negra ao incumbi-los de fazer o reconhecimento da Glaive do Mestre ao sul.",al={"quem dá frasco de vidência","onde consigo o frasco"}},{q="O que acontece se o frasco for perdido ou esgotado?",a="Se o frasco for perdido ou usado antes de concluir sua missão, Onu pode fornecer outro enquanto estiver meditando em Costa Negra.",al={"frasco de vidência perdido","conseguir outro frasco","substituir frasco"}},{q="Por que Onu está fazendo vidência na Glaive do Mestre?",a="Onu sabe que a Glaive do Mestre é onde um antigo senhor tombou e pede que você procure por cultistas do Martelo do Crepúsculo lá. O propósito deles é revelado à medida que a investigação continua.",al={"por que fazer vidência em glaive do mestre","missão de onu em glaive"}}},fx={["92e56a99"]={q="O que é o Frasco de Vidência?",a="O Frasco de Vidência é um receptáculo encantado que contém águas místicas fornecidas pelo ancestral de conhecimento, Onu. Quando despejado no campo, cria uma Bacia de Vidência temporária que serve como um condutor mágico, permitindo que você estabeleça uma ligação espiritual direta com o ancestral através de grandes distâncias.",al={"o que é o frasco de vidência","história do frasco de vidência","explicação do frasco de vidência"}},["16c85a4e"]={q="Por que Onu quer que você use o Frasco de Vidência?",a="Onu pede que você vasculhe The Master's Glaive em busca de cultistas do Martelo do Crepúsculo. O frasco permite que você crie uma bacia de vidência e fale com ele após revistar o local, sem precisar retornar ao bosque dele primeiro.",al={"por que usar o frasco de vidência","por que onu quer o frasco","por que precisar do frasco de vidência"}}},fp="16,173,23.242.0,19.313.1,34.155.0,34.122.0,47.120.0,44.171.0"}
P.entries["item:piece-of-krom-zar-s-banner"] = {n="Pedaço do Estandarte de Krom'zar",s="Uma tira de pano rasgada retirada dos estandartes do Warlord Krom'zar, comandante da força de retaliação Kolkar. Ela serve como prova tangível para Regthar Portões-da-morte de que a invasão de centauros vinda de Desolação foi desbaratada.",h="Uma tira de pano rasgada retirada dos estandartes do Warlord Krom'zar, comandante da força de retaliação...",kw={"estandarte","centauro","contra-ataque","encruzilhada","portões-da-morte","kolkar","krom'zar","regthar"},ang={["faction:Horde"]="Derrotar Krom'zar e tomar suas cores interrompe uma grande ofensiva dos centauros, protegendo os corredores do norte entre Durotar, Mulgore e a Encruzilhada.",["race:Tauren"]="A agressão dos centauros há muito atormenta as tribos nômades, tornando a destruição da vanguarda de Krom'zar um bem-vindo sinal de segurança para as trilhas que levam a Mulgore."},sec={{t="Troféu da Incursão Centauro",b="Após a derrota sistemática dos chefes Kolkar pelos Sertões, um furioso bando de guerra marchou para o leste a partir de Desolação, sedento por vingança. Liderados pelo Warlord Krom'zar, esses invasores atacaram os búnqueres defensivos a oeste da Encruzilhada. Cortar um pedaço do estandarte de batalha caído do senhor da guerra fornece uma prova irrefutável a Regthar Portões-da-morte de que o ataque foi esmagado e as rotas comerciais do sul foram preservadas para a Horda."}},faq={{q="Para que serve este pedaço de estandarte?",a="O pano rasgado é levado a Regthar Portões-da-morte em seu búnquer a oeste da Encruzilhada. Ele prova que o Warlord Krom'zar foi morto e sua força de ataque destroçada, concluindo a defesa do norte dos Sertões.",al={"objetivo do estandarte","por que guardar estandarte","o que fazer com pedaço de estandarte"}},{q="Quem foi o Warlord Krom'zar?",a="Krom'zar era um feroz comandante Kolkar enviado dos ermos de Desolação. Ele liderou um contra-ataque direto contra os postos avançados da Horda em resposta à morte dos líderes Kolkar locais.",al={"quem e kromzar","historia de krom'zar","warlord krom'zar"}},{q="Por que os Kolkar atacaram o búnquer?",a="Depois que os campeões da Horda eliminaram os chefes locais dos Sertões — incluindo Barak, Verog e Hezrul —, os centauros enfurecidos reuniram reforços de Desolação para se vingar da Presença da Horda a oeste da Encruzilhada.",al={"por que contra-atacar","motivo da invasao kolkar","motivo do contra-ataque nos sertoes"}},{q="Thrall fica sabendo dessa vitória?",a="Sim. Ao receber o fragmento de estandarte, Regthar Portões-da-morte promete enviar um comunicado oficial diretamente ao Chefe Guerreiro Thrall em Orgrimmar, elogiando os defensores que repeliram a invasão.",al={"recompensa de thrall","thrall fica sabendo"}}},fx={["92115071"]={q="O que é o Pedaço do Estandarte de Krom'zar?",a="É um retalho rasgado recuperado do estandarte de batalha do Senhor da Guerra Krom'zar, comandante do vingativo exército de centauros Kolkar que marchou da Desolação para os Sertões. Para as forças da Horda que defendem os bunkers ocidentais, serve como prova física inegável de que o senhor da guerra caiu em batalha e sua invasão foi contida.",al={"o que é o pedaço do estandarte de krom'zar","pedaço do estandarte de krom'zar","o que é o fragmento de estandarte"}},caa193f6={q="De onde vem o Pedaço do Estandarte de Krom'zar?",a="O estandarte foi levado para os Sertões pelo Senhor da Guerra Krom'zar e sua horda Kolkar, que viajaram desde sua terra natal na Desolação para se vingar da Horda. Quando Krom'zar entra em campo fora dos bunkers ocidentais e cai em combate, seu estandarte é deixado no campo de batalha, onde esse remanescente pode ser arrancado.",al={"de onde veio o estandarte de krom'zar","quem fez o estandarte de krom'zar","origem do estandarte de krom'zar"}},["7a980ed6"]={q="Por que Regthar Deathgate quer um Pedaço do Estandarte de Krom'zar?",a="Regthar Deathgate precisa de uma prova concreta de que o exército invasor Kolkar foi decisivamente esmagado. Apresentar este estandarte rasgado confirma que o Senhor da Guerra Krom'zar foi morto em frente aos bunkers da Horda, permitindo que Regthar declare oficialmente o fim da invasão e envie notícias de seu valor diretamente ao Chefe Guerreiro Thrall.",al={"por que regthar quer o estandarte","por que levar o estandarte de krom'zar para regthar","por que o estandarte de krom'zar é necessário"}}},fp="26,163,31.357.0,35.193.0,25.140.0,37.197.0,33.139.0"}
P.entries["item:plainstrider-beak"] = {n="Bico de Pinote",s="Bicos de Pinote são obtidos das aves altas e que não voam que vagam pelas matas dos Sertões. Os mestres da caça na Encruzilhada coletam esses bicos como prova física de que um caçador abateu as aves locais que ameaçam os mantimentos do assentamento.",h="Bicos de Pinote são obtidos das aves altas e que não voam que vagam pelas matas dos Sertões.",kw={"sertoes","encruzilhada","bico de pinote","a ameaça pinote","sergra espinhonegro","pernalta"},ang={["class:Hunter"]="Derrubar pinotes e colher seus bicos oferece aos rastreadores novatos uma lição introdutória sobre como espreitar e abater presas pelas planícies abertas de Kalimdor.",["faction:Horde"]="Abater os bandos incômodos a leste da Encruzilhada protege diretamente as frágeis rotas comerciais e de suprimentos que mantêm o entreposto da Horda abastecido."},sec={{t="Uma Medida da Caçada",b="As vastas savanas ao redor da Encruzilhada são povoadas por várias raças de pinotes, incluindo variedades maiores, fugazes e rabugentas. Embora sejam presas relativamente simples em comparação com as feras mais ferozes da região central de Kalimdor, seus hábitos agressivos de forrageamento as tornam uma praga constante perto dos assentamentos. Sergra Espinhonegro encarrega os caçadores recém-chegados de trazerem Bicos de Pinote para confirmar que o bando foi afastado das linhas essenciais de suprimentos e armazéns."}},faq={{q="Por que Sergra Espinhonegro quer Bicos de Pinote?",a="Sergra Espinhonegro pede aos caçadores que abatam os pinotes porque as aves agressivas frequentemente atacam os suprimentos de comida ao redor da Encruzilhada. Os bicos servem como prova tangível de uma caçada bem-sucedida, confirmando que a ameaça às rotas locais de suprimentos foi reduzida.",al={"por que coletar bicos","missao bico de pinote sergra","por que bicos"}},{q="Quais criaturas fornecem esses bicos?",a="Eles são obtidos das várias espécies de pernaltas que vagam pela savana, incluindo pinotes maiores, pinotes fugazes e pinotes rabugentos nos Sertões.",al={"o que dropa bico de pinote","fontes de bico de pinote","onde conseguir bicos"}},{q="Por que nem todos os pinotes fornecem um bico ao serem mortos?",a="No caos do combate, especialmente contra aves velozes e que se debatem muito, o bico costuma rachar, estilhaçar ou ficar inutilizável como um troféu de caça limpo, o que significa que apenas espécimes intactos são recolhidos.",al={"por que taxa de saque baixa","bico de pinote nao dropa"}}},fx={["7e2762f5"]={q="O que é um Bico de Pinote?",a="Um Bico de Pinote é o bico cortado das aves não voadoras que vagam pela savana dos Sertões. Duro e pontiagudo, esses bicos são coletados por caçadores como prova tangível de que as aves incômodas que ameaçam os suprimentos locais foram abatidas.",al={"item bico de pinote","o que é o bico de pinote","bicos de pinote"}},["6978f6b2"]={q="De onde vem um Bico de Pinote?",a="Esses bicos vêm diretamente das várias raças de pinotes — como pinotes maiores, ariscos e ferozes — nativos dos Sertões. Eles são colhidos por caçadores nas planícies áridas como troféus e prova de um abate bem-sucedido.",al={"onde conseguir bico de pinote","quem deixa cair bico de pinote","origem do bico de pinote"}}},fp="17,120,21.282.0,50.177.0,34.101.0,54.148.0"}
P.entries["item:plainstrider-feather"] = {n="Pena de Pinote",s="Arrancadas das aves velozes que vagam pelas planícies de Mulgore, as Penas de Pinote são materiais essenciais recolhidos por jovens caçadores na Chapada Nuvem Vermelha. Os taurens da Aldeia Narache as utilizam principalmente na confecção de roupas e adornos tribais, honrando as criaturas que sustentam a aldeia.",h="Arrancadas das aves velozes que vagam pelas planícies de Mulgore, as Penas de Pinote são materiais essenciais...",kw={"aldeia narache","pena","grull vento do falcão","mulgore","pinote","chapada nuvem vermelha","a caçada começa"},ang={["class:Hunter"]="Perseguir pinotes velozes pela Chapada Nuvem Vermelha proporciona a provação fundamental de um iniciado em paciência, rastreamento e respeito à presa.",["race:Tauren"]="Para um jovem tauren, recolher penas de um pinote é uma primeira lição essencial sobre não tomar nada das criaturas da Mãe Terra como garantido, aproveitando cada parte da presa para alimento e vestuário."},sec={{t="A Primeira Oferenda de um Caçador",b="Na Chapada Nuvem Vermelha, os jovens taurens aprendem cedo que a sobrevivência depende de rastreamento e caça aguçados. Os pinotes correm livres pelo platô verdejante, oferecendo tanto sustento quanto materiais práticos. Coletar suas penas resistentes permite que o acampamento confeccione vestimentas tradicionais e equipamentos. Apresentar essas penas junto com carne fresca a Grull Vento do Falcão demonstra respeito pelas necessidades da tribo e serve como o primeiríssimo teste para ser reconhecido pelo Chefe Vento do Falcão e acolhido no Penhasco do Trovão."}},faq={{q="Para que são usadas as Penas de Pinote?",a="Os taurens da Aldeia Narache as utilizam principalmente para fazer roupas e itens cerimoniais. Grull Vento do Falcão as recolhe de caçadores novatos para reabastecer os suprimentos tribais.",al={"propósito da pena","uso da pena de pinote","por que coletar penas"}},{q="Quem recolhe Penas de Pinote na Chapada Nuvem Vermelha?",a="Grull Vento do Falcão as solicita em nome da Aldeia Narache para reabastecer os depósitos da aldeia e testar se os jovens caçadores possuem a disciplina necessária para prover à tribo.",al={"quem quer penas","quem precisa de penas","penas de grull vento do falcão"}},{q="Onde os pinotes podem ser encontrados?",a="Eles vagam pelos campos abertos da Chapada Nuvem Vermelha e por todos os Morros Ondulantes de Mulgore.",al={"onde encontrar pinotes","localização dos pinotes","farmar penas"}},{q="Por que Grull Vento do Falcão exige essas penas para os ritos tribais?",a="A caça é um pilar da cultura tauren, praticada tanto para sobrevivência quanto por esporte. Retornar com sucesso trazendo carne e plumagem prova ao Chefe Vento do Falcão que um iniciado é capaz de sustentar a tribo antes de seguir adiante para o Penhasco do Trovão.",al={"lore de a caçada começa","caçada de provação tauren","por que caçar pinotes"}}},fx={f2ff74a3={q="O que é uma Pena de Pinote?",a="Uma Pena de Pinote é uma plumagem coletada das grandes aves não voadoras que vagam pelas pastagens de Mulgore. Os tauren da Chapada Nuvem Vermelha utilizam cada colheita da terra com profundo respeito, e essas penas resistentes e coloridas servem como materiais práticos para a confecção de vestimentas do dia a dia, bem como adornos tradicionais.",al={"o que é uma pena de pinote","informação sobre pena de pinote","penas de pinote"}},["8bb68bd8"]={q="De onde vêm as Penas de Pinote?",a="Essas penas são plumagens naturais colhidas diretamente dos pinotes selvagens que vagam pela Chapada Nuvem Vermelha e pelas planícies mais amplas de Mulgore. Elas não são fabricadas por mãos mortais, mas sim coletadas por caçadores após uma caçada bem-sucedida na pradaria aberta.",al={"origem da pena de pinote","onde conseguir penas de pinote","quem fez a pena de pinote"}}},fp="20,225,25.400.0,40.153.0,52.186.0,33.85.0,64.179.0"}
P.entries["item:plainstrider-kidney"] = {n="Rim de Pinote",s="Um órgão extraído dos velozes pinotes que vagam pelas planícies áridas dos Sertões. Embora pouco apetitoso para a maioria dos viajantes, serve como um componente bizarro, mas essencial, nas tradições exóticas de fermentação de Kalimdor.",h="Um órgão extraído dos velozes pinotes que vagam pelas planícies áridas dos Sertões.",kw={"cervejeiro drohn","chen malte do trovão","pinote","rim de pinote","vila catraca","malte do trovão","sertões"},ang={["class:Hunter"]="Limpar pinotes no campo ao longo da savana põe à prova a precisão do caçador, garantindo que os órgãos internos permaneçam intactos para o comércio com os cervejeiros de Vila Catraca.",["profession:Cooking"]="Aventureiros culinários podem hesitar em fermentar rins de aves em destilados finos, mas a sobrevivência nos ermos de Kalimdor frequentemente depende do aproveitamento total de cada parte da presa."},sec={{t="Um Ingrediente de Cervejaria Pouco Ortodoxo",b="As vastas extensões dos Sertões são povoadas por aves altas e não voadoras conhecidas como pinotes. Enquanto suas penas e carne costumam ser aproveitadas por caçadores para ferramentas e rações simples, o Cervejeiro Drohn em Vila Catraca busca seus órgãos internos com um propósito completamente diferente. De acordo com o excêntrico cervejeiro, os rins de pinote são um ingrediente necessário para reproduzir a lendária e potente cerveja de Chen Malte do Trovão, conferindo um toque único transmitido por uma linhagem não convencional de mestres cervejeiros."}},faq={{q="Para que serve um Rim de Pinote?",a="O Cervejeiro Drohn em Vila Catraca precisa deles para recriar um lote lendário da cerveja Malte do Trovão. Ele afirma que a receita foi ensinada ao seu mentor diretamente pelo mestre cervejeiro pandaren errante, Chen Malte do Trovão.",al={"uso do rim de pinote","por que preciso de rins de pinote","utilidade do rim de pinote"}},{q="Por que alguém faria cerveja com órgãos de animais?",a="Bebidas exóticas em Kalimdor frequentemente incorporam partes da fauna local rústica para alcançar sabores fortes e marcantes, além de toques distintos. O Cervejeiro Drohn observa que criar receitas tão potentes e selvagens o faz lembrar com carinho de criações pouco ortodoxas, como a cerveja de trogg.",al={"rim na cerveja","por que rim na malte do trovão","partes de animais no álcool"}},{q="Quais criaturas fornecem esses rins?",a="Eles são obtidos das várias espécies de pinotes que correm pelos Sertões, incluindo pinotes fugazes, pinotes ranhetas e pinotes-maiores.",al={"onde cai rim de pinote","quem dropa rim de pinote","fonte de rim de pinote"}},{q="Quais outros ingredientes são necessários junto com os rins?",a="Para completar sua mistura, o Cervejeiro Drohn pede cinco rins de pinote, cinco presas de leão-da-savana e um único Cifre de Lagarto Trovejante.",al={"outros ingredientes de cerveja","o que mais drohn precisa","ingredientes malte do trovão"}}},fx={d14d143c={q="O que é um Rim de Pinote?",a="É um órgão interno colhido dos grandes pinotes não voadores que vagam pelas savanas dos Sertões. Embora a maioria dos caçadores descarte tais entranhas ou as deixe para os necrófagos, certos cervejeiros excêntricos as valorizam como adições potentes e não convencionais a bebidas exóticas.",al={"o que é o rim de pinote","informação sobre rim de pinote","fale sobre o rim de pinote"}},["4fd58422"]={q="De onde vem um Rim de Pinote?",a="Esses órgãos são retirados diretamente dos pinotes selvagens nativos dos Sertões, incluindo variedades maiores, ferozes e ariscas. São partes da anatomia das aves que ocorrem naturalmente, em vez de produtos manufaturados, embora conseguir um exija caçar as velozes e agressivas aves pelas planícies.",al={"origem do rim de pinote","onde conseguir rim de pinote"}},["53f4067b"]={q="Por que o Cervejeiro Drohn quer Rins de Pinote?",a="O Cervejeiro Drohn na Vila Catraca busca esses rins para recriar a lendária e potente cerveja homônima de Chen Malte do Trovão. Chen passou a receita não convencional para o mentor de Drohn, e Drohn precisa dos rins, juntamente com presas de leão e um Cifre de Lagarto Trovejante, para criar a cerveja com seu toque forte característico.",al={"por que rins de pinote são necessários","quem quer rins de pinote","propósito do rim de pinote para drohn"}}},fp="19,181,32.415.0,39.198.0,46.215.0,36.86.0,56.126.0"}
P.entries["item:plainstrider-meat"] = {n="Carne de Pinote",s="A Carne de Pinote é uma caça recém-obtida das aves que não voam e vagam pelas planícies de Mulgore. Para os jovens taurens que chegam à maturidade na Chapada Nuvem Vermelha, coletar esse sustento serve tanto como provisão vital para o inverno quanto como um rito fundamental de passagem.",h="A Carne de Pinote é uma caça recém-obtida das aves que não voam e vagam pelas planícies de Mulgore.",kw={"aldeia narache","chefe vento do falcão","grull vento do falcão","mulgore","pinote","carne de pinote","chapada nuvem vermelha","a caçada começa"},ang={["class:Hunter"]="O veloz pinote oferece aos caçadores iniciantes um teste precoce de suas habilidades de rastreamento e pontaria pelas planícies abertas de Mulgore.",["race:Tauren"]="Para os jovens taurens que dão seus primeiros passos na Chapada Nuvem Vermelha, caçar pinotes é a primeira etapa prática para conquistar o respeito do Chefe Vento do Falcão e o direito de entrar no Penhasco do Trovão."},sec={{t="Sustento para a Chapada",b="A vida dos taurens está inextricavelmente ligada à terra, equilibrando o respeito pela natureza com a necessidade prática de sobrevivência. Na Chapada Nuvem Vermelha, o assentamento da Aldeia Narache depende intensamente da caça obtida nas pradarias ao redor. A carne de pinote fornece reservas essenciais de alimento para a aldeia quando os estoques diminuem, enquanto a plumagem das aves oferece material para vestimentas e adornos cerimoniais."},{t="A Prova do Jovem Caçador",b="A caça aos pinotes é um dos testes iniciais dados aos jovens que buscam conquistar o respeito da tribo. Grull Vento do Falcão orienta os aspirantes a caçadores a perseguirem as velozes aves pela chapada, recolhendo carne e penas para provar suas habilidades de rastreamento e autossuficiência antes de se apresentarem diante de seu pai, o Chefe Vento do Falcão."}},faq={{q="Para que serve a Carne de Pinote?",a="A Carne de Pinote é recolhida por jovens caçadores na Chapada Nuvem Vermelha para reabastecer as reservas esgotadas de comida da Aldeia Narache, cumprindo uma tarefa essencial para Grull Vento do Falcão.",al={"por que carne de pinote","missão carne de pinote","o que fazer com carne de pinote"}},{q="Quem pede essa carne?",a="Grull Vento do Falcão, filho do Chefe Vento do Falcão, pede aos iniciados que cacem os pinotes da chapada para repor os suprimentos de comida da tribo e provar seu valor como provedores.",al={"quem quer carne de pinote","grull vento do falcão carne"}},{q="Onde a Carne de Pinote pode ser encontrada?",a="Ela é obtida dos pinotes incapazes de voar que vagam pelas pradarias de Mulgore, especialmente pelas colinas ondulantes da Chapada Nuvem Vermelha.",al={"onde conseguir carne de pinote","localizações de pinotes","farmar carne de pinote"}},{q="Por que a caça de pinotes é considerada importante para os taurens?",a="Os taurens caçam tanto por necessidade prática quanto por disciplina espiritual. Trazer a caça de volta ao acampamento demonstra respeito pela Mãe Terra, autossuficiência e a capacidade de sustentar a tribo.",al={"cultura de caça tauren","por que caçar pinotes"}}},fx={f404715e={q="O que é Carne de Pinote?",a="Carne de Pinote é caça fresca colhida das aves não voadoras que vagam pelas planícies de Mulgore. Para os tauren da Chapada Nuvem Vermelha, serve como um alimento básico vital, reunido através de caçadas tradicionais que sustentam o povoado e honram o vínculo entre caçador e presa.",al={"informação sobre carne de pinote","o que é carne de pinote","história da carne de pinote"}},["00c8b7f8"]={q="De onde vem a Carne de Pinote?",a="A Carne de Pinote vem dos pinotes selvagens nativos de Mulgore. Jovens caçadores a colhem diretamente das feras que vagam pela Chapada Nuvem Vermelha durante seus primeiros ritos de caça para a tribo.",al={"de onde vem a carne de pinote","origem da carne de pinote","como conseguir carne de pinote"}},f1043112={q="Por que a Carne de Pinote é desejada na Aldeia Narache?",a="Os estoques de comida da Aldeia Narache estão baixos, e a tribo depende de uma caça aguçada para reabastecer seus suprimentos. Grull Vento do Falcão pede aos jovens caçadores que coletem Carne de Pinote para alimentar a aldeia e provar sua habilidade ao Chefe Vento do Falcão.",al={"por que precisar de carne de pinote","propósito da carne de pinote","por que coletar carne de pinote"}}},fp="17,165,23.293.0,22.221.0,35.116.0,23.135.0,37.99.0,64.176.0"}
P.entries["item:plainstrider-scale"] = {n="Escama de Pinote",s="Uma escama resistente obtida dos pernaltas que vagam pelas vastas planícies de Mulgore. Ela serve como um componente vital em um remédio tradicional preparado por Maur Clamachuva para combater uma infecção virulenta.",h="Uma escama resistente obtida dos pernaltas que vagam pelas vastas planícies de Mulgore.",kw={"aldeia casco sangrento","maur clamachuva","mazzranache","mulgore","pinote","remedio","escama","pernalta"},ang={["race:Tauren"]="Coletar remédios da terra reflete as habilidades tradicionais de sobrevivência ensinadas aos jovens caçadores em Mulgore, aproveitando cada parte da fauna das planícies para sustentar a tribo."},sec={{t="Um Ingrediente Raro",b="Embora os pinotes sejam mais conhecidos por suas penas macias e carne magra, suas pernas poderosas são cobertas por escamas protetoras e resistentes. Essas escamas resistem ao terreno acidentado dos matagais e às garras de predadores. Encontrar uma intacta e adequada para a medicina exige paciência, já que apenas alguns pinotes seletos por toda Mulgore rendem escamas firmes o suficiente para serem moídas e preparadas em remédios populares."},{t="Um Remédio para uma Mordida Venenosa",b="Quando Maur Clamachuva, na Aldeia Casco Sangrento, cruzou o caminho de Mazzranache — um pernalta lendário conhecido por seus olhos vermelhos demoníacos e mordida venenosa —, ele sofreu um ferimento grave no ombro. Tomado por uma febre delirante, Maur precisa de uma Escama de Pinote junto a um coração de lobo, fêmur de puma e moela de rapineiro para purificar a infecção que se espalha antes que ela se torne fatal."}},faq={{q="Para que serve a Escama de Pinote?",a="É um ingrediente medicinal essencial coletado para Maur Clamachuva na Aldeia Casco Sangrento. Combinado com partes de outros predadores de Mulgore, ele é preparado em um remédio para tratar um ferimento infectado e venenoso infligido pelo pernalta renegado Mazzranache.",al={"o que faz a escama de pinote","uso da escama de pinote","por que precisa de escama de pinote"}},{q="Onde você encontra uma Escama de Pinote?",a="As escamas são obtidas ao caçar os pinotes selvagens que vagam pelos campos abertos por toda Mulgore.",al={"onde conseguir escama de pinote","como conseguir escama de pinote","localizacao da escama de pinote"}},{q="Por que Maur Clamachuva está infectado?",a="Ao viajar pelas planícies, Maur sofreu uma emboscada e foi mordido no ombro por Mazzranache, um pernalta aterrorizante notório por sua mordida venenosa e olhos carmesins. A mordida o deixou com uma febre delirante e cada vez pior, que o descanso comum não consegue curar.",al={"como maur ficou doente","por que maur esta doente","mordida de mazzranache"}},{q="De quais outros ingredientes Maur precisa para seu remédio?",a="Junto com a Escama de Pinote, Maur precisa de um Coração de Lobo-da-pradaria, um Fêmur de Puma das Estepes e uma Moela de Rapineiro para completar a mistura medicinal.",al={"ingredientes de maur clamachuva","cura para mazzranache","itens de missao mazzranache"}}},fx={["95a4c3dd"]={q="O que é uma Escama de Pinote?",a="É uma escama resistente e especializada colhida dos pinotes que vagam pelas pastagens varridas pelo vento de Mulgore. Embora as aves e os pinotes sejam conhecidos principalmente por sua plumagem e bicos afiados, suas pernas e pés robustos possuem escamas grossas e endurecidas, capazes de resistir às planícies áridas. Xamãs e herbalistas valorizam essas escamas raras e densas por suas características protetoras ao preparar emplastros e curas especializadas.",al={"o que é a escama de pinote","escama de pinote","escamas de pinote"}},d7ded3c8={q="De onde vem uma Escama de Pinote?",a="É uma parte animal natural retirada diretamente dos pinotes selvagens que vagam por Mulgore. Ninguém a fabrica; os caçadores a colhem das pernas de pinotes abatidos pelas planícies, reunindo apenas as escamas mais resistentes para uso em preparações medicinais.",al={"origem da escama de pinote","de onde vem a escama de pinote","quem fez a escama de pinote"}}},fp="18,142,17.156.0,28.325.1,40.203.0,39.85.0,32.167.0,53.115.0"}
P.entries["item:plainstrider-talon"] = {n="Garra de Pinote",s="Por toda Mulgore, xamãs taurens coletam Garras de Pinote para totens de purificação. As garras afiadas vêm de grandes pinotes nativos da região, aves que não voam, e ajudam a purificar a água corrompida.",h="Por toda Mulgore, xamãs taurens coletam Garras de Pinote para totens de purificação.",kw={"aldeia casco sangrento","totem de purificação","mulgore","mull chifre troante","pinote","garra de pinote","poison water","poço casco invernal"},ang={["class:Shaman"]="Como xamã, você pode ver como os rituais taurens usam partes físicas de animais, como garras, para criar totens de purificação e extrair poder dos espíritos nativos da terra.",["race:Tauren"]="Como taurens, você honra o sacrifício da fauna de Mulgore por meio da caça. Cada animal abatido ajuda a curar a Earth Mother quando a exploração goblin ataca."},sec={{t="Laços das Planícies",b="Grandes pinotes, aves que não voam, percorrem os campos abertos de Mulgore, usando pernas poderosas e garras afiadas para buscar alimento no solo duro das pradarias e se defender de predadores. Para os taurens da Aldeia Casco Sangrento, cada parte de um animal caçado carrega uma ressonância espiritual. Quando empreendimentos goblins contaminaram fontes sagradas como o Poço Casco Invernal, o xamã Mull Chifre Troante buscou garras de pinote e patas de lobo da pradaria. Na criação ritualística taurena, reagentes de predadores e animais que buscam alimento nativos canalizam a essência espiritual da terra para totens capazes de expurgar venenos antinaturais."}},faq={{q="Quais criaturas deixam uma Garra de Pinote?",a="Pinotes adultos, pinotes anciãos e o notório pinote Mazzranache fornecem Garras de Pinote pelos campos de Mulgore.",al={"quem deixa garra de pinote","onde conseguir garras de pinote","origem da garra de pinote"}},{q="Para que servem as Garras de Pinote?",a="Mull Chifre Troante, na Aldeia Casco Sangrento, precisa de garras de pinote e patas de lobo da pradaria para criar um totem de purificação para purificar o Poço Casco Invernal corrompido.",al={"uso da garra de pinote","por que preciso de garras","missão da garra de pinote"}},{q="Por que Mull Chifre Troante precisa de partes de animais para limpar a água?",a="O xamanismo taureno se baseia na harmonia com os espíritos naturais de Mulgore. Vincular a fauna local a um totem ritual invoca o poder bruto da terra para combater poluentes antinaturais introduzidos pelos goblins da Empreendimentos S.A.",al={"por que patas e garras de animais","garras no ritual de purificação xamânico"}},{q="Quem envenenou os poços de água de Mulgore?",a="Agentes da Empreendimentos S.A. que operam em Mulgore, junto com seus capangas, contaminaram os poços de água sagrados das tribos. Seus atos perturbam o ambiente local e ameaçam as tribos taurenas.",al={"quem contaminou os poços","quem envenenou a água de mulgore","culpado em poison water"}}},fx={fdecb439={q="O que é uma Garra de Pinote?",a="Uma Garra de Pinote é a garra afiada colhida dos grandes pinotes que não voam e vagam por Mulgore. Embora usada naturalmente por essas aves velozes para defesa e forrageamento pelas planícies, as garras também carregam uma conexão inata com o mundo natural. Para os tauren, tais materiais representam a força da terra e podem ser canalizados por meio de rituais xamânicos.",al={"o que é garra de pinote","folclore garra de pinote","garras de pinote"}},["07c33870"]={q="De onde vêm as Garras de Pinote?",a="Essas garras são tiradas dos pinotes adultos que vagam pelas planícies abertas de Mulgore, a sudoeste da Aldeia Casco Sangrento. Caçadores as coletam de pinotes adultos e anciãos, ou até de bestas raras como Mazzranache, como oferendas da generosidade da terra.",al={"fonte de garra de pinote","onde conseguir garras de pinote","origem da garra de pinote"}},["826885d3"]={q="Por que Mull Chifre Troante quer Garras de Pinote?",a="Mull Chifre Troante na Aldeia Casco Sangrento precisa dessas garras para criar um totem de purificação para o Poço Casco Invernal. Goblins e seus capangas da Empreendimentos S.A. contaminaram a água sagrada, e Mull deve recorrer à essência primal das bestas nativas de Mulgore para neutralizar o veneno e restaurar a pureza do poço.",al={"por que mull quer garras","por que precisar de garra de pinote","propósito da garra de pinote"}}},fp="18,188,19.568.0,41.136.0,38.171.0,63.212.0,40.189.0"}
P.entries["item:podrig-s-order"] = {n="Ordens do Rodrigo",s="No Sepulcro, as Ordens do Rodrigo pede armas novas da Cidade Baixa.",h="No Sepulcro, as Ordens do Rodrigo pede armas novas da Cidade Baixa.",kw={"antônio nunes","hadrec","carlos razok","rodrigo","ordens do rodrigo","o sepulcro","floresta de pinhaprata"},ang={["profession:Blacksmithing"]="Como ferreiro, você sabe como armas forjadas são vitais na linha de frente, onde o combate consome continuamente os suprimentos de uma guarnição.",["race:Undead"]="Como Morto-vivo, você pode ver como a Cidade Baixa abastece postos avançados como o Sepulcro, mantendo os soldados da Dama Sombria armados contra o Flagelo."},sec={{t="Armando O Sepulcro",b="O necroguarda Rodrigo considerou os estoques do Sepulcro em sua maioria adequados, após um inventário ordenado pelo Executor Hadrec. As armas de reposição estavam quase acabando. Seu despacho lista as lâminas e armas necessárias aos necroguardas que defendem o posto avançado na Floresta de Pinhaprata, uma fronteira ameaçada pelo Flagelo, por feras selvagens e por outros perigos."},{t="Despacho pelo Tratador de Morcegos",b="A ordem é enviada a Antônio Nunes, um vendedor de armas no Distrito Comercial da Cidade Baixa, pois é difícil forjar armas nas criptas úmidas da Floresta de Pinhaprata. Mensageiros levam o documento ao mestre de morcegos Carlos Razok, usando as rotas aéreas dos Renegados para agilizar o envio da capital."}},faq={{q="O que está escrito em Ordens do Rodrigo?",a="Ordens do Rodrigo lista armas de reposição para os necroguardas do Sepulcro, cujas armas foram perdidas ou quebradas em combate.",al={"o que a ordem diz","conteúdo de ordens do rodrigo","detalhes de ordens do rodrigo"}},{q="Quem escreveu Ordens do Rodrigo?",a="O necroguarda Rodrigo escreveu a ordem por determinação do Executor Hadrec, após um inventário do arsenal do Sepulcro.",al={"quem escreveu","autor de ordens do rodrigo"}},{q="Quem recebe a ordem?",a="A ordem deve ser recebida por Antônio Nunes, um vendedor de armas no Distrito Comercial da Cidade Baixa.",al={"quem recebe a ordem","para onde vai ordens do rodrigo","destinatário de ordens do rodrigo"}},{q="Por que O Sepulcro precisa de novas armas?",a="Os necroguardas precisam de armas novas porque os confrontos com o Flagelo e outras forças hostis na Floresta de Pinhaprata costumam deixar seus equipamentos quebrados ou perdidos.",al={"por que precisa de armas","falta de armas no sepulcro"}}},fx={["92a3bbc0"]={q="O que são as Ordens do Rodrigo?",a="As Ordens do Rodrigo são um documento de requisição oficial dos Renegados, escrito para garantir armamentos novos para o posto avançado no Sepulcro. Redigido por Podrig em nome do Executor Hadrec, o pergaminho lista as armas de reposição necessárias para que os Guardas da Morte da guarnição sobrevivam aos seus constantes confrontos contra o Flagelo e outros terrores que espreitam na Floresta de Pinhaprata.",al={"o que são as ordens do rodrigo","item ordens do rodrigo","requisição de podrig"}},["6fc9fe58"]={q="Por que Antônio Nunes precisa das Ordens do Rodrigo?",a="Como vendedor de armas no Distrito Comercial da Cidade Baixa, Antônio Nunes precisa da requisição formal para verificar e cumprir o pedido de suprimentos da guarnição. Sem este manifesto verificado, O Sepulcro não pode receber o carregamento necessário de lâminas e equipamentos para reabastecer seus Guardas da Morte na linha de frente.",al={"por que antônio nunes quer as ordens","por que levar as ordens do rodrigo para a cidade baixa","por que as ordens do rodrigo são necessárias"}}},fp="14,82,20.335.0,24.268.0,34.124.0,25.121.0,23.96.0,40.152.0"}
P.entries["item:pork-belly-pie"] = {n="Torta de Barriga de Porco",s="A Torta de Barriga de Porco é um prato salgado caseiro assado pela 'Tia' Bernice Stonefield na Floresta de Elwynn. Apesar da rivalidade amarga e duradoura entre as famílias Stonefield e Maclure, o jovem Guinho Madruga não consegue resistir à culinária da Tia Bernice, exigindo uma torta como suborno para revelar informações sobre uma herança de família perdida.",h="A Torta de Barriga de Porco é um prato salgado caseiro assado pela 'Tia' Bernice Stonefield na Floresta de...",kw={"tia bernice stonefield","...com a vontade de comer","guinho madruga","floresta de elwynn","madruga","torta de barriga de porco","stonefield"},ang={["faction:Alliance"]="Para viajantes da Aliança que ajudam a área rural da Floresta de Elwynn, realizar tarefas como entregar tortas esclarece as brigas triviais, porém profundamente enraizadas, que dividem o coração agrário de Ventobravo.",["profession:Cooking"]="A torta destaca como a comida caseira e reconfortante pode exercer influência real sobre disputas locais, mesmo que a receita em si permaneça um segredo guardado da Tia Bernice."},sec={{t="Um Suborno Entre Fazendas Rivais",b="As famílias Stonefield e Maclure nutrem uma rivalidade amarga há anos, brigando por terras e orgulho no coração da Floresta de Elwynn. Apesar dessa hostilidade, o jovem Guinho Madruga tem uma fraqueza óbvia: ele adora a famosa torta de barriga de porco da Tia Bernice. Quando um valioso colar da família desaparece, Guinho se recusa a compartilhar o que sabe até que um aventureiro lhe entregue uma fatia quente. Bernice a prepara com muita relutância — e um desejo explícito de que o garoto ganancioso engasgue com ela — provando que a reputação culinária às vezes pode romper até as mais teimosas disputas familiares."}},faq={{q="Para que serve a Torta de Barriga de Porco?",a="A torta é assada pela Tia Bernice Stonefield para subornar o jovem Guinho Madruga. Guinho tem pistas cruciais sobre um colar de família desaparecido que pertence aos Stonefield, mas ele se recusa a falar até que seu apetite seja saciado com a culinária da Tia Bernice.",al={"uso da torta","por que torta de barriga de porco","o que faço com a torta"}},{q="Quem assa a Torta de Barriga de Porco?",a="A torta é assada na hora pela Tia Bernice Stonefield na Fazenda dos Campedra. Embora ela tenha um profundo ressentimento por Guinho Madruga e pelo resto de sua família, ela a prepara mesmo assim para ajudar a recuperar o colar perdido de sua família.",al={"quem fez a torta","boleira","torta da vovó stonefield"}},{q="Por que Guinho Madruga quer comida de uma família rival?",a="Apesar da rivalidade feroz e barulhenta entre os Stonefields e os Maclures, a culinária da Tia Bernice é bem conhecida em todo o vale. Guinho se importa muito mais com seu estômago e sua saborosa barriga de porco do que em manter as mágoas de sua família.",al={"por que guinho quer torta","por que um madruga quer comida dos stonefield"}},{q="Os jogadores podem comer a Torta de Barriga de Porco?",a="Não. A torta é um item de missão destinado apenas a Guinho Madruga. Você não pode consumi-la para restaurar vida ou mana, não importa o quão apetitosa ela pareça.",al={"posso comer","torta de barriga de porco é comestível"}}},fx={["6505ed9f"]={q="O que é a Torta de Barriga de Porco?",a="É uma torta de carne saborosa assada com barriga de porco, famosa por ser deliciosa apesar da amarga rivalidade entre as duas famílias de agricultores do sul da Floresta de Elwynn. Preparada na hora na cozinha da família Stonefield, ela serve como um suborno de dar água na boca para conseguir informações do filho dos Maclure, Billy, que alega que sua memória só funciona de barriga cheia.",al={"o que é torta de barriga de porco","folclore torta de barriga de porco","sobre torta de barriga de porco"}}},fp="14,167,29.366.0,36.188.0,29.161.0,53.181.0,35.85.0"}
P.entries["item:powdered-azurite"] = {n="Azurita Pulverizada",s="Azurita Pulverizada é um reagente mineral triturado colhido na Mina Veioazul no Contraforte de Eira dos Montes. Ele é procurado pelo mestre armeiro Thun'grim Firegaze para temperar e forjar Brutal Armor para os guerreiros da Horda em ascensão.",h="Azurita Pulverizada é um reagente mineral triturado colhido na Mina Veioazul no Contraforte de Eira dos...",kw={"mina veioazul","azurita","brutal armor","eira dos montes","azurita pulverizada","reagente","thun'grim firegaze"},ang={["class:Warrior"]="Adquirir Azurita Pulverizada prova sua resistência no exterior, coletando os reagentes especializados necessários a Thun'grim Firegaze para forjar armaduras pessoais de força selvagem.",["faction:Horde"]="Reivindicar este pó refinado exige avançar profundamente nos Reinos do Leste, tirando recursos diretamente das mãos da Aliança no Contraforte de Eira dos Montes."},sec={{t="Um Composto Mineral Raro",b="Azurita Pulverizada é um pó refinado derivado dos veios minerais sob o Contraforte de Eira dos Montes. Os trabalhadores humanos da Mina Veioazul cavam a terra para extrair esta pedra azul distinta, pulverizando-a e embalando-a para comércio e metalurgia. Nas mãos de um ferreiro habilidoso, o pó atua como um fluxo ou aditivo crucial ao trabalhar metais densos, aumentando a durabilidade e conferindo resiliência única à armadura acabada."},{t="Forjando Brutal Armor",b="Embora nativa dos túneis controlados por humanos através do Grande Oceano, a Azurita Pulverizada é reconhecida pelos ferreiros veteranos da Horda por suas propriedades metalúrgicas excepcionais. Thun'grim Firegaze, um armeiro orc envelhecido que reside nos Sertões, exige pequenas quantidades da pedra em pó junto com ferro refinado e reagentes ígneos. Misturado na fundição, o pó permite que ele molde as placas pesadas e punitivas que caracterizam sua armadura de batalha de obra-prima."}},faq={{q="Para que serve a Azurita Pulverizada?",a="Ela serve como um componente metalúrgico essencial para Thun'grim Firegaze, um mestre armeiro estacionado nos Sertões. Ele combina o mineral triturado com lingotes de ferro e reagentes voláteis para martelar peças de Brutal Armor para os campeões da Horda.",al={"uso da azurita pulverizada","o que é azurita pulverizada"}},{q="Onde a Azurita Pulverizada pode ser encontrada?",a="Ela é coletada dos mineradores humanos que trabalham na Mina Veioazul, localizada ao longo da costa sul do Contraforte de Eira dos Montes nos Reinos do Leste.",al={"onde encontrar azurita pulverizada","localização da azurita pulverizada","quem deixa cair azurita pulverizada"}},{q="Por que um armeiro nos Sertões precisa de reagentes de Eira dos Montes?",a="Thun'grim Firegaze procura os melhores materiais para produzir armaduras dignas de guerreiros lendários. Embora o ferro esteja prontamente disponível, as qualidades de têmpera específicas concedidas pelo mineral da Mina Veioazul fazem com que valha a pena pedir aos seus campeões que viajem através do mar para adquiri-lo.",al={"por que eira dos montes","fonte de mineral do thungrim"}}},fx={["139f7c50"]={q="O que é Azurita Pulverizada?",a="Azurita Pulverizada é um reagente mineral azul triturado extraído de veios profundos no Contraforte de Eira dos Montes. Venerado por armeiros mestres por suas propriedades metalúrgicas únicas, o pó fino pode ser ligado ou temperado em metais básicos durante a forja. É particularmente valorizado pelo armeiro da Horda Thun'grim Firegaze, que a utiliza junto com reagentes exóticos para criar uma armadura de malha pesada e resistente, digna de guerreiros renomados.",al={"o que é pó de azurita","folclore azurita pulverizada","item azurita pulverizada"}},["720f3d61"]={q="De onde vem a Azurita Pulverizada e quem a minerou?",a="A substância é extraída da Mina Veioazul, situada ao longo das colinas do sul do Contraforte de Eira dos Montes. Mineradores humanos que trabalham nos poços subterrâneos da Mina Veioazul desenterram o minério de azurita bruto e o moem até transformá-lo em um pó refinado. Como a mina permanece sob o controle firme dos trabalhadores humanos de Eira dos Montes, obter o pó exige tirá-lo diretamente dos mineradores que trabalham sob a terra.",al={"onde conseguir azurita pulverizada","quem minera azurita pulverizada","fonte de azurita pulverizada"}}},fp="16,168,23.218.0,20.366.0,34.133.0,36.128.0,67.193.0"}
P.entries["item:powers-of-the-void"] = {n="Poderes do Caos",s="Poderes do Caos é um raro tomo mágico originalmente guardado em uma ala restrita da biblioteca da Abadia de Vila Norte. Depois que um novato rebelde o roubou ao desertar para A Irmandade Défias, a mentora dos bruxos, Drusilla La Salle, busca sua recuperação para aprofundar seus próprios estudos de magia sombria.",h="Poderes do Caos é um raro tomo mágico originalmente guardado em uma ala restrita da biblioteca da Abadia de...",kw={"irmandade défias","drusilla la salle","diabrete","khadgar","abadia de vila norte","poderes do caos","livros roubados","ladrão que rouba ladrão...","bruxo"},ang={["class:Warlock"]="Recuperar este grimório roubado serve como o teste fundamental para jovens bruxos humanos, demonstrando vontade suficiente para obter o segredo de evocar um diabrete.",["race:Human"]="A presença do tomo em Vila Norte revela que a Sagrada Ordem preserva registros mágicos perigosos ao lado de textos clericais padrão, mantendo-os ocultos dos olhos dos novatos."},sec={{t="Um texto restrito de Vila Norte",b="Os arquivos da Abadia de Vila Norte guardam muito mais do que escrituras sagradas e registros clericais. Escondido em uma ala protegida da biblioteca da abadia estava Poderes do Caos, uma obra erudita sobre energias das sombras e do Éter, supostamente escrita pelo arquimago Khadgar. Dada a natureza perigosa de tal pesquisa, as autoridades da abadia mantinham o livro fortemente vigiado e estritamente proibido a visitantes casuais. Isso o manteve fora do alcance da mentora local dos bruxos de Vila Norte, Drusilla La Salle, que não podia rondar as estantes restritas sem levantar suspeitas indesejadas do sacerdócio."},{t="Roubo Défias e recuperação",b="O tomo finalmente deixou os muros da abadia não pelas mãos de Drusilla, mas por meio de uma traição intestina. Um novato que estudava em Vila Norte abandonou seus votos para se juntar à Irmandade Défias, saqueando vários volumes valiosos enquanto fugia para os vinhedos vizinhos. Aproveitando-se do oportunismo do ladrão, Drusilla envia iniciados bruxos promissores diretamente para o acampamento de bandidos Défias a fim de pegar o tomo em suas tendas. Recuperar o texto serve a um propósito duplo: coloca o conhecimento sombrio nas mãos da instrutora e testa se um novato possui a coragem necessária para subjugar demônios de outros mundos."}},faq={{q="O que é Poderes do Caos?",a="É um raro livro ocultista que detalha energias sombrias e conceitos do Éter, que se acredita ter sido escrito pelo arquimago Khadgar. Ele estava trancado dentro de uma ala restrita da Abadia de Vila Norte antes de ser roubado.",al={"o que e poderes do caos","livro poderes do caos","o que e ladrao que rouba ladrao..."}},{q="Por que o livro estava trancado na Abadia de Vila Norte?",a="A Abadia de Vila Norte preserva arquivos históricos, incluindo textos perigosos sobre magias ilícitas. Livros que detalham energias do Caos e demonologia são mantidos a sete chaves para evitar que novatos e praticantes desvirtuados os utilizem de forma indevida.",al={"por que estava na abadia","por que os padres tinham isso","ala da biblioteca de vila norte"}},{q="Como a Irmandade Défias conseguiu o livro?",a="Um novato da abadia desertou para se juntar à Irmandade Défias e levou vários volumes valiosos da biblioteca restrita de Vila Norte com ele, escondendo-os no acampamento de bandidos nos Vinhedos de Vila Norte.",al={"quem roubou o livro","livros roubados defias","como defias conseguiu"}},{q="Por que Drusilla La Salle quer Poderes do Caos?",a="Drusilla é a instrutora residente de bruxos de Vila Norte. Ela cobiça o conhecimento esotérico do tomo para sua própria arte sombria, mas nunca poderia entrar nos arquivos seguros da biblioteca da abadia sem soar o alarme.",al={"por que drusilla quer isso","quem quer o livro","drusilla la salle ladrao que rouba ladrao..."}},{q="O que a recuperação do tomo prova a Drusilla?",a="Recuperar o tomo prova a Drusilla que um iniciado tem a astúcia, a força e a determinação necessárias para comandar servos demoníacos, garantindo a ele instruções sobre como evocar seu primeiro diabrete.",al={"por que bruxos precisam do livro","teste de evocacao de diabrete","recompensa de ladrao que rouba ladrao..."}}},fx={["082e56cb"]={q="Quem escreveu Poderes do Caos?",a="Acredita-se que o tratado arcano tenha sido escrito pelo lendário arquimago Khadgar, que estudou muitos aspectos profundos e perigosos da magia antes de se aventurar além do Portal Negro. Seus insights proibidos sobre o vazio profundo foram considerados perigosos demais para uma leitura casual, levando os sacerdotes e estudiosos da Abadia de Vila Norte a selá-lo dentro de uma ala protegida de sua biblioteca até que um noviço traiçoeiro o roubou.",al={"autor de poderes do caos","quem fez poderes do caos","criador de poderes do caos"}}},fp="18,251,28.476.0,25.427.0,27.217.0,47.198.0,44.183.0,51.175.0,48.147.0"}
P.entries["item:prairie-alpha-tooth"] = {n="Dente de Lobo-da-pradaria Alfa",s="Um Dente de Lobo-da-pradaria Alfa é obtido dos ferozes líderes de matilha que vagam pelas planícies ao redor do Penhasco do Trovão. Na tradição taurena, esses dentes servem como uma oferenda poderosa para purificar e honrar as preciosas fontes de água da terra.",h="Um Dente de Lobo-da-pradaria Alfa é obtido dos ferozes líderes de matilha que vagam pelas planícies ao redor...",kw={"aldeia casco sangrento","mulgore","mull chifre troante","dente de lobo-da-pradaria alfa","lobo-da-pradaria alfa","poço de água","totem de juba agreste"},ang={["class:Shaman"]="Os espíritos dos poços de água devem ser aplacados por meio do equilíbrio terreno, e a oferenda das presas de um predador ápice ancora essa harmonia natural.",["race:Tauren"]="Tomar a presa de um alfa da pradaria representa o dever sagrado do caçador de colher o que é necessário com respeito, devolvendo essa essência primordial para curar a terra envenenada."},sec={{t="Uma Oferenda Purificadora",b="Os poços de água de Mulgore são fontes vitais para os taurens, e manter sua pureza espiritual exige ritos de respeito e sacrifício. Para purificar o Poço de Juba Agreste, Mull Chifre Troante, da Aldeia Casco Sangrento, precisa de dentes colhidos dos lobos-da-pradaria alfas que espreitam nas sombras do Penhasco do Trovão. Como predadores ápices das planícies verdejantes onduladas, esses alfas representam a força bruta da natureza selvagem. Oferecer seus dentes honra o equilíbrio entre caçador, presa e os espíritos da terra."}},faq={{q="Para que serve um Dente de Lobo-da-pradaria Alfa?",a="Mull Chifre Troante usa oito desses dentes em um ritual para purificar o Poço de Juba Agreste, o último poço de água contaminado perto da Aldeia Casco Sangrento.",al={"propósito do dente de alfa","para que servem os dentes de lobo mulgore","item totem de juba agreste"}},{q="Onde vagam os lobos-da-pradaria alfas?",a="Os lobos-da-pradaria alfas rondam as planícies verdejantes abertas do centro e do norte de Mulgore, circulando principalmente os penhascos ao redor da base do Penhasco do Trovão.",al={"onde estão os lobos-da-pradaria alfas","locais de lobos alfas","pontos de lobos-da-pradaria alfas"}},{q="Por que um ritual de purificação de água exige dentes de lobo?",a="Os ritos taurens honram o equilíbrio da natureza. A purificação dos poços exige componentes sagrados colhidos diretamente das ferozes feras nativas da terra, simbolizando tanto o sacrifício quanto a vitalidade da vida selvagem de Mulgore.",al={"por que dentes de lobo para água","lore do ritual de dentes mull chifre troante"}}},fx={f1f3b80c={q="O que é um Dente de Lobo-da-pradaria Alfa?",a="Um Dente de Lobo-da-pradaria Alfa é um dente tirado de um lobo-da-pradaria alfa, um dos líderes de alcateia mais ferozes que rondam as planícies de Mulgore. Entre os tauren, essas presas representam a força e o espírito dos predadores alfa da terra, carregando um peso espiritual quando oferecidas em ritual.",al={"dente de lobo-da-pradaria alfa","o que é dente de lobo-da-pradaria alfa","dente de alfa de lobo-da-pradaria"}},["0674aadd"]={q="De onde vem um Dente de Lobo-da-pradaria Alfa?",a="Esses dentes são colhidos de lobos-da-pradaria alfa que vagam pelas pastagens de Mulgore, particularmente perto da base do Penhasco do Trovão ao norte. Sendo presas naturais de predadores vivos, eles são retirados diretamente das bestas durante a caçada, em vez de serem criados por mãos mortais.",al={"de onde vêm os dentes de lobo-da-pradaria alfa","origem do dente de lobo-da-pradaria alfa","quem deixa cair dente de lobo-da-pradaria alfa"}}},fp="19,134,20.357.0,39.147.0,34.146.0,53.169.0"}
P.entries["item:prairie-wolf-heart"] = {n="Coração de Lobo-da-pradaria",s="Um Coração de Lobo-da-pradaria é um órgão vital obtido dos lobos que vagueiam pelas pradarias de Mulgore. Ele serve como ingrediente essencial em um remédio popular urgente preparado por Maur Clamachuva na Aldeia Casco Sangrento para conter uma infecção venenosa.",h="Um Coração de Lobo-da-pradaria é um órgão vital obtido dos lobos que vagueiam pelas pradarias de Mulgore.",kw={"aldeia casco sangrento","maur clamachuva","mazzranache","mulgore","prairie stalker","coração de lobo-da-pradaria","coração de lobo"},ang={["class:Hunter"]="Rastrear matilhas de lobos específicas nas planícies demonstra uma compreensão inicial da presa e da ecologia das feras em Mulgore.",["race:Tauren"]="Usar partes colhidas de animais para preparar curas de sobrevivência reflete as tradições pragmáticas e ligadas à terra dos taurens pelas terras selvagens de Mulgore."},sec={{t="Um Remédio para uma Picada Venenosa",b="Os lobos das planícies são predadores ferozes, resistentes e persistentes através das amplas relvas de Mulgore. Seus corações são procurados por Maur Clamachuva, um tauren residente na Aldeia Casco Sangrento que foi vítima do lendário pinote conhecido como Mazzranache. Atingido pelo veneno virulento e causador de febre da criatura, Maur recorre à medicina tradicional das planícies para deter o veneno que se espalha. Ao lado de outros reagentes potentes como osso de puma e moela de pássaro, a essência vital de um lobo-da-pradaria recém-abatido fornece as propriedades purificadoras necessárias para preparar uma cura antes que o delírio se torne fatal."}},faq={{q="Para que serve um Coração de Lobo-da-pradaria?",a="Ele é coletado para Maur Clamachuva na Aldeia Casco Sangrento. Maur precisa dele junto com várias outras partes de animais para preparar uma potente medicina popular para tratar uma picada venenosa infligida pelo notório pinote Mazzranache.",al={"uso do coração de lobo","por que pegar coração de lobo","propósito do coração de lobo-da-pradaria"}},{q="Onde se obtém um Coração de Lobo-da-pradaria?",a="Ele é retirado dos corpos de lobos-da-pradaria, lobos-da-pradaria alfa e prairie stalkers encontrados caçando pelos Morros Ondulantes de Mulgore.",al={"localização do coração de lobo","quem dropa coração de lobo","como encontrar coração de lobo-da-pradaria"}},{q="Por que Maur Clamachuva precisa de órgãos de animais para tratar seu ferimento?",a="Mazzranache inflige uma picada terrível e infectada que causa febre e delírio. Maur usa remédios tradicionais das planícies dos taurens compostos por reagentes potentes — coração de lobo, fêmur de puma, Escama de Pinote e Moela de Rapineiro — para purificar a infecção antes que ela se torne letal.",al={"por que coração de lobo para remédio","remédio de maur"}},{q="Qualquer coração de lobo pode ser usado para o remédio?",a="Maur Clamachuva pede simplesmente um coração de lobo. Aquele coletado para o remédio é obtido de lobos-da-pradaria, lobos-da-pradaria alfa ou prairie stalkers que caçam nas planícies de Mulgore.",al={"qualquer coração de lobo","quais lobos dropam"}}},fx={ee1c9772={q="O que é um Coração de Lobo-da-pradaria?",a="Um Coração de Lobo-da-pradaria é o órgão colhido dos lobos predadores que rondam as colinas de Mulgore. Embora tenha pouco valor comercial comum, a vitalidade do coração de uma besta selvagem o torna um ingrediente valioso na medicina tradicional tauren. Ele serve como um dos vários reagentes potentes necessários para preparar remédios capazes de purgar venenos naturais virulentos e infecções profundas.",al={"o que é coração de lobo-da-pradaria","coração de lobo-da-pradaria","sobre coração de lobo-da-pradaria"}},["1392571f"]={q="De onde vem um Coração de Lobo-da-pradaria?",a="O coração é retirado diretamente dos lobos-da-pradaria selvagens, lobos-da-pradaria alfa e espreitadores da pradaria nativos dos planaltos gramados de Mulgore. É um órgão biológico natural colhido de um predador abatido, em vez de um objeto criado por mãos mortais.",al={"de onde vem o coração de lobo-da-pradaria","origem do coração de lobo-da-pradaria","quem fez o coração de lobo-da-pradaria"}}},fp="18,89,28.330.0,38.170.0,43.121.0,63.220.0,42.143.0"}
P.entries["item:prairie-wolf-paw"] = {n="Pata de Lobo-da-pradaria",s="Patas de Lobo-da-pradaria são obtidas dos predadores que vagam pelas planícies de Mulgore. Praticantes xamânicos, como Mull Chifre Troante na Aldeia Casco Sangrento, as utilizam como componentes orgânicos para vincular o poder natural da terra a totens purificadores.",h="Patas de Lobo-da-pradaria são obtidas dos predadores que vagam pelas planícies de Mulgore.",kw={"aldeia casco sangrento","mulgore","mull chifre troante","garra de pinote","água venenosa","lobo-da-pradaria","pata de lobo-da-pradaria","poço casco invernal"},ang={["class:Shaman"]="A confecção de totens purificadores a partir de partes de animais locais demonstra o princípio elemental de usar a essência viva da terra para purgar a corrupção antinatural.",["race:Tauren"]="Para os taurens, colher patas de lobo é um dever solene de zelo, invocando as feras nativas da terra para curar os poços d'água ancestrais contaminados pela ganância dos goblins."},sec={{t="Reagentes Naturais das Planícies",b="Lobos-da-pradaria espreitam pelas campinas ondulantes de Mulgore, caçando em matilhas ao lado de espreitadores-da-pradaria e seus machos-alfa. Embora perigosos para jovens caçadores e para o gado local, essas criaturas estão profundamente interligadas ao equilíbrio espiritual das planícies. Os xamãs taurens veem as patas dos lobos não meramente como troféus, mas como condutores vitais da vitalidade inata da terra."},{t="Purificando os Poços",b="Quando empreendimentos goblins contaminaram as reservas de água sagradas de Mulgore, o xamã Mull Chifre Troante precisou do auxílio físico da própria terra para neutralizar a poluição. Unidas a garras de pisapradarias, as patas de lobo fornecem a ressonância espiritual bruta necessária para criar totens purificadores, dando início ao trabalho vital de purificar o Poço Casco Invernal."}},faq={{q="Quais criaturas concedem Pata de Lobo-da-pradaria?",a="Elas são obtidas de lobos-da-pradaria, espreitadores-da-pradaria e lobos-da-pradaria alfa encontrados caçando pelas planícies de Mulgore, principalmente a sudoeste da Aldeia Casco Sangrento.",al={"quem dropa pata de lobo-da-pradaria","onde conseguir patas de lobo-da-pradaria","fonte de pata de lobo-da-pradaria"}},{q="Quem quer Patas de Lobo-da-pradaria?",a="Mull Chifre Troante, um xamã tauren situado na Aldeia Casco Sangrento, pede que elas sejam trazidas para ajudar a confeccionar um totem purificador para restaurar os poços d'água contaminados.",al={"quem precisa de patas de lobo-da-pradaria","mull chifre troante patas de lobo","entregar pata de lobo-da-pradaria"}},{q="Por que patas de lobo são necessárias para purificar a água?",a="O xamanismo tauren baseia-se em canalizar a vitalidade natural da terra para neutralizar a corrupção. As patas de lobo, combinadas com garras de pássaros, permitem que o xamã vincule o espírito vivo de Mulgore a um totem elemental capaz de purgar os venenos dos goblins.",al={"por que patas de lobo","história da pata de lobo-da-pradaria","por que mull quer patas"}},{q="Qual poço d'água essas patas ajudam a purificar?",a="As patas são recolhidas especificamente para confeccionar o totem purificador para o Poço Casco Invernal, que foi envenenado por invasores goblins e seus agentes.",al={"qual poço","purificação do poço casco invernal"}}},fx={["94c15e4c"]={q="O que é uma Pata de Lobo-da-pradaria?",a="Uma Pata de Lobo-da-pradaria é um componente ritual natural colhido dos caninos selvagens que vagam pelas planícies de Mulgore. Em vez de servirem apenas como troféus, essas patas carregam a essência viva da terra, tornando-as valiosas para xamãs tauren que criam totens para curar e preservar a terra.",al={"pata de lobo-da-pradaria","o que são patas de lobo-da-pradaria","pata de lobo mulgore"}},["7a637be5"]={q="De onde vêm as Patas de Lobo-da-pradaria?",a="Essas patas são colhidas diretamente de lobos-da-pradaria, espreitadores da pradaria e alfas nativos dos planaltos gramados de Mulgore. Elas são partes naturais da natureza, levadas por caçadores para oferecer a força da terra em tempos de necessidade espiritual.",al={"de onde vêm as patas de lobo-da-pradaria","fonte de pata de lobo-da-pradaria","quem deixa cair patas de lobo"}}},fp="16,198,30.301.0,19.306.0,39.155.0,28.130.0,42.193.0,44.116.0"}
P.entries["item:prayer-to-elune"] = {n="Prayer to Elune",s="Prayer to Elune está gravada em uma tabuleta dourada entre os pertences de Twilight’s Hammer. Ela traz um apelo destinado a Astarii Mirestela, no Templo da Lua.",h="Prayer to Elune está gravada em uma tabuleta dourada entre os pertences de Twilight’s Hammer.",kw={"astarii mirestela","darnassus","elune","tabuleta dourada","prece a elune","garganta abrasadora","templo da lua","twilight's hammer"},ang={["race:NightElf"]="Como elfo noturno, você conhece Elune como a deusa do seu povo; esta tabuleta traz uma prece destinada a chegar até ela."},sec={{t="Uma Tabuleta Dourada",b="Entre os pertences de Twilight’s Hammer na Garganta Abrasadora há uma tabuleta dourada com uma prece a Elune. Astarii Mirestela, no Templo da Lua de Darnassus, pede que a levem até ela para que a prece chegue à sua deusa."}},faq={{q="O que é Prayer to Elune?",a="Prayer to Elune é uma prece gravada em uma tabuleta dourada.",al={"tabuleta de prece","prece a elune","qual prece"}},{q="Onde está a prece?",a="A tabuleta dourada está entre os pertences de Twilight’s Hammer na Garganta Abrasadora.",al={"onde está a tabuleta","encontrar a prece","local da prece"}},{q="Quem quer a tabuleta?",a="Astarii Mirestela, no Templo da Lua em Darnassus, pede a prece.",al={"quem quer a prece","prece de astarii","para quem levar"}},{q="Por que Astarii a quer?",a="Astarii quer que a prece seja devolvida para que Elune possa ouvi-la.",al={"por que a tabuleta","por que a prece a elune","para que serve"}}},fp="15,177,15.233.0,28.60.0,20.83.0,21.78.0,25.62.0"}
P.entries["item:pridewing-venom-sac"] = {n="Vesícula de Peçonha de Asaltiva",s="As Vesículas de Peçonha de Asaltiva são obtidas dos perigosos mantícoras que nidificam ao redor do Lago Mirkfallon, na Cordilheira das Torres de Pedra. Os elfos noturnos de Astranaar buscam estocar e destruir essas vesículas após relatos de inteligência indicarem que operativos da Horda extraem o potente veneno para assassinatos sigilosos.",h="As Vesículas de Peçonha de Asaltiva são obtidas dos perigosos mantícoras que nidificam ao redor do Lago...",kw={"astranaar","lago mirkfallon","asaltiva","shindrell fogofugaz","cordilheira das torres de pedra","vesícula de peçonha","mantícora"},ang={["faction:Alliance"]="Negar o acesso da Horda ao veneno dos asaltivas é vital para resguardar as patrulhas de fronteira contra assassinos invisíveis ao longo das divisas disputadas da Cordilheira das Torres de Pedra e de Vale Gris.",["race:NightElf"]="Embora a liderança das Sentinelas lamente ter que abater feras selvagens inocentes, proteger vidas de elfos contra lâminas envenenadas tem prioridade sobre a harmonia natural."},sec={{t="Uma Ameaça nos Penhascos",b="Os asaltivas das Torres de Pedra são predadores aéreos perigosos, nativos dos picos ao sul de Vale Gris, particularmente ao redor do Lago Mirkfallon. Embora os mantícoras selvagens sejam peçonhentos por natureza, informações da inteligência da Aliança vindas de Theramore indicam que assassinos da Horda começaram a extrair seu veneno para cobrir lâminas usadas em ataques furtivos contra assentamentos de elfos noturnos. Para proteger seu povo e prejudicar os suprimentos inimigos, as Sentinelas de Astranaar contratam batedores para caçar as feras e coletar as glândulas de peçonha antes que a Horda possa garanti-las."}},faq={{q="Quais criaturas fornecem uma Vesícula de Peçonha de Asaltiva?",a="Essas vesículas de peçonha são obtidas dos vários mantícoras que habitam os penhascos perto do Lago Mirkfallon, na Cordilheira das Torres de Pedra, incluindo asaltivas jovens, caça-céus, patriarcas e consortes.",al={"onde conseguir vesícula de peçonha de asaltiva","quem dropa vesícula de peçonha de asaltiva","fontes de veneno de asaltiva"}},{q="Por que Astranaar quer Vesículas de Peçonha de Asaltiva?",a="Shindrell Fogofugaz recebeu relatos de que agentes da Horda extraem o veneno dos asaltivas para banhar armas usadas em assassinatos silenciosos contra a Aliança. Destruir ou confiscar essas glândulas impede preventivamente esses ataques.",al={"por que coletar vesículas de veneno","veneno de shindrell fogofugaz"}},{q="Quem aceita essas vesículas de peçonha em Vale Gris?",a="Shindrell Fogofugaz, posicionada na cidade elfa noturna de Astranaar, em Vale Gris, coleta-as para proteger seu povo de ataques furtivos.",al={"quem aceita peçonha de asaltiva","entrega de missão de asaltiva"}},{q="Os asaltivas são naturalmente aliados da Horda?",a="Não. Os asaltivas selvagens ao redor do Lago Mirkfallon são feras que não ajudam a Horda de bom grado, embora agentes orcs explorem sua biologia peçonhenta em benefício de sua própria guerra.",al={"os asaltivas são da horda","os asaltivas trabalham para os orcs"}}},fx={e2bba8d5={q="O que é uma Vesícula de Peçonha de Asaltiva?",a="Uma Vesícula de Peçonha de Asaltiva é um órgão colhido das asaltivas que fazem ninho na Cordilheira das Torres de Pedra. Ela contém as toxinas naturais potentes que esses predadores alados produzem para subjugar suas presas. No frágil impasse entre os elfos noturnos e a Horda, tal veneno tornou-se uma arma valiosa para ataques secretos, levando os defensores de Astranaar a ficar atentos.",al={"o que é vesícula de peçonha de asaltiva","item vesícula de peçonha de asaltiva","o que são vesículas de peçonha de asaltiva"}},["816b56c2"]={q="De onde vem uma Vesícula de Peçonha de Asaltiva?",a="Essas vesículas são colhidas diretamente dos corpos das asaltivas — ferozes serpes selvagens que se empoleiram perto do Lago Mirkfallon na Cordilheira das Torres de Pedra. Como são órgãos corporais naturais produzidos pelas próprias bestas, e não produtos manufaturados, obtê-los exige caçar as serpes pelos rochedos e garantir o veneno antes que os agentes da Horda possam coletá-lo.",al={"fonte de vesícula de peçonha de asaltiva","de onde vêm as vesículas de peçonha de asaltiva","quem deixa cair vesícula de peçonha de asaltiva"}}},fp="19,193,21.446.0,43.97.0,45.181.0,42.133.0,51.133.0"}
P.entries["item:prismatic-punch-card"] = {n="Cartão Perfurado Prismático",s="O Cartão Perfurado Prismático é o cartão de dados com o nível de segurança mais alto encontrado na cidade caída de Gnomeregan. Aprimorado sequencialmente por meio de uma série de terminais de Perfuratriz Matricial, ele contém dados desesperadamente buscados pelos refugiados gnomos em Altaforja.",h="O Cartão Perfurado Prismático é o cartão de dados com o nível de segurança mais alto encontrado na cidade...",kw={"fundecano","data rescue","engineering labs","gnomeregan","perfuratriz matricial","cartão perfurado prismático"},ang={["profession:Engineering"]="A programação sequencial de cartões perfurados e a rede de terminais automatizados demonstram o alto padrão de maquinaria de computação construída pelos inventores de Gnomeregan.",["race:Gnome"]="O elaborado sistema de segurança de Perfuratriz é um excelente exemplo da engenhosidade e burocracia gnomica que sobreviveram intactas mesmo após a queda de seu lar."},sec={{t="Uma Questão de Segurança",b="Quando os gnomos fugiram da invasão trogg e da irradiação tóxica de Gnomeregan, enormes tesouros de pesquisas e registros civis foram abandonados nas profundezas. Para proteger sistemas de alto nível, os gnomos utilizaram um protocolo de segurança escalonado. Acessar o terminal de Perfuratriz Matricial 3005-D nos Engineering Labs inferiores requer trabalhar através de uma progressão de cartões perfurados: começando de um Cartão Perfurado Branco básico e avançando pelas liberações Amarela, Azul e Vermelha em terminais dedicados antes de perfurar o Cartão Perfurado Prismático final. Seu nível de liberação codificado é notado de forma extravagante como pendente da invenção de um número totalmente novo."},{t="A Transmissão Vital",b="O Mestre Mecânico Fundecano, agora estacionado entre os enclaves de refugiados em Altaforja, envia bravos aventureiros de volta aos salões contaminados de Gnomeregan em uma missão de salvamento de dados críticos. Embora Fundecano descreva os dados de destino como extremamente vitais e impossíveis de viver sem, a mensagem binária decodificada perfurada no cartão prismático final revela uma verdade divertida da vida civil gnomica cotidiana: uma notificação automatizada informando Fundecano que sua roupa de lavar está pronta para retirada."}},faq={{q="Como você cria um Cartão Perfurado Prismático?",a="Você obtém um Cartão Perfurado Prismático inserindo um Cartão Perfurado Vermelho em um terminal de Perfuratriz Matricial 3005-D localizado no nível inferior dos Engineering Labs em Gnomeregan. Chegar a esse estágio requer aprimorar um Cartão Perfurado Branco inicial sequencialmente através dos terminais modelo A, B e C por todo o complexo.",al={"como conseguir o cartão perfurado prismático","fazer cartão perfurado prismático","sequência de aprimoramento de cartão perfurado"}},{q="Quais dados estão armazenados no Cartão Perfurado Prismático?",a="O cartão declara que sua classificação de segurança é tão alta que está pendente da invenção de um novo número, seguido por uma longa sequência de código binário. O Mestre Mecânico Fundecano insiste que os dados são de vital importância.",al={"o que o cartão diz","tradução binária de cartão perfurado","cartão perfurado decodificado"}},{q="Quem quer o Cartão Perfurado Prismático?",a="O Mestre Mecânico Fundecano, um engenheiro gnomo exilado residindo em Altaforja, solicita o cartão durante a missão Data Rescue. Ele considera o conteúdo do cartão como informações urgentes e inestimáveis deixadas para trás durante a evacuação de Gnomeregan.",al={"quem recebe o cartão perfurado prismático","missão do fundecano","quem precisa do cartão"}},{q="Onde estão localizados os terminais da Perfuratriz Matricial?",a="Os terminais estão espalhados por toda Gnomeregan com base no nível de liberação. A Perfuratriz 3005-A é encontrada perto do Train Depot da superfície e da entrada do Workshop, o modelo B está localizado no Dormitório além da Clean Zone, o modelo C fica mais fundo dentro do complexo, e o modelo D fica nos Engineering Labs inferiores.",al={"localizações dos terminais","onde estão as perfuratrizes","onde perfurar cartões"}}},fx={f4168582={q="O que é um Cartão Perfurado Prismático?",a="Um Cartão Perfurado Prismático é um cartão de dados de nível de acesso extraordinariamente alto gerado pelos sistemas computacionais dentro de Gnomeregan. Sua classificação de segurança automatizada é supostamente tão elevada que a matemática gnomica ainda não inventou um número adequado para descrevê-la. Na verdade, ele contém texto binário codificado produzido por terminais da cidade profunda, funcionando como o ápice do protocolo de recuperação de dados em camadas dos gnomos.",al={"o que é cartão perfurado prismático","folclore cartão perfurado prismático","cartão prismático gnomeregan"}},["7551673e"]={q="De onde vem o Cartão Perfurado Prismático e quem o fez?",a="O cartão é produzido nas profundezas da cidade caída de Gnomeregan pelo Matrix Punchograph 3005-D, um terminal automatizado de alta segurança encontrado no nível inferior da Engineering Labs. Ele não é feito à mão por uma pessoa, mas sim codificado pela rede mecanizada dos gnomos quando um usuário insere um Cartão Perfurado Vermelho devidamente atualizado no aparelho.",al={"origem do cartão perfurado prismático","quem fez o cartão perfurado prismático","onde conseguir cartão perfurado prismático"}}},fp="20,134,20.538.0,22.316.1,41.204.0,48.169.1,35.200.0,51.268.0"}
P.entries["item:pristine-crawler-leg"] = {n="Pristine Crawler Leg",s="As Patas de Rastejante Imaculadas vêm dos Spiny Rock Crabs espinhosos ao redor da Ilha Theramore. Morgan Stern precisa delas para apresentar um novo prato que está pesquisando.",h="As Patas de Rastejante Imaculadas vêm dos Spiny Rock Crabs espinhosos ao redor da Ilha Theramore.",kw={"culinária","pata de rastejante","pântano vadeoso","morgan stern","pata de rastejante imaculada","patas de rastejante imaculadas","spiny rock crab","theramore"},ang={["profession:Cooking"]="Como cozinheiro, você entende por que Morgan se importa tanto com a concha quanto com a carne: ambas fazem parte do prato que ele está pesquisando."},sec={{t="Um Pedido de um Chef",b="Morgan Stern está pesquisando um prato na Ilha Theramore, e as patas de rastejante imaculadas são um de seus ingredientes. Ele quer as conchas sem marcas, pois o estado delas importa para a apresentação do prato. Os Spiny Rock Crabs espinhosos rondam as águas a leste da ilha, onde você pode encontrar as patas de que ele precisa."}},faq={{q="Para que servem as Patas de Rastejante Imaculadas?",a="Morgan Stern precisa das Patas de Rastejante Imaculadas como ingrediente de uma nova receita que está pesquisando em Theramore.",al={"para que servem as patas de rastejante","por que patas imaculadas","o que morgan precisa"}},{q="Onde posso encontrar Patas de Rastejante Imaculadas?",a="Os Spiny Rock Crabs nas águas a leste da Ilha Theramore têm Patas de Rastejante Imaculadas.",al={"localização das patas de rastejante","onde encontrar patas de caranguejo","spiny rock crabs"}},{q="Por que as patas precisam estar imaculadas?",a="Morgan quer conchas sem marcas porque elas são essenciais para a apresentação do prato.",al={"por que conchas sem marcas","patas de caranguejo perfeitas","pata de rastejante imaculada"}},{q="Quem quer as patas de rastejante?",a="Morgan Stern, um chef em Theramore, quer as patas para pesquisar sua receita.",al={"patas para morgan stern","quem precisa de patas de caranguejo","chef em theramore"}}},fp="20,156,18.288.0,35.106.0,39.84.0,36.80.0,27.74.0"}
P.entries["item:pristine-spider-silk"] = {n="Seda Pura de Aranha",s="A Seda pura de aranha é um fio excepcionalmente fino coletado dos aracnídeos venenosos da Floresta do Crepúsculo. Magos de Ventobravo encomendam este material raro para tecer vestes duráveis e encantadas, dignas de praticantes reconhecidos das artes arcanas.",h="A Seda pura de aranha é um fio excepcionalmente fino coletado dos aracnídeos venenosos da Floresta do...",kw={"black widow hatchling","carrion recluse","floresta do crepúsculo","veste de mago","seda pura de aranha","sacrário dos teurgos","manoela galante"},ang={["class:Mage"]="Os magos de Ventobravo são enviados diretamente à Floresta do Crepúsculo para coletar esse fio imaculado como um rito de passagem, a fim de obter uma veste condizente com sua crescente estatura arcana.",["profession:Tailoring"]="Colhidos de aracnídeos mortais, esses fios delicados, porém resistentes, representam o ápice dos tecidos naturais usados para tecer trajes mágicos."},sec={{t="Tecendo o Arcano",b="Não é qualquer fio que consegue reter os encantamentos e resistir ao desgaste exigidos por um mago praticante. Embora a seda de aranha comum seja bastante conhecida entre os alfaiates, apenas os fios imaculados obtidos de carrion recluses e filhotes de black widow hatchlings nos bosques sombrios da Floresta do Crepúsculo possuem a resiliência necessária. Os magos do Sacrário dos Teurgos de Ventobravo enviam seus novos adeptos a essas matas perigosas para coletar carretéis intactos, encarregando a mestre alfaiate local Manoela Galante de transformar o material em uma vestimenta adequada para um adepto."}},faq={{q="De onde vem a Seda pura de aranha?",a="Ela é coletada dos aracnídeos à espreita na Floresta do Crepúsculo, especificamente de carrion recluses e black widow hatchlings que nidificam sob a copa sombria.",al={"onde conseguir seda pura de aranha","quem saqueia seda pura de aranha","localização da seda pura de aranha"}},{q="Quem confecciona vestimentas a partir dessa seda?",a="Manoela Galante, uma costureira que atua no Distrito dos Magos de Ventobravo, usa os carretéis recolhidos para confeccionar uma veste refinada em nome do Sacrário dos Teurgos.",al={"quem usa seda pura de aranha","quem transforma seda em vestes","veste de manoela galante"}},{q="Por que os magos exigem essa seda específica?",a="Os magos precisam de vestimentas que reflitam seu crescente domínio arcano. Apenas a seda mais pura e intacta das aranhas mortíferas da Floresta do Crepúsculo oferece a resistência e a qualidade necessárias para a veste de um adepto.",al={"por que seda pura","uso da seda de aranha magica"}}},fx={dfaa8e27={q="O que é a Seda Pura de Aranha?",a="A Seda Pura de Aranha é uma teia imaculada e excepcionalmente fina fiada pelos aracnídeos que assombram a Floresta do Crepúsculo. Diferente das teias comuns e esfarrapadas que se prendem às árvores por toda a floresta sombria, apenas os fios mais puros e sem manchas se qualificam como puras. Alfaiates e magos a valorizam muito por sua qualidade e textura superiores, utilizando-a como o tecido base essencial para a confecção de vestimentas distintas adequadas para magos praticantes.",al={"seda pura de aranha","o que é seda pura","item seda pura"}}},fp="20,108,18.366.0,42.88.0,35.120.0,44.157.0"}
P.entries["item:pristine-tigress-fang"] = {n="Pristine Tigress Fang",s="Uma Presa de Tigresa Imaculada é um espécime que o Clarividente Mok'thardin procura no Acampamento Grom'gol. Seu estado importa para os encantamentos dele em favor da Horda.",h="Uma Presa de Tigresa Imaculada é um espécime que o Clarividente Mok'thardin procura no Acampamento Grom'gol.",kw={"encantamento","presa","grom'gol","ruínas de nizjah","mok'thardin","presa de tigresa imaculada","selva do espinhaço","tigresa"},ang={["faction:Horde"]="Mok'thardin procura a presa e as garras de Shadowmaw para aproveitar a magia da selva para a Horda."},sec={{t="Um espécime perfeito",b="Do outro lado do rio, a sudeste das Ruínas de Nizjah, as Tigresas do Espinhaço rondam a selva. O Clarividente Mok'thardin pede uma presa em estado imaculado, além de garras de Pantera Sombria. Ele diz que seus rituais já deram certo e pretende aproveitar a magia da selva para a Horda."}},faq={{q="Quem quer a Presa de Tigresa Imaculada?",a="O Clarividente Mok'thardin, no Acampamento Grom'gol, quer uma Presa de Tigresa Imaculada para seus encantamentos.",al={"quem quer a presa","presa de mok'thardin","presa para quem"}},{q="Por que a presa precisa estar imaculada?",a="Mok'thardin diz que, para seu trabalho com a magia da selva, só serve uma presa em estado imaculado.",al={"por que imaculada","presa perfeita","estado da presa"}},{q="Onde posso encontrar uma Presa de Tigresa Imaculada?",a="As Tigresas do Espinhaço na Selva do Espinhaço carregam Presas de Tigresa Imaculadas. Mok'thardin aponta para a selva a sudeste das Ruínas de Nizjah, do outro lado do rio.",al={"onde encontrar presa","localização da presa de tigresa","presa de tigresa"}},{q="De que mais Mok'thardin precisa?",a="Mok'thardin também pede oito Garras de Shadowmaw junto com a Presa de Tigresa Imaculada.",al={"de que mais ele precisa","garras também","mok'thardin precisa"}},{q="O que Mok'thardin está tentando fazer?",a="Mok'thardin busca aproveitar o poder da magia da selva para a Horda por meio de encantamentos poderosos.",al={"magia de mok'thardin","encantamento da selva","por que ele a quer"}}},fp="21,144,15.292.0,36.94.0,38.96.0,41.153.0,32.84.0,33.105.0"}
P.entries["item:prowler-claws"] = {n="Garras de Predador",s="Garras de Predador são troféus decepados coletados dos predadores da savana que espreitam as planícies castigadas pelo sol dos Sertões. Levadas a Sergra Espinhonegro na Encruzilhada, elas servem como prova tangível de que um caçador pode rastrear e subjugar os predadores furtivos mais letais de Kalimdor.",h="Garras de Predador são troféus decepados coletados dos predadores da savana que espreitam as planícies...",kw={"sertões","encruzilhada","garras de predador","predadores dos sertões","savannah prowler","sergra espinhonegro"},ang={["class:Hunter"]="Abater predadores da savana e reivindicar suas garras é um rito de passagem essencial para jovens caçadores que buscam aprender a arte da furtividade, rastreamento e combate corpo a corpo contra feras.",["faction:Horde"]="O abate de predadores perigosos ao redor da Encruzilhada ajuda a proteger mensageiros, caravanas e colonos da Horda que atravessam as estradas centrais perigosas de Kalimdor."},sec={{t="Troféus do Espreitador",b="A vegetação alta dos Sertões oculta os Savannah Prowlers, grandes felinos predadores conhecidos por sua paciência, astúcia e ataques letais. Caçá-los é uma importante prova de fogo para guerreiros e batedores em ascensão da Horda. Diferente de presas herbívoras como o plainstrider ou as zevras, os predadores emboscam ativamente qualquer um que adentre seus territórios de caça. Arrancar suas garras afiadas e curvas exige superar uma criatura que depende de furtividade absoluta e agressividade territorial, provando à caçadora do acampamento que o perseguidor se tornou a caça."},{t="Prova para a Caçadora",b="Na Encruzilhada, Sergra Espinhonegro exige essas garras para avaliar a preparação de um iniciado para provações maiores. Trazer de volta um punhado de garras demonstra que um caçador dominou o rastreamento em meio à relva dourada da savana e consegue resistir a garras capazes de dilacerar couro e carne. Aqueles que retornam com seu troféu mostram que possuem a percepção necessária para sobreviver a feras ainda mais mortíferas que espreitam pelas planícies."}},faq={{q="Onde obtenho Garras de Predador?",a="Garras de Predador são obtidas de Savannah Prowlers, que vagam pelos campos em toda a região central dos Sertões, em especial nas planícies a sudoeste da Encruzilhada.",al={"localização de garras de predador","como obter garras de predador","onde encontrar garras de predador"}},{q="Quem quer essas garras e por quê?",a="Sergra Espinhonegro, uma caçadora experiente estabelecida na Encruzilhada, pede aos caçadores que lhe tragam sete Garras de Predador como um teste de sua proeza de combate e rastreamento contra predadores perigosos.",al={"quem precisa de garras de predador","entregar garras de predador","missão de garras de sergra"}},{q="Por que os Savannah Prowlers são considerados uma caçada expressiva?",a="Diferente dos rebanhos pastadores dos Sertões, os predadores são carnívoros furtivos que perseguem ativamente viajantes e presas a partir de posições ocultas na vegetação densa. Caçá-los testa a capacidade de um aventureiro de evitar emboscadas e derrotar uma fera letal e astuta.",al={"por que caçar predadores","predadores perigosos"}}},fx={["551eb0e2"]={q="O que são Garras de Predador?",a="Garras de Predador são as garras afiadas tiradas das patas dos predadores da savana, os felinos predadores mortais que espreitam a grama alta da savana nos Sertões. Para os caçadores da Encruzilhada, levar esses troféus prova que você pode rastrear e superar uma besta astuta e letal sem se tornar a presa.",al={"o que são garras de predador","item garras de predador","sobre garras de predador"}},c8bad4fe={q="De onde vêm as Garras de Predador?",a="Essas garras vêm diretamente dos predadores da savana que vagam pelas planícies dos Sertões, particularmente nas pastagens a sudoeste da Encruzilhada. Elas são troféus naturais colhidos das carcaças dos grandes felinos por caçadores habilidosos o suficiente para derrubá-los.",al={"de onde vêm as garras de predador","fonte de garras de predador","como conseguir garras de predador"}}},fp="13,154,23.425.0,22.323.0,29.143.0,30.170.0,56.179.0"}
P.entries["item:pulsing-blue-shard"] = {n="Pulsing Blue Shard",s="Pulsing Blue Shards são cristais raros encontrados em Ironjaw Basilisks na Selva do Espinhaço. Kin'weelay precisa da magia deles para controlar o Olho da Mente.",h="Pulsing Blue Shards são cristais raros encontrados em Ironjaw Basilisks na Selva do Espinhaço.",kw={"fragmentos azuis","mina veia de cristal","ironjaw basilisk","kin'weelay","olho da mente","pulsing blue shard","selva do espinhaço","yennikan"},sec={{t="Um Cristal Cantante",b="Kin'weelay, um troll no Acampamento Grom'gol, pede que você traga Pulsing Blue Shards de Ironjaw Basilisks na Mina Veia de Cristal. Ele precisa da magia deles para o Olho da Mente, uma joia que, dizem, guarda grande poder."}},faq={{q="O que são Pulsing Blue Shards?",a="Pulsing Blue Shards são cristais raros encontrados em Ironjaw Basilisks na Selva do Espinhaço. A magia deles pode ajudar Kin'weelay a controlar o Olho da Mente.",al={"fragmento azul","cristal pulsante"}},{q="Quem precisa dos fragmentos?",a="Kin'weelay, no Acampamento Grom'gol, precisa de Pulsing Blue Shards para seu trabalho com o Olho da Mente.",al={"quem quer fragmentos azuis","fragmentos de kin'weelay"}},{q="De onde vêm os fragmentos?",a="Ironjaw Basilisks na Mina Veia de Cristal fornecem Pulsing Blue Shards.",al={"onde conseguir fragmentos","fragmentos da mina veia de cristal"}},{q="O que é o Olho da Mente?",a="O Olho da Mente é uma joia escondida nas profundezas da Selva do Espinhaço, que, dizem, guarda grande poder. Kin'weelay acredita que os fragmentos podem ajudá-lo a dominar a magia da joia.",al={"olho da mente","cristais cantantes"}},{q="Por que Kin'weelay os quer?",a="Kin'weelay precisa da magia dos fragmentos para controlar o Olho da Mente, que espera usar para trazer Yennikan de volta da escuridão.",al={"por que os fragmentos","para que servem os fragmentos"}}},fp="18,145,17.203.0,29.145.0,21.92.0,30.64.0,23.158.0,30.124.1"}
P.entries["item:pupellyverbos-port"] = {n="Xerez de Pupellyverbos",s="Uma caixa de Xerez de Pupellyverbos caiu no mar perto das Terras Agrestes durante uma tempestade. Aldo Isque, em Angra do Butim, precisa recuperar as garrafas antes que o capitão descubra que elas sumiram.",h="Uma caixa de Xerez de Pupellyverbos caiu no mar perto das Terras Agrestes durante uma tempestade.",kw={"angra do butim","terras agrestes","grogue perdido","penhascos do mirante","corsário","xerez de pupellyverbos","tempestade","aldo isque"},sec={{t="Perdido no mar",b="Uma tempestade atingiu o navio que levava Xerez de Pupellyverbos para Ventobravo, junto aos penhascos do Mirante. O capitão havia tomado a caixa de um corsário, e Aldo Isque a abriu para ganhar coragem quando as ondas cresceram. Uma onda enorme arrastou as garrafas para o mar. Agora, o grogue está espalhado pela costa, e Isque teme a fúria do capitão."}},faq={{q="O que é o Xerez de Pupellyverbos?",a="Xerez de Pupellyverbos é um grogue transportado em uma caixa a bordo de um navio com destino a Ventobravo.",al={"xerez de pupellyverbos","que bebida é essa","bebida de pupellyverbos"}},{q="Como as garrafas se perderam?",a="Uma tempestade perto dos penhascos do Mirante lançou uma onda enorme sobre o navio e arrastou as garrafas para o mar.",al={"para onde foram as garrafas","como o xerez se perdeu","o que aconteceu com o grogue"}},{q="Quem está procurando o xerez?",a="Aldo Isque, em Angra do Butim, quer as garrafas perdidas de volta antes que o capitão descubra que elas sumiram.",al={"quem quer a bebida","garrafas de aldo isque","grogue de isque"}},{q="De onde veio a caixa?",a="A tripulação do capitão tomou a caixa de um corsário que viajava para Ventobravo.",al={"quem estava com a caixa","origem do xerez","bebida do corsário"}}},fp="18,177,11.329.0,27.82.0,29.100.0,28.101.0,30.86.0"}
P.entries["item:pure-hearts"] = {n="Corações Puros",s="Corações Puros são reagentes rituais fornecidos a bruxos Renegados por Silvério Hidalgo na Cidade Baixa. Eles são usados para atrair e manifestar uma súcubo através do Twisting Nether para que o praticante possa derrotar e aprisionar o demônio.",h="Corações Puros são reagentes rituais fornecidos a bruxos Renegados por Silvério Hidalgo na Cidade Baixa.",kw={"silvério hidalgo","distrito da magia","corações puros","súcubo","evocação","the binding","cidade baixa"},ang={["class:Warlock"]="Para os bruxos Renegados, obter e usar esses corações representa um marco crucial na demonologia: provar a própria força mental contra as tentações sedutoras do Twisting Nether.",["race:Undead"]="Em meio à podridão e à praga da Cidade Baixa, usar corações puramente imaculados para manipular os apetites demoníacos exemplifica a feitiçaria fria e pragmática praticada pelos Renegados."},sec={{t="Isca para o Nether",b="A demonologia se baseia na exploração de desejos vis e vulnerabilidades espirituais. Para evocar uma súcubo no Distrito da Magia da Cidade Baixa, Silvério Hidalgo fornece Corações Puros aos bruxos. Quando colocadas sobre o círculo de evocação, essas essências espirituais imaculadas agem como uma isca potente, atraindo o demônio sedutor através do Twisting Nether para o reino mortal. Assim que o demônio se manifesta, o bruxo deve resistir aos seus fascinantes encantos mentais e derrubá-la em combate. Superar a súcubo afirma o domínio místico, banindo-a de volta para o Twisting Nether até que Silvério ensine ao bruxo o feitiço para evocá-la à vontade."}},faq={{q="Para que servem os Corações Puros?",a="Eles servem como o catalisador místico usado no círculo de evocação no Distrito da Magia da Cidade Baixa para atrair e manifestar uma súcubo através do caos, permitindo que um bruxo lute contra ela e a aprisione.",al={"uso dos corações puros","por que corações puros","o que fazem os corações puros"}},{q="Quem fornece os Corações Puros?",a="Silvério Hidalgo, o instrutor de bruxos Renegados localizado no Distrito da Magia sob as Ruínas de Lordaeron, os entrega a aspirantes a praticantes prontos para dominar a evocação de uma súcubo.",al={"quem dá os corações puros","quem dá a missão dos corações puros"}},{q="Por que uma súcubo responde aos Corações Puros?",a="As súcubos prosperam com a corrupção, a sedução e a corrupção da inocência. O resplendor de corações puros e imaculados é uma isca irresistível através do Twisting Nether, atraindo-as diretamente para o círculo de evocação preparado pelo bruxo.",al={"por que a súcubo quer corações puros","história dos corações puros"}},{q="Você fica com os Corações Puros após o ritual?",a="Não. Assim que a súcubo é evocada e subjugada, os restos dos Corações Puros são devolvidos a Silvério Hidalgo como prova da conclusão do teste de aprisionamento.",al={"fico com os corações puros","o que acontece com os corações puros"}}},fx={["105bfa16"]={q="O que são os Corações Puros?",a="Os Corações Puros são componentes rituais potentes usados por bruxos Renegados na Cidade Baixa. Quando lançados sobre um círculo de invocação, sua essência não contaminada atua como uma isca através do Nether Torcido, abrindo uma fenda projetada especificamente para atrair e invocar uma súcubo perigosa para a sua presença.",al={"o que são corações puros","item corações puros","corações puros bruxo"}},["3abadf0f"]={q="Por que alguém desejaria os Corações Puros?",a="Um aspirante a bruxo precisa dos Corações Puros para completar o perigoso ritual de ligação de uma súcubo. Sem oferecer tal isca imaculada para transpor o vazio, não se pode atrair o demônio para o reino mortal para subjugá-la e dominar a arte de invocá-la sob seu comando.",al={"por que querer corações puros","propósito dos corações puros","por que os corações puros são procurados"}}},fp="11,206,19.499.0,34.183.0,29.123.0,43.149.0,52.151.0"}
P.entries["item:purified-kor-gem"] = {n="Gema de Kor Purificada",s="A Gema de Kor Purificada é um cristal raro e consagrado exigido pelo armeiro Jardel Calmafonte nos arredores de Altaforja. Antes corrompida por energias sombrias, ela deve ser recuperada das profundezas de Kalimdor e purificada pela magia élfica antes de poder ser forjada em uma arma sagrada da Luz.",h="A Gema de Kor Purificada é um cristal raro e consagrado exigido pelo armeiro Jardel Calmafonte nos arredores...",kw={"auberdine","profundezas negras","gema kor corrompida","dun morogh","jardel calmafonte","gema de kor purificada","a prova da retidao","trovejius tecevento"},ang={["class:Paladin"]="Adquirir e purificar esta gema comprova a devoção de um paladino, levando-o das profundezas de Kalimdor de volta a Dun Morogh para forjar uma arma emblemática da Luz.",["faction:Alliance"]="Conseguir a gema purificada une esforços por toda a Aliança, contando com a sabedoria dos elfos noturnos em Auberdine para fortalecer um ferreiro humano trabalhando nas encostas de Dun Morogh."},sec={{t="Da Corrupção à Santidade",b="A pedra começa sua jornada como uma Gema Kor Corrompida nas mãos das vis nagas que espreitam nas Profundezas Negras, bem abaixo da costa do Vale Gris. Para purificar a pedra de sua mácula aquática e sombria, um paladino deve procurar o elfo noturno Trovejius Tecevento em Auberdine. Recorrendo a artes arcanas e naturais, Trovejius expurga a corrupção da pedra, transformando-a na radiante Gema de Kor Purificada. Apenas nesse estado imaculado ela se torna digna de servir como canalizadora do poder sagrado."},{t="A Obra-prima do Ferreiro",b="Nos arredores de Altaforja, nos penhascos nevados de Dun Morogh, o armeiro humano Jardel Calmafonte precisa da gema como um componente fundamental para forjar uma arma magistral. Tendo durante muito tempo projetos de um armamento digno do Punho de Prata, Calmafonte carecia dos materiais exóticos para concretizar seus planos. A Gema de Kor Purificada, juntamente com a Madeira de Carvalho de Pedralva e um minério raro, fornece o núcleo espiritual necessário para canalizar a ira justa do paladino."}},faq={{q="Para que serve a Gema de Kor Purificada?",a="Ela é levada ao ferreiro Jardel Calmafonte, localizado do lado de fora dos Portões de Altaforja em Dun Morogh. Calmafonte utiliza a gema santificada como componente essencial para forjar uma arma consagrada para um paladino que esteja enfrentando suas provações.",al={"uso da gema de kor purificada","por que preciso da gema de kor","para que serve a gema de kor"}},{q="De onde se origina a gema?",a="A pedra tem origem nas ruínas subterrâneas das Profundezas Negras, ao longo da costa do Vale Gris, onde é mantida pelas nagas como um artefato corrompido.",al={"origem da gema de kor","onde cai a gema de kor","quem saqueia a gema de kor"}},{q="Quem purifica a gema?",a="Trovejius Tecevento, um erudito élfico que reside no assentamento costeiro de Auberdine em Costa Negra, purifica as energias sombrias da Gema Kor Corrompida, restaurando-a ao seu estado purificado.",al={"como purificar a gema de kor","quem purifica a gema de kor","trovejius tecevento gema de kor"}},{q="Qualquer aventureiro pode usar a Gema de Kor Purificada?",a="A gema é procurada especificamente por paladinos que realizam A prova da retidão. Jardel Calmafonte reserva seu ofício para os guerreiros sagrados que lhe trouxerem o cristal purificado juntamente com outros materiais raros.",al={"gema de kor e so para paladino","qualquer um pode usar a gema de kor purificada"}}},fx={a30b14db={q="O que é uma Gema de Kor Purificada?",a="A Gema de Kor Purificada é um componente mineral raro e santificado, limpo de contaminação imunda. Originalmente recuperada como uma pedra corrompida mantida pelos naga nas Profundezas Negras, ela foi minuciosamente limpa de sua influência sombria por Thundris Windweaver em Auberdine, para que suas propriedades latentes possam ser aproveitadas com segurança em trabalhos sagrados.",al={"o que é gema de kor purificada","significado da gema de kor purificada","informações sobre gema de kor purificada"}}},fp="16,161,27.299.0,23.338.0,38.161.0,29.83.0,21.114.0,52.161.0"}
P.entries["item:putrid-claw"] = {n="Garra Pútrida",s="Garras Pútridas são as mãos em decomposição decepadas de mortos-vivos irracionais que rondam os bosques a oeste de Montalvo. O Necroguarda Dinis as recolhe como prova definitiva de que a ameaça invasora do Flagelo perto da velha ponte está sendo contida.",h="Garras Pútridas são as mãos em decomposição decepadas de mortos-vivos irracionais que rondam os bosques a...",kw={"uma tarefa podre","montalvo","necroguarda dinis","garra pútrida","cadáver devastado","morto apodrecido","flagelo","clareiras de tirisfal"},ang={["race:Undead"]="Para os novos iniciados Renegados que partem de Plangemortis, eliminar esse Flagelo irracional é um lembrete inicial de que a libertação exige defesa constante contra as carcaças irracionais com as quais eles outrora se pareciam."},sec={{t="Troféu dos Irracionais",b="Mesmo em sua própria terra natal, os Renegados não estão totalmente a salvo do alcance do Lich Rei. Bolsões do Flagelo irracional — mortos apodrecidos e cadáveres devastados — costumam cruzar as fronteiras orientais em direção às Clareiras de Tirisfal, aglomerando-se pelas estradas e perto da velha ponte a oeste de Montalvo. Para garantir a segurança dos viajantes e as linhas de suprimento da guarnição, os Necroguardas oferecem recompensas por esses horrores errantes. Uma garra pútrida decepada serve como evidência física inconfundível de que mais um cadáver cambaleante foi eliminado de vez."}},faq={{q="Para que servem as garras pútridas?",a="O Necroguarda Dinis, estacionado em Montalvo, recolhe-as como recompensas para confirmar que os recrutas Renegados locais estão reduzindo o Flagelo que vaga pelas Clareiras de Tirisfal.",al={"uso da garra pútrida","por que coletar garras pútridas","quem quer garras pútridas"}},{q="De onde vêm as garras pútridas?",a="Elas são recolhidas dos mortos apodrecidos e cadáveres devastados que vagam pelos bosques assombrados a oeste de Montalvo, especialmente perto da velha ponte do rio.",al={"onde conseguir garras pútridas","saques de garra pútrida","saques de morto apodrecido"}},{q="Por que o Flagelo está nas Clareiras de Tirisfal?",a="Após a devastação de Lordaeron, remanescentes do Flagelo irracional do Lich Rei infiltram-se continuamente a oeste pelas fronteiras de Tirisfal, ameaçando estradas e assentamentos, a menos que sejam ativamente eliminados.",al={"por que há zumbis perto de montalvo","flagelo em tirisfal"}},{q="Por que os Renegados simplesmente não deixam os mortos-vivos irracionais vagarem?",a="Ao contrário dos Renegados, que se libertaram sob o comando da Rainha Sylvana e recuperaram seu livre-arbítrio, o Flagelo irracional obedece apenas a instintos sombrios ou às ordens remanescentes do Lich Rei, atacando qualquer ser vivo ou morto-vivo livre à primeira vista.",al={"renegados versus zumbis irracionais","por que matar outros mortos-vivos"}}},fx={["37750c4d"]={q="O que é uma Garra Pútrida?",a="Uma Garra Pútrida é a mão decepada e apodrecida de um zumbi irracional pertencente ao Flagelo. Esses apêndices em decomposição são tirados dos cadáveres ambulantes que assombram as Clareiras de Tirisfal como prova de sua destruição.",al={"o que é garra pútrida","informações sobre garras pútridas","folclore da garra pútrida"}}},fp="11,191,22.354.0,31.155.0,32.140.0,38.170.0,59.205.0"}
P.entries["item:pyrewood-shackle"] = {n="Grilha de Lenhardente",s="Grilhões de Lenhardente são restrições encantadas usadas pelos habitantes atribulados do Vilarejo Lenhardente, no sul da Floresta de Pinhaprata. Imbuídos com a magia estranha do Arquimago Arugal, esses braceletes misteriosos parecem desempenhar um papel no destino sombrio que se abate sobre os aldeões quando a noite cai sobre o povoado.",h="Grilhões de Lenhardente são restrições encantadas usadas pelos habitantes atribulados do Vilarejo...",kw={"arugal","tessalba","moonrage","lenhardente","o sepulcro","grilhão","floresta de pinhaprata","worgen"},ang={["class:Mage"]="Magos que estudam a obra de Arugal reconhecerão a aplicação imprudente de magia de transmutação e vinculação entrelaçada ao aço comum.",["race:Undead"]="Eruditos Renegados n'O Sepulcro veem a feitiçaria desenfreada de Arugal como uma grande ameaça às suas fronteiras, tornando a coleta dessas amarras encantadas crucial para neutralizar a influência da Bastilha da Presa Negra."},sec={{t="A Magia Vinculadora de Arugal",b="O amaldiçoado Vilarejo Lenhardente guarda um segredo perturbador: de dia, seus residentes levam vidas normais parecendo humanos comuns, mas o pôr do sol os transforma em ferozes worgens Moonrage. O Arquimago Arugal prendeu esses aldeões em grilhões encantados como parte de seus experimentos distorcidos com feitiçaria worgen. Dalar Tessalba, um pesquisador arcano estabelecido n'O Sepulcro a serviço dos Renegados, estuda esses grilhões para decifrar os encantamentos que sustentam essa existência dual. Ao reunir e analisar a energia residual nas braçadeiras, Tessalba busca uma compreensão mais profunda da magia de Arugal, na esperança de desfazer o domínio do arquimago louco sobre a região."}},faq={{q="Para que servem os Grilhões de Lenhardente?",a="Dalar Tessalba, n'O Sepulcro, solicita esses grilhões para estudar seus encantamentos. Ao drenar sua magia, ele espera desvendar os feitiços do Arquimago Arugal e encontrar uma maneira de desmantelar a influência do arquimago na Floresta de Pinhaprata.",al={"uso de grilhões de lenhardente","por que coletar grilhões","grilhões de dalar tessalba"}},{q="Quem carrega esses grilhões?",a="Os grilhões são carregados pelos residentes amaldiçoados do Vilarejo Lenhardente, no sul da Floresta de Pinhaprata, usados durante seu disfarce humano durante o dia e em sua transformação noturna em worgens Moonrage.",al={"quem saqueia grilhões de lenhardente","fonte dos grilhões","onde encontrar grilhões de lenhardente"}},{q="Por que os aldeões se transformam à noite?",a="O Arquimago Arugal submeteu a população de Lenhardente a experimentos mágicos e encantamentos imprudentes. Os grilhões mantêm um encantamento que lhes permite parecer humanos comuns durante a luz do dia, apenas para revelar suas formas ferozes de worgen quando a escuridão cai.",al={"por que lenhardente se transforma em worgen","maldição do vilarejo lenhardente","segredo do lobisomem de lenhardente"}},{q="Quem é Dalar Tessalba?",a="Dalar Tessalba é um mago Renegado que reside n'O Sepulcro, na Floresta de Pinhaprata. Ele estuda ativamente as anomalias arcanas deixadas para trás pelo Arquimago Arugal, concentrando-se em dissecar e quebrar as maldições distorcidas do arquimago.",al={"dalar tessalba","quem é dalar"}}},fx={b92f5faa={q="O que é uma Grilha de Lenhardente?",a="Uma Grilha de Lenhardente é um grilhão encantado preso aos infelizes habitantes do Vilarejo Lenhardente, no sul da Floresta de Pinhaprata. Imbuídas com a estranha e imprudente feitiçaria do mago louco Arquimago Arugal, essas grilhas desempenham um papel direto em prender os habitantes da cidade à sua vontade e ocultar a maldição sombria que os aflige.",al={"grilha de lenhardente","o que são grilhas de lenhardente","grilhas de lenhardente"}},f6bcbb50={q="De onde vem uma Grilha de Lenhardente e quem a fez?",a="Esses grilhões encantados foram forjados e colocados nos aldeões pelo Arquimago Arugal, o mago renegado de Dalaran que se estabeleceu na Bastilha da Presa Negra. Arugal lançou as grilhas nos camponeses de Lenhardente como parte de seus encantamentos distorcidos, mantendo-os sob seu domínio enquanto escondia sua transformação lupina sob uma ilusão diurna de vida humana comum.",al={"quem fez as grilhas de lenhardente","origem da grilha de lenhardente","de onde vêm as grilhas"}},["98d012f7"]={q="Por que alguém quer as Grilhas de Lenhardente?",a="Dalar Tessalba, um ambicioso mago Renegado que conduz pesquisas n'O Sepulcro, busca esses grilhões encantados para estudar a magia de Arugal. Ao drenar sua energia residual, Dalar espera desvendar o bizarro encantamento que faz com que os aldeões pareçam humanos de dia e se transformem em vorazes worgen Luar-furioso após o anoitecer, buscando, em última análise, desmantelar os feitiços de Arugal.",al={"por que coletar grilhas de lenhardente","quem precisa de grilhas de lenhardente","propósito da grilha de lenhardente"}}},fp="16,141,22.410.1,36.176.0,27.155.1,40.234.1,24.167.0"}
P.entries["item:quinn-s-potion"] = {n="Poção de Quinn",s="A Poção de Quinn é uma mistura revigorante preparada pelo Boticário Renferrel n'O Sepulcro. Ela é fabricada para estabilizar e revitalizar o Deathstalker Quintino Yorick ferido após uma desastrosa patrulha de reconhecimento na Floresta de Pinhaprata.",h="A Poção de Quinn é uma mistura revigorante preparada pelo Boticário Renferrel n'O Sepulcro.",kw={"boticário renferrel","deathstalker","plantação do ivar","quintino yorick","poção de quinn","o sepulcro","floresta de pinhaprata"},ang={["race:Undead"]="A Real Sociedade de Boticários raramente gasta esforços em remédios de campo simples, a menos que isso preserve diretamente os batedores Renegados vitais para proteger as fronteiras da Floresta de Pinhaprata."},sec={{t="Cura de Renferrel",b="Depois que o Deathstalker Quintino Yorick foi severamente espancado e incapacitado perto da Plantação do Ivar, a notícia chegou à Real Sociedade de Boticários n'O Sepulcro. O Boticário Renferrel preparou às pressas esta poção especializada para facilitar a recuperação de Quintino. Embora Renferrel raramente deixe que baixas menores em campo o distraiam de suas pesquisas mais grandiosas e sinistras para Lady Sylvanas, ele forneceu o tônico restaurador para colocar o batedor ferido de volta de pé e capaz de viajar."}},faq={{q="Para que serve a Poção de Quinn?",a="A poção é formulada para ajudar na recuperação do Deathstalker Quintino Yorick, que se encontra ferido nos bosques do norte da Floresta de Pinhaprata. Bebê-la restaura sua vitalidade o suficiente para permitir que ele viaje novamente.",al={"propósito da poção de quinn","o que a poção de quinn faz","por que preparar a poção de quinn"}},{q="Quem preparou esta poção?",a="O Boticário Renferrel, um alquimista da Real Sociedade de Boticários instalado nas criptas d'O Sepulcro, preparou a poção.",al={"quem fez a poção de quinn","quem preparou","poção de renferrel"}},{q="Onde a poção precisa ser entregue?",a="Ela deve ser levada ao norte d'O Sepulcro para Quintino Yorick, que está abrigado perto da propriedade agrícola conhecida como Plantação do Ivar.",al={"onde levar a poção","localização de quinn","local de quintino yorick"}},{q="Por que Quintino Yorick precisava de uma poção?",a="Quintino fazia parte de uma patrulha de Deathstalkers que explorava o norte da Floresta de Pinhaprata. Na Plantação do Ivar, os batedores foram atacados pelo carniçal Ivar the Foul, e Quintino ficou gravemente ferido e isolado lá.",al={"por que quinn está ferido","o que aconteceu com quintino yorick","quinn ferido"}}},fx={["52098f03"]={q="O que é a Poção de Quinn?",a="É uma poção restauradora preparada pelo Boticário Renferrel n'O Sepulcro. Formulada especificamente para ajudar o batedor ferido Quintino Yorick, a bebida fornece a força de que ele precisa para se recuperar de seus ferimentos e recuperar mobilidade suficiente para viajar.",al={"poção de quinn","o que é esta poção","o que é a poção de quinn"}}},fp="14,154,16.415.0,32.156.0,23.123.0,43.109.0,41.169.0"}
P.entries["item:rackmore-s-golden-key"] = {n="Rackmore's Golden Key",s="Na Ilha Ranazjar, Rackmore’s Golden Key ajuda a abrir o baú onde um marinheiro escondeu seu tesouro. Os Slitherblade naga guardam a chave entre os restos espalhados de sua viagem.",h="Na Ilha Ranazjar, Rackmore’s Golden Key ajuda a abrir o baú onde um marinheiro escondeu seu tesouro.",kw={"desolação","chave dourada","rackmore","rackmore’s golden key","ilha ranazjar","slitherblade naga","tesouro"},sec={{t="O esconderijo de um marinheiro",b="O diário de Rackmore conta como seu navio seguia para o Domínio de Plumaluna quando criaturas marinhas o atacaram. Para proteger seu tesouro, ele escondeu um baú na Ilha Ranazjar. São necessárias duas chaves para abri-lo: uma de prata e uma de ouro. Os Slitherblade naga guardam Rackmore’s Golden Key, e também é preciso encontrar Rackmore’s Silver Key."}},faq={{q="O que Rackmore’s Golden Key abre?",a="Rackmore’s Golden Key abre o baú escondido na Ilha Ranazjar, junto com Rackmore’s Silver Key.",al={"chave dourada","chave de rackmore","para que serve a chave dourada"}},{q="Onde fica o baú do tesouro de Rackmore?",a="Rackmore escondeu seu baú na Ilha Ranazjar depois que criaturas marinhas atacaram seu navio.",al={"localização do baú de rackmore","onde fica o baú","tesouro de ranazjar"}},{q="Quem tem a Chave Dourada?",a="Os Slitherblade naga na Desolação guardam Rackmore’s Golden Key.",al={"quem tem a chave de rackmore","chave naga","chave slitherblade"}},{q="Por que Rackmore escondeu seu tesouro?",a="Rackmore escondeu o baú para proteger seu tesouro das criaturas marinhas que atacaram seu navio.",al={"por que esconder o baú","história do tesouro de rackmore","por que o tesouro está escondido"}}},fp="21,173,18.317.0,39.103.0,37.84.0,23.63.0,35.96.0"}
P.entries["item:rackmore-s-silver-key"] = {n="Rackmore's Silver Key",s="Rackmore’s Silver Key está perdida entre os makrura da Desolação. Ela é procurada por quem busca o tesouro escondido de Rackmore.",h="Rackmore’s Silver Key está perdida entre os makrura da Desolação.",kw={"desolação","drysnap crawler","drysnap pincer","chave dourada","rackmore","rackmore's chest","rackmore’s silver key","ilha ranazjar","chave de prata"},sec={{t="A Chave Perdida",b="O diário de Rackmore conta que seu navio seguia para o Domínio de Plumaluna quando criaturas do mar o atacaram. Para impedir que o tesouro caísse nas mãos dos inimigos, ele escondeu o baú na Ilha Ranazjar. A chave de prata se perdeu, e o baú continua trancado até que ela seja encontrada junto com sua contraparte dourada."}},faq={{q="O que Rackmore’s Silver Key abre?",a="Rackmore’s Silver Key é uma das duas chaves necessárias para abrir Rackmore’s Chest na Ilha Ranazjar. A chave dourada é a outra.",al={"para que serve a chave de prata","o que a chave abre","chave de rackmore"}},{q="Onde posso encontrar Rackmore’s Silver Key?",a="Drysnap Pincers e Drysnap Crawlers na Desolação carregam Rackmore’s Silver Key.",al={"localização da chave de prata","onde fica a chave","encontrar a chave de prata de rackmore"}},{q="Quem foi Rackmore?",a="Rackmore era dono de um baú de tesouro escondido na Ilha Ranazjar depois que seu navio foi atacado.",al={"história de rackmore","quem é rackmore","rackmore"}},{q="Por que o tesouro de Rackmore está escondido?",a="Rackmore escondeu seu baú na Ilha Ranazjar para impedir que o tesouro caísse nas mãos das criaturas que atacaram seu navio.",al={"por que o baú está escondido","por que o tesouro de rackmore está escondido","tesouro escondido"}},{q="O que aconteceu com o navio de Rackmore?",a="O diário de Rackmore diz que criaturas do mar atacaram seu navio enquanto ele navegava em direção ao Domínio de Plumaluna.",al={"navio atacado","navio de rackmore","o que aconteceu com o navio"}}},fp="21,126,12.282.0,39.123.0,41.79.0,17.95.0,36.129.0,35.108.0"}
P.entries["item:rage-scar-yeti-hide"] = {n="Rage Scar Yeti Hide",s="A Rage Scar Yeti Hide vem dos yetis da Bastilha Cortifúria, no norte de Feralas. Pradal McGrubben e Jangdor Passo Veloz procuram as peles para seu trabalho com couro.",h="A Rage Scar Yeti Hide vem dos yetis da Bastilha Cortifúria, no norte de Feralas.",kw={"feralas","jangdor passo veloz","couro","pradal mcgrubben","bastilha cortifúria","rage scar yeti hide","yetis de rage scar","pele de yeti"},sec={{t="Uma pele melhor",b="No norte de Feralas, os yetis da Bastilha Cortifúria fornecem peles muito apreciadas por quem trabalha com couro. Pradal McGrubben, no Domínio de Plumaluna, e Jangdor Passo Veloz, na Aldeia Mojache, procuram dez cada um para seu trabalho. Eles esperam que, depois de curtidas, as peles se mostrem tão resistentes quanto o tório."}},faq={{q="De onde vêm as Rage Scar Yeti Hides?",a="As Rage Scar Yeti Hides vêm dos yetis da Bastilha Cortifúria, no norte de Feralas.",al={"onde conseguir pele de yeti","origem da pele de rage scar"}},{q="Quem quer essas peles?",a="Pradal McGrubben, no Domínio de Plumaluna, e Jangdor Passo Veloz, na Aldeia Mojache, procuram Rage Scar Yeti Hides.",al={"quem precisa das peles","para quem são as peles"}},{q="Por que essas peles são valiosas?",a="Depois de curtida, a pele pode ser excepcionalmente resistente, o que a torna promissora para o trabalho com couro.",al={"por que querem peles de yeti","qualidade da pele"}},{q="Quantas peles são necessárias?",a="Pradal McGrubben e Jangdor Passo Veloz pedem dez Rage Scar Yeti Hides cada um.",al={"quantas","dez peles"}}},fp="19,164,13.267.0,40.80.0,22.114.0,27.93.0,26.79.0"}
P.entries["item:ran-bloodtooth-s-skull"] = {n="Crânio de Ran Dente Sangrento",s="O Crânio de Ran Dente Sangrento é um troféu macabro tirado do chefe dos furbolgs corrompidos no Vale Gris. Levado de volta aos elfos noturnos de Astranaar, ele serve como prova tangível de que uma ameaça feroz ao reino florestal chegou ao fim.",h="O Crânio de Ran Dente Sangrento é um troféu macabro tirado do chefe dos furbolgs corrompidos no Vale Gris.",kw={"vale gris","astranaar","crânio de dente sangrento","dente sangrento","furbolg","raene correlobos","raene's cleansing","ran dente sangrento"},ang={["faction:Alliance"]="Entregar este troféu sombrio prova o valor dos campeões da Aliança na defesa das frágeis fronteiras do Vale Gris ao lado das Sentinelas.",["race:NightElf"]="Para os elfos noturnos, obter o crânio é uma vitória amarga. Embora honre a tarefa inacabada de Teronis, também é um lembrete de quão profundamente a corrupção demoníaca devastou seus antigos aliados furbolgs."},sec={{t="Um Troféu da Defesa do Vale Gris",b="As florestas do Vale Gris sofreram imensamente com a mácula demoníaca e a corrupção da natureza, levando tribos de furbolgs outrora pacíficas a uma loucura assassina. Entre os chefes mais ferozes desses grupos hostis estava Ran Dente Sangrento. Recuperar seu crânio fornece às Sentinelas elfas noturnas uma prova irrefutável de que o bruto caiu, quebrando seu domínio sobre os furbolgs locais e oferecendo um pequeno alívio à sitiada cidade de Astranaar."},{t="Honrando os Caídos",b="Quando apresentado à Sentinela Raene Correlobos em Astranaar, o crânio marca a conclusão de uma investigação desencadeada pelo batedor caído Teronis. Ao lado da Varinha de Dartol — a varinha reconstruída que Teronis havia partido para encontrar —, o crânio de Ran Dente Sangrento é mantido em exibição como testemunho da coragem daqueles que lutaram para preservar a floresta sagrada."}},faq={{q="Quem foi Ran Dente Sangrento?",a="Ran Dente Sangrento era um chefe dos furbolgs corrompidos no Vale Gris, considerado pelas Sentinelas elfas noturnas como uma das ameaças regionais mais ferozes.",al={"quem é ran dente sangrento","história de ran dente sangrento","quem foi dente sangrento"}},{q="Por que as Sentinelas querem o crânio dele?",a="Raene Correlobos, em Astranaar, recebe o crânio como prova da derrota de Ran Dente Sangrento. O crânio é colocado ao lado da Varinha de Dartol como um símbolo de vitória e lembrança daqueles que se perderam defendendo o Vale Gris.",al={"para que preciso do crânio","crânio raene correlobos","para que serve o crânio"}},{q="Quem foi Teronis?",a="Teronis era um velho amigo de Raene Correlobos que ajudava as Sentinelas no Vale Gris. Ele partiu para encontrar uma gema para uma varinha feita pelo falecido mago Dartol, na esperança de que ela pudesse conter os ataques dos furbolgs, mas foi morto por murlocs no Lago Falathim. Sua tarefa foi continuada por Raene Correlobos e aventureiros de passagem.",al={"história de teronis","quem é teronis","teronis astranaar"}}},fx={["4d0a3ce4"]={q="O que é o Crânio de Ran Dente Sangrento?",a="Este é o crânio decepado de Ran Dente Sangrento, uma das ameaças de furbolgs corrompidos mais ferozes e perigosas que rondam Vale Gris. Tomado como prova de sua derrota, ele marca o fim do terror que ele trouxe contra as Sentinelas e a floresta.",al={"crânio de ran dente sangrento","o que é o crânio de ran","cabeça de ran dente sangrento"}},f5c7858d={q="De onde veio o Crânio de Ran Dente Sangrento?",a="O crânio é reivindicado diretamente de Ran Dente Sangrento após matá-lo em Vale Gris. Não é um artefato forjado ou criado por mãos mortais, mas sim o troféu sombrio colhido do próprio chefe.",al={"de onde veio o crânio de ran","quem fez o crânio de ran dente sangrento","fonte do crânio de ran dente sangrento"}}},fp="22,115,31.284.0,19.305.1,23.136.0,36.164.0,16.287.0"}
P.entries["item:ransom-letter"] = {n="Ransom Letter",s="A Carta de Resgate é uma ameaça dos ladrões que estão com o livro de Narain em Tanaris. Suas palavras recortadas e coladas exigem dinheiro e um encontro a sós.",h="A Carta de Resgate é uma ameaça dos ladrões que estão com o livro de Narain em Tanaris.",kw={"gnomo","narain","psíquico","resgate","carta de resgate","bilhete de resgate","livro roubado","tanaris"},ang={["race:Gnome"]="Como gnomo, você talvez reconheça o orgulho de Narain em seus poderes psíquicos. O livro roubado e a ameaça de resgate o deixam furioso."},sec={{t="Uma ameaça recortada",b="O desaparecimento do livro de Narain traz uma exigência de resgate a Tanaris. As palavras da carta foram recortadas de diferentes tipos de letra e coladas em um pergaminho. Ela promete devolver o livro se as exigências forem atendidas e, em seguida, apresenta instruções detalhadas em três páginas. A mensagem termina com uma ordem direta: leve o dinheiro e venha sozinho."},{t="A fúria de Narain",b="Quando Narain lê a carta de resgate, seu rosto fica vermelho como brasa. O gnomo promete ensinar aos sequestradores o que significa mexer com um vidente. O roubo do livro virou motivo de raiva, além de uma questão de pagamento."}},faq={{q="Quem escreveu a carta de resgate?",a="A carta não identifica quem a escreveu. Ela diz que os sequestradores estão com o livro de Narain e exige dinheiro em troca.",al={"autor da carta","quem enviou a carta","autor do bilhete de resgate"}},{q="De quem era o livro roubado?",a="O livro pertence a Narain, um gnomo de Tanaris.",al={"dono do livro","livro de narain","livro roubado"}},{q="O que a carta exige?",a="Os sequestradores exigem dinheiro e ordenam que o destinatário venha sozinho.",al={"o que querem","exigência de resgate","levar o dinheiro"}},{q="Por que a carta é feita de palavras recortadas?",a="O texto é formado por palavras de diferentes tipos de letra coladas em um pergaminho. A carta não explica o motivo desse método.",al={"tipo de letra do bilhete de resgate","bilhete de recortar e colar","carta estranha"}},{q="Como Narain reage?",a="O rosto de Narain fica vermelho como brasa, e ele promete dar uma lição aos sequestradores.",al={"narain furioso","reação do gnomo","o que narain diz"}}},fp="13,141,16.325.0,16.207.1,28.116.0,22.47.0,28.66.0,42.107.0,22.79.1"}
P.entries["item:raptor-head"] = {n="Cabeça de Raptor",s="Uma cabeça decepada de raptor serve como prova sangrenta de uma fera abatida nos Sertões. Gazrog da Encruzilhada exige esses troféus macabros para expurgar os bandos locais após um roubo improvável do pagamento dos guardas.",h="Uma cabeça decepada de raptor serve como prova sangrenta de uma fera abatida nos Sertões.",kw={"sertoes","encruzilhada","gazrog","cabeça de raptor","raptores ladrões","prata roubada","sunscale"},ang={["class:Hunter"]="Rastrear raptores Sunscale pelos arbustos secos dos Sertões põe à prova a habilidade de um caçador em superar alguns dos caçadores de bando mais agressivos e astutos da savana.",["faction:Horde"]="A Encruzilhada é o coração logístico das viagens da Horda no centro de Kalimdor. Eliminar os predadores ladrões protege os suprimentos e o soldo da guarnição."},sec={{t="Recompensa da Encruzilhada",b="A vida nas planícies áridas dos Sertões já é dura o bastante sem a fauna local invadindo as torres do assentamento. Quando um baú contendo o soldo dos guardas desapareceu da torre de vigia da Encruzilhada, os defensores pegaram um culpado improvável em flagrante: um raptor selvagem. Perplexo e furioso, Gazrog colocou uma recompensa imediata sobre os répteis astutos que rondam a savana. Levar cabeças de raptores decepadas de volta ao posto prova que essas pragas predatórias estão sendo eliminadas antes que possam saquear mais suprimentos da Horda."}},faq={{q="Por que Gazrog quer cabeças de raptor?",a="Uma remessa de prata destinada ao pagamento dos guardas da Encruzilhada foi roubada diretamente da torre deles. Para a descrença de todos, um dos ladrões pegos no ato foi um raptor. Gazrog quer que essas feras sejam caçadas por todos os Sertões para que não possam invadir o assentamento novamente.",al={"por que coletar cabeças de raptor","gazrog raptores","recompensa cabeça de raptor"}},{q="Por que raptores selvagens roubariam prata?",a="Gazrog admite que não faz ideia do motivo pelo qual feras selvagens teriam qualquer interesse em moedas de metal. No entanto, os raptores de Kalimdor são notórios por sua astúcia desconcertante, e o incidente deixa os guardas da Encruzilhada tanto envergonhados quanto ávidos por retaliação.",al={"por que raptores querem prata","raptores roubando moedas","misterio dos raptores ladroes"}},{q="Quais raptores concedem essas cabeças?",a="As cabeças podem ser obtidas de vários raptores Sunscale que vagam pela região central e pelos Sertões Meridionais, incluindo Sunscale Lashtails, Screechers e Scytheclaws. Feras notórias como Ishamuhale e Takk the Leaper também concedem cabeças.",al={"onde conseguir cabeca de raptor","quais raptores dropam cabecas","raptores dos sertoes"}},{q="O que acontece depois de entregar as cabeças?",a="Assim que Gazrog recebe doze cabeças e vê a ameaça dos raptores reduzida, a atenção se volta para rastrear para onde a remessa de prata roubada foi realmente levada.",al={"o que vem depois de raptores ladroes","apos coletar cabecas de raptor"}}},fx={f6102aac={q="O que é uma Cabeça de Raptor?",a="Uma Cabeça de Raptor é o troféu decepado e a prova de recompensa tirada de raptores que vagam pelos Sertões, incluindo alcateias locais de Escama-solar e bestas notórias como Ishamuhale ou Takk, o Saltador. As autoridades da Encruzilhada exigem esses tokens macabros como prova verificável de que os predadores astutos que perturbam suas linhas de suprimentos e guardas foram eliminados.",al={"o que é cabeça de raptor","item cabeça de raptor","o que são cabeças de raptor"}},["377da5ba"]={q="De onde vem uma Cabeça de Raptor?",a="Essas cabeças vêm diretamente dos raptores predadores que perseguem as savanas e cumes dos Sertões. Cauda-de-chicote Escama-solar, Gritadores, Garra-de-foice e caçadores notáveis por todas as planícies as rendem depois de mortos. Como restos biológicos colhidos no campo, eles não são criados por ninguém, mas sim reivindicados como troféus de uma caçada bem-sucedida.",al={"de onde vêm as cabeças de raptor","origem da cabeça de raptor","quem fez a cabeça de raptor"}}},fp="11,150,24.355.0,34.228.0,36.207.0,32.207.0,40.139.0"}
P.entries["item:rare-earth"] = {n="Terra Rara",s="Terra Rara é um pacote especializado de solo rico em minerais obtido de Darnassus para experimentos botânicos em Teldrassil. Ele é enviado por correio de Dolanaar para o pesquisador herborista Denalan em seu acampamento à beira do lago, perto do Lago Al'Ameth.",h="Terra Rara é um pacote especializado de solo rico em minerais obtido de Darnassus para experimentos botânicos...",kw={"darnassus","denalan","dolanaar","herborismo","lago al'ameth","terra rara","syral folhâmina"},ang={["profession:Herbalism"]="Os herboristas apreciarão os esforços meticulosos de pesquisadores como Syral Folhâmina e Denalan, que estudam como a terra especializada pode alterar o crescimento e as propriedades das mudas de Teldrassil.",["race:NightElf"]="Para os elfos noturnos cuidando de sua jovem Árvore do Mundo, cada experimento botânico no Lago Al'Ameth oferece uma visão de como a vida se adapta aos galhos indomados de Teldrassil."},sec={{t="Solo de Darnassus",b="O recém-formado ecossistema de Teldrassil requer observação cuidadosa e cultivo, levando herboristas de toda a ilha a estudar como várias plantas respondem a solos estrangeiros ou enriquecidos. Esta encomenda específica de terra rara foi requisitada diretamente de Darnassus por Denalan, um botânico excêntrico instalado ao longo da margem leste do Lago Al'Ameth. Após definhar em trânsito e chegar com atraso a Dolanaar, a herborista Syral Folhâmina encarrega viajantes que vão para o sul de entregar o solo perecível a Denalan antes que sua potência se perca."}},faq={{q="Para que serve a Terra Rara?",a="A terra rara é destinada a Denalan, um herborista e pesquisador botânico acampado nas margens do Lago Al'Ameth. Ele usa compostos minerais especializados e solos enriquecidos importados de Darnassus para cultivar e fazer experimentos na flora nativa de Teldrassil.",al={"uso da terra rara","o que denalan faz com a terra rara","propósito da terra rara"}},{q="Quem envia a Terra Rara para Denalan?",a="Syral Folhâmina, uma herborista localizada na vila de Dolanaar, está de posse do pacote. Ele chegou com atraso de Darnassus, e ela pede aos aventureiros que passam em direção ao sul rumo ao Lago Al'Ameth que o entreguem em seu nome.",al={"quem dá a terra rara","onde conseguir terra rara","encomenda de syral folhâmina"}},{q="Por que Denalan estava preocupado com a entrega?",a="A remessa atrasou durante o transporte para Dolanaar, deixando Denalan esperando à beira do lago por um tempo considerável. Ao recebê-la, ele imediatamente se preocupa se a terra manteve seu frescor e vitalidade para seus experimentos botânicos.",al={"a terra rara estragou","terra fresca de denalan","por que terra atrasada"}}},fx={e720b4cb={q="O que é Terra Rara?",a="Terra Rara é uma remessa de solo fértil, de origem especial, despachada de Darnassus. É cuidadosamente preparada e embalada para pesquisas agrícolas e botânicas sensíveis, retendo nutrientes especializados que exigem que seja entregue fresca para manter sua potência para experimentos delicados de cultivo.",al={"o que é terra rara","item terra rara","folclore de terra rara"}},["5312d2a9"]={q="Por que Denalan quer Terra Rara?",a="Denalan é um pesquisador herbalista estacionado nas margens orientais do Lago Al'Ameth, estudando e experimentando a flora local de Teldrassil. Ele confia neste solo raro e rico em nutrientes de Darnassus para nutrir suas plantas delicadas e avançar seu trabalho botânico na ilha.",al={"por que denalan quer terra rara","por que querer terra rara","por que terra rara é necessária"}}},fp="10,160,17.313.0,28.170.0,36.170.0,43.172.0"}
P.entries["item:raschal-s-report"] = {n="Raschal's Report",s="Raschal's Report relata uma infestação de silithid no sudeste de Feralas. Shandris Plumaluna envia uma cópia para Gracinha Forçânima, no Templo da Lua.",h="Raschal's Report relata uma infestação de silithid no sudeste de Feralas.",kw={"darnassus","feralas","gracinha forçânima","raschal","raschal's report","shandris plumaluna","silithid","sudeste de feralas","templo da lua"},ang={["class:Priest"]="Como sacerdote, você leva o relatório a Gracinha Forçânima, uma sacerdotisa cujo conhecimento dessas criaturas pode ajudar os defensores de Feralas.",["race:NightElf"]="Como elfo noturno, você leva o relatório de Shandris Plumaluna a Gracinha Forçânima, no Templo da Lua, onde ela reconhece a ameaça dos silithid a Feralas."},sec={{t="Uma cópia para Darnassus",b="No Domínio de Plumaluna, Shandris Plumaluna confia a você uma cópia de Raschal's Report sobre os silithid no sudeste de Feralas. O relatório principal está sendo arquivado em Darnassus. Esta cópia é para Gracinha Forçânima, uma sacerdotisa do Templo da Lua que conhece essas criaturas."},{t="O conselho do Templo",b="Gracinha Forçânima recebe você no Templo da Lua, onde reconhece o perigo descrito em Raschal's Report. Ela identifica os insetos como silithid e alerta que eles consumirão Feralas rapidamente. Para ela, são ferramentas de uma grande ameaça tanto à Horda quanto à Aliança, e ela reza por determinação para derrotá-los."}},faq={{q="O que é Raschal's Report?",a="Raschal's Report descreve a infestação de silithid no sudeste de Feralas.",al={"relatório de raschal","o que há no relatório"}},{q="Para quem é Raschal's Report?",a="Uma cópia de Raschal's Report é destinada a Gracinha Forçânima, uma sacerdotisa do Templo da Lua em Darnassus.",al={"quem recebe o relatório","relatório para gracinha"}},{q="Quem pede que você leve o relatório?",a="Shandris Plumaluna confia a você uma cópia de Raschal's Report para Gracinha Forçânima.",al={"quem me enviou","relatório de shandris"}},{q="O que são os insetos do relatório?",a="Gracinha identifica os insetos descritos em Raschal's Report como silithid.",al={"insetos de feralas","o que são os silithid"}},{q="Por que Gracinha precisa do relatório?",a="Gracinha tem amplo conhecimento de criaturas como os silithid, e Shandris acredita que receber o relatório será benéfico para todos.",al={"por que levar para gracinha","relatório do templo"}}},fp="16,164,20.288.0,20.329.0,25.76.0,28.112.0,33.90.0,35.73.0,33.125.0"}
P.entries["item:rattlecage-skull"] = {n="Crânio de Range-ossos",s="Crânios de Range-ossos são os restos despedaçados de mortos-vivos sem mente que vagam pelos arredores em ruínas de Plangemortis. Bruxos Renegados novatos devem coletar esses troféus calcificados para Vênia Martingil a fim de demonstrar sua vontade nascente e se qualificar para as artes sombrias de evocação.",h="Crânios de Range-ossos são os restos despedaçados de mortos-vivos sem mente que vagam pelos arredores em...",kw={"plangemortis","evocação de diabrete","perfurando o véu","rattlecage skeleton","crânio de range-ossos","clareiras de tirisfal","vênia martingil"},ang={["class:Warlock"]="Para os bruxos Renegados, juntar esses crânios representa o marco inicial de sua disciplina, provando que possuem a vontade fria necessária para escravizar seu primeiro demônio.",["race:Undead"]="O ato de despedaçar esqueletos menores e irracionais reforça a crença dos Renegados de impor domínio por pura força de vontade, diferenciando os mortos-vivos de livre-arbítrio dos servos sem mente."},sec={{t="O Teste de um Neófito",b="Dentro dos limites sem sol de Plangemortis, Renegados recém-erguidos com afinidade pela magia sombria são guiados por Vênia Martingil. Para provar que um praticante iniciante tem a determinação necessária para submeter criaturas extraplanares ao seu comando, Vênia o encarrega de subjugar os Rattlecage Skeletons remanescentes perto da ferraria em ruínas. Abater esses mortos-vivos menores e recuperar seus crânios decepados serve tanto como um teste prático de disciplina quanto como uma base ritual antes de aprender a romper o caos e escravizar um primeiro lacaio demoníaco."}},faq={{q="Para que servem os Crânios de Range-ossos?",a="Eles são recolhidos por Vênia Martingil em Plangemortis. Os bruxos Renegados devem levar três crânios a ela para provar seu foco e determinação antes que ela os instrua nos ritos de evocação e aprisionamento de um diabrete.",al={"o que são crânios de range-ossos","uso do crânio de range-ossos","quem quer crânios de range-ossos"}},{q="De onde vêm os Crânios de Range-ossos?",a="Eles são retirados dos restos despedaçados de Rattlecage Skeletons, mortos-vivos sem mente que perambulam pelas estradas cobertas de mato e pelos terrenos decadentes perto da ferraria abandonada de Plangemortis.",al={"onde conseguir crânios de range-ossos","quem saqueia crânio de range-ossos","localização do crânio de range-ossos"}},{q="Por que Vênia Martingil exige crânios de esqueleto para um teste de bruxo?",a="Vênia acredita que o poder escapa aos ignorantes e que o domínio exige dobrar forças externas à própria vontade. Abater os esqueletos irracionais e reivindicar suas cabeças demonstra que o aprendiz possui a força de vontade fundamental para controlar energias caóticas em vez de ser consumido por elas.",al={"por que crânios para bruxos","teste de vênia martingil"}},{q="Qual conhecimento é concedido após reunir esses crânios?",a="Assim que os crânios são entregues, Vênia Martingil transmite o ritual secreto necessário para invocar e prender um diabrete, concedendo aos jovens bruxos seu primeiro lacaio demoníaco de verdade.",al={"o que se ganha com crânios de range-ossos","recompensa de perfurando o véu"}}},fx={["9627b388"]={q="O que é um Crânio de Range-ossos?",a="Um Crânio de Range-ossos é a cabeça decepada de um Esqueleto Range-ossos, um dos mortos-vivos irracionais que vagam pelos terrenos devastados perto da ferraria abandonada de Plangemortis. Para aspirantes a bruxos Renegados, esses troféus sombrios servem como prova de determinação e foco mágico básico, mostrando que um iniciado pode enfrentar e superar os mortos ambulantes.",al={"o que é crânio de range-ossos","folclore do crânio de range-ossos"}}},fp="16,155,17.352.0,36.172.0,37.145.0,68.239.0,55.160.0"}
P.entries["item:raven-claw-talisman"] = {n="Talismã de Garra de Corvo",s="O Talismã de Garra de Corvo é uma relíquia sagrada dos elfos noturnos ligada aos Druids of the Talon. Guardado nas profundezas da Gruta de Ban'ethil em Teldrassil, é uma das quatro Relíquias do Despertar essenciais necessárias para guiar com segurança os druidas adormecidos de volta do Sonho Esmeralda.",h="O Talismã de Garra de Corvo é uma relíquia sagrada dos elfos noturnos ligada aos Druids of the Talon.",kw={"athridas mantursino","ban'ethil","gruta","dolanaar","druids of the talon","talismã de garra de corvo","reliquias do despertar","teldrassil"},ang={["class:Druid"]="O talismã é um emblema dos Druids of the Talon, ilustrando como os focos rituais protegem o espírito de um druida enquanto vaga pelo Sonho Esmeralda.",["race:NightElf"]="Recuperar esta relíquia protege tanto a antiga tradição dos elfos noturnos quanto a vida dos irmãos adormecidos ameaçados pela loucura dos fúrbolgs Gnarlpine."},sec={{t="Uma chave para o despertar",b="O Talismã de Garra de Corvo é preservado dentro de um baú específico dentro da Gruta de Ban'ethil, o santuário subterrâneo onde os Druids of the Talon de Teldrassil entravam em seus profundos sonos meditativos. A hibernação druídica é um limiar espiritual delicado. Se o elo de um druida com o mundo desperto for rompido sem o foco cerimonial adequado, seu espírito corre o risco de ficar preso no Sonho Esmeralda indefinidamente. Juntamente com o Cálamo de Pena Negra, a Safira do Céu e a Runa da Nidificação, o talismã é exigido por Athridas Mantursino em Dolanaar para realizar o ritual de despertar e trazer os dormentes de volta em segurança."},{t="A ameaça na gruta",b="Quando os fúrbolgs Gnarlpine corrompidos invadiram a Gruta de Ban'ethil, os baús sagrados e os druidas adormecidos caíram em perigo imediato. A profanação dos fúrbolgs isolou o sacrário de ajuda externa e colocou as relíquias em perigo de serem perdidas ou destruídas. Athridas Mantursino encarrega os defensores de Teldrassil de desbravar os sinuosos corredores de terra do covil para proteger o Talismã de Garra de Corvo antes que os druidas desalojados se percam no Sonho para sempre."}},faq={{q="Para que serve o Talismã de Garra de Corvo?",a="É uma das quatro Relíquias do Despertar sagradas necessárias para realizar o ritual que desperta os Druids of the Talon de sua profunda hibernação no Sonho Esmeralda.",al={"o que faz o talisma de garra de corvo","utilidade do talisma de garra de corvo","por que preciso do talisma de garra de corvo"}},{q="Onde o Talismã de Garra de Corvo é encontrado?",a="Ele repousa dentro do Chest of the Raven Claw, guardado nos túneis de terra da Gruta de Ban'ethil, a oeste de Dolanaar em Teldrassil.",al={"onde fica o talisma de garra de corvo","localizacao do bau da garra de corvo","como encontrar o talisma de garra de corvo"}},{q="Quem precisa do Talismã de Garra de Corvo?",a="Athridas Mantursino, um druida elfo noturno posicionado em Dolanaar, precisa do talismã para preparar os ritos de despertar para seus irmãos desalojados.",al={"quem quer o talisma de garra de corvo","quem recebe o talisma de garra de corvo","a quem entregar isso"}},{q="Por que os druidas não podem acordar sem ele?",a="Entrar no Sonho Esmeralda por meio da hibernação druídica envolve um transe complexo e delicado. Sem o foco específico das Relíquias do Despertar para ancorar o ritual de despertar, o espírito de um adormecido corre o risco de permanecer perdido no Sonho indefinidamente.",al={"por que druidas precisam de reliquias para acordar","por que reliquias do despertar","druidas podem acordar sem reliquias"}}},fx={["33636b37"]={q="O que é o Talismã de Garra de Corvo?",a="O Talismã de Garra de Corvo é uma das quatro Relíquias do Despertar sagradas mantidas pelos Druidas da Garra. Armazenado dentro de um baú dedicado na Gruta de Ban'ethil, é um componente essencial do ritual delicado necessário para chamar em segurança druidas adormecidos de volta de sua hibernação no Sonho Esmeralda.",al={"o que é talismã de garra de corvo","informações sobre talismã de garra de corvo","relíquia talismã de garra de corvo"}}},fp="19,210,18.440.0,28.413.0,41.164.0,39.153.0,34.139.0,40.175.0"}
P.entries["item:razorflank-s-medallion"] = {n="Medalhão da Talhaflanco",s="O Medalhão da Talhaflanco é um símbolo pessoal carregado por Charlga Talhaflanco, a megera que governa o Urzal dos Tuscos. Recuperado do coração da fortaleza dos javatuscos, ele serve como prova inegável de que a matriarca foi derrotada.",h="O Medalhão da Talhaflanco é um símbolo pessoal carregado por Charlga Talhaflanco, a megera que governa o...",kw={"agamaggan","charlga talhaflanco","falfindel waywarder","lonebrow","urzal dos tuscos","medalhão da talhaflanco","thalanaar"},ang={["faction:Alliance"]="Recuperar o medalhão vinga o batedor caído Heralath e o anão explorador Lonebrow, garantindo a segurança da rota fronteiriça de Thalanaar para Feralas.",["race:NightElf"]="Matar Charlga e reivindicar seu medalhão permite que os elfos noturnos estudem com segurança o local sagrado de repouso corrompido de Agamaggan."},sec={{t="Prova da Queda da Megera",b="Carregado pela própria Charlga Talhaflanco, este medalhão representa a autoridade da megera que lidera os javatuscos de Razorfen. Quando Falfindel Waywarder em Thalanaar descobre os destinos de exploradores caídos como Heralath e o anão Lonebrow, ele encarrega os aventureiros da Aliança de atacar diretamente a líder dos javatuscos. Apresentar o medalhão da megera confirma sua morte, tranquilizando as sentinelas elfas noturnas que guardam as fronteiras de Feralas de que as forças reunidas dentro do Urzal perderam sua líder."}},faq={{q="Quem carrega o Medalhão da Talhaflanco?",a="O medalhão pertence a Charlga Talhaflanco, a megera e líder indiscutível dos javatuscos dentro do Urzal dos Tuscos. Ela o carrega consigo nas profundezas dos labirintos espinhosos da fortaleza.",al={"quem dropa medalhao da talhaflanco","fonte do medalhao da talhaflanco","medalhao de charlga"}},{q="Quem deseja que este medalhão lhe seja entregue?",a="Falfindel Waywarder, estacionado no posto fronteiriço de Thalanaar entre Feralas e as Mil Agulhas, pede pelo medalhão. Ele o procura como prova definitiva de que Charlga foi morta.",al={"quem quer medalhao da talhaflanco","entregar medalhao da talhaflanco","medalhao de falfindel"}},{q="Por que Falfindel precisa de provas da morte de Charlga?",a="Charlga estava reunindo uma força hostil de javatuscos dentro do Urzal dos Tuscos, ameaçando as regiões vizinhas e levando à morte de batedores como Heralath e Lonebrow. Trazer de volta o medalhão garante aos elfos noturnos que a ameaça imediata foi desfeita e permite que suas investigações na área continuem.",al={"por que matar charlga","proposito do medalhao","por que precisa do medalhao"}}},fx={b119a669={q="O que é o Medalhão da Talhaflanco?",a="O Medalhão da Talhaflanco é um token pessoal carregado por Charlga Talhaflanco, a bruxa e líder dos javatuscos que habitam as profundezas do Urzal dos Tuscos. Mais do que um simples ornamento, serve como um símbolo inconfundível de sua autoridade sobre as tribos que enxameiam no Urzal, tornando-o o troféu definitivo de sua queda.",al={"o que é medalhão da talhaflanco","folclore do medalhão da talhaflanco","medalhão de charlga talhaflanco"}}},fp="22,157,25.393.0,35.98.0,41.100.0,49.269.0"}
P.entries["item:reagent-pouch-shaman"] = {n="Bornal de Reagentes",s="Um bornal de reagentes carregado por cultistas da Lâmina Ardente à espreita nos penhascos de Durotar. Xamãs que buscam comungar com o fogo precisam desses componentes mágicos reunidos para destilar seu Sapta do Fogo inicial.",h="Um bornal de reagentes carregado por cultistas da Lâmina Ardente à espreita nos penhascos de Durotar.",kw={"lâmina ardente","clamor do fogo","durotar","caverna sopravento","sapta do fogo","totem do fogo","bornal de reagentes","telf joolam"},ang={["class:Shaman"]="Recuperar o bornal é um rito de passagem crucial no caminho para conquistar seu Totem do Fogo, ensinando que até mesmo condutores elementais corrompidos podem ser recuperados para servir ao equilíbrio.",["class:Warlock"]="Os bornais refletem os suprimentos de feitiçaria padrão carregados por cultistas vis, contendo elementos rituais destinados à piromancia demoníaca em vez da comunhão com a natureza."},sec={{t="Componentes da Chama",b="Para forjar um Sapta do Fogo e sintonizar um jovem xamã com os espíritos da chama, catalisadores rituais específicos são vitais. Cultistas da Lâmina Ardente carregam pequenas bolsas cheias de reagentes adaptados para conjurações de fogo demoníaco. O eremita Telf Joolam usa esses pós e óleos reunidos, combinados com o Piche Ígneo dos javatuscos Razormane, para preparar a poção necessária para conceder a visão do reino do fogo."},{t="Fontes Maculadas, Visão Pura",b="Embora a Lâmina Ardente corrompa a chama para destruição e feitiçaria vil, os elementos físicos dentro de seus bornais permanecem ligados à natureza primordial do calor e da combustão. A filosofia xamânica sustenta que todas as forças elementais existem em tensão: o fogo é tanto criador quanto destruidor. Ao tomar as ferramentas roubadas dos cultistas, um xamã recupera o meio elemental para despertar uma verdadeira comunhão com os espíritos."}},faq={{q="Para que serve o bornal de reagentes?",a="Ele serve como um material essencial para Telf Joolam preparar um Sapta do Fogo. Beber este elixir concede ao xamã a visão necessária para buscar os espíritos elementais e reivindicar seu Totem do Fogo.",al={"uso do bornal de reagentes","o que faz o bornal de reagentes","missão de xamã bornal de reagentes"}},{q="Onde encontro um bornal de reagentes?",a="O bornal é obtido de cultistas da Lâmina Ardente instalados dentro da Caverna Sopravento, localizada nas colinas rochosas a nordeste de Monte Navalha, em Durotar.",al={"saque bornal de reagentes","onde conseguir bornal de reagentes","localização bornal lâmina ardente"}},{q="Por que um xamã precisa de reagentes de bruxo?",a="A Lâmina Ardente abastece seus bornais com ingredientes impregnados de magia de fogo. Como seus rituais dependem muito de chamas, seus reagentes fornecem catalisadores elementais prontos que podem ser reaproveitados para preparar o Sapta do Fogo.",al={"por que itens de bruxo","por que reagentes da lâmina ardente","xamã usando itens vis"}}},fx={ad39cae0={q="O que é o Bornal de Reagentes?",a="É uma pequena bolsa carregada por cultistas da Lâmina Ardente, repleta de ervas rituais, cinzas e catalisadores ocultos que eles usam para alimentar seus feitiços sombrios. Embora destinada à feitiçaria sombria, a mera concentração de componentes ígneos torna a bolsa inteira um pacote potente de materiais elementais brutos.",al={"o que é bornal de reagentes","história do bornal de reagentes","bornal de reagentes da lâmina ardente"}},["2a611680"]={q="De onde vem o Bornal de Reagentes?",a="Os bornais são montados e carregados por cultistas da Lâmina Ardente escondidos nas cavernas de Durotar e dos Sertões. Esses bruxos reúnem e armazenam componentes específicos necessários para seus ritos destrutivos, mantendo-os sempre à mão para conjurar magia de fogo e Shadow Magic.",al={"origem do bornal de reagentes","quem fez o bornal de reagentes","de onde veio o bornal de reagentes"}}},fp="13,209,23.316.0,28.307.0,35.189.0,32.126.0,40.160.0"}
P.entries["item:reconstructed-tome"] = {n="Tomo Reformado",s="O Tomo Reformado é um grimório reconstituído de conhecimentos sombrios do conluio, compilado para bruxos que buscam expandir seu domínio sobre servos demoníacos. Ele contém o conhecimento arcano e os rituais necessários para evocar e vincular um predador caçador vil da Espiral Etérea.",h="O Tomo Reformado é um grimório reconstituído de conhecimentos sombrios do conluio, compilado para bruxos que...",kw={"a vinculação","dragonmaw","caçador vil","vila catraca","tomo reformado","strahad farsan","tomo do conluio"},ang={["class:Warlock"]="Reunir o Tomo Reformado é um rito de passagem essencial, desbloqueando os ritos sombrios necessários para dominar um caçador vil e direcionar seu apetite devorador de magia contra conjuradores rivais."},sec={{t="Um Grimório Remontado",b="Recuperado em fragmentos e pacientemente remontado, o Tomo Reformado representa uma coleção elusiva de ensinamentos do conluio formalmente conhecida como Tomo do Conluio. Bruxos tanto da Aliança quanto da Horda fazem grandes esforços para restaurar suas folhas desgastadas, consultando estudiosos do ocultismo ansiosos por um mero vislumbre de seu conteúdo esotérico antes de entregarem o manuscrito concluído."},{t="Chave para o Caçador Vil",b="A obra reformada é levada a Strahad Farsan, um experiente mestre de evocação instalado perto do porto de Vila Catraca, nos Sertões. Acompanhado por bastões arcanos de canalização arrancados de conjuradores Dragonmaw, os rituais descritos no tomo fornecem os encantamentos exatos necessários para que o círculo de acólitos de Strahad ajude um bruxo a evocar, subjugar e vincular um voraz caçador vil à sua vontade."}},faq={{q="Para que serve o Tomo Reformado?",a="O livro contém rituais sombrios e ensinamentos do conluio necessários para evocar e subjugar um caçador vil. Um bruxo o entrega, junto com bastões de canalização, a Strahad Farsan em Vila Catraca para preparar o ritual de vinculação.",al={"propósito do tomo reformado","por que precisa do tomo reformado","uso do tomo reformado"}},{q="Quem é Strahad Farsan?",a="Strahad Farsan é um mestre evocador que reside acima da cidade portuária de Vila Catraca, nos Sertões. Ele supervisiona os exigentes testes de bruxos promissores que buscam escravizar entidades demoníacas mais perigosas.",al={"quem é strahad","papel de strahad farsan"}},{q="Por que os estudiosos que examinam o livro querem uma cópia?",a="Os estudiosos que auxiliam na decifração das páginas rasgadas acham os textos ocultistas do conluio fascinantes e extremamente raros. Tanto pesquisadores anões quanto Renegados consideram suas leituras habituais escassas em comparação e cobiçam o raro conhecimento demoníaco preservado nas páginas.",al={"quem o traduziu","estudiosos tomo reformado"}},{q="O que mais é necessário além do tomo para o ritual?",a="Strahad requer três bastões de canalização para permitir que seus acólitos sustentem o ritual de evocação. Esses bastões precisam ser tomados de conjuradores Dragonmaw entrincheirados em Pantanal.",al={"outros itens necessários","o que acompanha o tomo reformado"}}},fx={a9385a16={q="O que é o Tomo Reformado?",a="O Tomo Reformado é a versão montada do Tome of the Cabal, um grimório proibido contendo rituais demoníacos esotéricos. Depois que suas páginas espalhadas e materiais de encadernação são reunidos de todo o mundo, estudiosos remontam minuciosamente o texto fragmentado para que seu conhecimento sombrio possa ser decifrado e colocado em uso.",al={"o que é tomo reformado","folclore do tomo reformado","livro tome of the cabal"}},d276d405={q="De onde vem o Tomo Reformado e quem o fez?",a="O livro é a forma recuperada do antigo Tome of the Cabal. Estudiosos bruxos remontam seus capítulos rasgados e encadernação gasta depois que praticantes aventureiros recuperam seus componentes espalhados de locais perigosos em todos os continentes.",al={"origem do tomo reformado","quem fez o tomo reformado","de onde veio o tomo reformado"}},["04500ccd"]={q="Por que o Tomo Reformado é procurado?",a="Bruxos e estudiosos das artes sombrias buscam o tomo pelos segredos potentes e proibidos registrados em suas páginas recuperadas. Strahad Farsan precisa de seus ritos específicos para guiar um aspirante a bruxo através da invocação e ligação de um perverso cão-vil demoníaco, enquanto estudiosos locais desejam uma cópia puramente por seu conhecimento mágico raro e fascinante.",al={"por que querer o tomo reformado","por que strahad quer o tomo reformado","propósito do tomo reformado"}}},fp="18,172,22.250.0,20.291.1,40.182.0,22.160.0,51.199.0,54.146.0"}
P.entries["item:recruitment-letter"] = {n="Carta de Recrutamento",s="A Carta de Recrutamento é uma correspondência oficial entregue a aventureiros promissores que partem de Durotar para servir nos Sertões. Emitida pelo batedor Takrin Buscatrilha, ela orienta voluntários aptos a se apresentarem no posto avançado da fronteira supervisionado por Kargal Chaga de Guerra.",h="A Carta de Recrutamento é uma correspondência oficial entregue a aventureiros promissores que partem de...",kw={"sertoes","recruta da horda","encruzilhada","kargal chaga de guerra","monte navalha","carta de recrutamento","takrin buscatrilha"},ang={["faction:Horde"]="Carregar esta carta representa a transição de um recruta da defesa local em Durotar para o serviço militar ativo na fronteira de Kalimdor.",["race:Orc"]="Para jovens orcs, apresentar uma carta de serviço assinada a um veterano como Kargal Chaga de Guerra é um passo inicial crucial para conquistar honra sob a nova Horda do Chefe Guerreiro Thrall."},sec={{t="Alistamento para a Fronteira",b="À medida que jovens guerreiros e batedores provam seu valor nos arredores de Monte Navalha, o olhar da Horda se volta para o oeste, em direção à vasta e indomada extensão dos Sertões. Takrin Buscatrilha identifica recrutas promissores que parecem fortes o suficiente para lidar com o serviço na linha de frente e lhes fornece esta carta. Atravessar a ponte do Rio Furiaustral marca um rito de passagem: deixar para trás a terra vermelha e protegida de Durotar para se juntar às fileiras da Horda que montam guarda contra javatuscos, centauros e batedores da Aliança."},{t="Apresentando-se a Chaga de Guerra",b="O destinatário da carta é Kargal Chaga de Guerra, o veterano grisalho que administra o posto avançado logo após o rio. Kargal avalia cada conscrito antes de aprovar formalmente seu alistamento. No entanto, ter esta carta é apenas o primeiro passo; os postos avançados da fronteira estão perpetuamente sobrecarregados, e qualquer recruta aprovado é rapidamente redirecionado mais a oeste para o centro estratégico da Encruzilhada."}},faq={{q="Quem escreveu esta carta de recrutamento?",a="A carta é entregue por Takrin Buscatrilha, um batedor orc posicionado ao longo da estrada que sai de Monte Navalha e que fica atento a recrutas capazes que viajam para o oeste.",al={"quem entrega carta de recrutamento","quem escreveu","carta de takrin buscatrilha"}},{q="Para onde esta carta precisa ir?",a="Você a entrega a Kargal Chaga de Guerra no posto de vigia orc localizado logo após a ponte do Rio Furiaustral, bem na fronteira entre Durotar e os Sertões.",al={"onde levar carta de recrutamento","entregar carta de recrutamento","para quem entregar"}},{q="O que acontece quando a carta é assinada?",a="Kargal assina o documento para oficializar seu alistamento, mas imediatamente ordena que você avance pelas planícies para se apresentar ao serviço na Encruzilhada, onde reforços são necessários com urgência.",al={"o que acontece apos kargal assinar","proxima missao apos carta de recrutamento"}},{q="Por que a Horda está recrutando aventureiros nos Sertões?",a="Os Sertões são um território vasto e perigoso que conecta os principais assentamentos da Horda. Com ameaças constantes de clãs nativos de centauros, javatuscos Costas-de-cerda agressivos e operações da Aliança, os comandantes da linha de frente precisam de todos os braços fortes que conseguirem reunir.",al={"por que estao recrutando","por que conscricao sertoes"}}},fx={e6a35429={q="O que é a Carta de Recrutamento?",a="A Carta de Recrutamento é um documento oficial de recrutamento emitido para aventureiros capazes em Durotar. O batedor Takrin Buscatrilha a entrega àqueles que parecem fortes o suficiente para ajudar a presença crescente da Horda na fronteira severa dos Sertões, recomendando-os aos comandantes de postos avançados militares.",al={"o que é carta de recrutamento","propósito da carta de recrutamento","o que é esta carta"}},["6a5949ec"]={q="Por que Kargal Chaga de Guerra quer a Carta de Recrutamento?",a="Kargal Chaga de Guerra comanda o posto avançado na fronteira protegendo a ponte para os Sertões e precisa desesperadamente de recrutas capazes para reforçar a fronteira. A carta assinada verifica que você foi examinado pelo batedor Takrin Buscatrilha e está pronto para ser designado para onde a Horda mais precisa de você.",al={"por que kargal quer a carta","por que entregar carta de recrutamento","carta de recrutamento entregue"}}},fp="18,168,27.348.0,23.286.0,34.141.0,34.139.0,39.174.0,57.263.0"}
P.entries["item:red-burlap-bandana"] = {n="Bandana de Lona Vermelha",s="As Bandanas de Lona Vermelha são as máscaras de pano rústicas e tingidas usadas por salteadores e batedores de carteira de baixa patente da Irmandade Défias. No Vale de Vila Norte, o Delegado Willem coleta esses pedaços de pano como prova de ladrões mortos invadindo as proximidades dos vinhedos da abadia.",h="As Bandanas de Lona Vermelha são as máscaras de pano rústicas e tingidas usadas por salteadores e batedores...",kw={"bandana","brotherhood of thieves","défias","máscara","vila norte","bandana de lona vermelha","willem"},ang={["class:Rogue"]="Para um ladino em desenvolvimento, arrancar máscaras vermelhas dos batedores desajeitados de Vila Norte é uma lição de como rapidamente foras da lei indisciplinados se tornam alvos fáceis para as autoridades locais.",["faction:Alliance"]="A disseminação dessas bandanas vermelhas até a própria porta de entrada da Abadia de Vila Norte mostra a gravidade com que as fronteiras rurais do reino estão escapando do controle de Ventobravo."},sec={{t="Uma Marca da Irmandade",b="Usada sobre a parte inferior do rosto, a bandana de lona vermelha serve como o emblema de identificação da base da Irmandade Défias. Feito de tecido barato e áspero embebido em tinta vermelha, o pano oculta as feições de um ladrão enquanto sinaliza lealdade à rebelião crescente. Em Vila Norte, jovens recrutas e bandidos comuns levam esses lenços para os pomares do leste, sem saber que os guardas locais usam o chamativo tecido vermelho como um sombrio marcador de recompensa."}},faq={{q="Por que o Delegado Willem quer essas bandanas?",a="O Delegado Willem coleta as bandanas como prova tangível de que um aventureiro eliminou os bandidos Défias que avançavam do outro lado do rio, perto da Abadia de Vila Norte. Como os ladrões usam abertamente o pano vermelho, trazê-los serve como confirmação das recompensas pagas pelos salteadores locais.",al={"por que coletar bandanas","bandanas willem","entrega de brotherhood of thieves"}},{q="Quem usa as bandanas de lona vermelha?",a="Elas são usadas por batedores e bandidos afiliados à Irmandade Défias, um bando de foras da lei organizados ativo por toda a Floresta de Elwynn e Cerro Oeste. O tecido vermelho e grosseiro atua tanto como um disfarce quanto como um emblema de lealdade à sua guilda clandestina.",al={"quem usa bandana vermelha","história da máscara défias","quem dropa bandanas vermelhas"}},{q="Por que os ladrões Défias estão operando em Vila Norte?",a="Batedores e bandidos Défias montaram acampamentos do outro lado do riacho a leste da Abadia de Vila Norte para saquear e roubar suprimentos. A guarnição da abadia está sobrecarregada, permitindo que salteadores de nível baixo perambulem pelos pomares próximos.",al={"por que os défias estão em vila norte","ladrões perto da abadia"}},{q="O que torna as bandanas vermelhas?",a="As bandanas são simplesmente pedaços de lona barata tratados com tintura carmesim. A cor distinta atua como o estandarte e uniforme oficial da Irmandade Défias, garantindo que os companheiros se reconheçam em campo.",al={"por que as máscaras dos défias são vermelhas","significado do tecido vermelho"}}},fx={c4ebebb0={q="O que é uma Bandana de Lona Vermelha?",a="Uma Bandana de Lona Vermelha é a máscara de pano característica usada pelos membros da The Defias Brotherhood. Feita de forma barata com lona grossa e tingida de vermelho, ela oculta o rosto de quem a usa e marca sua lealdade à guilda fora da lei. Na Vila Norte, serve como prova direta da presença e atividade de um bandido a leste do rio.",al={"identidade bandana de lona vermelha","o que são bandanas vermelhas","lore bandana defias"}}},fp="18,180,25.319.0,43.189.0,34.148.0,47.188.0,28.172.0"}
P.entries["item:red-leather-bandana"] = {n="Bandana Vermelha de Couro",s="Uma peça de vestuário marcante usada por membros d'A Irmandade Défias por todo o Cerro Oeste. Confeccionada em couro tingido de carmesim, ela serve tanto como uma cobertura prática para o rosto quanto como um símbolo inconfundível de desafio contra a Coroa de Ventobravo.",h="Uma peça de vestuário marcante usada por membros d'A Irmandade Défias por todo o Cerro Oeste.",kw={"irmandade","défias","galiaan","máscara","bandana vermelha de couro","morro da sentinela","cerro oeste"},ang={["class:Rogue"]="A máscara carmesim é sinônimo de banditismo clandestino nas terras humanas, um emblema inconfundível de ladrões organizados com precisão militar.",["faction:Alliance"]="Cada bandana vermelha arrancada de um fora da lei derrotado representa um bandido a menos ameaçando os fazendeiros famintos e a milícia acuada de Cerro Oeste."},sec={{t="Marca da Irmandade",b="Pelos campos empoeirados e fazendas abandonadas de Cerro Oeste, essas bandanas carmesins ocultam os rostos de salteadores, saqueadores e trabalhadores rebeldes. Para A Milícia do Povo estacionada no Morro da Sentinela, a peça de cabeça é mais do que um simples tecido: é uma prova concreta de lealdade à fraternidade de renegados de Edwin VanCleef. O Batedor Galiaan recolhe essas bandanas de aventureiros que passam pela região para monitorar os movimentos e a diminuição dos números da irmandade."}},faq={{q="Por que os Défias usam bandanas vermelhas de couro?",a="A bandana vermelha serve como o uniforme unificado d'A Irmandade Défias. Ela oculta suas identidades durante saques a fazendas e estradas, ao mesmo tempo em que declara abertamente sua lealdade à rebelião de Edwin VanCleef contra Ventobravo.",al={"máscara défias","por que bandana vermelha","significado da bandana défias"}},{q="Quem quer que essas bandanas sejam recolhidas em Cerro Oeste?",a="O Batedor Galiaan, alocado com A Milícia do Povo no Morro da Sentinela, pede que viajantes as recolham. Ele as utiliza para rastrear as movimentações das tropas da gangue e confirmar a morte de bandidos errantes.",al={"quem aceita bandanas vermelhas","missão de bandana do galiaan","entrega de bandana no morro da sentinela"}},{q="Onde essas bandanas são encontradas?",a="Elas podem ser obtidas de quase qualquer ladino, salteador ou contrabandista a serviço d'A Irmandade Défias pelos acampamentos, campos e minas de Cerro Oeste.",al={"saque de bandana vermelha","farmar bandanas vermelhas","quem dropa bandana vermelha de couro"}}},fp="19,153,23.372.1,44.153.1,47.179.0,31.112.0"}
P.entries["item:red-linen-bandana"] = {n="Bandana de Linho Vermelha",s="Uma bandana de linho vermelha é a máscara facial característica usada pelos membros da Irmandade Défias por toda a Floresta de Elwynn. Além de ocultar a identidade de um bandido, o tecido é feito de linho de qualidade que os habitantes locais engenhosos costumam reaproveitar em peças úteis.",h="Uma bandana de linho vermelha é a máscara facial característica usada pelos membros da Irmandade Défias por...",kw={"máscara défias","vale do leste","floresta de elwynn","linho","bandana de linho vermelha","sara albernaz"},ang={["class:Rogue"]="Um tecido carmesim amarrado sobre a parte inferior do rosto tornou-se o semblante emblemático de salteadores e batedores de carteira por todos os bosques que cercam a capital.",["profession:Tailoring"]="As bandanas ilustram como o linho tecido cru continua valioso na zona rural de Elwynn, onde tecelões comuns reaproveitam as cores dos bandidos em roupas de trabalho."},sec={{t="Marca dos Défias",b="Enquanto iniciados de escalão inferior e bandidos comuns no Vale de Vila Norte se contentam com máscaras grosseiras de aniagem, os agentes plenos dos Défias por toda a Floresta de Elwynn usam bandanas tecidas de linho vermelho. O tecido carmesim vívido serve tanto de uniforme quanto de declaração de lealdade à fraternidade de renegados de Edwin VanCleef, disfarçando rostos enquanto sinaliza a insurreição contra a coroa de Ventobravo."},{t="Tecido Reaproveitado",b="Apesar de suas associações violentas, as bandanas são cortadas de tecidos de boa qualidade. Colonos pragmáticos como Sara Albernaz, na Madeireira Vale do Leste, costumam pedir a viajantes que as recolham dos acampamentos de foras da lei. Com um pouco de lavagem e costura, o tecido contrabandeado é transformado em roupas resistentes e bandagens para os trabalhadores da floresta."}},faq={{q="Por que os Défias usam bandanas de linho vermelhas?",a="A bandana vermelha serve como uniforme e emblema de desafio contra Ventobravo, ocultando a identidade de quem a usa e demonstrando lealdade à irmandade de Edwin VanCleef.",al={"significado da máscara défias","por que máscaras vermelhas","bandana vermelha défias"}},{q="Como elas diferem das máscaras usadas em Vila Norte?",a="Os capangas que agem no Vale de Vila Norte usam máscaras grosseiras de aniagem, enquanto os agentes estabelecidos dos Défias por toda a Floresta de Elwynn usam um linho vermelho mais refinado.",al={"aniagem vs linho","máscaras de vila norte","bandana de aniagem"}},{q="Quem quer recolher essas bandanas?",a="Sara Albernaz, na Madeireira Vale do Leste, as recolhe. Sendo uma costureira com falta de tecido, ela lava e desfia as máscaras dos bandidos para tecer peças de vestuário práticas.",al={"quem aceita bandanas de linho vermelhas","bandana sara albernaz","onde entregar missão bandana"}},{q="Quais inimigos carregam bandanas de linho vermelhas?",a="Quase todos os agentes Défias na Floresta de Elwynn as carregam, incluindo Bandidos Défias, Emboscadores, Magos Renegados, estivadores e líderes como Morgan, o Coletor.",al={"quem saqueia bandana de linho vermelha","onde farmar bandanas","saques de bandana défias"}}},fp="17,190,18.223.0,16.251.0,42.165.0,54.122.0,36.127.0,39.178.0"}
P.entries["item:red-wool-bandana"] = {n="Bandana Vermelha de Lã",s="As Bandanas Vermelhas de Lã são símbolos improvisados feitos por degoladores Défias encarcerados dentro do Cárcere de Ventobravo. Rasgadas de cobertores de lã da prisão, elas servem como emblemas desafiadores de irmandade mesmo atrás das grades.",h="As Bandanas Vermelhas de Lã são símbolos improvisados feitos por degoladores Défias encarcerados dentro do...",kw={"défias","mac raskol","nikova raskol","bandana vermelha de lã","ventobravo","a cor do sangue","o cárcere"},ang={["faction:Alliance"]="Para os defensores da Aliança, recuperar essas bandanas é um ato sombrio de justiça pelo jovem Mac Raskol e um golpe contra os amotinados que tomaram a prisão da cidade.",["profession:Tailoring"]="Essas bandanas rústicas ilustram como até cobertores grossos de lã podem ser desfiados e reaproveitados por mãos desesperadas no cativeiro."},sec={{t="Costuradas em Desafio",b="Mesmo trancados no fundo das altas muralhas de pedra do Cárcere de Ventobravo, os membros da Irmandade Défias se recusam a renunciar à sua identidade. Usando retalhos rasgados de cobertores de lã da prisão, os detentos confeccionam secretamente bandanas vermelhas para usar como cores de identificação. Para os guardas, esses lenços são contrabando que incitam motins fatais; para os prisioneiros, são uma declaração de que sua irmandade e rebelião perduram, mesmo acorrentados."},{t="A Vingança de uma Avó",b="As bandanas ganharam uma notoriedade amarga depois que o guarda prisional de quatorze anos, Mac Raskol, flagrou detentos rasgando cobertores para fazê-las. Quando tentou disciplinar os prisioneiros, os condenados Défias o esfaquearam pelas costas. Diante de sua morte, sua avó em luto, Nikova, procura aventureiros para entrar na masmorra amotinada, abater os rebeldes e recuperar os tecidos carmesins como prova de vingança."}},faq={{q="Onde os prisioneiros conseguem essas bandanas no Cárcere?",a="Os detentos Défias as fazem rasgando seus cobertores de lã fornecidos pela prisão. Apesar de desarmados e aprisionados, eles transformam sua roupa de cama escassa em símbolos de desafio para usar dentro das celas.",al={"de onde vêm as bandanas","origem da bandana do cárcere","como fazem bandanas vermelhas"}},{q="Quem quer que essas bandanas sejam coletadas?",a="Nikova Raskol, uma avó enlutada em Ventobravo, pede que os aventureiros as coletem. Seu neto de quatorze anos, Mac, era um guarda do Cárcere assassinado por prisioneiros após flagrá-los confeccionando as bandanas.",al={"quem precisa de bandana vermelha de lã","quem dá a missão cor de sangue","nikova raskol bandana"}},{q="Por que os prisioneiros se importam tanto em usar lenços vermelhos?",a="A Irmandade Défias usa máscaras e bandanas vermelhas como suas cores principais de gangue e uniforme. Atrás das grades, criar e usar esses retalhos permite que os detentos mantenham sua hierarquia, moral e união.",al={"por que bandanas vermelhas","símbolo vermelho défias","significado da bandana vermelha"}},{q="Quais detentos as carregam?",a="Elas são carregadas por quase qualquer membro Défias em revolta no Cárcere, incluindo Defias Captives, Inmates, Prisoners, Insurgents e Convicts.",al={"quem dropa bandana vermelha de lã","saques de bandana do cárcere"}}},fx={["7f0c1a2a"]={q="O que é uma Bandana Vermelha de Lã?",a="Uma Bandana Vermelha de Lã é um lenço carmesim improvisado feito pelos membros aprisionados da The Defias Brotherhood dentro da Stormwind Stockade. Ao retalhar e tingir os cobertores de lã fornecidos pela prisão, os detentos criam esses itens de pano para exibir abertamente sua lealdade à Brotherhood e manter sua identidade de gangue mesmo atrás das grades.",al={"o que é bandana vermelha de lã","item bandana vermelha de lã","bandana vermelha da stormwind stockade"}}},fp="16,166,20.335.0,25.366.0,54.181.0,35.218.0,60.156.0,25.134.0"}
P.entries["item:remaining-drops-of-purest-water"] = {n="Gotas Restantes da Mais Pura Água",s="As Gotas Restantes da Mais Pura Água são o resíduo final de uma poção especializada preparada pelo vidente da água Salma. Xamãs que carregam estas gotas potentes viajam por reinos para purificar um santuário de água sagrado corrompido pela praga dos mortos-vivos do Flagelo.",h="As Gotas Restantes da Mais Pura Água são o resíduo final de uma poção especializada preparada pelo vidente da...",kw={"brazier of everfount","brine","call of water","manifestação corrompida","mais pura água","pinhaprata","totem da água"},ang={["class:Shaman"]="Estas gotas representam o culminar de suas provações para dominar a água. Levá-las dos áridos Sertões até a costa assolada de Pinhaprata é essencial para ganhar seu Totem da Água.",["faction:Horde"]="A peregrinação do xamã conecta o território da Horda em Kalimdor com as posses precárias dos Renegados em Pinhaprata, demonstrando o alcance da restauração espiritual contra a praga do Flagelo."},sec={{t="Um Remédio para Águas Profanadas",b="Forjado através de uma coleta ritualística por Kalimdor e Lordaeron, este elixir concentrado retém a essência mais pura da água limpa, preparado pelo eremita Salma nos Sertões. Embora parte da poção seja consumida para conceder ao xamã a visão de elementos distantes, as gotas restantes são protegidas para uma tarefa muito mais perigosa. Levadas até as costas assoladas pela praga da Floresta de Pinhaprata, perto do Sepulcro, as gotas servem como o catalisador purificador vital sobre o Brazier of Everfount. Consumidas em chamas rituais junto com as braçadeiras de um elemental caído e maculado, esta água pura corta a corrupção necrótica, invocando um espírito da água não corrompido para comungar com o xamã e completar sua comunhão com o elemento."}},faq={{q="Para que estas gotas são usadas?",a="Elas são colocadas sobre o Brazier of Everfount na costa da Floresta de Pinhaprata junto com as braçadeiras de uma manifestação de água corrompida. Este ritual purifica o santuário elemental corrompido e invoca um espírito da água não corrompido.",al={"o que as gotas restantes fazem","propósito das gotas restantes","usar a mais pura água"}},{q="De onde veio o líquido?",a="Elas são a porção restante de uma poção purificadora preparada por Salma, um xamã orc que vive em uma colina nos Sertões Meridionais, criada durante as provações espirituais realizadas por aspirantes a xamã.",al={"quem fez a mais pura água","origem das gotas","gotas de água de brine"}},{q="Por que o ritual é realizado tão longe, na Floresta de Pinhaprata?",a="Um santuário da água ao longo da costa de Pinhaprata, a oeste do Sepulcro, foi corrompido pela praga dos mortos-vivos, deixando seus espíritos elementais hostis e distorcidos. Purificar aquele lago específico prova a devoção e o domínio de um xamã através de grandes distâncias.",al={"por que pinhaprata","por que viajar para pinhaprata","santuário da água de pinhaprata"}},{q="O que acontece quando elas tocam o braseiro?",a="Quando derramadas sobre as chamas do braseiro junto com as braçadeiras corrompidas, as gotas estalam no fogo, iniciando um encantamento que purifica a praga persistente e invoca uma manifestação pura de água.",al={"ritual do braseiro","o que acontece no braseiro","ritual do brazier of everfount"}}},fx={db79eea5={q="O que são as Gotas Restantes da Mais Pura Água?",a="Este pequeno frasco contém os últimos remanescentes da poção de limpeza preparada pelo eremita Salma nos Sertões meridionais. Infundido com água coletada dos Sertões, Serraria Tarren e Vale Gris, o líquido potente possui imensas propriedades purificadoras. Embora restem apenas algumas gotas, sua pureza concentrada é suficiente para eliminar a corrupção persistente quando oferecida em ritos elementais.",al={"o que são gotas restantes da mais pura água","o que são gotas de água puríssima","lore gotas de água puríssima"}},["55d7092f"]={q="Por que Islen Vidente da Água quer que você use as Gotas Restantes da Mais Pura Água?",a="Islen Vidente da Água exige que você derrame as gotas sobre o Braseiro da Fonte Eterna na Floresta de Pinhaprata. Um santuário de água sagrado lá sucumbiu à praga dos mortos-vivos, ensurdecendo seus espíritos locais para a comunhão xamânica. Ao oferecer essas gotas restantes junto com as braçadeiras de uma manifestação corrupta caída, o braseiro pode iniciar um ritual de limpeza potente o suficiente para invocar um espírito de água pura.",al={"por que usar gotas restantes da mais pura água","por que as gotas restantes da mais pura água são necessárias","por que você precisa de gotas de água puríssima"}}},fp="31,152,27.549.0,30.221.0,31.181.0,61.235.0,41.179.0"}
P.entries["item:remedy-of-arugal"] = {n="Remédio de Arugal",s="O Remédio de Arugal é um encantamento escrito pelo mago Arugal durante seus primeiros experimentos com a magia dos worgens. Deixado para trás em uma casa de fazenda dilapidada na Floresta de Pinhaprata, o feitiço é procurado por Dalar Tessalba para desvendar o trabalho sombrio do feiticeiro.",h="O Remédio de Arugal é um encantamento escrito pelo mago Arugal durante seus primeiros experimentos com a...",kw={"arugal","a loucura de arugal","dalar tessalba","grimórios empoeirados","moonrage","remédio de arugal","o sepulcro","floresta de pinhaprata"},ang={["class:Mage"]="Os magos Renegados compartilharão o desdém profissional de Dalar Tessalba pelos experimentos desajeitados e imprudentes de Arugal, mas reconhecerão o perigo inerente a magias de invocação descontroladas.",["race:Undead"]="Para os Renegados, proteger este feitiço é um passo inicial e vital para repelir os worgens ferozes que ameaçam as fronteiras da Floresta de Pinhaprata."},sec={{t="Os Restos de um Mago",b="Antes de tomar a Bastilha da Presa Negra, o Arquimago Arugal refugiou-se em uma fazenda de trigo abandonada ao norte da ponte sobre o rio na Floresta de Pinhaprata. Lá, em meio a ferramentas agrícolas esquecidas e tábuas podres no chão, ele documentou suas artes estranhas em um conjunto de grimórios empoeirados. O pergaminho intitulado Remédio de Arugal está entre essas notas, descrevendo os primeiros métodos e formulações mágicas que ele desenvolveu enquanto se aventurava nas perigosas transmutações que amaldiçoaram a população local."},{t="O Escrutínio dos Renegados",b="Dalar Tessalba, um habilidoso conjurador Renegado operando a partir d'O Sepulcro, tem pouco respeito pela linhagem de Arugal, desdenhando o intelecto do antigo mago de Dalaran como frágil e transparente. Mesmo assim, Tessalba reconhece a necessidade urgente de compreender a mecânica exata por trás da maldição dos worgens. Ao recuperar o Remédio de Arugal, os agentes Renegados fornecem a Tessalba o arcano fundamental necessário para conter a ameaça crescente de Arugal e proteger Pinhaprata para a Dama Sylvana."}},faq={{q="O que é o Remédio de Arugal?",a="É uma fórmula mágica escrita pelo mago renegado Arugal. Em vez de uma poção curativa, trata-se de um feitiço escrito contendo as técnicas arcanas que ele utilizou quando começou a experimentar a magia dos worgens na Floresta de Pinhaprata.",al={"o que é remédio de arugal","item remédio de arugal","feitiço do remédio"}},{q="Onde o Remédio foi deixado para trás?",a="Arugal o deixou dentro de um conjunto de grimórios empoeirados no andar superior de uma fazenda de trigo abandonada, localizada logo ao norte da ponte que cruza o rio na Floresta de Pinhaprata.",al={"onde encontrar remédio de arugal","localização remédio de arugal","grimório da fazenda"}},{q="Por que Dalar Tessalba quer este feitiço?",a="Dalar Tessalba busca analisar a magia específica empregada por Arugal para que os Renegados possam desenvolver defesas contra ela, esperando voltar os próprios métodos do feiticeiro contra ele para proteger a região.",al={"por que dalar quer o remédio","remédio dalar tessalba"}},{q="Quem guarda os grimórios na fazenda?",a="A fazenda está infestada com os lacaios lupinos de Arugal. Quando alguém tenta mexer nos grimórios empoeirados no segundo andar, um Moonrage Darkrunner salta das sombras para defender os pertences de seu mestre.",al={"o que ataca na fazenda","emboscada do grimório"}}},fx={["157696b2"]={q="De onde vem o Remédio de Arugal e quem o fez?",a="O Remédio de Arugal é um encantamento escrito pelo próprio Arquimago Arugal durante seus primeiros dias na Floresta de Pinhaprata. Depois que seus planos começaram a se desenrolar, ele residiu brevemente em uma fazenda de trigo ao norte da ponte principal do rio, deixando para trás livros de feitiços empoeirados contendo sua pesquisa.",al={"quem fez o remédio de arugal","origem do remédio de arugal","de onde veio o remédio de arugal"}}},fp="16,96,18.379.0,17.375.0,29.124.0,33.136.0,42.113.0,38.171.0"}
P.entries["item:rendered-spores"] = {n="Esporos Entregues",s="Esporos Entregues são uma emulsão volátil preparada a partir de amostras de fungos coletadas por todos os Sertões. Criada pelo Boticário Hermógenes na Encruzilhada, a mistura se decompõe rapidamente, a menos que seja entregue prontamente ao Apothecary Zamah sob o Penhasco do Trovão para estabilização.",h="Esporos Entregues são uma emulsão volátil preparada a partir de amostras de fungos coletadas por todos os...",kw={"boticário hermógenes","apothecary zamah","sertões","encruzilhada","emulsão","poços das visões","esporos entregues","penhasco do trovão"},ang={["race:Tauren"]="A presença de boticários Renegados experimentando com a estranha flora dos Sertões dentro dos sagrados Poços das Visões reflete a aliança tensa e prática forjada dentro do Penhasco do Trovão.",["race:Undead"]="A Sociedade Real de Boticários busca constantemente novos compostos biológicos por toda Kalimdor para ajudar os Renegados, contando com mensageiros rápidos para conectar pesquisadores de campo, como Hermógenes, com especialistas de laboratório, como Zamah."},sec={{t="Uma Mistura Volátil",b="Após adquirir estranhos Esporos de Fungos de cogumelos perto dos oásis úmidos dos Sertões, o Boticário Hermógenes os processa em uma emulsão química ativa conhecida como Esporos Entregues. A extração delicada suspende os compostos potentes dos crescimentos fúngicos em um meio líquido, mas a solução é quimicamente instável. Ela mantém sua potência vital por apenas quarenta e cinco minutos antes de se decompor e se tornar completamente inútil para estudo científico."},{t="Entrega nos Poços das Visões",b="Como Hermógenes não possui as instalações necessárias ou tempo em seu posto avançado remoto para concluir o processo de refino, a emulsão deve ser levada às pressas diretamente para sua colega Renegada, Apothecary Zamah. Escondida nos subterrâneos Poços das Visões, abaixo do Platô dos Espíritos no Penhasco do Trovão, Zamah possui o equipamento especializado e os reagentes necessários para selar novamente e finalizar o processamento dos esporos para a Sociedade Real de Boticários."}},faq={{q="Para que servem os Esporos Entregues?",a="Eles são matéria fúngica extraída pelo Boticário Hermógenes e transformada em uma emulsão para pesquisa pela Sociedade Real de Boticários. Apothecary Zamah usa a mistura potente no Penhasco do Trovão para continuar sua investigação sobre os estranhos crescimentos que se espalham pelos Sertões.",al={"objetivo dos esporos entregues","o que zamah faz com os esporos","por que esporos entregues"}},{q="Por que a emulsão tem um limite de tempo?",a="A emulsão química criada por Hermógenes é altamente volátil e começa a se decompor assim que é misturada. Sua potência ativa dura apenas quarenta e cinco minutos, exigindo que um mensageiro a transporte rapidamente pelas planícies até o Penhasco do Trovão antes que se torne inerte.",al={"por que os esporos entregues têm tempo","por que os esporos expiram","duração dos esporos entregues"}},{q="Quem criou esses esporos?",a="O Boticário Hermógenes, um pesquisador Renegado estacionado na Encruzilhada nos Sertões, transformou Esporos de Fungos crus coletados de cogumelos perto dos oásis neste composto líquido instável.",al={"quem fez os esporos entregues","quem entrega os esporos","esporos de hermógenes"}},{q="Para onde a mistura precisa ir?",a="Os esporos devem ser entregues à Apothecary Zamah. Ela reside profundamente dentro dos Poços das Visões, um sistema de cavernas escondido sob o Platô dos Espíritos na capital tauren de Penhasco do Trovão.",al={"onde levar os esporos entregues","localização de zamah","localização dos poços das visões"}}},fx={["7897c588"]={q="O que são Esporos Entregues?",a="Esporos Entregues são o extrato processado de estranhos crescimentos fúngicos colhidos nos Sertões. O Boticário Hermógenes ferveu e processou os esporos brutos em uma emulsão líquida volátil e instável, preparando cuidadosamente a mistura para posterior estudo alquímico pela Real Sociedade de Boticários.",al={"o que são esporos entregues","informações sobre esporos entregues","o que são os esporos entregues"}}},fp="15,153,18.219.0,31.310.0,34.217.0,40.211.0,25.134.0,34.120.0"}
P.entries["item:renferrel-s-findings"] = {n="Achados de Renferrel",s="Achados de Renferrel é uma coleção de notas de pesquisa compiladas pelo Boticário Renferrel na Floresta de Pinhaprata. Confiados a mensageiros da Horda, esses documentos transportam dados vitais para o sul, destinados ao Boticário Lindolfo na Serraria Tarren, a fim de ajudar na criação da Nova Peste dos Renegados.",h="Achados de Renferrel é uma coleção de notas de pesquisa compiladas pelo Boticário Renferrel na Floresta de...",kw={"achados","lindolfo","nova peste","renferrel","real sociedade de boticários","o sepulcro","serraria tarren"},ang={["faction:Horde"]="Os mensageiros que transportam os papéis de Renferrel ajudam a consolidar a presença da Horda em Lordaeron, conectando postos avançados isolados como O Sepulcro e a Serraria Tarren.",["race:Undead"]="A pesquisa contida nesses documentos atende à ambição máxima de Sylvana Correventos: aperfeiçoar Uma nova peste para erradicar tanto o Flagelo quanto os inimigos vivos que avançam sobre as terras dos Renegados."},sec={{t="Uma peste em desenvolvimento",b="A Real Sociedade de Boticários trabalha incansavelmente sob ordens diretas da Dama Sombria, Grande Dama Sylvana Correventos, para criar uma Nova Peste. Alcançar esse avanço exige colaboração constante entre pesquisadores espalhados por Lordaeron. Alocado n'O Sepulcro, na Floresta de Pinhaprata, o Boticário Renferrel compila esses achados para documentar seu progresso e experimentos, enviando os dados reunidos para o sul até a Serraria Tarren para que outros pesquisadores possam se basear em seus resultados."},{t="Para a Serraria Tarren",b="Levar esses papéis pela fronteira de Pinhaprata até o Contraforte de Eira dos Montes representa um elo vital na rede alquímica dos Renegados. Na Serraria Tarren, o Boticário Lindolfo aguarda ansiosamente as notas de Renferrel para cruzar referências e avançar suas próprias misturas contra os vivos e o Flagelo. Sem mensageiros confiáveis percorrendo as estradas contestadas de Eira dos Montes, a pesquisa descentralizada da Sociedade logo estagnaria."}},faq={{q="O que há dentro dos Achados de Renferrel?",a="O pacote contém os dados experimentais e as notas de pesquisa mais recentes reunidos pelo Boticário Renferrel durante seu trabalho na Floresta de Pinhaprata, especificamente relacionados à síntese de Uma nova peste para os Renegados.",al={"o que são os achados","pesquisa de renferrel","o que está nas notas"}},{q="Quem deve receber essa pesquisa?",a="O Boticário Lindolfo recebe os documentos. Ele conduz pesquisas sobre a peste na Serraria Tarren, um assentamento dos Renegados situado no Contraforte de Eira dos Montes.",al={"quem recebe os achados de renferrel","para onde vão os achados","alvo de entrega"}},{q="Por que os boticários estão compartilhando notas?",a="Grande Dama Sylvana Correventos colocou imensa pressão sobre a Real Sociedade de Boticários para inventar Uma nova peste. Os boticários acreditam que seu avanço chegará muito mais rápido se coordenarem e compararem resultados em vez de trabalharem isolados.",al={"por que compartilhar achados","por que enviar para lindolfo","comunicação dos boticários"}},{q="Onde o Boticário Renferrel conduz seus experimentos?",a="O Boticário Renferrel está instalado n'O Sepulcro, o principal posto avançado dos Renegados situado no coração da Floresta de Pinhaprata.",al={"onde está renferrel","localização do boticário renferrel","quem escreveu os achados de renferrel"}}},fx={f680c460={q="O que são os Achados de Renferrel?",a="Os Achados de Renferrel são uma coleção de notas alquímicas e documentos de pesquisa compilados pelo Boticário Renferrel. Eles detalham seus experimentos contínuos conduzidos em nome da Real Sociedade de Boticários, destinados a serem compartilhados diretamente com seus colegas praticantes em Lordaeron.",al={"o que são os achados de renferrel","item achados de renferrel","o que são estes achados"}},bf8d559a={q="De onde vêm os Achados de Renferrel e quem os fez?",a="Estes documentos foram escritos pelo Boticário Renferrel, um pesquisador ambicioso estacionado n'O Sepulcro na Floresta de Pinhaprata. Trabalhando diligentemente sob o mandato dos Renegados, ele escreveu estas notas para registrar seu progresso e avanços na composição de misturas experimentais.",al={"quem escreveu os achados de renferrel","de onde vieram os achados de renferrel","criador dos achados de renferrel"}},["21b2c0f4"]={q="Por que alguém quer os Achados de Renferrel?",a="A Real Sociedade de Boticários enfrenta uma imensa pressão da Grande Dama Sylvana Correventos para inventar uma Nova Praga. Acreditando que a colaboração acelerará seu trabalho sombrio, Renferrel enviou sua pesquisa para o Boticário Lindolfo na Serraria Tarren, que está ansioso para estudar os métodos de seu colega e integrá-los aos seus próprios esforços.",al={"por que entregar os achados de renferrel","quem quer os achados de renferrel","por que lindolfo quer os achados de renferrel"}}},fp="20,209,23.354.0,14.377.0,36.173.0,41.139.0,39.189.0,56.127.0"}
P.entries["item:report-on-the-defias-brotherhood"] = {n="Relatório sobre a Irmandade Défias",s="Na Bastilha Ventobravo, as descobertas sobre a Irmandade Défias chegam à corte real. O arquiteto da cidade, Baros Aleixo, confia o relatório ao aventureiro que descobriu a conspiração.",h="Na Bastilha Ventobravo, as descobertas sobre a Irmandade Défias chegam à corte real.",kw={"audiência com o rei","baros aleixo","défias","relatório","bastilha ventobravo","vancleef","cerro oeste"},ang={["faction:Alliance"]="A entrega do relatório leva à corte real a longa luta para proteger Cerro Oeste e alertar os líderes de Ventobravo sobre a insurreição nas fronteiras do reino.",["race:Human"]="Como humano do reino, você carrega um relatório sobre o conflito ainda sem solução entre a casa nobre de Ventobravo e os pedreiros que reconstruíram a cidade."},sec={{t="Um Despacho para o Trono",b="O arquiteto da cidade, Baros Aleixo, preparou o relatório para os líderes de Ventobravo após uma longa investigação sobre a agitação em Cerro Oeste e nas terras vizinhas. Ele o confiou ao aventureiro que desvendou a conspiração.\n\nO relatório é levado à Bastilha Ventobravo para uma audiência pessoal. Ali, as descobertas dizem respeito aos planos dos conspiradores e ao perigo que representam para o reino."},{t="Recepção na Bastilha",b="O rei Varian Wrynn está em uma viagem diplomática quando o mensageiro chega à sala do trono. Os conselheiros reais e a regência que governa em nome do menino-rei Anduin recebem o relatório em seu lugar. Eles elogiam o mensageiro por impedir os planos de VanCleef.\n\nLady Katrana Prestor está entre as figuras da corte presentes quando os alertas chegam à regência."}},faq={{q="O que é o Relatório sobre a Irmandade Défias?",a="O relatório é um informe oficial de Baros Aleixo. Ele reúne informações sobre Edwin VanCleef, seu exército subterrâneo e a conspiração mais ampla dos Défias contra Ventobravo.",al={"o que é este relatório","item relatório défias","relatório de baros aleixo"}},{q="Quem escreveu este relatório?",a="O arquiteto da cidade de Ventobravo, Baros Aleixo, preparou o relatório. Ele trabalhou ao lado dos pedreiros antes que eles se separassem para formar a Irmandade Défias.",al={"quem fez o relatório défias","autor do relatório"}},{q="Por que estou entregando isso na Bastilha Ventobravo?",a="Baros Aleixo acredita que o aventureiro que descobriu a conspiração merece apresentar as descobertas ao trono. Ele espera que você receba o reconhecimento da realeza por proteger o reino.",al={"por que entrego isso","entrega audiência com o rei"}},{q="O Rei Varian lê o relatório?",a="Não. O rei Varian Wrynn está em uma viagem diplomática quando você chega à Bastilha Ventobravo. Sua corte e a regência recebem o relatório em seu lugar.",al={"o rei lê isso","audiência com varian wrynn"}}},fp="32,178,25.367.0,21.337.1,45.170.1,22.160.1,43.182.0,33.138.0"}
P.entries["item:resonite-crystal"] = {n="Cristal de Ressonita",s="Cristais de Ressonita são amostras minerais raras extraídas por kobolds dentro da Caverna da Avalanche, na Cordilheira das Torres de Pedra. A escavação frenética deles atraiu a preocupação de Mor'rogal no Retiro Rocha do Sol.",h="Cristais de Ressonita são amostras minerais raras extraídas por kobolds dentro da Caverna da Avalanche, na...",kw={"avalanche","cristal","terranos","kobold","mor'rogal","ressonita","cordilheira das torres de pedra","titãs"},ang={["class:Shaman"]="Os Cristais de Ressonita carregam uma ressonância perturbadora para os xamãs, que conseguem reconhecer a magia da terra primordial e dormente deixada pelas criações dos Titãs há muito enterradas sob as montanhas.",["profession:Mining"]="Diferente de veios comuns de cobre ou estanho, a Ressonita é uma formação mineral intensamente concentrada cuja extração requer avançar além de kobolds agressivos até os estratos subterrâneos mais profundos."},sec={{t="Ressonância Ancestral",b="Escondidos nas profundezas da Ravina da Avalanche, os Cristais de Ressonita tornaram-se o ponto focal da escavação repentina e frenética dos kobolds. Embora mineradores comuns de cavernas geralmente busquem minérios mundanos ou bugigangas brilhantes, a obsessão dos kobolds por essas formações específicas alarmou imediatamente os xamãs do Retiro Rocha do Sol. Após um exame minucioso, as pedras vibram com uma sutil ressonância mágica ligada à formação primordial do mundo. Mor'rogal identificou essas energias tênues como vestígios de magia dos Terranos, indicando que as criaturas escavadoras invadiram uma camada ancestral moldada pelos Titãs."},{t="Explorando a Terra",b="A descoberta da Ressonita confirma notícias preocupantes para a presença da Horda na Cordilheira das Torres de Pedra: os escavadores kobolds cavaram fundo o suficiente para perturbar os ancestrais Terranos. Como os Terranos foram moldados diretamente pelos Titãs para esculpir e moldar as fundações do mundo, a magia residual apega-se obstinadamente à rocha ao redor. Ao coletar esses cristais, os agentes da Horda esperam decifrar as intenções frenéticas dos kobolds e voltar o próprio poder da pedra encantada contra quaisquer forças adormecidas que tenham sido perturbadas abaixo."}},faq={{q="Onde os Cristais de Ressonita são encontrados?",a="Os Cristais de Ressonita são encontrados dentro da Caverna da Avalanche, uma caverna profunda localizada na Ravina da Avalanche, no sudeste da Cordilheira das Torres de Pedra.",al={"localização da ressonita","onde conseguir ressonita","farm de cristal de ressonita"}},{q="Por que os kobolds estão minerando Cristais de Ressonita?",a="Os kobolds estão minerando freneticamente os cristais raros, mas Mor'rogal ainda não sabe o motivo. Ele pede amostras e uma investigação das profundezas da caverna para entender a atividade deles.",al={"por que kobolds minerando","plano dos cristais dos kobolds","kobolds da avalanche"}},{q="Que tipo de poder há em um Cristal de Ressonita?",a="Mor'rogal suspeita que os cristais estejam conectados a algo preocupante sob as montanhas. Sua natureza mágica é identificada depois que amostras e notícias da caverna chegam até ele.",al={"magia do cristal de ressonita","o que é ressonita","a ressonita é mágica"}},{q="Quem está estudando esses cristais?",a="Mor'rogal, um tauren posicionado no Retiro Rocha do Sol na Cordilheira das Torres de Pedra, investiga os cristais para entender o aumento repentino na atividade dos kobolds e encontrar uma maneira de combater qualquer mal que tenha sido descoberto.",al={"quem quer ressonita","cristais de mor'rogal","ressonita do retiro rocha do sol"}},{q="O que são os Terranos mencionados em conexão com o cristal?",a="Os Terranos são criaturas que teriam sido criadas pelos Titãs para moldar a terra. Sua possível conexão com a Ressonita é investigada durante a missão de Mor'rogal.",al={"o que são os terranos","conexão dos terranos com os titãs"}}},fx={c14b6c8c={q="O que é Cristal de Ressonita?",a="Ressonita é um cristal mineral raro encontrado na Caverna da Avalanche na Cordilheira das Torres de Pedra. A mineração frenética dos kobolds alarmou Mor'rogal, que solicita amostras e notícias da caverna para investigar.",al={"o que é ressonita","lore cristal de ressonita","minério de ressonita"}},af246400={q="Por que alguém quer o Cristal de Ressonita?",a="Mor'rogal quer amostras de minério para entender a mineração frenética dos kobolds e aprender o que está sob a Ravina da Avalanche. Ele pede a um aventureiro que explore a caverna, além de coletar os cristais.",al={"por que coletar cristais de ressonita","quem quer o cristal de ressonita","propósito do cristal de ressonita"}}},fp="16,131,17.290.1,17.334.1,34.123.0,45.172.0,44.170.0,31.194.0,60.129.0"}
P.entries["item:restabilization-cog"] = {n="Roda de Reestabilização",s="Rodas de Reestabilização são componentes mecânicos de precisão saqueados dos gnomos leprosos que vagam do lado de fora das ruínas irradiadas de Gnomeregan. Em Kharanos, engenhoqueiros gnomos precisam dessas peças intactas para construir o Recombobulador, uma máquina ambiciosa destinada a reverter a mutação leprosa.",h="Rodas de Reestabilização são componentes mecânicos de precisão saqueados dos gnomos leprosos que vagam do...",kw={"dun morogh","gibblewilt","gnomeregan","kharanos","gnomo leproso","operation recombobulation","razzle molavivaz","roda de reestabilização"},ang={["profession:Engineering"]="As tolerâncias precisas das Rodas de Reestabilização destacam o design gnômico clássico, construído para resistir ao atrito volátil e equilibrar conjuntos mecânicos delicados como o Recombobulador.",["race:Gnome"]="Para os gnomos exilados em Dun Morogh, recuperar esses componentes é um dever sombrio: retirar maquinário de irmãos corrompidos na esperança desesperada de construir uma cura para os caídos de Gnomeregan."},sec={{t="Componentes para uma Cura",b="Quando a radiação inundou Gnomeregan em uma tentativa desastrosa de aniquilar os troggs invasores, incontáveis gnomos foram transformados em gnomos leprosos doentios e hostis. Apesar de sua loucura, esses exilados afligidos ainda carregam maquinários gnômicos complexos e peças reaproveitáveis. Os engenhoqueiros Ozzie Mudavolt e Razzle Molavivaz acreditam que a terrível transformação pode ser sistematicamente desfeita. Para concluir o protótipo do Dispositivo de Recombobulação, eles contam com aventureiros para recuperar peças vitais diretamente dos afligidos do lado de fora dos portões de Gnomeregan, incluindo Rodas de Reestabilização intactas para equilibrar os sistemas de combustão interna da máquina."}},faq={{q="Para que serve uma Roda de Reestabilização?",a="Rodas de Reestabilização são necessárias para o engenhoqueiro Razzle Molavivaz em Kharanos. Juntamente com Gyromechanic Gears, elas servem como peças estruturais cruciais para a construção do Recombobulador, uma invenção experimental projetada para curar gnomos leprosos irradiados.",al={"propósito da roda","o que a roda de reestabilização faz","por que coletar rodas"}},{q="Onde essas rodas podem ser encontradas?",a="Elas são carregadas pelos enlouquecidos gnomos leprosos e pelo transtornado Gibblewilt, que vagam pelos portões externos e trincheiras do lado de fora de Gnomeregan, no oeste de Dun Morogh.",al={"localização da roda de reestabilização","quem saqueia rodas","onde obter rodas"}},{q="O Recombobulador pode realmente curar os gnomos leprosos?",a="Razzle Molavivaz e Ozzie Mudavolt estão confiantes de que maquinários calibrados corretamente podem reverter a mutação. No entanto, a engenharia gnômica é notoriamente volátil, e se o Recombobulador pode verdadeiramente restaurar as mentes e corpos do seu povo continua sendo um esforço contínuo e não testado.",al={"o recombobulador funciona","existe cura para gnomos leprosos"}}},fx={["8ac7e8f1"]={q="O que é uma Roda de Reestabilização?",a="Uma Roda de Reestabilização é um componente mecânico de precisão recuperado das máquinas caídas e dos gnomos leprosos irradiados que vagam fora da cidade em ruínas de Gnomeregan. Projetadas para manter o equilíbrio estrutural e rotacional em dispositivos gnomos complexos, essas rodas são valorizadas por engenheiros que procuram peças robustas e pré-usinadas para estabilizar invenções temperamentais como o Recombobulador de Ozzie Mudavolt.",al={"o que é roda de reestabilização","lore roda de reestabilização","sobre roda de reestabilização"}},ceb0040c={q="De onde vêm as Rodas de Reestabilização?",a="Estas rodas se originam das vastas obras mecânicas de Gnomeregan. Quando a cidade foi evacuada após a desastrosa ventilação de radiação, inúmeros dispositivos automatizados e os trágicos sobreviventes que sucumbiram à loucura leprosa levaram esses componentes padronizados para a neve fora dos portões.",al={"quem fez a roda de reestabilização","origem da roda de reestabilização","de onde veio a roda de reestabilização"}}},fp="19,156,21.476.0,39.203.0,30.142.0,54.220.0"}
P.entries["item:rin-ji-s-secret-quest-item"] = {n="Rin'ji's Secret",s="Nas Terras Agrestes, uma tabuleta com inscrições dos trolls Witherbark pode esconder algo valioso. Pedem a Urraca Convulserpe, no Distrito da Magia da Cidade Baixa, que a decifre.",h="Nas Terras Agrestes, uma tabuleta com inscrições dos trolls Witherbark pode esconder algo valioso.",kw={"terras agrestes","distrito da magia","urraca convulserpe","rin'ji","rinji","segredo","tabuleta","troll","cidade baixa","witherbark"},ang={["race:Troll"]="A tabuleta traz inscrições dos Witherbark, então seu mistério envolve a história e a tradição de uma tribo troll."},sec={{t="Inscrições de Trolls",b="Rin'ji's Secret é uma tabuleta encontrada entre os problemas das Terras Agrestes. Sua superfície traz inscrições dos trolls Witherbark, e seu significado é desconhecido. Urraca Convulserpe, estudiosa dos Witherbark na Cidade Baixa, talvez consiga lê-la."}},faq={{q="O que é Rin'ji's Secret?",a="Rin'ji's Secret é uma tabuleta coberta de inscrições dos trolls Witherbark. Seu significado é um mistério.",al={"segredo de rinji","tabuleta de rin'ji","o que é a tabuleta"}},{q="Quem pode ler a tabuleta?",a="Urraca Convulserpe, estudiosa dos trolls Witherbark no Distrito da Magia da Cidade Baixa, talvez consiga decifrar a tabuleta.",al={"quem decifra","tabuleta de oran","estudiosa do distrito da magia"}},{q="De onde veio a tabuleta?",a="A tabuleta está ligada aos problemas de Rin'ji nas Terras Agrestes.",al={"onde foi encontrada","tabuleta das terras agrestes","localização de rinji"}},{q="Rin'ji's Secret tem valor?",a="A tabuleta pode ser valiosa, mas seu valor é incerto até que suas inscrições sejam compreendidas.",al={"valor da tabuleta","tabuleta valiosa","valor de rin'ji's secret"}}},fp="15,166,14.245.0,24.91.0,24.114.0,25.59.0,28.89.0"}
P.entries["item:ring-of-zoram"] = {n="Anel de Zoram",s="O Anel de Zoram é uma relíquia Kaldorei antiga que remonta aos dias de glória da cidade submersa de Zoram antes da Grande Cisão. Uma vez usado pelos governantes da cidade e sendo a chave para a antiga fechadura de uma estatueta submersa, ele caiu recentemente nas mãos dos naga que invadem o litoral.",h="O Anel de Zoram é uma relíquia Kaldorei antiga que remonta aos dias de glória da cidade submersa de Zoram...",kw={"estatueta ancestral","vale gris","lady vespia","anel de zoram","ruuzel","talen","praia de zoram"},ang={["faction:Alliance"]="Recuperar o anel dos naga ajuda o estudioso elfo noturno Talen a recuperar a história kaldorei roubada ao longo das fronteiras contestadas de Vale Gris.",["race:NightElf"]="O anel representa um pedaço tangível da herança pré-Cisão de uma era antes que o império Kaldorei fosse despedaçado pela arrogância arcana e pelos mares que o afogaram."},sec={{t="Anel da Cidade Submersa",b="Antes que a Nascente da Eternidade entrasse em colapso e os oceanos engolissem as extensões ocidentais de Kalimdor, Zoram era uma joia costeira do império dos elfos noturnos. O Anel de Zoram pertencia aos governantes da cidade, e um código estranho está escrito na sua banda interna no idioma dos elfos noturnos. Quando a Grande Cisão despedaçou o continente dez mil anos atrás, o anel afundou junto com a cidade, perdido sob as marés agitadas do que é hoje a Praia de Zoram."},{t="Recuperação pelos Naga",b="Por milênios, o anel permaneceu enterrado sob lodo e ruínas até que os naga começassem a vasculhar o litoral de Vale Gris. Ruuzel, um líder naga que habita em um ilhéu na costa norte, descobriu o artefato entre os escombros submersos. Estudiosos como o elfo noturno Talen buscam o anel não apenas por sua antiguidade, mas porque ele funciona como a única chave capaz de abrir outras relíquias resgatadas das profundezas, incluindo antigas estatuetas seladas recuperadas do fundo do mar."}},faq={{q="Para que serve o Anel de Zoram?",a="O anel pertencia aos governantes de Zoram antes da Cisão afogar a cidade, e é a chave para uma fechadura antiga. Nos dias atuais, Talen busca o anel especificamente para abrir uma Estatueta Ancestral trancada, recuperada das ruínas submersas.",al={"objetivo anel de zoram","o que o anel faz","história anel de zoram"}},{q="Quem possui o Anel de Zoram?",a="O anel foi dragado das ruínas pelos naga costeiros que invadiram a Praia de Zoram. Ele é mantido principalmente pelo líder deles, Ruuzel, em uma ilha na costa norte, embora outra naga proeminente chamada Lady Vespia também tenha sido vista com ele.",al={"quem tem o anel","drop anel de zoram","onde conseguir anel de zoram"}},{q="Por que Talen quer o anel?",a="Talen busca descobrir os segredos da Estatueta Ancestral recuperada da Praia de Zoram. Sem o Anel de Zoram agindo como sua chave, o mecanismo antigo da estatueta não pode ser aberto.",al={"por que talen quer o anel","missão do anel de talen"}},{q="Para onde foi a cidade de Zoram?",a="Zoram era uma antiga cidade dos elfos noturnos que ficava ao longo da borda ocidental de Kalimdor antes da Grande Cisão dez mil anos atrás. Quando a Nascente da Eternidade implodiu, a cidade foi destruída e afogada sob as ondas, deixando para trás apenas a Praia de Zoram.",al={"o que aconteceu com zoram","história da cidade de zoram"}}},fx={["7e40c0d5"]={q="O que é o Anel de Zoram?",a="O Anel de Zoram é uma relíquia antiga usada uma vez pelos governantes da cidade submersa de Zoram, antes que as ondas da Grande Fragmentação a afogassem. Um código estranho está escrito dentro da banda na língua dos elfos noturnos, e o anel é a chave para a antiga fechadura de uma estatueta recuperada das ruínas.",al={"o que é anel de zoram","lore anel de zoram","item anel de zoram"}},["770adfa7"]={q="De onde vem o Anel de Zoram e quem o fez?",a="O anel se origina da cidade dos elfos noturnos de Zoram, anterior à Fragmentação, ao longo da costa da antiga Kalimdor. Pertencia aos governantes da cidade antes que maremotos cataclísmicos afogassem Zoram há dez mil anos, deixando a relíquia perdida no mar até que os nagas a dragassem recentemente das ruínas.",al={"origem do anel de zoram","quem fez o anel de zoram","de onde veio o anel de zoram"}}},fp="13,163,23.386.0,23.375.0,35.192.0,32.200.0,29.173.0,31.228.0"}
P.entries["item:robo-mechanical-guts"] = {n="Robo-Mechanical Guts",s="Robo-Mechanical Guts são peças, conduítes e partes internas de máquinas recuperáveis, colhidos dos construtos defeituosos que vagam pelas ruínas de Gnomeregan. Engenheiros gnômicos em Ventobravo precisam desses componentes específicos para consertar veículos de escavação pesada destinados a ajudar na recuperação de Gnomeregan em Dun Morogh.",h="Robo-Mechanical Guts são peças, conduítes e partes internas de máquinas recuperáveis, colhidos dos construtos...",kw={"relojoaria","dun morogh","gnomeregan","gyrodrillmatic excavationators","robo-mechanical guts","shoni","ventobravo"},ang={["profession:Engineering"]="Cada emaranhado de fiação e engrenagem giroscópica recuperado serve como um lembrete do auge do design automatizado dos gnomos, agora tragicamente tornado selvagem pela radiação e pelo isolamento.",["race:Gnome"]="Desmontar as sentinelas de relojoaria rebeldes do seu lar perdido é agridoce, mas reaproveitar seu maquinário interno fornece as peças tangíveis necessárias para recuperar Gnomeregan."},sec={{t="Sucata para a Frota",b="Quando o Grão-faz-tudo Gelbin Mekkatorque e os gnomos sobreviventes evacuaram Gnomeregan, milhares de mecanismos automatizados, sentinelas de relojoaria e robôs industriais foram abandonados lá dentro. Nas consequências radioativas da cidade, essas máquinas continuam a vagar pelos corredores autonomamente. Na cidade de Ventobravo, a faz-tudo Shoni busca montar uma frota de Gyrodrillmatic Excavationators para romper as defesas de Gnomeregan e recuperar a cidade perdida. Sem matérias-primas frescas, ela encarrega aventureiros corajosos de enfrentar os salões contaminados de Gnomeregan para extrair vísceras robóticas funcionais — molas, fios e componentes de giroscópio — para reequipar as máquinas de escavação."}},faq={{q="Para que servem os Robo-Mechanical Guts?",a="Eles são coletados por Shoni na cidade de Ventobravo para consertar uma frota de Gyrodrillmatic Excavationators — veículos de tunelamento especializados destinados a apoiar operações para recuperar Gnomeregan em Dun Morogh.",al={"para que servem as vísceras de robô","uso de robo-mechanical guts","por que coletar vísceras mecânicas"}},{q="Onde encontrar esses componentes?",a="Eles podem ser coletados dos vários autômatos de relojoaria hostis, mechas e inimigos contaminados que vagam tanto pelos arredores quanto pelas profundezas de Gnomeregan.",al={"onde conseguir robo mechanical guts","local de coleta de vísceras de robô","peças de robô de gnomeregan"}},{q="Quem é Shoni e por que ela precisa de tantas peças?",a="Shoni é uma engenheira gnomo ambiciosa estacionada no Distrito dos Anões de Ventobravo. Ela está encarregada de preparar toda uma divisão de máquinas de escavação subterrânea — quase quatrocentas no total — para romper as ruínas ocupadas de Gnomeregan.",al={"quem é shoni","shoni ventobravo","frota de gyrodrillmatic excavationators"}}},fx={b1d0efc3={q="O que são Robo-Mechanical Guts?",a="São as máquinas internas emaranhadas, engrenagens, fiação e componentes mecânicos recuperáveis retirados dos autômatos de corda que vagam por Gnomeregan. Embora sejam pouco mais que sucata para os olhos destreinados, essas entranhas funcionais fornecem mecanismos brutos cruciais que engenheiros gnomos engenhosos podem reaproveitar para projetos veiculares complexos.",al={"o que são robo-mechanical guts","item robo mechanical guts","o que são robo guts"}},cf2ae288={q="De onde vêm as Robo-Mechanical Guts e quem as fez?",a="Estes conjuntos se originaram nas oficinas de Gnomeregan, criados por inventores gnomos para alimentar sua força de trabalho automatizada e as defesas da cidade. Quando o desastre irradiado atingiu e o Alto Inventalorde Mekkatorque ordenou a evacuação, inúmeras construções mecânicas foram abandonadas lá dentro, onde continuam vagando pelas passagens em ruínas com seu funcionamento interno ainda intacto.",al={"quem fez as robo-mechanical guts","de onde vêm as robo mechanical guts","origem das robo mechanical guts"}},f52d09f9={q="Por que alguém quer as Robo-Mechanical Guts?",a="Shoni, a Shilenchiosa em Ventobravo, precisa desesperadamente delas como componentes de reposição para reparar toda uma frota de Gyrodrillmatic Excavationators. Com suprimentos limitados na capital humana, ela recorre aos mechs rebeldes em Gnomeregan como um abundante depósito de sucata para manter sua frota de engenharia operacional.",al={"por que coletar robo-mechanical guts","quem quer as robo mechanical guts","por que shoni quer as robo mechanical guts"}}},fp="20,161,21.513.0,39.171.0,35.145.0,49.191.0"}
P.entries["item:roc-gizzard"] = {n="Roc Gizzard",s="As Roc Gizzards vêm dos rocs de Tanaris. Nas Terras Agrestes, Rhapsody Shindigger precisa de três para preparar uma bebida forte.",h="As Roc Gizzards vêm dos rocs de Tanaris.",kw={"fire roc","kalimdor kocktail","rhapsody shindigger","roc","roc gizzard","searing roc","tanaris"},sec={{t="Uma bebida mais forte",b="Rhapsody Shindigger, nas Terras Agrestes, pede que você leve a ele três Roc Gizzards de Tanaris. Ele precisa delas para preparar um Kalimdor Kocktail, junto com fígados de Feralas. Rhapsody diz que a bebida vai ajudá-lo a falar sobre um voo assustador sobre um pântano."}},faq={{q="De onde vêm as Roc Gizzards?",a="Rocs, Fire Rocs e Searing Rocs de Tanaris fornecem Roc Gizzards.",al={"localização de roc gizzard","onde encontrar gizzards","partes de roc de tanaris"}},{q="Quem precisa de Roc Gizzards?",a="Rhapsody Shindigger, nas Terras Agrestes, precisa de três Roc Gizzards para seu Kalimdor Kocktail.",al={"quem quer roc gizzards","roc gizzard de rhapsody","gizzards para quem"}},{q="O que é um Kalimdor Kocktail?",a="É uma bebida forte que Rhapsody Shindigger pretende preparar com Roc Gizzards e fígados de Feralas.",al={"bebida de rhapsody","que bebida precisa de gizzards","coquetel de kalimdor"}},{q="Por que Rhapsody quer a bebida?",a="Rhapsody diz que precisa de algo forte antes de conseguir falar sobre um voo assustador sobre um pântano.",al={"por que rhapsody precisa de bebida","o que faz ele falar","história do pântano de rhapsody"}}},fp="11,115,16.246.0,32.64.0,23.90.0,28.97.0,33.97.0"}
P.entries["item:rock-elemental-shard"] = {n="Rock Elemental Shard",s="Fragmentos de Elemental de Pedra são pedaços coletados de elementais de pedra nos Ermos. Jarkal Limuno precisa deles entre vários reagentes para reabastecer seu estoque de alquimia.",h="Fragmentos de Elemental de Pedra são pedaços coletados de elementais de pedra nos Ermos.",kw={"reagentes de alquimia","ermos","jarkal limuno","karrath","fragmento de elemental de pedra","elementais de pedra"},ang={["faction:Horde"]="Como membro da Horda, você pode levar os reagentes dos Ermos para Jarkal Limuno, em Karrath, onde ele oferece moedas por eles."},sec={{t="Reagentes de Pedra",b="Em Karrath, Jarkal Limuno pede cinco Fragmentos de Elemental de Pedra, além de moelas de abutre e presas de coiote das rochas. Ele é um alquimista que busca reabastecer seu estoque e promete moedas pelos reagentes coletados."}},faq={{q="Para que servem os Fragmentos de Elemental de Pedra?",a="Jarkal Limuno, em Karrath, precisa de cinco Fragmentos de Elemental de Pedra para reabastecer seu estoque de alquimia.",al={"uso dos fragmentos","por que os fragmentos","do que jarkal precisa"}},{q="De onde vêm os Fragmentos de Elemental de Pedra?",a="Os Fragmentos de Elemental de Pedra vêm de elementais de pedra nos Ermos.",al={"origem dos fragmentos","onde encontrar fragmentos","conseguir fragmentos de pedra"}},{q="Quem quer os fragmentos?",a="Jarkal Limuno, um alquimista em Karrath, pede cinco Fragmentos de Elemental de Pedra.",al={"quem precisa dos fragmentos","fragmentos para jarkal","quem é jarkal"}},{q="Do que mais Jarkal precisa?",a="Jarkal também pede cinco moelas de abutre e dez presas de coiote das rochas.",al={"outros reagentes","o que jarkal precisa","moelas e presas"}}},fp="20,168,14.210.0,35.95.0,41.64.0,21.78.0,27.69.0"}
P.entries["item:rocket-car-parts"] = {n="Peças de Carro-foguete",s="Peças de carro-foguete são os restos retorcidos de metal espalhados por colisões em alta velocidade pela Chapada Cintilante, em Mil Agulhas. Gerados constantemente por pilotos gnômicos e goblins imprudentes que levam bólidos experimentais além dos seus limites, esses destroços resgatados são recolhidos por oportunistas que buscam transformar acidentes de pista em dinheiro rápido.",h="Peças de carro-foguete são os restos retorcidos de metal espalhados por colisões em alta velocidade pela...",kw={"engenharia","gnomo","goblin","kravel barbakarvão","circuito da ilusão","peças de carro-foguete","resgate","chapada cintilante","mil agulhas"},ang={["profession:Engineering"]="O rastro de engrenagens queimadas e conjuntos de exaustão destroçados pelas planícies de sal serve como testemunho dos extremos caóticos da filosofia de engenharia dos gnomos e goblins.",["race:Dwarf"]="Enquanto gnomos e goblins só se importam com a corrida em si, anões empreendedores como Kravel Barbakarvão provam que o verdadeiro lucro está em vasculhar os destroços deixados para trás."},sec={{t="Velocidade, Destroços e Comércio Sagaz",b="O Circuito da Ilusão, na Chapada Cintilante, é o palco de uma rivalidade explosiva e interminável entre a engenharia gângster goblin e a engenharia gnômica. Em sua busca por uma velocidade terrestre incomparável, os pilotos sofrem regularmente avarias catastróficas, falhas explosivas e batidas em alta velocidade que espalham metal pela planície de sal. Esses vestígios descartados — que vão de cilindros tortos e engrenagens queimadas a chapas de metal amassadas — não ficam abandonados por muito tempo. Catadores e comerciantes, com destaque para o anão oportunista Kravel Barbakarvão, contratam aventureiros que passam por ali para vasculhar a imensidão branca e ofuscante em busca dos escombros. Como ambas as equipes de corrida estão sempre desesperadas por maquinário sobressalente para remendar seu próximo protótipo, os destroços resgatados podem ser facilmente revendidos de volta para as próprias equipes que os destruíram."}},faq={{q="De onde vêm todas essas peças de carro-foguete?",a="Elas são o resultado de constantes colisões, explosões e falhas mecânicas no Circuito da Ilusão. Pilotos gnomos e goblins frequentemente levam veículos experimentais e voláteis movidos a foguete à destruição pelas vastas planícies de sal de Mil Agulhas.",al={"por que ha pecas na planicie de sal","origem da sucata de carro-foguete","de onde vem as pecas"}},{q="Quem compra esses destroços recuperados?",a="Comerciantes como o anão Kravel Barbakarvão recolhem os destroços trazidos por viajantes e os revendem — incluindo engrenagens, blindagens e engenhocas recuperadas — de volta aos gnomos e goblins, que sempre precisam de materiais extras para consertar e aprimorar seus carros de corrida.",al={"quem quer pecas de carro-foguete","kravel barbakarvao pecas de foguete","quem compra os destrocos"}},{q="É perigoso catar essas peças?",a="Os destroços em si são restos inertes, embora às vezes tragam sinais sombrios de batidas violentas, como membros decepados presos no metal. O perigo principal vem da fauna hostil da planície de sal, incluindo basiliscos, escorpitores chamuscados e abutres predadores do sal que rondam os campos de destroços.",al={"e seguro pegar pecas","ameacas ao juntar pecas"}},{q="Os gnomos e goblins se importam com o fato de as peças virem de carros batidos?",a="Nem um pouco. Nem os competidores gnomos nem os goblins têm nojo de materiais reciclados. A única prioridade deles é conseguir geringonças funcionais, engrenagens e placas de metal rápido o suficiente para montar algo que supere o rival na pista.",al={"os corredores se importam com destrocos","por que goblins reutilizam sucata"}}},fx={["9a01e74a"]={q="O que são Peças de Carro-foguete?",a="São os destroços espalhados de desastres de corrida em alta velocidade na Chapada Cintilante. Feitos de engrenagens soltas, cilindros, placas de metal retorcidas e dispositivos recuperados, esses restos foram outrora parafusados nas rugientes engenhocas experimentais construídas por velocistas goblins e gnomos que competiam no Circuito da Ilusão.",al={"o que são peças de carro-foguete","lore peças de carro-foguete","o que são estas peças"}}},fp="16,216,34.487.0,46.227.0,31.210.0,36.213.0,68.161.0"}
P.entries["item:rod-of-channeling"] = {n="Bastão de Canalização",s="Um Bastão de Canalização é um foco arcano portado por conjuradores do clã Dragonmaw em Pantanal. Bruxos que buscam dominar a evocação de um felhunter precisam reunir vários desses bastões para que os acólitos de Strahad Farsan possam ancorar com segurança o círculo ritual em Vila Catraca.",h="Um Bastão de Canalização é um foco arcano portado por conjuradores do clã Dragonmaw em Pantanal.",kw={"acampamento presirada","bonewarder","dragonmaw","felhunter","bastão de canalização","shadowwarder","strahad farsan","tomo do conluio"},ang={["class:Warlock"]="Obter três Bastões de Canalização é um marco crucial para concluir os testes de Tomo do Conluio, fornecendo a contenção necessária para vincular seu primeiro felhunter."},sec={{t="Instrumentos de vinculação",b="Quando um bruxo busca vincular um predador tão volátil quanto um felhunter, a força de vontade bruta raramente é suficiente. Strahad Farsan requer três bastões idênticos para permitir que seus acólitos canalizem sua magia em conjunto, estabilizando o círculo de evocação enquanto o praticante realiza a vinculação. Os conjuradores sombrios do clã Dragonmaw, incluindo os bonewarders e shadowwarders que assolam o Acampamento Presirada e as ruínas ao redor em Pantanal, portam esses implementos para seus próprios trabalhos vis. Embora normalmente desgastados e lascados em combate, os bastões continuam sendo focos potentes capazes de direcionar a caótica energia do Éter."}},faq={{q="Para que serve o Bastão de Canalização?",a="Os bastões são entregues ao bruxo Strahad Farsan, acima de Vila Catraca. Seus acólitos os utilizam para canalizar e estabilizar o círculo mágico necessário para evocar e vincular um felhunter hostil.",al={"o que é bastão de canalização","bastão de canalização finalidade","por que preciso de bastão de canalização"}},{q="Onde os Bastões de Canalização podem ser encontrados?",a="Eles estão em posse de conjuradores do clã Dragonmaw — principalmente Dragonmaw Bonewarders e Shadowwarders — posicionados em Pantanal, especialmente ao redor do Acampamento Presirada.",al={"onde conseguir bastões de canalização","quem saqueia bastão de canalização","localização bastão de canalização"}},{q="Por que Strahad precisa de três bastões?",a="Strahad emprega múltiplos acólitos para ajudar no ritual de evocação do felhunter. Cada assistente precisa de um foco dedicado para manter o canal com segurança enquanto o bruxo subjuga a fera.",al={"por que três bastões","por que 3 bastões de canalização"}},{q="Por que os Dragonmaw estão usando esses bastões?",a="O clã Dragonmaw pratica xamanismo sombrio e resquícios de magia das sombras da Horda Antiga. Seus bonewarders e shadowwarders usam os bastões para canalizar maldições, necromancia e Magia Sombria em suas contínuas guerras territoriais em Pantanal.",al={"bastões dragonmaw","por que dragonmaw têm isso"}}},fx={af4e8f1c={q="O que é um Bastão de Canalização?",a="Um Bastão de Canalização é um foco arcano utilizado por conjuradores para focar e manipular energias mágicas voláteis. Embora tenham sido originalmente empunhados pelos conjuradores sombrios do clã Dragonmaw no Pantanal, esses bastões são instrumentos rituais potentes capazes de estabilizar invocações de alta ordem quando manuseados por bruxos experientes.",al={"o que é bastão de canalização","conhecimento sobre bastão de canalização","sobre o bastão de canalização"}}},fp="17,163,22.464.0,39.158.0,38.133.0,33.140.0,39.227.0"}
P.entries["item:rokaro-s-letter"] = {n="Rokaro's Letter",s="Rokaro’s Letter leva um pedido da Aldeia Pescassombra para Myranda, a Bruxa Velha, nas Terras Pestilentas Ocidentais. Rokaro espera que a habilidade dela com disfarces ajude contra a Black Dragonflight.",h="Rokaro’s Letter leva um pedido da Aldeia Pescassombra para Myranda, a Bruxa Velha, nas Terras Pestilentas...",kw={"black dragonflight","desolação","disfarce","ilusão","myranda, a bruxa velha","rokaro","rokaro’s letter","aldeia pescassombra","colina do pesar","terras pestilentas ocidentais"},ang={["faction:Horde"]="Como membro da Horda, você leva o apelo de Rokaro a uma antiga ilusionista de Lordaeron, em busca de ajuda contra a Black Dragonflight."},sec={{t="Uma mensagem para Myranda",b="Na Aldeia Pescassombra, na Desolação, Rokaro envia você com uma mensagem para Myranda, a Bruxa Velha, na Colina do Pesar. Ela foi uma grande ilusionista de Lordaeron, e Rokaro acredita que a habilidade dela com disfarces pode ajudar a enganar a Black Dragonflight. Ele pede que você leve a carta até ela para que avalie se a causa merece sua ajuda."},{t="O que ela contém",b="Quando Myranda lê Rokaro’s Letter na Colina do Pesar, descobre que ela está intencionalmente em branco. O silêncio é sua proteção: se o portador fosse capturado ou morto, não haveria planos escritos a encontrar. Myranda reconhece a cautela de Rokaro e concorda em ajudar, lembrando-se de um favor que deve ao Chefe Guerreiro."}},faq={{q="Quem escreveu Rokaro’s Letter?",a="Rokaro enviou a carta da Aldeia Pescassombra, na Desolação, para Myranda, a Bruxa Velha.",al={"quem enviou a carta","bilhete de rokaro","carta de rokaro"}},{q="Para onde a carta deve ser levada?",a="A carta deve ser entregue a Myranda, a Bruxa Velha, na Colina do Pesar, nas Terras Pestilentas Ocidentais.",al={"onde levar","destino da carta","localização de myranda"}},{q="Por que Rokaro precisa de Myranda?",a="Rokaro busca a maestria de Myranda em ilusão e disfarces para ajudar a enganar a Black Dragonflight.",al={"por que myranda","precisa de ilusionista","ajuda com disfarces"}},{q="O que diz a carta?",a="Rokaro’s Letter está intencionalmente em branco, sem planos escritos que possam ser descobertos caso seu portador seja capturado ou morto.",al={"conteúdo da carta","o bilhete está em branco","o que está escrito"}},{q="Por que a carta está em branco?",a="A carta em branco protege seu propósito, pois não contém informações escritas que os inimigos possam descobrir.",al={"por que a carta está em branco","bilhete vazio","mensagem secreta"}},{q="Myranda concorda em ajudar?",a="Sim. Myranda concorda em ajudar, citando um favor que deve ao Chefe Guerreiro.",al={"myranda vai ajudar","myranda diz sim","ela concorda"}}},fp="15,184,20.326.0,15.288.1,28.78.0,32.82.0,29.94.0,25.112.1,24.101.1,27.66.1"}
P.entries["item:rolf-and-malakai-s-medallions"] = {n="Medalhões de Rodolfo e Malaquias",s="Os Medalhões de Rodolfo e Malaquias são os distintivos de serviço de dois guardas de Ventobravo que desapareceram enquanto patrulhavam o leste da Floresta de Elwynn. Ostentando a insígnia do reino, esses itens são procurados pelo Guarda Tomás para determinar o paradeiro de seus companheiros desaparecidos.",h="Os Medalhões de Rodolfo e Malaquias são os distintivos de serviço de dois guardas de Ventobravo que...",kw={"vale do leste","elwynn","guarda tomás","malakai","medalhoes","murloc","rolf","guarda de ventobravo"},ang={["faction:Alliance"]="Os medalhões são um lembrete solene de que, mesmo no coração da Aliança, os guardas locais enfrentam perigo mortal protegendo rotas comerciais rurais.",["race:Human"]="Para os humanos de Elwynn, esses distintivos representam filhos e defensores perdidos cujas mortes destacam a vulnerabilidade do reino enquanto o exército está ocupado em outros lugares."},sec={{t="Uma Confirmação Sombria",b="Quando os guardas Rolf e Malakai desapareceram ao longo das margens dos rios no leste da Floresta de Elwynn, o comandante de seu posto, Guarda Tomás, temeu o pior. A recuperação de seus medalhões pessoais de guarda fornece uma prova irrefutável de sua morte pelas mãos dos murlocs invasores. Para a guarnição de Ventobravo, esses distintivos não são meras bugigangas; eles representam soldados caídos que mantiveram a linha de frente contra as crescentes ameaças selvagens quando o exército do reino estava desesperadamente sobrecarregado."},{t="Distintivos de Serviço",b="Como muitos membros da patrulha urbana e das patrulhas rurais de Ventobravo, os guardas humanos carregam medalhões de identificação que atestam sua lealdade e autoridade sob a coroa. Devolver esses itens ao Guarda Tomás permite que ele justifique oficialmente seus homens desaparecidos, registre o sacrifício deles em seu relatório de campo e soe o alarme sobre as tribos agressivas de murlocs que se instalam perto das rotas comerciais."}},faq={{q="O que são os Medalhões de Rodolfo e Malaquias?",a="São os distintivos oficiais de identificação em serviço carregados pelos guardas Rolf e Malakai, dois patrulheiros de Ventobravo destacados no leste da Floresta de Elwynn que foram emboscados e mortos por murlocs.",al={"o que sao os medalhoes","medalhao de rolf","medalhao de malakai"}},{q="A quem pertencem esses medalhões?",a="Eles pertenciam aos Guardas Rolf e Malakai, companheiros de guarda destacados sob o comando do Guarda Tomás para vigiar o rio e as estradas entre Vila d'Ouro e a Madeireira Vale do Leste.",al={"quem eram rolf e malakai","de quem sao os medalhoes"}},{q="Para quem devo levar esses medalhões?",a="Entregue-os ao Guarda Tomás, que vigia a ponte leste ao longo da estrada que conecta Vila d'Ouro à Madeireira Vale do Leste.",al={"quem quer os medalhoes","onde entregar isto","entrega de medalhoes"}},{q="Por que esses medalhões são importantes para o Guarda Tomás?",a="O Guarda Tomás enviou ambos os guardas em patrulha e temia que eles tivessem encontrado um fim trágico. Receber seus medalhões confirma suas mortes, permitindo que ele documente seu sacrifício e alerte Ventobravo sobre a crescente ameaça dos murlocs.",al={"por que tomas quer eles","reacao do guarda tomas"}}},fp="29,178,19.339.0,17.358.0,39.180.1,34.161.0,39.135.0,51.197.1"}
P.entries["item:roon-s-kodo-horn"] = {n="Roon's Kodo Horn",s="O Chifre de Kodo de Roon Juba Agreste é um presente de um caçador Tauren da Desolação. Ele traz um convite para Rosarães Guima Jr. na Selva do Espinhaço e recorda a amizade entre Roon e o pai dele.",h="O Chifre de Kodo de Roon Juba Agreste é um presente de um caçador Tauren da Desolação.",kw={"desolação","acampamento grom'gol","rosarães guima","rosarães guima jr","chifre de kodo","roon","roon juba agreste","chifre de kodo de roon","selva do espinhaço"},ang={["race:Dwarf"]="Como anão, você leva um presente que recorda a amizade entre Guima e Roon Juba Agreste, apesar da inimizade entre seus povos.",["race:Tauren"]="Como Tauren, você talvez conheça o chifre como presente e boas-vindas de Roon Juba Agreste a Rosarães Guima Jr."},sec={{t="Presente de um Caçador",b="Rosarães Guima Jr. caça na Selva do Espinhaço, ao norte do Acampamento Grom'gol. O pai dele já caçou ao lado de Roon Juba Agreste na Desolação, e os dois deixaram de lado a inimizade entre seus povos. Roon lhe dá seu chifre de kodo para levar ao jovem Guima. O presente traz as boas-vindas de um antigo companheiro de caça."}},faq={{q="Quem é Roon?",a="Roon Juba Agreste é um caçador Tauren da Desolação que já caçou ao lado de Rosarães Guima.",al={"roon","roon juba agreste","caçador tauren"}},{q="Por que dar o chifre a Guima Jr.?",a="Roon envia o chifre como presente e dá as boas-vindas a Rosarães Guima Jr., filho de seu antigo companheiro.",al={"por que o chifre","presente de roon","chifre para guima"}},{q="Onde posso encontrar Guima Jr.?",a="Rosarães Guima Jr. fica na Selva do Espinhaço, ao norte do Acampamento Grom'gol.",al={"onde está guima","localização de guima","guima na selva do espinhaço"}},{q="Quem era o pai de Guima?",a="Guima era o anão que caçava grandes feras com Roon Juba Agreste na Desolação.",al={"pai de guima","guima sênior","guima mais velho"}},{q="O que o chifre significa para Roon?",a="O chifre é o presente de Roon para Rosarães Guima Jr. e leva suas boas-vindas.",al={"significado do chifre","por que chifre de kodo","chifre de kodo de roon"}},{q="Roon e Guima se davam bem?",a="Sim. Roon conta que ele e Guima caçaram juntos por muitos dias e esqueceram a inimizade entre seus povos.",al={"roon e guima","amizade entre anões e tauren","eles eram amigos"}}},fp="16,183,15.307.0,12.90.0,28.93.0,27.70.0,23.75.0,32.75.0,29.102.0"}
P.entries["item:rot-blossom"] = {n="Flores do Mal",s="Flores do Mal são uma flora fétida e necrótica encontrada crescendo entre os túmulos dessacrados da Floresta do Crepúsculo. Alimentadas pelo solo maculado e restos de mortos-vivos, elas são cobiçadas por suas propriedades alquímicas potentes e mórbidas.",h="Flores do Mal são uma flora fétida e necrótica encontrada crescendo entre os túmulos dessacrados da Floresta...",kw={"althea ebonlocke","vila sombria","floresta do crepúsculo","flores do mal","skeletal fiend","skeletal horror","cemitério jardins da paz","suco de zumbi"},ang={["faction:Alliance"]="Aventurar-se no solo amaldiçoado para colher essas flores mórbidas funciona também como um serviço para A Vigília Noturna, ajudando a manter as fronteiras de Vila Sombria livres de esqueletos vorazes.",["profession:Herbalism"]="Diferente das ervas comuns nutridas pela luz e pela chuva, as Flores do Mal são anomalias botânicas repugnantes alimentadas puramente pela podridão necrótica e pelo solo de cemitério, oferecendo um estudo sombrio da flora corrompida."},sec={{t="Flora das Criptas",b="A corrupção não natural da Floresta do Crepúsculo gera uma vegetação bizarra e perturbadora, nenhuma mais inquietante do que a Flor do Mal. Enraizadas na terra profanada de cemitérios como o Cemitério Jardins da Paz, essas flores mórbidas prosperam na proximidade da morte. Rumores locais afirmam que elas podem até criar raízes dentro dos crânios rachados dos mortos que caminham, especialmente Skeletal Horrors e Skeletal Fiends que espreitam os túmulos. Para os habitantes locais de Vila Sombria, colhê-las é tanto uma tarefa sombria quanto uma necessidade perigosa, já que perturbar seu solo significa enfrentar os mortos inquietos."},{t="Um Ingrediente Macabro",b="Apesar de sua natureza repulsiva, as Flores do Mal servem a um propósito especializado em misturas locais. As flores contêm essências sombrias necessárias para preparar Suco de zumbi, uma poção repugnante ligada aos macabros esforços de sobrevivência da Floresta do Crepúsculo. Aqueles enviados para colher as flores muitas vezes acabam inadvertidamente ajudando A Vigília Noturna, abatendo no processo os esqueletos inquietos que vagueiam pelos cemitérios assombrados."}},faq={{q="Onde as Flores do Mal podem ser encontradas?",a="As Flores do Mal são encontradas crescendo no solo corrompido dos cemitérios da Floresta do Crepúsculo, particularmente dentro do Cemitério Jardins da Paz, e são conhecidas por brotar dos restos de espíritos esqueléticos mortos-vivos.",al={"onde crescem as flores do mal","localização das flores do mal","encontrar flores do mal"}},{q="Para que servem as Flores do Mal?",a="Elas são um ingrediente essencial usado por cervejeiros e alquimistas locais para destilar uma mistura potente e fétida conhecida como Suco de zumbi.",al={"uso das flores do mal","por que colher flores do mal","o que torna as flores do mal úteis"}},{q="Por que essas flores crescem em esqueletos?",a="A magia sombria remanescente da Floresta do Crepúsculo infecta tanto a terra quanto os mortos inquietos. As Flores do Mal se alimentam diretamente da corrupção necrótica e da decomposição, o que lhes permite brotar dentro dos crânios e caixas torácicas dos esqueletos errantes.",al={"flores do mal em crânios","flor de skeletal horror","esqueletos flores do mal"}},{q="Como a colheita de Flores do Mal ajuda Vila Sombria?",a="Qualquer pessoa que se aventure em lugares como os Jardins da Paz para colher as flores deve inevitavelmente abater os Skeletal Horrors e Fiends que assolam a área, fornecendo um alívio muito necessário para Althea Ebonlocke e a sobrecarregada Vigília Noturna.",al={"althea ebonlocke flores do mal","a vigília noturna flores do mal","ajudando vila sombria"}}},fx={["93f3afdd"]={q="O que são Flores do Mal?",a="Flores do Mal são uma curiosidade botânica mórbida encontrada enraizada nos cemitérios assolados da Floresta do Crepúsculo. Em vez de brotarem em solo saudável, essas flores sombrias prosperam em meio à decomposição, germinando notoriamente dentro dos crânios ocos de Horrores Esqueléticos e Demônios Esqueléticos mortos-vivos. Infundidas com energias vis, são procuradas por moradores excêntricos que preparam poções potentes a partir do apodrecimento.",al={"o que são flores do mal","item flores do mal","o que é flores do mal"}}},fp="11,152,19.329.0,21.281.0,32.165.0,31.94.0,40.188.0,47.215.0"}
P.entries["item:rot-hide-ichor"] = {n="Linfa de Putricouro",s="A Linfa de Putricouro é um fluido corporal fétido extraído dos gnolls Putricouro mortos-vivos que infestam a Ilha de Fenris, no Espelho de Lordaeron. O Boticário Renferrel coleta amostras da substância n'O Sepulcro para descobrir a origem da corrupção dos gnolls e elaborar uma estratégia contra eles.",h="A Linfa de Putricouro é um fluido corporal fétido extraído dos gnolls Putricouro mortos-vivos que infestam a...",kw={"boticário renferrel","ilha de fenris","espelho de lordaeron","gnolls putricouro","linfa de putricouro","o sepulcro","floresta de pinhaprata"},ang={["race:Undead"]="Para os Renegados, estudar a linfa é uma informação militar vital para proteger o flanco oriental de Pinhaprata e avançar o domínio da Sociedade Real dos Boticários sobre a ciência das pragas."},sec={{t="Uma Praga no Sangue",b="Os gnolls Putricouro da Ilha de Fenris não são feras selvagens comuns; eles estão visivelmente decompostos e retorcidos por uma praga antinatural. Em vez de sangue normal, suas veias bombeiam uma linfa nociva que sustenta sua carne reanimada. A Sociedade Real dos Boticários suspeita que esse fluido guarda o segredo de como a matilha foi corrompida e de quem a comanda de dentro da fortaleza em ruínas da Ilha de Fenris."},{t="Pesquisa dos Boticários",b="O Boticário Renferrel reúne frascos dessa linfa para analisar suas propriedades n'O Sepulcro. Ao isolar os componentes químicos e mágicos que alimentam os gnolls, os Renegados esperam identificar vulnerabilidades antes de enviar tropas para um ataque em grande escala através do Espelho de Lordaeron."}},faq={{q="De onde vem a Linfa de Putricouro?",a="Ela é obtida dos corpos dos gnolls Putricouro que habitam a Ilha de Fenris, localizada no Espelho de Lordaeron, a leste da parte continental da Floresta de Pinhaprata.",al={"onde conseguir linfa de putricouro","como encontrar linfa de putricouro","localizacao da linfa de gnoll"}},{q="Por que o Boticário Renferrel quer essa linfa?",a="Renferrel busca dissecar o fluido estranho para descobrir o que corrompeu os gnolls e identificar quaisquer fraquezas físicas ou alquímicas que os Renegados possam explorar antes de atacar a ilha.",al={"por que renferrel precisa de linfa","motivo da missao de renferrel","utilidade da linfa de putricouro"}},{q="Os gnolls Putricouro pertencem ao Flagelo?",a="Eles são gnolls mortos-vivos deformados pela peste, mas os Renegados estão investigando ativamente quem ou o que exatamente os criou e comanda sua presença na Ilha de Fenris.",al={"os putricouro sao do flagelo","quem controla os putricouro","o que sao gnolls putricouro"}},{q="Todos os gnolls têm essa linfa?",a="Não. O fluido é exclusivo da matilha Putricouro, cuja carne e sangue foram corrompidos por vis pragas necromânticas.",al={"todos os gnolls dropam linfa","sangue normal de gnoll"}}},fx={c332bd61={q="O que é Linfa de Putricouro?",a="Linfa de Putricouro é um fluido estranho e não natural que corre através dos corpos dos gnolls Putricouro na Ilha de Fenris. Não é sangue comum; a Real Sociedade de Boticários acredita que essa substância contaminada é diretamente responsável pela natureza retorcida e morta-viva dos gnolls e por sua resiliência elevada.",al={"o que é linfa de putricouro","fluido de putricouro","o que é a linfa"}}},fp="14,168,21.303.0,19.267.0,36.117.0,46.166.0,32.142.0,30.109.0"}
P.entries["item:rough-quartz"] = {n="Quartzo Grosseiro",s="Quartzo Grosseiro é uma humilde pedra elemental presenteada a xamãs novatos por uma Manifestação Menor de Terra. Embora pequena e não refinada, ela serve como o núcleo espiritual vital necessário para criar o primeiro Totem da Terra de um xamã.",h="Quartzo Grosseiro é uma humilde pedra elemental presenteada a xamãs novatos por uma Manifestação Menor de...",kw={"call of earth","ranago arauto da terra","totem da terra","manifestação menor de terra","quartzo grosseiro","vale das provações"},ang={["class:Shaman"]="Quartzo Grosseiro representa sua primeira comunhão com o elemento terra, ancorando seus feitiços e marcando seu caminho como um verdadeiro condutor dos espíritos."},sec={{t="Coração do Totem da Terra",b="Para olhos destreinados, o Quartzo Grosseiro parece não passar de um seixo comum do deserto. Contudo, para um xamã que comunga com os espíritos em Durotar ou Mulgore, é uma dádiva elemental oferecida diretamente por uma Manifestação Menor de Terra. A pedra representa resistência, paciência e força inabalável. Quando apresentada a um ancião como Ranago Arauto da Terra no Vale das Provações, o quartzo é ligado à madeira entalhada de um Totem da Terra, agindo como o foco espiritual que conecta o xamã novato diretamente ao solo vivo de Azeroth."}},faq={{q="Qual é o propósito do Quartzo Grosseiro?",a="Ele serve como prova de que um xamã novato comungou com o espírito elemental da terra. Um xamã ancião usa este seixo como o núcleo espiritual ao entalhar o primeiro Totem da Terra do iniciado.",al={"o que o quartzo grosseiro faz","uso do quartzo grosseiro","por que preciso de quartzo grosseiro"}},{q="Quem lhe dá o Quartzo Grosseiro?",a="Ele é concedido por uma Manifestação Menor de Terra após você comungar com o espírito durante o ritual Call of Earth em Durotar ou Mulgore.",al={"onde conseguir quartzo grosseiro","quem deixa cair quartzo grosseiro"}},{q="Para quem devo levar esta pedra em Durotar?",a="Leve-o a Ranago Arauto da Terra, o instrutor de xamãs que reside no Vale das Provações, que o transformará no seu Totem da Terra.",al={"onde entregar o quartzo grosseiro","entrega de quartzo grosseiro","quem aceita o quartzo grosseiro"}},{q="Este quartzo é usado para algo mais?",a="Não. É puramente um objeto ritual sagrado destinado unicamente à criação de um Totem da Terra e não tem utilidade no comércio comum.",al={"posso vender quartzo grosseiro","quartzo grosseiro é usado em profissões"}}},fx={f25f16be={q="O que é um Quartzo Grosseiro?",a="O Quartzo Grosseiro é uma pequena pedra elemental dada a aspirantes a xamã por uma Manifestação Menor de Terra. Embora modesta em tamanho e aparência, a pedra representa a aprovação de um iniciado no rito da terra e a comunhão com o espírito elemental, servindo como prova tangível de seu vínculo.",al={"o que é quartzo grosseiro","item quartzo grosseiro","significado do quartzo grosseiro"}},["871e2ee1"]={q="Por que Ranago Arauto da Terra quer o Quartzo Grosseiro?",a="Ranago Arauto da Terra precisa do Quartzo Grosseiro como prova de que você atendeu ao chamado e comungou com o espírito elemental. Ele usa a pedra como o coração do seu primeiro Totem da Terra, permitindo que você comungue mais com a terra e lance feitiços ligados diretamente ao seu poder.",al={"por que precisa de quartzo grosseiro","propósito do quartzo grosseiro","por que levar quartzo grosseiro para ranago"}}},fp="12,143,24.439.0,40.172.0,31.143.0,40.127.0,38.102.0"}
P.entries["item:rumbleshot-s-ammo"] = {n="Munição do Estremetiro",s="Munição do Estremetiro é um caixote de munições extraviado destinado ao armeiro Hegnar Estremetiro em Dun Morogh. Perdido quando um mensageiro apavorado fugiu de wendigos famintos, o caixote pesado jaz abandonado na neve perto do Covil Cinzento.",h="Munição do Estremetiro é um caixote de munições extraviado destinado ao armeiro Hegnar Estremetiro em Dun...",kw={"munição","caixote","dun morogh","covil cinzento","hegnar","loslor","estremetiro","wendigo"},ang={["class:Hunter"]="Para atiradores que percorrem o frio congelante de Dun Morogh, manter a pólvora de Hegnar seca e o estoque de tiros abastecido garante um suprimento estável de munição para as armas de fogo anãs.",["profession:Engineering"]="Engenheiros e parafernalhistas anões dependem fortemente de um fluxo constante de projéteis e pólvora para testar suas armas de fogo fabricadas e armamentos experimentais."},sec={{t="Uma Carga Encalhada",b="Hegnar Estremetiro comanda uma loja de armas à beira da estrada ao longo da trilha na montanha que desce do Caminho de Cristálgida em direção a Sidermar. Com atiradores de Altaforja, montanhistas e equipes de morteiros anãs treinando constantemente nas alturas nevadas, seus suprimentos se esgotam quase tão rápido quanto a pólvora pega fogo. Esta remessa específica de munição foi despachada por Loslor a partir de Kharanos, mas nunca chegou às prateleiras. O mensageiro encarregado de transportá-la acampou perto demais dos predadores wendigos do Covil Cinzento, entrou em pânico quando atacado e fugiu para salvar a própria vida, deixando o pesado Caixote de Suprimentos abandonado nas profundezas do território de caça das feras."}},faq={{q="Quem é Hegnar Estremetiro?",a="Hegnar Estremetiro é um armeiro anão que comanda uma loja na saída da estrada em direção a Sidermar. Ele atende atiradores locais, caçadores e artilheiros militares que consomem munição rapidamente enquanto praticam nos penhascos de Dun Morogh.",al={"estremetiro","quem é hegnar","vendedor de armas"}},{q="Como o caixote de munição foi perdido?",a="Um mensageiro encarregado do caixote cometeu o erro de acampar perto da entrada do Covil Cinzento. Quando os wendigos territoriais do covil atacaram o acampamento, o mensageiro aterrorizado fugiu, deixando o pesado caixote para trás na neve.",al={"por que a munição foi perdida","o que aconteceu com a munição","munição do mensageiro"}},{q="Onde fica o Covil Cinzento?",a="O Covil Cinzento é um sistema de cavernas esculpido nas montanhas a sudoeste de Kharanos. Ele serve como um covil infame para os violentos wendigos de Dun Morogh, tornando as encostas ao redor perigosas para viajantes solitários.",al={"localização do covil cinzento","onde fica a caverna dos wendigos"}}},fx={["4221fe47"]={q="O que é a Munição do Estremetiro?",a="É um caixote de munição fresca embalado para a loja de Hegnar Estremetiro ao longo da estrada para Sidermar. Com fuzileiros e equipes de morteiros anões locais praticando constantemente nas proximidades, Hegnar depende de remessas constantes como esta para manter suas prateleiras abastecidas e seus clientes armados.",al={"o que é a munição do estremetiro","caixote de munição do estremetiro","o que são essas munições"}},["008970c2"]={q="De onde vem a Munição do Estremetiro?",a="O caixote foi fornecido e enviado por Loslor Rudge de Kharanos. Infelizmente, o mensageiro encarregado de levá-lo para o sudoeste em direção a Sidermar foi emboscado por wendigos ferozes perto de The Grizzled Den e fugiu, abandonando toda a remessa na neve.",al={"quem fez a munição do estremetiro","de onde veio a munição do estremetiro","quem enviou a munição"}},["6d6b5eaa"]={q="Por que Hegnar Estremetiro precisa desta munição?",a="Hegnar está prestes a ficar sem estoque. Os montanhistas, fuzileiros e equipes de morteiros das redondezas consomem pólvora e munição em um ritmo acelerado durante o treino de tiro, deixando muitos compradores ansiosos esperando o momento em que a nova remessa chega.",al={"por que a munição do estremetiro é necessária","por que querer a munição do estremetiro","quem precisa da munição do estremetiro"}}},fp="17,177,19.477.0,25.175.0,32.152.0,26.171.0"}
P.entries["item:rune-inscribed-parchment"] = {n="Pergaminho Inscrito em Runas",s="Uma mensagem escrita entregue a aspirantes a xamãs orcs no Vale das Provações. Redigida pelo instrutor Shikrik e entregue por Gornek, ela convoca os iniciados a abraçarem seu papel como líderes espirituais e condutores dos espíritos elementais.",h="Uma mensagem escrita entregue a aspirantes a xamãs orcs no Vale das Provações.",kw={"durotar","gornek","pergaminho","pergaminho inscrito em runas","xamã","shikrik","vale das provações"},ang={["class:Shaman"]="Esta nota inscrita com runas marca o seu primeiríssimo passo pelo caminho dos elementos, colocando você sob a tutela de Shikrik para aprender a adoração aos ancestrais e o domínio elemental.",["race:Orc"]="A redescoberta da tradição xamânica é central para A nova Horda, e este pergaminho representa a continuidade da sabedoria ancestral em Durotar."},sec={{t="Um Chamado aos Espíritos",b="Dentro do desfiladeiro ensolarado do Vale das Provações, novos xamãs orcs iniciam seu treinamento sob o olhar atento de supervisores veteranos. Ao realizarem os testes iniciais para Gornek, um iniciado recebe este documento coberto de runas. Enviado diretamente por Shikrik, o instrutor xamânico local, o pergaminho serve como uma convocação formal para os mistérios mais profundos da comunhão elemental. A cultura orca considera o xamã não apenas um conjurador no campo de batalha, mas um mediador essencial entre os vivos e os ancestrais. Este breve escrito marca a transição da simples força bruta para o caminho disciplinado da reverência ancestral."}},faq={{q="O que é o Pergaminho inscrito em runas?",a="É uma mensagem manuscrita entregue a xamãs orcs novatos por Gornek no Vale das Provações. Ela orienta o leitor a se apresentar ao instrutor de xamãs Shikrik para iniciar a instrução formal.",al={"pergaminho rúnico","o que é este item","pergaminho de xamã"}},{q="Quem escreveu o pergaminho?",a="O pergaminho foi escrito por Shikrik, o instrutor de xamãs situado no Vale das Provações, que desejava instruir jovens iniciados nos caminhos dos elementos e dos espíritos ancestrais.",al={"quem enviou o pergaminho","autor do pergaminho"}},{q="Por que os xamãs são considerados escolhidos entre os orcs?",a="Os xamãs orcs atuam como guias espirituais e condutores para seus ancestrais, ouvindo os espíritos elementais para guiar seu povo. Shikrik lembra aos aprendizes que seu dever inclui tanto curar aliados quanto brandir a fúria implacável dos elementos contra seus inimigos.",al={"por que ser um xamã","papel do xamã orc"}}},fx={["00232829"]={q="Por que Shikrik quer que você leia o Rune-Inscribed Parchment?",a="Shikrik enviou esta mensagem através de Gornek para convocá-lo diretamente a ela. Tendo reconhecido que você foi escolhido para guiar as vidas espirituais do seu povo, ela pretende começar seu treinamento formal em comunhão com ancestrais, domínio elemental e os ritos de um xamã orc.",al={"por que ler rune inscribed parchment","por que shikrik envia o parchment","propósito do rune-inscribed parchment"}}},fp="24,154,24.414.0,37.140.0,24.153.0,49.220.0"}
P.entries["item:rune-inscribed-pendant"] = {n="Rune-Inscribed Pendant",s="O Rune-Inscribed Pendant é um berloque mágico recuperado de remessas de suprimentos de Dalaran destinadas a Lenhâmbar. Valorizados pelo Kirin Tor, esses pingentes servem como condutores para canalizar energias arcanas potentes.",h="O Rune-Inscribed Pendant é um berloque mágico recuperado de remessas de suprimentos de Dalaran destinadas a...",kw={"allister","lenhâmbar","dalar tessalba","dalaran","kirin tor","pingente","rune-inscribed pendant","o sepulcro"},ang={["class:Mage"]="Os magos reconhecem com facilidade a manufatura do Kirin Tor; as runas esculpidas no pingente são projetadas para estabilizar correntes voláteis ao canalizar feitiços de ordem superior.",["race:Undead"]="Para os Renegados que guardam a Floresta de Pinhaprata, focos interceptados de Dalaran como este pingente fornecem informações cruciais sobre a resistência humana que se reúne atrás das muralhas de Lenhâmbar."},sec={{t="Relíquia do Kirin Tor",b="Descoberto entre caixotes de suprimentos cartográficos destinados ao enclave de Dalaran em Lenhâmbar, este pingente traz inscrições arcanas intrincadas. Magos de alto escalão do Kirin Tor costumam empregar tais artefatos para focar e amplificar o lançamento de seus feitiços. A presença de vários pingentes de canalização entrando na região desperta imediatamente a suspeita dos Renegados no Sepulcro, sinalizando um projeto iminente de imenso poder mágico."},{t="Uma Pista para os Planos de Lenhâmbar",b="Ao ser levado ao Sepulcro, o Sacerdote Sombrio Allister reconhece a ameaça representada pela posição fortificada dos magos de Dalaran, mas entrega a relíquia a Dalar Tessalba para uma análise mais aprofundada. Tessalba identifica o pingente como um componente fundamental das operações dos magos, deduzindo que o Kirin Tor está estocando ferramentas de foco arcano para alimentar grandes empreitadas defensivas ou ofensivas protegidas atrás das fronteiras de Lenhâmbar."}},faq={{q="Para que serve o Rune-Inscribed Pendant?",a="Os magos do Kirin Tor usam o pingente para canalizar e direcionar fluxos significativos de energia mágica. Ele serve como foco arcano para feitiçaria complexa, em vez de um simples adorno.",al={"o que o pingente faz","objetivo do pingente","uso do pingente rúnico"}},{q="De onde veio esse pingente?",a="Ele foi interceptado de remessas de suprimentos destinadas a Lenhâmbar, na Floresta de Pinhaprata, onde remanescentes do Kirin Tor se fortificaram fortemente.",al={"onde encontro o pingente","origem do pingente","onde foi encontrado"}},{q="Quem analisa o pingente no Sepulcro?",a="Após o Sacerdote Sombrio Allister inspecioná-lo brevemente ao lado de mapas capturados, ele o envia a Dalar Tessalba, um especialista arcano em O Sepulcro que reconhece o trabalho do Kirin Tor.",al={"quem estuda o pingente","quem quer o pingente","pingente de dalar"}},{q="Por que os Renegados estão preocupados com isso?",a="A remessa de grandes quantidades de pingentes de canalização sugere que o Kirin Tor em Lenhâmbar está preparando uma investida mágica massiva, ameaçando o domínio dos Renegados sobre a Floresta de Pinhaprata.",al={"por que os renegados se importam","ameaça de lenhâmbar","por que o pingente é perigoso"}}},fx={bf28d080={q="O que é o Rune-Inscribed Pendant?",a="É um artefato arcano criado e utilizado pelos poderosos magos de Dalaran. Frequentemente usado pelo Kirin Tor para focar e canalizar tremendas energias mágicas, tais pingentes são condutos de potente poder arcano em vez de simples ornamentos.",al={"o que é o rune-inscribed pendant","identidade do rune pendant","o que é este pingente de dalaran"}}},fp="22,166,15.327.0,27.338.1,44.111.0,33.125.0,42.165.0,40.185.0"}
P.entries["item:rune-inscribed-tablet"] = {n="Tabuleta Inscrita em Runas",s="A Tabuleta inscrita em runas é uma mensagem de pedra entregue a jovens xamãs trolls Lançanegra no Vale das Provações. Entregue por Gornek, ela orienta místicos promissores a iniciarem a comunhão formal com os elementos sob a tutela do instrutor orc Shikrik.",h="A Tabuleta inscrita em runas é uma mensagem de pedra entregue a jovens xamãs trolls Lançanegra no Vale das...",kw={"lançanegra","durotar","gornek","tabuleta inscrita em runas","xamã","shikrik","instrutor","vale das provações"},ang={["class:Shaman"]="A tabuleta representa o primeiro passo oficial de um xamã rumo ao domínio dos elementos da terra, fogo, água e ar, lembrando aos alunos que sua força flui dos espíritos ancestrais.",["race:Troll"]="Para os trolls Lançanegra, atender à convocação de um instrutor orc destaca o vínculo crescente e o caminho espiritual compartilhado entre os trolls e seus novos aliados da Horda."},sec={{t="Uma convocação aos espíritos",b="Esculpida com runas elementais, esta tabuleta serve como um convite formal para xamãs trolls iniciantes que dão seus primeiros passos em Durotar. Quando um iniciado demonstra sua coragem no Vale das Provações, o feitor Gornek apresenta a pedra, enviada pelo xamã troll Ishi-yo para direcionar o iniciado ao instrutor de xamãs Shikrik. Para os trolls Lançanegra — que possuem profundas tradições espirituais próprias —, a tabuleta marca o início de seu caminho compartilhado com os orcs, unindo o antigo misticismo dos trolls ao revitalizado legado xamânico defendido pelo Chefe Guerreiro Thrall."}},faq={{q="Para que serve a Tabuleta inscrita em runas?",a="A tabuleta é uma mensagem introdutória entregue por Gornek a jovens xamãs trolls no Vale das Provações. Ela instrui o iniciado a se apresentar a Shikrik, o instrutor de xamãs local, para iniciar sua educação espiritual formal.",al={"propósito da tabuleta","o que a tabuleta faz","uso da tabuleta rúnica"}},{q="Quem envia a tabuleta?",a="A tabuleta é assinada por Ishi-yo, o xamã troll que ensinou ao iniciado suas primeiras lições. Ela os envia a Shikrik, o instrutor de xamãs orc instalado logo do lado de fora d'O Covil no Vale das Provações, que já espera por sua chegada.",al={"quem escreveu a tabuleta","remetente da tabuleta","quem esculpiu"}},{q="Quem recebe esta tabuleta?",a="Apenas xamãs trolls Lançanegra recém-chegados recebem esta tabuleta específica de Gornek como sua convocação de classe inicial em Durotar.",al={"quem recebe a tabuleta inscrita em runas","qual classe recebe a tabuleta"}}},fx={cd2cca59={q="O que é a Tabuleta Inscrita em Runas?",a="A Tabuleta Inscrita em Runas é uma convocação escrita direcionada a aspirantes a xamãs troll treinando dentro do Vale das Provações. Marcada com runas xamânicas, ela serve como uma mensagem pessoal passada através de Gornek para apresentar recrutas promissores diretamente ao seu instrutor local.",al={"o que é a tabuleta inscrita em runas","conhecimento sobre tabuleta inscrita em runas","o que é esta tabuleta"}},["33b46b09"]={q="Por que Shikrik quer que você receba a Tabuleta Inscrita em Runas?",a="Na verdade, a tabuleta vem de Ishi-yo, o xamã troll que deu suas primeiras lições; Gornek apenas supõe que ela veio de Shikrik. Ishi-yo encaminha você a Shikrik, que já está esperando sua chegada. Ela quer instruir você sobre os elementos e os espíritos dos seus ancestrais, para que um dia você possa guiar e proteger as aldeias e cidades da Horda, assim como Thrall guia a própria Horda.",al={"por que shikrik envia a tabuleta","por que preciso desta tabuleta","shikrik tabuleta inscrita em runas"}}},fp="21,159,24.315.0,43.130.0,21.178.0,25.105.0"}
P.entries["item:rune-of-nesting"] = {n="Runa da Nidificação",s="A Runa da Nidificação é uma das quatro sagradas Relics of Wakening guardadas na Gruta de Ban'ethil em Teldrassil. Ela é um componente essencial no delicado ritual druídico necessário para chamar em segurança os Druids of the Talon adormecidos de volta do Sonho Esmeralda.",h="A Runa da Nidificação é uma das quatro sagradas Relics of Wakening guardadas na Gruta de Ban'ethil em...",kw={"athridas mantursino","gruta de ban'ethil","chest of nesting","druids of the talon","sonho esmeralda","relics of wakening","runa da nidificação"},ang={["class:Druid"]="Para os druidas, a Runa da Nidificação representa os rituais sagrados do Círculo Cenariano, destacando a vulnerabilidade dos irmãos adormecidos quando santuários sagrados são violados.",["race:NightElf"]="A profanação das grutas e a perda dessas relíquias de despertar ressaltam a crescente corrupção que assola a vida selvagem e os furbolds de Teldrassil."},sec={{t="Um Foco Sagrado para o Despertar",b="Druidas elfos noturnos passam por hibernações profundas e cíclicas dentro de grutas subterrâneas para comungar com a natureza através do Sonho Esmeralda. Despertar desse transe profundo não é uma simples questão de se levantar; requer um ritual preciso conduzido por instrumentos sagrados. A Runa da Nidificação, mantida em segurança dentro do Chest of Nesting nas profundezas das câmaras sinuosas da Gruta de Ban'ethil, ancora esse processo. Ao lado do Talismã de Garra de Corvo, do Cálamo de Pena Negra e da Safira do Céu, a runa serve como um canal para chamar os Druids of the Talon de volta ao mundo desperto."},{t="Crise em Ban'ethil",b="Quando os furbolds Gnarlpine corrompidos invadiram a Gruta de Ban'ethil, os defensores adormecidos da gruta foram colocados em perigo imediato. Sem acesso às suas relíquias, os druidas corriam o risco de ficar presos no Sonho Esmeralda indefinidamente enquanto os invasores profanavam seu santuário. Recuperar a Runa da Nidificação e seus artefatos companheiros permite que Athridas Mantursino, em Dolanaar, prepare o ritual necessário para despertar com segurança os druidas em perigo."}},faq={{q="Para que serve a Runa da Nidificação?",a="Ela é uma das quatro Relics of Wakening necessárias para que Athridas Mantursino realize o ritual que desperta com segurança os Druids of the Talon de seu sono profundo no Sonho Esmeralda.",al={"o que faz a runa da nidificação","objetivo da runa da nidificação"}},{q="Onde a Runa da Nidificação é encontrada?",a="Ela fica guardada dentro do Chest of Nesting, localizado nos túneis subterrâneos da Gruta de Ban'ethil, a oeste de Dolanaar, em Teldrassil.",al={"onde fica a runa da nidificação","localização do chest of nesting"}},{q="Por que os druidas adormecidos não podem simplesmente acordar sozinhos?",a="Entrar no Sonho Esmeralda durante a hibernação é um estado delicado de transe. Sem a orientação de relíquias sagradas e de um ritual de despertar, retornar pode ser impossível, deixando suas mentes à deriva enquanto seus corpos físicos ficam expostos ao perigo.",al={"por que druidas precisam do ritual de despertar","por que druidas não conseguem acordar"}},{q="Quais outras relíquias são necessárias além da Runa da Nidificação?",a="O ritual completo requer quatro Relics of Wakening: a Runa da Nidificação, o Talismã de Garra de Corvo, o Cálamo de Pena Negra e a Safira do Céu.",al={"outras relics of wakening","itens de relics of wakening"}}},fx={["375c0565"]={q="O que é a Runa da Nidificação?",a="A Runa da Nidificação é uma das quatro Relíquias do Despertar sagradas mantidas pelos Druidas da Garra em Teldrassil. Guardada dentro de um baú dedicado dentro da Gruta de Ban'ethil, ela carrega os encantamentos especializados necessários para realizar corretamente o ritual de despertar para druidas que descansam em comunhão profunda com o Sonho Esmeralda.",al={"runa da nidificação","o que é a runa da nidificação","conhecimento sobre runa da nidificação"}}},fp="15,179,28.497.0,19.354.0,37.212.0,35.133.0,58.204.0,59.139.0"}
P.entries["item:runes-of-summoning"] = {n="Runas de Evocação",s="As Runas de Evocação são um item ritualístico fornecido pelo instrutor de bruxos Silvério Hidalgo no Distrito da Magia de Cidade Baixa. Elas são usadas para atrair um emissário do caos desvinculado para um círculo de evocação, permitindo que um aspirante a bruxo o dobre à sua vontade.",h="As Runas de Evocação são um item ritualístico fornecido pelo instrutor de bruxos Silvério Hidalgo no Distrito...",kw={"silvério hidalgo","distrito da magia","runas de evocação","a vinculação","cidade baixa","emissário do caos","bruxo"},ang={["class:Warlock"]="Bruxos Renegados usam as runas para provar seu domínio sobre o Caos, transformando uma sombra caótica em um lacaio leal e duradouro.",["race:Undead"]="Nas profundezas subterrâneas de Cidade Baixa, praticantes Renegados contornam tabus ancestrais para vincular entidades do caos diretamente sob as Ruínas de Lordaeron."},sec={{t="Subjugação no Distrito da Magia",b="Dentro dos recessos escuros do Distrito da Magia de Cidade Baixa, praticantes Renegados das artes sombrias estudam a manipulação do Eterévio. Silvério Hidalgo confia as Runas de Evocação apenas a bruxos que se prepararam para assumir o comando de um emissário do caos. Ao lançar as runas dentro do círculo de evocação ativo abaixo do posto de Hidalgo, o praticante rasga o tecido do Caos, atraindo uma criatura que deve ser subjugada e vinculada à servidão."}},faq={{q="Para que servem as Runas de Evocação?",a="Elas são usadas dentro do círculo de evocação no Distrito da Magia de Cidade Baixa para atrair um emissário do caos desvinculado do Eterévio para o mundo físico, permitindo que um bruxo o derrote e subjugue.",al={"objetivo das runas de evocação","o que fazem as runas de evocação","como usar as runas de evocação"}},{q="Quem fornece as Runas de Evocação?",a="Silvério Hidalgo, o instrutor de bruxos Renegado localizado no Distrito da Magia de Cidade Baixa, fornece-as durante a etapa final do treinamento para vincular um emissário do caos.",al={"quem dá as runas de evocação","instrutor das runas de evocação","runas de silvério hidalgo"}},{q="Onde as runas devem ser ativadas?",a="Elas devem ser levadas até o círculo de evocação roxo situado diretamente abaixo da plataforma de Silvério Hidalgo no Distrito da Magia.",al={"onde usar as runas de evocação","localização das runas de evocação","círculo de evocação cidade baixa"}},{q="O que acontece depois que a entidade é evocada?",a="O emissário do caos ataca imediatamente. O bruxo deve subjugá-lo pela força da magia e das armas. Uma vez derrotada, a entidade é submetida, e Silvério Hidalgo concede o feitiço permanente para evocá-la.",al={"o que acontece após usar as runas","emissário do caos subjugado","após evocar emissário do caos"}}},fx={["1ce5479a"]={q="O que são as Runas de Evocação?",a="As Runas de Evocação são um catalisador ritual especializado dado a aspirantes a bruxos Renegados na Cidade Baixa. Quando levadas ao círculo de evocação no Distrito da Magia, as runas focam energias mágicas para rasgar uma passagem e atrair um andalho do vácuo liberto do Nether.",al={"o que são runas de evocação","runas de evocação","item runas de evocação"}},["0508549c"]={q="Por que Silvério Hidalgo quer as Runas de Evocação de volta?",a="Silvério Hidalgo fornece as runas especificamente como um teste de domínio. Assim que você as ativa e subjuga o andalho do vácuo evocado em combate, devolver as runas prova a ele que você dominou a criatura, permitindo que ele ensine a você corretamente o feitiço permanente para evocar e comandar andalhos do vácuo.",al={"por que devolver runas de evocação","por que silvério quer as runas","devolver runas de evocação"}}},fp="18,188,32.366.0,41.187.0,36.155.0,34.110.0,42.200.0"}
P.entries["item:ryedol-s-lucky-pick"] = {n="Ryedol's Lucky Pick",s="Ryedol’s Lucky Pick é uma ferramenta de mineração perdida quando os anões Shadowforge atacaram Hammertoe’s Digsite, nos Ermos. Prospector Ryedol espera recuperá-la.",h="Ryedol’s Lucky Pick é uma ferramenta de mineração perdida quando os anões Shadowforge atacaram Hammertoe’s...",kw={"ermos","dark iron","sítio de escavação do pé-de-malho","picareta da sorte","prospector ryedol","ryedol’s lucky pick","shadowforge"},ang={["race:Dwarf"]="Como anão, você pode ajudar Prospector Ryedol a recuperar sua ferramenta após o ataque Shadowforge a Hammertoe’s Digsite."},sec={{t="Uma ferramenta de prospecção",b="Prospector Ryedol trabalha ao sul de Hammertoe’s Digsite, nos Ermos. O clã Shadowforge atacou o local da escavação e matou quase todos que estavam lá, incluindo o chefe de Ryedol, Hammertoe. Ryedol escapou, mas sua picareta da sorte ficou para trás. Ele pede que você procure a ferramenta entre os anões Dark Iron."}},faq={{q="Quem é o dono de Ryedol’s Lucky Pick?",a="Prospector Ryedol é o dono da picareta e quer que ela seja devolvida.",al={"picareta de ryedol","dono da picareta da sorte"}},{q="Onde a picareta foi perdida?",a="A picareta ficou em Hammertoe’s Digsite, nos Ermos, depois que o clã Shadowforge atacou.",al={"onde a picareta foi perdida","local da picareta"}},{q="Quem está com Ryedol’s Lucky Pick?",a="Um dos anões Shadowforge em Hammertoe’s Digsite está com a picareta.",al={"quem está com a picareta","picareta shadowforge"}},{q="Por que Ryedol quer a picareta de volta?",a="É a picareta da sorte de Ryedol, e ele pede que você a recupere dos anões Shadowforge.",al={"por que a picareta da sorte","ryedol precisa da picareta"}}},fp="19,156,21.309.0,31.54.0,24.95.0,30.69.0,35.88.0"}
P.entries["item:sack-of-murloc-heads"] = {n="Saco com Cabeças de Murloc",s="O Saco com Cabeças de Murloc é um pacote macabro recolhido pelas praias de Contraforte de Eira dos Montes. Reunido como prova de ação militar contra as pragas costeiras locais, ele é repassado pelo Tenente Fárrio Orinelle a aventureiros que passam por ali para que seja entregue ao Delegado Trilharrubra em Costa Sul.",h="O Saco com Cabeças de Murloc é um pacote macabro recolhido pelas praias de Contraforte de Eira dos Montes.",kw={"recompensa","fárrio orinelle","cabeças","eira dos montes","delegado trilharrubra","murloc","costa sul"},ang={["faction:Alliance"]="A entrega ilustra a logística desgastada e os fardos cotidianos nada glamourosos enfrentados pelos defensores de Costa Sul enquanto mantêm de pé o enclave da Aliança no norte."},sec={{t="Burocracia e Pragas Costeiras",b="Costa Sul vive sob constante cerco de criminosos da Camarilha, guerrilheiros dos Renegados e murlocs selvagens que infestam a costa. Para garantir verbas e favores da liderança da cidade, os oficiais locais precisam demonstrar que as ameaças costeiras estão sendo ativamente eliminadas. O Tenente Fárrio Orinelle junta provas na forma de cabeças decepadas, mas a natureza repulsiva da carga — e seu próprio nojo — o leva a entregar o saco pingando a viajantes em vez de levar a evidência medonha pessoalmente ao Delegado Trilharrubra."}},faq={{q="O que é o Saco com Cabeças de Murloc?",a="É um saco de estopa cheio de cabeças decepadas de murlocs recolhidas nas praias ocidentais de Eira dos Montes. Ele serve como prova física da pacificação costeira para o comandante da guarnição de Costa Sul.",al={"saco de cabeças","saco de murloc","o que é este item"}},{q="Por que o Tenente Fárrio não o entrega pessoalmente?",a="Fárrio acha repugnante carregar uma sacola fedorenta de cabeças de homens-peixe em decomposição. Preferindo manter seu uniforme e suas mãos limpos, ele delega a tarefa desagradável através de Costa Sul a um aventureiro prestativo.",al={"por que fárrio faz você carregar","desculpa de fárrio","fárrio preguiçoso"}},{q="Quem recebe o saco?",a="A entrega é feita ao Delegado Trilharrubra, o comandante que supervisiona as defesas de Costa Sul, responsável por avaliar a segurança da cidade e exigir provas concretas dos esforços defensivos.",al={"quem recebe as cabeças","onde devo levar","entrega ao delegado trilharrubra"}},{q="Por que Costa Sul exige cabeças de murloc como prova?",a="Os murlocs atacam constantemente a costa e ameaçam o porto. Espera-se que os oficiais comprovem que as patrulhas estão mantendo a segurança do perímetro, e troféus tangíveis garantem que nenhum soldado leve crédito por vigílias ociosas.",al={"por que coletar cabeças de murloc","prova de abate"}}},fx={["3f14ed35"]={q="De onde vem o Saco com Cabeças de Murloc e quem o fez?",a="O saco é montado a partir das cabeças decepadas dos murlocs que você caçou ao longo da costa sul do Contraforte de Eira dos Montes. O Tenente Fárrio Orinelle as juntou para apresentar ao seu oficial comandante, embora ele rapidamente devolva o pacote repulsivo para você entregá-lo em seu lugar.",al={"quem fez o saco com cabeças de murloc","de onde veio o saco com cabeças","quem deu o saco com cabeças de murloc"}}},fp="20,217,29.433.0,33.166.0,47.170.0,22.139.0,50.248.0"}
P.entries["item:sack-of-supplies"] = {n="Saco de Suprimentos",s="Estes sacos de mantimentos pertencem a uma remessa de caravana destinada ao engenheiro goblin Rezlak, nos arredores de Orgrimmar. Transportadas por Durotar, as mercadorias foram interceptadas pelas harpias Dustwind que nidificam nos penhascos da Garganta do Vento Cortante.",h="Estes sacos de mantimentos pertencem a uma remessa de caravana destinada ao engenheiro goblin Rezlak, nos...",kw={"durotar","harpias dustwind","gasganete","garganta do vento cortante","rezlak","saco de suprimentos"},ang={["faction:Horde"]="Recuperar os suprimentos perdidos dos predadores locais garante que a construção de fronteira ao redor da jovem capital de Orgrimmar prossiga sem atrasos dispendiosos."},sec={{t="Uma Caravana Saqueada",b="Rezlak, um engenheiro contratado em Vila Catraca por Gasganete, depende de caravanas regulares através de Durotar para abastecer seus esforços de construção para a Horda. As terras selvagens de Durotar, no entanto, estão longe de ser mansas. Quando uma remessa prometida passou perto da estrada do cânion ao sul de Orgrimmar, foi emboscada e saqueada pelas harpias Dustwind locais. As criaturas cruéis arrastaram a carga para as profundezas de seus ninhos na Garganta do Vento Cortante, espalhando os sacos entre a terra e o cascalho junto aos locais de nidificação das harpias."}},faq={{q="O que há dentro destes sacos de mantimentos?",a="Os sacos contêm materiais de construção e mercadorias enviadas em nome das operações de engenharia de Gasganete para apoiar os projetos de construção orcos perto de Orgrimmar. Sem eles, Rezlak fica desamparado e sem suprimentos para concluir seu trabalho.",al={"conteúdo do saco de mantimentos","o que há nos sacos","mantimentos de rezlak"}},{q="Quem roubou os mantimentos?",a="Os suprimentos foram roubados pelas harpias Dustwind, uma raça aviária selvagem que infesta as fendas e ravinas altas da Garganta do Vento Cortante.",al={"quem pegou os mantimentos","quem roubou os sacos"}},{q="Quem é Rezlak?",a="Rezlak é um engenheiro goblin enviado por Gasganete de Vila Catraca para ajudar a Horda com a construção e a infraestrutura de linhas em Durotar.",al={"quem é rezlak","história de rezlak"}}},fx={["812e6d27"]={q="De onde vêm esses sacos de suprimentos?",a="Esses sacos faziam parte de uma remessa enviada a Durotar em nome de Gasganete e seus engenheiros goblins. Destinados a ajudar os orcs na construção e manutenção de seus assentamentos, a caravana que os transportava foi emboscada e saqueada ao longo da estrada antes que pudesse chegar ao seu destino.",al={"origem do saco de suprimentos","de onde vieram os suprimentos","quem fez o saco de suprimentos"}},["55ee41bd"]={q="Por que Rezlak quer esses sacos de suprimentos?",a="Rezlak não pode realizar o trabalho de construção que Gasganete lhe designou sem os equipamentos e materiais adequados. Harpias da Garganta do Vento Cortante saquearam a caravana que transportava suas ferramentas e provisões, deixando o capataz goblin completamente paralisado até que alguém recupere a carga roubada.",al={"por que rezlak quer suprimentos","por que precisa de sacos de suprimentos","suprimentos de winds in the desert por que"}}},fp="16,156,19.381.0,34.197.0,23.118.0,14.122.0"}
P.entries["item:salty-scorpid-venom"] = {n="Peçonha Salgada de Escorpídeo",s="A Peçonha Salgada de Escorpídeo é um fluido cáustico extraído dos escorpídeos que espreitam a Chapada Cintilante em Mil Agulhas. Repleta de sais naturais do solo do deserto, ela é muito valorizada por pilotos de foguete gnômicos que tentam desenvolver um combustível volátil e extremamente quente.",h="A Peçonha Salgada de Escorpídeo é um fluido cáustico extraído dos escorpídeos que espreitam a Chapada...",kw={"xabu latafuso","circuito da ilusão","peçonha salgada de escorpídeo","scorpid reaver","scorpid terror","peçonha de escorpídeo","chapada cintilante","mil agulhas"},ang={["profession:Engineering"]="Inventores que realizam experimentos na Chapada Cintilante buscam constantemente alternativas ao petróleo e ao carvão convencionais, testando toxinas orgânicas como aceleradores voláteis de combustão.",["race:Gnome"]="Apenas a engenhosidade gnômica cogitaria pegar um veneno letal do deserto, combiná-lo com negacatalisadores e injetá-lo em um motor de foguete apenas para reduzir alguns segundos no tempo de uma volta."},sec={{t="Um Agente de Combustão Volátil",b="Os escorpídeos que rastejam pela extensão árida da Chapada Cintilante se adaptaram a um ambiente intensamente rico em minerais. Ao longo de gerações, o veneno de feras como os Scorpid Reavers e os Scorpid Terrors absorveu quantidades colossais do sal local. Em vez de preparar antídotos ou venenos comuns, engenhoqueiros gnômicos como Xabu Latafuso cobiçam esse composto cáustico como um aditivo promissor para combustível de motores de alta combustão."},{t="Alimentando a Rivalidade no Circuito",b="No Circuito da Ilusão, a rivalidade de engenharia entre gnomos e goblins leva inventores a testar materiais cada vez mais perigosos em seus carros-foguete. Xabu Latafuso acredita que ferver o veneno salgado, tratá-lo com catalisadores especializados e misturá-lo nos tanques de propelente gerará o calor abrasador necessário para ultrapassar os corredores goblins no deserto de sal."}},faq={{q="Quais criaturas produzem a Peçonha Salgada de Escorpídeo?",a="Ela é obtida dos perigosos escorpídeos que vagam pelas planícies de sal em Mil Agulhas, principalmente os Scorpid Reavers e os Scorpid Terrors.",al={"quem concede peçonha salgada de escorpídeo","onde conseguir peçonha de escorpídeo","fonte de peçonha de escorpídeo"}},{q="Por que o veneno é tão salgado?",a="Os escorpídeos vivem exclusivamente sobre o solo incrustado de minerais da Chapada Cintilante. A fisiologia deles absorve os sais densos do leito do lago seco, impregnando suas glândulas de veneno com uma concentração salina marcante.",al={"por que é salgado","explicação da peçonha do salar","história do sal do escorpídeo"}},{q="Quem precisa desse veneno e por quê?",a="Xabu Latafuso, um engenheiro gnomo situado no Circuito da Ilusão, busca o veneno para formular uma mistura experimental de combustível que queime quente o suficiente para impulsionar seu carro-foguete rumo à vitória.",al={"quem precisa de peçonha de escorpídeo","por que xabu quer peçonha","item de missão de xabu latafuso"}}},fx={["9840b612"]={q="O que é Peçonha Salgada de Escorpídeo?",a="É um fluido potente e rico em minerais colhido dos escorpídeos que espreitam a Chapada Cintilante. A bacia de sal áspera e seca fez com que os terrores e saqueadores escorpídeos locais desenvolvessem uma peçonha incomumente saturada de sal. Embora mortal como uma toxina natural, suas propriedades químicas reativas a tornam muito mais interessante para os inventores como um reagente bruto volátil do que como um simples veneno.",al={"o que é peçonha salgada de escorpídeo","peçonha salgada de escorpídeo","peçonha de escorpídeo da chapada"}}},fp="19,215,27.321.0,27.317.0,43.99.0,26.173.0,29.181.0"}
P.entries["item:samophlange-item"] = {n="Rebimboca",s="O samophlange é um componente mecânico enigmático recuperado das profundezas do interior de um console de controle automatizado nos Sertões. Apesar de sua aparência complexa, sua função exata continua sendo um mistério de engenharia até mesmo para os mecânicos goblins que o procuravam.",h="O samophlange é um componente mecânico enigmático recuperado das profundezas do interior de um console de...",kw={"sertoes","console","vila catraca","samophlange","cobogó","tinkers union","undermine"},ang={["profession:Engineering"]="Os engenheiros apreciarão o samophlange como o exemplo perfeito de projeto hipercomplicado, onde uma fachada intrincada esconde um mecanismo tão frágil que se quebra no momento em que toca o chão."},sec={{t="Uma Engenhoca Desconcertante",b="Escondido atrás de um labirinto de fiação supérflua e tubulações ocas dentro de um console de controle dos Sertões, encontra-se o samophlange. É preciso vasculhar um maquinário deliberadamente desconcertante apenas para removê-lo de seu compartimento. Aos olhos destreinados, parece um nexo essencial de tecnologia de relógio e vapor. Para os engenhoqueiros goblins, é um enigma mecânico irresistível destinado a ser enviado para a Tinkers' Union em Undermine — embora sua estrutura frágil signifique que raramente sobrevive ao manuseio descuidado por tempo suficiente para ser compreendido."},{t="Curiosidade e Catástrofe",b="Quando recuperado e levado a Cobogó em Vila Catraca, o engenheiro pretende enviar a peça para dissecação e pesquisa pelas mentes de alto escalão da União. No entanto, a curiosidade dos goblins inevitavelmente supera o bom senso profissional. O simples ato de pousar o dispositivo delicado para inspecionar seus mecanismos internos muitas vezes basta para despedaçá-lo em sucata arruinada."}},faq={{q="O que é um samophlange?",a="É um componente mecânico bizarro extraído do coração de um console de controle nos Sertões. Seu verdadeiro propósito é desconhecido, já que o maquinário ao redor está apinhado de tubos e fios que parecem não ter nenhuma utilidade prática.",al={"o que faz um samophlange","para que serve o samophlange","o que e este item"}},{q="Quem quer o samophlange?",a="Cobogó, um engenheiro estabelecido na cidade portuária de Vila Catraca, pede aos viajantes que recuperem o componente para que ele possa estudá-lo e eventualmente enviá-lo para a Tinkers' Union.",al={"quem precisa do samophlange","para quem entrego o samophlange"}},{q="O que Cobogó faz com ele?",a="Embora planeje enviá-lo para Undermine para um exame minucioso pelos pesquisadores da Tinkers' Union, ele tenta dar uma olhada mais de perto antes. Ao colocá-lo no chão para inspecioná-lo, o mecanismo frágil quebra imediatamente.",al={"cobogo samophlange","o que acontece com o samophlange"}},{q="De onde veio o samophlange?",a="Ele fica instalado dentro de um elaborado console operacional localizado nos confins setentrionais dos Sertões, oculto atrás de camadas de engenharia confusa e aparentemente inútil.",al={"localizacao do samophlange","onde encontrar"}}},fp="11,140,22.353.0,25.264.1,22.204.0,26.124.0,34.156.1,36.142.0"}
P.entries["item:samophlange-manual"] = {n="Manual da Rebimboca",s="O Manual da Rebimboca é um guia operacional técnico que detalha o funcionamento interno do esquivo samophlange. Guardadas a sete chaves pela Empreendimentos S.A., suas páginas espalhadas contêm as instruções necessárias para que engenheiros goblins reparem e operem a engenhoca bizarra.",h="O Manual da Rebimboca é um guia operacional técnico que detalha o funcionamento interno do esquivo...",kw={"sertões","boss copperplug","mina veio do pedregulho","engenharia","manual","rilli greasygob","samophlange","cobogó","empreendimentos s.a."},ang={["faction:Horde"]="Recuperar o manual permite que goblins alinhados à Horda em Orgrimmar estudem e reaproveitem o maquinário corporativo de perfuração bem debaixo do nariz da Empreendimentos S.A.",["profession:Engineering"]="O manual representa tecnologia proprietária da Empreendimentos S.A., demonstrando como engenhoqueiros goblins guardam obsessivamente segredos comerciais e esquemas funcionais de seus companheiros."},sec={{t="Segredos da Engenhoca",b="Esquemas de engenharia e manuais de operações são guardados como ouro entre os empreendimentos goblins, e o Manual da Rebimboca não é exceção. Enquanto trabalhava na Empreendimentos S.A., um ambicioso feitor chamado Boss Copperplug acumulou zelosamente conhecimento sobre o dispositivo, distribuindo apenas páginas espalhadas aos seus subordinados mais leais para manter o controle sobre o maquinário. Quando o dispositivo escapou das garras da Empreendimentos S.A., consertá-lo se mostrou impossível sem reunir a documentação rasgada e distribuída pelo feitor e sua equipe na Mina Veio do Pedregulho."},{t="A Ambição de um Rival",b="Após romper laços com a Empreendimentos S.A., o engenheiro goblin Rilli Greasygob fixou residência em Orgrimmar com a esperança de dominar a construção do samophlange. Sem o favor de Copperplug durante seu emprego anterior, Rilli depende de viajantes empreendedores para recuperar a capa e as folhas soltas do manual. Reconstruir o manual oferece aos engenhoqueiros goblins que trabalham ao lado da Horda uma rara visão da engenharia proprietária da Empreendimentos S.A."}},faq={{q="O que é o Manual da Rebimboca?",a="É um manual de engenharia que detalha como operar e consertar o samophlange, um dispositivo mecânico complexo e excêntrico usado pela Empreendimentos S.A. nos Sertões.",al={"o que é o manual da rebimboca","livro do samophlange","guia do samophlange"}},{q="Quem era o dono do manual originalmente?",a="Ele era guardado por Boss Copperplug, um feitor da Empreendimentos S.A. instalado na Mina Veio do Pedregulho, no nordeste dos Sertões. Copperplug vigiava seus segredos de perto, racionando páginas individuais apenas aos seus trabalhadores de maior confiança.",al={"quem tem o manual","manual do boss copperplug","quem escreveu o manual"}},{q="Por que o manual está rasgado em páginas?",a="Boss Copperplug separou intencionalmente o livro para evitar que rivais ou subordinados não confiáveis compreendessem o dispositivo por completo. Ele manteve a capa do manual enquanto distribuiu cinco páginas específicas entre seus mineradores e operadores.",al={"por que encontrar páginas do manual","páginas espalhadas do manual","por que faltam páginas"}},{q="Quem quer ler o manual completo?",a="Rilli Greasygob, um engenheiro que atua em Orgrimmar, precisa do manual remontado para entender e consertar a Rebimboca Quebrada recuperada nos Sertões.",al={"quem precisa do manual","rilli greasygob","quem quer o manual da rebimboca"}},{q="Para que serve um samophlange?",a="Ninguém fora da Empreendimentos S.A. parece saber. A empresa estava fazendo experimentos com um deles em um pequeno local de pesquisa a sudoeste do Charco de Lodo, nos Sertões, e até mesmo os engenheiros que o estudaram pouco puderam entender a seu respeito.",al={"o que o samophlange faz","propósito do samophlange","finalidade do samophlange"}}},fp="18,165,26.354.0,18.351.0,31.117.0,32.197.0,34.191.0,39.147.0,31.252.0"}
P.entries["item:sample-elven-gem"] = {n="Sample Elven Gem",s="A Sample Elven Gem comprova a descoberta de um tesouro pela tripulação de Shakes O’Breen. O Mestre de Frota Chifre do Mar, em Angra do Butim, precisa dela para saber da descoberta.",h="A Sample Elven Gem comprova a descoberta de um tesouro pela tripulação de Shakes O’Breen.",kw={"angra do butim","gema élfica","mestre de frota chifre do mar","sample elven gem","shakes o’breen","sunken treasure","tesouro"},sec={{t="Uma amostra para Seahorn",b="A tripulação de Shakes O’Breen encontrou um tesouro, mas a maré baixa e as criaturas atentas impedem que partam. Eles precisam que você leve a Sample Elven Gem ao Mestre de Frota Chifre do Mar, em Angra do Butim. A gema comprova o achado e informa Chifre do Mar de que eles estão tentando recuperar mais tesouros."}},faq={{q="O que é a Sample Elven Gem?",a="A Sample Elven Gem comprova o tesouro descoberto pela tripulação de Shakes O’Breen.",al={"gema de amostra","amostra de gema élfica"}},{q="Quem me deu a Sample Elven Gem?",a="Shakes O’Breen entregou a Sample Elven Gem para você levar ao Mestre de Frota Chifre do Mar.",al={"quem me deu a gema","gema de shakes"}},{q="Quem precisa da gema?",a="O Mestre de Frota Chifre do Mar, em Angra do Butim, precisa da Sample Elven Gem como prova da descoberta da tripulação.",al={"quem quer esta gema","gema para seahorn"}},{q="Por que a tripulação de Shakes O’Breen não pode partir?",a="A maré está baixa demais, e as criaturas perturbadas pela tripulação estão observando seus movimentos.",al={"por que estão presos","por que não podem partir"}}},fp="16,150,20.265.0,29.83.0,33.87.0,18.96.0,44.87.0"}
P.entries["item:sample-ichor"] = {n="Amostra de Linfa",s="Este frasco contém um extrato refinado do fluido imundo que sustenta os gnolls putricouros da Floresta de Pinhaprata. Destilada até seus componentes básicos pelo Boticário Renferrel, a substância carrega vestígios persistentes tanto de necromancia quanto de feitiçaria de bruxo.",h="Este frasco contém um extrato refinado do fluido imundo que sustenta os gnolls putricouros da Floresta de...",kw={"boticário renferrel","boanerges stalactus","distrito da magia","putricouro","a origem dos putricouro","amostra de linfa","floresta de pinhaprata","cidade baixa"},ang={["class:Mage"]="Boanerges Stalactus recorre a feitiços de adivinhação especializados para interpretar os resíduos na amostra, demonstrando o valor da análise arcana clássica ao confrontar a feitiçaria sombria.",["class:Warlock"]="O Boticário Renferrel detecta especificamente artes de bruxo entrelaçadas com necromancia dentro da linfa, sugerindo que práticas vis ajudaram a vincular essas feras mortas-vivas."},sec={{t="Desvendando os Putricouros",b="Os gnolls Putricouro que espreitam pela Floresta de Pinhaprata não são feras comuns. Após recuperar amostras das criaturas e de seus restos remanescentes, o Boticário Renferrel, da Real Sociedade de Boticários, reduziu o líquido vil a seus elementos constituintes. Sua análise química revelou que a linfa foi fabricada artificialmente por meio de uma convergência de escolas sombrias: ritos necromânticos entrelaçados com magias de bruxo. Como a arte por trás disso beira disciplinas arcanas que fogem à simples alquimia, Renferrel embalou esta amostra e a enviou a Cidade Baixa para que Boanerges Stalactus a examinasse com adivinhação."}},faq={{q="O que é a Amostra de Linfa?",a="É um extrato refinado preparado pelo Boticário Renferrel a partir dos fluidos corporais dos gnolls putricouros. Renferrel o separou em seus componentes básicos para analisar os métodos mágicos usados para criar essas feras mortas-vivas.",al={"amostra de linfa","o que é esta linfa","o que é amostra de linfa"}},{q="Quem precisa ver esta amostra?",a="A amostra deve ser entregue a Boanerges Stalactus, um mago morto-vivo situado no Distrito da Magia de Cidade Baixa. A perícia de Boanerges em adivinhação e tradições mágicas permite que ele identifique vestígios de magia que a alquimia padrão não consegue discernir.",al={"a quem entrego a linfa","entregar amostra de linfa","boanerges stalactus linfa"}},{q="Que tipo de magia há dentro da linfa?",a="Renferrel detectou uma combinação de magia de bruxo e necromântica vinculada ao fluido. Ao examinar o frasco, Boanerges Stalactus nota que ele está impregnado de encantamentos poderosos e antigos que exigem um feitiço de adivinhação mais profundo para serem totalmente desvendados.",al={"que magia há na linfa","tipo de magia da linfa","magia dos putricouros"}},{q="Por que os boticários não terminaram de analisá-la sozinhos?",a="Embora a Real Sociedade de Boticários se destaque em alquimia, toxinas e pragas corporais, decifrar tramas arcanas complexas requer um feiticeiro dedicado. Boanerges Stalactus é hábil em identificar escolas mágicas e desvendar feitiços esotéricos que vão além do aparato padrão de um boticário.",al={"por que o boticario enviou para boanerges","por que nao descartar linfa de putricouro"}}},fx={f4e4cc11={q="De onde vem esta Amostra de Linfa e quem a fez?",a="O Boticário Renferrel preparou este frasco decompondo linfa bruta colhida dos gnolls Putricouro na Floresta de Pinhaprata. Sua análise inicial revelou que quem criou a substância original a infundiu tanto com necromancia quanto com magia de bruxo, embora o verdadeiro mentor por trás de sua criação permaneça um mistério a ser desvendado.",al={"origem da amostra de linfa","de onde veio a amostra de linfa","quem fez a amostra de linfa"}},["045e6062"]={q="Por que Boanerges Stalactus quer a Amostra de Linfa?",a="O Boticário Renferrel atingiu os limites da ciência alquímica tentando determinar o que criou os couros de putrefação. Ele enviou esta amostra refinada para Boanerges Stalactus no Distrito da Magia da Cidade Baixa, porque Boanerges possui um profundo conhecimento das artes arcanas e sombrias, permitindo que ele use magia de adivinhação para identificar os feitiços obscuros entrelaçados no fluido.",al={"por que boanerges quer a amostra de linfa","por que a amostra de linfa é procurada","propósito da amostra de linfa com boanerges"}}},fp="12,164,24.380.0,25.196.0,29.202.0,39.183.0,59.236.0"}
P.entries["item:sample-of-zanzil-s-altered-mixture"] = {n="Amostra de Preparado Adulterado de Zanzil",s="Este frasco contém um espécime potente de uma mistela preparada pelo curandeiro Zanzil, recuperada durante uma infiltração secreta nos Sertões. Carregada por um operativo que sofre de seus efeitos debilitantes, a amostra é enviada através do mar para a Serraria Tarren na esperança de descobrir tanto um antídoto quanto os segredos letais da arte dos venenos.",h="Este frasco contém um espécime potente de uma mistela preparada pelo curandeiro Zanzil, recuperada durante...",kw={"mistura alterada","eira dos montes","venenos","ladino","serguei hinoto","charco de lodo","serraria tarren","zanzil"},ang={["class:Rogue"]="Entregar esta amostra vil é um rito de passagem para ladinos da Horda, levando diretamente às lições avançadas de Serguei Hinoto sobre preparar, manusear e aplicar venenos letais.",["faction:Horde"]="Transportar esta beberagem perigosa exige uma jornada intercontinental, dependendo das torres de zepelim e das estradas estabelecidas que ligam Kalimdor aos territórios dos Renegados em Lordaeron."},sec={{t="Um símbolo tóxico",b="Após se infiltrar na torre da Empreendimentos S.A. perto do Charco de Lodo e saquear o esconderijo da mistura de Zanzil na caixa-forte de Gallywix, um operativo acaba afligido pelo toque vil de Zanzil. Shenthul ordena que o agente afetado atravesse o Grande Oceano com uma amostra da beberagem em mãos. Encontrar uma cura significa localizar Serguei Hinoto, um boticário situado na Serraria Tarren, no Contraforte de Eira dos Montes, que possui o raro conhecimento necessário para isolar a toxina e decifrar seus componentes."},{t="Segredos da arte dos venenos",b="A amostra serve como mais do que apenas uma urgência médica; é um espécime de valor inestimável para ladinos da Horda que buscam dominar as artes mais sombrias de seu ofício. Serguei Hinoto analisa a mistura alterada não apenas para purificar o mensageiro afligido, mas para demonstrar o ofício químico preciso necessário para preparar e manusear envenenamentos potentes em campo."}},faq={{q="O que é esta mistura?",a="É um espécime de uma beberagem alquímica ligada ao curandeiro Zanzil, recuperada durante uma missão na torre da Empreendimentos S.A. perto do Charco de Lodo, nos Sertões. Ela carrega uma toxina potente que inflige efeitos debilitantes e persistentes a quem entrar em contato direto com ela.",al={"o que e a mistura de zanzil","amostra da mistura alterada de zanzil","amostra de veneno de zanzil"}},{q="Por que preciso levá-la a Serguei Hinoto?",a="Serguei Hinoto é um boticário habilidoso situado na Serraria Tarren, no Contraforte de Eira dos Montes. Ele possui o conhecimento especializado necessário para neutralizar os efeitos da mistela e produzir uma cura confiável antes que a toxina cause danos permanentes.",al={"quem e serguei hinoto","por que levar para a serraria tarren","cura para a mistura de zanzil"}},{q="Quem é Zanzil?",a="Zanzil, o Exilado, é um notório curandeiro troll da selva conhecido por criar elixires indutores de loucura, venenos e mutagênicos. Suas receitas tóxicas se espalharam muito além de suas selvas natais, encontrando caminho em operações mercenárias e industriais como a Empreendimentos S.A.",al={"quem e zanzil","zanzil o exilado","historia de zanzil"}},{q="Como chegar à Serraria Tarren para entregá-la?",a="Os viajantes devem embarcar no zepelim de Durotar para a Cidade Baixa, nas Clareiras de Tirisfal. De lá, pegue a estrada principal ao sul através da Floresta de Pinhaprata, seguindo as placas para o leste em direção ao Contraforte de Eira dos Montes até chegar à cidade da Serraria Tarren.",al={"como chegar a serraria tarren","viajar para eira dos montes","direcoes para serraria tarren"}}},fp="34,213,13.394.0,22.207.1,21.236.0,41.185.0,14.243.0,43.189.0"}
P.entries["item:sample-snapjaw-shell"] = {n="Amostra de Casco de Mordelisca",s="Uma Amostra de Casco de Mordelisca é uma carapaça durável de tartaruga colhida nos oásis de água doce dos Sertões. Notável por sua vitalidade persistente, ela é enviada através do Grande Oceano para auxiliar a pesquisa druídica voltada a rejuvenescer os bosques assolados da Floresta de Pinhaprata.",h="Uma Amostra de Casco de Mordelisca é uma carapaça durável de tartaruga colhida nos oásis de água doce dos...",kw={"sertões","mura runa totem","oásis","amostra de casco de mordelisca","o sepulcro","floresta de pinhaprata","mordelisca","casco de tartaruga"},ang={["class:Druid"]="Para os druidas do Círculo Cenariano, estudar a vitalidade resiliente das mordeliscas dos oásis proporciona lições cruciais sobre como a vida persevera e como terras assoladas podem um dia ser curadas.",["race:Tauren"]="A entrega deste casco destaca o compromisso dos taurens com a Mãe Terra, demonstrando sua disposição em estender ajuda e cura natural até mesmo aos seus aliados mortos-vivos do outro lado do oceano."},sec={{t="Uma Centelha de Vida dos Oásis",b="As tartarugas-mordedoras que habitam os oásis exuberantes e marcados por anomalias dos Sertões possuem cascos de vigor surpreendente. Diferente da matéria comum de cascos, uma Amostra de Casco de Mordelisca fresca retém um brilho interior tênue e uma pulsação energética muito tempo após ser separada da criatura. Para os druidas taurens que observam as rápidas mudanças ecológicas da terra, essas carapaças representam a centelha resiliente e adaptativa da natureza selvagem de Kalimdor, sugerindo que a vida pode florescer mesmo em meio a arredores áridos e inóspitos."},{t="Curando Terras Distantes",b="Reconhecendo a vitalidade latente no casco, os naturalistas taurens enviam mensageiros através do mar para entregar espécimes a Mura Runa Totem no Sepulcro. Posicionada nas extensões assoladas da Floresta de Pinhaprata, Mura busca ajudar os Renegados encontrando formas de curar as terras afligidas do norte. Ao examinar a força vital duradoura preservada dentro da carapaça da mordelisca, ela espera isolar segredos capazes de revitalizar uma floresta adoecida e estimular um novo crescimento em um solo moribundo."}},faq={{q="O que torna este casco de mordelisca especial?",a="Diferente de ossos mundanos e frágeis, esta carapaça retém um brilho interior e parece ainda pulsar com vida após a coleta. Ela provém das mordeliscas que florescem ao redor dos estranhos oásis de água doce dos Sertões, onde as energias naturais fluem de maneira extraordinariamente intensa.",al={"por que o casco é especial","o que é casco de mordelisca","casco brilhante"}},{q="Quem precisa desta amostra?",a="O casco destina-se a Mura Runa Totem, uma druida tauren que habita O Sepulcro na Floresta de Pinhaprata. Ela viajou para os Reinos do Leste para ajudar os Renegados e estudar como trazer terras moribundas de volta à vida.",al={"quem quer o casco","onde entrego o casco","missão mura runa totem"}},{q="Por que enviar um casco dos Sertões até Pinhaprata?",a="Pinhaprata é um bosque adoecido e corrompido, ao passo que os oásis dos Sertões subitamente explodiram em uma vida obstinada e persistente. Os druidas acreditam que estudar a robusta vitalidade contida nas feras de Kalimdor pode fornecer revelações para curar o solo assolado de Lordaeron.",al={"por que enviar para pinhaprata","ligação do casco com pinhaprata"}},{q="O casco é perigoso ou maculado?",a="Não. O casco irradia vitalidade pura, e não magia sombria. Embora o crescimento súbito nos oásis dos Sertões seja misterioso, os druidas compreendem essa energia persistente como uma resiliência natural que vale a pena cultivar.",al={"o casco é maligno","o casco está corrompido"}}},fx={["6161673b"]={q="O que é a Amostra de Casco de Mordelisca?",a="É um espécime retirado da carapaça de uma tartaruga mordelisca encontrada nas extensões áridas dos Sertões. Impregnado com uma vitalidade estranha e pulsante, este casco é preservado cuidadosamente para que sua energia vital incomum possa ser examinada longe das planícies de Kalimdor.",al={"o que é a amostra de casco de mordelisca","item amostra de casco de mordelisca","identidade da amostra de casco de mordelisca"}},c3ef5b23={q="De onde vem a Amostra de Casco de Mordelisca?",a="Ela se origina das mordeliscas selvagens que habitam os oásis e cursos d'água dos Sertões. O casco natural foi coletado por aventureiros da Horda em Kalimdor e escolhido pelos druidas tauren como uma amostra representativa da força vital florescente encontrada dentro do deserto banhado pelo sol.",al={"origem do casco de mordelisca","de onde veio o casco de mordelisca","quem criou a amostra de casco de mordelisca"}}},fp="20,149,21.326.0,21.350.0,38.194.0,22.140.0,51.200.0,34.157.0"}
P.entries["item:samuel-s-remains"] = {n="Restos Mortais de Samuel",s="Os Restos Mortais de Samuel são os restos terrenos recuperados de Samuel Fipps, um antigo morador de Clareiras de Tirisfal que sucumbiu ao Flagelo. Recolhidos por aventureiros perto de Plangemortis, eles são sepultados ao lado de sua esposa Marla para realizar seu último desejo.",h="Os Restos Mortais de Samuel são os restos terrenos recuperados de Samuel Fipps, um antigo morador de...",kw={"plangemortis","marla fipps","sepultura de marla","o último desejo de marla","noviça elvira","samuel fipps","restos mortais de samuel"},ang={["race:Undead"]="Enterrar os restos mortais de Samuel é uma lição precoce sobre a identidade dos Renegados: respeitar os mortos trágicos marca a divisão moral crucial entre os mortos-vivos livres e os lacaios irracionais do Flagelo."},sec={{t="Um Reencontro Trágico",b="Antes de a praga da morte-viva assolar Lordaeron, Samuel Fipps vivia pacificamente com sua esposa, Marla. Quando o contágio atacou, Samuel sucumbiu e foi subjugado à servidão irracional ao Flagelo. Marla escapou da morte-viva apenas para ser assassinada pelo próprio marido que amava. Apesar desse fim brutal, seu último desejo não foi vingança, mas a eternidade juntos: ela implorou para ser sepultada ao lado de Samuel assim que sua forma amaldiçoada tivesse descanso. A Noviça Elvira em Plangemortis recruta Renegados recém-despertos para rastrear a forma errante de Samuel a nordeste do assentamento, recuperar seus ossos e enterrá-los na fileira da frente do cemitério local."}},faq={{q="Quem era Samuel Fipps?",a="Samuel Fipps era um humano que vivia em Clareiras de Tirisfal antes da Terceira Guerra. Quando a praga do Flagelo invadiu, ele pereceu e ergueu-se como um lacaio morto-vivo do Lich Rei. Movido por uma fome insaciável, ele acabou matando sua própria esposa, Marla.",al={"samuel fipps","quem e samuel","historia de samuel"}},{q="Onde os restos mortais de Samuel são encontrados?",a="Eles são recuperados do próprio Samuel Fipps, que vagueia pelo acampamento em ruínas ao longo da estrada a nordeste de Plangemortis. Dar um fim à sua existência irracional permite recuperar seus restos terrenos.",al={"encontrar restos de samuel","onde fica samuel fipps","localizacao de samuel"}},{q="Por que os Renegados o enterram ao lado de sua esposa?",a="O último desejo de Marla era descansar ao lado de seu amado marido, apesar de ter sido ele quem a matou. A Noviça Elvira honra esse pedido para provar que os Renegados recém-libertados ainda possuem compaixão, respeito pelos mortos e a humanidade que os separa do Flagelo.",al={"por que enterrar samuel","tumulo de marla","ultimo desejo de marla"}}},fx={["29aac9a9"]={q="De onde vêm os Restos Mortais de Samuel?",a="Estes são os restos físicos mortais de Samuel Fipps, um ex-residente das Clareiras de Tirisfal que sucumbiu à praga da morte-viva e tornou-se um peão sem mente do Flagelo. Após vagar pelo ermo a nordeste de Plangemortis, seu corpo de morto-vivo é abatido para que seus remanescentes possam finalmente ser reunidos e sepultados.",al={"origem dos restos mortais de samuel","de onde vêm os restos mortais de samuel","quem criou os restos mortais de samuel"}}},fp="16,91,16.533.0,21.223.0,33.186.0,45.260.0"}
P.entries["item:sapphire-of-aku-mai"] = {n="Safira de Aku'Mai",s="As Safiras de Aku'Mai são aglomerados minerais brilhantes e infundidos com água que crescem ao longo dos túneis subterrâneos de Profundezas Negras. Os naga invasores começaram a extrair essas gemas, levando a Harmonia Telúrica a buscá-las antes que seu potente poder arcano possa ser explorado.",h="As Safiras de Aku'Mai são aglomerados minerais brilhantes e infundidos com água que crescem ao longo dos...",kw={"aku'mai","profundezas negras","cristais","je'neu sancrea","naga","safira","espíritos da água","praia de zoram"},ang={["class:Mage"]="A saturação inata de água faz com que essas safiras brutas sejam altamente valorizadas como condutores de componentes arcanos potentes.",["class:Shaman"]="Xamãs da Harmonia Telúrica como Je'neu Sancrea percebem prontamente os espíritos da água aprisionados dentro dessas gemas, tratando a colheita dos naga como uma ameaça elemental."},sec={{t="Gemas das Profundezas",b="Descobertas dentro das entradas de cavernas aquáticas de Profundezas Negras, ao longo da Praia de Zoram em Vale Gris, as Safiras de Aku'Mai são formações cristalinas ricas em energia elemental. Os espíritos da água se apegam fortemente a elas, tornando-as catalisadores excepcionais para trabalhos mágicos. Quando os batedores relataram que os naga subterrâneos começaram a extrair ativamente esses aglomerados das paredes das cavernas, o Xamã Je'neu Sancrea buscou a ajuda de aventureiros para confiscá-los. Deixadas nas garras do povo serpente, as pedras poderiam facilmente alimentar rituais arcanos devastadores."}},faq={{q="O que é uma Safira de Aku'Mai?",a="Elas são cristais de safira vibrantes encontrados revestindo as paredes de Profundezas Negras. Estreitamente ligadas aos espíritos elementais da água, elas possuem uma profunda ressonância arcana e elemental.",al={"o que é este cristal","história safira de aku'mai","o que são essas gemas"}},{q="Por que os naga estão coletando essas safiras?",a="Suas intenções exatas permanecem incertas, mas Je'neu Sancrea suspeita que os naga pretendiam canalizar as ricas energias aquáticas e arcanas dos cristais para feitiçarias perigosas dentro do templo submerso.",al={"por que os naga querem safiras","colheita de cristais pelos naga"}},{q="Quem está procurando por essas safiras?",a="Je'neu Sancrea, um xamã da Harmonia Telúrica posicionado no Assentamento Zoram'gar ao longo da Praia de Zoram em Vale Gris, encarrega viajantes de reuni-las para mantê-las longe das mãos dos naga.",al={"quem quer safiras de akumai","quem entrega essência de akumai"}},{q="Esses cristais estão diretamente ligados à besta Aku'mai?",a="Embora recebam o nome de Aku'mai, a hidra monstruosa que habita as profundezas, os cristais crescem naturalmente nas paredes da caverna. O nome reflete a proximidade com a presença sombria que espreita dentro das ruínas.",al={"conexão com aku'mai","é de akumai"}}},fx={["12f03799"]={q="De onde vêm as Safiras de Aku'Mai e quem as criou?",a="Estes grandes aglomerados de safira crescem naturalmente ao longo das paredes das cavernas dentro dos túneis iniciais das Profundezas Negras. Eles não são criados por mãos mortais; pelo contrário, são formações minerais naturais impregnadas com as energias ambientes da caverna. Espíritos da água se apegam naturalmente aos cristais, conferindo-lhes potência elemental inerente.",al={"origem da safira de aku'mai","quem criou a safira de akumai","de onde vêm as safiras de aku'mai"}}},fp="19,179,16.380.0,30.139.0,44.176.0,35.158.0,54.186.0"}
P.entries["item:sapphire-of-sky"] = {n="Safira do Céu",s="A Safira do Céu é uma das quatro sagradas The Relics of Wakening mantidas pelos elfos noturnos dentro da Gruta de Ban'ethil. É um foco essencial usado para invocar com segurança Druidas da Garra adormecidos de volta do Sonho Esmeralda.",h="A Safira do Céu é uma das quatro sagradas The Relics of Wakening mantidas pelos elfos noturnos dentro da...",kw={"athridas mantursino","gruta de ban'ethil","chest of the sky","druida da garra","sonho esmeralda","relics of wakening","safira do céu"},ang={["class:Druid"]="A safira exemplifica os rituais cuidadosos necessários ao projetar o espírito de alguém no Sonho Esmeralda, demonstrando quão facilmente uma comunhão pode se tornar fatal sem âncoras sagradas.",["race:NightElf"]="Preservar os artefatos sagrados na Gruta de Ban'ethil é fundamental para salvaguardar a ordem frágil de Teldrassil em meio à crescente corrupção."},sec={{t="O Ritual do Despertar",b="Nas profundezas das raízes de Teldrassil, os Druidas da Garra comungam com as áreas selvagens enquanto repousam em hibernação dentro da Gruta de Ban'ethil. Despertar de estados de transe tão profundos para o mundo desperto é um processo frágil e perigoso. Para salvaguardar a transição, os druidas dependem de quatro artefatos consagrados conhecidos como The Relics of Wakening: o Cálamo de Pena Negra, o Talismã de Garra de Corvo, a Runa da Nidificação e a Safira do Céu. Sem esta gema ressonante, a harmonia necessária para chamar os espíritos adormecidos de volta do Sonho Esmeralda permanece incompleta, deixando-os vulneráveis ao aprisionamento eterno."},{t="A Ameaça em Ban'ethil",b="Quando os furbolgs Gnarlpine corrompidos invadiram a gruta, os artefatos sagrados foram deixados para trás em seus repositórios ornamentados. A Safira do Céu reside guardada dentro do Chest of the Sky em meio aos sinuosos corredores subterrâneos. Com os druidas ainda em sono profundo enquanto os furbolgs fazem alvoroço ao redor deles, recuperar esta joia junto com suas relíquias companheiras é uma questão urgente para Athridas Mantursino em Dolanaar antes que os dormentes sejam perdidos permanentemente."}},faq={{q="O que é a Safira do Céu?",a="É uma pedra preciosa sagrada e uma das quatro The Relics of Wakening armazenadas dentro da Gruta de Ban'ethil. Ela funciona em conjunto com três talismãs aviários para guiar com segurança os Druidas da Garra para fora do Sonho Esmeralda.",al={"lore da safira do céu","o que é esta gema","safira do céu"}},{q="Onde a Safira do Céu é guardada?",a="Ela está preservada dentro do Chest of the Sky, descansando no labirinto subterrâneo da Gruta de Ban'ethil, no centro de Teldrassil.",al={"onde encontrar a safira do céu","localização do chest of the sky","localização da safira"}},{q="Por que a safira é necessária agora?",a="Furbolgs Gnarlpine corrompidos invadiram a Gruta de Ban'ethil, colocando os druidas adormecidos em grave perigo. Druidas em transe profundo não podem simplesmente acordar por conta própria; Athridas Mantursino precisa da safira e de outras relíquias para realizar o delicado ritual de despertar antes que os dormentes sejam perdidos para sempre.",al={"por que obter a safira","propósito das relics of wakening"}},{q="Quem usa este artefato?",a="Os Druidas da Garra e guardiões de rituais como Athridas Mantursino a utilizam durante os ritos comunitários que despertam irmãos adormecidos de sua profunda comunhão com a natureza.",al={"quem usa a safira do céu","gema de ritual druida"}}},fp="15,171,19.457.0,23.394.0,28.199.0,34.132.0,37.295.0,23.152.0"}
P.entries["item:sara-balloo-s-plea"] = {n="Apelo de Sara Caxias",s="O Apelo de Sara Caxias é uma missiva escrita à mão por uma viúva em luto em Altaforja. Incapaz de encarar o monarca diretamente em sua dor, ela confia esta carta a um campeão de confiança da Aliança para levá-la perante o Rei Magni Barbabronze.",h="O Apelo de Sara Caxias é uma missiva escrita à mão por uma viúva em luto em Altaforja.",kw={"homenagem real","a sala do trono","altaforja","magni barbabronze","sara caxias","apelo de sara caxias"},ang={["faction:Alliance"]="Sara confia sua petição apenas a campeões reconhecidos por seus serviços à Aliança, confiando que a reputação deles garantirá uma audiência para o seu apelo perante a realeza.",["race:Dwarf"]="Para os anões, levar a mensagem de Sara à Sala do Trono é um ato de profundo parentesco, garantindo que, mesmo no luto, nenhum montanhista ou cidadão deixe de ser ouvido pelo Rei Magni."},sec={{t="O Apelo de uma Viúva",b="Escrito à sombra de uma profunda tragédia pessoal, o Apelo de Sara Caxias representa uma humilde súplica diretamente ao trono de Altaforja. Em vez de enfrentar a Sala do Trono ela mesma em seu estado consumido pelo luto, Sara procura um aventureiro que tenha demonstrado lealdade e valor à Aliança para entregar suas palavras. A mensagem pede a atenção do Rei Magni Barbabronze, voltando o olhar do soberano para o luto particular e os sacrifícios feitos por famílias anãs comuns a serviço do reino."}},faq={{q="O que é o Apelo de Sara Caxias?",a="É uma carta escrita à mão por Sara Caxias, endereçada ao Rei Magni Barbabronze, pedindo sua atenção real enquanto ela chora em particular.",al={"apelo de sara caxias","bilhete de viuva altaforja","bilhete de sara"}},{q="Por que Sara Caxias precisa que outra pessoa a entregue?",a="Sara se sente consumida pela dor e acredita que comparecer diante do Rei de Altaforja em tal estado emocional prejudicaria seu apelo, levando-a a confiar em um campeão da Aliança.",al={"por que entregar bilhete","por que sara nao pode ir","luto de sara"}},{q="Quem recebe esta mensagem?",a="A carta é endereçada e entregue diretamente ao Rei Magni Barbabronze na Sala do Trono de Altaforja.",al={"quem recebe apelo","a quem entregar","carta para magni"}},{q="A que leva a entrega da carta?",a="Apresentar a carta ao Rei Magni chama sua atenção para o luto de Sara Caxias e inicia uma resposta real em homenagem à sua família falecida.",al={"sequencia de missoes do apelo","link para a kings tribute","o que acontece a seguir"}}},fx={["2b83ea9f"]={q="De onde vem o Apelo de Sara Caxias e quem o criou?",a="Esta nota escrita foi redigida diretamente por Sara Caxias, uma anã enlutada em Altaforja. Devastada pela perda, ela mesma preparou a mensagem para peticionar ao trono de Altaforja, confiando-a a um campeão da Aliança em vez de tentar a jornada emocional até A Sala do Trono por conta própria.",al={"quem escreveu o apelo de sara caxias","de onde veio o apelo de sara caxias","quem criou o apelo de sara caxias"}},["4ac5e6cf"]={q="Por que alguém quer o Apelo de Sara Caxias?",a="O Rei Magni Barbabronze precisa da carta para ouvir a petição de um de seus súditos enlutados. Sara Caxias não consegue se forçar a aparecer diante do monarca em seu estado de tristeza, então ela depende de você para apresentar o apelo diretamente nas mãos do governante de Altaforja.",al={"por que o apelo de sara caxias é necessário","quem quer o apelo de sara caxias","por que entregar o apelo de sara caxias"}}},fp="18,110,16.229.0,27.127.0,53.166.0,26.76.0,40.136.1"}
P.entries["item:sarilus-foulborne-s-head"] = {n="Cabeça do Sarilus Malnato",s="A Cabeça do Sarilus Malnato é um troféu macabro obtido de um feiticeiro morto-vivo que corrompeu as águas do norte de Kalimdor. Levada de volta através da fronteira dos Sertões para o Vale Gris, ela serve como prova irrefutável de que o mago intrometido encontrou seu fim pelas mãos das Sentinelas.",h="A Cabeça do Sarilus Malnato é um troféu macabro obtido de um feiticeiro morto-vivo que corrompeu as águas do...",kw={"sertões","morro de brumedo","cabeça","mage summoner","sarilus foulborne","refúgio brisaprata","velene golpestela","elementais da água"},ang={["faction:Alliance"]="Realizar este ataque exige infiltrar-se profundamente nas terras hostis da Horda dentro dos Sertões para eliminar um perigoso conjurador renegado.",["race:NightElf"]="Pegar a cabeça de Foulborne satisfaz a vingança das Sentinelas contra um imprudente corruptor arcano que profanou os espíritos da terra."},sec={{t="Um Corruptor Silenciado",b="Instalado no alto do Morro de Brumedo, no norte de Sertões, o conjurador Renegado Sarilus Foulborne atraiu a ira dos elfos noturnos ao corromper e dominar enxames de Water Elementals. De seu posto no Refúgio Brisaprata, a Sentinela Velene Golpestela reconheceu sua obra nefasta e enviou campeões através da fronteira, para o território da Horda, a fim de pôr fim a seus experimentos imprudentes. Decapitar o mago era a única prova que Golpestela aceitaria para confirmar que seu sorriso zombeteiro havia sido apagado para sempre, garantindo alguma paz às águas conturbadas do Vale Gris."}},faq={{q="Quem foi Sarilus Foulborne?",a="Sarilus Foulborne era um mago morto-vivo que se estabeleceu no alto do Morro de Brumedo, no norte de Sertões. Ele despertou a ira dos elfos noturnos ao distorcer e conjurar vastas quantidades de Water Elementals, levando a Sentinela Velene Golpestela a ordenar sua morte.",al={"quem é sarilus","história de sarilus foulborne","quem é foulborne"}},{q="Por que a Sentinela Velene Golpestela quer a cabeça dele?",a="Velene Golpestela queria certeza absoluta de que o arrogante feiticeiro estava morto. Sarilus zombara dela abertamente enquanto profanava os espíritos das águas da região, e trazer sua cabeça decepada era a única prova que ela aceitaria de que a ameaça havia sido eliminada.",al={"por que pegar a cabeça dele","cabeça velene golpestela","prova de morte"}},{q="Onde fica Sarilus Foulborne?",a="Ele tem seu covil no ponto mais alto do Morro de Brumedo, uma montanha escarpada situada na porção norte dos Sertões, logo ao sul da fronteira com o Vale Gris.",al={"onde encontrar foulborne","localização de sarilus","mago do morro de brumedo"}},{q="Por que Foulborne profanava os Water Elementals?",a="Foulborne usava conjurações arcanas para submeter numerosos Water Elementals à sua vontade, corrompendo-os no processo. Sua manipulação imprudente perturbou o equilíbrio natural das águas que correm perto do Vale Gris, provocando uma rápida retaliação das Sentinelas.",al={"por que corromper elementais","corrupção de elementais da água","motivos de foulborne"}}},fx={a996e76e={q="De onde veio a Cabeça do Sarilus Malnato?",a="Esta cabeça decepada foi retirada diretamente de Sarilus Malnato, um mago Renegado que se estabeleceu no topo do Morro de Brumedo, nos Sertões setentrionais. Operando perto das fronteiras de Vale Gris, Malnato passava seus dias profanando elementais da água e antagonizando os elfos noturnos até que a Sentinela Velene Golpestela enviou um aventureiro ao território inimigo para colocar um fim à sua zombaria.",al={"origem da cabeça de sarilus","de onde veio a cabeça de malnato"}}},fp="24,177,18.497.1,26.241.1,50.217.0,35.104.1,44.240.0"}
P.entries["item:sarkoth-s-mangled-claw"] = {n="Garra Mutilada de Sarkoth",s="A Garra Mutilada de Sarkoth é a pinça decepada de Sarkoth, um escorpião monstruoso que persegue as escarpas ao sul do Vale das Provações. Marcado gravemente pelo troll gravemente ferido Hana'zua, o troféu serve tanto como prova da morte da fera quanto como um consolo final para o orgulho de um caçador ferido.",h="A Garra Mutilada de Sarkoth é a pinça decepada de Sarkoth, um escorpião monstruoso que persegue as escarpas...",kw={"garra","durotar","hana'zua","garra mutilada","sarkoth","escorpião","vale das provações"},ang={["faction:Horde"]="Para iniciados no Vale das Provações, reivindicar este troféu marca um dos primeiros testes de coragem e força marcial nas selvas hostis de Durotar.",["race:Troll"]="Trazer a garra mutilada para Hana'zua concede a um parente Lançanegra moribundo uma medida de dignidade, deixando-o saber que seu golpe final marcou a besta antes do fim."},sec={{t="Um Troféu de Vingança",b="Enquanto caçava no Vale das Provações, um jovem troll Lançanegra chamado Hana'zua enfrentou um escorpião maciço conhecido como Sarkoth. Antes que o ferrão venenoso de Sarkoth perfurasse seu peito e o deixasse sangrando sob uma árvore próxima, Hana'zua desferiu um golpe esmagador contra a enorme pinça da criatura. Decepar esse membro surrado oferece uma prova inegável de que o escorpião monstruoso foi morto. Para Hana'zua, segurar a garra mutilada confirma que seu golpe desesperado deixou uma marca duradoura, proporcionando uma faísca fugaz de honra de guerreiro enquanto o veneno percorre suas veias."}},faq={{q="Por que a garra está mutilada?",a="A garra foi esmagada durante um duelo desesperado entre Sarkoth e o caçador troll Hana'zua. Embora Sarkoth tenha desferido uma picada mortal no peito de Hana'zua, o troll desferiu um golpe feroz contra a pinça da besta antes que ela se fechasse em torno de sua perna.",al={"por que garra quebrada","quem esmagou a garra de sarkoth","história da garra mutilada"}},{q="Quem quer a Garra Mutilada de Sarkoth?",a="Hana'zua pede pela garra. Ele jaz gravemente ferido sob uma árvore no Vale das Provações, temendo que morrerá ali, e quer que o escorpião seja morto para que sua honra seja mantida. Ver o feito realizado o fortalece para aguentar até que Gornek envie ajuda.",al={"quem precisa da garra de sarkoth","para quem entregar","garra de hanazua"}},{q="De onde veio esta garra?",a="Ela é tirada de Sarkoth, um escorpião grande e agressivo que ronda o planalto elevado ao longo dos penhascos ao sul do Vale das Provações em Durotar.",al={"localização de sarkoth","onde está sarkoth","onde conseguir a garra mutilada"}}},fx={["5a9dc5fc"]={q="O que é a Garra Mutilada de Sarkoth?",a="É a pinça decepada de Sarkoth, um escorpidídeo incomumente grande e cruel que ronda o planalto sul acima do Vale das Provações. A garra apresenta danos severos e estilhaçantes infligidos pelo troll Lançanegra Hana'zua, gravemente ferido, durante sua luta desesperada, servindo como prova inegável de que a besta monstruosa foi finalmente morta.",al={"o que é a garra mutilada de sarkoth","identidade da garra de sarkoth","garra mutilada"}}},fp="22,191,21.449.0,24.189.0,33.219.0,30.147.0"}
P.entries["item:sarltooth-s-talon"] = {n="Garra do Sarilodonte",s="Garra do Sarilodonte é uma garra decepada tirada do raptor alfa que espreita acima do Sítio de Escavação de Whelgar, nos Pantanal. Ela serve como prova tangível para o anão Ormer Trançaferro de que a besta cruel responsável por invadir a escavação arqueológica foi abatida.",h="Garra do Sarilodonte é uma garra decepada tirada do raptor alfa que espreita acima do Sítio de Escavação de...",kw={"escavação","ormer trançaferro","raptor","sarilodonte","garra","pantanal","whelgar"},ang={["class:Hunter"]="Rastrear um líder de matilha astuto como Sarilodonte e reivindicar uma garra como troféu é um teste clássico de pontaria e domínio das feras.",["race:Dwarf"]="Recuperar esta garra traz a vingança há muito esperada pelos arqueólogos anões caídos que perderam suas vidas servindo à Liga dos Exploradores por ordem do Rei Magni Barbabronze."},sec={{t="Um Troféu de Vingança",b="Quando os raptores invadiram o Sítio de Escavação de Whelgar e massacraram a expedição anã, Ormer Trançaferro observou da crista acima, incapaz de impedir o abate. Ele escolheu um raptor enorme e ameaçador — Sarilodonte — como o provável líder da matilha por trás do ataque. Buscando retribuição por seus parentes caídos, Ormer exigiu a morte da besta e solicitou uma de suas garras cruéis como prova do feito. Decepar esta garra marca o fim do reinado de terror de Sarilodonte sobre as antigas ruínas anãs."}},faq={{q="De onde vem a Garra do Sarilodonte?",a="A garra é extraída de Sarilodonte, um grande raptor alfa que ronda as cristas ocidentais com vista para o Sítio de Escavação de Whelgar, nos Pantanal.",al={"quem derruba a garra do sarilodonte","localização de sarilodonte","como conseguir a garra"}},{q="Quem quer a Garra do Sarilodonte?",a="Ormer Trançaferro, um anão estacionado no mirante acima do Sítio de Escavação de Whelgar, pede a garra para confirmar que a besta que massacrou sua equipe foi eliminada.",al={"quem aceita a garra","onde entregar a garra","missão de ormer trançaferro"}},{q="Por que Ormer Trançaferro precisa de prova da morte de Sarilodonte?",a="Ormer acredita que Sarilodonte liderou a matilha de raptores que expulsou e matou os escavadores anões. Ele considera a garra um símbolo de justiça e encerramento para seus colegas caídos.",al={"por que matar sarilodonte","o que sarilodonte fez"}},{q="O que aconteceu com os anões no sítio de escavação?",a="A escavação anã tinha como objetivo descobrir artefatos antigos para a Liga dos Exploradores, mas raptores selvagens emboscaram os trabalhadores, massacrando a maioria deles e forçando os sobreviventes a fugir para a crista próxima.",al={"história do sítio de escavação de whelgar","por que há raptores na escavação"}}},fx={["28fc0e8a"]={q="O que é a Garra do Sarilodonte?",a="É uma garra decepada retirada de Sarilodonte, o raptor feroz suspeito de liderar o bando selvagem que invadiu o Sítio de Escavação de Whelgar. Ormer Trançaferro exige a garra como prova inegável de que a besta foi morta e os escavadores anões caídos foram vingados.",al={"o que é a garra do sarilodonte","história da garra do sarilodonte"}}},fp="17,153,21.384.0,39.137.0,28.174.0,57.173.0,52.167.0"}
P.entries["item:sathrah-s-sacrifice"] = {n="Sacrifício de Sathrah",s="O Sacrifício de Sathrah consiste nas fiandeiras prateadas retiradas de Lady Sathrah, uma aranha poderosa que habita Teldrassil. Confiada a aventureiros pela Sacerdotisa A'mura, esta oferenda é apresentada na fonte do Templo da Lua para purificar a corrupção da criatura e fazer seu espírito descansar.",h="O Sacrifício de Sathrah consiste nas fiandeiras prateadas retiradas de Lady Sathrah, uma aranha poderosa que...",kw={"darnassus","eluna","lady sathrah","sacerdotisa a'mura","sacrifício de sathrah","fiandeiras prateadas","aranha","teldrassil","templo da lua"},ang={["class:Priest"]="Sacerdotes a serviço da Irmandade de Eluna veem este ritual como um ato solene de misericórdia divina, usando águas sagradas para purificar a mácula em vez de simplesmente descartar uma fera abatida.",["race:NightElf"]="Para os elfos noturnos, abater animais selvagens corrompidos é um dever sombrio; devolver o espírito de Lady Sathrah à graça de Eluna garante que a vida em Teldrassil possa, eventualmente, renascer livre da loucura."},sec={{t="Purificação nas Águas Sagradas",b="Lady Sathrah já foi uma criatura venerável de Teldrassil que caiu vítima da loucura rastejante e da corrupção que assolam os galhos da grande árvore. Incumbidos pela Irmandade de Eluna, os aventureiros recuperam suas fiandeiras prateadas não como meros troféus, mas como uma oferenda consagrada. Ao banhar esses restos mortais na fonte sagrada do Templo da Lua, a mácula nefasta que envenenou a mente de Sathrah é lavada. O rito liberta sua alma atormentada, permitindo que seu espírito se manifeste pacificamente no santuário e concedendo-lhe a promessa de renascimento sob a graça de Eluna."}},faq={{q="O que é o Sacrifício de Sathrah?",a="O Sacrifício de Sathrah é a oferenda ritual feita a partir das fiandeiras prateadas de Lady Sathrah, uma aranha gigante corrompida abatida em Teldrassil. A Irmandade de Eluna a utiliza em um rito de purificação para limpar a alma da criatura.",al={"o que são as fiandeiras","item sacrifício de sathrah","oferenda de lady sathrah"}},{q="Por que as fiandeiras devem ser colocadas na fonte?",a="A fonte central dentro do Templo da Lua de Darnassus contém águas sagradas consagradas a Eluna. Submergir os restos mortais de Sathrah no lago afasta a corrupção nefasta que a enlouqueceu, libertando seu espírito da agonia.",al={"por que fonte do templo","por que sacrificar sathrah","o que a fonte faz"}},{q="O que acontece quando a oferenda é apresentada?",a="Ao ser colocada nas águas sagradas, a corrupção é expurgada e a forma espectral de Lady Sathrah aparece, caminhando serenamente ao redor do lago para demonstrar que sua alma está em paz.",al={"o que acontece na fonte","espírito de sathrah aparecer","evento da fonte"}},{q="Quem supervisiona este ritual?",a="A Sacerdotisa A'mura, uma serva da Irmandade de Eluna posicionada dentro do Templo da Lua, orienta os aventureiros a darem descanso à criatura e a oferecerem seus restos mortais à deusa.",al={"quem dá sacrifício de sathrah","missão sacerdotisa a'mura","quem purifica sathrah"}}},fx={c7289e92={q="De onde vem o Sacrifício de Sathrah?",a="A Sacerdotisa A'mura preparou esta oferenda diretamente das fiandeiras prateadas retiradas da Senhora Sathrah, uma grande aranha abatida em Teldrassil após cair na loucura e na corrupção.",al={"origem do sacrifício de sathrah","de onde veio o sacrifício de sathrah","quem criou o sacrifício de sathrah"}},b18748b3={q="Por que a Sacerdotisa A'mura quer o Sacrifício de Sathrah?",a="A Sacerdotisa A'mura precisa do sacrifício para que ele possa ser depositado nas águas sagradas de The Temple of the Moon. Por meio desta oferenda a Eluna, a corrupção que distorceu a Senhora Sathrah em vida pode finalmente ser purificada, sepultando a grande besta e permitindo que seu espírito renasça renovado.",al={"por que o sacrifício de sathrah é procurado","por que oferecer o sacrifício de sathrah","para que serve o sacrifício de sathrah"}}},fp="19,171,31.542.0,28.176.0,50.196.0,44.187.1,25.187.0"}
P.entries["item:satyr-horns"] = {n="Chifres de Sátiro",s="Satyr Horns são troféus sombrios colhidos dos sátiros corrompidos que assolam os bosques ancestrais do Vale Gris. Cobiçados tanto por habitantes da floresta em luto em busca de retribuição quanto por mercadores oportunistas que negociam a partir de Vila Catraca, eles servem como prova inegável de que outro servo da Legião Ardente caiu.",h="Satyr Horns são troféus sombrios colhidos dos sátiros corrompidos que assolam os bosques ancestrais do Vale...",kw={"anilia","cantilenda","iliana","trilha da noite","pixel","satyr horns","satyrnaar","posto machadada","xavian"},ang={["faction:Horde"]="Operando a partir do Posto Machadada, guerreiros da Horda eliminam os sátiros imundos que ameaçam suas operações madeireiras enquanto lucram com compradores goblins com destino a Vila Catraca.",["race:NightElf"]="Para os kaldorei, retirar os chifres dos sátiros é um dever amargo, purificando sua floresta ancestral de primos que voluntariamente trocaram sua herança pela servidão demoníaca."},sec={{t="Troféus de Vingança e Comércio",b="Os chifres recurvados dos sátiros do Vale Gris são símbolos patentes da corrupção demoníaca enraizada na floresta sagrada. Para a dríade Iliana no Altar de Aessina, coletar esses chifres decepados é uma questão de dor e vingança por sua falecida irmã Anilia. Para negociantes de fora, como a goblina viajante Pixel descansando no Posto Machadada, contudo, os chifres representam pura oportunidade. A demanda por chifres de sátiro disparou no porto neutro de Vila Catraca, transformando esses restos macabros de demônios abatidos em mercadorias lucrativas para qualquer um ousado o suficiente para caçar seus portadores."},{t="Abatendo os Enclaves Corrompidos",b="Satyr Horns não podem ser comprados de fornecedores comuns; eles precisam ser cortados diretamente das feras à espreita nos cantos escuros da floresta. Os sátiros mantêm fortalezas por todo o Vale Gris, mais notoriamente nos bosques corrompidos de Xavian, nas baixadas sombrias de Satyrnaar e nas ruínas da Trilha da Noite. Limpar esses enclaves livra a terra da mácula demoníaca remanescente enquanto mantém tanto guardiões em luto quanto mercadores ávidos abastecidos com provas do abate."}},faq={{q="Por que Iliana quer Satyr Horns?",a="Iliana busca Satyr Horns para vingar sua falecida irmã, Anilia, que foi assassinada pelos sátiros do Vale Gris. Pegar os chifres dos demônios abatidos fornece a ela a prova de que seus números estão sendo reduzidos e traz paz ao espírito de sua irmã.",al={"chifres de iliana","sátiros de anilia","missão de cantilenda"}},{q="Por que Pixel está coletando Satyr Horns?",a="Pixel é uma viajante empreendedora hospedada no Posto Machadada em seu caminho para Vila Catraca. Ela descobriu que os chifres de sátiro alcançam um preço alto no porto goblin e contrata aventureiros para fazer a caçada perigosa em seu nome antes de partir.",al={"pixel machadada","por que pixel quer chifres","chifres de sátiro vila catraca"}},{q="Onde ficam os melhores lugares para encontrar sátiros com esses chifres?",a="Os sátiros habitam diversas áreas corrompidas por todo o Vale Gris. Concentrações proeminentes são encontradas em Xavian e Satyrnaar no nordeste, e na Trilha da Noite no centro-leste da floresta.",al={"localizações de sátiros vale gris","onde estão os sátiros","acampamentos de sátiros"}},{q="O que são sátiros e por que eles têm chifres?",a="Sátiros são antigos elfos noturnos transformados em seres bestiais e demoníacos por meio dos pactos demoníacos feitos durante a Guerra dos Antigos. Seus cascos caprinos, caudas e chifres perversos são as marcas físicas da corrupção demoníaca concedidas pela Legião Ardente.",al={"o que é um sátiro","por que os sátiros têm chifres"}}},fx={["2131c67f"]={q="O que são Satyr Horns?",a="Satyr Horns são os chifres curvos e diabólicos decepados das cabeças de sátiros mortos que espreitam em Vale Gris. Como corrupções demoníacas de antigos elfos noturnos, os sátiros carregam esses crescimentos ameaçadores como marcas de sua aflição amaldiçoada. Nas mãos de aventureiros, eles servem principalmente como prova sombria do fim de um sátiro ou como curiosidades exóticas valiosas negociadas por Kalimdor.",al={"o que são satyr horns","item satyr horns","identidade dos chifres de sátiro"}},["8a39621c"]={q="Por que alguém quer Satyr Horns?",a="Facções diferentes buscam Satyr Horns por razões muito diferentes. Para a dríade Iliana em Cantilenda, eles servem como troféus inegáveis de retribuição contra os demônios corruptos que assassinaram sua irmã Anilia. Enquanto isso, mercadores oportunistas como Pixel os coletam para vender no movimentado porto de Vila Catraca, onde a demanda é alta por reagentes alquímicos exóticos, curiosidades e partes de bestas.",al={"quem quer satyr horns","por que coletar satyr horns","por que satyr horns são procurados"}}},fp="11,163,34.327.0,30.359.0,35.170.0,36.223.0,58.155.0,44.212.0"}
P.entries["item:savannah-lion-tusk"] = {n="Presa de Leão da Savana",s="As Presas de Leão da Savana são caninos robustos extraídos dos grandes felinos predadores que vagam pelas planícies áridas dos Sertões. Embora sejam troféus de caça comuns para viajantes, elas servem a um propósito exótico como ingrediente de fermentação para a lendária e potente cerveja de Chen Malte do Trovão.",h="As Presas de Leão da Savana são caninos robustos extraídos dos grandes felinos predadores que vagam pelas...",kw={"sertoes","cervejeiro drohn","chen malte do trovao","dishu","humar","vila catraca","presa de leão da savana"},ang={["class:Hunter"]="Caçar as matilhas ferozes pela vegetação dourada dos Sertões oferece um verdadeiro teste de rastreamento, rendendo dentes perigosos que se mostram letais em combate e valiosos para os cervejeiros locais."},sec={{t="Um Ingrediente Curioso de Cervejaria",b="Os grandes felinos dos Sertões — de predadores e caçadoras a alcateias majestosas governadas por patriarcas e feras como Humar, o Senhor da Matilha — estão armados com presas afiadas e pesadas. Enquanto a maioria dos que abatem esses predadores recolhe seus dentes como simples prova de bravura, o Cervejeiro Drohn em Vila Catraca os procura para um ofício muito mais espirituoso. Drohn usa as presas junto com rins de pisaprados e chifres de lagartos-trovão para recriar a famosa bebida homônima de Chen Malte do Trovão, conferindo um impacto lendário que poucas gargantas mortais conseguem suportar com facilidade."}},faq={{q="Por que o Cervejeiro Drohn precisa de Presas de Leão da Savana?",a="O Cervejeiro Drohn em Vila Catraca está recriando a receita da bebida homônima de Chen Malte do Trovão, que lhe foi transmitida por seu mentor. As presas são um dos três reagentes nativos dos Sertões necessários para reproduzir o sabor e o impacto distintos da cerveja.",al={"por que presas para cerveja","drohn presas de leao","cervejeiro drohn receita"}},{q="Quais feras carregam Presas de Leão da Savana?",a="Elas podem ser extraídas de qualquer membro das matilhas de leões da savana que rondam os Sertões, incluindo Crinas-altas da Savana, Patriarcas, Matriarcas, Caçadoras, Espreitadores e feras raras como Dishu e Humar, o Senhor da Matilha.",al={"onde caem presas de leao","quem dropa presa de leao","fonte de presa de leao da savana"}},{q="Leões realmente têm presas?",a="Nas terras selvagens e acidentadas de Kalimdor, os caninos avantajados dos grandes felinos da savana crescem de forma tão proeminente e espessa que caçadores locais e pioneiros os chamam coloquialmente de presas.",al={"por que dentes de leao sao chamados de presas","presas de leao vs caninos","anatomia da presa de leao"}}},fx={["98d362c4"]={q="O que é uma Presa de Leão da Savana?",a="Uma Presa de Leão da Savana é um dente canino afiado colhido dos gatos predadores que rondam as planícies banhadas pelo sol dos Sertões. Embora chamadas de presas, são as presas formidáveis dos leões da savana que dominam os locais de caça regionais. Além de servirem como troféus sombrios de sobrevivência no ermo, essas partes resilientes encontram usos peculiares entre os locais que sabem como extrair suas qualidades essenciais.",al={"o que é uma presa de leão da savana","história da presa de leão da savana","presa de leão"}},ea601034={q="De onde vem uma Presa de Leão da Savana?",a="Estas presas são retiradas diretamente dos gatos de alcateia selvagens que caçam as savanas centrais de Kalimdor. Cada raça de leão que persegue os Sertões — de rondadores e caçadoras a poderosos patriarcas e jubaltas — possui estes dentes afiados, contando com eles para derrubar caminhantes das planícies e defender seu território contra predadores concorrentes.",al={"de onde vêm as presas de leão","quem deixa cair presas de leão","fonte da presa de leão"}}},fp="18,104,28.414.0,51.240.0,39.188.0,29.151.0"}
P.entries["item:sawtooth-snapper-claw"] = {n="Sawtooth Snapper Claw",s="As Sawtooth Snapper Claws vêm dos murlocs da costa do Pântano das Mágoas. Tok'Kar as prepara como armas para ajudar a defender Pedregal.",h="As Sawtooth Snapper Claws vêm dos murlocs da costa do Pântano das Mágoas.",kw={"costa","murloc","sawtooth snapper","sawtooth snapper claw","pedregal","pântano das mágoas","tok'kar","armas"},ang={["faction:Horde"]="Tok'Kar está ajudando a proteger Pedregal, um assentamento orc, contra ameaças ao longo da costa."},sec={{t="Garras para Pedregal",b="Na costa do Pântano das Mágoas, Tok'Kar pede Sawtooth Snapper Claws para reforçar as defesas de Pedregal. Os sawtooth snappers são murlocs, e suas garras se tornam ótimas armas quando preparadas adequadamente. Tok'Kar está na costa para vigiar ameaças e alertar Pedregal se o perigo ficar grande demais."}},faq={{q="De onde vêm as Sawtooth Snapper Claws?",a="As Sawtooth Snapper Claws vêm dos sawtooth snappers da costa do Pântano das Mágoas.",al={"origem das garras de snapper","de onde vêm as garras"}},{q="Quem quer as garras?",a="Tok'Kar quer Sawtooth Snapper Claws para preparar armas para a defesa de Pedregal.",al={"quem quer as garras de snapper","garras de tok'kar"}},{q="Por que Tok'Kar precisa das garras?",a="Tok'Kar diz que as garras se tornam ótimas armas quando preparadas adequadamente, deixando Pedregal com mais armas prontas para um ataque.",al={"por que as garras","para que servem as garras"}},{q="O que Tok'Kar está fazendo na costa?",a="Tok'Kar e suas forças vigiam a costa para proteger Pedregal ou alertá-la se uma ameaça ficar grande demais.",al={"função de tok'kar","por que tok'kar está lá"}}},fp="21,135,17.306.0,42.84.0,20.78.0,32.113.0,35.96.0"}
P.entries["item:scaber-stalk"] = {n="Galho de Piolho",s="Galhos de Piolho são cogumelos raros que proliferam na caverna úmida e isolada oculta atrás de Quedas de Fontescarpa, em Costa Negra. Valorizados por herboristas e alquimistas por suas propriedades incomuns, eles são procurados por Barithras Sombraluna para suas misturas.",h="Galhos de Piolho são cogumelos raros que proliferam na caverna úmida e isolada oculta atrás de Quedas de...",kw={"auberdine","barithras sombraluna","cogumelos da caverna","quedas de fontescarpa","costa negra","cogumelo-cicuta","galho de piolho"},ang={["profession:Herbalism"]="Embora não sejam uma erva comercial comum, essas hastes subterrâneas oferecem uma visão valiosa sobre como os climas singulares das cavernas e as sombras invasoras alteram a biologia fúngica local.",["race:NightElf"]="Atendendo aos avisos do Bosque dos Ancientes, os elfos noturnos abordam a colheita desses cogumelos da caverna com grande cautela, devido à presença corruptora que se prolifera perto de Quedas de Fontescarpa."},sec={{t="Um Espécime Fúngico Raro",b="Galhos de Piolho são cogumelos obscuros encontrados nas profundezas da caverna aninhada atrás de Quedas de Fontescarpa, situada ao longo das montanhas do nordeste de Costa Negra. Diferente da flora florestal comum, essas hastes pálidas prosperam estritamente na umidade isolada da rede subterrânea de cavernas. Seu habitat remoto e perigoso torna a colheita extremamente rara, levando alquimistas como Barithras Sombraluna, em Auberdine, a encomendar batedores ousados dispostos a enfrentar a escuridão."},{t="Uma Sombra nas Quedas",b="Colher Galhos de Piolho traz muito mais perigo do que a forragem comum. Os veneráveis espíritos das árvores no Bosque dos Ancientes emitiram avisos aos elfos noturnos locais, tendo sentido um mal sombrio e crescente se estabelecendo na caverna de Quedas de Fontescarpa. Embora os alquimistas valorizem as hastes ao lado dos raros Cogumelos-cicuta para poções experimentais, coletá-los inevitavelmente coloca os colhedores frente a frente com qualquer maldade que tenha se enraizado sob as montanhas."}},faq={{q="Onde os Galhos de Piolho crescem?",a="Os Galhos de Piolho crescem exclusivamente dentro da caverna úmida escondida atrás de Quedas de Fontescarpa, localizada no nordeste de Costa Negra, ao longo da crista montanhosa.",al={"localização do galho de piolho","onde encontrar galhos de piolho","caverna do galho de piolho"}},{q="Quem quer Galhos de Piolho?",a="Barithras Sombraluna, um estudioso elfo noturno que reside em Auberdine, procura Galhos de Piolho junto com um Cogumelo-cicuta para preparar uma poção especializada.",al={"quem usa galho de piolho","cogumelos de barithras sombraluna","quem precisa de galhos de piolho"}},{q="Por que Barithras Sombraluna não coletou os galhos ele mesmo?",a="Barithras foi alertado a ficar longe da caverna pelo Bosque dos Ancientes, cujos espíritos pressentiram que um novo e perigoso mal havia se refugiado atrás da cachoeira.",al={"por que não pegar pessoalmente","aviso de barithras","aviso da caverna de fontescarpa"}},{q="O que mais cresce junto aos Galhos de Piolho?",a="A caverna também abriga o letal Cogumelo-cicuta, outro espécime raro necessário para as pesquisas alquímicas de Barithras.",al={"outros cogumelos na caverna","cogumelo-cicuta e galho de piolho","cogumelos de fontescarpa"}}},fx={f5b84e96={q="O que é um Galho de Piolho?",a="Um Galho de Piolho é uma espécie rara de cogumelo de caverna nativo da caverna sombria escondida atrás das Quedas de Fontescarpa em Costa Negra. Embora fungos subterrâneos sejam comuns por todo o norte de Kalimdor, esta variedade em particular floresce em grutas escuras e úmidas que abrigam energias sinistras.",al={"o que é um galho de piolho","informações sobre o galho de piolho","cogumelo galho de piolho"}},["053fa90e"]={q="Por que alguém quer Galhos de Piolho?",a="Barithras Sombraluna em Auberdine busca Galhos de Piolho como um ingrediente vital para preparar poções especializadas. Como estes fungos potentes crescem apenas na caverna isolada perto das Quedas de Fontescarpa, herbalistas e alquimistas devem depender de viajantes aventureiros para coletá-los.",al={"por que coletar galho de piolho","uso do galho de piolho","para que servem os galhos de piolho"}}},fp="12,91,22.313.0,21.337.1,28.101.0,24.98.0,58.141.0,40.122.0"}
P.entries["item:scale-of-old-murk-eye"] = {n="Escama do Velho Olho-turvo",s="A Escama do Velho Olho-turvo é obtida do infame líder murloc que aterroriza o litoral de Cerro Oeste. Arrancada do couro da fera, ela serve como prova inegável de sua morte para o Capitão Calvino, o fantasma que assombra o Farol de Cerro Oeste.",h="A Escama do Velho Olho-turvo é obtida do infame líder murloc que aterroriza o litoral de Cerro Oeste.",kw={"capitão calvino","ameaça costeira","murloc","velho olho-turvo","escama do velho olho-turvo","cerro oeste","farol de cerro oeste"},ang={["faction:Alliance"]="Para os marinheiros da Aliança que navegam pelo Grande Oceano em direção às águas de Ventobravo, dar um fim ao Velho Olho-turvo ajuda a garantir que o farol de Cerro Oeste permaneça aceso, salvando futuras embarcações de colidirem contra as rochas."},sec={{t="Troféu de um Flagelo Costeiro",b="A costa de Cerro Oeste já é perigosa o suficiente entre baixios ocultos e tempestades implacáveis, mas a presença do Velho Olho-turvo elevou o perigo de um risco de navegação a um verdadeiro massacre. De acordo com o Capitão Calvino, o fantasma aprisionado ao Farol de Cerro Oeste, este murloc em particular possuía uma astúcia que ia além de seus parentes ferozes, reunindo murlocs de mente mais fraca para saquear a costa. Olho-turvo afugentou a família do vigia, deixando o farol às escuras na noite em que o navio de Calvino se chocou contra as rochas, e, quando a família retornou para reacender a chama, ele atacou novamente e os massacrou. Arrancar uma escama da criatura é a única maneira de satisfazer o espírito vingativo e provar que a costa foi purificada de seu predador mais feroz."}},faq={{q="Para que serve a Escama do Velho Olho-turvo?",a="A escama serve como prova de morte para o Capitão Calvino, o fantasma que assombra a ilha rochosa do Farol de Cerro Oeste. Calvino busca vingança contra o Velho Olho-turvo por ter deixado o farol às escuras na noite do naufrágio fatal do capitão e, mais tarde, ter massacrado a família do vigia do farol.",al={"quem quer a escama","entrega da escama do olho-turvo","uso da escama do velho olho-turvo"}},{q="Quem é o Velho Olho-turvo?",a="O Velho Olho-turvo é um líder murloc notoriamente perverso e astuto que vaga pelas margens arenosas de Cerro Oeste. Diferente dos murlocs comuns, ele demonstrou a habilidade de organizar e coagir seus irmãos em ataques coordenados e mortais contra postos avançados no litoral.",al={"quem é olho-turvo","história do olho-turvo","velho olho-turvo"}},{q="Por que o Velho Olho-turvo atacou o farol?",a="O Velho Olho-turvo atacou inicialmente o farol para afugentar o vigia e sua família, mergulhando a costa na escuridão. Quando os vigias retornaram para reacender a chama, Olho-turvo reuniu seus parentes para um segundo ataque, assassinando toda a família e deixando os navios cegos para os traiçoeiros baixios costeiros.",al={"por que atacar o farol","ataque ao farol","olho-turvo farol"}}},fx={["6e72b95e"]={q="O que é a Escama do Velho Olho-turvo?",a="É uma escama resistente e distinta retirada diretamente da pele do Velho Olho-turvo, o notório líder murloc que aterroriza a costa de Cerro Oeste. Carregá-la serve como prova irrefutável de que o mortal saqueador costeiro foi finalmente morto.",al={"o que é a escama do velho olho-turvo","item escama do velho olho-turvo","escama do olho-turvo"}},["383f15e9"]={q="De onde vem a Escama do Velho Olho-turvo?",a="A escama vem da pele natural do Velho Olho-turvo, um murloc incomumente astuto e cruel que ronda o litoral de Cerro Oeste. Ela não foi forjada ou criada por mãos mortais, mas colhida de sua carcaça após derrotá-lo em batalha.",al={"origem da escama do velho olho-turvo","onde conseguir a escama do velho olho-turvo","quem criou a escama do velho olho-turvo"}},e7059369={q="Por que o Capitão Calvino quer a Escama do Velho Olho-turvo?",a="O Capitão Calvino, o fantasma de um capitão do mar que vaga pelo Farol de Cerro Oeste, busca vingança e encerramento. O Velho Olho-turvo afugentou a família do guardião do farol, deixando o sinal luminoso apagado na noite em que o navio de Calvino colidiu contra as rochas, e, quando a família retornou, ele atacou novamente e os massacrou. Calvino exige a escama como prova incontestável de que a fera está morta e o litoral está mais seguro.",al={"por que calvino quer a escama","por que a escama do velho olho-turvo e procurada","quem quer a escama do velho olho-turvo"}}},fp="21,165,27.481.0,43.240.0,20.178.0,43.277.0"}
P.entries["item:scarlet-armband"] = {n="Braçadeiras Escarlate",s="As Braçadeiras Escarlate são insígnias usadas por membros da Cruzada Escarlate, marcando sua lealdade fanática à erradicação de todos os mortos-vivos. Em Plangemortis, o Executor Arren as exige como prova de que os Renegados recém-erguidos revidaram contra os fanáticos que invadiam seu território.",h="As Braçadeiras Escarlate são insígnias usadas por membros da Cruzada Escarlate, marcando sua lealdade...",kw={"plangemortis","executor arren","braçadeiras escarlate","convertido escarlate","cruzada escarlate","iniciado escarlate","clareiras de tirisfal"},ang={["race:Undead"]="Para os Renegados recém-erguidos, coletar essas braçadeiras é uma introdução sombria ao ódio do mundo dos vivos, mostrando que a sobrevivência exige uma defesa impiedosa contra a Cruzada."},sec={{t="Um Distintivo de Fanatismo",b="Usadas nas mangas de Iniciados Escarlate e novos convertidos, a Braçadeira Escarlate é a marca inconfundível da Cruzada Escarlate. Para os Renegados recém-erguidos que emergem de Plangemortis, essas faixas de tecido vermelho representam uma ameaça letal bem à sua porta. A Cruzada não faz distinção entre os lacaios irracionais do Flagelo e os súditos de livre arbítrio da Dama Sombria; aos olhos deles, qualquer cadáver ambulante deve ser queimado. O Executor Arren usa a coleta dessas braçadeiras como um rito de passagem sombrio, confirmando as mortes de batedores inimigos a sudeste do assentamento e provando que os novos Renegados podem defender sua nação nascente."}},faq={{q="Por que o Executor Arren quer Braçadeiras Escarlate?",a="O Executor Arren requer as braçadeiras como prova de que o acampamento invasor da Cruzada Escarlate a sudeste de Plangemortis está sendo dizimado. A Cruzada representa uma ameaça existencial imediata aos Renegados recém-despertos, e coletar esses símbolos garante que seus batedores e recrutas avançados tenham sido eliminados.",al={"por que coletar braçadeiras","missão de braçadeira do arren","propósito da braçadeira escarlate"}},{q="Quem usa essas braçadeiras?",a="As braçadeiras são usadas por membros de baixa patente da Cruzada Escarlate estacionados perto de Plangemortis, especificamente Iniciados Escarlate, Convertidos Escarlate e o mensageiro Meven Korgal.",al={"quem deixa cair braçadeiras escarlate","onde encontrar braçadeiras"}},{q="Por que a Cruzada Escarlate odeia os Renegados?",a="Movida por fanatismo extremo, a Cruzada Escarlate se recusa a ver qualquer diferença entre o Flagelo irracional do Lich King e os Renegados de livre arbítrio. Eles veem todos os mortos-vivos como abominações que devem ser permanentemente erradicadas.",al={"por que os escarlates atacam mortos-vivos","cruzada vs renegados","fanáticos escarlate"}},{q="Onde fica o acampamento onde essas braçadeiras podem ser encontradas?",a="O acampamento está situado logo a sudeste de Plangemortis nas Clareiras de Tirisfal, aninhado nas colinas além do perímetro do assentamento.",al={"localização do acampamento escarlate","acampamento escarlate de plangemortis","onde estão os convertidos escarlate"}}},fx={["365b2391"]={q="O que é uma Braçadeiras Escarlate?",a="Uma Braçadeiras Escarlate é um pedaço de tecido carmesim usado por iniciados e convertidos da The Scarlet Crusade. Ela serve como uma insígnia de identificação para a zelosa ordem humana, marcando seus usuários como cruzados jurados dedicados a erradicar todos os mortos-vivos de Lordaeron, independentemente de esses mortos-vivos servirem ao Flagelo ou possuírem livre arbítrio como os Renegados.",al={"o que é braçadeiras escarlate","significado de braçadeiras escarlate","história de braçadeiras escarlate"}}},fp="15,158,21.513.0,46.244.0,25.169.0,47.204.0,52.110.0"}
P.entries["item:scarlet-crusade-documents"] = {n="Documentos da Cruzada Escarlate",s="Estes papéis interceptados eram transportados por um mensageiro da Cruzada Escarlate no acampamento da Cruzada perto de Plangemortis. Contendo ordens para os comandantes de campo da Cruzada pelas Clareiras de Tirisfal, eles fornecem aos Renegados as informações militares exatas necessárias para atingir a liderança regional da Cruzada.",h="Estes papéis interceptados eram transportados por um mensageiro da Cruzada Escarlate no acampamento da...",kw={"montalvo","plangemortis","executor arren","executor zigano","meven korgal","documentos da cruzada escarlate","the red messenger","vital intelligence"},ang={["race:Undead"]="Carregar esses papéis interceptados marca a graduação de um Renegado desperto dos testes do cemitério de Plangemortis para o esforço de guerra mais amplo comandado a partir de Montalvo."},sec={{t="Ordens Interceptadas",b="O mensageiro Meven Korgal carregava estes documentos no acampamento da Cruzada a sudeste de Plangemortis. Emitidas por ordem do Grão-senhor, as diretrizes são endereçadas aos capitães do Comando Regional de Tirisfal da Cruzada: o Capitão Perrine deve fortificar ainda mais a torre sudoeste e reunir informações sobre os mortos-vivos em Montalvo, o Capitão Vachon deve esmagar a movimentação dos mortos-vivos perto da torre norte, e o Capitão Melrose deve vigiar as fronteiras das Terras Pestilentas. Os documentos revelam os nomes, postos e ordens dos oficiais de campo escarlates posicionados pelas Clareiras de Tirisfal, transformando o que seria uma corrida rotineira de mensageiro em uma quebra de segurança catastrófica para os fanáticos."},{t="Entrega em Montalvo",b="O Executor Arren rapidamente reconheceu que as forças locais em Plangemortis não poderiam aproveitar toda a extensão das informações. Em vez disso, o dossiê capturado serve como o passaporte de um Renegado recém-despertado para fora de Plangemortis. Carregados para o nordeste, passando pelo Casarão Lar Glacial até Montalvo, os documentos são entregues diretamente ao Executor Zigano do lado de fora da Prefeitura de Montalvo. Com essas ordens em mãos, a liderança militar dos Renegados planeja ataques de decapitação rápidos contra os comandantes escarlates entrincheirados pelas Clareiras."}},faq={{q="Quem estava carregando estes documentos?",a="Eles eram carregados por Meven Korgal, um mensageiro da Cruzada Escarlate encontrado no acampamento da Cruzada a sudeste de Plangemortis.",al={"quem derrubou estes documentos","mensageiro escarlate","meven korgal"}},{q="Quais informações estão dentro dos documentos?",a="O pacote contém diretrizes, por ordem do Grão-senhor, para os capitães do Comando Regional de Tirisfal da Cruzada: o Capitão Perrine deve fortificar a torre sudoeste e espionar os mortos-vivos em Montalvo, o Capitão Vachon deve lidar com a movimentação dos mortos-vivos perto da torre norte, e o Capitão Melrose deve vigiar as fronteiras das Terras Pestilentas.",al={"o que dizem os papéis","conteúdo dos documentos"}},{q="Quem precisa ver estes documentos?",a="Após serem recuperados para o Executor Arren em Plangemortis, eles são confiados a você para entrega ao Executor Zigano, que supervisiona os esforços militares regionais em frente à Prefeitura de Montalvo.",al={"para onde os levo","a quem entrego os documentos"}},{q="Por que estes documentos são importantes para os Renegados?",a="As ordens capturadas detalham o posicionamento dos oficiais da Cruzada pelas Clareiras de Tirisfal, dando aos Renegados a vantagem para eliminar a liderança inimiga e abalar o moral regional dos fanáticos.",al={"por que os renegados os querem","importância dos documentos escarlates"}}},fx={b6ac443b={q="O que são os Documentos da Cruzada Escarlate?",a="Eles são um maço de documentos militares confidenciais, relatórios de batalha e ordens carregados por um mensageiro da The Scarlet Crusade. Embora grande parte do pacote consista em contas de batedores comuns e propaganda sobre escaramuças com os Renegados, ele também contém instruções operacionais detalhadas destinadas aos oficiais da Cruzada estacionados por todas as Clareiras de Tirisfal.",al={"o que são os documentos","informações sobre documentos da cruzada escarlate","item documentos escarlate"}},["5f5d9cee"]={q="De onde vieram os Documentos da Cruzada Escarlate?",a="São diretrizes emitidas por ordem do Grão-cruzado da Cruzada aos capitães de seu Comando Regional de Tirisfal. Elas foram confiadas a um mensageiro chamado Meven Korgal, a quem os Renegados encontraram no acampamento da Cruzada a sudeste de Plangemortis.",al={"quem escreveu os documentos da cruzada escarlate","fonte dos documentos escarlates","de onde vieram os documentos"}}},fp="25,243,18.495.0,17.427.0,33.115.0,41.295.0,33.180.0,50.172.0"}
P.entries["item:scarlet-insignia-ring"] = {n="Anel com Insígnia Escarlate",s="Um Anel com Insígnia Escarlate é um anel de sinete usado por membros d'A Cruzada Escarlate aquartelados por todas as Clareiras de Tirisfal. Para os defensores Renegados de Montalvo, esses anéis servem como uma prova macabra de que mais um fanático foi eliminado do solo de Lordaeron.",h="Um Anel com Insígnia Escarlate é um anel de sinete usado por membros d'A Cruzada Escarlate aquartelados por...",kw={"montalvo","necroguarda belchior","executor zigano","prova da morte","cruzada escarlate","anel com insígnia escarlate","clareiras de tirisfal","varimatras"},ang={["faction:Horde"]="Coletar esses anéis ajuda a incipiente Horda a consolidar seu domínio nos Reinos do Leste, enfraquecendo os cruzados fanáticos que cercam a Cidade Baixa.",["race:Undead"]="Para os Renegados, arrancar esses anéis das mãos de cruzados mortos é uma declaração direta de que Tirisfal pertence aos mortos, cumprindo as ordens da Dama Sombria e de Varimatras."},sec={{t="Símbolos de Fanatismo",b="Todos os membros combatentes d'A Cruzada Escarlate nas Clareiras de Tirisfal — desde neófitos recém-chegados e frades zelosos até capitães experientes como Melrache e Perrine — carregam um anel com insígnia. Marcados com o emblema flamejante da Cruzada, os anéis identificam irmãos e irmãs dentro de uma organização consumida pela paranoia. Para estranhos e inimigos, no entanto, esses berloques servem a propósitos totalmente diferentes: são identificadores inequívocos do remanescente humano mais fanático de Lordaeron."},{t="Recompensa do Senhor do Medo",b="Sob o mandato direto de Varimatras, o tenente senhor do medo de Lady Sylvanas, o Necroguarda Belchior em Montalvo coleta ativamente esses anéis. Os Renegados consideram A Cruzada Escarlate uma praga intolerável rastejando por sua terra natal recém-conquistada. Para os recrutas Renegados, trazer pilhas desses anéis de volta a Montalvo é tratado como Prova da morte irrefutável e uma afirmação direta de lealdade ao trono da Cidade Baixa."}},faq={{q="Quem usa esses anéis com insígnia?",a="Quase qualquer membro d'A Cruzada Escarlate posicionado nas Clareiras de Tirisfal usa um. Isso inclui soldados rasos como neófitos, missionários, fanáticos e vanguardeiros, bem como oficiais de campo como o Capitão Perrine, o Capitão Melrache e o Capitão Vachon.",al={"quem dropa anéis","quais cruzados têm anéis","donos dos anéis"}},{q="Por que o Necroguarda Belchior quer os Anéis com Insígnia Escarlate?",a="O Necroguarda Belchior coleta os anéis como prova física de que os membros da Cruzada Escarlate estão sendo eliminados. Agindo com base em decretos originados de Varimatras e da Dama Sombria, a guarnição dos Renegados em Montalvo usa os anéis para medir a lealdade de um recruta e sua eficácia em expurgar os humanos de Lordaeron.",al={"por que coletar anéis","motivo de prova da morte","anéis de belchior"}},{q="O que a insígnia no anel representa?",a="O anel traz a marca d'A Cruzada Escarlate, simbolizando sua guerra santa para erradicar todos os mortos-vivos de Lordaeron. Os cruzados o usam com orgulho feroz, vendo-o como um emblema de retidão, mesmo enquanto sua obsessão os leva a massacrar qualquer um que não pertença à sua ordem.",al={"símbolo escarlate","o que é a insígnia","emblema do anel"}},{q="Qual é o papel de Varimatras na coleta desses anéis?",a="Varimatras atua como o principal tenente de Sylvana Correventos na Cidade Baixa. Ele supervisiona os esforços militares estratégicos para aniquilar humanos vivos hostis nas Clareiras de Tirisfal, tornando a erradicação d'A Cruzada Escarlate uma prioridade máxima para comandantes Renegados como o Executor Zigano e o Necroguarda Belchior.",al={"ordens de varimatras","por que varimatras quer anéis","envolvimento do senhor do medo"}}},fx={d4097e42={q="O que é um Anel com Insígnia Escarlate?",a="Um Anel com Insígnia Escarlate é um anel de identificação carregado por membros da The Scarlet Crusade pelas Clareiras de Tirisfal. Ostentando o emblema da ordem militante, ele marca a lealdade do usuário à sua cruzada fanática para erradicar a morte-viva. Para os Renegados que defendem suas novas fronteiras, esses anéis servem como prova indiscutível de que um soldado ou oficial inimigo foi eliminado.",al={"o que é anel com insígnia escarlate","história do anel com insígnia escarlate","o que são esses anéis"}}},fp="21,155,18.319.0,23.321.0,31.226.0,56.262.0,45.244.0,58.256.0"}
P.entries["item:scavenged-goods"] = {n="Material Reaproveitado",s="Material Reaproveitado consiste em diversas peças descartadas de equipamentos e mantimentos guardadas em caixas de equipamentos ao redor de Plangemortis. Renegados recém-erguidos os recuperam para garantir que o fluxo interminável de novos recrutas possa ser armado e vestido.",h="Material Reaproveitado consiste em diversas peças descartadas de equipamentos e mantimentos guardadas em...",kw={"necroguarda saulo","plangemortis","caixas de equipamentos","suprimentos dos renegados","material reaproveitado","vasculhando plangemortis"},ang={["race:Undead"]="Para os Renegados, vasculhar equipamentos descartados é uma necessidade de sobrevivência, consolidando a dura verdade de que os vivos não lhes concederão ajuda nem misericórdia."},sec={{t="Cuidando de Si Mesmos",b="Quando novos Renegados emergem da terra no cemitério de Plangemortis, eles despertam com pouco mais do que mortalhas apodrecidas. Os povoados e reinos vizinhos não oferecem ajuda aos mortos-vivos, deixando-os totalmente dependentes do que conseguem recuperar. O Necroguarda Saulo coordena a coleta de armas, ferramentas e vestimentas descartadas e escondidas em caixotes de suprimentos por toda a vila, distribuindo-as diretamente para a próxima leva de recrutas erguidos."}},faq={{q="Para que serve o material reaproveitado?",a="O Necroguarda Saulo os recolhe para equipar os novos recrutas Renegados que se erguem do cemitério. Sem resgatar restos dos caixotes próximos, os mortos-vivos recém-erguidos teriam que cambalear pelas Clareiras de Tirisfal completamente desarmados e despidos.",al={"propósito do material reaproveitado","por que coletar material reaproveitado","o que saulo faz com material reaproveitado"}},{q="Onde esses materiais são encontrados?",a="Eles são recuperados de caixas de equipamentos deixadas do lado de fora de chalés e ao redor de construções em ruínas por toda Plangemortis.",al={"onde encontrar material reaproveitado","localização do material reaproveitado","onde estão as caixas de equipamentos"}},{q="Quem pede o material reaproveitado?",a="O Necroguarda Saulo, um oficial destacado em Plangemortis, orienta os Renegados recém-despertados a recolher essas provisões para ensiná-los a ter autossuficiência e prepará-los para as próximas levas.",al={"quem quer material reaproveitado","missão necroguarda saulo"}}},fx={f565021a={q="O que é o Material Reaproveitado?",a="São peças sortidas de equipamentos, roupas e utensílios úteis recuperados de velhos caixotes deixados espalhados por Plangemortis. Em vez de armamentos intactos, eles são restos descartados da vida passada da cidade que ainda podem servir a um propósito prático para os Renegados recém-despertados.",al={"o que é material reaproveitado"}},["0b2267aa"]={q="De onde vem o Material Reaproveitado?",a="Eles vêm de caixas de equipamento abandonadas entre as estruturas arruinadas de Plangemortis. Outrora pertencentes aos habitantes vivos de Lordaeron antes de o reino cair perante a praga, esses suprimentos permaneceram esquecidos nas ruínas até que os Renegados começassem a reivindicar a cidade como sua base de operações.",al={"origem do material reaproveitado","quem fez o material reaproveitado","de onde veio o material reaproveitado"}},["36f8df02"]={q="Por que o Necroguarda Saulo quer o Material Reaproveitado?",a="Os Renegados estão continuamente despertando mortos recém-erguidos do cemitério, e esses novos recrutas entram no mundo com quase nada. O Necroguarda Saulo reúne esses itens recuperados para que os mortos-vivos emergentes tenham roupas e equipamentos básicos em vez de tropeçar no serviço desarmados e expostos.",al={"por que saulo quer o material reaproveitado","por que coletar material reaproveitado","por que o material reaproveitado é necessário"}}},fp="15,161,22.332.0,34.183.0,28.96.0,33.170.0"}
P.entries["item:scavenger-paw"] = {n="Pata de Carniceiro",s="Patas de Carniceiro são membros decepados obtidos dos lobos jovens e esfarrapados que vagam pelas colinas de Plangemortis. Renegados recém-despertados as recolhem para que os cuidadores locais as costurem em equipamentos rústicos de proteção.",h="Patas de Carniceiro são membros decepados obtidos dos lobos jovens e esfarrapados que vagam pelas colinas de...",kw={"plangemortis","noviça elvira","ragged scavenger","pata de carniceiro","os malditos","young scavenger"},ang={["profession:Tailoring"]="A confecção rústica a partir de patas de lobo e asas de morcego pela Noviça Elvira demonstra como a costura improvisada sustenta os primeiros assentamentos dos Renegados.",["race:Undead"]="Ao despertar com carne em decomposição e poucos equipamentos, recolher partes de predadores locais costuma ser o primeiro passo para montar armadura suficiente para resistir aos perigos de Tirisfal."},sec={{t="Armadura Improvisada em Plangemortis",b="Os recursos são escassos para os recém-retornados em Plangemortis. Com o Flagelo e a Cruzada Escarlate pressionando Tirisfal, cada pedaço de pele e osso tem uso prático. A Noviça Elvira, assistente do Sacerdote Sombrio Sarvis, recolhe patas dos lobos carniceiros locais junto com asas de morcego para confeccionar vestimentas e armaduras úteis para os Renegados desorientados que acabam de sair de suas sepulturas."}},faq={{q="Para que servem as Patas de Carniceiro?",a="Elas são recolhidas pela Noviça Elvira em Plangemortis, que costura partes brutas de animais para criar armaduras básicas e vestimentas remendadas para os novos iniciados Renegados.",al={"objetivo da pata de carniceiro","uso para patas","por que recolher patas"}},{q="Onde encontrá-las?",a="Elas são obtidas de Young Scavengers e Ragged Scavengers, os lobos ferozes que vagam pelos bosques e campos ao redor de Plangemortis.",al={"local de saque da pata","onde conseguir patas","quais lobos dropam patas"}},{q="Quem pede essas patas?",a="A Noviça Elvira, que auxilia o Sacerdote Sombrio Sarvis cuidando de recrutas feridos, costurando equipamentos e equipando aqueles enviados para o campo.",al={"quem quer patas de carniceiro","iniciador da missão das patas","patas da noviça elvira"}}},fx={["41bb56d4"]={q="O que é uma Pata de Carniceiro?",a="Uma Pata de Carniceiro é a pata decepada de um lobo carniceiro que vaga pelas florestas assombradas das Clareiras de Tirisfal ao redor de Plangemortis. Embora pareçam troféus sombrios, essas partes animais duráveis servem como matéria-prima para os Renegados recém-despertados, que precisam utilizar cada pedaço da vida selvagem nativa para criar necessidades e sobreviver.",al={"identidade de pata de carniceiro","o que são patas de carniceiro","o que é pata de carniceiro"}},["366465d3"]={q="De onde vem uma Pata de Carniceiro?",a="Essas patas são colhidas dos jovens e esfarrapados lobos carniceiros que rondam o perímetro de Plangemortis. Espreitando as clareiras definhadas logo além das muralhas da vila, essas feras selvagens vasculham o campo assolado por carniça, tornando-as presas fáceis para os novos recrutas Renegados que buscam provar sua força.",al={"origem de pata de carniceiro","onde conseguir pata de carniceiro","patas de lobo carniceiro"}},f83538b8={q="Por que alguém quer Patas de Carniceiro?",a="A Noviça Elvira em Plangemortis coleta-as para costurar armaduras e roupas resistentes para os soldados Renegados recém-despertados. Os recursos são escassos para os mortos-vivos livres recém-nascidos, e Elvira junta peles, asas e patas para remendar equipamentos que podem proteger você dos mortos-vivos irracionais e dos cruzados da The Scarlet Crusade que ameaçam o refúgio.",al={"por que coletar patas de carniceiro","quem precisa de patas de carniceiro","uso de patas de carniceiro lore"}}},fp="13,178,27.408.0,33.132.0,23.117.0,24.158.0"}
P.entries["item:sceptre-of-light"] = {n="Sceptre of Light",s="O Sceptre of Light é uma relíquia que, segundo dizem, pode afundar cidades sob o mar. Um vidente da Lâmina Ardente o guarda na Fortaleza Machado do Trovão, na Desolação.",h="O Sceptre of Light é uma relíquia que, segundo dizem, pode afundar cidades sob o mar.",kw={"azore albamorte","lâmina ardente","desolação","ethel rethor","naga","sceptre of light","vidente","fortaleza machado do trovão"},sec={{t="O prêmio de um vidente",b="De uma torre de vigia na Fortaleza Machado do Trovão, um vidente da Lâmina Ardente estuda o Sceptre of Light. Dizem que a Lâmina Ardente o tomou dos naga. As lendas afirmam que seu poder pode afundar cidades inteiras sob o mar, por isso Azore Albamorte, em Ethel Rethor, busca recuperá-lo."}},faq={{q="O que o Sceptre of Light faz?",a="Diz a lenda que o Sceptre of Light pode afundar cidades inteiras sob o mar.",al={"poder do cetro","o que ele faz","cetro da luz"}},{q="Quem está com o Sceptre of Light?",a="Um vidente da Lâmina Ardente estuda o Sceptre of Light de uma torre de vigia na Fortaleza Machado do Trovão.",al={"quem está com ele","quem está com o cetro","cetro da lâmina ardente"}},{q="Onde está o Sceptre of Light?",a="O Sceptre of Light está na Fortaleza Machado do Trovão, na Desolação.",al={"onde está o cetro","localização do cetro","cetro da fortaleza machado do trovão"}},{q="Quem quer o cetro de volta?",a="Azore Albamorte, na torre de Ethel Rethor, quer o Sceptre of Light de volta.",al={"quem quer o cetro","azore e o cetro","ethel rethor"}},{q="Onde a Lâmina Ardente o conseguiu?",a="Dizem que a Lâmina Ardente conseguiu o Sceptre of Light com os naga.",al={"cetro dos naga","de onde veio","origem do cetro"}}},fp="16,135,16.270.0,34.72.0,29.92.0,30.65.0,31.80.0,35.81.0"}
P.entries["item:scorched-ectoplasm"] = {n="Scorched Ectoplasm",s="Ectoplasma Chamuscado é matéria espectral coletada dos espíritos atormentados de elfos noturnos em Silithus. Mux Zoamana precisa dela para seu trabalho com os mortos.",h="Ectoplasma Chamuscado é matéria espectral coletada dos espíritos atormentados de elfos noturnos em Silithus.",kw={"ectoplasma","destilador ectoplásmico","geringontzan","mux zoamana","ectoplasma chamuscado","silithus","druida atormentado","sentinela atormentada"},ang={["profession:Engineering"]="Como engenheiro, você talvez reconheça o Destilador Ectoplásmico como o dispositivo de Mux Zoamana para coletar matéria espectral."},sec={{t="Um Vestígio Chamuscado",b="Em Silithus, os espíritos atormentados de druidas e Sentinelas fornecem Ectoplasma Chamuscado. Mux Zoamana, um engenheiro goblin de Geringontzan, procura essa substância e outras formas de ectoplasma. Ele acredita que suas energias estranhas podem alcançar almas que permanecem perto do mundo dos vivos."}},faq={{q="O que é Ectoplasma Chamuscado?",a="É matéria espectral retirada dos espíritos atormentados de elfos noturnos de Silithus.",al={"ectoplasma chamuscado","o que é ectoplasma chamuscado","item de ectoplasma"}},{q="De onde vem o Ectoplasma Chamuscado?",a="Druidas Atormentados e Sentinelas Atormentadas em Silithus fornecem Ectoplasma Chamuscado.",al={"onde encontrar ectoplasma chamuscado","localização do ectoplasma chamuscado","onde conseguir"}},{q="Por que Mux Zoamana o quer?",a="Mux Zoamana espera usar as energias sobrenaturais do ectoplasma para alcançar almas que permanecem perto do mundo dos vivos.",al={"por que mux quer ectoplasma","mux e ectoplasma","o que mux está fazendo"}},{q="Quais são os outros tipos de ectoplasma?",a="Ectoplasma Congelado vem de espíritos Altaneiros em Hibérnia, enquanto Ectoplasma Estável vem de fantasmas e banshees nas Terras Pestilentas Orientais.",al={"outros ectoplasmas","ectoplasma congelado e estável","tipos de ectoplasma"}},{q="Onde posso encontrar Mux Zoamana?",a="Mux Zoamana pode ser encontrado em Geringontzan, em Tanaris.",al={"onde está mux","localização de mux","goblin de geringontzan"}}},fp="18,146,16.265.0,27.76.0,40.76.0,35.119.0,38.144.0,35.56.0"}
P.entries["item:scorched-spider-fang"] = {n="Presa de Aranha Calcinada",s="Presas de Aranha Calcinadas são materiais especializados de criação coletados de aracnídeos predadores que espreitam nas cavernas encharcadas de Pantanal. O armeiro anão Furen Barbalonga precisa de uma quantidade substancial dessas presas temperadas pelo calor para forjar uma malha resistente e endurecida pelo fogo para guerreiros experientes.",h="Presas de Aranha Calcinadas são materiais especializados de criação coletados de aracnídeos predadores que...",kw={"cave stalker","malha endurecida a fogo","furen barbalonga","leech stalker","presa de aranha calcinada","ventobravo","pantanal"},ang={["class:Warrior"]="Juntar cinquenta dessas presas é uma das provações árduas designadas por Furen Barbalonga para testar sua resistência e fornecer os componentes brutos para a sua armadura de malha personalizada.",["profession:Blacksmithing"]="O método de Furen de incorporar quitina e presas calcinadas em elos de malha oferece um vislumbre das raras tradições anãs de armaria, que vão muito além da fundição convencional."},sec={{t="A Fórmula de um Ferreiro Anão",b="Forjar uma armadura capaz de desviar lâminas e resistir a traumas violentos exige mais do que ferro comum. No movimentado distrito de Ventobravo, o habilidoso ferreiro Furen Barbalonga usa técnicas metalúrgicas obscuras que combinam partes de feras com reagentes raros. Furen exige cinquenta presas calcinadas dos aracnídeos gigantes dos pântanos, utilizando sua composição densa, venenosa e naturalmente endurecida para reforçar os elos de malha durante o processo de têmpera."},{t="Espreitadores de Pantanal",b="Essas presas são extraídas diretamente dos aracnídeos letais que habitam os vales submersos e tocas de Pantanal, principalmente Cave Stalkers e Leech Stalkers. Apesar do ambiente úmido e pútrido do pântano, esses predadores possuem mandíbulas peculiarmente endurecidas e calcinadas. Coletá-las nas quantidades que Furen exige requer aventurar-se em cavidades profundas e exterminar enxames inteiros de pragas monstruosas."}},faq={{q="Para que servem as Presas de Aranha Calcinadas?",a="Elas são coletadas para Furen Barbalonga, um armeiro localizado em Ventobravo. Ele precisa de cinquenta delas, junto com componentes de Cordilheira das Torres de Pedra e Urzal dos Tuscos, para forjar um peitoral excepcionalmente durável para guerreiros da Aliança.",al={"o que fazer com presa de aranha calcinada","utilidade da presa de aranha calcinada","quem precisa de presa de aranha calcinada"}},{q="Onde posso encontrar Presas de Aranha Calcinadas?",a="Elas são obtidas de aracnídeos em Pantanal, especificamente Leech Stalkers e Cave Stalkers encontrados à espreita nas tocas úmidas, encostas e cavernas de escavação da região.",al={"onde cai presa de aranha calcinada","quais aranhas dropam presa de aranha calcinada","onde farmar presas de aranha calcinadas"}},{q="Por que um ferreiro precisa de tantas presas de aranha para fazer uma armadura?",a="Furen Barbalonga emprega métodos de forja anões pouco ortodoxos. As propriedades densas em minerais e resistentes ao fogo dessas presas endurecidas servem como um agente de endurecimento não convencional, reforçando os elos de malha quando tratadas juntamente com flogisto e chifres de fera.",al={"por que 50 presas","por que furen precisa de presas de aranha"}},{q="Qualquer aventureiro pode coletar e entregar essas presas?",a="Embora qualquer um que viaje por Pantanal possa abater as aranhas e coletar suas mandíbulas, Furen Barbalonga só encomenda o projeto de criação para guerreiros aspirantes que buscam obter sua malha endurecida pelo fogo.",al={"presa de aranha calcinada e so para guerreiro","quem pode entregar presas de aranha calcinadas"}}},fx={a7a99cbb={q="O que é uma Presa de Aranha Calcinada?",a="Uma Presa de Aranha Calcinada é um dente venenoso endurecido e tratado termicamente, colhido de aracnídeos predadores como Perseguidores das Cavernas e Perseguidores Sanguessugas que espreitam no Pantanal. Sua aparência enegrecida e quebradiça esconde uma densidade extraordinária, tornando-as valiosas entre armeiros habilidosos que buscam componentes raros para técnicas avançadas de forja.",al={"o que é presa de aranha calcinada","presas de aranha calcinada","presa calcinada"}},c6d8f632={q="De onde vêm as Presas de Aranha Calcinada?",a="Essas presas não são criadas por mãos mortais; elas são colhidas diretamente dos aracnídeos gigantes do Pantanal, especificamente Perseguidores Sanguessugas e Perseguidores das Cavernas. A exposição constante aos elementos subterrâneos e a alquimia natural de seu veneno dá a essas presas sua resiliência enegrecida e tratada pelo fogo.",al={"de onde vêm as presas de aranha calcinada","origem da presa de aranha calcinada","fonte da presa de aranha calcinada"}}},fp="20,165,25.253.0,24.267.0,40.185.0,39.138.0,62.133.0,51.175.0"}
P.entries["item:scorpashi-venom"] = {n="Scorpashi Venom",s="O veneno Scorpashi é um reagente extraído dos escorpiões que vagam pela Desolação. Kreldig Ungor precisa dele para uma lista de materiais solicitada pela Reclaimers Inc.",h="O veneno Scorpashi é um reagente extraído dos escorpiões que vagam pela Desolação.",kw={"couro de kodo envelhecido","desolação","kreldig ungor","leftwitch","reclaimers inc","scorpashi","veneno scorpashi"},ang={["class:Mage"]="A lista de Leftwitch pede veneno Scorpashi, um dos reagentes mais incomuns que um mago pode buscar."},sec={{t="A lista de um Mago",b="Kreldig Ungor está reunindo materiais na Desolação para a Reclaimers Inc., seguindo uma lista preparada por Leftwitch. O veneno Scorpashi é um dos itens exigidos pelo mago, junto com couro de kodos envelhecidos. Kreldig está ansioso para terminar a lista e voltar a Altaforja."}},faq={{q="Para que serve o veneno Scorpashi?",a="Leftwitch precisa do veneno Scorpashi para uma lista de materiais reunidos por Kreldig Ungor para a Reclaimers Inc.",al={"uso do veneno scorpashi","por que coletar veneno","reagente de veneno"}},{q="Quem precisa do veneno?",a="Kreldig Ungor está coletando o veneno na Desolação para a Reclaimers Inc., seguindo a lista de Leftwitch.",al={"quem quer veneno scorpashi","veneno de kreldig","quem precisa dele"}},{q="De onde vem o veneno Scorpashi?",a="O veneno Scorpashi vem dos escorpiões encontrados por toda a Desolação.",al={"onde encontrar veneno","localização dos scorpashi","origem do veneno"}},{q="Que outro material está na lista de Leftwitch?",a="Kreldig também precisa de couro de kodos envelhecidos; as instruções de Leftwitch especificam kodos envelhecidos, e não moribundos ou ancestrais.",al={"outro reagente","o que mais kreldig precisa","couro de kodo envelhecido"}}},fp="15,147,15.257.0,33.104.0,20.100.0,37.67.0,45.120.0"}
P.entries["item:scrap-metal-scrounging"] = {n="Scrap Metal",s="Sucata é recolhida dos ogros da Gruta Arrota-pó, nos Ermos. Sigrun precisa dela para construir defesas e conseguir suprimentos para um pequeno acampamento.",h="Sucata é recolhida dos ogros da Gruta Arrota-pó, nos Ermos.",kw={"ermos","acampamento","gruta arrota-pó","explorers' league","altaforja","ogros","sucata","scrounging","sigrun"},ang={["profession:Engineering"]="Como engenheiro, você entende por que Sigrun precisa de sucata: faltam materiais para as defesas e outras necessidades do acampamento.",["race:Dwarf"]="Como anão, você talvez saiba que o acampamento aguarda notícias de Altaforja enquanto Sigrun se vira com os suprimentos disponíveis."},sec={{t="Para o acampamento",b="Sigrun precisa de sucata para as defesas e outras necessidades do acampamento nos Ermos. Os ogros da Gruta Arrota-pó, a oeste, carregam sucata, e o acampamento tem pouca reserva. Até chegarem notícias de Altaforja ou da Explorers' League, cada peça ajuda."}},faq={{q="Para que serve a sucata?",a="Sigrun precisa de sucata para construir defesas e outras estruturas necessárias ao acampamento nos Ermos.",al={"uso da sucata","por que coletar sucata","metal para sigrun"}},{q="Onde posso encontrar sucata?",a="Os ogros da Gruta Arrota-pó, a oeste do acampamento de Sigrun nos Ermos, carregam sucata.",al={"localização da sucata","onde encontrar metal","metal da gruta arrota-pó"}},{q="Quem quer a sucata?",a="Sigrun quer sucata para ajudar a abastecer e defender o acampamento.",al={"quem precisa de metal","sucata para sigrun","metal para quem"}},{q="Por que Sigrun está reunindo suprimentos?",a="Sigrun tem poucos materiais para as defesas e outras necessidades do acampamento, então está reunindo o que consegue.",al={"suprimentos necessários ao acampamento","por que recolher sucata","defesas de sigrun"}}},fp="11,141,12.251.0,24.98.0,29.88.0,26.60.0,33.105.0"}
P.entries["item:scrimshank-s-surveying-gear"] = {n="Scrimshank's Surveying Gear",s="O equipamento topográfico de Scrimshank está sob as areias de Tanaris, na Fenda Hazzali. O Topógrafo Sênior Secamolha precisa de seus registros para investigar os insetos estranhos do deserto.",h="O equipamento topográfico de Scrimshank está sob as areias de Tanaris, na Fenda Hazzali.",kw={"secamolha","fenda hazzali","goblin","topógrafo júnior","scrimshank","silitídeo","equipamento topográfico","tanaris"},sec={{t="Sob as areias",b="Na Fenda Hazzali, em Tanaris, o equipamento topográfico de Scrimshank é tudo o que restou do Topógrafo Júnior desaparecido. Seu superior, Secamolha, enviou-o ao deserto após relatos de insetos estranhos. A máquina guarda os últimos registros de Scrimshank, que podem ajudar a explicar o perigo que ameaça Geringontzan."}},faq={{q="O que é o equipamento topográfico de Scrimshank?",a="É o equipamento topográfico do Topógrafo Júnior Scrimshank, encontrado sob Tanaris, na Fenda Hazzali.",al={"equipamento de scrimshank","máquina topográfica","o que é o equipamento"}},{q="Onde está o equipamento topográfico?",a="O equipamento topográfico de Scrimshank está na Fenda Hazzali, sob Tanaris.",al={"local do equipamento","onde estão as coisas de scrimshank","equipamento da fenda hazzali"}},{q="Quem era Scrimshank?",a="O Topógrafo Júnior Scrimshank era assistente do Topógrafo Sênior Secamolha e foi enviado para investigar insetos estranhos na Fenda Hazzali.",al={"topógrafo júnior","história de scrimshank","quem é scrimshank"}},{q="Por que Secamolha quer o equipamento?",a="Secamolha espera que os registros de Scrimshank ajudem a revelar o que está acontecendo com os insetos estranhos do deserto.",al={"importância do equipamento","secamolha quer o equipamento","o que foi registrado"}}},fp="27,178,17.297.0,36.103.0,28.69.0,19.126.0,36.111.0"}
P.entries["item:scroll-of-messaging"] = {n="Pergaminho de Mensagem",s="O Pergaminho de Mensagem é um pergaminho encantado que contém um feitiço mágico específico de envio. Adquirido para o engenheiro gnomo Gaxim Deuxabu na Cordilheira das Torres de Pedra, ele serve a um propósito incomum: fornecer o gatilho mágico necessário para detonar explosivos à distância.",h="O Pergaminho de Mensagem é um pergaminho encantado que contém um feitiço mágico específico de envio.",kw={"explosivos","gaxim deuxabu","ng-5","detonador remoto","pergaminho de mensagem","cordilheira das torres de pedra","empreendimentos s.a."},ang={["faction:Alliance"]="O pergaminho desempenha um papel fundamental ao ajudar agentes da Aliança a sabotar o maquinário da Empreendimentos S.A. e conter a devastação ambiental nas Torres de Pedra.",["profession:Engineering"]="Fiel à inovação gnômica, este pergaminho demonstra como a magia arcana teórica pode ser reaproveitada como um receptor remoto para demolições mecânicas."},sec={{t="Uma Mensagem Volátil",b="Embora ostensivamente seja uma escrita arcana destinada à comunicação de longa distância, Gaxim Deuxabu tem uma aplicação muito mais disruptiva em mente para o Pergaminho de Mensagem. Ao combinar seu encantamento de transmissão com cargas voláteis de NG-5, o gnomo planeja criar um explosivo detonado remotamente. A explosão resultante tem o objetivo de desencadear uma distração em massa na operação madeireira da Empreendimentos S.A. nas Torres de Pedra, concedendo aos agentes uma oportunidade para passar despercebidos pelos guardas e furtar esquemas de engenharia proprietários e correspondências confidenciais."}},faq={{q="Para que serve o Pergaminho de Mensagem?",a="Embora tenha sido escrito como um feitiço de mensagens, Gaxim Deuxabu usa sua magia de transmissão para criar um detonador remoto. Quando combinado com o explosivo NG-5, ele permite detonar uma explosão a uma distância segura.",al={"uso do pergaminho de mensagem","o que faz o pergaminho de mensagem","por que gaxim quer o pergaminho"}},{q="Quem recebe este pergaminho?",a="O pergaminho é entregue a Gaxim Deuxabu, um engenheiro gnomo aliado da Aliança que opera na Cordilheira das Torres de Pedra.",al={"quem recebe o pergaminho de mensagem","onde levar o pergaminho de mensagem","destinatário do pergaminho"}},{q="Por que Gaxim precisa de um explosivo remoto?",a="Gaxim precisa de uma grande distração na operação local da Empreendimentos S.A. O caos resultante fornece cobertura para se infiltrar no complexo deles, roubar projetos de engenharia valiosos e recuperar documentos para deter o desmatamento agressivo da floresta.",al={"motivo do explosivo de gaxim","por que explodir a empreendimentos s.a.","distração nas torres de pedra"}},{q="O que é NG-5?",a="NG-5 é uma carga química explosiva utilizada por Gaxim Deuxabu. Combinada com o sinal mágico inscrito no Pergaminho de Mensagem, ela forma um dispositivo improvisado de detonação remota.",al={"ng-5","o que é ng-5","explosivo ng5"}}},fx={["2071477e"]={q="O que é o Pergaminho de Mensagem?",a="O Pergaminho de Mensagem é um pergaminho encantado contendo um feitiço arcano. Gaxim Deuxabu procurou-o como um catalisador não convencional para combinar com seu composto explosivo volátil, NG-5, permitindo-lhe criar uma carga acionada remotamente contra as operações da Empreendimentos S.A. na Cordilheira das Torres de Pedra.",al={"o que é pergaminho de mensagem","história do pergaminho de mensagem","sobre o pergaminho de mensagem"}}},fp="19,98,18.314.0,41.152.0,25.84.0,39.220.0,13.130.0"}
P.entries["item:scroll-of-myzrael"] = {n="Pergaminho de Myzrael",s="O Pergaminho de Myzrael é usado nos Shards of Myzrael, no Planalto Arathi, para invocá-la novamente.",h="O Pergaminho de Myzrael é usado nos Shards of Myzrael, no Planalto Arathi, para invocá-la novamente.",kw={"planalto arathi","grilhões sobrenaturais","myzrael","princesa","pergaminho de myzrael","shards of myzrael","invocação"},sec={{t="Nos Shards",b="Nos Shards of Myzrael, no Planalto Arathi, o pergaminho invoca a criatura aprisionada sob eles. Myzrael deve ser derrotada, e seus Grilhões Sobrenaturais, presos aos fragmentos. O objetivo é mantê-la cativa enquanto seu poder cresce."}},faq={{q="Para que serve o Pergaminho de Myzrael?",a="O Pergaminho de Myzrael é usado para invocar Myzrael nos Shards of Myzrael, no Planalto Arathi.",al={"uso do pergaminho de myzrael","para que serve este pergaminho","invocar myzrael"}},{q="Onde uso o pergaminho?",a="O pergaminho é usado nos Shards of Myzrael, no Planalto Arathi, onde Myzrael foi encontrada pela primeira vez.",al={"onde fica o pergaminho","localização dos shards of myzrael","onde invocá-la"}},{q="Por que invocar Myzrael?",a="Myzrael deve ser derrotada antes que seu poder cresça e, depois, aprisionada novamente nos fragmentos com seus Grilhões Sobrenaturais.",al={"por que invocar myzrael","qual é o objetivo","por que chamá-la"}},{q="Para que servem os Grilhões Sobrenaturais?",a="Os Grilhões Sobrenaturais são presos aos Shards of Myzrael para aprisioná-la novamente.",al={"objetivo dos grilhões sobrenaturais","grilhões de myzrael","como aprisioná-la"}}},fp="17,103,13.232.0,35.97.0,26.105.0,19.107.1,35.75.1"}
P.entries["item:sea-creature-bones"] = {n="Ossos de Criaturas Marinhas",s="Ossos de Criaturas Marinhas são amostras esqueléticas recolhidas das carcaças marinhas gigantescas que chegam à costa encoberta pela névoa de Costa Negra. Enviados diretamente para O Templo da Lua em Darnassus, estes restos mortais são peças centrais em uma investigação contínua sobre o que está levando essas grandes feras a encalharem nas praias.",h="Ossos de Criaturas Marinhas são amostras esqueléticas recolhidas das carcaças marinhas gigantescas que chegam...",kw={"auberdine","criatura marinha encalhada","costa negra","murlocs greymist","gwennyth bly'leggonde","beira das névoas","ossos de criaturas marinhas","templo da lua"},ang={["class:Druid"]="As mortes inexplicáveis de predadores marinhos ancestrais sinalizam uma profunda perturbação nas águas ao largo de Kalimdor, inquietando qualquer guardião dedicado a preservar o equilíbrio ecológico.",["race:NightElf"]="Os repentinos encalhes em massa ao longo de Costa Negra perturbam profundamente os elfos noturnos, que reverenciam a harmonia do mundo natural e veem esses incidentes como um mau agouro que exige a atenção do Templo da Lua."},sec={{t="Um Presságio na Costa",b="As praias cobertas de névoa de Costa Negra testemunharam recentemente um aumento alarmante de criaturas marinhas gigantescas — incluindo debulhadores gigantes bem maiores do que os nativos das águas rasas locais — lançando-se contra a praia até morrerem. O ocorrido é considerado um presságio sombrio pelos elfos noturnos. Gwennyth Bly'Leggonde, uma investigadora enviada pelo Templo da Lua a Auberdine, coleta amostras de ossos desses leviatãs encalhados para enviá-las por hipogrifo a Darnassus para exame detalhado."},{t="Carniça e Necrófagos",b="Recuperar estes ossos é uma tarefa repleta de perigos, já que as imensas carcaças inevitavelmente atraem carniceiros locais. Os murlocs Greymist costeiros costumam se aglomerar em torno dos leviatãs mortos e moribundos, banqueteando-se com os restos e defendendo os locais de alimentação de forma agressiva. Embora os murlocs sejam fracos demais para caçar criaturas tão colossais sozinhos, sua presença oportunista ao longo da Beira das Névoas força investigadores e aventureiros a abrirem caminho pelos bandos de carniceiros para conseguir fragmentos de ossos viáveis para estudo."}},faq={{q="Por que essas criaturas estão encalhando?",a="A causa exata permanece desconhecida. Embora encalhes ocasionais sejam um risco natural, seu aumento súbito e dramático é considerado antinatural e alarmante pelas sacerdotisas de Elune, motivando uma investigação formal.",al={"por que os debulhadores estao encalhando","baleias mortas costa negra","por que as criaturas encalham costa negra"}},{q="Quem quer esses ossos?",a="Gwennyth Bly'Leggonde, uma investigadora instalada em Auberdine, recolhe os ossos em nome do Templo da Lua em Darnassus, onde eruditos e sacerdotisas esperam determinar o que está perturbando os mares.",al={"quem pega os ossos","quem entrega ossos de criaturas marinhas","gwennyth costa negra"}},{q="Os murlocs mataram essas feras gigantes?",a="Não. Os murlocs Greymist locais são fracos demais para abater feras marinhas desse porte. Eles são apenas necrófagos que se reúnem em grandes números para se alimentar das carcaças assim que elas encalham.",al={"os murlocs mataram o debulhador","murlocs greymist mataram monstro marinho"}},{q="De onde os ossos são recuperados?",a="Eles são recolhidos diretamente das carcaças gigantescas encalhadas ao longo do litoral de Costa Negra, em especial nas areias ao sul de Auberdine e pela Beira das Névoas.",al={"onde encontrar ossos de criaturas marinhas","localizacoes de criatura marinha encalhada"}}},fx={["90a4db20"]={q="O que são estes Ossos de Criaturas Marinhas?",a="Eles são restos esqueléticos recuperados da carcaça maciça de uma besta marinha que encalhou — especificamente um tubarão-raposa incomumente grande — ao longo da costa enevoada de Costa Negra. Recuperados pelos murlocs da Neblina Cinzenta locais, esses restos maciços servem como prova física vital para pesquisadores que tentam entender por que os gigantes do oceano estão perecendo na costa.",al={"o que são ossos de criaturas marinhas","história dos ossos de criaturas marinhas","ossos gigantes em costa negra"}},cb40613a={q="De onde vêm os Ossos de Criaturas Marinhas?",a="Esses ossos vêm de um tubarão-raposa colossal, muito maior do que qualquer um esperado nas águas de Costa Negra, que inexplicavelmente se lançou nas praias da Beira das Névoas ao sul de Auberdine. Em vez de serem criados ou mortos por predadores locais, os ossos pertencem naturalmente a bestas das profundezas que misteriosamente se lançaram à costa para morrer.",al={"de onde vêm os ossos de criaturas marinhas","origem dos ossos de criaturas marinhas","origem de criatura marinha encalhada"}}},fp="18,223,22.411.0,22.319.0,39.208.0,22.166.0,40.143.0,35.129.0"}
P.entries["item:sea-turtle-remains"] = {n="Carcaça de Tartaruga Marinha",s="A Carcaça de Tartaruga Marinha consiste em amostras esqueléticas recuperadas das carcaças de tartarugas marinhas gigantes ao longo da costa de Costa Negra. Elas servem como espécimes vitais para pesquisadores elfos noturnos em Auberdine que investigam um aumento alarmante de encalhes marinhos.",h="A Carcaça de Tartaruga Marinha consiste em amostras esqueléticas recuperadas das carcaças de tartarugas...",kw={"auberdine","tartaruga marinha encalhada","costa negra","gwennyth bly'leggonde","carcaça de tartaruga marinha","teldrassil","templo da lua","deixa a água me levar"},ang={["class:Druid"]="A morte antinatural de leviatãs marinhos selvagens sinaliza uma corrupção mais profunda que abala o equilíbrio da natureza ao longo da costa de Kalimdor.",["race:NightElf"]="O encalhe em massa da vida marinha diante de sua costa ancestral é um presságio sombrio, especialmente com suspeitas apontando de volta para as águas que cercam Teldrassil."},sec={{t="Um Encalhe Perturbador",b="Criaturas marinhas gigantes começaram a encalhar ao longo de toda a costa envolta em névoa de Costa Negra, enquanto outras jazem submersas perto da costa, junto a destroços naufragados. Gwennyth Bly'Leggonde, posicionada em Auberdine, supervisiona a coleta de fragmentos esqueléticos e tecidos desses corpos. O Templo da Lua em Darnassus solicita essas amostras com urgência, preocupado com teorias de que as feras possam estar fugindo de uma perturbação antinatural nas águas que cercam a recém-nascida árvore do mundo, Teldrassil."},{t="Carniceiros dos Rasos",b="Recuperar esses restos mortais é um trabalho perigoso. Tribos costeiras de murlocs rotineiramente se reúnem ao redor das carcaças colossais, limpando a carne dos ossos e fazendo ninhos ao lado delas. Os estudiosos necessitam de fragmentos ósseos e tecidos frescos antes que os carniceiros destruam qualquer evidência sobrevivente que possa explicar a migração fatal dessas criaturas."}},faq={{q="Para que esses restos são usados?",a="Os restos são coletados por Gwennyth Bly'Leggonde em Auberdine. Ela os prepara para estudiosos e sacerdotisas no Templo da Lua em Darnassus, que tentam discernir por que tantas criaturas oceânicas estão morrendo ao longo de Costa Negra.",al={"por que coletar restos de tartaruga","uso dos ossos de tartaruga","missão tartaruga marinha costa negra"}},{q="Por que as tartarugas marinhas estão encalhando em Costa Negra?",a="A causa exata continua sob investigação, mas os pesquisadores temem que a vida marinha esteja fugindo de algo perturbador nas águas ao redor de Teldrassil. Os encalhes não são incidentes isolados, apontando para um sofrimento ecológico generalizado.",al={"por que as tartarugas estão morrendo","encalhe de tartarugas costa negra","criaturas marinhas encalhadas"}},{q="Onde essas carcaças são encontradas?",a="Tartarugas marinhas esqueléticas gigantes estão espalhadas pelo litoral de Costa Negra, com algumas repousando em águas rasas perto de navios naufragados a oeste de Auberdine e outras espalhadas pelas praias cercadas por acampamentos de murlocs.",al={"localizações dos restos de tartaruga","onde encontrar tartaruga marinha esqueletica"}},{q="Quem está estudando esses restos?",a="Gwennyth Bly'Leggonde, uma pesquisadora em Auberdine, reúne os achados e envia relatórios detalhados diretamente para a Irmandade de Eluna no Templo da Lua em Darnassus.",al={"quem quer os restos","gwennyth blyleggonde"}}},fx={dfe0d6c5={q="O que é essa Carcaça de Tartaruga Marinha?",a="Estes restos são amostras esqueléticas recuperadas de tartarugas marinhas gigantes que deram à costa ao longo do litoral de Costa Negra ou morreram em suas águas rasas. Embora recuperados por predadores locais e murlocs, ossos e tecidos recuperáveis permanecem, oferecendo pistas físicas sobre os momentos finais das criaturas.",al={"o que é carcaça de tartaruga marinha","história da carcaça de tartaruga marinha"}},be90da46={q="De onde vem a Carcaça de Tartaruga Marinha?",a="Eles são coletados diretamente de carcaças esqueléticas maciças que jazem ao longo das margens e águas costeiras de Costa Negra, incluindo espécimes perto de Auberdine. São restos naturais de bestas marinhas em vez de objetos criados, deixados para trás quando tartarugas moribundas nadam até a terra e perecem.",al={"de onde vem a carcaça de tartaruga marinha","origem da carcaça de tartaruga marinha","fonte da carcaça de tartaruga marinha"}}},fp="18,149,19.379.0,26.287.0,32.199.0,53.195.0,32.181.0,30.150.0"}
P.entries["item:seahorn-s-sealed-letter"] = {n="Seahorn's Sealed Letter",s="A carta lacrada de Seahorn leva uma mensagem secreta de Angra do Butim a Juanka Nabrava, na costa de Arathi. Os Blackwater Raiders contam com sua entrega segura.",h="A carta lacrada de Seahorn leva uma mensagem secreta de Angra do Butim a Juanka Nabrava, na costa de Arathi.",kw={"arathi coast","blackwater raiders","angra do butim","seahorn","carta lacrada","correspondência secreta","juanka nabrava"},sec={{t="Uma Mensagem Lacrada",b="De Angra do Butim, Seahorn pede que você leve sua carta lacrada a Juanka Nabrava, cujo navio está ao largo da costa de Arathi. A frota de Seahorn aguarda suprimentos na baía, enquanto assuntos preocupantes surgem por perto e em terras distantes. Ele pede discrição e uma viagem segura. Os Blackwater Raiders aguardam notícias de que a mensagem chegou ao destino."}},faq={{q="Quem enviou a carta lacrada?",a="Seahorn enviou a carta lacrada de Angra do Butim. Ele pede que ela chegue a Juanka Nabrava em segurança e em sigilo.",al={"quem escreveu","carta de seahorn"}},{q="Quem deve recebê-la?",a="Juanka Nabrava, que está ancorado ao largo da costa de Arathi, é o destinatário da carta.",al={"quem recebe a carta","entregar para quem","carta para shakes"}},{q="Por que Seahorn precisa de um mensageiro?",a="Seahorn precisa que a correspondência lacrada seja levada a Juanka Nabrava enquanto sua frota está retida em Angra do Butim, à espera de suprimentos.",al={"por que entregar","o que há na carta","mensagem secreta"}},{q="O que acontece se eu entregá-la em segurança?",a="Os Blackwater Raiders agradecem pela longa e perigosa viagem, e Seahorn fica satisfeito quando a mensagem chega ao destinatário.",al={"o que acontece ao entregar","blackwater raiders","seahorn satisfeito"}}},fp="23,166,16.341.0,27.109.0,30.88.0,32.122.0,36.133.1"}
P.entries["item:sealed-description-of-thredd-s-visitor"] = {n="Descrição do Visitante de Thredd Lacrada",s="A Descrição do Visitante de Thredd Lacrada é um relatório confidencial escrito pelo Carcereiro-chefe Thelágua sobre um homem enigmático que visitou o líder Defias aprisionado, Basílio Taborda, dentro do Cárcere de Ventobravo. Seu conteúdo ajuda a localizar um operativo secreto que se move sem ser visto pelas esferas políticas e criminosas de Ventobravo.",h="A Descrição do Visitante de Thredd Lacrada é um relatório confidencial escrito pelo Carcereiro-chefe Thelágua...",kw={"baros aleixo","basílio taborda","maelik","mathias shaw","descrição lacrada","cárcere","carcereiro-chefe thelágua"},ang={["class:Rogue"]="Carregar este dossiê é uma lição direta em espionagem: nomes falsos, documentação forjada e visitas a celas são todos descobertos quando Mathias Shaw cruza as descrições físicas com a inteligência do AVIN.",["faction:Alliance"]="O documento expõe rachaduras preocupantes na segurança interna de Ventobravo, provando que conspiradores podem caminhar diretamente pelos portões do Cárcere usando credenciais falsificadas."},sec={{t="Um Patrono Misterioso",b="Durante anos dentro do Cárcere, o prisioneiro Basílio Taborda ficou em sua cela sem visitas. Essa rotina mudou quando um homem pouco comunicativo começou a aparecer uma ou duas vezes por semana com documentos de identificação completamente válidos. Observando essas chegadas incomuns, o Carcereiro-chefe Thelágua compôs um relato físico do homem, que portava uma identificação marcando-o como 'Maelik'. O carcereiro lacrou o perfil para evitar que olhos intrometidos o lessem antes que os investigadores apropriados pudessem agir."},{t="De Pedreiros a Espiões",b="Quando levada ao arquiteto da cidade, Baros Aleixo, a descrição não causou reconhecimento imediato além de uma leve suspeita de que o visitante pudesse ser um operativo ligado à rebelião Defias. Aleixo rapidamente redirecionou o Envelope Selado para o Mestre Mathias Shaw, líder do serviço de inteligência de Ventobravo, o AVIN. Shaw imediatamente desvendou o engano: a descrição correspondia a um mercenário letal que opera sob pseudônimos incluindo Marzon, atualmente fazendo o trabalho sujo para Lorde Gregor Lescovar."}},faq={{q="Quem escreveu esta descrição?",a="O Carcereiro-chefe Thelágua, o carcereiro-chefe do Cárcere de Ventobravo, escreveu e lacrou o documento. Ele ficou desconfiado quando uma figura desconhecida começou a fazer visitas regulares ao líder Defias aprisionado, Basílio Taborda.",al={"quem escreveu","autor da descrição","quem redigiu a nota"}},{q="Quem é o visitante descrito no papel?",a="Ele apresentou documentos sob o nome Maelik. O Carcereiro-chefe Thelágua registrou sua aparência para que os investigadores pudessem estabelecer sua identidade.",al={"quem estava visitando taborda","quem é maelik","identidade do visitante"}},{q="Por que o visitante estava se encontrando com Basílio Taborda?",a="Thelágua ficou desconfiado quando Taborda começou a receber visitas regulares após anos sem nenhuma. O objetivo do visitante é investigado através da Descrição do Visitante de Thredd Lacrada.",al={"por que visitar taborda","propósito do visitante de taborda"}},{q="Para onde este documento lacrado precisa ser levado?",a="O documento é primeiro levado ao arquiteto da cidade, Baros Aleixo, em Ventobravo. Após Aleixo examiná-lo e achar a descrição desconhecida, ele instrui você a entregá-lo diretamente ao Mestre Mathias Shaw na sede do AVIN em Cidade Velha.",al={"onde devo entregar","quem quer a descrição"}}},fx={["7193ccc9"]={q="Por que a descrição do visitante de Basílio Taborda é tão importante?",a="Por anos, Basílio Taborda permaneceu abandonado no Cárcere sem um único visitante. Quando uma figura misteriosa carregando papéis sob o nome 'Maelik' começou subitamente a visitá-lo semanalmente, o Carcereiro-chefe Thelágua ficou desconfiado de uma conspiração mais profunda. Desmascarar este visitante é vital para descobrir quem em Ventobravo está ativamente coordenando com a liderança encarcerada da The Defias Brotherhood, levando os investigadores a procurar a rede de inteligência de Mathias Shaw para identificar o contato sombrio.",al={"por que eles querem a descrição","por que a descrição selada de taborda é procurada","por que a descrição do visitante é importante"}}},fp="38,215,19.325.0,25.380.1,27.196.0,42.127.2,46.153.2,49.206.1"}
P.entries["item:sealed-envelope"] = {n="Envelope Selado",s="Este pacote firmemente selado contém documentos técnicos confidenciais e esquemas roubados dos Empreendimentos S.A. Reunido pelo engenheiro gnomo exilado Fizziks, ele contém projetos proprietários destinados à entrega para Cobogó na Vila Catraca.",h="Este pacote firmemente selado contém documentos técnicos confidenciais e esquemas roubados dos...",kw={"projetos","fizziks","vila catraca","envelope selado","cobogó","cordilheira das torres de pedra","super reaper 6000","empreendimentos s.a."},ang={["faction:Horde"]="Levar esses papéis para o sul a partir da Cordilheira das Torres de Pedra ajuda os goblins neutros da Vila Catraca a minar as operações de extração de madeira agressivas e exploratórias dos Empreendimentos S.A.",["profession:Engineering"]="O envelope guarda desenhos técnicos para o Super Reaper 6000, representando algumas das automações mecânicas mais destrutivas e lucrativas concebidas por mãos goblins."},sec={{t="Espionagem Corporativa",b="Quando o engenheiro goblin Fizziks foi abruptamente expulso das operações de extração de madeira dos Empreendimentos S.A. na Cordilheira das Torres de Pedra, ele não saiu de mãos vazias. Colocando manuais internos, procedimentos operacionais e especificações técnicas dentro deste envelope, ele conseguiu contrabandear segredos da empresa bem debaixo do nariz de seus antigos feitores. Os mais valiosos entre esses registros roubados são os esquemas técnicos para o Super Reaper 6000, uma peça devastadora de maquinário industrial de corte raso de madeira."},{t="Entrega na Vila Catraca",b="Em vez de manter os perigosos segredos comerciais enterrados, Fizziks envia o pacote para o sul para Cobogó, um engenheiro residente no porto goblin neutro da Vila Catraca. Embora os rivais comerciais do Cartel Bondebico tenham pouco amor ou confiança pessoal por Fizziks, o valor de engenharia dos projetos dentro do envelope é inegável. Os documentos oferecem uma visão clara da engenhosidade mecânica dos Empreendimentos S.A. e dão aos engenheiros independentes uma chance de explorar as avançadas tecnologias de extração de madeira dos Empreendimentos S.A."}},faq={{q="O que há dentro do Envelope Selado?",a="O envelope contém documentos internos dos Empreendimentos S.A., manuais técnicos de operação e os projetos da máquina de desmatamento Super Reaper 6000, todos surrupiados por Fizziks durante sua partida precipitada.",al={"conteúdo do envelope","o que está no envelope selado","itens do envelope selado"}},{q="Quem preparou este pacote?",a="O envelope foi preparado por Fizziks, um engenheiro goblin descontente que foi expulso pelos Empreendimentos S.A. de sua operação de extração de madeira na Cordilheira das Torres de Pedra.",al={"quem fez o envelope","quem deu o envelope selado","envelope de fizziks"}},{q="Quem deve recebê-lo?",a="Ele é endereçado a Cobogó, um engenhoqueiro goblin residente na cidade portuária da Vila Catraca, nos Sertões.",al={"quem recebe o envelope","para onde vai o envelope","entrega para cobogó"}},{q="Por que Cobogó quer esses documentos?",a="Embora Cobogó não goste dos Empreendimentos S.A. e desconfie de Fizziks, os documentos contêm aprimoramentos e esquemas valiosos que permitem que engenhoqueiros de fora compreendam e adotem os poderosos projetos mecânicos da empresa.",al={"por que cobogó quer","tecnologia dos empreendimentos s.a. vila catraca"}}},fp="15,109,19.315.0,19.342.0,35.192.0,25.138.0,30.99.0,43.185.0"}
P.entries["item:sealed-note-to-advisor-belgrum"] = {n="Sealed Note to Advisor Belgrum",s="A nota lacrada do Historiador Karnik leva um aviso dos Ermos ao Conselheiro Belgrum. Seu conteúdo orienta o próximo passo contra os anões Shadowforge.",h="A nota lacrada do Historiador Karnik leva um aviso dos Ermos ao Conselheiro Belgrum.",kw={"conselheiro belgrum","ermos","hammertoe","historiador karnik","passing word of a threat","nota lacrada","shadowforge"},sec={{t="Um Aviso a Caminho",b="Nos Ermos, você leva a nota do Historiador Karnik ao Conselheiro Belgrum. Karnik pede que você conte a Belgrum o que testemunhou e busque seu conselho. Enquanto isso, Karnik procura o espírito de Hammertoe, na esperança de que ele ajude a deter as atividades dos anões Shadowforge."}},faq={{q="Quem escreveu a nota lacrada?",a="O Historiador Karnik enviou a nota ao Conselheiro Belgrum.",al={"autor da nota","quem enviou a nota"}},{q="Para quem é a nota?",a="A nota é endereçada ao Conselheiro Belgrum.",al={"quem recebe a nota","nota para belgrum"}},{q="Sobre o que é a nota?",a="Karnik diz que a nota explicará o que você testemunhou e pede orientação a Belgrum sobre como proceder.",al={"o que diz a nota","conteúdo da nota"}},{q="Por que Karnik está enviando a nota?",a="Karnik quer que Belgrum saiba o que você testemunhou e decida como devem proceder.",al={"por que levar a nota","mensagem de karnik"}},{q="O que Karnik está fazendo enquanto você a leva?",a="Karnik planeja falar com o espírito de Hammertoe, na esperança de que ele ajude a deter as atividades dos anões Shadowforge nos Ermos.",al={"o que karnik está fazendo","espírito de hammertoe"}}},fp="30,152,17.256.0,26.50.0,20.41.0,23.101.0,31.83.0,40.123.0"}
P.entries["item:sealed-note-to-elling"] = {n="Bilhete Lacrado para Eling",s="O Bilhete Lacrado para Eling é um despacho confidencial escrito pelo pescador de Ventobravo, Jorge. Destinado a Elling Trias, proprietário da Trias' Cheese, ele serve como um elo inicial na discreta investigação sobre um diplomata desaparecido.",h="O Bilhete Lacrado para Eling é um despacho confidencial escrito pelo pescador de Ventobravo, Jorge.",kw={"elling trias","jorge","bilhete lacrado para eling","ventobravo","the missing diplomat","distrito comercial","queijo de trias"},ang={["class:Rogue"]="Ladinos familiarizados com as redes sombrias de Ventobravo reconhecem Elling Trias como muito mais do que um comerciante de queijo cheddar, tornando essa correspondência discreta uma manobra de espionagem nada surpreendente.",["faction:Alliance"]="Levar a mensagem de Jorge é um serviço direto à Coroa, avançando em uma investigação crítica para a estabilidade política de Ventobravo."},sec={{t="Uma Entrega Discreta",b="Carregar um bilhete lacrado pelas movimentadas avenidas de Ventobravo pode parecer trivial, mas as instruções rígidas de Jorge deixam o perigo claro: entregue o pergaminho nas mãos de Elling Trias e fique em silêncio. Embora Trias se apresente publicamente como um pacato comerciante de queijos no Distrito Comercial, essa mensagem clandestina direciona a investigação do diplomata desaparecido direto para o seu balcão, sugerindo redes muito mais profundas do que o comércio de laticínios."}},faq={{q="O que está escrito dentro do bilhete lacrado?",a="O bilhete permanece lacrado até ser entregue a Elling Trias. Ele contém o relatório de Jorge e uma apresentação que direciona o mensageiro a Trias para investigações mais aprofundadas sobre o desaparecimento do diplomata.",al={"conteúdo do bilhete","o que diz o bilhete","texto da carta"}},{q="Por que um vendedor de queijo recebe informações secretas?",a="Elling Trias mantém uma despretensiosa loja de queijos no Distrito Comercial como fachada pública. Por baixo do avental, Trias possui uma vasta rede clandestina de olhos e ouvidos por toda a cidade, tornando-se um trunfo inestimável para investigações delicadas.",al={"por que elling trias","por que loja de queijo","trias é um espião"}},{q="Quem é Jorge?",a="Jorge é um pescador encontrado perto da água no Vale dos Heróis, em Ventobravo. Ele tem algum tipo de história com Elling Trias e o Bispo DeLavey, e o bispo recorre a ele para assuntos discretos, longe de olhares curiosos.",al={"quem escreveu o bilhete","história de jorge","vigilante jorge"}},{q="Sobre o que é o caso do diplomata desaparecido?",a="Um diplomata de Ventobravo enviado a Theramore para se encontrar com Jaina Proudmore nunca chegou, e as autoridades reais estão investigando discretamente todas as pistas suspeitas sem causar pânico nas ruas.",al={"história do diplomata desaparecido","quem é o diplomata","por que diplomata desaparecido"}}},fx={["2cd529f3"]={q="De onde vem o Bilhete Lacrado para Eling?",a="O bilhete foi escrito e lacrado por Jorge. Após questionar e avaliar a pista sobre o diplomata desaparecido do reino, Jorge redige este despacho discreto e o coloca diretamente em suas mãos para levar a Elling Trias.",al={"quem escreveu o bilhete lacrado para eling","de onde veio o bilhete lacrado","quem deu o bilhete lacrado para eling"}},["92e95eae"]={q="Por que o Bilhete Lacrado para Eling é necessário?",a="O desaparecimento do diplomata é uma questão da maior delicadeza e segurança do estado. Jorge não pode falar abertamente nas ruas, então o bilhete serve como uma introdução silenciosa e uma entrega de informações para Elling Trias, trazendo Trias para a investigação sem alertar olhares curiosos.",al={"por que entregar o bilhete lacrado","por que ellings trias precisa do bilhete","por que o bilhete de jorgen é importante"}},["76232759"]={q="O que é o Bilhete Lacrado para Eling?",a="É uma mensagem confidencial dada a você por Jorge, destinada especificamente aos ouvidos — e olhos — de Elling Trias. Lacrada com cera para garantir o sigilo, ela carrega informações urgentes sobre a investigação sobre o diplomata desaparecido, confiada a você para entrega segura em mãos por Ventobravo.",al={"o que é o bilhete lacrado para eling","item bilhete lacrado para eling","o que é o bilhete de jorge"}}},fp="21,176,16.297.0,39.169.0,53.235.0,14.197.0,40.177.0"}
P.entries["item:sealed-note-to-watcher-backus"] = {n="Bilhete Lacrado para o Vigia Backor",s="O Bilhete Lacrado para o Vigia Backor é uma mensagem confidencial escrita pelo mestre queijeiro e informante Elling Trias. Endereçado a um membro da The Night Watch que patrulha a estrada nos arredores de Vila Sombria, ele cobra um favor pessoal para reunir informações sobre as atividades dos Défias na Floresta do Crepúsculo.",h="O Bilhete Lacrado para o Vigia Backor é uma mensagem confidencial escrita pelo mestre queijeiro e informante...",kw={"vila sombria","floresta do crepúsculo","elling trias","the night watch","bilhete lacrado","the missing diplomat","vigia backor"},ang={["class:Rogue"]="O uso de um guarda comum como informante local por parte de Trias é uma demonstração exemplar da coleta discreta de informações muito além das muralhas da cidade.",["faction:Alliance"]="A missiva ilustra como a espionagem informal e as conexões pessoais mantêm unidos os territórios fragilizados da Aliança quando os canais oficiais falham."},sec={{t="Uma Palavra para a Guarda",b="Quando o bilhete lacrado de Jorge o arrasta para a busca pelo diplomata desaparecido em The Missing Diplomat, o vendedor de queijos Elling Trias concorda relutantemente em acionar seus próprios contatos. Ele escreve esta missiva selada com cera para o Vigia Backor, um guarda da The Night Watch destacado na Floresta do Crepúsculo. Trias envia um aventureiro para o sul através da floresta sombria para entregá-la em mãos, valendo-se de sua longa relação com Backor para obter quaisquer relatos sobre a presença de Défias vagando perto de Vila Sombria."},{t="Os Olhos de Longo Alcance de Trias",b="Embora ostensivamente seja apenas um comerciante que vende queijos finos no Distrito Comercial, a correspondência de Trias com um guarda municipal na Floresta do Crepúsculo revela a imensa amplitude de sua rede de inteligência. A The Night Watch de Vila Sombria é notoriamente fechada e desconfiada de forasteiros, sobrevivendo sob a constante ameaça de mortos-vivos e feras selvagens. Ainda assim, a calorosa recepção de Backor ao bilhete de Trias prova que o lojista aparentemente humilde desfruta de genuína lealdade e respeito muito além das muralhas de Ventobravo."}},faq={{q="Quem escreveu este bilhete?",a="O bilhete foi escrito por Elling Trias, proprietário da Trias' Cheese no Distrito Comercial de Ventobravo, que opera secretamente como um espião habilidoso e informante.",al={"quem escreveu bilhete lacrado para o vigia backor","autor do bilhete","quem entrega o bilhete"}},{q="Por que ele está sendo enviado ao Vigia Backor?",a="O Vigia Backor é um membro da The Night Watch de Vila Sombria e um contato de confiança de Elling Trias. Trias precisa que ele compartilhe quaisquer avistamentos ou boatos locais a respeito das atividades da Irmandade Défias pelos arredores da Floresta do Crepúsculo.",al={"quem e vigia backor","por que enviar para backor","qual e a funcao de backor"}},{q="Onde o Vigia Backor pode ser encontrado?",a="O Vigia Backor patrulha a estrada que segue para o norte, logo nos arredores de Vila Sombria, na Floresta do Crepúsculo, vigiando os acessos florestais que levam à cidade.",al={"onde esta backor","localizacao do vigia backor","encontrar vigia backor"}},{q="O que acontece depois que o bilhete é entregue?",a="Ao reconhecer o nome e a confiança de Trias, Backor deixa de lado sua cautela habitual em relação a aventureiros errantes e concorda em ajudar na investigação sobre atividades suspeitas nos bosques circundantes.",al={"o que backor diz","apos entregar o bilhete"}}},fx={["8647b8fc"]={q="O que é o Bilhete Lacrado para o Vigia Backor?",a="É uma mensagem confidencial escrita por Elling Trias, o mestre mercador de queijos de Ventobravo, destinada ao Vigia Backor na Floresta do Crepúsculo. Trias a envia com você para solicitar a ajuda de Backor na coleta de informações sobre a atividade local da Irmandade Défias como parte da investigação em curso sobre o diplomata desaparecido.",al={"o que é o bilhete lacrado para o vigia backor","propósito do bilhete lacrado para o vigia backor","bilhete de trias para backor"}}},fp="29,149,20.285.0,25.309.1,20.137.0,39.189.0,34.110.0,41.163.0"}
P.entries["item:sealed-venom-container"] = {n="Sealed Venom Container",s="O Sealed Venom Container contém veneno coletado de criaturas venenosas em Silithus. Em Geringontzan, um engenheiro precisa dele para trabalhar em um dispositivo que pode falar com os mortos.",h="O Sealed Venom Container contém veneno coletado de criaturas venenosas em Silithus.",kw={"comunicar-se com os mortos","geringontzan","mux zoamana","sealed venom container","silithus","dispositivo sobrenatural","veneno"},sec={{t="Veneno para Geringontzan",b="O veneno de Silithus é transportado no Sealed Venom Container. A amostra é destinada a um engenheiro em Geringontzan que estuda o sobrenatural. Ele está construindo um dispositivo para se comunicar com os mortos, e o veneno é o pagamento pelo trabalho dele."}},faq={{q="O que há no Sealed Venom Container?",a="O Sealed Venom Container contém veneno coletado de criaturas venenosas em Silithus.",al={"o que há no recipiente de veneno","conteúdo do recipiente de veneno"}},{q="Para onde o recipiente deve ir?",a="O recipiente é destinado a um engenheiro em Geringontzan que está trabalhando em um dispositivo para falar com os mortos.",al={"onde levar o veneno","destino do recipiente de veneno"}},{q="Quem quer o veneno?",a="Mux Zoamana, um engenheiro em Geringontzan interessado no sobrenatural, quer o veneno.",al={"quem precisa do recipiente","veneno de mux"}},{q="Por que o engenheiro precisa do veneno?",a="O veneno é o pagamento pelo trabalho de Mux Zoamana em um dispositivo que pode se comunicar com os mortos.",al={"para que serve o veneno","por que dar veneno a mux"}}},fp="22,171,19.233.0,38.86.0,28.102.0,20.98.0,33.97.0"}
P.entries["item:searing-collar"] = {n="Colar Calcinante",s="Colares Calcinantes são torques rituais usados por membros do culto da Lâmina Ardente escondidos na Rocha da Caveira, em Durotar. Aquecidos para queimar a carne do usuário, eles são usados pelos cultistas para se sintonizarem com poderes demoníacos.",h="Colares Calcinantes são torques rituais usados por membros do culto da Lâmina Ardente escondidos na Rocha da...",kw={"lâmina ardente","demônio","durotar","vil","margoz","colar calcinante","rocha da caveira"},ang={["class:Warlock"]="Bruxos reconhecem os Colares Calcinantes como condutores rudes, mas eficazes, para canalizar a corrupção vil diretamente na carne mortal.",["race:Orc"]="Para os orcs que lutam para libertar seu povo do legado da servidão demoníaca, encontrar cultistas usando esses colares às portas de Durotar é um lembrete sombrio de que a sombra ainda persiste."},sec={{t="Instrumentos de corrupção",b="Dentro da caverna sombria da Rocha da Caveira, logo a leste de Orgrimmar, a Lâmina Ardente se reúne para realizar rituais sombrios. Cultistas, neófitos e bandidos do culto colocam Colares Calcinantes em seus pescoços, sujeitando-se voluntariamente a um calor abrasador que marca e queima sua pele. O eremita Margoz estuda esses artefatos cruéis, teorizando que a sensação ardente e os encantamentos sombrios ligados ao metal servem para sintonizar os usuários diretamente com energias demoníacas. Investigar os colares revela que eles são um canal significativo de corrupção demoníaca se infiltrando na sociedade órquica bem debaixo do nariz da Horda."}},faq={{q="O que é um Colar Calcinante?",a="Um Colar Calcinante é uma faixa ritual usada em volta do pescoço por cultistas da Lâmina Ardente. Ele queima a carne de quem o usa e canaliza energia demoníaca para sintonizar o cultista com a magia sombria.",al={"o que são colares calcinantes","história do colar calcinante","o que o colar faz"}},{q="Quem usa esses colares?",a="Eles são usados por membros do culto da Lâmina Ardente escondidos dentro da Rocha da Caveira, incluindo cultistas, fanáticos, bandidos, aprendizes e neófitos.",al={"quem usa eles","quem saqueia colares calcinantes","colares da lâmina ardente"}},{q="Por que os cultistas queimam a própria carne?",a="A Lâmina Ardente usa o metal ardente como um meio ritualístico. Ao suportar as queimaduras e o encantamento demoníaco, os cultistas sintonizam seus corpos físicos e espíritos com o poder demoníaco.",al={"por que queimar a própria carne","por que usar colar calcinante","propósito do colar"}},{q="Quem quer inspecionar os Colares Calcinantes?",a="Margoz, um investigador acampado em Durotar, recolhe os colares para estudar seus encantamentos e descobrir os segredos por trás da influência sombria da Lâmina Ardente.",al={"quem precisa de colares calcinantes","quem está estudando os colares","colares do margoz"}}},fp="14,140,25.448.0,25.149.0,24.139.0,41.162.0,41.141.0"}
P.entries["item:searing-coral"] = {n="Coral Causticante",s="O Coral Causticante é uma substância mineral rara e resistente colhida de corais de ferro vivos na costa dos Pantanais. Valorizado por engenhocas e ferreiros, ele possui propriedades térmicas notáveis que permitem que seja fundido e forjado em armaduras de proteção.",h="O Coral Causticante é uma substância mineral rara e resistente colhida de corais de ferro vivos na costa dos...",kw={"furen barbalonga","coral de ferro","altaforja","cronomorfus espanafuso","porto de menethil","coral causticante","armadura de guerreiro","pantanal"},ang={["class:Warrior"]="Juntar Coral Causticante é um passo crucial para provar sua dedicação aos mestres armeiros de Altaforja, garantindo a você um peitoral forjado sob medida, projetado para suportar o combate pesado na linha de frente.",["profession:Blacksmithing"]="A integração do Coral Causticante demonstra a fusão inventiva da engenhosidade gnômica com a clássica metalurgia anã, transformando minerais oceânicos em placas temperadas."},sec={{t="Um recurso costeiro raro",b="O Coral Causticante cresce exclusivamente nas águas oceânicas geladas ao longo da costa ao sul do Porto de Menethil, nos Pantanais. Apesar de prosperar em água salgada e fria, esse organismo marinho único rende um material rico em minerais capaz de suportar calor extremo. Os coletores enfrentam a arrebentação traiçoeira e os predadores costeiros dos Pantanais para soltar as formações endurecidas."},{t="Aplicação na ferraria",b="Embora tradicionalmente fora da metalurgia anã padrão, o Coral Causticante chamou a atenção de mentes curiosas em Altaforja. Artesãos gnomos como Cronomorfus Espanafuso adaptam as técnicas do veterano armeiro Furen Barbalonga, fundindo e martelando o coral diretamente em ligas metálicas para produzir armaduras leves e excepcionalmente duráveis para aspirantes a guerreiros."}},faq={{q="Onde o Coral Causticante cresce?",a="O Coral Causticante é colhido no leito marinho ao longo da costa ao sul do Porto de Menethil, nos Pantanais. Ele cresce dentro de bancos naturais de Coral de Ferro submersos sob as águas costeiras rasas.",al={"localização do coral causticante","onde encontrar coral causticante","localização do coral de ferro"}},{q="Quem procura Coral Causticante em Altaforja?",a="Cronomorfus Espanafuso, um artífice gnômico que reside no Distrito dos Gnomos de Altaforja, busca Coral Causticante. Ele o utiliza para fazer experimentos com métodos de forja aprendidos com o lendário armeiro anão Furen Barbalonga.",al={"quem usa coral causticante","cronomorfus espanafuso coral","furen barbalonga coral"}},{q="Como o coral pode ser forjado em armadura?",a="O Coral Causticante possui uma estrutura incomumente densa e resistente ao calor. Quando fundido em uma forja e martelado em ligas metálicas, ele fortalece o chapeamento composto, resultando em equipamentos de proteção excepcionalmente resistentes.",al={"forja de coral","é possível fundir coral","metalurgia do coral causticante"}},{q="É perigoso colher Coral Causticante?",a="O coral em si é seguro de colher depois de localizado, mas coletá-lo exige nadar pelas águas abertas da costa dos Pantanais, onde murlocs selvagens e feras aquáticas agressivas rondam.",al={"o coral causticante é quente","colhendo coral de ferro"}}},fx={["3e3d13aa"]={q="O que é o Coral Causticante?",a="O Coral Causticante é um crescimento marinho raro e rico em minerais, colhido de formações de Iron Coral sob as ondas ao longo da costa do Pantanal, ao sul do Porto de Menethil. Apesar de ser um espécime oceânico, suas propriedades densas e peculiares permitem que ele seja fundido, martelado e trabalhado como metal por ferreiros habilidosos.",al={"o que é o coral causticante","informações sobre coral causticante","história do coral causticante"}},["1c0d8f00"]={q="De onde vem o Coral Causticante?",a="O Coral Causticante é um crescimento aquático natural, e não um artefato manufaturado. Ele cresce exclusivamente em um lugar conhecido no mundo: entre os leitos de coral de ferro submersos ao longo das águas costeiras ao sul do Porto de Menethil, no Pantanal.",al={"origem do coral causticante","de onde vem o coral causticante","quem fez o coral causticante"}}},fp="13,170,23.267.0,23.290.0,30.115.0,37.187.0,35.198.0,38.167.0"}
P.entries["item:secure-crate"] = {n="Caixote Fechado",s="O Caixote Fechado é um pacote firmemente embalado e repleto de poções, reagentes alquímicos e outras mercadorias diversas destinadas aos Reinos do Leste. Confiado a viajantes nos Sertões, ele deve ser levado até o agitado porto de Vila Catraca para pegar a maré de partida.",h="O Caixote Fechado é um pacote firmemente embalado e repleto de poções, reagentes alquímicos e outras...",kw={"sertões","angra aguanegra","poções","vila catraca","reagentes","caixote fechado","remessa","mestre portuário caruncho"},ang={["faction:Horde"]="Lidar com o transporte marítimo através de Vila Catraca lembra aos viajantes da Horda sobre os elos comerciais neutros e vitais que os portos goblins fornecem entre Kalimdor e os Reinos do Leste.",["profession:Herbalism"]="O empacotamento seguro dos reagentes destaca o quanto os alquimistas e herboristas de além-mar dependem das rotas comerciais de fronteira para trocar matérias-primas."},sec={{t="A Carga de um Mensageiro",b="As rotas comerciais entre Kalimdor e os Reinos do Leste dependem de uma cadeia frágil de mensageiros, caravanas do deserto e embarcações mercantes de gnomos e goblins. Quando as caravanas terrestres pelos Sertões perdem suas partidas programadas, remessas frágeis como este Caixote Fechado precisam ser transportadas por viajantes independentes até a costa. Em seu interior há itens alquímicos, poções e diversos reagentes destinados a associados do outro lado do Grande Oceano. Dada a natureza delicada e valiosa do conteúdo, o caixote está firmemente lacrado para garantir que resista tanto às trilhas áridas dos Sertões quanto à maresia do trânsito oceânico."},{t="Pelo Porto de Vila Catraca",b="O destino do trecho terrestre do caixote são as docas de Vila Catraca, supervisionadas pelo Mestre Portuário Caruncho. O porto de Vila Catraca atua como o principal canal neutro por onde suprimentos atravessam o mar rumo a destinos como a Angra Aguanegra. Operando sob os registros do Cartel Bondebico, Caruncho garante que tanto encomendas pequenas quanto fretes pesados sejam devidamente registrados e carregados no próximo navio a partir, proporcionando uma ligação comercial vital entre o Velho Mundo e a fronteira."}},faq={{q="O que há dentro do Caixote Fechado?",a="O caixote contém uma seleção delicada de poções, reagentes alquímicos e outros suprimentos destinados a associados nos Reinos do Leste.",al={"conteúdo do caixote","o que há dentro do caixote","itens do caixote fechado"}},{q="Para onde o caixote está sendo enviado?",a="A pé, ele deve ser entregue ao Mestre Portuário Caruncho nas docas de Vila Catraca. De lá, Caruncho o despacha em uma embarcação mercante que navega pelo mar até a Angra Aguanegra, no Velho Mundo.",al={"destino do caixote","para onde vai o caixote fechado"}},{q="Por que o caixote foi entregue a um aventureiro em vez de a uma caravana?",a="O remetente não tinha tempo para fazer a jornada até Vila Catraca pessoalmente, e a caravana comercial programada já havia partido, tornando necessária a contratação de um mensageiro para não perder a maré.",al={"por que estou com o caixote","caravana perdida"}},{q="Quem recebe o caixote em Vila Catraca?",a="O Mestre Portuário Caruncho recebe o caixote nas docas de Vila Catraca, registrando-o em seu livro de remessas antes de acomodá-lo a bordo do próximo navio que partir com a maré.",al={"quem recebe o caixote","caixote do caruncho"}}},fx={e5dd21c1={q="O que é o Caixote Fechado?",a="O Caixote Fechado é uma remessa bem compactada contendo uma variedade de poções, reagentes e outros suprimentos valiosos. Ele é embalado com segurança para que seu conteúdo delicado sobreviva a uma longa jornada de caravana e embarcação através do mar até os Reinos do Leste.",al={"o que é o caixote fechado","história do caixote fechado","sobre o caixote fechado"}},["4df2d75b"]={q="De onde vem o Caixote Fechado e quem o fez?",a="O caixote tem origem nos Sertões, embalado e lacrado por um boticário ou estudioso que precisava exportar seus suprimentos alquímicos com urgência. Sem tempo para viajar até a costa pessoalmente após perder a caravana comercial regular, eles prepararam o caixote para ser levado à mão diretamente ao porto em Vila Catraca.",al={"quem fez o caixote fechado","de onde veio o caixote fechado","origem do caixote fechado"}},b7ad6ca4={q="Por que o Caixote Fechado é procurado?",a="Associados nos Reinos do Leste, do outro lado do mar, estão aguardando esses reagentes e poções essenciais. O Wharfmaster Dizzywig em Vila Catraca precisa que o caixote seja entregue em suas docas para que ele possa registrá-lo em seu livro de registros comerciais e armazená-lo a bordo da próxima embarcação que partirá para Angra Aguanegra.",al={"por que querer o caixote fechado","quem precisa do caixote fechado","por que dizzywig quer o caixote fechado"}}},fp="12,139,17.376.0,27.382.0,32.111.0,30.151.0,62.163.0,31.158.0"}
P.entries["item:senir-s-report"] = {n="Relatório de Senir",s="O Relatório de Senir é um documento enviado e redigido pelo Montanhista Senir Barbabranca detalhando a ameaça dos trolls Juba Fria em Dun Morogh. Ele contém descobertas encomendadas sob diretiva real e é destinado ao Senador Barin Itarrubra em Altaforja.",h="O Relatório de Senir é um documento enviado e redigido pelo Montanhista Senir Barbabranca detalhando a ameaça...",kw={"barin itarrubra","juba fria","altaforja","magni barbabronze","senado","senir barbabranca","relatório de senir","os relatórios"},ang={["faction:Alliance"]="Lidar com o Relatório de Senir ajuda na defesa de Dun Morogh enquanto você navega pela espinhosa política interna da classe governante de Altaforja.",["race:Dwarf"]="Transportar o Relatório de Senir expõe a nítida divisão política entre os decretos reais do Rei Magni Barbabronze e a autoridade tradicional exigida pelo Senado em Altaforja."},sec={{t="Uma Diretiva Real",b="Redigido após missões de reconhecimento contra os trolls Juba Fria alojados nos despenhadeiros de Dun Morogh, este relatório de campo contém observações de montanhista destinadas ao Senado anão. Senir Barbabranca, posicionado nos sopés gelados, redigiu o documento e anexou o relatório de seu irmão Grolin sobre o Vale Cristálgida, o qual afirma que Grolin agiu sob sanção do Rei Magni Barbabronze. Senir encarrega aventureiros de levarem as descobertas diretamente ao Senador Barin Itarrubra na Sala do Trono de Altaforja — aconselhando cautelosamente os mensageiros a omitirem quanta ajuda externa ele precisou para compilá-las."},{t="Atrito na Sala do Trono",b="Ao ser entregue à corte real, o documento causa alvoroço imediato. Ao ler o relato de Barbabranca, o Senador Barin Itarrubra fica indignado não apenas pelo conteúdo da ameaça dos trolls, mas pela autoridade executiva estampada nele. O fato de Magni ignorar a supervisão legislativa e de Barbabranca agir sob ordens reais irrestritas alimenta um ressentimento antigo dentro do Senado anão, ilustrando a tensão política entre o governo decisivo do Rei Magni e os senadores indignados que exigem controle processual."}},faq={{q="O que é o Relatório de Senir?",a="É um comunicado oficial por escrito de autoria do Montanhista Senir Barbabranca resumindo suas investigações sobre os trolls Juba Fria em Dun Morogh, escrito para ser entregue diretamente ao Senado anão em Altaforja.",al={"relatorio de senir","o que e este relatorio","o relatorio"}},{q="Quem deve receber o relatório?",a="O relatório é endereçado ao Senador Barin Itarrubra, um político anão amargurado situado perto do trono do Rei Magni Barbabronze na Sala do Trono de Altaforja.",al={"quem recebe o relatorio","a quem entrego o relatorio","destinatario do relatorio"}},{q="Por que o Senador Itarrubra fica tão irritado ao lê-lo?",a="O Senador Itarrubra fica furioso porque o relatório anexado do irmão de Senir, Grolin Barbabranca, revela que Grolin agiu sob a autoridade do Rei Magni em vez de consultar o Senado anão. Itarrubra se ressente de a coroa tomar medidas unilaterais sobre assuntos de defesa sem a aprovação senatorial.",al={"por que barin esta bravo","por que o senador esta com raiva","reacao de itarrubra"}},{q="Por que Senir pede para você não mencionar que o ajudou?",a="Senir Barbabranca prefere que seus superiores acreditem que ele realizou o arriscado trabalho de reconhecimento nas colinas nevadas inteiramente por conta própria, desejando proteger sua reputação de montanhista diligente e capaz.",al={"por que ficar quieto","segredo de senir","credito de senir"}}},fx={["078e838e"]={q="De onde vem o Relatório de Senir e quem o fez?",a="Senir Barbabranca redigiu este despacho pessoalmente em Dun Morogh após explorar as ameaças locais dos trolls Jubafria e garantir ajuda para lidar com a Fortaleza Jubafria. Junto com suas próprias descobertas, ele anexa o Relatório de Grolin sobre o Vale Cristálgida, que Grolin escreveu sob sanção do Rei Magni Barbabronze, e leva ambos das fronteiras nevadas para os grandes salões da capital.",al={"quem escreveu o relatório de senir","de onde veio o relatório de senir","autor do relatório de senir"}},e0c0da53={q="Por que alguém quer o Relatório de Senir?",a="O Senador Barin Itarrubra e o Senado de Altaforja exigem avaliações de campo oficiais para acompanhar os desenvolvimentos regionais e as ações militares em Dun Morogh. No entanto, como este despacho específico afirma a autoridade unilateral do Rei Magni sobre as manobras locais, ele carrega um peso político acentuado, informando ao Senado sobre ações da coroa que eles sentem que ignoram sua supervisão.",al={"por que entregar o relatório de senir","por que redstone precisa do relatório de senir","propósito do relatório de senir"}}},fp="14,133,17.399.0,25.430.1,23.143.0,38.131.0,56.253.1,50.210.0"}
P.entries["item:serena-s-head"] = {n="Cabeça da Serena",s="A Cabeça da Serena é o troféu macabro tirado da matriarca das harpias dos Montes Áridos no norte dos Sertões. Darsok Punhálacre da Encruzilhada a exigiu como prova de sua morte, com a intenção de exibi-la nas carroças de suprimentos da Horda como um severo aviso contra novos ataques aéreos.",h="A Cabeça da Serena é o troféu macabro tirado da matriarca das harpias dos Montes Áridos no norte dos Sertões.",kw={"encruzilhada","darsok punhálacre","montes áridos","harpia","rexxar","serena bloodfeather","cabeça da serena","witchwing"},ang={["class:Rogue"]="Darsok Punhálacre aprecia um trabalho limpo e implacável, elogiando mercenários capazes de esgueirar-se por trás dos poleiros inimigos e executar um alvo sem pestanejar.",["faction:Horde"]="As caravanas são vitais para conectar Durotar a Mulgore e aos postos avançados distantes; fixar a cabeça da Serena nas carroças de suprimentos envia uma mensagem inequívoca do domínio da Horda sobre os ermos selvagens."},sec={{t="Um Aviso na Estrada",b="As harpias Witchwing dos Montes Áridos há muito assolam o comércio que passa pelo norte dos Sertões, mas sob o comando de Serena Bloodfeather seus ataques se tornaram particularmente cruéis. Suas investidas contra as linhas de suprimentos da Horda eram movidas por vingança pessoal por sua irmã, que caiu perante o mestre das feras Rexxar. Para quebrar permanentemente o moral do bando, o ladino orc Darsok Punhálacre ordenou que Serena fosse caçada. Em vez de deixar sua morte passar despercebida, ele buscou sua cabeça decepada para que pudesse ser montada na próxima caravana de partida — servindo como um aviso sombrio e sangrento para qualquer harpia que estivesse observando dos penhascos acima."}},faq={{q="Por que Darsok Punhálacre quer a cabeça da Serena?",a="Darsok quer uma prova irrefutável de que Serena Bloodfeather está morta, e pretende fixar a cabeça dela no topo de uma caravana de suprimentos da Horda. Ele espera que a exibição dos restos mortais da matriarca aterrorize as harpias Witchwing sobreviventes e as desencoraje de atacar viajantes.",al={"por que pegar a cabeça da serena","darsok cabeça da serena","o que darsok faz com a cabeça"}},{q="Por que Serena Bloodfeather estava atacando as caravanas da Horda?",a="Os ataques de Serena eram movidos por uma vingança contra a Horda. Sua irmã, Bloodfeather, foi morta pelo campeão meio-ogro Rexxar, e Serena buscou vingança atacando as linhas de suprimentos da Horda e viajantes pelos Sertões.",al={"por que serena atacou caravanas","motivo de serena bloodfeather","ataques de harpias sertões"}},{q="De onde vem este troféu?",a="Ele é arrancado de Serena Bloodfeather, a matriarca que se empoleira entre os penhascos dos Montes Áridos no extremo noroeste dos Sertões.",al={"onde encontrar a cabeça da serena","localização de serena bloodfeather","como pegar a cabeça da serena"}}},fx={["29e11954"]={q="O que é a Cabeça da Serena?",a="A Cabeça da Serena é a cabeça decepada de Serena Bloodfeather, a vingativa matriarca do bando de harpias Asa-de-Bruxa nos Sertões do norte. Levá-la marca o fim de seus ataques às rotas de suprimentos da Encruzilhada e serve como prova irrefutável de que a ameaça das harpias foi atingida em seu próprio topo.",al={"o que é a cabeça da serena","cabeça de serena bloodfeather","item cabeça da serena"}}},fp="13,176,21.411.1,47.194.0,53.175.1,33.126.0"}
P.entries["item:serpentbloom"] = {n="Ofídea",s="Ofídeas são uma erva subterrânea rara encontrada apenas nas profundezas escuras da Caverna Ululante. Suas potentes propriedades naturais atraíram o grande interesse da Real Sociedade de Boticários dos Renegados.",h="Ofídeas são uma erva subterrânea rara encontrada apenas nas profundezas escuras da Caverna Ululante.",kw={"boticária zaqueia","sertões","erva","real sociedade de boticários","ofídea","penhasco do trovão","caverna ululante"},ang={["profession:Herbalism"]="Herboristas treinados possuem os olhos atentos necessários para rastrear essas raras flores cavernosas onde outros veem apenas pedra úmida.",["race:Undead"]="Conseguir Ofídeas ajuda diretamente a Boticária Zaqueia e a Real Sociedade de Boticários em sua busca por recursos botânicos em terras estrangeiras para fortalecer os Renegados."},sec={{t="Uma Flora Subterrânea Rara",b="Ofídeas crescem exclusivamente dentro dos túneis úmidos e sombrios da Caverna Ululante, sob os Sertões. Enraizada em um ecossistema deformado pelas energias descontroladas do Sonho Esmeralda, a planta prospera longe da luz do sol e frequentemente abriga serpentes venenosas aninhadas entre seus caules. Como o sistema de cavernas está infestado de feras hostis e druidas corrompidos, poucos dos que se aventuram lá dentro retornam com espécimes viáveis."},{t="Interesse Boticário",b="Operando a partir dos Poços das Visões, sob Penhasco do Trovão, a Boticária Zaqueia coleta Ofídeas em nome da Real Sociedade de Boticários da Cidade Baixa. Os Renegados buscam continuamente vegetações virulentas, estranhas e quimicamente potentes por toda Kalimdor para abastecer suas pesquisas para a Dama Sombria. Zaqueia acredita que colher Ofídeas em quantidades significativas pode render avanços valiosos para a alquimia dos Renegados."}},faq={{q="Onde crescem as Ofídeas?",a="Ofídeas são encontradas apenas nas profundezas da Caverna Ululante, uma rede labiríntica de cavernas localizada a sudoeste da Encruzilhada, nos Sertões. Elas se agarram ao chão nos recessos escuros e úmidos da caverna.",al={"onde encontrar ofídeas","localização das ofídeas","erva caverna ululante"}},{q="Por que a Real Sociedade de Boticários quer Ofídeas?",a="A Boticária Zaqueia, uma agente da Real Sociedade de Boticários posicionada em Penhasco do Trovão, busca a planta para pesquisas. Os Renegados examinam a flora incomum e perigosa de toda Kalimdor para desenvolver novas misturas químicas e apoiar os objetivos mais amplos de Sylvana Correventos.",al={"quem quer ofídeas","erva boticária zaqueia","por que coletar ofídeas"}},{q="Por que colher Ofídeas é perigoso?",a="Além dos perigos gerais da Caverna Ululante — infestada de raptores, crocoliscos e druidas corrompidos —, a própria erva frequentemente abriga cobras venenosas. Perturbar a planta muitas vezes faz com que essas serpentes ocultas ataquem.",al={"perigo das ofídeas","cobra ofídeas"}},{q="Herboristas conseguem encontrar Ofídeas com mais facilidade?",a="Sim. Aqueles treinados em herborismo são naturalmente atentos para avistar o crescimento vegetal e podem rastrear canteiros de Ofídeas em meio aos cantos sombrios do chão da caverna.",al={"encontrar ofídeas herborismo","rastrear ofídeas"}}},fx={bee22cd2={q="O que é a Ofídea?",a="A Ofídea é um espécime de flora extremamente raro, nativo dos recessos mais sombrios da Caverna Ululante nos Sertões. Enraizada nas profundezas úmidas e subterrâneas, esta erva incomum distingue-se por suas qualidades semelhantes às de uma serpente — perturbá-la geralmente atrai cobras agressivas aninhadas ao redor de suas raízes.",al={"o que é a ofídea","erva ofídea","informações sobre a ofídea"}}},fp="12,133,25.327.0,19.368.0,29.186.0,56.295.0,41.163.0,45.131.0"}
P.entries["item:sethir-s-journal"] = {n="Diário de Sethir",s="O Diário de Sethir é um registro pessoal carregado pelo esquivo sátiro Sethir the Ancient em Teldrassil. Recuperado por meio de furtividade, seu conteúdo confirma a alarmante disseminação da corrupção do continente de Kalimdor para a Árvore do Mundo.",h="O Diário de Sethir é um registro pessoal carregado pelo esquivo sátiro Sethir the Ancient em Teldrassil.",kw={"costa negra","o destino chama","clareira do oráculo","satiro","sethir the ancient","diário de sethir","syurna","teldrassil"},ang={["class:Rogue"]="Recuperar o diário prova que a infiltração sutil e o furto de bolsos podem desvendar informações críticas onde guerreiros da linha de frente e diplomatas falharam completamente.",["race:NightElf"]="O diário fornece evidências angustiantes de que Teldrassil não está imune à antiga mácula demoníaca que rasteja pelo continente de Kalimdor."},sec={{t="Uma pista para a mácula",b="Teldrassil foi erguida na esperança de recuperar a imortalidade élfica, mas uma enfermidade invisível tem se enraizado cada vez mais em seus galhos. Syurna, em Darnassus, suspeitava que Sethir the Ancient, um sátiro solitário à espreita em um galho afastado perto da Clareira do Oráculo, tinha respostas. Quando a diplomacia direta e a força aberta resultaram apenas em morte para batedores anteriores, o furto discreto rendeu o Diário de Sethir. Os escritos revelam uma verdade sombria: a misteriosa praga que envenena os bosques e as águas do outro lado do mar, em Costa Negra, atravessou para a própria Teldrassil."}},faq={{q="O que é o Diário de Sethir?",a="É um diário carregado por Sethir the Ancient, um sátiro hostil que vive ao longo dos galhos externos perto da Clareira do Oráculo em Teldrassil. Ele contém anotações que detalham a propagação da corrupção que assola a região.",al={"o que e o diario de sethir","historia diario de sethir","quem tem o diario de sethir"}},{q="Como o diário é obtido?",a="Como as tentativas anteriores de negociar ou lutar contra Sethir resultaram em fracasso e morte, o diário deve ser afanado diretamente de suas bolsas usando furtividade.",al={"como conseguir o diario de sethir","onde pegar diario de sethir","bater carteira sethir"}},{q="O que o diário revela?",a="De acordo com a instrutora de ladinos Syurna, o diário prova que a estranha enfermidade que assola as florestas e águas de Costa Negra conseguiu se infiltrar em Teldrassil.",al={"o que diz o diario de sethir","o que tem no diario de sethir"}},{q="Quem é Sethir the Ancient?",a="Sethir é um sátiro solitário que habita um galho isolado nos arredores da Clareira do Oráculo. Conhecido por lidar com intrusos de forma violenta, ele possui informações vitais sobre a corrupção rastejante da Árvore do Mundo.",al={"quem e sethir","sethir the ancient"}}},fx={["3d18c972"]={q="De onde vem o Diário de Sethir e quem o fez?",a="O diário pertence a Sethir, o Ancião, um sátiro hostil que espreita em um galho alto nas margens da Clareira do Oráculo em Teldrassil. Carregando seus escritos e registros pessoais entre seus pertences, ele manteve o diário até que ladinos em Darnassus tentaram pegá-lo discretamente de sua posse para descobrir qual corrupção está se espalhando pela árvore do mundo.",al={"quem escreveu o diário de sethir","origem do diário de sethir"}}},fp="16,144,19.475.1,25.171.0,28.130.0,29.130.0,26.207.0"}
P.entries["item:sevren-s-orders"] = {n="Ordens de Sevren",s="Ordens de Sevren são despachos escritos redigidos pelo Magistrado Sevren de Montalvo. Eles instruem um agente Renegado comprovado a se apresentar a Boanerges Stalactus, um formidável mago situado no Distrito da Magia da Cidade Baixa.",h="Ordens de Sevren são despachos escritos redigidos pelo Magistrado Sevren de Montalvo.",kw={"boanerges stalactus","montalvo","distrito da magia","magistrado sevren","lich pródigo","ordens de sevren","cidade baixa"},ang={["class:Mage"]="Para praticantes do arcano, entregar essas ordens concede uma audiência com Boanerges Stalactus, um dos conjuradores mais proeminentes do reino dos Renegados.",["race:Undead"]="Portar o selo de Sevren marca a transição de um operativo do serviço local em Tirisfal para o apoio direto à elite arcana da Cidade Baixa."},sec={{t="Convocação para a Capital",b="À medida que os Renegados consolidam seu domínio sobre as ruínas de Lordaeron, agentes habilidosos que provaram seu valor contra o Flagelo nas Clareiras de Tirisfal são convocados ao sul para a capital. Emitidas pelo Magistrado Sevren, essas ordens escritas servem como apresentação oficial e credenciais para Boanerges Stalactus, um dos principais praticantes do arcano da Dama Sombria no Distrito da Magia. Embora Sevren saiba pouco além do fato de que a missão envolve contatar um lich errante, a convocação traz a autoridade absoluta dos altos magos da Cidade Baixa."}},faq={{q="Quem escreveu essas ordens?",a="O Magistrado Sevren, o supervisor Renegado que administra os assuntos na vila de Montalvo, nas Clareiras de Tirisfal, redigiu as ordens.",al={"autor de ordens de sevren","quem é sevren","quem dá ordens de sevren"}},{q="Quem deve receber essas ordens?",a="Elas são endereçadas a Boanerges Stalactus, um mago Renegado de alto escalão localizado no Distrito da Magia da Cidade Baixa.",al={"quem recebe as ordens","onde levar ordens de sevren","quem é boanerges stalactus"}},{q="Qual é a missão mencionada nas ordens?",a="A missão envolve recrutar um lich rebelde para ajudar os Renegados, uma tarefa perigosa que exige um agente que já tenha se mostrado capaz contra o Flagelo.",al={"qual é a missão do lich","o que boanerges quer","missão do lich pródigo"}},{q="Por que fui escolhido para entregá-las?",a="Boanerges solicitou um operativo com capacidade comprovada contra o Flagelo. O Magistrado Sevren considerou seus esforços nas Clareiras de Tirisfal suficientes para lidar com a perigosa tarefa de Boanerges.",al={"por que eu","por que sevren me escolheu"}}},fx={["59d8f724"]={q="O que são as Ordens de Sevren?",a="As Ordens de Sevren são um despacho oficial escrito pelo Magistrado Sevren de Montalvo. Elas funcionam como credenciais formais, identificando você como um agente de valor comprovado que lutou eficazmente contra o Flagelo e está pronto para realizar uma missão delicada.",al={"o que são as ordens de sevren","item ordens de sevren","o que é este documento"}},["680dc8a1"]={q="Por que Boanerges Stalactus quer as Ordens de Sevren?",a="Boanerges Stalactus, um mago proeminente no Distrito da Magia da Cidade Baixa, exigiu que Sevren fornecesse um agente capaz de lidar com uma tarefa perigosa envolvendo um lich renegado. Apresentar essas ordens prova que você é o agente escolhido de Sevren e que sua interrupção do poderoso mago é justificada.",al={"por que entregar as ordens de sevren","por que bethor quer as ordens","quem precisa das ordens de sevren"}}},fp="15,150,22.460.0,23.76.0,40.107.0,44.139.0,33.157.0"}
P.entries["item:shackle-key-stranglethorn-vale"] = {n="Shackle Key",s="A Shackle Key está com King Mukla na Ilha Jaguara. Princesa Manda-chuva precisa dela para escapar do cativeiro.",h="A Shackle Key está com King Mukla na Ilha Jaguara.",kw={"cativeiro","ilha jaguara","rei mukla","princesa manda-chuva","algema","shackle key","selva do espinhaço"},sec={{t="Uma princesa cativa",b="Princesa Manda-chuva está acorrentada na Ilha Jaguara, onde King Mukla a mantém contra a vontade dela. A chave de suas algemas está ligada à liberdade, e ela pede ajuda a quem estiver disposto a enfrentar o grande rei Skymane."}},faq={{q="O que a Shackle Key abre?",a="A Shackle Key abre a algema que mantém Princesa Manda-chuva cativa na Ilha Jaguara.",al={"para que serve a chave","o que a chave abre"}},{q="Quem está com a Shackle Key?",a="King Mukla está com a Shackle Key na Ilha Jaguara.",al={"quem está com a chave","chave de mukla"}},{q="Onde Princesa Manda-chuva está presa?",a="Princesa Manda-chuva está presa na Ilha Jaguara, na Selva do Espinhaço.",al={"onde está manda-chuva","manda-chuva cativa"}},{q="Por que Princesa Manda-chuva precisa da chave?",a="Princesa Manda-chuva precisa da Shackle Key para se libertar da corrente que a mantém cativa.",al={"por que precisa da chave","libertar manda-chuva"}}},fp="11,104,18.208.0,31.82.0,24.47.0,30.62.0,38.89.0"}
P.entries["item:shackle-key-the-hinterlands"] = {n="Shackle Key",s="Shackle Key está com Hitah'ya the Keeper, em uma caverna perto de Jintha'alor. O Ancião Presa-arrancada precisa dela para afrouxar suas amarras e voltar para casa.",h="Shackle Key está com Hitah'ya the Keeper, em uma caverna perto de Jintha'alor.",kw={"amarras","ancião presa-arrancada","terras agrestes","hitah'ya the keeper","jintha'alor","shackle key"},sec={{t="O ancião acorrentado",b="Em Jintha'alor, nas Terras Agrestes, o Ancião Presa-arrancada espera pela chave de suas amarras. Hitah'ya the Keeper a guarda em uma caverna próxima, bem protegida. Leve a chave de volta a Torntusk para que ele possa se libertar e voltar para casa."}},faq={{q="Quem está com Shackle Key?",a="Hitah'ya the Keeper está com Shackle Key em uma caverna perto de Jintha'alor.",al={"quem está com a chave","quem tem a chave","chave de hitah'ya"}},{q="Para que serve Shackle Key?",a="Shackle Key afrouxa as amarras do Ancião Presa-arrancada para que ele possa voltar para casa.",al={"o que a chave faz","para que serve a chave","chave de torntusk"}},{q="Onde está a chave?",a="Hitah'ya the Keeper está com a chave em uma caverna perto de Jintha'alor, nas Terras Agrestes.",al={"localização da chave","onde está a chave","caverna próxima"}},{q="Quem precisa da chave?",a="O Ancião Presa-arrancada, em Jintha'alor, precisa da chave para se libertar das amarras.",al={"quem quer a chave","quem precisa dela","ancião presa-arrancada"}}},fp="11,138,15.218.0,24.69.0,28.72.0,17.80.0,18.78.0"}
P.entries["item:shadow-hunter-knife"] = {n="Shadow Hunter Knife",s="A Shadow Hunter Knife é uma lâmina dos trolls Witherbark, procurada pelo Aprendiz Kraiten na Ponta do Refúgio. Ela está ligada aos ritos dos caçadores das sombras da tribo.",h="A Shadow Hunter Knife é uma lâmina dos trolls Witherbark, procurada pelo Aprendiz Kraiten na Ponta do Refúgio.",kw={"arquimago malin","kraiten","ponta do refúgio","ritos de passagem","shadow hunter knife","troll","witherbark"},ang={["faction:Alliance"]="Como viajante da Aliança, o trabalho de Kraiten na Ponta do Refúgio serve à pesquisa do Arquimago Malin em Arathi."},sec={{t="Lâmina de um Troll",b="O Aprendiz Kraiten procura a Shadow Hunter Knife na Ponta do Refúgio para a pesquisa do Arquimago Malin. Ele diz que os caçadores das sombras Witherbark mais fortes recebem a lâmina especial após concluir seus ritos de passagem. A aldeia deles fica a sudeste de Arathi, e Kraiten não consegue saber qual caçador carrega uma até que a luta termine."}},faq={{q="Quem quer a Shadow Hunter Knife?",a="O Aprendiz Kraiten, na Ponta do Refúgio, procura a Shadow Hunter Knife para a pesquisa do Arquimago Malin.",al={"quem precisa da faca","faca de kraiten","quem quer a faca"}},{q="Quem carrega a Shadow Hunter Knife?",a="Os caçadores das sombras Witherbark mais fortes podem carregar a faca especial recebida após seus ritos de passagem.",al={"quem tem a faca","qual troll tem a faca","lâmina de caçador das sombras"}},{q="Por que a faca é especial?",a="Kraiten diz que os Witherbark dão a faca aos seus caçadores das sombras mais fortes após concluírem seus ritos de passagem.",al={"por que a faca é especial","significado da faca troll","o que ela tem de especial"}},{q="Onde os Witherbark vivem?",a="Os Witherbark vivem a sudeste de Arathi, perto da Aldeia Cascasseca.",al={"onde ficam os witherbark","localização da aldeia troll"}}},fp="19,154,15.328.0,34.97.0,36.103.0,25.119.0,29.65.0"}
P.entries["item:shadowhide-pendant"] = {n="Pingente Umbrapele",s="Pingentes Umbrapele são amuletos ornamentais rudes carregados pelos gnolls Umbrapele que vagam pelas Montanhas Cristarrubra. Coletados como prova legal do cumprimento de recompensas, eles indicam que os defensores locais aplicaram a lei de Vila Plácida contra os gnolls que colaboram com o mago renegado Morganth.",h="Pingentes Umbrapele são amuletos ornamentais rudes carregados pelos gnolls Umbrapele que vagam pelas...",kw={"meirinho conacher","gnoll","vila plácida","tenente fangore","morganth","pingente","montanhas cristarrubra","umbrapele","a lei de salomão"},ang={["class:Warrior"]="Os gnolls Umbrapele são adversários agressivos e fisicamente imponentes, cujas fileiras testam os defensores da linha de frente que protegem as estradas para Vila Plácida.",["faction:Alliance"]="Assentamentos de fronteira como Vila Plácida recebem pouca ajuda da guarnição de Ventobravo, deixando os magistrados locais dependentes de aventureiros leais da Aliança para aplicar a lei do reino."},sec={{t="Símbolos de Desafio",b="Carregados por guerreiros, brutamontes e conjuradores do clã Umbrapele, esses pingentes servem como rudes totens pessoais ou insígnias de patente. Nas profundezas das colinas de Cristarrubra, o clã se reuniu sob o comando do Tenente Fangore e caiu sob a influência de Morganth, um manipulador renegado do Arcano. Para os habitantes de Vila Plácida, esses amuletos não são meras joias primitivas; são marcas de identificação de uma ameaça organizada que atormenta os assentamentos por toda a região em nome de um inimigo da Coroa."},{t="A Justiça de Vila Plácida",b="Sob a autoridade do Magistrado Salomão e as leis de Ventobravo, ajudar ativamente um criminoso conhecido do reino acarreta a pena de morte. Sem reforços reais suficientes, o Meirinho Conacher, na Prefeitura de Vila Plácida, depende de aventureiros independentes para manter a paz. Apresentar dez Pingentes Umbrapele fornece prova tangível de que os gnolls que obedecem às ordens de Morganth enfrentaram a justiça da fronteira."}},faq={{q="O que é um Pingente Umbrapele?",a="É um amuleto usado por membros do clã de gnolls Umbrapele nas Montanhas Cristarrubra. O magistrado local os aceita como evidência de que gnolls invasores foram mortos em defesa do vilarejo.",al={"o que são pingentes umbrapele","história do pingente umbrapele","pingente de cristarrubra"}},{q="Por que o Meirinho Conacher quer esses pingentes?",a="O Meirinho Conacher os coleta como prova do cumprimento de recompensas sob A lei de Salomão. Como o clã Umbrapele está colaborando com o mago renegado Morganth para aterrorizar a população local, a cidade considera cada gnoll afiliado um inimigo sujeito à pena capital.",al={"por que coletar pingentes","recompensa do meirinho conacher","missão de conacher"}},{q="Quem carrega esses pingentes?",a="Eles são carregados por toda a hierarquia do clã Umbrapele, desde salteadores comuns, brutamontes e gnolls raivosos até figuras como Rohh the Silent e o Tenente Fangore nas terras selvagens de Cristarrubra.",al={"quem dropa pingentes","quais gnolls têm pingentes","fonte do pingente umbrapele"}},{q="Qual é a relação entre o clã Umbrapele e Morganth?",a="Morganth, um praticante renegado do Arcano que espreita nas colinas orientais, usou seus poderes sinistros para dobrar os gnolls Umbrapele à sua vontade, utilizando-os como soldados rasos para aterrorizar Vila Plácida e executar seus planos.",al={"gnolls e morganth","por que os gnolls trabalham com morganth","umbrapele morganth"}}},fp="18,127,18.341.0,19.340.0,29.212.0,46.256.0,27.145.0,66.218.0"}
P.entries["item:shadowmaw-claw"] = {n="Shadowmaw Claw"}
P.entries["item:shadowstalker-scalp"] = {n="Shadowstalker Scalp"}
P.entries["item:shadra-s-venom"] = {n="Shadra's Venom",s="O veneno de Shadra é obtido da deusa-aranha nas Terras Agrestes. O Boticário Lindolfo, na Serraria Tarren, precisa dele após a invocação de Shadra.",h="O veneno de Shadra é obtido da deusa-aranha nas Terras Agrestes.",kw={"boticário lindolfo","gadrin's parchment","terras agrestes","shadra","shadra'alor","veneno de shadra","deusa-aranha","serraria tarren"},sec={{t="Veneno para Lindolfo",b="Em Shadra'Alor, nas Terras Agrestes, o pergaminho chama Shadra de seu covil. O veneno dela é levado ao Boticário Lindolfo, na Serraria Tarren, que está à espera."}},faq={{q="O que é o veneno de Shadra?",a="O veneno de Shadra é obtido de Shadra, a deusa-aranha das Terras Agrestes.",al={"veneno de shadra","qual veneno"}},{q="Quem precisa do veneno de Shadra?",a="O Boticário Lindolfo, na Serraria Tarren, pede que você leve o veneno de Shadra até ele.",al={"quem quer o veneno","veneno para lindolfo"}},{q="Onde você consegue o veneno de Shadra?",a="O veneno de Shadra vem de Shadra, no altar de Shadra'Alor, nas Terras Agrestes.",al={"onde fica o veneno","conseguir veneno de shadra"}},{q="Como Shadra é invocada?",a="Leia Gadrin's Parchment no altar de Shadra'Alor, nas profundezas de Witherbark realm, nas Terras Agrestes.",al={"invocar shadra","altar de shadra"}}},fp="14,130,15.151.0,23.71.0,25.72.0,32.80.0,23.105.0"}
P.entries["item:shaman-voodoo-charm"] = {n="Patuá Vodu de Xamã",s="O Patuá Vodu de Xamã é um berloque de ritual sombrio carregado por xamãs nocturpinos nas profundezas da Gruta de Ban'ethil. Emanando uma aura vil, este patuá canaliza uma magia antinatural capaz de separar o espírito de um druida adormecido de sua carne física.",h="O Patuá Vodu de Xamã é um berloque de ritual sombrio carregado por xamãs nocturpinos nas profundezas da Gruta...",kw={"gruta de ban'ethil","sonho esmeralda","furbolg","nocturpino","oben patafúria","patuá vodu de xamã","druida adormecido","teldrassil"},ang={["class:Druid"]="Para um druida, o patuá representa uma terrível perversão do sono sagrado, usando magia sombria para prender o sonhador no Sonho Esmeralda enquanto manipula sua forma física como marionete.",["race:NightElf"]="A descoberta desses patuás dentro da Gruta de Ban'ethil revela o quão profundamente os Nocturpinos profanaram um dos locais de descanso comunitário mais sagrados dos kaldorei."},sec={{t="Uma magia pervertida",b="A tribo dos Nocturpinos de Teldrassil sucumbiu à loucura e à corrupção, mas dentro da Gruta de Ban'ethil seus xamãs empunham poderes que vão muito além da feitiçaria selvagem comum. Usando esses estranhos patuás vodu, os xamãs descobriram uma forma de arrancar a consciência de um druida adormecido do reino mortal e aprisioná-la, indefesa, dentro do Sonho Esmeralda. Ao separar a alma do receptáculo, os furbolgs conseguem animar a forma física vazia, transformando veneráveis protetores elfos noturnos em guardiões irracionais que chacinam qualquer um que se aventure nos túmulos."},{t="Desvendando a maldição",b="Quando o druida Oben Patafúria foi vítima desse ritual, seu espírito viu-se aprisionado no Sonho enquanto seu corpo animado aterrorizava as profundezas dos túmulos. Estendendo seu alcance através do véu, Oben incumbiu aventureiros de abater os xamãs nocturpinos e recuperar um de seus patuás vodu. Ao examinar o encantamento vil imbuído no berloque, Oben esperava decifrar a arte deturpada dos furbolgs e descobrir um meio de quebrar a vinculação sobre sua carne roubada."}},faq={{q="Para que serve o Patuá Vodu de Xamã?",a="Os xamãs nocturpinos usam o patuá para realizar um ritual poderoso que separa o espírito de um druida adormecido do seu corpo físico, aprisionando a mente no Sonho Esmeralda enquanto anima a carne oca para atacar invasores.",al={"objetivo do patuá vodu","o que o patuá faz","uso do patuá de xamã"}},{q="Quem carrega esses patuás?",a="Os patuás são carregados por xamãs nocturpinos que habitam as profundezas sinuosas da Gruta de Ban'ethil em Teldrassil.",al={"quem dropa o patuá","onde encontrar patuá vodu de xamã","patuá de xamã nocturpino"}},{q="Por que Oben Patafúria precisa de um?",a="Oben Patafúria está atualmente preso no Sonho Esmeralda enquanto seu corpo animado age descontroladamente. Ele precisa inspecionar a aura vil e a trama mágica do patuá para descobrir como quebrar o encantamento dos furbolgs.",al={"por que oben quer o patuá","patuá de oben patafúria","item de o druida adormecido"}},{q="Por que os furbolgs possuem magia vodu?",a="Embora os xamãs furbolgs tradicionais reverenciem os espíritos da natureza e os elementos, a corrupção que assola Teldrassil levou os Nocturpinos a praticar magias sombrias e pervertidas. O patuá possui uma aura vil e antinatural, bem diferente da adoração tradicional à natureza.",al={"por que furbolgs usam vodu","história do vodu furbolg"}}},fx={["6bf5e1a6"]={q="O que é o Patuá Vodu de Xamã?",a="É um talismã furbolg encantado empunhado por xamãs Gnarlpine corrompidos dentro da Gruta de Ban'ethil. Emanando uma aura mágica vil, o patuá aproveita rituais sombrios capazes de separar o espírito de um druida elfo noturno adormecido de sua forma física, deixando o espírito indefeso enquanto os furbolgs animam e controlam o corpo em sono profundo.",al={"o que é o patuá vodu de xamã","história do patuá vodu","o que são estes patuás"}}},fp="19,134,17.393.0,20.378.1,41.170.0,25.89.0,32.180.0,34.204.0"}
P.entries["item:shard-of-water"] = {n="Estilhaço de Água",s="O Estilhaço de Água é um resquício elemental obtido durante a comunhão de um xamã com os espíritos da água. Entregue a Islen Vidente da Água ao longo da costa dos Sertões, ele serve como prova tangível de que um iniciado compreendeu a natureza vivificante da água e superou sua corrupção.",h="O Estilhaço de Água é um resquício elemental obtido durante a comunhão de um xamã com os espíritos da água.",kw={"sertões","clamor da água","islen vidente da água","estilhaço de água","floresta de pinhaprata","totem da água"},ang={["class:Shaman"]="Obter este estilhaço marca o passo final na sua sintonização com os espíritos da água, concluindo a longa jornada para obter seu Totem da Água."},sec={{t="Emblema de Pureza Elemental",b="Para xamãs que buscam o domínio sobre os elementos, a comunhão com a água exige uma compreensão profunda de equilíbrio, vida e preservação. Nas provações do Clamor da água, os xamãs são instruídos a enfrentar a corrupção infiltrada em nascentes naturais — viajando até mesmo pelo mar até terras flageladas como a Floresta de Pinhaprata. O Estilhaço de Água é concedido ao purificar essas águas corrompidas. Devolver este emblema de cristal a Islen Vidente da Água nas margens rochosas dos Sertões comprova o valor do iniciado, fornecendo a chave final necessária para forjar seu Totem da Água."}},faq={{q="Para que serve o Estilhaço de Água?",a="Ele serve como prova da sua provação para Islen Vidente da Água ao longo da costa leste dos Sertões. Apresentar o estilhaço a ela completa sua comunhão com a água e concede a você o seu Totem da Água.",al={"propósito do estilhaço de água","o que faz o estilhaço de água","por que tenho estilhaço de água"}},{q="Quem exige este item?",a="Islen Vidente da Água, uma xamã que vive em uma cabana ao sul de Vila Catraca ao longo da Costa dos Mercadores, pede o estilhaço para confirmar que você purificou com sucesso a água corrompida.",al={"quem quer estilhaço de água","onde entregar estilhaço de água","estilhaço de islen vidente da água"}},{q="Por que a provação foi realizada em um lugar tão distante quanto Pinhaprata?",a="A água representa cura e preservação, mas a corrupção interrompe a vida. As águas contaminadas de Pinhaprata representam um teste rigoroso da capacidade de um xamã de restaurar a harmonia elemental em meio a uma profunda decadência.",al={"missão da água pinhaprata","por que floresta de pinhaprata","xamã pinhaprata"}}},fx={aaf07767={q="O que é o Estilhaço de Água?",a="O Estilhaço de Água é um fragmento elemental sagrado concedido aos xamãs que realizam os testes da água. Ele serve como prova tangível de que você realizou o ritual para purificar águas corrompidas e compreendeu a verdadeira natureza da água como doadora e protetora da vida.",al={"o que é o estilhaço de água","item estilhaço de água","o que é este estilhaço"}},["47314211"]={q="De onde vem o Estilhaço de Água e quem o fez?",a="Você recebe o estilhaço ao final de sua jornada espiritual na Floresta de Pinhaprata, concedido ao completar seu ritual para purificar as águas corrompidas da região. Ele incorpora o poder elemental da água pura despertada através desse rito.",al={"onde se consegue o estilhaço de água","quem dá o estilhaço de água","origem do estilhaço de água"}}},fp="14,108,25.403.0,36.165.0,23.141.0,48.163.0"}
P.entries["item:sharpbeak-s-feather"] = {n="Sharpbeak's Feather",s="A pena de Sharpbeak guarda um vestígio do jovem grifo procurado nas Terras Agrestes. Tádius Sombraustera espera que o vínculo com Sharpbeak ajude sua magia de adivinhação a encontrá-lo.",h="A pena de Sharpbeak guarda um vestígio do jovem grifo procurado nas Terras Agrestes.",kw={"ninho da águia","adivinhação","grifo","sharpbeak","pena de sharpbeak","tádius sombraustera","wildhammer"},ang={["race:Dwarf"]="Como anão, a busca por Sharpbeak toca os Wildhammer: Tádius Sombraustera deixou o Ninho da Águia, mas ainda mantém seu coração Wildhammer."},sec={{t="Uma pena de grifo",b="Na Bastilha de Etergarde, Tádius Sombraustera pede uma pena retirada do ninho onde Sharpbeak dorme. O adivinho deixou o Ninho da Águia há muitos anos em busca de conhecimentos sombrios, embora ainda tenha um coração Wildhammer. Ele acredita que a pena pode ajudá-lo a encontrar o jovem grifo."},{t="Um sinal promissor",b="Tádius reconhece que a pena pertence a um grifo magnífico. Ele acredita que Sharpbeak está destinado a grandes feitos, se chegar à idade adulta sem sofrer nenhum dano. Com a pena em mãos, ele pede que você escute com atenção enquanto começa a adivinhar onde o grifo está."}},faq={{q="Para que serve a Pena de Sharpbeak?",a="Tádius Sombraustera usa a Pena de Sharpbeak como vínculo para adivinhar onde o jovem grifo está.",al={"pena de sharpbeak","para que serve a pena","uso da pena"}},{q="De onde veio a pena?",a="A pena foi retirada do ninho onde dorme Sharpbeak, o filhote de grifo.",al={"origem da pena de sharpbeak","de onde veio a pena","pena do ninho de grifo"}},{q="Quem é Tádius Sombraustera?",a="Tádius Sombraustera é um adivinho Wildhammer que deixou o Ninho da Águia há muitos anos em busca de conhecimentos sombrios. Ele pode ser encontrado na torre dos magos da Bastilha de Etergarde, na Barreira do Inferno.",al={"história de tádius","quem é tádius","sombraustera"}},{q="O que Tádius pensa de Sharpbeak?",a="Tádius diz que Sharpbeak é um grifo magnífico, destinado a grandes feitos se chegar à idade adulta sem sofrer danos.",al={"destino de sharpbeak","o que tádius pensa","filhote de grifo"}}},fp="19,167,19.271.0,17.259.0,32.98.0,32.77.0,25.170.0,37.104.0"}
P.entries["item:shaw-s-report"] = {n="Relatório do Shaw",s="O Relatório do Shaw é um despacho confidencial escrito pelo Mestre Mathias Shaw da AVIN para Miguel Mantoforte em Cerro Oeste. Ele resume o conhecimento da agência de inteligência sobre a Guilda dos Pedreiros, seu líder Edwin VanCleef e suas queixas contra a coroa após a reconstrução de Ventobravo.",h="O Relatório do Shaw é um despacho confidencial escrito pelo Mestre Mathias Shaw da AVIN para Miguel...",kw={"defias","edwin vancleef","miguel mantoforte","mathias shaw","relatório do shaw","avin","guilda dos pedreiros","cerro oeste"},ang={["class:Rogue"]="O relatório destaca o alcance e os métodos do Mestre Mathias Shaw, o mestre indiscutível da rede de espionagem de Ventobravo e líder da AVIN.",["faction:Alliance"]="O documento expõe a podridão interna de Ventobravo, detalhando como uma dívida não paga aos arquitetos do reino deu origem a uma insurreição que ameaça as terras agrícolas do reino."},sec={{t="Informações sobre os Pedreiros",b="Levado do quartel-general secreto da AVIN em Ventobravo até o Morro da Sentinela, o Relatório do Shaw fornece à Milícia do Povo sua primeira explicação clara sobre quem comanda os bandidos que assolam Cerro Oeste. O documento detalha como a Guilda dos Pedreiros, sob a liderança de Edwin VanCleef, reconstruiu minuciosamente Ventobravo após sua destruição na Primeira Guerra. Quando a coroa e a nobreza se recusaram a pagar os pedreiros de forma justa após a conclusão das obras, um ressentimento amargo se instalou. As informações de Shaw estabelecem a ligação vital entre os artesãos desalentados e descontentes e a revolta criminosa que agora toma conta dos territórios periféricos do reino."}},faq={{q="O que é o Relatório do Shaw?",a="É um dossiê confidencial de inteligência compilado pelo Mestre Mathias Shaw, líder da agência secreta AVIN de Ventobravo, endereçado a Miguel Mantoforte. Ele contém as informações da coroa sobre a Guilda dos Pedreiros e o histórico de Edwin VanCleef.",al={"relatório do shaw","o que shaw escreve","conteúdo do relatório do shaw"}},{q="O que o relatório revela sobre Edwin VanCleef?",a="Ele identifica VanCleef como o antigo líder da Guilda dos Pedreiros que supervisionou a reconstrução de Ventobravo após a Primeira Guerra. O documento explica que VanCleef e seus artesãos se rebelaram após terem o pagamento adequado negado pelos governantes do reino.",al={"vancleef no relatório","o que diz sobre vancleef"}},{q="Por que Miguel Mantoforte precisa deste relatório?",a="Mantoforte lidera a Milícia do Povo na defesa de Cerro Oeste contra ataques coordenados de bandidos. Sem o auxílio de tropas regulares do reino, ele depende da espionagem de Mathias Shaw para descobrir quem lidera os fora da lei e quais são seus verdadeiros motivos.",al={"por que enviar relatório para miguel","por que mantoforte precisa do relatório"}},{q="Como Mantoforte reage ao relatório?",a="Mantoforte fica profundamente abalado. Ele reconhece Edwin VanCleef como um artesão trabalhador e talentoso, achando difícil acreditar que um construtor tão respeitado pudesse ter caído na vilania sem mais provas concretas.",al={"reação de miguel","reação de mantoforte"}}},fx={c86c6e50={q="De onde vem o Relatório do Shaw e quem o fez?",a="O relatório foi redigido pelo Mestre Mathias Shaw, o chefe do serviço de inteligência de Ventobravo, a AVIN. Trabalhando de sua sede na Cidade Velha, Shaw compilou as informações coletadas pela AVIN sobre a história da Guilda dos Pedreiros e Edwin VanCleef para enviar de volta a Gryan Stoutmantle no Morro da Sentinela.",al={"quem escreveu o relatório do shaw","quem fez o relatório do shaw","de onde vem o relatório do shaw"}}},fp="13,221,31.491.1,22.250.0,49.224.0,44.254.0,41.211.0"}
P.entries["item:shay-s-bell"] = {n="Shay's Bell",s="Shay’s Bell é um sino querido, guardado em um baú em Feralas. Shay Velifrondes diz que seu som pode chamá-la de volta quando ela se afasta.",h="Shay’s Bell é um sino querido, guardado em um baú em Feralas.",kw={"feralas","trinca-pedra","shay","shay velifrondes","shay’s bell","shay’s chest","wandering shay"},sec={{t="Um som familiar",b="Shay Velifrondes guarda seu sino em um baú em Feralas. Ela adora seu som e diz que ele a fará voltar correndo quando ela se afastar. Trinca-pedra espera por Shay em seu acampamento, e o sino deve ajudá-la a encontrar o caminho de volta para casa."}},faq={{q="Para que serve Shay’s Bell?",a="Shay diz que o som do sino chamará sua atenção e a fará voltar se ela se afastar.",al={"sino de shay","uso do sino","chamar shay"}},{q="Onde posso encontrar Shay’s Bell?",a="Shay’s Bell fica no baú de Shay em Feralas.",al={"localização do sino","baú de shay","onde está o sino"}},{q="A quem pertence o sino?",a="O sino é precioso para Shay Velifrondes, que adora seu som.",al={"de quem é o sino","item de shay","dono do sino"}},{q="Quem Shay está tentando encontrar?",a="Shay Velifrondes está tentando encontrar sua amiga Trinca-pedra, que está em seu acampamento.",al={"para onde shay vai","amiga de shay","trinca-pedra"}}},fp="11,128,16.225.0,26.90.0,31.51.0,28.61.0,27.75.0"}
P.entries["item:sheathed-trol-kalar"] = {n="Sheathed Trol'kalar",s="Trol'kalar repousa livre dentro de sua bainha de pedra no Planalto Arathi. Zengu, na Ruína do Martelo, aguarda a espada, muito estimada pelos Trolls Lançanegra.",h="Trol'kalar repousa livre dentro de sua bainha de pedra no Planalto Arathi.",kw={"lançanegra","ruína do martelo","nimboya","sheathed trol'kalar","bainha de pedra","trol'kalar","tumba de trollbane","zengu"},ang={["race:Troll"]="Como troll, você carrega uma arma que Zengu chama de a maior de Strom e Arathor. Os Lançanegra têm uma dívida com você por devolvê-la."},sec={{t="A Bainha de Pedra",b="Você carrega Trol'kalar dentro de sua bainha de pedra, vinda da Tumba de Trollbane, no Planalto Arathi. A luz que prendia a espada se apaga, libertando a arma. Zengu aguarda na Ruína do Martelo para recebê-la."}},faq={{q="O que é Sheathed Trol'kalar?",a="Sheathed Trol'kalar contém a espada Trol'kalar dentro de uma bainha de pedra. A luz que se apaga liberta a arma.",al={"sheathed trolkalar","espada na bainha de pedra"}},{q="Onde encontrei Trol'kalar?",a="Você encontra Sheathed Trol'kalar na Tumba de Trollbane, no Planalto Arathi.",al={"localização de trolkalar","tumba de trollbane"}},{q="Quem quer a espada?",a="Zengu, na Ruína do Martelo, aguarda Trol'kalar. Ele diz que a espada será entregue a Nimboya, em Grom'gol.",al={"quem recebe trolkalar","espada de zengu"}},{q="Por que Trol'kalar é importante para os trolls?",a="Trol'kalar é chamada de a maior arma de Strom e Arathor. Zengu diz que os Trolls Lançanegra têm uma dívida com você por devolvê-la.",al={"importância de trolkalar","por que os trolls querem a espada"}}},fp="19,136,16.186.0,28.107.0,28.69.0,20.91.0,41.132.0"}
P.entries["item:shellfish"] = {n="Shellfish",s="Os mariscos são coletados em armadilhas sob as docas da Aldeia Pescassombra. Jinar'Zillen quer que você os recolha e oferece um peixe Bloodbelly em troca.",h="Os mariscos são coletados em armadilhas sob as docas da Aldeia Pescassombra.",kw={"peixe bloodbelly","desolação","docas","jinar'zillen","aldeia pescassombra","mariscos","armadilhas de mariscos"},sec={{t="Sob as Docas",b="As águas a oeste da Aldeia Pescassombra têm armadilhas de mariscos sob as docas. Jinar'Zillen pede que você recolha cinco mariscos para deixar o trabalho para outra pessoa. Em troca, ele oferece um peixe Bloodbelly de qualidade."}},faq={{q="Onde encontro mariscos?",a="Você pode coletar mariscos em armadilhas nas águas a oeste da Aldeia Pescassombra, sob as docas.",al={"local dos mariscos","onde encontrar mariscos","armadilhas de mariscos"}},{q="Quem quer os mariscos?",a="Jinar'Zillen, na Aldeia Pescassombra, pede que você recolha mariscos nas armadilhas sob as docas.",al={"quem precisa de mariscos","jinar zillen mariscos","mariscos para quem"}},{q="De quantos mariscos Jinar'Zillen precisa?",a="Jinar'Zillen pede que você recolha cinco mariscos.",al={"quantidade de mariscos","quantas conchas","cinco mariscos"}},{q="O que Jinar'Zillen oferece pelos mariscos?",a="A cada cinco mariscos que você levar para ele, Jinar'Zillen oferece um peixe Bloodbelly.",al={"recompensa por mariscos","peixe bloodbelly","o que ganha por mariscos"}}},fp="9,146,15.223.0,26.96.0,24.96.0,42.48.0,43.78.0"}
P.entries["item:shimmering-frond"] = {n="Fronde Cintilante",s="Uma Fronde Cintilante é um espécime colhido de uma planta estranha e brilhante que cresce dentro da Clareira do Oráculo, em Teldrassil. Sua luminescência incomum e sua aura retorcida revelam que se trata de uma espécie exótica, totalmente alheia aos galhos da Árvore do Mundo.",h="Uma Fronde Cintilante é um espécime colhido de uma planta estranha e brilhante que cresce dentro da Clareira...",kw={"botanica","denalan","lago al'ameth","clareira do oráculo","fronde cintilante","strange fronded plant","pântano das mágoas","teldrassil"},ang={["class:Druid"]="O surgimento de uma planta pantanosa invasora florescendo nos galhos recém-nascidos de Teldrassil é uma curiosa anomalia ecológica digna da atenção de qualquer druida.",["profession:Herbalism"]="Os herboristas que percorrem Teldrassil podem apreciar a rara resiliência necessária para que uma espécie nativa do Pântano das Mágoas atravesse o oceano e prospere em solo estrangeiro."},sec={{t="Um espécime de longe",b="Ao caminhar sob as copas verdejantes ao redor da Clareira do Oráculo, os viajantes podem se deparar com uma vegetação estranha ostentando uma aura radiante e pulsante. As frondes colhidas dessa planta captam a luz filtrada da floresta de maneiras não naturais, brilhando com uma vitalidade vibrante. Denalan, um botânico que cuida de seus canteiros junto ao Lago Al'Ameth, reconhece a folhagem de imediato como uma espécie nativa do distante Pântano das Mágoas, nos Reinos do Leste. Como as sementes de um pântano situado tão longe, do outro lado do Grande Oceano, conseguiram criar raízes e florescer na recém-erguida Teldrassil continua sendo um mistério intrigante, levando Denalan a germinar e estudar espécimes em seu próprio solo."}},faq={{q="De onde vem a Fronde Cintilante?",a="A fronde é colhida de uma estranha planta frondosa situada na Clareira do Oráculo, em Teldrassil. A planta se destaca devido ao resplendor retorcido e pulsante que brilha em suas folhas sob a luz da floresta.",al={"onde pegar fronde cintilante","localização da fronde cintilante","strange fronded plant"}},{q="Quem se interessa pela Fronde Cintilante?",a="Denalan, um naturalista elfo noturno que conduz pesquisas botânicas ao lado do Lago Al'Ameth, está ansioso para examinar o espécime. Ele se interessa muito por vegetações estranhas que criam raízes por toda Teldrassil.",al={"quem quer fronde cintilante","para quem entregar fronde cintilante","denalan fronde cintilante"}},{q="O que torna essa planta tão incomum em Teldrassil?",a="A planta não é nativa de Kalimdor nem da Árvore do Mundo. Denalan a reconhece como uma espécie nativa das águas turvas do Pântano das Mágoas, localizado do outro lado do Grande Oceano, nos Reinos do Leste, tornando sua presença próspera em Teldrassil bastante inesperada.",al={"por que a fronde cintilante e especial","origem da planta","planta do pantano das magoas"}},{q="O que acontece depois de entregar a fronde a Denalan?",a="Denalan imediatamente planta e cultiva o espécime em seus canteiros ao lado do Lago Al'Ameth para realizar testes sobre seu rápido crescimento e propriedades exóticas.",al={"o que denalan faz com ela","historia das frondes brotadas"}}},fx={["7be1ca60"]={q="O que é a Fronde Cintilante?",a="É uma folha tirada de uma flora incomum e coberta de vegetação, conhecida como Planta Estranha Frondeada, encontrada na Clareira do Oráculo. A fronde brilha constantemente sob a copa da floresta, irradiando uma aura retorcida e pulsante incomum aos galhos de Teldrassil.",al={"o que é a fronde cintilante","item fronde cintilante","o que é esta fronde"}}},fp="16,152,20.421.0,42.151.0,42.139.0,47.183.0,47.116.0"}
P.entries["item:shimmerweed"] = {n="Tremulerva",s="A shimmerweed é uma erva distinta cultivada pelos trolls Frostmane na Cordilheira Cintilante, nas alturas nevadas de Dun Morogh. Embora os trolls a colham para seus próprios rituais tribais, os mestres-cervejeiros anões locais cobiçam seu sabor marcante e único para cervejas experimentais.",h="A shimmerweed é uma erva distinta cultivada pelos trolls Frostmane na Cordilheira Cintilante, nas alturas...",kw={"aldeia da cevada","dun morogh","frostmane","stout perfeita","rejold cervevada","cordilheira cintilante","shimmerweed"},ang={["profession:Herbalism"]="Embora não faça parte do kit padrão de um botânico de campo, a shimmerweed demonstra como a flora regional costuma ser adaptada tanto para tradições locais de fermentação quanto para a alquimia ritualística.",["race:Dwarf"]="Fiel à engenhosidade dos anões, se uma planta estranha cresce num penhasco próximo, alguém eventualmente tentará fermentá-la em cerveja."},sec={{t="Uma Plantação Trólica",b="Bem acima das terras baixas de Dun Morogh, os trolls Frostmane cuidam de canteiros de shimmerweed ao longo dos penhascos gelados da Cordilheira Cintilante. Os trolls colhem e armazenam a planta em cestos trançados espalhados por seus acampamentos, contando com ela para alimentar seus rituais sagrados e enigmáticos. Fora da sociedade trólica, poucos montanhistas dão muita atenção a essa erva, embora suas propriedades potentes tenham atraído os olhares de forasteiros inventivos."},{t="Um Ingrediente Secreto",b="Na vizinha Aldeia da Cevada, o mestre-cervejeiro Rejold Cervevada desenvolveu um grande interesse pela erva. Acreditando que a fabricação de cerveja está em seu sangue, Rejold busca criar a stout anã definitiva e suspeita que o sabor pungente e inconfundível da shimmerweed possa ser a peça que faltava. Ele frequentemente contrata viajantes aventureiros para se infiltrarem nos acampamentos Frostmane, desviarem dos trolls hostis e trazerem alqueires para despejar em seus tanques de fermentação."}},faq={{q="Onde a shimmerweed cresce?",a="A shimmerweed é encontrada no alto da Cordilheira Cintilante, uma elevação gélida a noroeste da Aldeia da Cevada em Dun Morogh. Ela é cultivada e colhida pelos trolls Frostmane, que a guardam em cestos ao redor de seus acampamentos.",al={"localização de shimmerweed","onde encontrar shimmerweed","planta cordilheira cintilante"}},{q="Para que os trolls Frostmane usam a shimmerweed?",a="Os trolls Frostmane utilizam a shimmerweed em seus misteriosos ritos e cerimônias tribais. Embora os detalhes precisos de seus rituais permaneçam obscuros para forasteiros, a erva desempenha um papel ativo em suas práticas culturais e espirituais na Cordilheira Cintilante.",al={"uso de shimmerweed por trolls","por que trolls querem shimmerweed"}},{q="Por que Rejold Cervevada quer shimmerweed?",a="Rejold Cervevada está se esforçando para produzir a stout anã perfeita na Aldeia da Cevada. Tendo identificado um sabor único na erva silvestre, ele deseja despejar alqueires frescos de shimmerweed em sua mistura experimental para ver se ela confere o perfil marcante de que sua receita precisa.",al={"missão rejold cervevada","quem quer shimmerweed","por que produzir cerveja com shimmerweed"}},{q="A shimmerweed cresce em algum lugar fora de Dun Morogh?",a="Variedades de shimmerweed já foram colhidas em terras áridas como Durotar, onde clarividentes como Drek'Thar valorizam a planta para infusões medicinais e poções de ervas potentes, provando que a planta consegue se adaptar além dos picos congelados de Khaz Modan.",al={"shimmerweed durotar","shimmerweed fora de dun morogh"}}},fx={["1978b4f9"]={q="O que é Shimmerweed?",a="Shimmerweed é uma planta distinta cultivada nas alturas nevadas de Dun Morogh pelos trolls Pelo de Gelo, particularmente ao redor de Shimmer Ridge. Notável por seu sabor e propriedades incomuns, a erva é colhida em cestos de troll e desempenha um papel em rituais tribais locais, embora cervejeiros anões ambiciosos tenham recentemente demonstrado interesse em testar suas qualidades potentes em cervejas experimentais.",al={"o que é shimmerweed","planta shimmerweed","sobre shimmerweed"}},d2fd1cd1={q="De onde vem a Shimmerweed e quem a criou?",a="Shimmerweed é cultivada naturalmente pelos trolls Pelo de Gelo em Dun Morogh, que cuidam e colhem a planta em cestos em Shimmer Ridge. Embora os Pelo de Gelo mantenham plantações dela para seus próprios rituais, variedades selvagens da erva potente também são conhecidas por crescerem em terras distantes como Durotar, onde herbalistas e xamãs da selva a valorizam para preparar poções.",al={"de onde vem shimmerweed","quem criou shimmerweed","origem de shimmerweed"}}},fp="11,155,15.319.0,19.352.0,28.175.0,49.209.0,44.230.0,50.210.0"}
P.entries["item:shindrell-s-note"] = {n="Bilhete de Shindrell",s="O Bilhete de Shindrell é uma missiva escrita detalhando observações recentes de corrupção ao redor de Astranaar e da costa de Vale Gris. Redigido pela Sentinela elfa noturna Shindrell Fogofugaz, ele serve como um relatório de inteligência enviado a leste através da floresta para o druida Kainet Brisacalma.",h="O Bilhete de Shindrell é uma missiva escrita detalhando observações recentes de corrupção ao redor de...",kw={"vale gris","astranaar","cantilenda","kainet brisacalma","floresta noturcanto","shindrell fogofugaz","bilhete de shindrell"},ang={["class:Druid"]="Levar as observações de Shindrell a Kainet Brisacalma ajuda os outros druidas a descobrir as raízes da praga sobrenatural que perturba a floresta.",["race:NightElf"]="A missiva ilustra a cooperação contínua entre as Sentinelas que defendem os assentamentos de Vale Gris e os druidas Cenarianos que estudam sua enfermidade ecológica."},sec={{t="Uma Missiva Através dos Bosques",b="À medida que a inquietação se espalha por Vale Gris, sentinelas e druidas elfos noturnos se coordenam para monitorar as fronteiras da floresta. Redigido pela Sentinela Shindrell Fogofugaz em Astranaar, este relatório detalha perturbações preocupantes avistadas ao longo da costa oeste e através das copas centrais. Ele é endereçado a Kainet Brisacalma, um druida situado no santuário de Cantilenda, dentro da Floresta Noturcanto a leste. Ao enviar mensageiros com suas observações em primeira mão, Shindrell auxilia a investigação de Kainet sobre a sutil corrupção que se infiltra pelos bosques sagrados."}},faq={{q="O que é o Bilhete de Shindrell?",a="É um relatório de campo escrito pela Sentinela Shindrell Fogofugaz detalhando perturbações e suspeitas de corrupção avistadas perto de Astranaar e ao longo da costa de Vale Gris.",al={"o que é este bilhete","bilhete de shindrell","o que diz o bilhete"}},{q="Quem deve receber o bilhete?",a="O bilhete é endereçado a Kainet Brisacalma, um druida elfo noturno localizado em Cantilenda, nos confins orientais de Vale Gris conhecidos como Floresta Noturcanto.",al={"a quem entrego isto","para onde vai","para quem é o bilhete"}},{q="Por que o bilhete foi escrito?",a="Kainet Brisacalma solicitou informações sobre ocorrências incomuns nas florestas ocidentais, temendo que uma corrupção insidiosa esteja se enraizando na mata. Shindrell reuniu seus avistamentos para ajudá-lo a avaliar a ameaça.",al={"por que escrever o bilhete","de qual corrupção shindrell está falando","propósito do relatório"}},{q="Onde reside Shindrell Fogofugaz?",a="Shindrell Fogofugaz é uma sentinela elfa noturna posicionada no assentamento de Astranaar, localizado no centro de Vale Gris.",al={"onde está shindrell","localização de shindrell fogofugaz","quem enviou isto"}}},fx={ed6c40b2={q="De onde vem o Bilhete de Shindrell e quem o criou?",a="O bilhete foi escrito pela sentinela Shindrell Fogofugaz em Astranaar. Escrito como um relatório de campo formal, ele detalha os eventos perturbadores que ela observou ao longo da costa de Vale Gris e por todos os bosques circundantes.",al={"quem escreveu o bilhete de shindrell","quem criou o bilhete de shindrell","origem do bilhete de shindrell"}}},fp="16,162,26.450.0,25.139.0,33.121.0,25.183.0,38.102.0"}
P.entries["item:shipment-of-boots"] = {n="Carregamento de Botas",s="Um caixote de calçados despachado de Angra do Butim pelo comerciante Drizzlik, destinado à rede comercial de Gasganete em Vila Catraca. Ele foi interceptado na costa por Flibusteiros dos Mares do Sul e escondido no acampamento deles ao sul do porto.",h="Um caixote de calçados despachado de Angra do Butim pelo comerciante Drizzlik, destinado à rede comercial de...",kw={"angra do butim","drizzlik","gasganete","vila catraca","carregamento de botas","os flibusteiros dos mares do sul","butim roubado"},ang={["class:Rogue"]="Infiltrar-se nos acampamentos dos Mares do Sul ao longo da costa exige desviar de patrulhas densas de piratas, tornando uma abordagem furtiva a maneira mais segura de recuperar a carga roubada de Gasganete."},sec={{t="Uma Carga Saqueada",b="Administrar um porto comercial goblin exige suprimentos sem fim, e Gasganete encomendou uma nova remessa de botas de Drizzlik, um fornecedor de vestuário estabelecido em Angra do Butim. O carregamento nunca chegou às docas de Vila Catraca. Os Flibusteiros dos Mares do Sul que rondavam a Costa dos Mercadores emboscaram a embarcação de transporte, levando os caixotes para seus acampamentos na praia, ao sul do porto. Os piratas espalharam a carga roubada por suas tendas e barracos, deixando Gasganete sem as mercadorias esperadas até que mercenários aventureiros pudessem ser contratados para vasculhar o litoral."}},faq={{q="Quem enviou este carregamento de botas?",a="As botas foram enviadas de Angra do Butim por Drizzlik, um comerciante goblin que administra um empório que vende roupas e suprimentos no porto ao sul.",al={"quem fez as botas","de onde vieram as botas","botas de drizzlik"}},{q="Quem deveria receber as botas?",a="Gasganete, o engenheiro-chefe e superintendente de Vila Catraca, encomendou os calçados para abastecer sua força de trabalho local e suas operações mercantis.",al={"quem é o dono das botas","carregamento de botas de gasganete"}},{q="Como as botas foram parar com os piratas?",a="Os Flibusteiros dos Mares do Sul interceptaram o navio de carga ao longo da costa dos Sertões, saqueando a embarcação e levando os caixotes de volta para seus acampamentos ao sul de Vila Catraca.",al={"por que os piratas dos mares do sul têm botas","quem roubou as botas"}},{q="Onde o carregamento pode ser encontrado?",a="O caixote fica dentro do acampamento de piratas dos Mares do Sul situado ao longo do litoral ao sul de Vila Catraca, escondido em meio aos seus bens saqueados.",al={"localização das botas","onde fica carregamento de botas","encontrar carregamento de botas"}}},fx={["06b396e7"]={q="O que é o Carregamento de Botas?",a="O Carregamento de Botas é um caixote de calçados enviado através do Grande Oceano de Angra do Butim para Vila Catraca. Despachado pelo mercador goblin Drizzlik, era destinado diretamente a Gasganete antes que os Southsea Freebooters interceptassem o navio de carga que transportava suas mercadorias.",al={"o que é o carregamento de botas","item carregamento de botas","quais são as botas"}}},fp="17,211,17.348.0,32.80.0,38.152.0,42.149.0,32.107.0"}
P.entries["item:shipment-of-iron"] = {n="Carregamento de Ferro",s="Um caixote de metal bruto armazenado na ferraria humana nos Campos de Eira dos Montes. Ele serve como suprimento vital para a produção bélica local, tornando-se um alvo prioritário para as forças dos Renegados que procuram cortar as rotas de abastecimento que armam os cidadãos de Eira dos Montes.",h="Um caixote de metal bruto armazenado na ferraria humana nos Campos de Eira dos Montes.",kw={"battle of hillsbrad","darthalia","campos de eira dos montes","carregamento de ferro","serraria tarren","verringtan"},ang={["faction:Horde"]="Negar suprimentos a Eira dos Montes paralisa a resistência armada dos fazendeiros antes que a campanha avance contra Costa Sul.",["profession:Blacksmithing"]="O estoque representa a força vital da produção de armas humanas no vale; sem as barras de ferro bruto, a forja de Verringtan fica completamente inútil."},sec={{t="Alimentando a Resistência",b="Na luta contínua através do Contraforte de Eira dos Montes, o campesinato humano montou uma resistência surpreendentemente ferrenha contra Serraria Tarren. Boa parte dessa capacidade de combate vem diretamente da ferraria na borda sudoeste dos Campos de Eira dos Montes, onde o Ferreiro Verringtan e seus aprendizes trabalham dia e noite forjando armas e armaduras a partir de pesados carregamentos de ferro. Para quebrar a determinação dos fazendeiros, os comandantes dos Renegados ordenaram que a forja fosse apagada, seus ferreiros eliminados e seus estoques de metal confiscados para o esforço de guerra da Horda."}},faq={{q="Onde o carregamento de ferro é guardado?",a="O carregamento fica diretamente dentro da oficina do ferreiro situada no limite sudoeste dos Campos de Eira dos Montes, fortemente vigiado pelo Ferreiro Verringtan e seus aprendizes.",al={"localização do carregamento de ferro","onde fica o ferro","localização do ferro de eira dos montes"}},{q="Por que os Renegados querem esse ferro?",a="Tomar o ferro interrompe a linha de suprimento de armas que equipa a milícia humana local. Alta-executora Darthalia também pretende reaproveitar os estoques de metal para apoiar a máquina de guerra da Horda quando a ofensiva se voltar para arrasar Costa Sul.",al={"por que roubar ferro","ferro de serraria tarren","objetivo do ferro em battle of hillsbrad"}},{q="Quem usava esse ferro originalmente?",a="O Ferreiro Verringtan e seus quatro aprendizes de ferreiro usavam o ferro para equipar os habitantes do povoado e os trabalhadores rurais, transformando simples fazendeiros em uma força armada de defesa local contra os mortos-vivos.",al={"a quem pertence o ferro","ferro de verringtan","ferreiros de eira dos montes"}},{q="Quem ordena a recuperação do carregamento de ferro?",a="Alta-executora Darthalia, que comanda as operações dos Renegados a partir da Serraria Tarren, dá a ordem direta para matar os ferreiros e tomar o ferro durante a Battle of Hillsbrad.",al={"quem dá a missão","missão de ferro da darthalia"}}},fx={["8a003d21"]={q="O que é o Carregamento de Ferro?",a="O Carregamento de Ferro é um estoque de metal bruto armazenado na ferraria humana nos Campos de Eira dos Montes. Serve como o material principal que o ferreiro Verringtan e seus aprendizes usam para forjar armas e armaduras para os habitantes locais de Eira dos Montes que resistem aos Renegados.",al={"o que é o carregamento de ferro","carregamento de ferro","carregamento de ferro eira dos montes"}}},fp="16,106,22.445.0,35.153.0,37.217.0,35.182.0,46.154.0"}
P.entries["item:shipment-to-nethergarde"] = {n="Shipment to Nethergarde",s="A caravana de Biggs envia suprimentos vitais do Pântano das Mágoas à Bastilha de Etergarde. A bastilha precisa deles para vigiar o Portal Negro.",h="A caravana de Biggs envia suprimentos vitais do Pântano das Mágoas à Bastilha de Etergarde.",kw={"azoran crystals","biggs","barreira do inferno","portal negro","bastilha de etergarde","ataques de ogros","intendente lungertz","carga para etergarde"},ang={["faction:Alliance"]="Como viajante da Aliança, você leva suprimentos à Bastilha de Etergarde, que vigia o Portal Negro."},sec={{t="Uma entrega necessária",b="Biggs pede que você leve à Intendente Lungertz, na Bastilha de Etergarde, suprimentos salvos de ataques de ogros. A bastilha vigia o Portal Negro das colinas ao norte da Barreira do Inferno. Biggs está consertando sua carroça, então a carga precisa seguir pela estrada sem ele."}},faq={{q="O que há na carga?",a="A carga contém suprimentos vitais resgatados de ataques de ogros. A Intendente Lungertz espera que ela inclua Azoran Crystals, que estão acabando nos estoques de Etergarde.",al={"conteúdo da carga","o que há no pacote","azoran crystals"}},{q="Quem enviou a carga?",a="Biggs preparou os suprimentos para a Bastilha de Etergarde depois que ataques de ogros ameaçaram a caravana.",al={"quem preparou a carga","pacote do biggs","de onde vem a carga"}},{q="Quem deve receber a carga?",a="A Intendente Lungertz, na Bastilha de Etergarde, está esperando a carga.",al={"quem recebe o pacote","entrega para etergarde","intendente lungertz"}},{q="Por que Etergarde precisa dela?",a="A Bastilha de Etergarde precisa dos suprimentos, e a Intendente Lungertz diz que as reservas de Azoran Crystals estão acabando.",al={"por que levar suprimentos","do que a bastilha precisa","estoque de etergarde"}}},fp="23,147,17.266.0,24.163.0,22.89.0,32.71.0,29.113.0"}
P.entries["item:shipping-schedule"] = {n="Shipping Schedule",s="O Shipping Schedule é um documento logístico mantido pelo mestre do cais da Irmandade Défias no Ancoradouro de Jerod. Ele descreve os carregamentos ilícitos que fluem pela Floresta de Elwynn entre as Montanhas Cristarrubra e Cerro Oeste, atraindo a atenção cuidadosa da agência de inteligência de Ventobravo.",h="O Shipping Schedule é um documento logístico mantido pelo mestre do cais da Irmandade Défias no Ancoradouro...",kw={"defias","mestre do cais","floresta de elwynn","ancoradouro de jerod","mathias shaw","shipping schedule","avin","contrabando"},ang={["class:Rogue"]="Obter o cronograma dos bolsos do mestre do cais é um teste definitivo de furtividade e furto para aspirantes a agentes que buscam ingressar nas fileiras da AVIN."},sec={{t="Contrabando no Ancoradouro de Jerod",b="Ao sul de Vila d'Ouro, na margem de Elwynn do Nazferiti River, a Irmandade Défias assumiu o controle do Ancoradouro de Jerod para servir como centro de seu tráfego fluvial. Por meio deste cais secreto, a Irmandade transporta grandes quantidades de contrabando entre as Montanhas Cristarrubra e Cerro Oeste, deslizando pelas vias navegáveis bem debaixo do nariz da Guarda de Ventobravo. O Shipping Schedule registra essas movimentações clandestinas, mantido sob guarda cerrada junto ao corpo do mestre do cais."},{t="Na mira da AVIN",b="O Mestre Mathias Shaw, líder da AVIN, encomendou o roubo do cronograma para mapear as cadeias de suprimentos Défias e testar agentes novatos. Infiltrar-se na casa do cais e surrupiar o documento dos bolsos do mestre do cais serve tanto como inteligência acionável para a coroa quanto como teste de iniciação. Se o agente for capturado, a AVIN nega qualquer ligação, não deixando nenhum rastro de volta ao quartel em Ventobravo."}},faq={{q="O que é o Shipping Schedule?",a="É um registro operacional mantido pelo mestre do cais da Irmandade Défias no Ancoradouro de Jerod. Ele detalha a movimentação de contrabando e suprimentos transportados entre as Montanhas Cristarrubra e Cerro Oeste pelas águas interiores da Floresta de Elwynn.",al={"horário de embarque de défias","o que e este documento","cronograma do mestre do cais"}},{q="Quem deseja a recuperação deste cronograma?",a="O Mestre Mathias Shaw, líder do serviço de inteligência de Ventobravo, a AVIN. Ele usa a inteligência para rastrear o aparato de contrabando Défias e para avaliar ladinos promissores em campo.",al={"quem precisa do cronograma","cronograma de mathias shaw","quem pega o shipping schedule"}},{q="Onde o cronograma é encontrado?",a="O documento é carregado pelo Defias Dockmaster dentro da casa do cais no Ancoradouro de Jerod, localizado no Nazferiti River, ao sul de Vila d'Ouro, na Floresta de Elwynn. Um agente deve entrar furtivamente no edifício e bater a carteira ou saqueá-lo dele.",al={"localizacao do shipping schedule","onde fica o mestre do cais","como conseguir o cronograma"}},{q="Para que é usado o Ancoradouro de Jerod?",a="O Ancoradouro de Jerod foi invadido por bandidos Défias para servir como ponto de trânsito. Eles usam seu acesso ao rio para contrabandear cargas ilícitas pelo reino, conectando suas operações nas Montanhas Cristarrubra diretamente às suas fortalezas em Cerro Oeste.",al={"ancoradouro de jerod defias","por que os defias tem o ancoradouro de jerod","cais defias elwynn"}}},fx={["45ccd8c3"]={q="De onde vem o Shipping Schedule e quem o criou?",a="O horário é mantido pelo mestre de docas da The Defias Brotherhood estacionado no Ancoradouro de Jerod, ao sul de Vila d'Ouro. Ele detalha as operações fluviais do sindicato de fora da lei, rastreando o movimento de mercadorias ilícitas e contrabando transportado entre as Montanhas Cristarrubra e Cerro Oeste.",al={"quem escreveu o shipping schedule","origem do shipping schedule","quem criou o defias shipping schedule"}}},fp="17,181,28.335.0,25.350.0,30.208.0,34.141.0,28.208.0,33.167.0"}
P.entries["item:shrunken-head"] = {n="Shrunken Head",s="Uma Shrunken Head é retirada de caçadores de cabeças Bloodscalp no norte da Selva do Espinhaço. Nimboya, no Acampamento Grom'gol, examina as cabeças em busca de notícias de Yennikan.",h="Uma Shrunken Head é retirada de caçadores de cabeças Bloodscalp no norte da Selva do Espinhaço.",kw={"bloodscalp","grom'gol","headhunter","nimboya","shrunken head","yennikan","zul'kunda","zuuldaia"},ang={["faction:Horde"]="Como membro da Horda, você pode levar a Nimboya as cabeças de que ele precisa para procurar Yennikan, o filho do chefe."},sec={{t="A busca de Nimboya",b="No Acampamento Grom'gol, Nimboya pede que você lhe traga Shrunken Heads de Bloodscalp Headhunters. Ele procura em cada uma sinais de Yennikan, o filho do chefe, cujo destino desconhece. As ruínas de Zuuldaia e Zul'Kunda ficam no litoral norte, onde é possível encontrar muitos Headhunters."}},faq={{q="Para que serve uma Shrunken Head?",a="Nimboya examina Shrunken Heads para descobrir se Yennikan está entre os mortos.",al={"uso de shrunken head","por que coletar cabeças"}},{q="Quem está procurando Yennikan?",a="Nimboya, no Acampamento Grom'gol, teme por Yennikan, o filho do chefe, e busca sinais de seu destino.",al={"quem procura yennikan","busca de nimboya"}},{q="De onde vêm as Shrunken Heads?",a="Os Bloodscalp Headhunters no norte da Selva do Espinhaço carregam as cabeças que Nimboya procura.",al={"onde encontrar cabeças","cabeças bloodscalp"}},{q="Onde posso encontrar Bloodscalp Headhunters?",a="Nimboya indica as ruínas de Zuuldaia e Zul'Kunda, no litoral norte.",al={"localização de headhunters","onde ficam os headhunters"}}},fp="13,154,16.289.0,28.75.0,27.94.0,34.79.0,40.79.0"}
P.entries["item:sida-s-bag"] = {n="Bolsa da Cida",s="A Bolsa da Cida é a sacola pessoal de Cida, uma moradora do Porto de Menethil. Engolida inteira por uma gosma rastejante durante sua excursão à Tumba dos Barbaférreos, a bolsa e seu conteúdo misterioso exigem uma caçada minuciosa pelas lamas ácidas do Pantanal para serem recuperados.",h="A Bolsa da Cida é a sacola pessoal de Cida, uma moradora do Porto de Menethil.",kw={"dun modr","tumba dos barbaférreos","porto de menethil","gosma","cida","bolsa da cida","pantanal"},ang={["faction:Alliance"]="Os refugiados e habitantes acuados do Porto de Menethil dependem inteiramente de viajantes que passam pelo local para lidar com os horrores predatórios que rastejam do Pantanal alagado."},sec={{t="Uma defesa em pânico",b="Enquanto fazia sua costumeira visita semanal à Tumba dos Barbaférreos perto de Dun Modr, Cida foi emboscada pelas terríveis e gotejantes gosmas que infestam a área. Em pânico diante do lodo que se aproximava, ela arremessou sua sacola pessoal diretamente contra uma das criaturas. Em vez de afugentar a besta, a gosma simplesmente absorveu a bolsa em seu corpo gelatinoso. A distração garantiu a Cida preciosos momentos para fugir com vida de volta à segurança do Porto de Menethil, deixando seus pertences presos dentro de uma gosma desconhecida."},{t="Recuperada do lodo",b="Como as ondulantes gosmas que rondam a Tumba dos Barbaférreos — variando de variedades carmesins a monstruosas — são muito parecidas, encontrar a bolsa exige abater as lamas do pântano até que a sacola engolida apareça intacta. Apesar de ficar de molho na gosma digestiva ácida, a bolsa resistente preserva seu conteúdo. Uma vez devolvida a Cida, ela prontamente recolhe seus pertences e descarta o exterior arruinado e coberto de gosma, oferecendo o recipiente desbotado a quem quer que tenha desafiado o pântano em seu favor."}},faq={{q="Por que a bolsa de Cida estava dentro de uma gosma?",a="Cida entrou em pânico quando foi atacada por gosmas gotejantes durante uma visita à Tumba dos Barbaférreos. Desesperada para fugir, ela arremessou sua sacola contra um dos monstros, que imediatamente a envolveu e engoliu por inteiro.",al={"como gosma pegou bolsa","por que bolsa esta no lodo","como cida perdeu a bolsa"}},{q="Quais gosmas carregam a Bolsa da Cida?",a="Cida não consegue diferenciar as lamas, portanto qualquer uma das gosmas predadoras que cercam a Tumba dos Barbaférreos no nordeste do Pantanal — incluindo Crimson Oozes, Black Oozes ou Monstrous Oozes — pode tê-la engolido.",al={"onde encontrar a bolsa da cida","o que dropa bolsa da cida","qual gosma tem a bolsa"}},{q="Por que Cida visita a Tumba dos Barbaférreos?",a="Cida faz uma jornada semanal partindo do Porto de Menethil para visitar a antiga cripta anã perto de Dun Modr, embora guarde para si os motivos pessoais por trás de suas visitas de rotina.",al={"conexao cida barbaferreos","por que tumba dos barbaferreos"}},{q="O que havia dentro da bolsa de Cida?",a="Cida esvazia rapidamente os itens recuperados no chão e os junta sem mostrar o que são, apenas observando que o conteúdo era importante demais para ser deixado dissolvendo dentro de uma gosma.",al={"o que cida tira da bolsa","conteudo da bolsa"}}},fx={["113113dd"]={q="O que é a Bolsa da Cida?",a="A Bolsa da Cida é uma mochila pessoal pertencente à Cida, uma residente que está hospedada no Porto de Menethil. Enquanto fazia sua visita rotineira à Tumba dos Barbaférreos no Pantanal, ela foi emboscada por limos e arremessou sua bolsa em um deles em uma tentativa frenética de escapar. A criatura a engoliu inteira, deixando a bolsa presa dentro do corpo gelatinoso da criatura.",al={"o que é a bolsa da cida","bolsa da cida","quem é a bolsa da cida"}},afbd2451={q="Por que a Cida quer sua bolsa de volta?",a="A Cida precisa desesperadamente do conteúdo trancado dentro de sua mochila perdida, e não da bolsa em si. Assim que você a retira dos restos dos limos na Tumba dos Barbaférreos e a devolve para ela no Porto de Menethil, ela imediatamente despeja o conteúdo viscoso no chão, recolhe-o e entrega a você a bolsa vazia e manchada de limo.",al={"por que a cida quer sua bolsa","por que bolsa da cida","por que alguém quer a bolsa da cida"}}},fp="10,224,18.300.0,24.369.0,34.160.0,29.204.0,37.154.0,27.179.0"}
P.entries["item:sigil-fragment"] = {n="Sigil Fragment",s="Sigil Fragment é uma peça de um sigilo protetor procurado no Planalto Arathi. Tor’gan, na Ruína do Martelo, pode unir os fragmentos reunidos.",h="Sigil Fragment é uma peça de um sigilo protetor procurado no Planalto Arathi.",kw={"planalto arathi","sigilo quebrado","galen","ruína do martelo","sigil fragment","sigil of thoradin","stromgarde","thoras trollbane","tor'gan"},ang={["class:Shaman"]="Como xamã, você talvez reconheça o papel de Tor’gan: o xamã troll pode unir os fragmentos e formar um sigilo completo."},sec={{t="Partes de um sigilo",b="Defensores de Stromgarde guardam fragmentos do sigilo nas ruínas de Stromgarde. Galen, filho de Thoras Trollbane, dividiu o Sigil of Thoradin em onze partes e as espalhou entre os defensores. Tor’gan, um xamã troll na Ruína do Martelo, pode unir as partes reunidas e restaurar o sigilo completo."}},faq={{q="O que é um Sigil Fragment?",a="Um Sigil Fragment é uma das partes do Sigil of Thoradin, que Galen dividiu em onze partes.",al={"parte do sigilo","o que é este fragmento","significado do fragmento"}},{q="Quem está com os fragmentos?",a="Defensores de Stromgarde no Planalto Arathi guardam os fragmentos.",al={"onde encontrar fragmentos","quem guarda as partes do sigilo","fragmentos de stromgarde"}},{q="Quem pode reconstruir o sigilo?",a="Tor’gan, o xamã troll na Ruína do Martelo, pode unir os fragmentos e restaurar o Sigil of Thoradin completo.",al={"quem conserta o sigilo","fragmentos de tor’gan","reconstruir sigilo quebrado"}},{q="Por que o sigilo foi dividido?",a="Galen, filho de Thoras Trollbane, dividiu o Sigil of Thoradin em onze partes e as espalhou entre os defensores de Stromgarde.",al={"por que dividir o sigilo","quem o dividiu","sigilo de galen"}}},fp="14,151,17.297.0,25.94.0,22.64.0,36.102.1,31.127.1"}
P.entries["item:sigil-of-arathor"] = {n="Sigil of Arathor",s="O Sigil of Arathor está com o tenente Valorcall, líder da cavalaria de Stromgarde. Zengu, na Ruína do Martelo, quer o sigilo para procurar Trol’kalar.",h="O Sigil of Arathor está com o tenente Valorcall, líder da cavalaria de Stromgarde.",kw={"planalto arathi","cavalaria","ruína do martelo","tenente valorcall","sigil of arathor","stromgarde","trol'kalar","zengu"},ang={["faction:Horde"]="Como membro da Horda, você pode ouvir Zengu, na Ruína do Martelo, buscar o sigilo para enfraquecer os defensores de Stromgarde."},sec={{t="Um sigilo de cavalaria",b="O tenente Valorcall leva o Sigil of Arathor pelo Planalto Arathi. Ele lidera a cavalaria que serve ao príncipe humano e aos defensores de Stromgarde. Zengu, na Ruína do Martelo, busca o sigilo, e o cavalo de Valorcall permite que ele percorra a região com rapidez."},{t="O objetivo de Zengu",b="Zengu quer que devolvam o sigilo a ele na Ruína do Martelo. Ele acredita que tomá-lo de Valorcall enfraquecerá os defensores de Stromgarde. Também diz que o sigilo o aproxima de conquistar Trol’kalar."}},faq={{q="O que é o Sigil of Arathor?",a="O Sigil of Arathor é um símbolo carregado pelo tenente Valorcall, líder da cavalaria de Stromgarde.",al={"sigil of arathor","sigilo de arathor"}},{q="Quem está com o sigilo?",a="O tenente Valorcall leva o Sigil of Arathor enquanto cavalga pelo Planalto Arathi.",al={"sigilo de valorcall","quem está com ele"}},{q="Onde está o tenente Valorcall?",a="O tenente Valorcall cavalga pelo Planalto Arathi, onde seu cavalo permite que viaje rapidamente.",al={"onde está valorcall","encontrar valorcall"}},{q="Quem quer o Sigil of Arathor?",a="Zengu, na Ruína do Martelo, quer que devolvam o Sigil of Arathor a ele.",al={"quem quer o sigilo","zengu quer"}},{q="Por que Zengu quer o sigilo?",a="Zengu acredita que tomar o sigilo enfraquecerá os defensores de Stromgarde e o aproximará de conquistar Trol’kalar.",al={"por que zengu quer","sigilo trolkalar"}}},fp="16,149,15.259.0,17.203.1,29.102.0,18.91.0,30.97.0,31.63.0,30.115.0"}
P.entries["item:sigil-of-ignaeus"] = {n="Signo de Ígnaeus",s="O Signo de Ígnaeus é formado por quatro signos antigos na Ruína do Martelo. Sua luz pode abrir caminho pelas proteções do túmulo de Trollbane.",h="O Signo de Ígnaeus é formado por quatro signos antigos na Ruína do Martelo.",kw={"ruína do martelo","ígneaus","sacrário","signo","signo de ígnaeus","stromgarde","trol'kalar","trollbane","zengu"},sec={{t="Os Signos Unidos",b="Na Ruína do Martelo, Zengu entrega a você o Signo de Ígnaeus depois que os quatro signos separados são reunidos. Suas linhas brilhantes correspondem às inscrições na face do túmulo de Trollbane, no Sacrário em Stromgarde. As proteções do túmulo barram o caminho até o que há lá dentro."},{t="No Túmulo de Trollbane",b="Quando você alinha as linhas do signo às inscrições no túmulo de Trollbane, um clarão de luz o consome. As mãos de pedra soltam a espada lendária Trol'kalar."}},faq={{q="O que é o Signo de Ígnaeus?",a="O Signo de Ígnaeus é um único signo formado quando os Sigils of Strom, Thoradin, Arathor e Trollbane são reunidos.",al={"signo de ígnaeus","o que é o signo"}},{q="Quem entrega o Signo de Ígnaeus a você?",a="Zengu entrega o Signo de Ígnaeus a você na Ruína do Martelo.",al={"quem tem o signo de ígnaeus","onde conseguir o signo","signo de zengu"}},{q="O que o signo faz?",a="Suas linhas brilhantes correspondem às inscrições no túmulo de Trollbane e rompem as proteções que o guardam.",al={"uso do signo","por que precisa do signo de ígnaeus","romper proteções do túmulo"}},{q="Onde fica o túmulo de Trollbane?",a="O túmulo de Trollbane fica no Sacrário, atrás da capela em Stromgarde.",al={"localização do túmulo de trollbane","onde fica o túmulo","localização do sacrário"}},{q="O que acontece com o signo no túmulo?",a="Um clarão de luz consome o Signo de Ígnaeus quando suas linhas são alinhadas às inscrições do túmulo.",al={"signo consumido","o que acontece com o signo","clarão no túmulo"}}},fp="16,139,17.256.0,19.155.1,29.126.0,35.51.0,23.94.1,26.69.0,38.97.1"}
P.entries["item:sigil-of-strom"] = {n="Sigil of Strom",s="O Sigil of Strom é um dos selos que protegem Trol'kalar no túmulo de Trollbane. Zengu, da Ruína do Martelo, procura por ele entre a Camarilha em Stromgarde.",h="O Sigil of Strom é um dos selos que protegem Trol'kalar no túmulo de Trollbane.",kw={"ruína do martelo","sigil of strom","stromgarde","camarilha","trol'kalar","matador de trolls","trollbane","zengu"},sec={{t="Um Sigil of Strom de Stromgarde",b="A Camarilha tomou um dos sigilos que protegem Trol'kalar, a antiga espada matadora de trolls. Zengu, da Ruína do Martelo, precisa dele como primeiro passo para reunir os selos que protegem a lâmina no túmulo de Trollbane."}},faq={{q="O que é o Sigil of Strom?",a="O Sigil of Strom é um dos vários selos que protegem Trol'kalar no túmulo de Trollbane.",al={"significado de sigil of strom","sigilo de strom","o que é o sigilo"}},{q="Quem quer o Sigil of Strom?",a="Zengu, na Ruína do Martelo, procura o Sigil of Strom para começar a reunir os selos que protegem Trol'kalar.",al={"quem precisa do sigilo","sigilo de zengu","quem quer o sigilo"}},{q="Onde posso encontrar o Sigil of Strom?",a="A Camarilha tomou o Sigil of Strom, e um de seus agentes em Stromgarde está com ele.",al={"localização do sigilo","onde fica o sigilo de strom","encontrar o sigilo"}},{q="Por que Zengu precisa do sigilo?",a="O sigilo é um dos vários selos de que Zengu precisa para retirar Trol'kalar do túmulo de Trollbane.",al={"por que pegar o sigilo","por que zengu quer o sigilo","selos de trol'kalar"}},{q="O que é Trol'kalar?",a="Trol'kalar é uma antiga espada cujo nome significa matador de trolls na língua dos trolls. Lord Ignaeus of Strom, chamado Trollbane, empunhou-a em batalha.",al={"espada trol'kalar","matador de trolls","significado de trol'kalar"}}},fp="14,145,18.204.0,27.85.0,29.98.0,36.86.0,30.89.1,19.146.0"}
P.entries["item:sigil-of-the-hammer"] = {n="Signo do Martelo",s="O Signo do Martelo é um sinal para procurar estudiosos que guardam o Compêndio de Yagyin. Ele abre caminho para conhecimentos buscados para proteção.",h="O Signo do Martelo é um sinal para procurar estudiosos que guardam o Compêndio de Yagyin.",kw={"forlorn cavern","gerrig agarrosso","signo do martelo","altaforja","guardião bel'dugur","cidade baixa","compêndio de yagyin"},sec={{t="Um Sinal de Aprendizado",b="Uma tabuleta aponta para um compêndio escrito por Yagyin, e o Signo do Martelo é o sinal que abre o caminho até ele. Em Altaforja, Gerrig Agarrosso mantém uma loja em Forlorn Cavern. Na Cidade Baixa, o Guardião Bel'dugur cuida de uma coleção de livros. Mostre o signo a qualquer um dos estudiosos e peça o compêndio."}},faq={{q="Para que serve o Signo do Martelo?",a="O Signo do Martelo identifica quem o carrega para os estudiosos a quem se pode pedir o Compêndio de Yagyin.",al={"uso do signo","finalidade do signo do martelo"}},{q="A quem devo mostrar o signo?",a="Mostre o Signo do Martelo a Gerrig Agarrosso, em Altaforja, ou ao Guardião Bel'dugur, na Cidade Baixa.",al={"a quem entregar o signo","destinatário do signo"}},{q="Onde fica Gerrig Agarrosso?",a="Gerrig Agarrosso mantém uma loja em Forlorn Cavern, em Altaforja.",al={"localização de gerrig","loja de gerrig"}},{q="Onde fica o Guardião Bel'dugur?",a="O Guardião Bel'dugur fica na Cidade Baixa, onde cuida de uma coleção de livros.",al={"localização de bel'dugur","estudioso da cidade baixa"}},{q="Por que o compêndio é importante?",a="O compêndio contém conhecimentos buscados para proteger quem os procura.",al={"por que o compêndio de yagyin","importância do compêndio"}}},fp="19,139,18.303.0,36.95.0,27.98.0,25.64.0,26.75.0,27.63.0"}
P.entries["item:sigil-of-thoradin"] = {n="Sigil of Thoradin",s="O Sigil of Thoradin é um selo restaurado ligado ao túmulo de Trollbane no Planalto Arathi. Zengu, na Ruína do Martelo, precisa dele para ajudar a abrir o túmulo.",h="O Sigil of Thoradin é um selo restaurado ligado ao túmulo de Trollbane no Planalto Arathi.",kw={"planalto arathi","ruína do martelo","sigil of thoradin","thoradin","túmulo","trol'kalar","trollbane","zengu"},sec={{t="Um selo restaurado",b="Zengu, na Ruína do Martelo, precisa do Sigil of Thoradin para ajudar a destrancar o selo no túmulo de Trollbane. A reconstrução deu certo, e o trabalho para chegar a Trol'kalar pode continuar. Zengu diz que a busca está apenas na metade; os portadores do terceiro sigilo circulam pelo Planalto Arathi."}},faq={{q="O que o Sigil of Thoradin abre?",a="O Sigil of Thoradin restaurado pode ajudar a destrancar o selo no túmulo de Trollbane.",al={"o que o sigilo abre","selo do túmulo"}},{q="Quem precisa do sigilo?",a="Zengu, na Ruína do Martelo, precisa do Sigil of Thoradin restaurado.",al={"quem quer o sigilo","a quem dar o sigilo"}},{q="Por que o sigilo é importante?",a="Ele é necessário para ajudar a remover Trol'kalar do túmulo de Trollbane.",al={"por que o sigilo importa","finalidade do sigilo"}},{q="Onde está o terceiro sigilo?",a="Zengu não sabe onde está o terceiro sigilo; seus portadores circulam pelo Planalto Arathi.",al={"localização do terceiro sigilo","onde está o terceiro"}}},fp="17,138,15.265.0,37.76.0,20.57.0,27.61.1,25.77.0"}
P.entries["item:sigil-of-trollbane"] = {n="Sigil of Trollbane",s="O príncipe Galen Trollbane guarda o Sigil of Trollbane em Stromgarde. Zengu, na Ruína do Martelo, busca o sigilo, e você deve enfrentar o príncipe para conquistá-lo.",h="O príncipe Galen Trollbane guarda o Sigil of Trollbane em Stromgarde.",kw={"galen trollbane","príncipe galen","sigil of trollbane","stromgarde","thoras trollbane","trol'kalar","trollbane","zengu"},ang={["class:Warrior"]="Como guerreiro, você pode considerar o príncipe Galen um guardião adequado para o último sigilo; ele próprio é um combatente experiente."},sec={{t="O último sigilo",b="Zengu, na Ruína do Martelo, busca o sigilo final, que o príncipe Galen mantém em Stromgarde. Galen vive em uma capela no distrito controlado pela milícia e está bem protegido. Leve o sigilo a Zengu para que o caminho até a tumba de Thoras Trollbane possa ser aberto."}},faq={{q="Para que serve o Sigil of Trollbane?",a="O Sigil of Trollbane é o último sigilo necessário para abrir a tumba de Thoras Trollbane e reivindicar Trol’kalar.",al={"finalidade do sigilo","por que precisa do sigilo","sigilo de trollbane"}},{q="Quem está com o Sigil of Trollbane?",a="O príncipe Galen Trollbane está com o Sigil of Trollbane em Stromgarde.",al={"quem está com ele","guardião do sigilo","sigilo de galen"}},{q="Onde posso encontrar o príncipe Galen?",a="O príncipe Galen vive em uma capela no distrito de Stromgarde controlado pela milícia.",al={"onde está galen","localização de galen","encontrar o príncipe trollbane"}},{q="Quem quer o sigilo?",a="Zengu, na Ruína do Martelo, busca o Sigil of Trollbane.",al={"quem quer o sigilo","sigilo para zengu","sigilo na ruína do martelo"}},{q="O que acontece depois que os sigilos são reunidos?",a="Com os sigilos em mãos, Zengu planeja atacar os trolls de Zul’Gurub e tomar Trol’kalar da tumba de Thoras Trollbane.",al={"o que vem depois dos sigilos","próximo passo para trol’kalar","abrir a tumba"}}},fp="18,142,14.244.0,35.106.2,31.66.0,30.76.0,20.49.0,41.134.1"}
P.entries["item:sign-of-the-earth"] = {n="Signo da Terra",s="O Signo da Terra é um selo feito pelos anões Dark Iron e procurado nos Ermos. Ele guarda a chave de uma prisão na Ravina Lethlor.",h="O Signo da Terra é um selo feito pelos anões Dark Iron e procurado nos Ermos.",kw={"fortaleza angor","ermos","blacklash","deathwing","garek","gorn","hematus","ravina lethlor","signo da terra","tho'grun"},ang={["class:Mage"]="Como mago, você talvez reconheça Krasus como um mestre do Kirin Tor. Ele enviou Garek aos Ermos para impedir que os problemas na Ravina Lethlor se agravem.",["faction:Horde"]="Como membro da Horda, o Signo lembra a antiga aliança com Deathwing durante a Segunda Guerra. Gorn o procura para libertar Blacklash e Hematus, embora queira que encontrem seu fim."},sec={{t="Um selo roubado",b="Garek, enviado aos Ermos por Krasus, do Kirin Tor, pede que você recupere o Signo da Terra. Ogros errantes o levaram e passam perto do Acampamento Barf. Os anões Dark Iron fizeram a marca na Fortaleza Angor, e ela mantém dois prisioneiros na Ravina Lethlor."},{t="A chave da prisão",b="Em Karrath, Gorn conta que a Horda já se aliou a Deathwing durante a Segunda Guerra. Tho'grun e seus ogros foram contratados para obter o Signo, mas Tho'grun traiu a Horda e ficou com ele. Com o selo de volta, Gorn pretende abrir a prisão dos dracos e libertá-los para que encontrem seu fim."}},faq={{q="O que é o Signo da Terra?",a="O Signo da Terra é um selo feito pelos anões Dark Iron na Fortaleza Angor. Ele mantém Blacklash e Hematus presos na Ravina Lethlor.",al={"signo da terra","selo da terra","o que é o signo"}},{q="Quem quer o Signo da Terra?",a="Garek, enviado por Krasus, do Kirin Tor, pede que você recupere o Signo. Gorn, em Karrath, também o procura para a Horda.",al={"quem precisa do signo","garek e o signo","gorn e o signo"}},{q="Quem roubou o Signo?",a="Um grupo de ogros errantes levou o Signo da Terra. Seu líder, Tho'grun, ficou com ele depois de trair a Horda.",al={"quem tem o signo","signo de tho'grun","ogros roubaram"}},{q="O que o Signo destranca?",a="O Signo da Terra é a chave da prisão que mantém os dracos negros Blacklash e Hematus na Ravina Lethlor.",al={"chave da prisão do signo","o que destranca","prisão dos dracos negros"}},{q="Onde posso encontrar o Signo?",a="Os ogros errantes às vezes passam pelo Acampamento Barf, nos Ermos, onde Tho'grun pode ser encontrado.",al={"local do signo","onde fica o signo da terra","signo no acampamento barf"}}},fp="17,118,13.251.0,16.281.1,30.130.0,32.115.0,19.112.1,26.112.0,26.100.0"}
P.entries["item:signed-recruitment-letter"] = {n="Carta de Recrutamento Assinada",s="A Carta de Recrutamento Assinada é um despacho oficial emitido por Kargal Chaga de Guerra no Posto Remoto. Com a marca de Kargal, ela transfere novos recrutas para o interior árido dos Sertões para se apresentarem ao serviço na Encruzilhada.",h="A Carta de Recrutamento Assinada é um despacho oficial emitido por Kargal Chaga de Guerra no Posto Remoto.",kw={"recrutamento","encruzilhada","posto remoto","kargal chaga de guerra","sergra espinhonegro","carta de recrutamento assinada","sertões","thrall"},ang={["class:Shaman"]="O documento coloca você a serviço de Sergra Espinhonegro, uma proeminente xamã orc incumbida por Thrall de ajudar a proteger os Sertões.",["faction:Horde"]="A carta de recrutamento representa a sua transição do serviço básico em Durotar para a estrutura militar mais ampla da fronteira da Horda."},sec={{t="A Transferência de um Recruta",b="Servindo como o limiar oriental dos Sertões, o Posto Remoto avalia os recém-chegados que atravessam o Rio Furiaustral vindos de Durotar. Uma vez que o recruta prove sua prontidão a Kargal Chaga de Guerra, ele carimba e assina esta Letter of Introduction. Ela serve como ordens militares direcionando os recrutas a oeste pela estrada até a Encruzilhada, onde Sergra Espinhonegro coordena operações logísticas e a defesa territorial pelas planícies secas."},{t="Tensão nos Postos Avançados",b="Embora a carta seja um documento oficial da Horda, Kargal não esconde seu desprezo pessoal pela oficial que aguarda o recruta. Ele vê Sergra Espinhonegro como uma xamã irritante que enrola os soldados com palavras, questionando abertamente a alta consideração que o Chefe de Guerra Thrall tem por ela. Apesar de suas ressalvas, o despacho deve ser entregue diretamente nas mãos de Sergra antes que novas tarefas na Encruzilhada sejam concedidas."}},faq={{q="Qual é o objetivo da Carta de Recrutamento Assinada?",a="A carta atua como um documento oficial de transferência militar. Ela prova a Sergra Espinhonegro na Encruzilhada que Kargal Chaga de Guerra avaliou você no Posto Remoto e considerou você apto para servir nos Sertões.",al={"o que esta carta faz","uso da carta de recrutamento","carta assinada sertões"}},{q="Quem assinou a carta?",a="Kargal Chaga de Guerra, um veterano orc encarregado do Posto Remoto na fronteira entre Durotar e os Sertões. Ele assina a carta depois que um recruta conclui seus deveres iniciais na fronteira.",al={"quem escreveu a carta","carta de kargal","quem assinou isto"}},{q="Para quem devo entregar a carta?",a="Você a entrega para Sergra Espinhonegro, uma influente xamã orc posicionada no cruzamento central da Encruzilhada.",al={"onde levo a carta","quem recebe a carta","destinatário da carta"}},{q="Por que Kargal fala mal de Sergra Espinhonegro?",a="Kargal considera Sergra uma oficial de língua afiada e difícil, que perde tempo falando quando há trabalho a ser feito. Embora o Chefe de Guerra Thrall a tenha em alta estima, Kargal continua cético quanto à liderança dela.",al={"rivalidade entre kargal e sergra","por que kargal odeia sergra"}}},fx={ea3ee62a={q="O que é a Carta de Recrutamento Assinada?",a="É um documento oficial de recrutamento da Horda entregue aos recrutas que chegam nos Sertões vindos de Durotar. Redigido e aprovado por Kargal Chaga de Guerra no Posto Remoto, ele serve como certificação formal de que você foi avaliado, alistado e enviado para ajudar o assentamento na Encruzilhada.",al={"o que é a carta de recrutamento assinada","carta de recrutamento","o que é esta carta"}},ea22ddb8={q="Por que Sergra Darkthorn quer a Carta de Recrutamento Assinada?",a="Sergra Darkthorn supervisiona as operações na Encruzilhada e depende de mão de obra para garantir os Sertões para a Horda. A carta confirma seu alistamento sob a autoridade de Kargal, provando que você está pronto para receber ordens, provar seu valor e lidar com o trabalho urgente e as ameaças que o assentamento enfrenta.",al={"por que sergra quer a carta","por que entregar a carta de recrutamento","quem precisa da carta de recrutamento"}}},fp="25,164,22.389.0,23.320.0,53.190.0,22.183.0,31.120.0,49.182.0"}
P.entries["item:silithid-egg-the-barrens"] = {n="Ovo de Silitídeo",s="Ovos de Silitídeo são a ninhada em desenvolvimento das criaturas insetoides que fazem ninhos no sul dos Sertões. Encontradas enterradas em montes de terra ao redor do Campo dos Gigantes, essas ninhadas são coletadas por pesquisadores da Horda que buscam descobrir as origens e a inteligência do enxame invasor.",h="Ovos de Silitídeo são a ninhada em desenvolvimento das criaturas insetoides que fazem ninhos no sul dos...",kw={"encruzilhada","garra de escavação","ovo tipo extra","campo dos gigantes","korran","montes","silithídeo","ovo de silitídeo","sertões"},ang={["faction:Horde"]="O surgimento de enxames de insetos inteligentes tão perto da Encruzilhada representa um perigo inquietante para as rotas comerciais e o território da Horda no centro de Kalimdor."},sec={{t="Um Enxame Misterioso",b="Na bacia árida do Campo dos Gigantes, seres bizarros semelhantes a insetos começaram a revirar a terra em montes imponentes. Nas profundezas desses ninhos estão seus ovos, enterrados sob o solo endurecido e vigiados por ninhadas territoriais. A Horda sabe surpreendentemente pouco sobre os silithídeos, mas batedores posicionados na Encruzilhada notaram sinais de comportamento coordenado e um intelecto misterioso que ultrapassa em muito o de feras selvagens comuns. Coletar ovos não chocados oferece aos estudiosos de Orgrimmar a melhor chance de analisar o ciclo de vida e a natureza dessa ameaça emergente."},{t="Escavação e Perigo",b="Alcançar os ovos requer vasculhar os montes de silithídeo com Garras de Escavação especializadas. Perturbar essas ninhadas é um trabalho perigoso; os silithídeos reagem ferozmente a invasões perto de seus berçários subterrâneos, atacando em massa qualquer um que ameace seus filhotes que ainda não nasceram. Para pesquisadores como o troll Korran, conseguir espécimes intactos e sem danos é crucial para a análise antes que o enxame se espalhe ainda mais por Kalimdor."}},faq={{q="O que são Ovos de Silitídeo?",a="São as ninhadas não chocadas dos silithídeos insetoides que nidificam dentro de montes de terra no sul dos Sertões, especialmente por todo o Campo dos Gigantes.",al={"ovo de silitídeo","o que é ovo de silitídeo","montes de silithídeo"}},{q="Quem quer a coleta desses ovos?",a="Korran, um pesquisador troll baseado na Encruzilhada, os coleta em nome de seus mestres em Orgrimmar para estudar a estranha biologia e o comportamento dos silithídeos.",al={"quem precisa de ovos","missão de korran","quem dá a missão ovo tipo extra"}},{q="Por que os silithídeos estão sendo estudados?",a="A Horda sabe muito pouco sobre os silithídeos. Korran observa que eles exibem sinais de inteligência e coordenação muito superiores aos de animais selvagens típicos, gerando preocupação entre os líderes da Horda sobre sua presença repentina nos Sertões.",al={"por que estudar silithídeos","ameaça dos silithídeos","silithídeos são inteligentes"}},{q="Como os ovos são coletados?",a="Eles devem ser cuidadosamente desenterrados dos montes de silithídeo usando uma Garra de Escavação adaptada, enquanto se repele o enxame agressivo que protege os ninhos.",al={"como pegar ovos","garra de escavação","coletar ovos de silitídeo"}}},fx={["04f05afd"]={q="De onde vêm os Ovos de Silitídeo?",a="Esses ovos são postos pelos estranhos silitídeos, semelhantes a insetos, nas profundezas de seus montes de terra nos Sertões Meridionais, particularmente por todo o Campo dos Gigantes. Os silitídeos enterram e protegem cuidadosamente suas ninhadas dentro desses enormes montes de terra, atacando ferozmente qualquer um que seja ousado o suficiente para perturbar os ninhos.",al={"origem do ovo de silitídeo","de onde vêm os ovos de silitídeo","quem pôs os ovos de silitídeo"}}},fp="12,168,18.405.0,21.294.0,23.125.0,31.142.0,35.191.0,26.96.0"}
P.entries["item:silixiz-s-tower-key"] = {n="Chave da Torre de Biela",s="Foreman Silixiz carrega a chave da torre da Empreendimentos S.A. perto do Charco de Lodo. Agentes da Shattered Hand devem furtá-la do bolso dele como parte de uma missão secreta de sabotagem.",h="Foreman Silixiz carrega a chave da torre da Empreendimentos S.A.",kw={"barrens","foreman silixiz","shattered hand","shenthul","silixiz","charco de lodo","chave da torre","empreendimentos s.a."},ang={["class:Rogue"]="Como ladino da Horda, obter a Chave da Torre de Biela é uma prova para ingressar nas fileiras da Shattered Hand. Isso exige habilidade para se esgueirar e furtar bolsos.",["faction:Horde"]="Como membro da Horda, você carrega um troféu ligado aos esforços contra a exploração e os experimentos químicos da Empreendimentos S.A. no norte de Barrens."},sec={{t="Um teste de sutileza",b="Ao norte do Charco de Lodo, a Empreendimentos S.A. mantém sua torre sob forte segurança. Grand Foreman Puzik Gallywix supervisiona o posto de vigia isolado, enquanto mercenários goblins patrulham o complexo. Do lado de fora, Foreman Silixiz carrega a chave da torre. Um agente da Shattered Hand vindo de Orgrimmar deve furtá-la e guardá-la. A força não resolve: o agente deve entrar sem ser visto e furtar o bolso de Silixiz, provando sua furtividade antes de subir aos níveis superiores tóxicos da torre."}},faq={{q="Onde encontro Foreman Silixiz?",a="Foreman Silixiz fica fora da torre da Empreendimentos S.A., diretamente ao norte do Charco de Lodo, no nordeste de Barrens.",al={"localização de silixiz","onde fica foreman silixiz","encontrar silixiz"}},{q="Posso obter a chave matando Foreman Silixiz?",a="Não. A chave não pode ser retirada do cadáver de Silixiz. Um agente deve furtar o bolso dele enquanto ele estiver vivo.",al={"saque da chave de silixiz","é possível matar silixiz","saquear chave de silixiz"}},{q="Quem exige esta chave?",a="Contatos da Shattered Hand dão a tarefa de entregar a chave a Shenthul, o treinador de ladinos em Orgrimmar.",al={"quem quer a chave","entregar chave de silixiz","missão da chave da torre de biela"}},{q="Para que serve a chave?",a="A chave comprova que um agente se infiltrou na torre da Empreendimentos S.A. perto do Charco de Lodo. Ela é entregue à Shattered Hand com a cabeça de Grand Foreman Puzik Gallywix e o Esconderijo da Mistura Adulterada do Zanzil.",al={"o que a chave de silixiz abre","finalidade da chave de silixiz","usar chave da torre"}}},fx={["163c94d7"]={q="O que é a Chave da Torre de Biela?",a="É uma chave mantida pelo capataz Silixiz do lado de fora da torre da Empreendimentos S.A. ao norte do Charco de Lodo. O agente é instruído a roubá-la e ficar com ela caso o contato da The Shattered Hand precise dela mais tarde.",al={"o que é a chave da torre de biela","chave de silixiz","chave da torre da empreendimentos sa"}}},fp="19,195,18.451.0,32.115.0,48.103.0,22.94.0,25.198.1"}
P.entries["item:silver-dawning-s-lockbox"] = {n="Baú do Aurora de Prata",s="O Baú do Aurora de Prata é um baú resistente que repousa nos destroços submersos da embarcação Aurora de Prata, na costa de Costa Negra. Ele contém os pertences pessoais e o diário de bordo do capitão caído da embarcação, perdido durante uma emboscada de murlocs costeiros.",h="O Baú do Aurora de Prata é um baú resistente que repousa nos destroços submersos da embarcação Aurora de...",kw={"auberdine","costa negra","gorbold manácero","baú","murloc","naufrágio","aurora de prata"},ang={["race:Dwarf"]="Gorbold Manácero assume a responsabilidade de garantir que os capitães caídos sejam honrados e que seus pertences sejam devolvidos aos seus companheiros sobreviventes.",["race:NightElf"]="O baú preserva os escritos finais e as relíquias de um capitão kaldorei que morreu defendendo sua embarcação bem perto da costa do norte de Kalimdor."},sec={{t="Restos Submersos",b="O navio Aurora de Prata estava a caminho, cruzando o mar em direção ao porto de Auberdine, quando o desastre aconteceu. Murlocs costeiros atacaram a embarcação, levando-a para as águas escuras ao norte do porto. O capitão pereceu no ataque, deixando os destroços submersos sob as ondas como um monumento sombrio reivindicado pelas criaturas. Dentro do casco inundado permanece o baú pessoal do capitão, contendo o diário de bordo do navio e seus pertences privados. Recuperar esses efeitos oferece uma medida final de paz aos membros sobreviventes da tripulação em terra."}},faq={{q="Onde está localizado o Baú do Aurora de Prata?",a="O baú fica dentro dos destroços submersos do Aurora de Prata, uma embarcação virada que repousa no fundo do oceano ao norte de Auberdine, na costa de Costa Negra.",al={"localização do baú","onde está o baú do aurora de prata","destroços do aurora de prata"}},{q="O que aconteceu com o Aurora de Prata?",a="Enquanto o Aurora de Prata navegava em direção a Auberdine pelo oceano, foi emboscado por murlocs locais. A embarcação foi superada, naufragou e afundou sob as ondas, ceifando a vida de seu capitão.",al={"por que o aurora de prata afundou","história do aurora de prata","como o navio naufragou"}},{q="O que há dentro do baú?",a="O baú contém os pertences pessoais e o diário de bordo mantido pelo capitão do Aurora de Prata, preservados contra as profundezas do oceano.",al={"conteúdo do aurora de prata","o que há no baú"}},{q="Quem está procurando pelo baú?",a="Gorbold Manácero, um Anão estacionado em Auberdine, pede a nadadores corajosos que mergulhem nos destroços e recuperem o baú para que a tripulação sobrevivente do capitão caído possa honrar adequadamente sua memória.",al={"quem quer o baú","quem dá a missão","entregar baú"}}},fx={["9cc39920"]={q="O que é o Baú do Aurora de Prata?",a="É o baú pessoal pertencente ao falecido capitão do Aurora de Prata. Quando o navio foi invadido e afundado por murlocs na costa norte de Costa Negra, o baú afundou com os destroços. Ele contém o diário do capitão e pertences pessoais sobreviventes, descansando nas profundezas subaquáticas em meio às criaturas que rondam o local.",al={"o que é o baú do aurora de prata","conhecimento sobre o baú aurora de prata","baú do capitão aurora de prata"}}},fp="24,179,15.344.0,46.130.0,36.149.0,27.76.0,27.167.0"}
P.entries["item:silvermane-stalker-flank"] = {n="Silvermane Stalker Flank",s="Silvermane Stalker Flanks são carne crua que Agnar Domaferas procura nas Terras Agrestes. Ele precisa delas para alimentar um filhote de Dardejante.",h="Silvermane Stalker Flanks são carne crua que Agnar Domaferas procura nas Terras Agrestes.",kw={"agnar domaferas","food for baby","terras agrestes","carne crua","silvermane stalker","silvermane stalker flank","dardejante"},sec={{t="A Primeira Refeição",b="Agnar Domaferas está se preparando para a eclosão do ovo e teme que o jovem Dardejante não sobreviva sem uma boa primeira refeição. Ele pede que você traga cinco Silvermane Stalker Flanks. A carne é para o filhote quando ele sair do ovo."}},faq={{q="Quem quer Silvermane Stalker Flanks?",a="Agnar Domaferas, nas Terras Agrestes, quer cinco Silvermane Stalker Flanks para alimentar um filhote de Dardejante.",al={"quem precisa dos flancos","carne de agnar","quem quer essa carne"}},{q="Para que servem os flancos?",a="Agnar planeja alimentar um Dardejante com a carne crua quando o ovo eclodir.",al={"por que a carne","comida para filhote de dardejante","para que serve esse flanco"}},{q="De quantos flancos Agnar precisa?",a="Agnar Domaferas pede que você traga cinco Silvermane Stalker Flanks.",al={"quantos pedaços","cinco flancos","quantidade de carne"}},{q="De onde vêm os Silvermane Stalker Flanks?",a="Silvermane Stalker Flanks vêm de Silvermane Stalkers nas Terras Agrestes.",al={"onde encontrar flancos","carne de silvermane stalker","origem dos silvermane stalker flanks"}},{q="O que um Dardejante come?",a="Dardejantes comem carne e vegetação. Agnar pede Silvermane Stalker Flanks crus como primeira refeição para o filhote.",al={"dieta do dardejante","o que os dardejantes comem","comida para filhote de dragão"}}},fp="24,129,12.235.0,36.106.0,24.73.0,32.65.0,45.75.0,30.124.0"}
P.entries["item:silvery-spinnerets"] = {n="Fiandeiras Prateadas",s="As Fiandeiras Prateadas são obtidas da grande aranha Lady Sathrah, no norte de Teldrassil. Outrora usadas para tecer teias que capturavam o orvalho curativo da noite para o Templo da Lua, elas são procuradas pelas Sacerdotisas de Elune para honrar a alma da criatura caída por meio de um ritual sagrado de renascimento.",h="As Fiandeiras Prateadas são obtidas da grande aranha Lady Sathrah, no norte de Teldrassil.",kw={"lady sathrah","sacerdotisa a'mura","sacrifício de sathrah","fiandeiras prateadas","tears of the moon","templo da lua","lago olho-d'água"},ang={["class:Priest"]="Para os servos de Elune, recuperar as fiandeiras não é um contrato de extermínio, mas um rito fúnebre sagrado destinado a pedir à Mãe Lua a redenção de uma criatura.",["race:NightElf"]="O fim trágico de Lady Sathrah é um lembrete sério para os Kaldorei de que até mesmo as criaturas amadas por Elune são vulneráveis à aflição rastejante que adoece Teldrassil."},sec={{t="Teias Sagradas e Corrupção",b="Lady Sathrah já foi contada entre as criaturas favorecidas de Elune, renomada por tecer teias reluzentes sob o luar perto do Lago Olho-d'Água. Sua seda prateada reunia a Mist da noite, formando orvalhos curativos valorizados pela Sisterhood of Elune em Darnassus. Infelizmente, a corrupção que se arrastava pelos galhos de Teldrassil não a poupou. Caindo em uma loucura violenta, Sathrah tornou-se um perigo para sua própria prole e para a floresta ao redor. A Sacerdotisa A'mura pede aos viajantes que ponham fim ao sofrimento da aranha e recuperem suas fiandeiras como um ato de misericórdia, trazendo um desfecho para uma reverenciada habitante dos grandes galhos."},{t="Um Sacrifício para o Renascimento",b="As fiandeiras recuperadas não são procuradas como um mero troféu ou material de criação. Em vez disso, a Sisterhood as oferece diretamente à Deusa da Lua na fonte central dentro do Templo da Lua. Por meio dessa consagração, conhecida como Sacrifício de Sathrah, as sacerdotisas rezam para que Elune receba o espírito da criatura, purifique a loucura que tomou seu corpo mortal e lhe conceda paz no renascimento."}},faq={{q="Onde você obtém as Fiandeiras Prateadas?",a="Elas são obtidas de Lady Sathrah, uma grande aranha encontrada ao longo das fronteiras do norte de Teldrassil, perto do Lago Olho-d'Água.",al={"onde encontrar fiandeiras prateadas","drop de fiandeiras prateadas","quem derruba fiandeiras prateadas"}},{q="Por que a Sacerdotisa A'mura quer as fiandeiras?",a="A Sacerdotisa A'mura busca oferecê-las a Elune como um sacrifício sagrado. Esse ritual honra a antiga pureza de Lady Sathrah e pede à deusa que purifique o espírito da fera e lhe conceda paz e renascimento.",al={"por que a'mura quer fiandeiras","propósito de tears of the moon"}},{q="Por que as teias de Lady Sathrah eram especiais?",a="Lady Sathrah tecia uma luminosa seda prateada que capturava a Mist da noite sob o luar. O orvalho colhido de suas teias possuía uma potente magia restauradora, que a Sisterhood of Elune armazenava no Templo da Lua para cura.",al={"teias de lady sathrah","o que lady sathrah fez"}},{q="Por que Lady Sathrah foi morta se ela era sagrada?",a="Ela caiu em uma loucura incurável junto com outras criaturas corrompidas da vida selvagem em Teldrassil. Sua agressividade colocou a floresta em perigo e ameaçou suas futuras ninhadas, levando as sacerdotisas a considerarem matá-la um triste ato de misericórdia.",al={"por que matar lady sathrah","por que sathrah enlouqueceu"}}},fx={["6e94bdc8"]={q="O que são as Fiandeiras Prateadas?",a="As Fiandeiras Prateadas são os órgãos produtores de seda retirados da aranha sagrada Lady Sathrah no norte de Teldrassil. Em tempos mais saudáveis, ela os usava para tecer fios de prata cintilantes através do luar. Essas teias capturavam a névoa noturna, produzindo um orvalho milagroso com potentes propriedades curativas valorizadas pelas Sacerdotisas de Eluna.",al={"o que são as fiandeiras prateadas","informações sobre as fiandeiras prateadas","fiandeiras de lady sathrah"}},["48fdca9c"]={q="De onde vêm as Fiandeiras Prateadas?",a="Elas são colhidas de Lady Sathrah, uma aranha gigante que habita perto do Lago Olho-d'Água ao longo das fronteiras norte de Teldrassil. Antes reverenciada como uma criatura graciosa e pura abençoada por Eluna, Sathrah sucumbiu recentemente à loucura, exigindo que os elfos noturnos terminassem com seu sofrimento e recuperassem seus restos mortais sagrados.",al={"origem das fiandeiras prateadas","quem criou as fiandeiras prateadas","onde conseguir as fiandeiras prateadas"}}},fp="18,177,29.453.0,23.332.1,40.123.0,47.192.0,37.213.0,46.220.0"}
P.entries["item:simple-memorandum"] = {n="Memorando Simples",s="O Memorando Simples é um aviso oficial entregue a guerreiros gnomos novatos que estão treinando no Vale Cristálgida. Uma diretiva gnômica concisa, ele instrui os iniciantes a se apresentarem ao treinador de guerreiros Thran Khorman em Sidermar para se prepararem para a guerra de retomada de Gnomeregan.",h="O Memorando Simples é um aviso oficial entregue a guerreiros gnomos novatos que estão treinando no Vale...",kw={"sidermar","vale cristálgida","dun morogh","gnomeregan","memorando simples","thran khorman","treinamento de guerreiro"},ang={["class:Warrior"]="Este bilhete representa o passo inicial de um guerreiro para sair das escaramuças rudimentares e entrar na instrução formal de combate sob o comando de Thran Khorman em Sidermar.",["race:Gnome"]="Para os gnomos exilados, o memorando é um lembrete de seu objetivo compartilhado: aprimorar habilidades de batalha ao lado de seus aliados anões a fim de se prepararem para a eventual libertação de Gnomeregan."},sec={{t="Uma Convocação para Sidermar",b="Aventureiros novatos no Vale Cristálgida frequentemente recebem cartas de apresentação à medida que demonstram sua coragem contra a fauna local e as ameaças dos troggs. Para os jovens combatentes gnomos, este memorando serve como uma ordem formal para se apresentarem a Thran Khorman, o treinador de guerreiros residente em Sidermar. Veteranos anões reconhecem que, embora os gnomos possam depender do intelecto e de engenhocas, retomar Gnomeregan exigirá pura determinação física e disciplina marcial. O memorando orienta o portador a deixar de lado tarefas preliminares e buscar instrução personalizada na arte da guerra."}},faq={{q="O que é o Memorando Simples?",a="É uma mensagem escrita entregue a guerreiros gnomos novatos que trabalham no Vale Cristálgida, ordenando que se apresentem ao treinador de guerreiros anão em Sidermar.",al={"memorando simples","o que é este bilhete","item memorando"}},{q="Quem escreveu o Memorando Simples?",a="Ele não possui assinatura. Sten Braçoforte supõe que veio de Thran Khorman, mas o texto fala em retomar nosso lar de Gnomeregan, portanto é uma diretiva gnômica ordenando que você se apresente a Thran, o treinador de guerreiros anão em Sidermar.",al={"quem escreveu o memorando","quem enviou o bilhete","autor do memorando simples"}},{q="O que acontece após ler o Memorando Simples?",a="Depois de ler o documento, você o leva até Thran Khorman dentro de Sidermar. Ele reconhece sua determinação para recuperar seu lar perdido e oferece treinamento em técnicas fundamentais de guerreiro.",al={"o que fazer com o memorando","onde levar","entregar memorando simples"}},{q="Por que um anão está treinando guerreiros gnomos?",a="Após a queda de Gnomeregan, refugiados gnomos se estabeleceram sob a hospitalidade de Altaforja e Sidermar. Veteranos anões como Thran Khorman comprometeram sua perícia marcial para ajudar seus aliados exilados a treinar e, por fim, retomar sua cidade irradiada.",al={"por que thran treina gnomos","anões treinando gnomos"}}},fx={b027c55a={q="Por que o Memorando Simples me foi entregue?",a="O memorando é uma diretriz gnômica ordenando que você se apresente a Thran Khorman, o instrutor de guerreiros anão dentro de Sidermar. Como um guerreiro gnomo deslocado, sua diretriz principal é se preparar para a guerra para recuperar Gnomeregan, e Thran deu sua palavra para ajudar a preparar você e seu povo para isso. Sten Braçoforte passou o bilhete adiante enquanto você o ajudava no Vale Cristálgida.",al={"por que memorando simples","objetivo do memorando simples","por que preciso do memorando simples"}}},fp="17,142,21.407.0,30.159.0,32.237.0,49.185.0,39.244.0"}
P.entries["item:simple-rune"] = {n="Runa Simples",s="Uma Simple Rune é um símbolo de pedra inscrito entregue a guerreiros anões novatos em treinamento no Vale Cristálgida. Ela serve como uma convocação do instrutor de guerreiros Thran Khorman, orientando os recrutas a buscarem instrução dentro de Sidermar.",h="Uma Simple Rune é um símbolo de pedra inscrito entregue a guerreiros anões novatos em treinamento no Vale...",kw={"sidermar","vale cristálgida","dun morogh","runa de anão","simple rune","thran khorman","treinamento de guerreiro"},ang={["class:Warrior"]="Para guerreiros anões, esta pedra inscrita marca o primeiro passo no treinamento militar formal sob a tutela do veterano instrutor Thran Khorman.",["race:Dwarf"]="A runa de Thran Khorman promete a um jovem anão o básico da luta: a empunhadura de um machado, o peso da armadura e o suor da verdadeira batalha."},sec={{t="Um Chamado às Armas",b="Esculpida com marcas marciais básicas, a Simple Rune é entregue a recrutas promissores que começaram a eliminar as ameaças ao redor do Vale Cristálgida. Em vez de um amuleto mágico, ela atua como uma pedra de convocação formal de Thran Khorman, o instrutor de guerreiros residente em Sidermar. Ao ler as orientações inscritas nela, espera-se que um jovem combatente se apresente diretamente a Thran para aprender técnicas básicas de combate e ouvir conselhos práticos sobre como sobreviver às terras selvagens e hostis de Dun Morogh."}},faq={{q="Qual é o propósito da Simple Rune?",a="A Simple Rune é uma tabuleta de instruções dada a guerreiros novatos no Vale Cristálgida. Lê-la orienta o recruta a se apresentar a Thran Khorman dentro de Sidermar para treinamento formal.",al={"uso de simple rune","o que a runa faz","item de missão simple rune"}},{q="Quem envia a Simple Rune?",a="Ela é enviada por Thran Khorman, o instrutor de guerreiros anão estabelecido dentro de Sidermar, que observa combatentes promissores ajudando nos arredores do vale.",al={"quem escreveu a runa","quem me deu a simple rune","remetente da runa"}},{q="Para onde levo a Simple Rune?",a="Leve-a para Thran Khorman dentro do salão da grande forja de Sidermar, localizado no centro do Vale Cristálgida.",al={"para onde eu vou","entrega da runa","localização de thran khorman"}}},fx={["0f0eb9fb"]={q="O que é a Simple Rune?",a="A Simple Rune é uma pedra anã inscrita entregue a guerreiros promissores em Vale Cristálgida. Em vez de conter encantamentos místicos, ela funciona como uma convocação escrita de Thran Khorman, chamando combatentes novatos para se apresentarem a ele em Sidermar para começar seu treinamento marcial formal.",al={"o que é a simple rune","conhecimento sobre a simple rune","item simple rune"}},["2d1fc984"]={q="Por que Thran Khorman quer que você tenha a Simple Rune?",a="Thran Khorman envia a runa para recrutá-lo para a instrução formal de guerreiro. Vendo potencial em seus primeiros feitos ao redor de Vale Cristálgida, ele quer fundamentá-lo na disciplina marcial anã adequada e ensinar-lhe o que é realmente necessário para lutar por Altaforja em meio às ameaças locais crescentes.",al={"por que thran envia a runa","por que preciso da simple rune","por que querer a simple rune"}}},fp="11,120,17.305.0,39.169.0,26.137.0,32.83.0"}
P.entries["item:simple-sigil"] = {n="Selo Simples",s="O selo simples é um modesto símbolo de treinamento entregue a guerreiros elfos noturnos novatos em Umbravale. Carregado como uma convocação da instrutora de guerreiros Alyissia, ele marca a introdução formal de um jovem combatente na defesa marcial de Teldrassil.",h="O selo simples é um modesto símbolo de treinamento entregue a guerreiros elfos noturnos novatos em Umbravale.",kw={"alyissia","ilthalaine","guerreiro kaldorei","umbravale","o selo simples","teldrassil","treinamento de guerreiro"},ang={["class:Warrior"]="Para guerreiros kaldorei, este emblema simples é a sua primeira credencial, apresentando você às tradições marciais necessárias para proteger Teldrassil.",["race:NightElf"]="O selo ressalta a urgência enfrentada pelos kaldorei, enquanto instrutores como Alyissia recrutam quaisquer mãos capazes para conter a crescente corrupção sob os galhos da Árvore do Mundo."},sec={{t="Uma Convocação às Armas",b="Sob os galhos abrigados de Umbravale, jovens elfos noturnos são guiados pelo Conservador Ilthalaine para encontrar sua vocação. Para os guerreiros iniciantes, Ilthalaine entrega O selo simples enviado por um mensageiro da instrutora de guerreiros Alyissia. Portando uma inscrição que orienta o recruta a se apresentar para instrução, este emblema representa o início de um treinamento marcial disciplinado em tempos conturbados para a Árvore do Mundo."},{t="O Fardo da Defesa",b="Quando levado a Alyissia, o selo abre um diálogo sobre a situação premente dos kaldorei. O crescimento recente de Teldrassil, a corrupção rastejante que contamina as feras da floresta e a redescoberta de terras distantes como Feralas sobrecarregaram os protetores elfos noturnos. O selo não é um artefato de poder, mas uma credencial prática que acolhe o recruta nas fileiras de guardiões encarregados de proteger seu povo de ameaças emergentes."}},faq={{q="O que é O selo simples?",a="É um emblema introdutório com inscrições entregue a guerreiros elfos noturnos novatos pelo Conservador Ilthalaine em Umbravale. Ele instrui o portador a se apresentar a Alyissia para o treinamento formal de guerreiro.",al={"item o selo simples","o que o selo simples faz","o que é este selo"}},{q="Quem envia O selo simples?",a="O selo é despachado por um mensageiro a mando de Alyissia, a instrutora de guerreiros residente em Umbravale, que deseja iniciar o treinamento de novos guerreiros na defesa de Teldrassil.",al={"quem fez o selo","quem enviou o selo simples"}},{q="O que devo fazer com ele?",a="Leia o texto inscrito e entregue-o a Alyissia perto da base de Aldrassil em Umbravale para iniciar sua instrução de guerreiro.",al={"onde entregar o selo simples","quem recebe o selo simples"}},{q="O selo concede alguma habilidade especial?",a="Não. É apenas um aviso por escrito e uma credencial destinada a apresentar aspirantes a guerreiros ao seu mentor.",al={"poderes do selo","atributos do selo simples"}}},fp="12,138,17.341.0,21.366.0,25.193.0,27.150.0,25.131.0,43.91.0"}
P.entries["item:simple-tablet"] = {n="Tabuleta Simples",s="A Tabuleta Simples é uma missiva escrita entregue a guerreiros trolls novatos que chegam ao Vale das Provações. Entregue por Gornek, ela orienta o combatente iniciante a se apresentar a Frang, o instrutor de guerreiros local.",h="A Tabuleta Simples é uma missiva escrita entregue a guerreiros trolls novatos que chegam ao Vale das...",kw={"lançanegra","durotar","frang","gornek","tabuleta simples","o covil","vale das provações","instrutor de guerreiros"},ang={["class:Warrior"]="A tabuleta marca a apresentação formal de um guerreiro troll a Frang, iniciando sua instrução de combate dentro da Horda.",["race:Troll"]="Para os Trolls Lançanegra que conquistam seu espaço ao lado dos orcs em Durotar, receber a convocação significa seu dever de reforçar as fileiras da linha de frente."},sec={{t="Uma Convocação para a Batalha",b="Dentro dos limites vermelhos e áridos do Vale das Provações, novos recrutas são rapidamente postos para trabalhar. Para jovens trolls que buscam o caminho do guerreiro, Gornek entrega esta simples placa ou pergaminho. Escrita pelo troll Tar'sere e endereçada a Frang, o mestre de armas que descansa perto de O Covil, ela serve como uma introdução oficial ao treinamento marcial em Durotar. Ela exorta o recruta a dar um passo à frente, apresentar-se e provar sua disposição de empunhar armas sob o estandarte da Horda."}},faq={{q="O que é a Tabuleta Simples?",a="É uma mensagem escrita introdutória entregue por Gornek a aspirantes a guerreiros trolls no Vale das Provações. Ela os instrui a lê-la e procurar Frang para receber treinamento profissional de combate.",al={"tabuleta simples","o que é esta tabuleta","tabuleta de guerreiro troll"}},{q="Quem envia a tabuleta?",a="A mensagem é assinada pelo troll Tar'sere, que envia o recruta a Frang, o instrutor de guerreiros posicionado do lado de fora de O Covil no Vale das Provações.",al={"quem enviou a tabuleta simples","quem escreveu a tabuleta","remetente da tabuleta"}},{q="Onde levo a tabuleta?",a="Leve-a para Frang, que pode ser encontrado descansando na sombra do lado de fora da entrada de O Covil no Vale das Provações.",al={"a quem entrego a tabuleta simples","onde levar a tabuleta","localização de frang"}},{q="Quem recebe esta tabuleta?",a="A Tabuleta Simples é fornecida especificamente a guerreiros trolls que estão iniciando seus ritos de passagem no Vale das Provações.",al={"qualquer um pode pegar a tabuleta simples","qual classe recebe a tabuleta simples"}}},fx={["219776b3"]={q="Por que Frang envia a Tabuleta Simples a você?",a="Na verdade, Frang não a escreve. Gornek supõe que ela veio de Frang, mas a tabuleta é assinada pelo troll Tar'sere, que encaminha você a Frang, do lado de fora do Den. Frang precisa de guerreiros trolls astutos para mostrar aos orcs como lutar com mais do que músculos, e ele pode treinar você para as batalhas da Horda que virão.",al={"por que tabuleta simples","por que frang me procura","finalidade da tabuleta simples"}}},fp="13,85,19.269.0,26.116.0,21.121.0,27.83.0,25.98.0"}
P.entries["item:singed-scale"] = {n="Escama Chamuscada",s="As Escamas Chamuscadas são placas carbonizadas e endurecidas por choques, retiradas dos lagartos-trovão eletrificados de Durotar. Conseguir essas escamas serve como um rito de passagem para jovens guerreiros da Horda que buscam dominar as artes marciais defensivas.",h="As Escamas Chamuscadas são placas carbonizadas e endurecidas por choques, retiradas dos lagartos-trovão...",kw={"posto remoto","pele-de-relâmpago","caminho da defesa","escama chamuscada","lagarto-trovão","desfiladeiro do trovão","uzzek"},ang={["class:Warrior"]="Para um guerreiro em desenvolvimento, levar essas escamas até Uzzek marca um passo fundamental no domínio da disciplina de proteção e no aprendizado para se tornar um escudo impenetrável para a Horda.",["faction:Horde"]="As provações realizadas no Posto Remoto garantem que os guardas e vanguardas que protegem as fronteiras de Durotar e dos Sertões possuam um vigor inabalável."},sec={{t="Um Teste de resistência",b="Para os veteranos da Horda, um verdadeiro guerreiro não é medido apenas pelo sangue derramado por seu machado, mas pelos golpes que consegue absorver para proteger seus aliados. No cânion árido de Desfiladeiro do Trovão, no oeste de Durotar, peles-de-relâmpago e lagartos-trovão crepitam com energias tempestuosas voláteis. Caçar essas feras exige que o guerreiro suporte choques elétricos incessantes e ataques físicos esmagadores. As escamas enegrecidas e queimadas arrancadas de seus couros oferecem uma prova incontestável da capacidade de um combatente de resistir a agressões punitivas e permanecer firme onde soldados inferiores cairiam."},{t="O Caminho do Escudo",b="No Posto Remoto, na fronteira entre Durotar e os Sertões, o guerreiro veterano Uzzek exige cinco dessas escamas dos iniciados antes de compartilhar seu conhecimento. Aos olhos de Uzzek, um iniciado deve possuir uma resistência física inerente antes de conseguir compreender a sutil disciplina das posturas e da defesa tática. Apresentar as escamas demonstra que o guerreiro tem a fortitude necessária para combinar pele grossa, armadura pesada e um jogo de pernas calculado em uma muralha inflexível contra os inimigos da Horda."}},faq={{q="Para que servem as escamas chamuscadas?",a="As escamas chamuscadas servem como prova de resistência marcial. O instrutor de guerreiros Uzzek exige cinco delas para comprovar que um iniciado possui a robustez física necessária para aprender técnicas defensivas avançadas.",al={"uso da escama chamuscada","quem quer escamas chamuscadas","missão da escama chamuscada"}},{q="Onde você encontra escamas chamuscadas?",a="Elas são obtidas de lagartos-trovão e peles-de-relâmpago que habitam o Desfiladeiro do Trovão, um cânion no oeste de Durotar situado logo do outro lado do rio que faz divisa com os Sertões.",al={"localização da escama chamuscada","onde encontrar escamas chamuscadas","como conseguir escama chamuscada"}},{q="Por que as escamas estão chamuscadas?",a="Os lagartos-trovão canalizam naturalmente relâmpagos e tempestades elétricas através de seus corpos. O crepitar contínuo de energia elemental queima e enegrece sua couraça externa, conferindo às escamas uma textura carbonizada.",al={"por que chamuscada","por que as escamas estão queimadas"}},{q="Quem é Uzzek e por que ele se importa com essas escamas?",a="Uzzek é um guerreiro veterano alocado no Posto Remoto, no leste dos Sertões. Ele treina novos guerreiros da Horda em combate defensivo, mas exige que primeiro provem sua pura resiliência contra feras mortais antes de aceitar instruí-los.",al={"quem é uzzek","uzzek"}}},fx={c263d0cb={q="O que é uma Escama Chamuscada?",a="Uma Escama Chamuscada é uma escama reptiliana resistente retirada dos ferozes lagartos-do-trovão e couros-relâmpago que habitam o Desfiladeiro do Trovão. Estalando constantemente com energia elétrica natural, essas criaturas possuem placas enegrecidas e marcadas por suas próprias descargas violentas de relâmpagos, deixando para trás armaduras carbonizadas, porém notavelmente resistentes.",al={"o que é uma escama chamuscada","conhecimento sobre a escama chamuscada","informações sobre escamas chamuscadas"}}},fp="12,138,19.371.0,21.395.0,32.137.0,32.142.0,26.201.0,53.197.0"}
P.entries["item:singed-scroll-fragment"] = {n="Singed Scroll Fragment",s="O Singed Scroll Fragment é uma das três partes de um pergaminho destruído que Theldurin, o Perdido, procura. Recuperá-lo pode ajudar a se proteger de Myzrael.",h="O Singed Scroll Fragment é uma das três partes de um pergaminho destruído que Theldurin, o Perdido, procura.",kw={"ermos","crumpled scroll fragment","enraged rock elemental","myzrael","pergaminho de myzrael","singed scroll fragment","theldurin, o perdido","torn scroll fragment"},sec={{t="Um pedaço chamuscado",b="Enraged Rock Elementals nas colinas atrás de Theldurin, o Perdido, carregam o Singed Scroll Fragment. Ele o procura junto com outras duas partes do Pergaminho de Myzrael, na esperança de reuni-las novamente."}},faq={{q="O que é o Singed Scroll Fragment?",a="É um dos três fragmentos do Pergaminho de Myzrael destruído.",al={"fragmento chamuscado","pedaço chamuscado de pergaminho"}},{q="De onde vem o fragmento?",a="Enraged Rock Elementals nas colinas atrás de Theldurin, o Perdido, carregam o fragmento.",al={"onde encontrar o fragmento chamuscado","localização do fragmento chamuscado"}},{q="Quem quer o fragmento?",a="Theldurin, o Perdido, pede o fragmento junto com o Torn Scroll Fragment e o Crumpled Scroll Fragment.",al={"quem precisa do fragmento chamuscado","fragmento de theldurin"}},{q="Por que Theldurin quer os fragmentos?",a="Ele espera reuni-los para que o Pergaminho de Myzrael possa ser usado contra Myzrael.",al={"por que coletar fragmentos","por que o pergaminho de myzrael"}}},fp="22,146,16.198.0,35.66.0,34.72.0,23.99.0,38.79.0"}
P.entries["item:singing-blue-crystal"] = {n="Singing Blue Crystal",s="Os Singing Blue Crystals são extraídos pelos Empreendimentos S.A. nas colinas ao redor da Mina Veia de Cristal. Cranque Mirrabolha, em Angra do Butim, quer usá-los como prova de que os goblins estão perdendo terreno.",h="Os Singing Blue Crystals são extraídos pelos Empreendimentos S.A.",kw={"basiliscos","angra do butim","cranque mirrabolha","mina veia de cristal","singing blue crystal","cristais cantantes","selva do espinhaço","empreendimentos s.a."},sec={{t="Cristais nas colinas",b="Perto da Mina Veia de Cristal, equipes dos Empreendimentos S.A. extraem Singing Blue Crystals das colinas ao redor. Eles pretendiam trabalhar dentro da mina, mas os basiliscos os expulsaram. Cranque Mirrabolha, em Angra do Butim, pede que você traga cristais retirados dos mineradores da empresa. Ele diz que a retirada deles abriria mais espaço para o comércio honesto na Selva do Espinhaço."}},faq={{q="O que são Singing Blue Crystals?",a="São cristais extraídos pelos Empreendimentos S.A. nas colinas ao redor da Mina Veia de Cristal.",al={"cristais cantantes","cristal azul","o que são esses cristais"}},{q="Onde os Empreendimentos S.A. extraem esses cristais?",a="Os Empreendimentos S.A. extraem Singing Blue Crystals nas colinas ao redor da Mina Veia de Cristal, na Selva do Espinhaço.",al={"onde ficam os cristais","localização dos cristais","onde os empreendimentos s.a. mineram"}},{q="Por que eles não estão minerando dentro da Mina Veia de Cristal?",a="Os basiliscos da Mina Veia de Cristal expulsaram os Empreendimentos S.A., então suas equipes extraem cristais nas colinas ao redor.",al={"por que não dentro da mina","mina dos basiliscos","basiliscos da mina veia de cristal"}},{q="Quem quer os cristais?",a="Cranque Mirrabolha, em Angra do Butim, quer Singing Blue Crystals como prova de que os Empreendimentos S.A. estão perdendo terreno.",al={"quem precisa de cristais cantantes","cristais para cranque mirrabolha","cristais para cranque"}},{q="O que os Empreendimentos S.A. querem fazer com os cristais?",a="Os Empreendimentos S.A. planejavam extrair Singing Blue Crystals da Mina Veia de Cristal, mas passaram a buscá-los nas colinas depois que os basiliscos os expulsaram.",al={"por que minerar cristais","cristais dos empreendimentos s.a.","o que os goblins estão escavando"}}},fp="20,177,21.344.0,31.84.0,41.113.0,47.109.0,23.108.0,53.137.0"}
P.entries["item:singing-crystal-shard"] = {n="Singing Crystal Shard",s="Fragmentos de Singing Crystal são cristais azuis valiosos encontrados na Selva do Espinhaço. Os basiliscos de lá comem os cristais, endurecendo a própria pele.",h="Fragmentos de Singing Crystal são cristais azuis valiosos encontrados na Selva do Espinhaço.",kw={"basilisco","fragmentos azuis","cranque mirrabolha","singing crystal shard","singing crystals","selva do espinhaço","empreendimentos s.a."},sec={{t="Cristal e escamas",b="Na Selva do Espinhaço, os basiliscos comem Singing Crystals, que endurecem a pele deles. Às vezes, é possível coletar um fragmento deles. Cranque Mirrabolha diz que os cristais só existem na Selva do Espinhaço e são valiosos para certos grupos. Os Empreendimentos S.A. dificultam a coleta para ele."}},faq={{q="O que são Singing Crystal Shards?",a="Singing Crystal Shards são fragmentos de cristais encontrados na Selva do Espinhaço. Os basiliscos comem os cristais, que endurecem a pele deles.",al={"singing shards","fragmentos de cristal azul"}},{q="Por que os basiliscos têm a pele endurecida?",a="Os basiliscos da Selva do Espinhaço comem Singing Crystals, que endurecem a pele deles.",al={"pele dura de basilisco","por que os basiliscos são resistentes"}},{q="Onde posso encontrar os fragmentos?",a="É possível coletar Singing Crystal Shards de basiliscos na Selva do Espinhaço.",al={"localização dos fragmentos","onde ficam os singing crystals"}},{q="Por que Cranque Mirrabolha os quer?",a="Cranque Mirrabolha diz que os cristais são valiosos para certos grupos e que pode revendê-los com lucro.",al={"crank quer fragmentos","do que crank precisa"}},{q="O que os Empreendimentos S.A. têm a ver com os cristais?",a="Os Empreendimentos S.A. dificultam a coleta dos cristais para Cranque Mirrabolha.",al={"cristais dos empreendimentos s.a.","por que os empreendimentos s.a."}}},fp="21,134,17.294.0,32.127.0,36.89.0,28.77.0,35.101.0,59.82.0"}
P.entries["item:skeleton-finger"] = {n="Dedo Descarnado",s="Um dígito ósseo decepado, retirado dos mortos-vivos que vagam pelos bosques amaldiçoados e cemitérios da Floresta do Crepúsculo. Madame Eva de Vila Sombria coleta esses restos macabros junto com presas de cararniço e veneno de aranha para criar talismãs de proteção.",h="Um dígito ósseo decepado, retirado dos mortos-vivos que vagam pelos bosques amaldiçoados e cemitérios da...",kw={"vila sombria","floresta do crepúsculo","presa de carniçal","madame eva","skeletal raider","dedo descarnado","totem do castigo"},ang={["class:Mage"]="Magos que estudam adivinhação popular acharão o método de Madame Eva de transformar dígitos esqueléticos e venenos naturais em um encantamento retaliatório uma mistura incomum de bruxaria empírica e magia simpática.",["class:Paladin"]="Paladinos podem estremecer ao profanar restos esqueléticos e carregar suas partes decepadas, mas, na penumbra sombria da Floresta do Crepúsculo, reaproveitar os ossos do profano para proteger os vivos é uma necessidade sombria."},sec={{t="Ossos dos Inquietos",b="Os bosques amaldiçoados da Floresta do Crepúsculo estão infestados pelos restos inquietos dos mortos, desde invasores e guerreiros esqueléticos até magos e demônios necróticos. Enquanto viajantes comuns evitam tocar nos restos imundos dos mortos ressuscitados, adivinhos e místicos valorizam sua essência gélida. Madame Eva, a vidente residente de Vila Sombria, reúne esses dedos ósseos para vincular suas energias necróticas residuais em uma proteção de magia retaliatória conhecida como o Totem do Castigo."}},faq={{q="Quais criaturas concedem um Dedo Descarnado?",a="Os Dedos Descarnados são obtidos dos vários mortos-vivos esqueléticos encontrados pela Floresta do Crepúsculo, incluindo Skeletal Raiders, Healers, Warders, Warriors, Horrors, Fiends e Skeletal Mages.",al={"onde encontrar dedos descarnados","o que concede dedos descarnados","origem do dedo descarnado"}},{q="Quem quer Dedos Descarnados na Floresta do Crepúsculo?",a="Madame Eva, a adivinha que reside em Vila Sombria, precisa deles como parte dos componentes rituais necessários para encantar uma proteção.",al={"quem precisa de dedos descarnados","doador da missão do dedo descarnado","para que servem dedos descarnados"}},{q="O que é o Totem do Castigo?",a="É uma proteção encantada criada por Madame Eva usando dedos descarnados, presas de cararniço e veneno de aranha. Ela entrelaça as energias sombrias desses itens em uma aura projetada para infligir dano retaliatório a qualquer um que tente usar de violência contra o portador.",al={"utilidade do totem do castigo","o que madame eva faz"}},{q="Por que Madame Eva precisa de restos de mortos-vivos para um amuleto de proteção?",a="Os rituais de Madame Eva canalizam a mácula e a agressividade latentes que residem nos monstros locais. Ao vincular as essências violentas dos esqueletos, cararniços e feras venenosas da Floresta do Crepúsculo, ela transforma a própria malícia residual dessas criaturas em uma proteção que pune invasores hostis.",al={"por que magia de ossos","por que dedos descarnados para o totem"}}},fx={["7c732e26"]={q="O que é um Dedo Descarnado?",a="Um Dedo Descarnado é o fragmento ósseo decepado e ressecado retirado de um dos horrores esqueléticos animados que vagam pelas florestas devastadas e criptas da Floresta do Crepúsculo. Preservados pela mácula necromântica que tomou conta da região, esses dedos retêm vestígios da magia sombria que mantém os mortos-vivos inquietos e em movimento.",al={"o que é um dedo descarnado","o que são dedos descarnados","identificar dedo descarnado"}},a7de6990={q="De onde vem um Dedo Descarnado?",a="Estes dedos vêm dos restos esqueléticos erguidos por todos os cemitérios e ruínas assombrados da Floresta do Crepúsculo. Em vez de serem fabricados ou manufaturados, são colhidos diretamente dos cadáveres animados — como guerreiros, seres vis, guardiões e saqueadores esqueléticos — que rastejam pela escuridão, animados pela mancha misteriosa e rastejante que corrompe a floresta.",al={"origem do dedo descarnado","de onde vêm os dedos descarnados","quem criou o dedo descarnado"}}},fp="15,157,21.373.0,38.125.0,39.84.0,32.179.0,63.206.0"}
P.entries["item:skeleton-key-mold"] = {n="Skeleton Key Mold",s="O Skeleton Key Mold molda uma haste de chave de tório e osso na lava do Pico Penacho de Fogo. O Boticário Trépido precisa da chave inacabada para combater o Flagelo em Andorhal.",h="O Skeleton Key Mold molda uma haste de chave de tório e osso na lava do Pico Penacho de Fogo.",kw={"andorhal","boticário trépido","pico penacho de fogo","flagelo","chave-mestra","skeleton key mold","tório","cratera un’goro","chave-mestra inacabada"},ang={["faction:Horde"]="Trépido pede sua ajuda para combater o Flagelo, cujo poder mantém Andorhal sob seu domínio.",["profession:Mining"]="É preciso tório para forjar a haste da chave, mas Trépido deixa que você consiga o material."},sec={{t="Um molde para a chave",b="O Boticário Trépido fornece o Skeleton Key Mold para o trabalho no Pico Penacho de Fogo, na Cratera Un’Goro. Com duas Thorium Bars, você pode usar o molde ao lado do lago de lava para fundir tório e osso em uma haste de chave inacabada. Trépido diz que o calor da lava fará a forja, mas o tório precisa ser fornecido à parte."}},faq={{q="Para que serve o Skeleton Key Mold?",a="O Skeleton Key Mold molda uma haste de chave de tório e osso na lava do Pico Penacho de Fogo.",al={"finalidade do molde de chave-mestra","o que o molde faz"}},{q="Quem me dá o molde?",a="O Boticário Trépido fornece o Skeleton Key Mold para o trabalho no Pico Penacho de Fogo.",al={"onde conseguir o molde de chave-mestra","molde de trépido"}},{q="Do que preciso junto com o molde?",a="São necessárias duas Thorium Bars junto com o Skeleton Key Mold para forjar a haste de chave inacabada.",al={"ingredientes do molde","barras de tório para a chave"}},{q="Onde o molde é usado?",a="Use o Skeleton Key Mold ao lado do lago de lava no topo do Pico Penacho de Fogo, na Cratera Un’Goro.",al={"onde usar o molde de chave-mestra","lava do pico penacho de fogo"}},{q="Por que Trépido está fazendo uma chave-mestra?",a="Trépido está preparando a chave como parte do esforço para atacar o Flagelo em Andorhal.",al={"chave para andorhal","por que fazer uma chave-mestra"}}},fp="17,177,18.318.0,34.89.0,22.83.0,29.88.0,23.96.0,37.88.0"}
P.entries["item:skin-of-sweet-rum"] = {n="Odre de Rum Doce",s="Um Odre de Rum Doce é uma bebida especializada obtida na Estalagem do Leão Orgulhoso em Vila d'Ouro. Ele é procurado pelo Taberneiro Daniel em Vila Plácida, que está desesperado para manter sua taverna abastecida enquanto os orcs Rocha Negra isolam Cristarrubra das rotas comerciais regulares.",h="Um Odre de Rum Doce é uma bebida especializada obtida na Estalagem do Leão Orgulhoso em Vila d'Ouro.",kw={"taberneiro daniel","tempos de seca","vila d'ouro","vila plácida","estalagem do leão orgulhoso","odre de rum doce","rum doce"},ang={["faction:Alliance"]="Obter esse rum evidencia a tensão logística que a invasão dos orcs Rocha Negra impôs aos pequenos povoados que defendem as fronteiras orientais do reino de Ventobravo."},sec={{t="Um Conforto Raro para Vila Plácida",b="Na cidade de Vila Plácida, desgastada pela guerra, os suprimentos da taverna estão perigosamente escassos. A invasão dos orcs Rocha Negra bloqueou as rotas de abastecimento que levam às Montanhas Cristarrubra, deixando o Taberneiro Daniel em apuros para saciar a sede dos guardas e refugiados sitiados da cidade. Para reabastecer suas prateleiras vazias, Daniel envia viajantes pelo reino afora para coletar especialidades regionais, incluindo um cantil repleto do distinto rum doce produzido e servido na Estalagem do Leão Orgulhoso de Vila d'Ouro."}},faq={{q="Onde posso encontrar um Odre de Rum Doce?",a="Um Odre de Rum Doce pode ser comprado diretamente com o estalajadeiro ou taberneiro na Estalagem do Leão Orgulhoso em Vila d'Ouro, localizado na Floresta de Elwynn.",al={"localização do rum doce","onde comprar rum doce","quem vende rum doce"}},{q="Quem quer este rum?",a="O Taberneiro Daniel, proprietário da taverna de Vila Plácida, pede um odre de Rum Doce junto com várias outras bebidas regionais para reabastecer seu estoque esgotado durante a missão Tempos de seca.",al={"quem precisa de rum doce","entregar rum doce","missão do rum doce"}},{q="Por que a bebida está acabando em Vila Plácida?",a="A repentina escalada da invasão dos orcs Rocha Negra em Cristarrubra cortou as linhas comerciais e atrasou os carregamentos para a cidade. Com as carroças mercantes comuns incapazes de percorrer as estradas com segurança, os estoques locais estão quase vazios.",al={"por que estão sem bebida","por que vila plácida está seca","motivo de tempos de seca"}},{q="Que outras bebidas são necessárias além do rum?",a="Além do Odre de Rum Doce de Vila d'Ouro, o Taberneiro Daniel também precisa de um barril de Cerveja Cervaforte de Cerro Oeste, um Barril de Vinho Merlot de Ventobravo e uma Garrafa de Pinga de Vila Sombria.",al={"bebidas de tempos de seca","lista de bebidas do daniel","outras bebidas necessárias"}}},fx={efbd5e13={q="O que é um Odre de Rum Doce?",a="Um Odre de Rum Doce é um odre de couro cheio de licor açucarado vendido em Vila d'Ouro, na Floresta de Elwynn. É uma das várias bebidas espirituosas regionais especiais valorizadas nos reinos humanos do sul de Azeroth.",al={"o que é rum doce","informações sobre o odre de rum doce","rum doce"}}},fp="17,123,28.311.0,37.117.0,19.140.0,39.152.0,48.148.0"}
P.entries["item:skittering-blood"] = {n="Sangue de Pateante",s="O Sangue de Pateante é um reagente alquímico colhido dos aracnídeos que habitam a Penumbra Furtiva da Floresta de Pinhaprata. Ele serve como um ingrediente tóxico vital para as pesquisas da Real Sociedade de Boticários sobre a New Plague, projetada para erradicar tanto o Flagelo quanto a humanidade.",h="O Sangue de Pateante é um reagente alquímico colhido dos aracnídeos que habitam a Penumbra Furtiva da...",kw={"faranello","the new plague","renferrel","real sociedade de boticários","floresta de pinhaprata","sangue de pateante","penumbra furtiva","skitterweb"},ang={["faction:Horde"]="Os boticários Renegados acolhem a matéria-prima para proteger Lordaeron, lutando sua guerra contra o Flagelo com armas de sua própria autoria.",["race:Undead"]="Contribuir com Sangue de Pateante ajuda diretamente a Rainha Sylvanas e a Real Sociedade de Boticários a criarem a arma biológica definitiva contra Arthas e a humanidade viva."},sec={{t="Um Destilado Tóxico",b="Colhida de Skitterweb lurkers, strikers e de sua matriarca Krethis the Shadowspinner, esta hemolinfa venenosa possui propriedades virulentas estimadas pelos alquimistas Renegados. O Boticário Renferrel descobriu que, quando refinado junto com toxinas extraídas de corações de urso grisalhos, o sangue forma a base de um elixir excepcionalmente letal. Os compostos presentes no fluido revelam agentes contaminantes severos, tornando-o um catalisador biológico ideal para os experimentos químicos do Boticarium."},{t="Abastecendo The New Plague",b="Sob a direção do Mestre-boticário Faranello na Cidade Baixa, a Real Sociedade de Boticários reúne reagentes como o Sangue de Pateante para criar uma devastadora New Plague. Diante de hordas esmagadoras do Flagelo e de remanescentes humanos hostis, os Renegados recorrem à guerra biológica como um equalizador. Faranello analisa a potência tóxica do sangue para conceber um contágio potente o suficiente para extinguir tanto a não-vida quanto a carne viva."}},faq={{q="Para que é usado o Sangue de Pateante?",a="A Real Sociedade de Boticários utiliza o Sangue de Pateante para desenvolver The New Plague dos Renegados. Quando misturado com toxinas derivadas de corações de urso, produz uma mistura volátil que o Mestre-boticário Faranello estuda para erradicar tanto os mortos-vivos do Flagelo quanto os humanos vivos.",al={"uso do sangue de pateante","por que coletar sangue de aranha","o que faranello faz com sangue de pateante"}},{q="Onde o Sangue de Pateante é encontrado?",a="Ele é coletado dos corpos de aranhas Skitterweb — incluindo lurkers, strikers e Krethis the Shadowspinner — que espreitam dentro e ao redor da Penumbra Furtiva, uma floresta sombria e repleta de teias localizada no noroeste da Floresta de Pinhaprata.",al={"onde conseguir sangue de pateante","localização do sangue de pateante","quem dropa sangue de pateante"}},{q="Quem solicita essas amostras?",a="O Boticário Renferrel, no Sepulcro na Floresta de Pinhaprata, encomenda a coleta do sangue, orientando os aventureiros a entregarem o fluido colhido diretamente ao Mestre-boticário Faranello no Boticarium da Cidade Baixa.",al={"quem quer sangue de pateante","doador da missão para sangue de pateante"}},{q="Por que os Renegados precisam de veneno de feras locais?",a="A Real Sociedade de Boticários isola constantemente toxinas naturais da fauna corrompida de Lordaeron. O veneno inerente dos aracnídeos gigantes de Floresta de Pinhaprata fornece patógenos biológicos brutos que podem ser concentrados e transformados em armas na forma de pragas sintéticas.",al={"por que veneno de aranha","pesquisa de boticário com feras"}}},fx={["8eea8a63"]={q="O que é Sangue de Pateante?",a="Sangue de Pateante é o icor virulento colhido das aranhas gigantes que habitam a Penumbra Furtiva da Floresta de Pinhaprata. Possui propriedades venenosas e contaminantes naturais que o tornam um reagente biológico inestimável para experimentos alquímicos.",al={"o que é sangue de pateante","item sangue de pateante","sobre o sangue de pateante"}},f7d32240={q="De onde vem o Sangue de Pateante e quem o produziu?",a="Ele não é fabricado, mas extraído naturalmente dos aracnídeos predadores que habitam o noroeste da Floresta de Pinhaprata, incluindo Espreitadores Teia-de-Pateante, Atacantes Teia-de-Pateante e a matriarca Krethis, a Tecedeira das Sombras. O sangue é extraído diretamente de suas carcaças por caçadores que fazem Gathering Materials para os Renegados.",al={"de onde vem o sangue de pateante","quem produziu o sangue de pateante","origem do sangue de pateante"}}},fp="16,224,18.307.0,22.345.0,34.245.0,32.185.0,27.156.0,49.221.0"}
P.entries["item:skullsplitter-fetish"] = {n="Skullsplitter Fetish",s="Um fetiche Rachacrânio é um instrumento de magia Troll reunido para o Irmão Nimetz no Acampamento dos Rebeldes. Ele espera que o fetiche esclareça a corrupção do Coronel Kurzen.",h="Um fetiche Rachacrânio é um instrumento de magia Troll reunido para o Irmão Nimetz no Acampamento dos...",kw={"irmão nimetz","coronel kurzen","místico","rachacrânio","fetiche rachacrânio","selva do espinhaço","magia troll","feiticeiro"},ang={["faction:Alliance"]="Como viajante da Aliança, você pode levar esses fetiches ao Irmão Nimetz para ajudar em seu estudo sobre a corrupção do Coronel Kurzen."},sec={{t="Magia Troll",b="Irmão Nimetz, no Acampamento dos Rebeldes, procura fetiches Rachacrânio com feiticeiros e místicos Rachacrânio na Selva do Espinhaço. Ele estuda esses amuletos em busca de sinais do que levou o Coronel Kurzen ao mal."}},faq={{q="O que é um fetiche Rachacrânio?",a="Um fetiche Rachacrânio é um instrumento de magia Troll carregado por feiticeiros e místicos Rachacrânio.",al={"significado de fetiche rachacrânio","o que é o fetiche","patuá troll"}},{q="Quem quer os fetiches?",a="Irmão Nimetz, no Acampamento dos Rebeldes, quer fetiches Rachacrânio para estudar sua magia.",al={"quem quer o fetiche","para onde vão os fetiches","irmão nimetz"}},{q="Por que Irmão Nimetz os quer?",a="Irmão Nimetz espera que os fetiches revelem o segredo por trás da corrupção do Coronel Kurzen.",al={"por que os fetiches","corrupção de kurzen","o que nimetz quer"}},{q="Onde se encontram fetiches Rachacrânio?",a="Feiticeiros e místicos Rachacrânio na Selva do Espinhaço carregam os fetiches.",al={"local dos fetiches","onde estão os rachacrânio","obter fetiches"}},{q="De quantos fetiches Nimetz precisa?",a="Irmão Nimetz pede quatro fetiches Rachacrânio.",al={"quantidade de fetiches","quantos amuletos","quatro fetiches"}}},fp="20,160,11.211.0,31.106.0,23.90.0,34.91.0,39.81.0,35.52.0"}
P.entries["item:skullsplitter-tusk"] = {n="Skullsplitter Tusk",s="Uma presa de Rachacrânio é uma presa de troll usada para forjar presas falsas de tigre, vendidas nos Mares do Sul. Kebok, em Angra do Butim, quer um grande carregamento para seu comércio.",h="Uma presa de Rachacrânio é uma presa de troll usada para forjar presas falsas de tigre, vendidas nos Mares do...",kw={"angra do butim","kebok","presa de rachacrânio","presas de rachacrânio","mares do sul","selva do espinhaço","presas de tigre"},sec={{t="Uma presa falsa",b="Kebok, em Angra do Butim, envia você atrás dos trolls Rachacrânio para obter suas presas. Elas rendem cópias convincentes de presas de tigre, que são difíceis e caras de conseguir dos próprios animais. As falsificações seguem em um carregamento com destino às ilhas dos Mares do Sul."}},faq={{q="O que é uma presa de Rachacrânio?",a="Uma presa de Rachacrânio é uma presa de troll que Kebok usa para fazer presas falsas de tigre.",al={"presa de rachacrânio","presa de troll","que presa"}},{q="Quem quer presas de Rachacrânio?",a="Kebok, em Angra do Butim, quer presas de Rachacrânio para seu carregamento de presas de tigre falsificadas.",al={"quem quer presas","presas do kebok","comprador de presas"}},{q="Por que Kebok precisa das presas?",a="Kebok usa presas de Rachacrânio como falsificações convincentes de presas de tigre, que são difíceis e caras de conseguir.",al={"por que presas","presas falsas de tigre","uso das presas"}},{q="De onde vêm as presas de Rachacrânio?",a="As presas vêm dos trolls Rachacrânio na Selva do Espinhaço.",al={"de onde vêm as presas","localização dos rachacrânio","presas de troll"}}},fp="18,157,12.256.0,29.83.0,30.84.0,30.98.0,39.63.0"}
P.entries["item:skylord-plume"] = {n="Skylord Plume",s="A Skylord Plume é retirada de um Razorbeak Skylord nas Terras Agrestes. O Guarda-caça Markhor, na Aldeia Revatusco, quer a pena como prova de que um desses grifos perigosos foi abatido.",h="A Skylord Plume é retirada de um Razorbeak Skylord nas Terras Agrestes.",kw={"grifo","terras agrestes","markhor","razorbeak skylord","aldeia revatusco","skylord plume","trolls caçadores"},ang={["class:Hunter"]="O Guarda-caça Markhor convoca você para caçar um grifo raro que ataca caçadores nas Terras Agrestes.",["race:Troll"]="Markhor diz que os Razorbeak Skylords devoraram trolls caçadores nas Terras Agrestes, tornando a ameaça próxima de casa."},sec={{t="Prova de um Caçador",b="Na Aldeia Revatusco, o Guarda-caça Markhor pede que você lhe traga uma Skylord Plume. Os Razorbeak Skylords são grifos raros das Terras Agrestes, e Markhor diz que eles caçam os trolls caçadores. Ele quer que você abata um e traga sua pena como prova."}},faq={{q="O que é a Skylord Plume?",a="A Skylord Plume vem de um Razorbeak Skylord, um grifo raro das Terras Agrestes.",al={"skylord plume","qual pena","pena de grifo"}},{q="Quem quer a Skylord Plume?",a="O Guarda-caça Markhor, na Aldeia Revatusco, quer que você lhe traga uma Skylord Plume.",al={"quem quer a pena","pena de markhor","caçador da aldeia revatusco"}},{q="Por que Markhor a quer?",a="Markhor pede que você abata um Razorbeak Skylord e volte com sua pena como prova.",al={"por que a pena","markhor quer a pena","para que serve"}},{q="Onde posso encontrar um Razorbeak Skylord?",a="Os Razorbeak Skylords são grifos raros que habitam as regiões selvagens das Terras Agrestes.",al={"onde fica o skylord","encontrar razorbeak","localização do skylord"}},{q="Por que os Skylords são perigosos para os trolls?",a="Markhor diz que os grifos mais velhos caçam trolls caçadores e criam filhotes que também matam trolls.",al={"skylords e trolls","ameaça dos grifos","por que matar o skylord"}}},fp="13,180,16.235.0,26.84.0,28.75.0,25.80.0,37.78.0,41.96.0"}
P.entries["item:sleepers-key"] = {n="Chave do Adormecido",s="A Chave do Adormecido é uma das três chaves encantadas criadas por druidas elfos noturnos para selar seu cofre sagrado dentro do Retiro do Gadanho, no topo do Morro das Torres de Pedra. Mantida em segurança dentro de um esconderijo secreto aberto com a Chave do Guardião do Portal, é uma das três chaves necessárias para abrir o tesouro dos druidas.",h="A Chave do Adormecido é uma das três chaves encantadas criadas por druidas elfos noturnos para selar seu...",kw={"chave do guardião do portal","esconderijo do adormecido","chave do adormecido","morro das torres de pedra","retiro do gadanho","tesouro do retiro do gadanho","the den"},ang={["class:Druid"]="As chaves e esconderijos do Retiro do Gadanho exibem as defesas em camadas dos druidas elfos noturnos, que usavam esconderijos secretos e fechaduras com chaves para selar relíquias de poder.",["faction:Horde"]="Adquirir a Chave do Adormecido faz parte de uma incursão orquestrada ao coração do Morro das Torres de Pedra, desmantelando as proteções defensivas dos elfos noturnos para reivindicar as relíquias seladas em seu tesouro."},sec={{t="Uma Proteção Druídica",b="Esculpido nas alturas do Morro das Torres de Pedra, o Retiro do Gadanho serve como reduto e santuário para os druidas de Kalimdor. Cientes de que suas relíquias sagradas e tesouros poderosos poderiam atrair atenção indesejada, os guardiões elfos noturnos criaram um intrincado sistema de trancas e esconderijos secretos para proteger seu tesouro. A Chave do Adormecido é um terço dessa barreira de proteção. Colocada dentro de um esconderijo isolado nas profundezas do retiro, ela só pode ser recuperada usando a Chave do Guardião do Portal, escondida perto da entrada. Junto com a Chave da Garra e a Chave da Ermida, a Chave do Adormecido deve ser inserida nas trancas de pedra do Talon Den Hoard para dispersar a proteção e revelar os itens antigos guardados em seu interior."}},faq={{q="Para que serve a Chave do Adormecido?",a="A Chave do Adormecido é usada junto com a Chave da Ermida e a Chave da Garra para abrir o Talon Den Hoard, um cofre de pedra protegido escondido nas profundezas da ermida no Morro das Torres de Pedra.",al={"o que a chave do adormecido faz","propósito da chave do adormecido","chaves do tesouro do retiro do gadanho"}},{q="Como a Chave do Adormecido foi trancada?",a="Os druidas a colocaram dentro do Sleepers' Cache nos túneis a noroeste do Retiro do Gadanho. Abrir esse esconderijo requer a Chave do Guardião do Portal, que os druidas ocultaram dentro de uma lanterna despretensiosa perto da entrada do retiro.",al={"onde fica a chave do adormecido","abrindo o esconderijo do adormecido","requisito da chave do guardião do portal"}},{q="Por que os druidas esconderam suas relíquias com múltiplas chaves?",a="Os druidas elfos noturnos criaram proteções complexas para que seus itens poderosos e relíquias sagradas nunca caíssem em mãos inimigas se o retiro fosse atacado. Dispersar as chaves entre esconderijos secretos garantiu que intrusos não pudessem saquear facilmente seu tesouro.",al={"por que tantas chaves","defesa do retiro do gadanho","enigma do tesouro dos druidas"}},{q="Por que se chama Chave do Adormecido?",a="Os druidas nunca explicam o nome. A chave simplesmente o compartilha com o Sleepers' Cache, o baú oculto no Retiro do Gadanho onde é guardada.",al={"quem são os adormecidos","significado do nome da chave do adormecido"}}},fx={["0a862a33"]={q="O que é a Chave do Adormecido?",a="A Chave do Adormecido é uma das três chaves especializadas criadas pelos druidas elfos noturnos do Morro das Torres de Pedra. Escondida dentro de um esconderijo trancado nas profundezas do Retiro do Gadanho, ela forma um componente essencial do sistema de proteção que guarda o tesouro central de relíquias sagradas dos druidas.",al={"o que é a chave do adormecido","história da chave do adormecido","sobre a chave do adormecido"}},["8275ad63"]={q="De onde vem a Chave do Adormecido e quem a criou?",a="A chave foi criada pelos druidas que estabeleceram o Retiro do Gadanho no Morro das Torres de Pedra. Para proteger seus artefatos potentes de intrusos, eles criaram um esquema de segurança complexo, protegendo a chave dentro de um baú dedicado chamado Esconderijo do Adormecido.",al={"quem criou a chave do adormecido","origem da chave do adormecido","de onde veio a chave do adormecido"}},["3884172c"]={q="Por que alguém quer a Chave do Adormecido?",a="A Horda busca a chave para contornar as defesas em camadas dos druidas e abrir o Tesouro do Retiro do Gadanho. Juntamente com a Chave da Garra e a Chave da Ermida, ela abre o cofre de pedra que contém as relíquias poderosas que os druidas esconderam no Morro das Torres de Pedra.",al={"por que encontrar a chave do adormecido","por que precisar da chave do adormecido","quem quer a chave do adormecido"}}},fp="13,149,19.546.0,35.148.0,38.200.0,56.237.0,35.141.0"}
P.entries["item:small-brass-key"] = {n="Small Brass Key",s="A Small Brass Key está escondida em um livro-caixa no Kurzen’s Compound. Talvez sirva em um cofre no Stockpile.",h="A Small Brass Key está escondida em um livro-caixa no Kurzen’s Compound.",kw={"contador herodes","herodes","chave escondida","complexo do kurzen","muddy note","small brass key","stockpile","selva do espinhaço","cofre"},sec={{t="Uma chave no livro-caixa",b="Os papéis de Herodes apontam você para o Stockpile, uma caverna atrás do Kurzen’s Compound, na Selva do Espinhaço. A Small Brass Key está escondida na encadernação de um dos livros-caixa dele. Talvez ela abra o cofre protegido mencionado nas anotações."},{t="Dentro do cofre",b="O cofre guarda as moedas e os itens mais valiosos de Herodes. Ao abri-lo com a Small Brass Key, você também encontra uma Muddy Note, que dá continuidade à busca pelo traidor."}},faq={{q="Onde encontro a Small Brass Key?",a="A Small Brass Key está escondida na encadernação de um dos livros-caixa do Contador Herodes.",al={"localização da chave pequena","onde está a chave de latão","chave de herodes"}},{q="O que a Small Brass Key abre?",a="A Small Brass Key abre o cofre protegido do Contador Herodes no Stockpile, no Kurzen’s Compound.",al={"o que a chave abre","cofre da chave de latão","chave do cofre"}},{q="O que há no cofre de Herodes?",a="Herodes guarda no cofre suas moedas e seus itens mais valiosos. Também há uma Muddy Note lá.",al={"conteúdo do cofre de herodes","o que há no cofre","cofre do contador herodes"}},{q="O que significa a Muddy Note?",a="A Muddy Note leva a busca adiante, em direção à descoberta do traidor.",al={"pista da muddy note","nota do cofre","nota sobre o traidor"}}},fp="15,111,19.248.0,14.172.1,36.85.0,35.100.0,31.97.0,30.71.1"}
P.entries["item:small-stone-shard"] = {n="Small Stone Shard",s="Small Stone Shards vêm de elementais de rocha inferiores nos Ermos. Lotwil Viriato precisa deles para testar feitiços e dispositivos usados em seu trabalho de vinculação elemental.",h="Small Stone Shards vêm de elementais de rocha inferiores nos Ermos.",kw={"ermos","vinculação elemental","elemental de rocha inferior","lotwil viriato","feitiços ofensivos","algemas","small stone shard","small stone shards"},ang={["class:Mage"]="Como mago, você pode ver Lotwil Viriato testando feitiços ofensivos e dispositivos enquanto trabalha em algemas para prender elementais."},sec={{t="Pedra para Estudo",b="Elementais de rocha inferiores nas colinas a oeste de Lotwil Viriato carregam Small Stone Shards. O mago os reúne para testar seus feitiços ofensivos e os dispositivos que montou. Ele está trabalhando em algemas para prender elementais, e esses fragmentos estão entre os materiais de que precisa."}},faq={{q="De onde vêm Small Stone Shards?",a="Você os retira dos elementais de rocha inferiores que vagam pelas colinas a oeste de Lotwil Viriato.",al={"origem de small stone shard","onde encontrar fragmento de pedra","elementais de rocha inferiores"}},{q="Quem quer os fragmentos?",a="Lotwil Viriato precisa de Small Stone Shards para seu trabalho com a vinculação elemental e para testar feitiços e dispositivos.",al={"quem precisa dos fragmentos","fragmentos de lotwil","a quem entregar os fragmentos"}},{q="Para que servem os fragmentos?",a="Lotwil Viriato usa Small Stone Shards para testar feitiços ofensivos e dispositivos de seu trabalho em algemas para vinculação elemental.",al={"por que os fragmentos","finalidade dos fragmentos","o que lotwil está fazendo"}},{q="Onde Lotwil Viriato está trabalhando?",a="Lotwil Viriato está trabalhando nos Ermos, com elementais de rocha inferiores nas colinas logo a oeste.",al={"localização de lotwil","onde fica lotwil","mago nos ermos"}}},fp="17,154,15.278.0,38.90.0,21.111.0,29.123.0,33.109.0"}
P.entries["item:smithing-tuyere"] = {n="Alcaraviz de Ferraria",s="O Alcaraviz de Ferraria é uma ferramenta de ferreiro roubada por Dark Iron dwarves na Garganta Abrasadora. A Irmandade do Tório quer que ele seja devolvido ao Capataz Scrange.",h="O Alcaraviz de Ferraria é uma ferramenta de ferreiro roubada por Dark Iron dwarves na Garganta Abrasadora.",kw={"ferramenta de ferraria","dark iron dwarves","fornalha","garganta abrasadora","alcaraviz de ferraria","capataz scrange","irmandade do tório","alcaraviz"},ang={["profession:Blacksmithing"]="Como ferreiro, você sabe que um alcaraviz leva ar à fornalha e deixa o fogo quente o bastante para trabalhar o metal."},sec={{t="Uma ferramenta roubada",b="A Irmandade do Tório procura o Alcaraviz de Ferraria na Garganta Abrasadora, onde Dark Iron dwarves o roubaram. A ferramenta pertence à forja de um ferreiro. O ar soprado pelo tubo deixa a fornalha mais quente, amolecendo o metal o bastante para ser trabalhado."}},faq={{q="O que é um Alcaraviz de Ferraria?",a="Um Alcaraviz de Ferraria é um tubo que sopra ar na fornalha e deixa o fogo mais quente para que o metal possa ser trabalhado.",al={"o que é um alcaraviz","ferramenta alcaraviz","tubo de ferraria"}},{q="Quem roubou o alcaraviz?",a="A Irmandade do Tório acredita que Dark Iron dwarves roubaram o Alcaraviz de Ferraria na Garganta Abrasadora.",al={"quem o levou","roubo dos dark iron","quem roubou a ferramenta"}},{q="Quem quer o alcaraviz de volta?",a="A Irmandade do Tório quer que o Alcaraviz de Ferraria seja devolvido ao Capataz Scrange, na Garganta Abrasadora.",al={"quem o quer","devolver o alcaraviz","item da irmandade do tório"}},{q="Onde o alcaraviz foi roubado?",a="O Alcaraviz de Ferraria foi roubado por Dark Iron dwarves na Garganta Abrasadora.",al={"onde foi perdido","local do alcaraviz","onde encontrar a ferramenta"}}},fp="15,154,13.240.0,26.105.0,21.94.0,26.98.0,28.69.0"}
P.entries["item:smoky-iron-ingot"] = {n="Lingote Fumegante de Ferro",s="Lingotes Fumegantes de Ferro são barras de metal processadas de forma rústica, fundidas pelos kobolds dos sítios de escavação de Cortavento na Cordilheira das Torres de Pedra. Os armeiros orcs valorizam esses lingotes como matéria-prima para forjar equipamentos de malha resistentes, dignos dos guerreiros da Horda.",h="Lingotes Fumegantes de Ferro são barras de metal processadas de forma rústica, fundidas pelos kobolds dos...",kw={"armadura brutal","kobold","lingote fumegante de ferro","cordilheira das torres de pedra","thun'grim olhafogo","guerreiro","cortavento"},ang={["class:Warrior"]="Para guerreiros da Horda, obter esses lingotes é uma prova de resistência nas Torres de Pedra, servindo como componente essencial para forjar a Cota Brutal.",["profession:Blacksmithing"]="A qualidade rudimentar desses lingotes ilustra os métodos primitivos de fundição dos escavadores kobolds em comparação com as técnicas refinadas praticadas por ferreiros treinados."},sec={{t="Metalurgia Rústica dos Kobolds",b="Dentro dos túneis manchados de fuligem do Rochedo Cortavento na Cordilheira das Torres de Pedra, os kobolds escavam fundo na terra rochosa, extraindo minério bruto das encostas e fundindo-o sobre fogueiras rústicas e fumegantes. Os Lingotes Fumegantes de Ferro resultantes estão longe de ser puros — cheios de resíduos e carvão —, mas são densos o suficiente para reter uma considerável resistência à tração."},{t="Forjando a Armadura Brutal",b="O armeiro orc quase cego Thun'grim Olhafogo, trabalhando em um acampamento rústico com vista para os Sertões, solicita especificamente esses lingotes ao criar armaduras para guerreiros comprovados da Horda. Combinado com barras de ferro refinado, azurita pulverizada e flogisto volátil, o metal fumegante serve como um núcleo resistente para a confecção de Cotas Brutais."}},faq={{q="De onde vêm os Lingotes Fumegantes de Ferro?",a="Os Lingotes Fumegantes de Ferro são carregados pelos kobolds que habitam os túneis e sítios de escavação de Cortavento na parte leste da Cordilheira das Torres de Pedra, incluindo escavadores, talhadores de pedra, pestes, geomantes e seus capatazes.",al={"onde encontrar lingote fumegante de ferro","localização do lingote fumegante de ferro","quem saqueia lingote fumegante de ferro"}},{q="Para que servem os Lingotes Fumegantes de Ferro?",a="Eles são coletados por guerreiros que atendem ao chamado de Thun'grim Olhafogo, um mestre armeiro que reside nos picos próximos à Encruzilhada, nos Sertões. Ele exige quinze desses lingotes para forjar a emblemática Cota Brutal.",al={"uso do lingote fumegante de ferro","para que serve lingote fumegante de ferro","item de missão armadura brutal"}},{q="Por que os lingotes são descritos como 'fumegantes'?",a="Os kobolds utilizam técnicas primitivas de fundição a baixa temperatura em seus túneis escuros. O metal resultante retém fuligem, pó de carvão e cinzas de suas fornalhas subterrâneas esfumaçadas, em vez de ser refinado até atingir um brilho limpo.",al={"por que é fumegante","história do ferro fumegante"}},{q="Qualquer ferreiro pode forjar com esses lingotes?",a="Não. Os Lingotes Fumegantes de Ferro são barras irregulares e incrustadas de fuligem, inutilizáveis na ferraria comercial padrão. Apenas ferreiros especializados como Thun'grim Olhafogo sabem como incorporá-los em equipamentos de combate personalizados.",al={"jogadores podem forjar ferro fumegante","ferro fumegante é item de comércio"}}},fx={["9ee5c553"]={q="De onde vem o Lingote Fumegante de Ferro e quem o fabricou?",a="Estes lingotes são minerados e fundidos pelos kobolds do Rochedo Cortavento na Cordilheira das Torres de Pedra. Nas profundezas de seus túneis subterrâneos, escavadores e vermes desenterram o minério bruto e o fundem em lingotes de ferro utilizáveis para reforçar suas operações subterrâneas e armar seus bandos de guerra.",al={"fonte do lingote fumegante de ferro","de onde vêm os lingotes fumegantes de ferro","quem fabrica o lingote fumegante de ferro"}},["18404e72"]={q="O que é um Lingote Fumegante de Ferro?",a="Lingotes Fumegantes de Ferro são barras de ferro escuro, fundidas de forma rudimentar e marcadas por fuligem, encontradas nas mãos dos kobolds Windshear que escavam nas profundezas da Cordilheira das Torres de Pedra. Embora sejam grosseiros em comparação com metais refinados, possuem a resistência necessária aos ferreiros habilidosos que buscam forjar armaduras pesadas e duradouras.",al={"o que é lingote fumegante de ferro","informações sobre lingote fumegante de ferro","sobre lingote fumegante de ferro"}},["8ab45f92"]={q="Por que alguém quer um Lingote Fumegante de Ferro?",a="O mestre ferreiro orc quase cego Thun'grim Firegaze, que vive no alto dos penhascos dos Sertões, precisa de quinze desses lingotes para fabricar Brutal Armor para guerreiros dignos da Horda. Combinado com outros agentes alquímicos e minerais raros, o metal bruto serve de base para uma armadura feita para resistir à brutalidade da guerra.",al={"por que conseguir lingote fumegante de ferro","quem quer lingote fumegante de ferro","uso e história do lingote fumegante de ferro"}}},fp="16,164,23.242.0,24.281.0,37.182.0,36.194.0,40.159.0,43.166.0"}
P.entries["item:smoldering-embers"] = {n="Brasas Fumegantes",s="Brasas Fumegantes são os restos incandescentes e calcinados recuperados dos furiosos elementais do fogo do Vale Carbonizado. As Sentinelas dos elfos noturnos usam essas cinzas como prova física de que os terrores ígneos que assolam o bosque devastado estão sendo subjugados.",h="Brasas Fumegantes são os restos incandescentes e calcinados recuperados dos furiosos elementais do fogo do...",kw={"burning destroyer","burning ravager","vale carbonizado","espíritos enfurecidos","kaela umbralança","ladino flame spirit","brasas fumegantes","cordilheira das torres de pedra","empreendimentos s.a."},ang={["class:Druid"]="Os druidas veem as brasas como uma prova trágica da natureza desequilibrada pela ganância industrial, onde a fúria elemental indomada impede que o solo sufocado em cinzas se regenere.",["race:NightElf"]="Para os elfos noturnos, ver o Vale Carbonizado em chamas é uma ferida desoladora em Kalimdor. Coletar essas brasas é um dever solene para expurgar a profanação estrangeira e restaurar a paz sob o olhar de Eluna."},sec={{t="Vestígios do Vale Carbonizado",b="O desmatamento implacável e a devastação industrial da Empreendimentos S.A. rasgaram o Vale Carbonizado, incendiando a floresta e libertando uma fúria destrutiva das profundezas da terra. Em seu rastro, elementais de fogo vivo — Burning Ravagers, Burning Destroyers e Rogue Flame Spirits errantes — espalharam-se pela bacia queimada. Essas Brasas Fumegantes são os núcleos residuais e cobertos de cinzas deixados para trás quando um elemental é extinto, servindo como prova de que os incêndios descontrolados do vale estão sendo sistematicamente contidos."}},faq={{q="De onde vêm as Brasas Fumegantes?",a="As Brasas Fumegantes são obtidas dos elementais ígneos que assombram o Vale Carbonizado no sul da Cordilheira das Torres de Pedra, incluindo Burning Ravagers, Burning Destroyers e Rogue Flame Spirits.",al={"onde encontrar brasas fumegantes","quem dropa brasas fumegantes","fonte de brasa fumegante"}},{q="Por que Kaela Umbralança quer essas brasas?",a="Kaela Umbralança busca essas brasas como prova incontestável de que os elementais de fogo descontrolados no Vale Carbonizado estão sendo abatidos. Ela acredita que a terra marcada jamais poderá se curar sob A graça de Eluna enquanto esses espíritos violentos vagarem sem controle.",al={"por que coletar brasas fumegantes","kaela umbralança brasas","objetivo de espíritos enfurecidos"}},{q="O que fez com que os elementais de fogo aparecessem no Vale Carbonizado?",a="A Empreendimentos S.A. utilizou maquinário agressivo e queimadas indiscriminadas para desmatar a floresta ancestral. Sua exploração imprudente desestabilizou a terra, desenterrando e libertando elementais hostis de chamas e pedras que acabaram expulsando os goblins.",al={"o que aconteceu com o vale carbonizado","por que ha elementais de fogo nas torres de pedra","empreendimentos s.a. espiritos de fogo"}}},fx={["4d13fc7e"]={q="O que são Brasas Fumegantes?",a="Brasas Fumegantes são os restos físicos ardentes deixados para trás pelos elementais de fogo destrutivos que infestam o Vale Carbonizado. Esses remanescentes brilhantes permanecem depois que criaturas como Devastadores Ardentes, Espíritos das Chamas Ladinos e Destruidores Ardentes são mortos, servindo como prova tangível de que seu ataque de fogo pela floresta arruinada foi contido.",al={"o que são brasas fumegantes","história das brasas fumegantes","o que é uma brasa fumegante"}}},fp="17,159,28.404.0,37.182.0,45.208.0,62.277.0"}
P.entries["item:smotts-cutlass"] = {n="Smotts' Cutlass",s="O Capitão Smotts quer sua espada de volta na Selva do Espinhaço. Ele pede que você leve vinho e Barbecued Buzzard Wings até seu velho bote salva-vidas na costa.",h="O Capitão Smotts quer sua espada de volta na Selva do Espinhaço.",kw={"barbecued buzzard wings","capitão smotts","espada","negolash","bote salva-vidas destruído","smotts' cutlass","selva do espinhaço"},sec={{t="Lâmina de um capitão",b="O Capitão Smotts pede que você leve vinho e Barbecued Buzzard Wings até seu velho bote salva-vidas na costa. Negolash, o gigante faminto que destruiu o navio do capitão, gosta dos dois. Smotts pretende atrair o gigante e recuperar sua espada. A lâmina está nas mãos de Negolash."}},faq={{q="Quem é o dono de Smotts' Cutlass?",a="O Capitão Smotts é o dono da espada e pede que ela seja devolvida.",al={"dono da espada de smotts","espada do capitão","quem é smotts"}},{q="Como Negolash conseguiu a espada?",a="Negolash pegou a espada depois que o gigante destruiu o navio do Capitão Smotts.",al={"espada de negolash","como o gigante conseguiu","espada roubada"}},{q="Por que Smotts quer vinho e asas de ave carniceira?",a="Negolash deseja vinho e as Barbecued Buzzard Wings do Capitão Smotts, então Smotts usa os dois para atrair o gigante até seu velho bote salva-vidas.",al={"isca para negolash","por que vinho e asas","comida de smotts"}},{q="Onde está Smotts' Cutlass?",a="Negolash está com Smotts' Cutlass na Selva do Espinhaço.",al={"localização da espada","onde está a lâmina de smotts","item de negolash"}}},fp="15,148,17.273.0,25.56.0,33.73.1,44.124.0,25.51.1"}
P.entries["item:snapshot-of-gammerita"] = {n="Snapshot of Gammerita",s="Nas Terras Agrestes, a imagem de Gammerita é capturada com a Superinstantânea FX de Curgle. Daryn Aelumnis, em Rut’theran Village, quer a foto para seus estudos.",h="Nas Terras Agrestes, a imagem de Gammerita é capturada com a Superinstantânea FX de Curgle.",kw={"daryn aelumnis","gammerita","terras agrestes","rut’theran village","foto de gammerita","superinstantânea fx"},sec={{t="Uma foto para Daryn",b="Curgle empresta a Superinstantânea FX para fotografar Gammerita nas Terras Agrestes. Daryn Aelumnis espera em Rut’theran Village para receber a foto e diz que a invenção de Curgle correspondeu às expectativas dela."}},faq={{q="Quem é Gammerita?",a="Gammerita é uma criatura das Terras Agrestes, e Daryn Aelumnis pede uma foto dela.",al={"gammerita","quem é gammerita"}},{q="Quem quer esta foto?",a="Daryn Aelumnis quer a foto para seus estudos e espera em Rut’theran Village.",al={"quem quer a foto de gammerita","foto para quem"}},{q="Como a foto foi tirada?",a="A Superinstantânea FX de Curgle tira a foto quando é apontada para Gammerita.",al={"como tirar foto de gammerita","foto com a superinstantânea"}},{q="O que é a Superinstantânea FX?",a="A Superinstantânea FX é uma invenção de Curgle, emprestada para que seja possível fotografar Gammerita.",al={"superinstantânea","invenção de curgle"}},{q="Onde posso encontrar Gammerita?",a="Gammerita fica nas Terras Agrestes.",al={"localização de gammerita","onde fica gammerita"}}},fp="21,161,19.206.0,17.85.0,24.76.0,27.71.0,29.93.0,27.32.0"}
P.entries["item:snellig-s-snuffbox"] = {n="Caixa de Rapé do Expedito",s="A Caixa de Rapé do Expedito é uma lembrança pessoal recuperada do inquieto morto-vivo Primeiro Oficial Snellig entre os destroços da Frota Perdida. Levar este berloque de volta ao Primeiro Oficial Simonez no Porto de Menethil serve como prova de que seu antigo companheiro de tripulação amaldiçoado finalmente descansou.",h="A Caixa de Rapé do Expedito é uma lembrança pessoal recuperada do inquieto morto-vivo Primeiro Oficial...",kw={"tripulação amaldiçoada","simonez","kul tiraz","frota perdida","snellig","caixa de rapé","the third fleet","pantanal"},ang={["faction:Alliance"]="Recuperar os pertences dos marinheiros kultirenos caídos e conceder descanso a seus espíritos amaldiçoados é um dever sombrio a serviço de um antigo aliado naval da Aliança."},sec={{t="Uma Lembrança da The Third Fleet",b="Quando a The Third Fleet de Kul Tiraz encalhou ao longo da costa norte do Pantanal, seus marinheiros e oficiais não encontraram mortes pacíficas. Presos por um poder misterioso e sombrio ligado a um tesouro escondido a bordo dos navios, a tripulação afogada ergueu-se novamente como espíritos torturados e mortos-vivos esqueléticos. Entre eles estava o Primeiro Oficial Snellig, que ainda assombra o porão apodrecido dos destroços mais próximos da costa. Mesmo na morte, ele se apegou à sua caixa de rapé — uma lembrança pequena e mundana de sua vida mortal no mar. Para o único sobrevivente vivo do desastre, o Primeiro Oficial Simonez, recuperar essa pequena posse fornece uma prova tangível de que pelo menos um de seus companheiros de navio perdidos foi libertado de uma eternidade de tormento."}},faq={{q="O que é a Caixa de Rapé do Expedito?",a="É um pequeno recipiente pessoal que pertenceu ao Primeiro Oficial Snellig, um oficial da malfadada The Third Fleet de Kul Tiraz. Ela é carregada por seu remanescente morto-vivo a bordo dos naufrágios na costa norte do Pantanal.",al={"o que é este item","caixa de rapé do expedito","caixa de rapé"}},{q="Onde encontro a Caixa de Rapé do Expedito?",a="A caixa de rapé é obtida do Primeiro Oficial Snellig, que assombra o porão do naufrágio mais próximo da costa na Frota Perdida, no noroeste do Pantanal.",al={"onde snellig dropa caixa de rapé","encontrar snellig","localização do primeiro oficial snellig"}},{q="Quem quer esta caixa de rapé?",a="O Primeiro Oficial Simonez, o único sobrevivente vivo da The Third Fleet, pede aos aventureiros que levem a caixa de rapé até ele no Porto de Menethil como prova de que Snellig descansou.",al={"quem aceita a caixa de rapé","a quem entregar isto","missão de simonez"}},{q="Por que o Primeiro Oficial Snellig é amaldiçoado?",a="Segundo Simonez, um tesouro sombrio e terrível escondido a bordo de uma das embarcações da The Third Fleet condenou as tripulações após o naufrágio, aprisionando suas almas nas madeiras apodrecidas e negando-lhes o descanso.",al={"por que snellig é morto-vivo","maldição da frota perdida","maldição da the third fleet"}}},fp="18,184,29.620.0,27.168.0,35.152.0,24.167.0,33.194.0"}
P.entries["item:snufflenose-command-stick"] = {n="Bastão de Adestramento do Fungafuça",s="O Bastão de Adestramento do Fungafuça é uma vara de treino fornecida pelo empresário goblin Cáliper Porcatraca em Vila Catraca. Ele é usado para orientar roedores fungafuças adestrados a localizar e desenterrar valiosos tubérculos folhazul enterrados nas profundezas do Urzal dos Tuscos.",h="O Bastão de Adestramento do Fungafuça é uma vara de treino fornecida pelo empresário goblin Cáliper...",kw={"tubérculo folhazul","bastão de adestramento","roedor","cáliper porcatraca","vila catraca","urzal dos tuscos","fungafuça","sertões"},ang={["profession:Cooking"]="Embora os tubérculos folhazul sejam considerados uma iguaria culinária requintada em todo o mundo, extraí-los requer um animal treinado e a vara de um adestrador, em vez de utensílios comuns de cozinha."},sec={{t="Uma Vara para Roedores",b="Tubérculos folhazul são iguarias cobiçadas em toda Azeroth, mas encontrá-los é quase impossível sem ajuda especializada. Enterradas nas profundezas subterrâneas e espinhosas do Urzal dos Tuscos, as raízes ficam totalmente escondidas da vista. Para explorar esse mercado lucrativo sem ter que enfrentar pessoalmente os covis dos javatuscos, o comerciante de Vila Catraca, Cáliper Porcatraca, condicionou roedores fungafuças de faro aguçado para desenterrar os tubérculos. O Bastão de Adestramento do Fungafuça é a ferramenta que os aventureiros usam para orientar essas criaturinhas adestradas, incentivando-as a farejar e expor nós de raízes a até cinquenta passos de distância."}},faq={{q="Para que serve o Bastão de Adestramento do Fungafuça?",a="O bastão de adestramento é usado para ordenar a um roedor fungafuça adestrado que procure por tubérculos folhazul escondidos dentro dos túneis espinhosos do Urzal dos Tuscos. Quando apontada para um roedor evocado, a vara estimula a criatura a seguir rastros de cheiro e desenterrar nós de raízes.",al={"como usar o bastão de adestramento","o que faz o bastão de adestramento","finalidade do bastão de adestramento"}},{q="Onde você obtém o Bastão de Adestramento do Fungafuça?",a="Você o pega em Vila Catraca, nos Sertões, diretamente do lado de fora da oficina de Cáliper Porcatraca, junto com um caixote contendo um roedor adestrado e um manual de instruções.",al={"onde obter o bastão de adestramento","localização do bastão de adestramento","quem dá o bastão de adestramento"}},{q="Por que Cáliper Porcatraca quer tubérculos folhazul?",a="Tubérculos folhazul são iguarias raras vendidas com lucro considerável para contatos culinários abastados ao redor do mundo. Como só crescem nas profundezas dos Sertões, em território dos javatuscos, Cáliper contrata aventureiros para colhê-los.",al={"por que tubérculos","finalidade do tubérculo folhazul","por que cáliper quer tubérculos"}},{q="Você pode ficar com o bastão após encontrar os tubérculos?",a="Não. Depois de reunir os tubérculos solicitados, Cáliper exige que você devolva tanto o bastão de adestramento quanto o caixote de transporte a ele em Vila Catraca, juntamente com sua colheita.",al={"posso ficar com o bastão de adestramento","devolver o bastão de adestramento"}}},fx={["8cc828c2"]={q="O que é o Bastão de Adestramento do Fungafuça?",a="O Bastão de Adestramento do Fungafuça é a ferramenta de manejo patenteada da Snuff Inc., fornecida com os esquilos adestrados do empreendedor goblin Cáliper Porcatraca em Vila Catraca. Ele foi projetado especificamente para direcionar os esquilos fungafuça adestrados, dando-lhes o sinal para desenterrar iguarias escondidas e esquivas que um batedor comum ignoraria completamente.",al={"o que é o bastão de adestramento","bastão fungafuça","o que é o bastão de adestramento do fungafuça"}},["9fdd5faa"]={q="De onde vem o Bastão de Adestramento do Fungafuça e quem o fabricou?",a="O bastão de adestramento é um produto patenteado da Snuff Inc., cujo proprietário Marwig Rustbolt explica seu uso no Manual de Proprietário do Fungafuça. Cáliper Porcatraca em Vila Catraca treinou seus esquilos fungafuça para colher iguarias raras e mantém os bastões de adestramento, caixotes e manuais juntos para que os ajudantes contratados possam controlar as criaturas adequadamente.",al={"quem fabricou o bastão de adestramento","origem do bastão de adestramento","de onde vem o bastão de adestramento"}},fb1cfa60={q="Por que alguém quer o Bastão de Adestramento do Fungafuça?",a="Tubérculos de Blueleaf raros são impossíveis de encontrar sem ajuda sob as sarças do Urzal dos Tuscos. O bastão de adestramento é vital porque obriga um esquilo fungafuça adestrado a farejar cinquenta passos à frente e desenterrar os tubérculos, que podem então ser devolvidos a Cáliper Porcatraca por uma boa recompensa.",al={"por que precisar do bastão","por que o bastão de adestramento é procurado","por que obter o bastão de adestramento do fungafuça"}}},fp="25,93,17.432.0,47.178.0,50.166.0,45.247.0,54.141.0"}
P.entries["item:snufflenose-owner-s-manual"] = {n="Manual de Proprietário do Fungafuça",s="O Manual de Proprietário do Fungafuça é um livreto de instruções de Marwig Rustbolt da Snuff Inc., guardado ao lado do empresário goblin Cáliper Porcatraca em Vila Catraca. Ele explica como posicionar e direcionar um Snufflenose Gopher treinado para localizar Blueleaf Tubers raras enterradas no Urzal dos Tuscos.",h="O Manual de Proprietário do Fungafuça é um livreto de instruções de Marwig Rustbolt da Snuff Inc., guardado...",kw={"tubérculo folhazul","esquilo-terrestre","manual","cáliper porcatraca","vila catraca","urzal dos tuscos","fungafuça"},ang={["profession:Cooking"]="O manual detalha o processo de recuperação de Blueleaf Tubers, uma raiz subterrânea considerada uma iguaria rara por gastrônomos e comerciantes de toda Azeroth."},sec={{t="Um Guia de Operação de Goblin",b="Escrito por Marwig Rustbolt, proprietário da Snuff Inc., este guia breve detalha como trabalhar com os snufflenose gophers treinados da empresa. Essas feras possuem um olfato aguçado capaz de detectar Blueleaf Tubers subterrâneas a cinquenta passos de distância. O manual instrui os garimpeiros a soltar um gopher usando um caixote ventilado e a guiar seus instintos de fossar com um bastão de comando, direcionando a criatura através dos espinhos hostis e túneis de javatuscos do Urzal dos Tuscos para obter as cobiçadas iguarias culinárias."}},faq={{q="Qual é o objetivo do Manual de Proprietário do Fungafuça?",a="Ele serve como instruções para lidar com os snufflenose gophers treinados de Cáliper Porcatraca. Aventureiros o leem para entender como soltar o animal de seu caixote e direcioná-lo com um bastão de comando para localizar Blueleaf Tubers enterradas dentro do Urzal dos Tuscos.",al={"o que o manual faz","por que ler o manual","objetivo do manual"}},{q="Onde posso encontrar o manual?",a="O manual é guardado em Vila Catraca nos Sertões, bem perto de Cáliper Porcatraca junto com os caixotes especializados e bastões de comando necessários para coletar tubérculos.",al={"localização do manual","onde está o livro","como obter o manual"}},{q="Por que os snufflenose gophers são necessários para encontrar Blueleaf Tubers?",a="Blueleaf tubers crescem ocultas nas profundezas da terra dentro do Urzal dos Tuscos e são praticamente impossíveis de serem vistas por humanoides. Os gophers treinados possuem focinhos aguçados que podem detectar o cheiro de um tubérculo enterrado a cinquenta passos de distância.",al={"por que usar esquilos-terrestres","posso encontrar tubérculos sem esquilos-terrestres"}},{q="Quem escreveu o manual?",a="Ele é assinado por Marwig Rustbolt, proprietário da Snuff Inc., que o escreveu para ensinar novos proprietários a alimentar, passear e comandar seus gophers com o bastão de comando patenteado.",al={"autor do manual","quem fez"}}},fx={["1c231f00"]={q="O que é o Manual de Proprietário do Fungafuça?",a="É um manual de instruções fornecido junto com um esquilo fungafuça adestrado e um bastão de adestramento. O manual guia os aventureiros sobre como lidar com a criatura dentro dos túneis subterrâneos do Urzal dos Tuscos, explicando como comandar o esquilo para farejar os esquivos Tubérculos de Blueleaf subterrâneos.",al={"o que é o manual de proprietário do fungafuça","identidade do manual do fungafuça","o que é o manual"}}},fp="26,193,26.388.0,54.184.0,28.114.0,59.142.0,21.165.0"}
P.entries["item:sodium-nitrate"] = {n="Nitrato de Sódio",s="O Nitrato de Sódio é um reagente químico volátil carregado pelos escavadores e pela guarnição de anões posicionados em Bael Modan, nos Sertões Meridionais. Embora tenha sido importado pela expedição de Altaforja para abrir caminho através de pedras ancestrais, o tauren exilado Gann Agulha de Pedra busca recuperá-lo para montar uma carga explosiva contra os invasores.",h="O Nitrato de Sódio é um reagente químico volátil carregado pelos escavadores e pela guarnição de anões...",kw={"bael modan","bael'dun","blackforge","gann agulha de pedra","nitroglicerina","a vingança de gann","nitrato de sódio","polpa de madeira"},ang={["profession:Engineering"]="Os engenheiros reconhecem facilmente a combinação de nitrato de sódio, nitroglicerina e polpa de madeira como a receita clássica para dinamite estabilizada, ressaltando a sólida lógica por trás das cargas de demolição improvisadas de Gann.",["race:Tauren"]="Para os taurens, usar produtos químicos dos anões é um doloroso afastamento dos métodos tradicionais, mas Gann Agulha de Pedra considera justificadas essas medidas desesperadas para revidar a destruição de seu território ancestral."},sec={{t="Demolição Industrial",b="A expedição de Bael'dun invadiu as terras ancestrais da tribo Agulha de Pedra armada com pesadas escavadeiras e reagentes de detonação. Para romper as rochas resistentes dos Sertões Meridionais, os anões dependiam de compostos químicos voláteis. O Nitrato de Sódio atua como um agente estabilizador e oxidante crucial em explosivos de alto nível, sendo carregado rotineiramente por fuzileiros, soldados e oficiais de Bael'dun dentro das escavações e na fortaleza próxima."},{t="Reviravolta e Retribuição",b="Após a devastação da terra natal de sua tribo, Gann Agulha de Pedra observou os invasores de perto e vasculhou seus esquemas de engenharia. Reconhecendo que ataques convencionais não romperiam facilmente a fortaleza fortemente defendida, Gann tramou usar os suprimentos industriais de detonação dos próprios anões contra eles. Misturando Nitrato de Sódio saqueado com nitroglicerina e polpa de madeira, o tauren exilado cria cargas improvisadas destinadas a abalar as fundações de Bael Modan."}},faq={{q="Para que serve o Nitrato de Sódio nos Sertões?",a="Os anões de Altaforja o usam como componente químico em explosivos para abrir caminho pelo terreno rochoso do sítio de escavação. Gann Agulha de Pedra planeja combiná-lo com nitroglicerina e polpa de madeira a fim de criar poderosas cargas de demolição para atacar a fortaleza de Bael Modan.",al={"utilidade do nitrato de sódio","o que faz o nitrato de sódio"}},{q="De onde vem o Nitrato de Sódio?",a="Ele fica em posse da força militar dos anões posicionada em Bael Modan, nos Sertões Meridionais. Soldados, fuzileiros, oficiais e seus comandantes, como Lord Cyrik Blackforge, trazem suprimentos desse reagente consigo.",al={"quem saqueia nitrato de sódio","onde conseguir nitrato de sódio"}},{q="Por que Gann Agulha de Pedra precisa desse produto químico?",a="Gann perdeu sua aldeia ancestral para as escavações dos anões. Sem equipamento pesado de cerco, ele estudou os esquemas dos anões para replicar suas cargas de mineração, com o objetivo de desmantelar as posições fortificadas deles usando seus próprios armamentos.",al={"por que gann quer nitrato de sódio","explosivos de gann agulha de pedra"}},{q="O Nitrato de Sódio é perigoso sozinho?",a="Por si só, o nitrato de sódio é um oxidante e sal químico, e não um explosivo imediato. Ele se torna perigoso e volátil quando misturado adequadamente a uma fonte de combustível e a produtos químicos sensíveis ao choque, como a nitroglicerina.",al={"nitrato de sódio é explosivo"}}},fx={caaef0db={q="O que é Nitrato de Sódio?",a="O nitrato de sódio é um agente químico volátil estocado pelas forças expedicionárias anãs estacionadas em Bael Modan. Embora relativamente estável quando armazenado, os anões dependem dele como um componente central para preparar cargas explosivas de alto grau usadas para explodir pedras sólidas em seus locais de escavação. Nas mãos de um sabotador inteligente, no entanto, ele pode ser facilmente reaproveitado para desmantelar a própria fortaleza.",al={"o que é nitrato de sódio","história do nitrato de sódio","nitrato de sódio nos sertões"}}},fp="14,175,21.313.0,25.375.1,47.185.0,36.176.0,44.233.0,39.199.0"}
P.entries["item:soft-shelled-clam-meat"] = {n="Soft-Shelled Clam Meat",s="Soft-Shelled Clam Meat é uma isca tentadora para os peixes perto da Aldeia Pescassombra. Mai'Lahii pede que você traga um pouco do navio naufragado ao norte.",h="Soft-Shelled Clam Meat é uma isca tentadora para os peixes perto da Aldeia Pescassombra.",kw={"isca de amêijoa","desolação","pesca","mai'lahii","aldeia pescassombra","soft-shelled clam meat","navio naufragado"},sec={{t="Isca para Mai'Lahii",b="Mai'Lahii, da Aldeia Pescassombra, prefere Soft-Shelled Clam Meat para pescar. Ele diz que os peixes não conseguem resistir e pede que você traga dez unidades das amêijoas perto do navio naufragado ao norte da aldeia."}},faq={{q="Para que serve Soft-Shelled Clam Meat?",a="Mai'Lahii, da Aldeia Pescassombra, usa Soft-Shelled Clam Meat como isca para pescar.",al={"uso da carne de amêijoa","carne de concha mole","isca de amêijoa"}},{q="Onde posso encontrar amêijoas de concha mole?",a="Há amêijoas de concha mole perto do navio naufragado na costa ao norte da Aldeia Pescassombra.",al={"localização das amêijoas","onde encontrar amêijoas","amêijoas do navio ao norte"}},{q="Quem quer a carne de amêijoa?",a="Mai'Lahii, da Aldeia Pescassombra, pede que você traga dez unidades de Soft-Shelled Clam Meat.",al={"para quem é a carne de amêijoa","isca para mai'lahii","quem precisa de amêijoas"}},{q="Por que Mai'Lahii quer pescar?",a="Mai'Lahii diz que seu médico-bruxo o aconselhou a pescar por causa da dor de cabeça, e ele se sente melhor depois que você traz a carne de amêijoa.",al={"dor de cabeça de mai'lahii","por que pescar","conselho do médico-bruxo"}}},fp="22,153,18.205.0,35.80.0,36.87.0,24.91.0,38.126.1"}
P.entries["item:solid-crystal-leg-shaft"] = {n="Solid Crystal Leg Shaft"}
P.entries["item:solomon-s-plea-to-darkshire"] = {n="Apelo de Salomão a Vila Sombria",s="O Apelo de Salomão a Vila Sombria é uma missiva urgente redigida pelo Magistrado Salomão de Vila Plácida e endereçada ao Lorde Malaquias Ebanez. Diante das crescentes ameaças dos orcs Rocha Negra e dos gnolls, a carta implora à liderança de Vila Sombria que envie sua milícia de elite, a Vigília Noturna, para reforçar as combalidas defesas de Vila Plácida.",h="O Apelo de Salomão a Vila Sombria é uma missiva urgente redigida pelo Magistrado Salomão de Vila Plácida e...",kw={"vila sombria","floresta do crepúsculo","vila plácida","lorde malaquias ebanez","magistrado salomão","mensagem para vila sombria","a vigilia noturna","montanhas cristarrubra","apelo de salomao"},ang={["faction:Alliance"]="A mensagem ilustra a fragmentação das terras do sul da Grande Aliança, onde povoados distantes precisam implorar entre si pela sobrevivência enquanto Ventobravo permanece indiferente.",["race:Human"]="Para os viajantes humanos, transportar este despacho destaca o perigo compartilhado que ameaça tanto as terras fronteiriças das Montanhas Cristarrubra quanto os bosques sombrios da Floresta do Crepúsculo."},sec={{t="Um Apelo Desesperado por Ajuda",b="Vila Plácida está prestes a ser subjugada por orcs Rocha Negra, gnolls e murlocs invasores, com praticamente nenhum reforço oficial chegando de Ventobravo. Em desespero, o Magistrado Salomão redigiu este apelo formal ao prefeito Lorde Malaquias Ebanez, de Vila Sombria, solicitando o envio de membros da Vigília Noturna para o norte, rumo às Montanhas Cristarrubra. O documento reflete o colapso severo do apoio militar central pelo sul de Azeroth, forçando os assentamentos humanos a recorrerem uns aos outros pela sobrevivência mútua."},{t="A Terrível Situação de Vila Sombria",b="Embora o pedido de Salomão seja urgente, ele evidencia o isolamento de Vila Plácida em relação aos verdadeiros horrores que assolam seus vizinhos. A própria Floresta do Crepúsculo está sitiada por mortos-vivos, feras vorazes e uma escuridão penetrante, deixando a Vigília Noturna já no limite de suas forças apenas para manter as fronteiras do vilarejo. Em vez de encontrar uma reserva intacta de novos soldados, os mensageiros que entregam o apelo deparam-se com uma cidade igualmente assolada e totalmente incapaz de dispensar defensores para as Montanhas Cristarrubra."}},faq={{q="O que é o Apelo de Salomão a Vila Sombria?",a="É uma carta oficial escrita pelo Magistrado Salomão de Vila Plácida para o Lorde Malaquias Ebanez, o prefeito de Vila Sombria. A mensagem pede com urgência que Vila Sombria conceda a ajuda de sua milícia, a Vigília Noturna, para auxiliar na defesa das Montanhas Cristarrubra contra os orcs Rocha Negra e os gnolls.",al={"carta de salomao para vila sombria","o que e o apelo de salomao","carta de vila placida para floresta do crepusculo"}},{q="Por que Vila Plácida está pedindo ajuda militar a Vila Sombria em vez de Ventobravo?",a="O governo central de Ventobravo falhou em fornecer guarnições de tropas adequadas aos seus territórios periféricos devido à inércia política e a conflitos internos. Deixado para defender Vila Plácida sozinho contra incursões crescentes, o Magistrado Salomão recorreu aos municípios humanos vizinhos na esperança de garantir forças aliadas.",al={"por que pedir a vila sombria","por que nao ventobravo","por que salomao precisa da vigilia noturna"}},{q="Quem é o Lorde Malaquias Ebanez?",a="O Lorde Malaquias Ebanez é o prefeito e principal líder civil de Vila Sombria, na Floresta do Crepúsculo. Ele supervisiona a cidade e coordena a Vigília Noturna, a força de defesa civil dedicada a conter os horrores que espreitam na floresta.",al={"quem e ebanez","prefeito de vila sombria","lorde malaquias"}},{q="Vila Sombria pode realmente dispensar a Vigília Noturna para ajudar Vila Plácida?",a="Não. A Floresta do Crepúsculo está presa em seu próprio pesadelo, cercada por mortos-vivos, worgens ferozes e magia sombria. A Vigília Noturna mal tem combatentes suficientes para manter o perímetro de Vila Sombria e não pode dispensar um único guerreiro para marchar até as Montanhas Cristarrubra.",al={"vila sombria ajuda","a vigilia noturna vai vir","ebanez enviou guardas"}}},fx={a3b7e1d6={q="De onde vem o Apelo de Salomão a Vila Sombria e quem o escreveu?",a="A carta foi escrita diretamente pelo Magistrado Salomão, o líder da cidade de Vila Plácida, nas Montanhas Cristarrubra. Com os orcs do Rocha Negra pressionando fortemente sua cidade e Ventobravo incapaz de fornecer reforços reais, Salomão escreveu o apelo urgente pessoalmente da prefeitura de Vila Plácida na esperança de garantir ajuda dos assentamentos vizinhos.",al={"quem escreveu o apelo de salomão","origem do apelo de salomão a vila sombria","quem criou o apelo de salomão"}},["5061acb5"]={q="Por que Lorde Malaquias Ebanez quer o Apelo de Salomão a Vila Sombria?",a="Lorde Malaquias Ebanez precisa da carta porque ela detalha formalmente a defesa desesperada de Vila Plácida e o pedido direto do Magistrado Salomão por assistência militar. Como prefeito de Vila Sombria e comandante da The Night Watch, Ebanez conta com despachos oficiais como este para entender as ameaças que seus vizinhos da Aliança enfrentam e avaliar se sua cidade pode ceder guardas.",al={"por que entregar o apelo de salomão","por que ebanez precisa da carta","propósito do apelo de salomão a vila sombria"}}},fp="27,149,24.361.0,23.222.1,36.139.0,73.206.0,27.193.0,63.165.1"}
P.entries["item:solomon-s-plea-to-westfall"] = {n="Apelo de Salomão a Cerro Oeste",s="Apelo de Salomão a Cerro Oeste é um apelo urgente por escrito redigido pelo Magistrado Salomão de Vila Plácida. Desesperado por reforços contra os orcs Blackrock e gnolls, Salomão envia este despacho a Gryan Stoutmantle em Cerro Oeste na esperança de que a recém-formada The People's Militia possa prestar auxílio enquanto o exército real de Ventobravo não responde.",h="Apelo de Salomão a Cerro Oeste é um apelo urgente por escrito redigido pelo Magistrado Salomão de Vila...",kw={"gryan stoutmantle","vila plácida","magistrado salomão","the people's militia","montanhas cristarrubra","apelo de salomão","exército de ventobravo","cerro oeste"},ang={["faction:Alliance"]="O documento destaca a crescente paralisia administrativa no coração da Aliança, onde cidades periféricas precisam depender de voluntários locais em vez de tropas reais.",["race:Human"]="Para os humanos das províncias do sul, este apelo revela como os assentamentos rurais ficaram sobrecarregados à medida que o rei desaparecido e a negligência política deixam as terras fronteiriças vulneráveis."},sec={{t="Um Chamado Desesperado por Socorro",b="Enquanto a ameaça do clã Blackrock e de gnolls hostis paira sobre as Montanhas Cristarrubra, o Magistrado Salomão se vê perigosamente isolado em Vila Plácida. O exército real de Ventobravo inexplicavelmente falhou em chegar em peso para defender as fronteiras da região. Incapaz de esperar pelo apoio oficial da capital do reino, Salomão escreve este apelo em uma tentativa desesperada de recrutar assistência de fora da estrutura militar regular. Tendo ouvido rumores sobre uma força defensiva voluntária se formando além de Elwynn a oeste, ele recorre diretamente à The People's Militia."},{t="Cruzando a Fronteira",b="A mensagem é endereçada diretamente a Gryan Stoutmantle, um Guerreiro veterano que organiza a defesa da fronteira de Cerro Oeste. Salomão espera que Stoutmantle possa ceder combatentes para reforçar Vila Plácida até que a coroa de Ventobravo finalmente envie reservas regulares. Confiado a um aventureiro atuando como mensageiro, o documento reflete a fratura na coordenação administrativa pelos territórios periféricos de Ventobravo, onde magistrados locais são deixados para negociar acordos de ajuda mútua por iniciativa própria."}},faq={{q="O que é o Apelo de Salomão a Cerro Oeste?",a="É uma petição oficial escrita pelo Magistrado Salomão de Vila Plácida, pedindo a Gryan Stoutmantle e à The People's Militia em Cerro Oeste que enviem reforços militares para ajudar a defender as Montanhas Cristarrubra.",al={"o que é o apelo de salomão","carta do apelo de salomão a cerro oeste","carta de vila plácida para cerro oeste"}},{q="Por que o Magistrado Salomão está pedindo ajuda a Cerro Oeste em vez de a Ventobravo?",a="Salomão observa que algo estranho está acontecendo com o exército de Ventobravo, já que as tropas reais não conseguiram chegar em peso, apesar do perigo crescente em Vila Plácida. Sem tempo para esperar pela Coroa, Salomão recorre a qualquer força de combate próxima disposta a ajudar.",al={"por que pedir ajuda a cerro oeste","por que não pedir a ventobravo","por que enviar o apelo para cerro oeste"}},{q="Quem é Gryan Stoutmantle?",a="Gryan Stoutmantle é o líder da The People's Militia, uma liga defensiva popular organizada por fazendeiros e colonos locais para proteger Cerro Oeste da Irmandade Défias.",al={"quem é stoutmantle","papel de gryan stoutmantle"}},{q="Quais ameaças estão levando Salomão a enviar esta carta?",a="Vila Plácida enfrenta incursões agressivas dos orcs Blackrock, juntamente com saques de gnolls por todas as Montanhas Cristarrubra, sobrecarregando a guarda municipal local além de seus limites.",al={"por que vila plácida está em perigo","o que ameaça as montanhas cristarrubra"}}},fx={["7804da1c"]={q="De onde vem o Apelo de Salomão a Cerro Oeste e quem o escreveu?",a="A carta foi escrita diretamente pelo Magistrado Salomão em Vila Plácida, a cidade sitiada nas Montanhas Cristarrubra. Desesperado depois que o Exército de Ventobravo não enviou os reforços prometidos para defender seu povo, Salomão escreveu esta mensagem urgente pessoalmente para implorar por ajuda aos aliados próximos.",al={"quem escreveu o apelo de salomão a cerro oeste","de onde vem o apelo de salomão","criador do apelo de salomão"}},["6d6e291d"]={q="Por que Gryan Stoutmantle quer o Apelo de Salomão a Cerro Oeste?",a="Gryan Stoutmantle lidera a The People's Militia em Cerro Oeste, e este despacho o informa sobre a situação terrível de Vila Plácida. Salomão espera que a milícia possa ceder combatentes para reforçar as defesas diminuídas de Montanhas Cristarrubra enquanto o município aguarda notícias e tropas da corte do Rei Anduin em Ventobravo.",al={"por que entregar o apelo de salomão","por que stoutmantle quer o apelo","para que serve a carta"}}},fp="26,207,24.381.0,26.355.0,35.148.0,72.165.0,25.151.0,53.124.0"}
P.entries["item:soran-ruk-fragment"] = {n="Fragmento de Soran'ruk",s="Um Fragmento de Soran'ruk é uma lasca despedaçada de um orbe de prisão demoníaca que outrora esteve vinculado ao espírito de um servo desgraçado da Legião Ardente. Embora partido e disperso entre cultistas nas profundezas sob o Vale Gris, cada estilhaço ainda irradia energia vil residual.",h="Um Fragmento de Soran'ruk é uma lasca despedaçada de um orbe de prisão demoníaca que outrora esteve vinculado...",kw={"profundezas negras","doan karhan","vil","orbe de soran'ruk","soran'ruk","soranruk","twilight acolyte"},ang={["class:Warlock"]="Receptáculos de prisão demoníaca como O orbe de Soran'ruk representam condutores valiosos para bruxos que buscam vincular e manipular energias vis puras sem a subjugação demoníaca direta."},sec={{t="Uma Prisão Despedaçada",b="Quando demônios da Legião Ardente caem em desgraça perante seus mestres, seus espíritos às vezes são condenados ao aprisionamento dentro de orbes especializados e distribuídos a conjuradores vis como condutores de poder puro. O orbe de Soran'ruk teve esse destino, mas, em algum momento de sua história, foi partido. Uma metade foi quebrada em estilhaços menores e caiu nas mãos dos cultistas do Twilight's Hammer que espreitam nas ruínas submersas de Profundezas Negras, que extraem a essência demoníaca remanescente para seus próprios intentos sombrios."},{t="Reconstrução nos Sertões",b="Apesar de estar fragmentada, cada parte retém um vestígio da vitalidade da entidade aprisionada. Nos Sertões Meridionais, o recluso estudioso Doan Karhan passou a vida inteira estudando esses receptáculos demoníacos, e ele possui um orbe semelhante, o Orb of Zargain. Ao recuperar três pequenos fragmentos juntamente com a parte maior mantida em Floresta de Pinhaprata, um bruxo ambicioso pode fazer com que a relíquia seja forjada inteira novamente, tornando-se um instrumento de poder."}},faq={{q="O que é Soran'ruk?",a="Soran'ruk era um demônio da Legião Ardente que caiu em desgraça com a liderança demoníaca. Como punição, seu espírito foi extraído e aprisionado dentro de um orbe cristalino para servir a bruxos e magos mortais como um reservatório de energia.",al={"quem e soranruk","historia de soran'ruk","soranruk e um demonio"}},{q="Onde esses fragmentos são encontrados?",a="Os estilhaços menores são carregados por Twilight Acolytes dentro dos salões cavernosos de Profundezas Negras ao longo da Praia de Zoram.",al={"onde conseguir fragmento de soranruk","quem dropa fragmentos de soran'ruk","localizacao do fragmento de soranruk"}},{q="Por que o Twilight's Hammer possui esses estilhaços?",a="Mesmo quando quebrados, os estilhaços retêm a essência mágica do demônio aprisionado. Os cultistas do Twilight's Hammer saqueiam esses artefatos corrompidos para alimentar seus rituais sombrios e canalizar magia proibida.",al={"por que os cultistas tem isso","twilights hammer soranruk"}},{q="Quem pode restaurar O orbe de Soran'ruk?",a="Doan Karhan, um eremita solitário que vive nos Sertões Meridionais, perto da fronteira com Mil Agulhas, é especialista em estudar e reforjar os orbes demoníacos da Legion.",al={"quem conserta o orbe","onde entregar fragmento de soranruk","doan karhan orbe"}}},fx={["49c59cce"]={q="De onde vêm os Fragmentos de Soran'ruk e quem os criou?",a="Eles são restos despedaçados do Orbe de Soran'ruk, um receptáculo demoníaco forjado pela Legião Ardente. Quando demônios caem em desgraça, a Legião aprisiona seus espíritos dentro de tais orbes e os confia aos seus magos e bruxos. O Orbe de Soran'ruk foi posteriormente quebrado em pedaços, e esses fragmentos menores acabaram nas mãos dos acólitos do Martelo do Crepúsculo dentro das Profundezas Negras.",al={"origem do fragmento de soranruk","quem criou os fragmentos de soranruk","de onde vieram os fragmentos de soranruk"}},["5e1e8c12"]={q="Por que alguém quer Fragmentos de Soran'ruk?",a="Mesmo partidos em estilhaços, os fragmentos ainda vibram com a essência e o poder do demônio aprisionado. O bruxo eremita Doan Karhan, nos Sertões, dedicou sua vida a estudar e reconstruir orbes da Legião. Se você levar a ele esses estilhaços menores junto com o grande fragmento da Bastilha da Presa Negra, ele poderá reforjar o Orbe de Soran'ruk e torná-lo um instrumento potente para o seu ofício.",al={"por que coletar fragmentos de soranruk","quem quer os fragmentos de soranruk","por que você precisa de fragmentos de soranruk"}}},fp="18,150,18.407.0,29.373.1,18.217.0,32.115.0,49.168.0,37.191.0"}
P.entries["item:southsea-treasure"] = {n="Tesouro dos Mares do Sul",s="O Tesouro dos Mares do Sul é um valioso espólio guardado nas profundezas do porão da embarcação dos Flibusteiros dos Mares do Sul, o Tide Razor. Procurado por Wrenix, o Ignóbil em Vila Catraca, recuperá-lo testa as habilidades de arrombamento e infiltração de ladrões novatos.",h="O Tesouro dos Mares do Sul é um valioso espólio guardado nas profundezas do porão da embarcação dos...",kw={"b.e.c.a.","arrombamento","polly","vila catraca","a mão despedaçada","tesouro dos mares do sul","tide razor","wrenix, o ignóbil"},ang={["class:Rogue"]="Recuperar o Tesouro dos Mares do Sul representa um rito de passagem para ladinos em desenvolvimento, proporcionando tanto prática real de arrombamento quanto uma introdução ao sombrio sindicato conhecido como A Mão Despedaçada.",["faction:Horde"]="Os Flibusteiros dos Mares do Sul hostilizam rotineiramente o comércio ao redor dos Sertões e do Porto de Vila Catraca, tornando qualquer roubo do seu estoque principal uma perturbação bem-vinda para as autoridades locais."},sec={{t="Um Golpe Mortal",b="Ancorado ao longo da Costa dos Mercadores, ao sul de Vila Catraca, o navio pirata Tide Razor serve como base avançada e campo de treinamento para Os Flibusteiros dos Mares do Sul. Escondido no fundo do seu porão mais baixo jaz um cobiçado estoque de saques conhecido como o Tesouro dos Mares do Sul. Wrenix, o Ignóbil, um patife gnomo que opera a partir de Vila Catraca, considera isso o teste supremo para aspirantes a batedores de carteira. De acordo com Wrenix, os últimos cinco agentes enviados para furtar o baú voltaram em pedaços, graças aos piratas atentos a bordo e a um guardião surpreendentemente feroz que vigia o porão."},{t="A Lembrança de Polly",b="Ladrões que conseguem passar pelos instrutores piratas e arrombar a fechadura do baú visado encontram uma surpresa cruel à sua espera. Em vez de estar solto dentro do cofre, o verdadeiro Tesouro dos Mares do Sul é vigiado por Polly, um papagaio extraordinariamente hostil. Vencer a ave feroz — muitas vezes com o auxílio da engenharia gnômica, como o dispositivo B.E.C.A. de Wrenix — é a única maneira de libertar o tesouro e levá-lo de volta a Vila Catraca intacto."}},faq={{q="Onde fica o Tesouro dos Mares do Sul?",a="O tesouro fica a bordo do Tide Razor, um navio dos Flibusteiros dos Mares do Sul ancorado ao longo da costa ao sul de Vila Catraca, nos Sertões. Ele repousa no porão mais baixo, abaixo dos alojamentos de treinamento dos piratas.",al={"onde fica o tesouro","localização do tide razor","como encontrar o tesouro dos mares do sul"}},{q="Quem deseja o Tesouro dos Mares do Sul?",a="Wrenix, o Ignóbil, um goblin inescrupuloso instalado em Vila Catraca, contrata agentes secretos para se infiltrarem no navio e recuperarem o saque em seu nome.",al={"quem dá a missão","quem é wrenix","quem quer isso"}},{q="Por que o baú está vazio quando é arrombado?",a="Arrombar a fechadura do baú de tesouro desencadeia o surgimento de Polly, um papagaio monstruosamente agressivo que guarda o porão. Derrotar Polly é o que realmente concede o Tesouro dos Mares do Sul.",al={"de onde veio polly","por que polly apareceu","por que o tesouro não está na caixa"}},{q="O que é uma B.E.C.A. e por que ela é necessária?",a="A B.E.C.A. é um dispositivo experimental goblin fornecido por Wrenix, o Ignóbil. Ele foi projetado para enfraquecer ameaças aéreas invulgarmente ferozes — especificamente o letal papagaio guardião Polly, à espreita dentro do porão do navio pirata.",al={"o que é beca","como derrotar polly","papagaio hostil"}},{q="Para que Os Flibusteiros dos Mares do Sul usam o navio?",a="O Tide Razor serve como base de operações e covil de ladrões para Os Flibusteiros dos Mares do Sul, contando com caixas trancadas de treino no segundo nível, onde a tripulação treina seus batedores de carteira.",al={"o que é tide razor","covil pirata sertões","porão do navio dos mares do sul"}}},fx={c9f033cd={q="O que é o Tesouro dos Mares do Sul?",a="O Tesouro dos Mares do Sul é o espólio saqueado acumulado pelos Southsea Freebooters a bordo de seu navio, o Lâmina da Maré, ancorado na costa dos Sertões. Mantido no fundo do porão do navio e vigiado por um papagaio pirata notoriamente feroz chamado Polly, ele representa os ganhos ilícitos acumulados pelos corsários a partir de seus saques ao longo da Costa dos Mercadores.",al={"o que é o tesouro dos mares do sul","item tesouro dos mares do sul","que tipo de tesouro é o tesouro dos mares do sul"}}},fp="17,189,14.462.0,16.299.1,39.172.0,32.139.0,35.155.1,41.195.0,50.159.0"}
P.entries["item:spectral-comb"] = {n="Pente Espectral",s="O Pente Espectral é uma ferramenta etérea de cuidados usada para interagir com os mortos inquietos da Floresta do Crepúsculo. Feito para atravessar formas intangíveis, ele é levado ao aflito espírito Maria Cega para coletar fios de cabelo de fantasma.",h="O Pente Espectral é uma ferramenta etérea de cuidados usada para interagir com os mortos inquietos da...",kw={"maria cega","pente","vila sombria","floresta do crepúsculo","fantasma","linha de cabelo de fantasma","pente espectral"},ang={["faction:Alliance"]="Aventurar-se ao sul de Vila Sombria com o pente serve como um lembrete sombrio dos destinos trágicos sofridos pelos antigos colonos da Floresta do Crepúsculo.",["profession:Tailoring"]="O Pente Espectral demonstra que a alfaiataria em lugares sombrios exige métodos de coleta incomuns, obtendo fibras etéreas de fantasmas dispostos em vez da tosquia tradicional."},sec={{t="Uma Ferramenta para os Mortos Inquietos",b="Instrumentos comuns não podem tocar ou pentear um espírito, tornando a coleta de materiais etéreos quase impossível para artífices mortais. O Pente Espectral é especialmente adequado para interagir com formas fantasmagóricas, deslizando através de mechas que de outra forma seriam intangíveis. Ele é levado ao sul de Vila Sombria até a fazenda em ruínas onde o fantasma choroso de Maria Cega lamenta em isolamento. Encontrando consolo no ato familiar de pentear seus cabelos arruinados, Maria usa o pente de bom grado, deixando para trás as fibras espectrais necessárias para tecer a Linha de Cabelo de Fantasma."}},faq={{q="Para que serve o Pente Espectral?",a="O pente é entregue a Maria Cega, um fantasma choroso que habita ao sul de Vila Sombria. Quando ela o usa para pentear o cabelo, ele recolhe fios etéreos que mais tarde podem ser fiados em uma linha sobrenatural.",al={"objetivo do pente espectral","por que preciso do pente espectral","o que o pente faz"}},{q="Quem é Maria Cega?",a="Maria Cega é um espírito atormentado que assombra uma casa abandonada nas colinas ao sul de Vila Sombria. Enlouquecida pela tragédia, ela arrancou os próprios olhos e permanece apavorada de que os outros a achem hedionda na morte.",al={"história de maria cega","quem é o fantasma com o pente","maria cega"}},{q="Por que um pente comum não pode ser usado?",a="Espíritos não podem ser tocados por ferramentas físicas e mundanas sem magias ou encantamentos especializados. O Pente Espectral foi projetado especificamente para interagir com o cabelo intangível de uma aparição.",al={"por que pente espectral","pente comum fantasma"}}},fx={e893aa2f={q="O que é o Pente Espectral?",a="O Pente Espectral é uma ferramenta de higiene etérea especificamente encantada para interagir com o incorpóreo. Enquanto utensílios comuns passariam direto por um fantasma sem efeito, este pente pode tocar, desembaraçar e coletar os fios espectrais do cabelo de um fantasma.",al={"o que é o pente espectral","pente espectral","identidade do pente espectral"}}},fp="13,95,24.375.0,35.177.0,18.186.0,37.119.0"}
P.entries["item:spells-of-shadow"] = {n="Feitiços da Sombra",s="Feitiços da Sombra é um tomo sombrio carregado pelos cultistas da Searing Blade à espreita sob Orgrimmar nas Cavernas Ígneas. Repleto de magia vil concedida pela Legião Ardente, ele é alvo de recuperação pela liderança dos Renegados em Cidade Baixa.",h="Feitiços da Sombra é um tomo sombrio carregado pelos cultistas da Searing Blade à espreita sob Orgrimmar nas...",kw={"encantamentos do éter","cavernas ígneas","searing blade","feitiços da sombra","sylvanas","o poder de destruir","cidade baixa","varimatras"},ang={["class:Warlock"]="O tomo representa o patrocínio demoníaco direto da Legião, demonstrando como cultos renegados feito a Searing Blade utilizam as artes sombrias e do éter.",["race:Undead"]="Recuperar o grimório serve diretamente a Lady Sylvanas, reivindicando conhecimento demoníaco perigoso sob Orgrimmar para fortalecer Cidade Baixa contra o Flagelo."},sec={{t="Tomos da Searing Blade",b="Ocultos nas profundezas das cavernas de magma das Cavernas Ígneas, membros da Searing Blade — um culto dissidente ligado ao Shadow Council — utilizam ritos sombrios concedidos por mestres demoníacos da Legião Ardente. Entre os seus tesouros mais vigiados está Feitiços da Sombra, um texto que contém feitiçaria nefasta de sombras e vil. Cultistas e bruxos da seita mantêm este livro sempre por perto enquanto conspiram sob os pés da Horda em Durotar."},{t="A Ambição da Dama Sombria",b="Notícias sobre as dádivas demoníacas da Searing Blade chegaram aos aposentos reais de Cidade Baixa. Grande Dama Sylvana Correventos e seu tenente lorde do medo, Varimatras, determinaram que relíquias tão poderosas estavam sendo desperdiçadas em cultistas de visão inferior. Varimatras encarrega aventureiros da Horda de se aventurarem no abismo para confiscar Feitiços da Sombra junto ao seu tomo irmão, Encantamentos do Éter, direcionando o poder deles para a causa dos Renegados contra o Flagelo e o Lich King."}},faq={{q="O que é Feitiços da Sombra?",a="É um livro de magias demoníaco em posse dos cultistas da Searing Blade nas Cavernas Ígneas, contendo dádivas de Magia Sombria concedidas pela Legião Ardente.",al={"livro feitiços da sombra","o que é feitiços da sombra","livro feitiços da sombra rfc"}},{q="Quem deseja este livro?",a="Varimatras, o lorde do medo conselheiro de Grande Dama Sylvana Correventos, busca o tomo em nome da Dama Sombria. Ele reside no Distrito Real de Cidade Baixa.",al={"quem precisa de feitiços da sombra","quem entrega feitiços da sombra","feitiços da sombra entregador de missão"}},{q="Onde o livro pode ser encontrado?",a="Ele é carregado por cultistas e bruxos da Searing Blade dentro das Cavernas Ígneas, a rede de cavernas ardentes localizada sob a cidade de Orgrimmar.",al={"localização de feitiços da sombra","onde conseguir feitiços da sombra","como conseguir feitiços da sombra"}},{q="Por que os Renegados querem este grimório?",a="Lady Sylvanas acredita que as dádivas sombrias concedidas pela Legião são mais bem aproveitadas pelos Renegados do que por cultistas inferiores, usando essa magia para fortalecer a guerra dela contra o Flagelo e o Lich King.",al={"por que sylvanas quer o livro","por que varimatras quer feitiços da sombra"}}},fp="16,148,26.335.0,24.437.0,29.130.0,20.133.0,28.114.0,39.193.0"}
P.entries["item:spirit-of-silverpine-charts"] = {n="Spirit of Silverpine Charts",s="As Cartas do Spirit of Floresta de Pinhaprata são os mapas do navio, agora procurados em seu naufrágio no Planalto Arathi. Primeiro Oficial Nadaliso quer recuperá-las antes que a informação chegue a olhos curiosos.",h="As Cartas do Spirit of Floresta de Pinhaprata são os mapas do navio, agora procurados em seu naufrágio no...",kw={"planalto arathi","cartas","deep sea salvage","primeiro oficial nadaliso","mestre de frota chifre do mar","spirit da floresta de pinhaprata","cartas do spirit da floresta de pinhaprata"},sec={{t="Encalhado na Enseada",b="As cartas do naufrágio são procuradas junto com o diário de bordo, então Primeiro Oficial Nadaliso pede que você recupere ambos. A tripulação conta que o Spirit of Floresta de Pinhaprata encalhou em um templo no recife quando a maré baixou. As cartas contêm informações que a tripulação teme que possam cair em mãos inimigas, e Mestre de Frota Chifre do Mar espera que sejam levadas de volta à Angra do Butim."}},faq={{q="O que são as Cartas do Spirit of Floresta de Pinhaprata?",a="São cartas náuticas do Spirit of Floresta de Pinhaprata, um navio naufragado no Planalto Arathi.",al={"cartas de pinhaprata","cartas do spirit"}},{q="Onde posso encontrar as cartas?",a="As Cartas do Spirit of Floresta de Pinhaprata são procuradas nos destroços do Spirit of Floresta de Pinhaprata, no Planalto Arathi.",al={"onde ficam as cartas","localização do mapa de pinhaprata"}},{q="Quem quer as cartas?",a="Primeiro Oficial Nadaliso quer que as cartas e os diários de bordo do Spirit of Floresta de Pinhaprata e do Maiden's Folly sejam recuperados.",al={"quem precisa das cartas","cartas de nadaliso"}},{q="Por que querem as cartas?",a="A tripulação teme que as cartas revelem informações a olhos curiosos se forem deixadas para trás.",al={"por que as cartas são importantes","o que há nas cartas"}},{q="Como o Spirit of Floresta de Pinhaprata afundou?",a="A tripulação conta que o Spirit of Floresta de Pinhaprata encalhou em um templo no recife quando a maré começou a baixar.",al={"naufrágio de pinhaprata","por que o navio afundou"}},{q="Para onde as cartas serão levadas?",a="As cartas recuperadas devem ser entregues a Mestre de Frota Chifre do Mar e ao comando na Angra do Butim.",al={"cartas para angra do butim","quem recebe as cartas"}}},fp="27,187,19.336.0,41.98.0,28.110.0,21.108.0,26.81.0,38.105.0,33.99.0"}
P.entries["item:spirit-of-silverpine-log"] = {n="Spirit of Silverpine Log",s="O registro de bordo do Spirit of Floresta de Pinhaprata é o diário do capitão de um navio naufragado no recife de Planalto Arathi. Seus mapas e registros guardam informações que a tripulação quer manter longe das mãos inimigas.",h="O registro de bordo do Spirit of Floresta de Pinhaprata é o diário do capitão de um navio naufragado no...",kw={"planalto arathi","angra do butim","diário do capitão","deep sea salvage","primeiro oficial nadaliso","mestre de frota chifre do mar","naufrágio","spirit of pinhaprata","registro de bordo do spirit of pinhaprata"},sec={{t="Os navios naufragados",b="O Primeiro Oficial Nadaliso quer recuperar o diário de bordo e os mapas do navio antes que a tripulação deixe a enseada. O Spirit of Floresta de Pinhaprata e o Maiden’s Folly encalharam quando a maré baixou, atingindo o que parecia ser um templo no recife. Os dois navios afundaram rapidamente. Seus registros agora são importantes para o comando em Angra do Butim, que teme que as informações cheguem às mãos dos inimigos."}},faq={{q="O que é o registro de bordo do Spirit of Floresta de Pinhaprata?",a="É o diário de bordo do capitão do Spirit of Floresta de Pinhaprata, um dos navios naufragados no Planalto Arathi.",al={"registro de pinhaprata","diário de bordo","diário do capitão"}},{q="Onde o Spirit of Floresta de Pinhaprata afundou?",a="O Spirit of Floresta de Pinhaprata encalhou no que parecia ser um templo no recife, numa enseada do Planalto Arathi.",al={"onde fica pinhaprata","naufrágio de pinhaprata","navio no planalto arathi"}},{q="Por que o Primeiro Oficial Nadaliso quer o diário de bordo?",a="O Primeiro Oficial Nadaliso quer que o diário de bordo e os mapas do Spirit of Floresta de Pinhaprata sejam recuperados antes que a tripulação parta, para que as informações não caiam nas mãos dos inimigos.",al={"por que pegar o diário","o que nadaliso quer","recuperar registro de pinhaprata"}},{q="O que aconteceu com o Spirit of Floresta de Pinhaprata?",a="Quando a maré baixou, o Spirit of Floresta de Pinhaprata encalhou no que parecia ser um templo no recife e afundou rapidamente.",al={"naufrágio de pinhaprata","o que aconteceu com o navio","como o navio afundou"}},{q="Por que os mapas e os diários de bordo são importantes?",a="A tripulação teme que os registros caiam nas mãos dos inimigos, e o Mestre de Frota Chifre do Mar os responsabilizará se isso acontecer.",al={"por que recuperar os mapas","mãos inimigas","registros de angra do butim"}}},fp="24,168,17.358.0,37.111.0,40.113.0,41.155.0,42.117.0,38.126.0"}
P.entries["item:split-bone-necklace"] = {n="Split Bone Necklace",s="Os Split Bone Necklaces são troféus tomados dos trolls Rachacrânio da Selva do Espinhaço. Kin'weelay os pede para ajudar os Lançanegra em sua longa guerra.",h="Os Split Bone Necklaces são troféus tomados dos trolls Rachacrânio da Selva do Espinhaço.",kw={"lançanegra","acampamento grom'gol","kin'weelay","colar","rachacrânio","split bone necklace","selva do espinhaço","troll"},ang={["race:Troll"]="Como troll, você vê a antiga guerra de uma tribo ser levada adiante por outra. Os Lançanegra não vivem mais na Selva do Espinhaço, mas Kin'weelay diz que continuam ligados ao conflito com os Rachacrânios."},sec={{t="Uma contagem Lançanegra",b="No Acampamento Grom'gol, Kin'weelay envia você para sudeste, em direção à tribo Rachacrânio. Seus guerreiros vivem entre as ruínas de trolls da Selva do Espinhaço, e os Lançanegra lutam contra eles há anos. Embora os Lançanegra não vivam mais no vale, Kin'weelay diz que continuam ligados a esse conflito. Leve os colares até ele, e seus feitos ajudarão o povo dele."}},faq={{q="Quem quer os Split Bone Necklaces?",a="Kin'weelay, da tribo Lançanegra, pede que você leve os Split Bone Necklaces até ele no Acampamento Grom'gol.",al={"quem quer esses colares","colar de kin'weelay","colar para quem"}},{q="Quem usa esses colares?",a="Os trolls Rachacrânio carregam Split Bone Necklaces. Kin'weelay os busca como troféus na guerra dos Lançanegra contra os Rachacrânios.",al={"de onde vêm os colares","significado de split bone necklace","colar dos rachacrânios"}},{q="Por que Kin'weelay os quer?",a="Kin'weelay quer os colares para ajudar os Lançanegra em seu longo conflito com a tribo Rachacrânio.",al={"por que coletar split bones","por que kin'weelay precisa deles","guerra dos lançanegra"}},{q="Onde ficam os Rachacrânios?",a="Os Rachacrânios vivem a sudeste do Acampamento Grom'gol, entre as ruínas de trolls da Selva do Espinhaço.",al={"onde encontrar os rachacrânios","localização dos rachacrânios","ruínas de trolls"}},{q="Quantos colares Kin'weelay pede?",a="Kin'weelay pede que você leve vinte e cinco Split Bone Necklaces até ele.",al={"quantidade de colares","quantos split bones","25 colares"}}},fp="19,158,17.364.0,35.106.0,26.137.0,30.105.0,29.100.0,43.66.0"}
P.entries["item:spotted-sunfish"] = {n="Peixe-lua Malhado",s="O Peixe-lua Malhado é um peixe de água doce nativo do Lago Plácido, nas Montanhas Cristarrubra. Renomado localmente por seu sabor, ele é uma mercadoria fundamental para as docas de Vila Plácida, embora a crescente infestação de murlocs torne sua obtenção perigosa.",h="O Peixe-lua Malhado é um peixe de água doce nativo do Lago Plácido, nas Montanhas Cristarrubra.",kw={"mestre das docas baren","lago plácido","vila plácida","murloc","montanhas cristarrubra","o lago está para peixe","peixe-lua malhado"},ang={["profession:Cooking"]="Peixes nativos de água doce como o peixe-lua malhado formam a base culinária do Lago Plácido, tornando-os uma presença constante nas mesas das tavernas de Cristarrubra."},sec={{t="Uma Captura Valiosa",b="O Lago Plácido é celebrado há muito tempo por seus peixes-lua malhados, que alcançam um preço confiável tanto entre comerciantes locais quanto visitantes. O Mestre das Docas Baren mantém um comércio constante deles nos píeres de Vila Plácida, fornecendo alimento e comércio para uma cidade sob pressão. No entanto, as tribos agressivas de murlocs que rondam as águas rasas perturbaram a pesca de rotina, frequentemente acumulando capturas próprias que os aventureiros precisam recuperar à força."}},faq={{q="Onde os Peixes-lua Malhados são encontrados?",a="Eles prosperam nas águas do Lago Plácido, nas Montanhas Cristarrubra. Embora os pescadores possam capturá-los diretamente do lago, os murlocs locais também os pescam constantemente, tornando os acampamentos de murlocs ao redor da margem um excelente local para recuperá-los.",al={"onde conseguir peixe-lua malhado","localização do peixe-lua malhado","peixe do lago plácido"}},{q="Quem compra ou precisa de Peixe-lua Malhado?",a="O Mestre das Docas Baren nas docas de Vila Plácida compra lotes de Peixe-lua Malhado. Ele mantém o comércio dessa iguaria e oferece pagamento a qualquer um disposto a lhe trazer estoque fresco.",al={"quem quer peixe-lua malhado","peixe mestre das docas baren","missão o lago está para peixe"}},{q="Por que os murlocs carregam esses peixes?",a="Os murlocs que vivem ao longo do Lago Plácido forrageiam e caçam a fauna nativa para alimentar suas tribos em expansão. Eles retiram peixes-lua do lago assim como os pescadores humanos fazem, guardando-os em seus acampamentos ao longo das águas rasas.",al={"peixe-lua malhado murloc","por que murlocs dropam peixe"}},{q="É possível obtê-los sem pescar?",a="Sim. O Mestre das Docas Baren observa que os viajantes que não possuem uma vara de pescar podem simplesmente derrotar os murlocs hostis ao longo das margens do Lago Plácido e pegar os peixes que eles coletaram.",al={"conseguir peixe-lua sem vara de pescar","peixe-lua sem vara de pescar"}}},fx={["723094c5"]={q="O que é um Peixe-lua Malhado?",a="O Peixe-lua Malhado é um peixe de água doce valorizado, nativo do Lago Plácido nas Montanhas Cristarrubra. Famoso em toda a região por seu sabor e valor comercial, ele prospera nas águas profundas do lago e serve como uma mercadoria básica para os pescadores de Vila Plácida, além de ser uma fonte primária de alimento para os murlocs locais.",al={"o que é peixe-lua malhado","informações sobre o peixe-lua malhado","história do peixe-lua malhado"}},["1a933976"]={q="De onde vem o Peixe-lua Malhado?",a="O Peixe-lua Malhado é originário naturalmente das águas frescas do Lago Plácido, nas Montanhas Cristarrubra. Em vez de serem criados ou cultivados, são peixes selvagens colhidos diretamente do lago, capturados tanto por pesca ao longo dos ancoradouros e margens quanto recuperados das garras dos Murloc Poachers locais.",al={"origem do peixe-lua malhado","de onde vêm os peixes-lua malhados","fonte do peixe-lua malhado"}}},fp="15,149,14.293.0,32.145.0,34.109.0,36.126.0,36.137.0"}
P.entries["item:spy-s-report"] = {n="Spy's Report",s="O Spy’s Report de Marg Nighteye foi escrito por um espião orc e encontrado perto do Casarão do Pantanal Iluminado, no Pântano Vadeoso. Pedem ao Capitão Garrido Valente, em Theramore, que o leia porque ele conhece o idioma órquico.",h="O Spy’s Report de Marg Nighteye foi escrito por um espião orc e encontrado perto do Casarão do Pantanal...",kw={"captain vimes","pântano vadeoso","espiões da horda","marg nighteye","espião orc","spy’s report","casarão do pantanal iluminado","theramore","morro das bruxas"},ang={["faction:Alliance"]="O relatório alerta sobre espiões da Horda perto de Theramore, um assentamento da Aliança no litoral do Pântano Vadeoso."},sec={{t="Um relatório enterrado",b="Perto do Morro das Bruxas, terra solta ao lado do Casarão do Pantanal Iluminado esconde um relatório escrito por Marg Nighteye. O texto está ligado a espiões orcs perto de Theramore, e pedem ao Capitão Garrido Valente que o examine. Ele conhece o idioma órquico melhor do que a maioria em Theramore."}},faq={{q="Quem escreveu o Spy’s Report?",a="Marg Nighteye escreveu o Spy’s Report.",al={"quem escreveu o relatório","autor do relatório","relatório de marg nighteye"}},{q="Onde o relatório foi encontrado?",a="O Spy’s Report estava enterrado em terra solta ao lado do Casarão do Pantanal Iluminado, no Morro das Bruxas, no Pântano Vadeoso.",al={"onde o relatório foi encontrado","local do relatório do espião","relatório em terra solta"}},{q="Quem deve ler o relatório?",a="O Capitão Garrido Valente, na Ilha Theramore, deve ler o relatório porque conhece o idioma órquico melhor do que a maioria.",al={"quem recebe o relatório","relatório para captain vimes","relatório para vimes"}},{q="Sobre o que é o relatório?",a="O relatório foi escrito por um espião orc e pode contar ao Capitão Garrido Valente sobre espiões da Horda perto de Theramore.",al={"o que há no relatório","relatório do espião orc","espiões da horda em theramore"}}},fp="12,186,15.237.0,29.39.0,27.102.0,27.103.0,29.104.0"}
P.entries["item:stable-ectoplasm"] = {n="Stable Ectoplasm",s="Perto dos fantasmas das Terras Pestilentas Orientais, um Destilador Ectoplásmico pode coletar Stable Ectoplasm. Mux Zoamana precisa dela para alcançar espíritos cujas almas ainda não deixaram este mundo.",h="Perto dos fantasmas das Terras Pestilentas Orientais, um Destilador Ectoplásmico pode coletar Stable...",kw={"banshees","terras pestilentas orientais","ectoplasma","destilador ectoplásmico","geringontzan","fantasmas","mux zoamana","vilarejo do norte","stable ectoplasm"},ang={["profession:Engineering"]="Mux chama o Destilador Ectoplásmico de uma bela peça de engenharia. Seu trabalho mostra como engenhocas goblins podem ser usadas no estudo do mundo espiritual."},sec={{t="Entre os fantasmas",b="Mux Zoamana pede Stable Ectoplasm dos fantasmas e banshees das Terras Pestilentas Orientais. Ele precisa dela junto com outros dois tipos de ectoplasma, coletados em Silithus e Hibérnia. O destilador extrai a substância de mortos-vivos incorpóreos próximos. Vilarejo do Norte é um bom lugar para encontrá-los."}},faq={{q="O que é Stable Ectoplasm?",a="Stable Ectoplasm é uma substância coletada de fantasmas e banshees nas Terras Pestilentas Orientais com um Destilador Ectoplásmico.",al={"stable ectoplasm","o que é ectoplasma","coisa de fantasma"}},{q="Quem precisa de Stable Ectoplasm?",a="Mux Zoamana, em Geringontzan, precisa de Stable Ectoplasm, além de Scorched Ectoplasm e Frozen Ectoplasm, para seu trabalho com o Destilador Ectoplásmico.",al={"quem quer stable ectoplasm","mux ectoplasma","do que mux precisa"}},{q="Onde posso encontrar Stable Ectoplasm?",a="Fantasmas e banshees nas Terras Pestilentas Orientais fornecem Stable Ectoplasm. Vilarejo do Norte é um bom lugar para encontrá-los.",al={"localização de stable ectoplasm","onde encontrar ectoplasma","fantasmas de vilarejo do norte"}},{q="Por que Mux quer ectoplasma?",a="Mux espera usar a energia sobrenatural do ectoplasma para alcançar espíritos cujas almas ainda não deixaram completamente este mundo.",al={"por que ectoplasma","plano de mux","alcançar espíritos"}}},fp="16,179,16.303.0,25.123.0,27.141.0,34.110.0,28.118.0"}
P.entries["item:stalker-claws"] = {n="Garras de Espreitador",s="As Garras de Espreitador são as garras obtidas dos prairie stalkers que vagam pelos Morros Ondulantes de Mulgore. Os xamãs taurens as utilizam como componentes vitais no entalhe de totens de purificação tradicionais para purificar poços de água corrompidos.",h="As Garras de Espreitador são as garras obtidas dos prairie stalkers que vagam pelos Morros Ondulantes de...",kw={"totem de purificação","mulgore","mull chifre troante","prairie stalker","garras de espreitador","totem de chifre troante","poço de água"},ang={["class:Shaman"]="As garras dos predadores selvagens das planícies canalizam a feroz pureza da natureza, material essencial para vincular e fortalecer totens de purificação.",["race:Tauren"]="Coletar essas garras serve ao dever sagrado da sua tribo de restaurar as águas sagradas envenenadas por invasores industriais descuidados."},sec={{t="Predadores das Planícies",b="As estepes relvadas de Mulgore abrigam predadores naturais mortais, entre eles os furtivos prairie stalkers. Essas feras sobrevivem graças ao puro instinto e à precisão letal, um equilíbrio essencial dentro do desígnio da Mãe Terra. Mull Chifre Troante, buscando curar a terra flagelada, precisa dessas garras não por malícia contra os animais, mas porque a ferocidade pura e natural com que caçam possui a ressonância espiritual necessária para neutralizar a corrupção artificial."},{t="Purificando os Poços",b="Quando os empreendimentos dos goblins começaram a perfurar e minerar pelo centro de Kalimdor, venenos químicos infiltraram-se profundamente nas águas subterrâneas que abastecem os poços ancestrais dos taurens. O Poço Chifre Troante, em particular, foi vítima de uma corrupção vil. Ao unir Garras de Espreitador e Garras de Puma em um Totem de Purificação Chifre Troante, os xamãs tribais criam um canal espiritual capaz de expurgar a sujeira e a lama não natural das fontes naturais da terra."}},faq={{q="De onde vêm as Garras de Espreitador?",a="Elas são obtidas caçando prairie stalkers pelas colinas verdejantes de Mulgore, principalmente a leste e a oeste da Aldeia Casco Sangrento.",al={"onde encontrar garras de espreitador","quem saqueia garras de espreitador","fonte de garras de espreitador"}},{q="Por que Mull Chifre Troante precisa dessas garras?",a="Mull Chifre Troante usa as garras, juntamente com as garras de cougar das planícies, para criar um Totem de Purificação Chifre Troante. A pureza e a força inatas dos caçadores nativos das planícies são necessárias para purificar os poços de água envenenados.",al={"por que coletar garras de espreitador","propósito de mull chifre troante","uso das garras de espreitador"}},{q="Por que o Poço Chifre Troante está corrompido?",a="O poço está sofrendo com a poluição industrial artificial causada pelas operações dos goblins em Mulgore, que perturbam o equilíbrio natural e envenenam o lençol freático local.",al={"quem envenenou o poço","por que o poço chifre troante adoeceu","poluição de chifre troante"}},{q="O que acontece depois que as garras são coletadas?",a="Depois de coletadas, Mull entalha as garras em um totem de purificação, que deve então ser levado diretamente ao Poço Chifre Troante para expurgar a corrupção persistente.",al={"o que vem a seguir","próximo passo após as garras","ritual do totem de purificação"}}},fx={a496bd75={q="O que são Garras de Espreitador?",a="As Garras de Espreitador são as presas naturais colhidas de espreitadores das pradarias, ferozes predadores felinos que vagam pelas planícies de Mulgore. Embora sejam apenas troféus de caça para um estranho, os xamãs Tauren as veem como a personificação do foco predatório natural da criatura e da harmonia com a terra.",al={"o que são garras de espreitador","item garras de espreitador","garra de espreitador"}}},fp="13,148,23.364.0,19.338.0,33.136.0,43.173.0,42.141.0,42.152.0"}
P.entries["item:star-of-xil-yeh"] = {n="Estrela de Xil'yeh",s="A Estrela de Xil'yeh é uma poderosa gema que, dizem, permite a quem a possui falar com seres de outros mundos. Gerrig Agarrosso a procura entre três relíquias em Altaforja.",h="A Estrela de Xil'yeh é uma poderosa gema que, dizem, permite a quem a possui falar com seres de outros mundos.",kw={"gema","gerrig agarrosso","mão de dagun","legacy heart","outros mundos","estrela de xil'yeh","xil'yeh","compêndio de yagyin"},ang={["faction:Alliance"]="Como aventureiro da Aliança, você pode levar esta relíquia a Gerrig Agarrosso em Altaforja, onde ele a procura para sua ordem."},sec={{t="Uma relíquia procurada",b="Em Altaforja, Gerrig Agarrosso pede a Estrela de Xil'yeh como uma das três relíquias de que precisa. Ele procura os itens para trocá-los pelo Compêndio de Yagyin, um livro ligado ao início de um novo capítulo para sua ordem."}},faq={{q="O que a Estrela de Xil'yeh faz?",a="Dizem que a Estrela de Xil'yeh permite a quem a possui falar com seres de outros mundos.",al={"poder da estrela de xil'yeh","o que é a gema estrela","gema de xil'yeh"}},{q="Por que Gerrig Agarrosso quer a Estrela?",a="Gerrig precisa da Estrela de Xil'yeh, da Mão de Dagun e do Legacy Heart. Ele procura as três relíquias em troca do Compêndio de Yagyin.",al={"por que gerrig quer a estrela","estrela de agarrosso","relíquias de gerrig"}},{q="Onde encontrar a Estrela?",a="Grel'borg the Miser tem a Estrela de Xil'yeh nas Montanhas de Alterac.",al={"localização da estrela","onde fica xil'yeh","encontrar a estrela"}},{q="O que é o Compêndio de Yagyin?",a="O Compêndio de Yagyin é um livro que Gerrig Agarrosso oferece em troca de três relíquias. Ele acredita que o livro pode ajudar a iniciar um novo capítulo para sua ordem.",al={"compêndio de yagyin","por que agarrosso quer o compêndio","livro de agarrosso"}},{q="Quais são as outras relíquias que Gerrig procura?",a="Além da Estrela de Xil'yeh, Gerrig pede a Mão de Dagun e o Legacy Heart.",al={"mão e coração","três relíquias","itens de agarrosso"}}},fp="15,153,14.201.0,33.80.0,39.141.0,28.69.0,24.137.0,39.87.0"}
P.entries["item:stave-of-equinex"] = {n="Báculo de Equinex",s="O Báculo de Equinex é um cajado energizado ligado ao Equinex Monolith, em Feralas. Seu poder é necessário para abrir a pedra ancestral.",h="O Báculo de Equinex é um cajado energizado ligado ao Equinex Monolith, em Feralas.",kw={"byltan","equinex monolith","feralas","imbel","lahassa","morrow stone","ruínas dos ventos corvejantes","samha","báculo de equinex","troyas' stave"},sec={{t="O monólito silencioso",b="Nas Ruínas dos Ventos Corvejantes, em Feralas, o Troyas' Stave pode se tornar o Báculo de Equinex. Quatro chamas ainda ardem nas proximidades: Samha, Imbel, Byltan e Lahassa. Suas essências despertam o báculo ao lado do Equinex Monolith. O cajado é uma chave, e o monumento de pedra guarda algo em seu interior."},{t="Um poder enfraquecido",b="Quando o Báculo de Equinex energizado toca o monólito, uma pequena porta se abre em sua superfície fria. Feixes de luz preenchem as ruínas enquanto o artefato oculto é retirado. O poder do báculo então começa a se dissipar, e Troyas Brisaluna, no Domínio de Plumaluna, pode estudar o que foi encontrado."}},faq={{q="O que o Báculo de Equinex faz?",a="O Báculo de Equinex é uma chave que abre o Equinex Monolith nas Ruínas dos Ventos Corvejantes.",al={"utilidade do báculo","o que é báculo de equinex"}},{q="Como o Troyas' Stave é transformado?",a="As essências das quatro chamas, Samha, Imbel, Byltan e Lahassa, energizam o Troyas' Stave ao lado do Equinex Monolith.",al={"energizar troyas stave","criar báculo de equinex"}},{q="Onde fica o Equinex Monolith?",a="O Equinex Monolith fica entre as Ruínas dos Ventos Corvejantes, em Feralas, a oeste do Ramo de Morfeu.",al={"localização do monólito","onde fica equinex"}},{q="O que há dentro do monólito?",a="Uma pequena porta no monólito se abre e revela um artefato. Troyas Brisaluna identifica a pedra retirada de lá como Morrow Stone.",al={"artefato do monólito","o que há em equinex"}},{q="Por que o báculo perde o poder?",a="O Báculo de Equinex começa a perder sua energia assim que o artefato é retirado do monólito.",al={"báculo enfraquecendo","por que o báculo enfraquece"}}},fp="16,130,19.283.0,14.273.1,34.88.0,29.117.0,30.93.0,28.131.1,30.100.1"}
P.entries["item:steelgrill-s-tools"] = {n="Ferramentas do Gradaço",s="As Ferramentas do Gradaço são um conjunto especializado de instrumentos mecânicos requisitados para Beldin Gradaço, o mestre técnico da Garagem do Gradaço. Famoso por levar os engenhos de cerco — e seus próprios equipamentos — ao limite, Beldin quebra ferramentas com frequência e depende de remessas da vizinha Kharanos para manter sua oficina funcionando.",h="As Ferramentas do Gradaço são um conjunto especializado de instrumentos mecânicos requisitados para Beldin...",kw={"beldin","garagem","kharanos","vila catraca","engenho de cerco","chave","gradaço","ferramentas"},ang={["profession:Engineering"]="Qualquer engenheiro consegue simpatizar com o dilema de Beldin, já que reparos de alto torque em engenhos de cerco pesados costumam sacrificar chaves de arco voltaico e chaves de boca delicadas.",["race:Dwarf"]="Manter os engenhos de cerco blindados da Aliança é uma questão de orgulho para os anões, e manter Beldin abastecido garante que a vanguarda blindada de Altaforja permaneça pronta para o combate."},sec={{t="Um Artesão de Mão Pesada",b="Beldin Gradaço é amplamente considerado um dos melhores técnicos de engenhos de cerco de Dun Morogh, mas seu estilo agressivo de reparo é infame entre os comerciantes locais. Trabalhando incansavelmente em tanques blindados e engenhocas mecânicas, Beldin tende a destruir equipamentos delicados quase tão rápido quanto eles podem ser forjados. Entre quebrar chaves de arco voltaico e espanar catracas de dente, o mecânico está constantemente fazendo novos pedidos em Kharanos para manter suas bancadas de trabalho abastecidas."},{t="Mantendo os Motores em Movimento",b="Esta entrega específica de ferramentas é vital para manter operacionais as máquinas de guerra de Altaforja. Em sua garagem a nordeste de Kharanos, Beldin realiza a manutenção ativa de veículos de combate para condutores experientes, como o Piloto Marchapedra. Sem um suprimento renovado de chaves e catracas, engenhos de cerco essenciais ficariam semi-montados na neve, paralisando tanto a garagem quanto as defesas locais."}},faq={{q="Para que servem as Ferramentas do Gradaço?",a="Elas são ferramentas mecânicas de reposição entregues a Beldin Gradaço na Garagem do Gradaço. Beldin precisa delas para reformar o maquinário pesado dos anões, em especial o engenho de cerco danificado pertencente ao Piloto Marchapedra.",al={"o que são estas ferramentas","objetivo das ferramentas do gradaço"}},{q="Por que Beldin Gradaço gasta tantas ferramentas?",a="Beldin é um mecânico excepcionalmente bruto que leva suas ferramentas ao ponto de ruptura. De acordo com fornecedores em Kharanos, ele quebra chaves de arco voltaico e catracas de dente quase mais rápido do que os artesãos locais conseguem fabricá-las.",al={"por que ferramentas quebradas","por que beldin precisa de ferramentas"}},{q="De onde veio esta caixa de ferramentas?",a="A remessa é montada e despachada no assentamento próximo de Kharanos antes de ser entregue a viajantes que seguem para o nordeste em direção à Garagem do Gradaço.",al={"onde consigo ferramentas","origem da remessa de ferramentas"}},{q="Quem é Beldin Gradaço?",a="Beldin é um mestre mecânico anão, proprietário e operador da Garagem do Gradaço, localizada a nordeste de Kharanos. Ele é considerado o principal técnico de engenhos de cerco da região.",al={"quem é beldin","história de beldin gradaço"}}},fx={["8eb066d8"]={q="O que são as Ferramentas do Gradaço?",a="As Ferramentas do Gradaço são um pedido recém-embalado de equipamento mecânico pesado, incluindo chaves de arco e catracas de presa. O pacote foi preparado para entrega direta a Beldin Gradaço, o mestre técnico de máquinas de cerco que trabalha na Garagem do Gradaço, perto de Kharanos.",al={"o que são as ferramentas do gradaço","caixa de ferramentas do gradaço","o que é as ferramentas do gradaço"}},["11454cb4"]={q="Por que Beldin Gradaço precisa desta caixa de ferramentas?",a="Beldin é um mecânico especialista, mas ele força seus equipamentos ao limite enquanto faz a manutenção de máquinas pesadas. Tendo acabado de quebrar sua última catraca de presa, ele precisa urgentemente dessa nova remessa para concluir reparos críticos em máquinas de cerco, como a do Piloto Marchapedra.",al={"por que beldin quer as ferramentas","por que precisar das ferramentas do gradaço","por que as ferramentas são procuradas"}}},fp="18,182,24.349.0,27.287.0,37.180.0,52.151.0,40.99.0,25.147.0"}
P.entries["item:steelsnap-s-rib"] = {n="Costela do Estalaço",s="A Costela do Estalaço é um troféu sombrio retirado da carcaça da feroz hiena Estalaço em Mil Agulhas. Levada de volta ao Penhasco do Trovão, ela serve como prova física de que uma criatura considerada fora da bênção da Mãe Terra foi eliminada.",h="A Costela do Estalaço é um troféu sombrio retirado da carcaça da feroz hiena Estalaço em Mil Agulhas.",kw={"aldeia e'thok","platô dos caçadores","hiena","melor casco de pedra","estalaço","costela do estalaço","mil agulhas","penhasco do trovão"},ang={["class:Hunter"]="Retirar a costela de um líder de matilha impõe um teste à habilidade do caçador de rastrear presas perigosas e abater ameaças que perturbam o equilíbrio da natureza selvagem.",["race:Tauren"]="Para os taurens, trazer este troféu cumpre um dever para com a Mãe Terra ao expurgar uma criatura cuja crueldade desmedida macula o equilíbrio sagrado."},sec={{t="Uma Caçada Fora da Bênção",b="A maioria das caçadas dos taurens é realizada para o sustento, pela honra ou em busca de harmonia com a natureza. Estalaço, no entanto, representa um tipo diferente de presa. Vagando pelo leito do desfiladeiro de Mil Agulhas, ao sul da Aldeia E'thok, essa hiena alfa perversa aterroriza a fauna pacífica e incita matilhas de predadores menores a um derramamento de sangue sem sentido. Quando o mestre de caça Melor Casco de Pedra no Platô dos Caçadores marca Estalaço para a morte, ele exige um osso pesado — a costela do Estalaço — como confirmação incontestável de que o tirano foi abatido e o cânion purificado de sua praga."}},faq={{q="Para que serve a Costela do Estalaço?",a="A costela é entregue a Melor Casco de Pedra no topo do Platô dos Caçadores, no Penhasco do Trovão, para concluir a caçada ao Estalaço. Ela serve como prova tangível de que a hiena cruel foi derrotada.",al={"missão costela do estalaço","quem quer a costela do estalaço","o que fazer com a costela do estalaço"}},{q="Onde posso encontrar o Estalaço para conseguir a costela?",a="O Estalaço vaga pelas áreas a noroeste de Mil Agulhas, perambulando pelo fundo do cânion ao sul da Aldeia E'thok, tipicamente flanqueado por membros leais de sua matilha.",al={"localização do estalaço","onde fica o estalaço","encontrar o estalaço"}},{q="Por que Melor Casco de Pedra quer a morte do Estalaço?",a="Melor considera Estalaço um tirano não natural que existe fora da bênção da Mãe Terra. Ao contrário dos predadores comuns que caçam pela sobrevivência, Estalaço espalha terror e derramamento de sangue desnecessário entre feras pacíficas, tornando sua destruição imprescindível.",al={"por que matar o estalaço","motivo de melor casco de pedra","história do estalaço"}},{q="Quem é Melor Casco de Pedra?",a="Melor Casco de Pedra é um caçador tauren veterano situado no Platô dos Caçadores, no Penhasco do Trovão, que encarrega aspirantes a rastreadores de caçar feras perigosas por toda Kalimdor.",al={"quem é melor","localização de melor casco de pedra","platô dos caçadores melor"}}},fx={["27efcb35"]={q="O que é a Costela do Estalaço?",a="É um osso pesado retirado da carcaça de Steelsnap, uma hiena notoriamente selvagem que aterroriza os cânions de Mil Agulhas. Em vez de um material de artesanato útil ou carne, ele serve como uma prova física inegável de que a fera cruel foi abatida.",al={"o que é a costela do estalaço","o que é a costela de steelsnap","osso de steelsnap"}},["57ae26da"]={q="De onde vem a Costela do Estalaço?",a="A costela vem diretamente dos restos de Steelsnap, uma hiena anormalmente feroz que vaga pelas planícies áridas de Mil Agulhas, ao sul dos Sertões. Para reivindicá-la, um caçador deve rastrear a besta e derrotar tanto Steelsnap quanto sua alcateia.",al={"onde conseguir a costela do estalaço","origem da costela do estalaço","quem derruba a costela do estalaço"}},["4a69fb67"]={q="Por que Melor Casco de Pedra quer a Costela do Estalaço?",a="Melor Casco de Pedra pede a costela como prova física da morte de Steelsnap. Ao contrário das caçadas realizadas por comida ou honra, Melor envia caçadores para erradicar Steelsnap porque a besta existe fora da bênção da Mãe Terra, espalhando derramamento de sangue e medo entre criaturas mais pacíficas. Retornar com o osso confirma que o cânion foi purificado daquela mancha.",al={"por que levar a costela do estalaço a melor","por que melor precisa da costela","por que coletar a costela do estalaço"}}},fp="15,181,27.428.0,33.118.0,42.121.0,47.180.0,23.142.0"}
P.entries["item:stolen-silver"] = {n="Prata Roubada",s="A Prata Roubada é um cofre recuperado de moedas da Horda destinado à guarnição da guarda da Encruzilhada. Ele foi bizarramente levado para a vastidão selvagem pelos ferozes raptores dos Sertões, gerando incredulidade entre os feitores do entreposto.",h="A Prata Roubada é um cofre recuperado de moedas da Horda destinado à guarnição da guarda da Encruzilhada.",kw={"pagamento dos sertões","encruzilhada","gazrog","terra dos raptores","caixa trancada de prata","prata roubada","raptor escamassol"},ang={["faction:Horde"]="A Encruzilhada atua como o coração estratégico da presença da Horda nos Sertões. Recuperar esse pagamento garante que os soldados locais continuem alimentados, pagos e prontos para manter a linha contra incursões de centauros e da Aliança."},sec={{t="Um Roubo Bestial",b="As vastas terras selvagens dos Sertões apresentam ameaças constantes às rotas de suprimentos, mas poucos esperavam que os raptores Escamassol locais visassem cofres de moedas de metal. Quando uma remessa de prata destinada ao pagamento da guarnição da Encruzilhada foi roubada da torre de guarda, os raptores arrastaram a caixa trancada de volta para seus ninhos comunais na Terra dos Raptores, ao sul de Vila Catraca. Para feitores como Gazrog, o roubo revela um grau inquietante de astúcia nos predadores, que aparentemente valorizam berloques brilhantes ou possuem uma inteligência muito além da de feras selvagens comuns."}},faq={{q="O que é a Prata Roubada?",a="É uma pesada caixa trancada cheia de moedas de prata destinada a pagar os guardas da Encruzilhada. Ela foi roubada da torre de guarda da Encruzilhada por raptores e carregada para seus locais de nidificação.",al={"o que é a prata roubada","o que é a prata"}},{q="Por que os raptores roubaram uma caixa trancada de moedas?",a="O motivo dos predadores permanece um mistério até mesmo para guerreiros experientes como Gazrog. Enquanto os animais normalmente buscam comida, os raptores dos Sertões são conhecidos por sua astúcia incomum, e essas feras foram atraídas a arrastar o baú de metal brilhante para o fundo de seu covil.",al={"por que raptores querem prata","inteligência dos raptores","por que prata"}},{q="Para onde a prata foi levada?",a="Os raptores arrastaram a caixa trancada para a Terra dos Raptores, um desfiladeiro acidentado de ninhos localizado ao sul de Vila Catraca, no leste dos Sertões.",al={"localização da prata roubada","onde está a prata"}},{q="Quem está procurando pela Prata Roubada?",a="Gazrog, um orc estacionado na Encruzilhada, procura pelo baú. Os fundos representam um mês inteiro de pagamento para os defensores sobrecarregados do entreposto.",al={"quem quer a prata","quem entrega a prata roubada"}}},fp="13,157,15.406.0,26.160.0,41.157.0,27.120.0,37.146.0"}
P.entries["item:stoley-s-bottle"] = {n="Stoley's Bottle",s="A Garrafa do Esmirno contém rum de porão Steamwheedle, enviado à Angra do Butim para Sea Wolf MacKinley. MacKinley deve provar o rum e avaliar sua aspereza.",h="A Garrafa do Esmirno contém rum de porão Steamwheedle, enviado à Angra do Butim para Sea Wolf MacKinley.",kw={"angra do butim","sea wolf mackinley","steamwheedle bilge rum","esmirno","garrafa do esmirno","stoley's debt"},sec={{t="Uma Garrafa Amarga",b="Na Angra do Butim, Sea Wolf MacKinley recebe de Esmirno uma garrafa de rum de porão Steamwheedle. MacKinley espera que a bebida acabe com suas dúvidas sobre as bebidas da Angra do Butim. Um gole prova que o rum é péssimo. É espesso como cascalho e queima como lava, exatamente como Esmirno prometeu."}},faq={{q="O que há na Garrafa do Esmirno?",a="A Garrafa do Esmirno contém rum de porão Steamwheedle.",al={"o que há na garrafa","conteúdo da garrafa do esmirno"}},{q="Para quem é a garrafa?",a="Sea Wolf MacKinley, na Angra do Butim, deve receber a Garrafa do Esmirno.",al={"quem recebe a garrafa","para quem entregar a garrafa"}},{q="Por que MacKinley quer a garrafa?",a="MacKinley quer acabar com suas dúvidas sobre as bebidas da Angra do Butim provando o rum de porão Steamwheedle de Esmirno.",al={"por que bebida para mackinley","garrafa de mac kinley"}},{q="Qual é o gosto do rum?",a="MacKinley acha o rum péssimo, espesso como cascalho e ardente como lava.",al={"o rum é bom","gosto do rum de porão"}},{q="A garrafa quita a dívida de Esmirno?",a="Depois de provar o rum, MacKinley diz que Esmirno pode ficar com o dinheiro que lhe deve. A bebida é tão áspera quanto Esmirno prometeu.",al={"dívida de esmirno e garrafa","mac kinley perdoa esmirno"}}},fp="15,150,15.272.0,29.50.0,22.70.0,35.109.0,29.72.1,39.114.1"}
P.entries["item:stoley-s-shipment"] = {n="Stoley's Shipment",s="A Carga de Esmirno é um carregamento de rum roubado, mantido por piratas na Enseada do Armador Perdido. Esmirno quer recuperá-lo para acertar uma aposta com “Sea Wolf” MacKinley.",h="A Carga de Esmirno é um carregamento de rum roubado, mantido por piratas na Enseada do Armador Perdido.",kw={"angra do butim","captain cuergo","enseada do armador perdido","rum","sea wolf mackinley","porto de bondebico","esmirno","carga de esmirno","tanaris","aposta"},sec={{t="Rum por uma aposta",b="Na Enseada do Armador Perdido, a Carga de Esmirno está entre os carregamentos roubados pelos piratas. Captain Cuergo levou o último carregamento de rum de Esmirno e o mantém na cidade pirata murada. Esmirno precisa que a carga seja devolvida ao Porto de Bondebico para acertar sua aposta com “Sea Wolf” MacKinley em Angra do Butim."}},faq={{q="O que é a Carga de Esmirno?",a="A Carga de Esmirno é um carregamento de rum roubado por Captain Cuergo de Esmirno.",al={"carga de esmirno","rum de esmirno","carregamento de esmirno"}},{q="Quem roubou o rum?",a="Captain Cuergo roubou o último carregamento de rum de Esmirno.",al={"quem levou o rum de esmirno","carregamento de cuergo","pirata roubou rum"}},{q="Onde está a Carga de Esmirno?",a="A Carga de Esmirno está na cidade pirata murada da Enseada do Armador Perdido, em Tanaris.",al={"onde está o rum","carga da enseada do armador perdido","local da carga"}},{q="Por que Esmirno quer a carga de volta?",a="Esmirno quer o rum de volta para acertar uma aposta com “Sea Wolf” MacKinley em Angra do Butim.",al={"por que devolver o rum","aposta de esmirno","aposta de bebida"}},{q="Quem é MacKinley?",a="“Sea Wolf” MacKinley é o marinheiro de Angra do Butim com quem Esmirno fez uma aposta sobre o rum de Kalimdor.",al={"sea wolf","aposta de mackinley","sujeito de angra do butim"}}},fp="17,151,15.287.0,28.82.0,18.53.0,29.85.0,39.94.0,17.102.0"}
P.entries["item:stone-circle"] = {n="Círculo de Pedra",s="O Círculo de Pedra é uma pedra marcada por uma serpente, guardada na oficina de Marlon Catarrebite, na Vila Catraca. Ela lembra uma câmara circular no Templo Submerso.",h="O Círculo de Pedra é uma pedra marcada por uma serpente, guardada na oficina de Marlon Catarrebite, na Vila...",kw={"câmara circular","marlon catarrebite","vila catraca","símbolo da serpente","círculo de pedra","templo submerso"},sec={{t="Uma Marca de Serpente",b="Marlon Catarrebite guarda o Círculo de Pedra em sua oficina, na Vila Catraca, e pede que você o recupere. Ele se lembra de ter encontrado um símbolo de serpente igual depois de escapar do Templo Submerso. A pedra pode ajudá-lo a se lembrar de mais coisas que viu lá."}},faq={{q="O que é o Círculo de Pedra?",a="O Círculo de Pedra é uma pedra redonda com o símbolo de uma serpente, guardada na oficina de Marlon Catarrebite, na Vila Catraca.",al={"círculo de pedra","que pedra é esta"}},{q="Onde fica o Círculo de Pedra?",a="Marlon Catarrebite está com o Círculo de Pedra em sua oficina, na Vila Catraca.",al={"onde fica o círculo de pedra","encontrar a pedra"}},{q="Quem quer o Círculo de Pedra?",a="Marlon Catarrebite pede que você recupere o Círculo de Pedra em sua oficina, na Vila Catraca.",al={"quem quer esta pedra","pedra do marlon"}},{q="O que significa a marca da serpente?",a="O símbolo da serpente é igual ao das estátuas de que Marlon se lembra, em uma câmara circular do Templo Submerso.",al={"símbolo da serpente","significado da marca da serpente"}},{q="Por que Marlon o quer?",a="Marlon espera que a pedra o ajude a se lembrar de sua fuga do Templo Submerso e a descobrir mais sobre o lugar.",al={"por que o círculo de pedra","marlon quer a pedra"}}},fp="12,146,14.238.0,25.115.0,26.67.0,27.86.0,32.99.0,24.114.0"}
P.entries["item:stone-of-relu"] = {n="Pedra de Relu",s="A Pedra de Relu é uma antiga relíquia arqueológica recuperada no Pantanal. Considerada pelo Arqueólogo Pançacheia como a chave para liberar poderes latentes em fósseis primordiais, ela foi perdida brevemente quando raptores locais emboscaram o estudioso na estrada.",h="A Pedra de Relu é uma antiga relíquia arqueológica recuperada no Pantanal.",kw={"arqueólogo pançacheia","liga dos exploradores","fossil","raptor malhado","prospector whelgar","pedra de relu","pantanal"},ang={["faction:Alliance"]="As expedições da Aliança no Porto de Menethil dependem de artefatos recuperados como a Pedra de Relu para justificar as árduas escavações pelas terras pantanosas perigosas.",["race:Dwarf"]="Para a Liga dos Exploradores, a Pedra de Relu é uma ferramenta vital para reconstruir as origens da vida antiga e o legado esquecido do mundo."},sec={{t="Uma chave para relíquias antigas",b="Descoberta durante operações da Liga dos Exploradores, acredita-se que a Pedra de Relu possua o poder decifrador necessário para desvendar fósseis pré-históricos coletados em Kalimdor e nos Reinos do Leste. O Arqueólogo Pançacheia identificou o artefato como o catalisador necessário para revelar os segredos tanto de seus próprios espécimes do Pantanal quanto do fóssil desenterrado pelo Prospector Trilheiro na Costa Negra."},{t="Perdida nos pântanos",b="Enquanto Pançacheia viajava pelas estradas dos Pântanos para se encontrar com o Prospector Whelgar, um bando de raptores malhados o emboscou. Durante o confronto, a relíquia foi perdida e engolida por uma das feras famintas, forçando a Liga a recrutar aventureiros para caçar os raptores do pântano e arrancar a pedra antiga de suas goelas."}},faq={{q="O que é a Pedra de Relu?",a="A Pedra de Relu é um artefato antigo procurado pelo Arqueólogo Pançacheia. Ele acredita que ela funcione como uma cifra ou catalisador capaz de desbloquear os mistérios ocultos e o poder dormente dentro de fósseis pré-históricos.",al={"pedra de relu","o que e esta pedra","artefato de relu"}},{q="Como a pedra foi parar dentro de um raptor?",a="O Arqueólogo Pançacheia transportava a relíquia pela estrada do Pantanal para encontrar o Prospector Whelgar quando raptores malhados atacaram seu grupo. No caos, a pedra foi perdida e engolida por uma das feras carniceiras.",al={"por que raptores estao com ela","quem perdeu a pedra","como ela foi perdida"}},{q="O que Pançacheia planeja fazer com a pedra?",a="Pançacheia pretende combinar a pedra com seu fóssil recuperado e com o fóssil encontrado pelo Prospector Trilheiro na Costa Negra, usando a relíquia para decifrar e liberar seus segredos mágicos latentes.",al={"o que pancacheia quer","proposito da pedra de relu"}}},fp="13,142,23.275.0,19.285.0,26.146.0,41.160.0,48.179.0"}
P.entries["item:stone-of-the-tides"] = {n="Pedra das Marés",s="A Pedra das Marés é uma antiga relíquia Gurubashi cobiçada pelo Barão Rezingada para sua coleção. Ela comanda a água e pode invocar Water Elementals.",h="A Pedra das Marés é uma antiga relíquia Gurubashi cobiçada pelo Barão Rezingada para sua coleção.",kw={"barão rezingada","maldição","gurubashi","pedra das marés","artefato troll","água","water elementals"},ang={["faction:Alliance"]="Como viajante da Aliança na Selva do Espinhaço, você pode ajudar o Barão Rezingada a recuperar a Pedra para sua coleção de artefatos antigos dos trolls.",["race:Troll"]="Como troll, você pode reconhecer a Pedra das Marés como um artefato já usado pelo Império Gurubashi."},sec={{t="Uma relíquia submersa",b="O Barão Rezingada busca a Pedra das Marés para sua coleção de artefatos antigos dos trolls. A relíquia já pertenceu ao poderoso Império Gurubashi e pode comandar a água e invocar Water Elementals. Porém, seu poder traz uma maldição: quem a usa desaparece lentamente da existência."}},faq={{q="O que é a Pedra das Marés?",a="A Pedra das Marés é um poderoso artefato mágico que já foi usado pelo Império Gurubashi. Ela comanda a água e invoca Water Elementals.",al={"pedra das marés","o que é a pedra das marés"}},{q="O que a Pedra das Marés faz?",a="A Pedra das Marés permite que quem a usa controle a água e invoque Water Elementals.",al={"poderes da pedra","o que a pedra das marés pode fazer"}},{q="Qual é a maldição da Pedra das Marés?",a="A Pedra das Marés faz com que quem a usa desapareça lentamente da existência.",al={"maldição da pedra das marés","por que ela faz desaparecer"}},{q="Por que o Barão Rezingada quer a Pedra?",a="O Barão Rezingada quer a Pedra das Marés para sua coleção de artefatos antigos dos trolls.",al={"reizingada quer a pedra","por que o barão a quer"}},{q="De onde veio a Pedra?",a="A Pedra das Marés já foi usada pelo Império Gurubashi.",al={"origem da pedra","pedra das marés gurubashi"}}},fp="18,149,14.263.0,31.136.0,36.79.0,44.65.1,39.90.0,30.61.0"}
P.entries["item:stonetalon-sap"] = {n="Seiva das Torres de Pedra",s="A Seiva das Torres de Pedra é uma substância pegajosa e potente colhida diretamente das pesadas bestas de seiva que vagam pelas alturas escarpadas da Cordilheira das Torres de Pedra. Ela serve como um reagente essencial para o mandingueiro Lançanegra Jin'Zil, que usa suas propriedades florestais brutas para preparar uma poção rancorosa.",h="A Seiva das Torres de Pedra é uma substância pegajosa e potente colhida diretamente das pesadas bestas de...",kw={"jin'zil","malaka'jin","lago mirkfallon","besta de seiva","morro das torres de pedra","seiva das torres de pedra"},ang={["race:NightElf"]="A profanação dos elementos nativos da Cordilheira das Torres de Pedra por um mandingueiro da Horda para envenenar elfos engaiolados é um ultraje contra a natureza e Eluna.",["race:Troll"]="O Mandingueiro Jin'Zil demonstra o talento dos Lançanegra para transformar o ambiente amado do inimigo em um instrumento letal de vodu."},sec={{t="Uma Colheita Amarga",b="Encontrado gotejando das arbóreas bestas de seiva perto do Lago Mirkfallon e do Morro das Torres de Pedra, este fluido pesado carrega a essência concentrada da flora ancestral da montanha. Embora inofensiva quando dormente na natureza, a seiva pode facilmente ser transformada em algo muito mais sombrio nas mãos de um alquimista ou mandingueiro experiente. Jin'Zil de Malaka'jin a cobiça para preparar o que ele zombeteiramente chama de \"magia da floresta\" — uma poção mortal destinada a atormentar seus prisioneiros elfos noturnos engaiolados com a própria essência de sua estimada floresta."}},faq={{q="Quais criaturas carregam a Seiva das Torres de Pedra?",a="Ela é coletada de bestas de seiva, as estranhas criaturas da floresta encontradas perto do Lago Mirkfallon e mais acima ao longo das encostas que levam ao Morro das Torres de Pedra.",al={"onde conseguir seiva das torres de pedra","quem saqueia seiva das torres de pedra","bestas de seiva"}},{q="Para que o Mandingueiro Jin'Zil usa a seiva?",a="Jin'Zil combina a seiva com olhos de corredor, bigodes do crepúsculo e uma Escama de Dragão Encantado para produzir uma poção tóxica que ele lança sobre seus prisioneiros elfos noturnos engaiolados.",al={"por que jin'zil quer seiva","receita de magia da floresta de jin'zil"}},{q="Onde é o melhor lugar para encontrar bestas de seiva?",a="As bestas de seiva habitam os bosques que cercam o Lago Mirkfallon e os caminhos verdejantes que sobem em direção ao Morro das Torres de Pedra.",al={"localização das bestas de seiva","bestas de seiva do lago mirkfallon"}},{q="A seiva é mágica por si só?",a="Ela é naturalmente infundida com a vitalidade primordial das terras altas da Cordilheira das Torres de Pedra, mas são necessários mojo de troll e reagentes específicos para distorcê-la em um veneno letal.",al={"a seiva das torres de pedra é mágica","propriedades da seiva das torres de pedra"}}},fx={b24da591={q="O que é a Seiva das Torres de Pedra?",a="A Seiva das Torres de Pedra é uma resina natural e pegajosa coletada das bestas de seiva que vagam pela Cordilheira das Torres de Pedra, particularmente ao redor de lugares como o Lago Mirkfallon e o Morro das Torres de Pedra. Ela é espessa, viscosa e cheia de essência natural bruta, tornando-a um componente ideal para poções e misturas vodu que aproveitam a magia peculiar da natureza local.",al={"o que é a seiva das torres de pedra","item seiva das torres de pedra","sobre a seiva das torres de pedra"}},["7615d27b"]={q="De onde vem a Seiva das Torres de Pedra?",a="Esta seiva âmbar é colhida diretamente das bestas de seiva vivas que vagueiam pelas florestas e margens dos lagos da Cordilheira das Torres de Pedra. Ela não é fabricada ou destilada por nenhum artesão mortal, mas sim secretada naturalmente por essas bizarras criaturas vegetais primordiais.",al={"fonte da seiva das torres de pedra","onde conseguir seiva","origem da seiva das torres de pedra"}}},fp="14,172,16.241.1,36.94.0,47.141.1,43.96.0,30.123.0"}
P.entries["item:stormpike-banner"] = {n="Estandarte dos Lançatroz",s="O Estandarte dos Lançatroz é um estandarte militar escondido nas profundezas da traiçoeira Caverna Asálgida, no Vale Alterac. Recrutas da Aliança precisam enfrentar harpias selvagens para recuperá-lo como um teste de iniciação, provando que são dignos de usar a insígnia dos Lançatroz.",h="O Estandarte dos Lançatroz é um estandarte militar escondido nas profundezas da traiçoeira Caverna Asálgida...",kw={"vale alterac","dun baldar","haggerdin","caverna asálgida","insígnia","proving grounds","estandarte dos lançatroz"},ang={["faction:Alliance"]="Recuperar o estandarte marca sua entrada formal na Guarda de Lançatroz, garantindo a você o direito de portar a insígnia de batalha deles contra o Clã Lobo do Gelo.",["race:Dwarf"]="O estandarte representa a reivindicação soberana de Altaforja e a sagrada missão do clã Lançatroz de desvendar as relíquias de seu passado por todo o vale."},sec={{t="Um Rito de Iniciação",b="Para se juntar oficialmente às fileiras da expedição Lançatroz no Vale Alterac, os possíveis recrutas devem provar seu valor antes de enfrentar os orcs Lobo do Gelo. O Tenente Haggerdin envia soldados recém-chegados da Aliança para a Caverna Asálgida, situada a sudoeste de Dun Baldar. Cravado nas profundezas deste covil subterrâneo congelado, o Estandarte dos Lançatroz serve como campo de testes: qualquer um com coragem suficiente para enfrentar as harpias nativas, pegar o estandarte e trazê-lo de volta com vida ganha o posto e a insígnia de um iniciado na Guarda de Lançatroz."}},faq={{q="Onde o Estandarte dos Lançatroz está localizado?",a="O estandarte está cravado nas profundezas da Caverna Asálgida, um sistema de cavernas tomado pelo gelo situado a sudoeste de Dun Baldar, no Vale Alterac.",al={"localização do estandarte","onde fica o estandarte dos lançatroz","como encontrar o estandarte"}},{q="Por que os recrutas precisam recuperar o estandarte?",a="O Tenente Haggerdin exige que todos os recrutas da Aliança demonstrem sua coragem antes de se juntarem às linhas de batalha. Trazer o estandarte de volta da perigosa caverna infestada de harpias rende ao recruta sua Insígnia dos Lançatroz inicial.",al={"prova de proving grounds","por que pegar o estandarte","missão de haggerdin"}},{q="Quais ameaças guardam o estandarte dentro da caverna?",a="A Caverna Asálgida é ferozmente defendida por harpias selvagens locais, que atacarão brutalmente quaisquer invasores em busca do estandarte.",al={"monstros perto do estandarte","inimigos da caverna asálgida"}},{q="A quem devo devolver o estandarte assim que encontrá-lo?",a="Entregue o estandarte recuperado ao Tenente Haggerdin, o oficial da Aliança posicionado do lado de fora da entrada, nas Montanhas de Alterac.",al={"entregar o estandarte","entrega do estandarte"}}},fx={["27f01085"]={q="O que é o Estandarte dos Lançatroz?",a="O Estandarte dos Lançatroz é um estandarte militar que representa a Guarda de Lançatroz, a expedição anã que atualmente trava guerra por todo o Vale Alterac. Plantado profundamente dentro das perigosas Cavernas Asa-de-Gelo, infestadas de harpias a sudoeste de Dun Baldar, o estandarte serve como um marco de desafio. Os recrutas devem se aventurar nas profundezas geladas, enfrentar as feras ferozes que espreitam lá dentro e recuperar as cores para provar sua coragem e dignidade para usar a insígnia dos Lançatroz.",al={"o que é o estandarte dos lançatroz","história do estandarte dos lançatroz","sobre o estandarte dos lançatroz"}}},fp="16,139,19.286.0,38.96.0,44.167.0,46.90.0,41.125.0"}
P.entries["item:stormpike-s-request"] = {n="Pedido de Lançatroz",s="Pedido de Lançatroz é uma encomenda por escrito despachada pelo Montanhista Lançatroz das colinas de Loch Modan para Ventobravo. A carta pede ao mestre forjador de armaduras Furen Barbalonga para fabricar um escudo sob medida com uma qualidade anã inigualável.",h="Pedido de Lançatroz é uma encomenda por escrito despachada pelo Montanhista Lançatroz das colinas de Loch...",kw={"ferreiro","dun morogh","distrito dos anões","furen barbalonga","pedido","escudo","lancatroz","ventobravo"},ang={["profession:Blacksmithing"]="A solicitação é uma prova da reputação dos mestres armeiros, demonstrando que a grande forja anã atrai clientes de reinos inteiros.",["race:Dwarf"]="Para os anões, levar o pedido mantém os laços de clã e ofício entre os montanhistas que guardam Khaz Modan e os artesãos que vivem no exterior, em cidades humanas."},sec={{t="Uma Encomenda do Norte",b="Enquanto está destacado no extremo norte em Loch Modan, o Montanhista Lançatroz precisa de um novo escudo resistente para enfrentar os perigos da fronteira anã. Em vez de confiar em um ferreiro comum, ele insiste em encomendar com Furen Barbalonga, um forjador de armaduras cuja habilidade lendária ele tem na mais alta consideração. Como Furen agora reside longe ao sul, entre os humanos do Distrito dos Anões de Ventobravo — atraído para longe de Altaforja pelo que Lançatroz presume ser uma fortuna de rei —, o montanhista conta com aventureiros viajantes para entregar seu pedido formal através dos reinos."},{t="A Linhagem Lançatroz",b="Entregar a carta no movimentado Distrito dos Anões de Ventobravo coloca a encomenda diretamente nas mãos competentes de Furen Barbalonga. Sendo um clã anão orgulhoso e estabelecido, conhecido por toda Khaz Modan tanto pela coragem marcial quanto pela riqueza substancial, uma encomenda dos Lançatroz tem grande peso. Contente por receber notícias e negócios de suas terras ancestrais do norte, Furen concorda em atender ao pedido e começa a trabalhar para forjar o escudo do montanhista."}},faq={{q="O que é o Pedido de Lançatroz?",a="É uma encomenda por escrito enviada pelo Montanhista Lançatroz de Loch Modan, solicitando que o mestre forjador de armaduras Furen Barbalonga forje um escudo de alta qualidade para ele.",al={"o que e esta carta","item de encomenda lancatroz","pedido de lancatroz"}},{q="Quem escreveu esta carta?",a="Ela foi redigida pelo Montanhista Lançatroz, uma sentinela anã que defende as passagens de Loch Modan e que admira profundamente a arte de forja de Furen Barbalonga.",al={"quem enviou o pedido de lancatroz","quem escreveu","montanhista lançatroz"}},{q="Para onde esta carta precisa ir?",a="Ela é endereçada a Furen Barbalonga, que trabalha em sua forja dentro do Distrito dos Anões de Ventobravo.",al={"onde levo o pedido de lancatroz","quem recebe esta carta","entregar pedido de lancatroz"}},{q="Por que Lançatroz contrata um ferreiro tão longe, em Ventobravo?",a="O Montanhista Lançatroz considera a perícia de Furen incomparável e recusa-se a aceitar qualquer outro armeiro, mesmo que Furen tenha decidido deixar Altaforja para exercer seu ofício entre os humanos do sul.",al={"por que furen","por que nao forjar em altaforja","por que enviar para ventobravo"}}},fx={["181a24c8"]={q="Por que Furen Barbalonga quer o Pedido de Lançatroz?",a="Esta ordem escrita encomenda um escudo anão finamente trabalhado. Furen Barbalonga, um ferreiro de armaduras que reside no Distrito dos Anões de Ventobravo, valoriza negócios do renomado clã Lançatroz. Ele sabe que a família não é apenas orgulhosa e estimada por toda Khaz Modan, mas também rica o suficiente para pagar generosamente por um artesanato excepcional.",al={"por que furen quer isso","por que o pedido de lançatroz é procurado","por que o pedido de lançatroz é desejado"}}},fp="19,100,21.422.0,18.312.0,28.87.0,22.131.0,34.93.0,57.137.0"}
P.entries["item:stormwind-armor-marker"] = {n="Vale-armadura de Ventobravo",s="Um Vale-armadura de Ventobravo é uma ficha oficial de requisição militar emitida para aventureiros que ajudaram o reino. Ele pode ser resgatado com artesãos autorizados, como Sara Albernaz na Madeireira Vale do Leste, em troca de equipamentos recém-fabricados.",h="Um Vale-armadura de Ventobravo é uma ficha oficial de requisição militar emitida para aventureiros que...",kw={"vale-armadura","armadura de pano e couro","madeireira vale do leste","floresta de elwynn","requisicao","sara albernaz","vale-armadura de ventobravo"},ang={["faction:Alliance"]="O vale representa os laços logísticos que unem assentamentos de fronteira, como a Madeireira Vale do Leste, diretamente ao comando militar de Ventobravo."},sec={{t="Requisições Militares",b="Manter a lei e a ordem em toda a Floresta de Elwynn sobrecarrega os recursos do reino. Em vez de distribuir equipamentos padrão diretamente dos postos avançados militares, os comandantes às vezes emitem fichas oficiais conhecidas como vales-armadura. Essas guias de requisição comprovam que o portador prestou serviços valorosos a Ventobravo e autorizam artesãos locais contratados a supri-los com armaduras sob medida."},{t="Abastecimento no Vale do Leste",b="Um dos principais destinos desses vales é a Madeireira Vale do Leste, situada na fronteira leste de Elwynn. Lá, artesãos como Sara Albernaz operam sob comissão do Exército de Ventobravo, transformando materiais locais em vestimentas protetoras de tecido e couro. Apresentar um vale concede aos recrutas defesas sob medida para ajudá-los a proteger os bosques ao redor."}},faq={{q="Qual é a finalidade do Vale-armadura de Ventobravo?",a="Ele serve como um comprovante militar oficial entregue a aventureiros que auxiliam os guardas de Ventobravo. A ficha comprova seu serviço e permite que você resgate uma peça de armadura de proteção com um artesão contratado pelo exército.",al={"o que e vale-armadura","para que serve o vale","uso do vale de ventobravo"}},{q="Quem aceita o vale?",a="Sara Albernaz o aceita na Madeireira Vale do Leste, localizada logo a leste, cruzando o rio na Floresta de Elwynn. Ela tem contrato com o Exército de Ventobravo para fornecer equipamentos sob medida de tecido e couro.",al={"quem aceita o vale","onde entregar o vale","vale sara albernaz"}},{q="Por que Ventobravo usa vales em vez de entregar armaduras diretamente?",a="Postos de guarda afastados muitas vezes não têm o espaço de armazenamento ou as instalações de ferraria e alfaiataria necessárias para equipar recrutas no local. Ao emitir fichas de requisição, os comandantes de campo delegam o suprimento a artesãos locais, como Sara Albernaz, que mantêm oficinas dedicadas.",al={"por que fichas em vez de armadura","por que fichas do exercito","comprovantes militares elwynn"}},{q="Que tipo de equipamento o vale concede?",a="O comprovante concede ao portador o direito de escolher entre peças recém-fabricadas de armadura de tecido ou couro feitas sob encomenda por fornecedores contratados do exército.",al={"qual armadura eu recebo","recompensas do vale","tecido ou couro"}}},fx={e5398b12={q="O que é o Vale-armadura de Ventobravo?",a="É um comprovante militar oficial emitido em nome do Exército de Ventobravo. Em vez de carregar pesados conjuntos de equipamento de proteção pela Floresta de Elwynn, os comandantes locais emitem este item como garantia de requisição, dando ao portador o direito de retirar armaduras de tecido ou couro recém-confeccionadas de um armeiro autorizado.",al={"o que é o vale-armadura de ventobravo","vale-armadura","o que é o vale"}},["618263b5"]={q="Por que Sara Albernaz quer o Vale-armadura de Ventobravo?",a="Sara Albernaz foi contratada pelo Exército de Ventobravo para equipar seus recrutas e voluntários com armaduras de tecido e couro. Ela exige o vale como prova oficial de autorização antes de entregar seu equipamento feito à mão, garantindo que os suprimentos do reino vão apenas para defensores reconhecidos.",al={"por que sara quer o vale","por que levar o vale para eastvale","por que precisar do vale-armadura"}},["3e7f2980"]={q="De onde vem o Vale-armadura de Ventobravo e quem o criou?",a="O vale é emitido em nome do Stormwind Army pelo Guarda Tomás, em seu posto junto à ponte leste em Elwynn, e concedido a defensores que comprovam sua astúcia e bravura. Ele traz a autoridade do exército do reino, encarregando artesãos locais de equipar recrutas às custas da coroa.",al={"quem criou o vale-armadura","de onde veio o vale","quem entrega o vale-armadura"}}},fp="22,177,21.341.0,21.324.0,50.195.0,23.195.0,69.244.0,47.128.0"}
P.entries["item:stoutmantle-s-response-to-solomon"] = {n="Resposta de Mantoforte a Salomão",s="A Resposta de Mantoforte a Salomão é uma mensagem oficial por escrito levada do Morro da Sentinela até a Vila Plácida. Nela, Gryan Stoutmantle informa sombriamente ao Magistrado Salomão que a combalida People's Militia não pode dispensar um único soldado sequer para defender as Montanhas Cristarrubra.",h="A Resposta de Mantoforte a Salomão é uma mensagem oficial por escrito levada do Morro da Sentinela até a Vila...",kw={"gryan","vila plácida","carta","magistrado salomão","messenger to westfall","peoples militia","montanhas cristarrubra","salomão","stoutmantle","cerro oeste"},ang={["faction:Alliance"]="Levar esta carta expõe a podridão política que paralisa o coração da Aliança: assentamentos distantes precisam implorar por ajuda uns aos outros enquanto a capital retém suas forças.",["race:Human"]="Para os defensores humanos, a mensagem oficial é um lembrete sombrio de que os centros rurais, como Cerro Oeste e Montanhas Cristarrubra, compartilham a mesma luta desesperada pela sobrevivência sem a guarda real de Ventobravo."},sec={{t="Um Apelo Negado",b="Enfrentando a pressão implacável de gnolls e orcs Blackrock, o Magistrado Salomão de Vila Plácida entrou em contato com o Morro da Sentinela na esperança de que as forças locais de Cerro Oeste pudessem enviar reforços. A resposta por escrito de Gryan Stoutmantle traz notícias amargas. Lamentando as perdas de Vila Plácida, Stoutmantle explica que Cerro Oeste é assolado por sua própria guerra. A People's Militia foi formada por puro desespero exatamente porque a Coroa retirou sua guarnição, deixando fazendeiros e voluntários sozinhos no combate contra a Irmandade Défias. Stoutmantle explica que suas próprias forças estão sangrando e sobrecarregadas, incapazes de sacrificar homens para socorrer outra fronteira abandonada."},{t="O Descaso do Reino",b="A correspondência destaca a tragédia compartilhada dos territórios humanos do sul em 25 ADP. Tanto as Montanhas Cristarrubra quanto Cerro Oeste se encontram inteiramente abandonados pela corte real de Ventobravo. Enquanto o Rei Varian Wrynn permanece desaparecido e o exército permanente do reino é misteriosamente mantido longe das fronteiras provinciais, os povoados periféricos são deixados para formar patrulhas voluntárias independentes ou perecer. Quando Salomão recebe a resposta selada, fica evidente a constatação de que nenhum dos povoados pode salvar o outro; todo o reino está se desfazendo enquanto a capital permanece em silêncio."}},faq={{q="O que está escrito na resposta de Stoutmantle?",a="Gryan Stoutmantle explica que Cerro Oeste está mergulhado em uma guerra brutal contra a Irmandade Défias e foi abandonado pelo exército de Ventobravo assim como as Montanhas Cristarrubra. Ele lamenta pelos defensores caídos, mas recusa categoricamente o pedido de reforços militares feito pelo Magistrado Salomão.",al={"o que diz a carta","conteúdo da carta de stoutmantle","texto da resposta a salomão"}},{q="Por que Salomão pediu ajuda a Cerro Oeste logo de início?",a="A Vila Plácida está sob pesado ataque de gnolls e orcs Blackrock, e seu apelo ao General Marcus Jonas em Ventobravo ainda não trouxe nenhuma tropa. Sem apoio oficial, o Magistrado Salomão buscou ajuda através de Elwynn junto à People's Militia, na esperança de que os defensores da fronteira pudessem ceder tropas.",al={"por que pedir ajuda a cerro oeste","salomão pedindo a stoutmantle","por que vila plácida pediu a milícia"}},{q="Por que a People's Militia não pode dispensar tropas?",a="A People's Militia é um exército de voluntários que mal consegue manter o controle do Morro da Sentinela e das planícies ao redor contra a Irmandade Défias. Com baixas aumentando diariamente e sem o apoio do exército regular, enviar combatentes para a Vila Plácida deixaria Cerro Oeste inteiramente indefeso.",al={"por que a milícia não ajuda","cerro oeste pode ajudar montanhas cristarrubra","por que recusar salomão"}},{q="Por que o Exército de Ventobravo não está protegendo esses povoados?",a="Ninguém em nenhum dos povoados sabe. Stoutmantle escreve apenas que Ventobravo retirou suas tropas e deixou Cerro Oeste indefeso, e o Magistrado Salomão se pergunta que ação poderia ser tão importante a ponto de afastar o Exército de Ventobravo de seu próprio povo. Ambas as regiões rurais foram abandonadas à própria sorte com voluntários locais.",al={"onde está o exército de ventobravo","por que ventobravo não ajuda","abandono de ventobravo"}}},fx={["399f6159"]={q="O que é a Resposta de Mantoforte a Salomão?",a="É um despacho escrito oficial de Gryan Stoutmantle, comandante da Milícia Popular no Morro da Sentinela, endereçado ao Magistrado Salomão, em Montanhas Cristarrubra. A carta traz a triste notícia de que o Cerro Oeste está envolvido em sua própria guerra desesperada contra a The Defias Brotherhood e não pode enviar soldados ou recursos para ajudar Vila Plácida.",al={"o que é a resposta de mantoforte","carta de mantoforte a salomão","resposta de gryan para vila plácida"}},["945d8c3a"]={q="De onde vem a Resposta de Mantoforte a Salomão e quem a escreveu?",a="Ela foi escrita pelo próprio Gryan Stoutmantle no Morro da Sentinela, no Cerro Oeste. Após ler o pedido de reforços do Magistrado Salomão, Stoutmantle redigiu a resposta e confiou a você a tarefa de levá-la pelo reino de volta às Montanhas Cristarrubra.",al={"quem escreveu a resposta de mantoforte","quem fez a resposta de mantoforte a salomão","de onde veio a resposta de mantoforte"}},c46920a1={q="Por que alguém quer a Resposta de Mantoforte a Salomão?",a="O Magistrado Salomão aguarda esta resposta em Vila Plácida, na esperança de obter auxílio militar para afastar a invasão dos orcs Rocha Negra que ameaça as Montanhas Cristarrubra. Ele precisa da palavra de Stoutmantle para saber se a The People's Militia pode cavalgar para a defesa de Vila Plácida ou se sua cidade deve enfrentar os perigos sozinha.",al={"quem quer a resposta de mantoforte","por que entregar a carta de mantoforte","por que levar a resposta a salomão"}}},fp="33,116,13.458.0,21.393.1,42.230.0,57.236.0,48.253.0,52.254.0"}
P.entries["item:strange-smelling-powder"] = {n="Pó com Cheiro Estranho",s="O Pó com Cheiro Estranho é um resíduo enigmático descoberto durante investigações sobre sabotagens suspeitas ao redor de Loch Modan. Temido por ser um agente de demolição instável, ele faz com que o Engenheiro-chefe Hinderweir envie um mensageiro urgente ao norte em busca de um especialista em demolições.",h="O Pó com Cheiro Estranho é um resíduo enigmático descoberto durante investigações sobre sabotagens suspeitas...",kw={"uma ameaça sombria à espreita","ashlan risadura","dun modr","hinderweir","loch modan","pó com cheiro estranho","ponte thandol"},ang={["profession:Engineering"]="Engenheiros reconhecerão o cheiro de misturas explosivas sulfurosas e instáveis que não correspondem às fórmulas padrão usadas nos postos de mineração da Aliança.",["race:Dwarf"]="Para os anões, proteger as estruturas de pedra e os reservatórios de Loch Modan é primordial, tornando qualquer indício de explosivos inimigos uma crise imediata para o clã."},sec={{t="Uma Descoberta Volátil",b="Descoberto em meio a sinais de sabotagem que ameaçam a infraestrutura de Loch Modan, este pó peculiar imediatamente alarmou o Engenheiro-chefe Hinderweir. Seu odor pungente e consistência fina sugerem um composto de demolição projetado, em vez de pólvora de mineração padrão. Sem ter certeza da natureza química ou da origem da mistura, Hinderweir se recusa a manuseá-lo ele mesmo, sabendo que até mesmo uma faísca mínima poderia desencadear um desastre."},{t="A Estrada para o Norte",b="Como os engenheiros anões não se arriscam com reagentes voláteis, Hinderweir envia amostras do pó através do Portão de Algaz até o Pantanal. Lá, posicionado em Dun Modr perto da Ponte Thandol, o experiente especialista em explosivos Ashlan Risadura tem a tarefa de inspecionar os grãos para determinar que tipo de explosão catastrófica os sabotadores estão preparando."}},faq={{q="O que é o Pó com Cheiro Estranho?",a="É um resíduo químico suspeito recuperado em Loch Modan durante investigações sobre sabotagens locais. Seu odor fétido pungente e sua composição levam os engenheiros anões a suspeitar que se trate de um agente explosivo.",al={"o que e po com cheiro estranho","o que e este po","po loch modan"}},{q="Por que o Engenheiro-chefe Hinderweir quer que ele seja examinado?",a="Hinderweir suspeita que o pó seja um explosivo especializado. Para compreender a escala e a gravidade da trama que ameaça Loch Modan, ele precisa de uma análise profissional feita por alguém com profundo conhecimento em demolições pesadas.",al={"por que examinar po","po hinderweir","quem precisa deste po"}},{q="Quem pode identificar o pó?",a="O Engenheiro-chefe Hinderweir orienta os viajantes a levarem a amostra até Ashlan Risadura, um especialista em explosivos posicionado bem ao norte com o regimento em Dun Modr, perto da Ponte Thandol.",al={"quem identifica o po","onde levar o po","especialista em po"}},{q="Por que transportar o pó é perigoso?",a="Além da volatilidade inerente a um agente explosivo desconhecido, carregar a amostra exige enfrentar a perigosa jornada através do Portão de Algaz pelas estradas pantanosas e hostis do Pantanal.",al={"o po e perigoso","por que perigoso"}}},fp="23,168,20.322.0,14.284.1,32.196.0,52.153.0,28.158.0,41.130.0"}
P.entries["item:strangely-marked-box"] = {n="Caixa com Marcações Estranhas",s="Uma Caixa com Marcações Estranhas é uma peça de carga descoberta dentro dos arreios presos a tartarugas-marinhas mortas ao longo do litoral de Costa Negra. Seu exterior misterioso traz a escrita rúnica dos serpentinos nagas, oferecendo aos estudiosos elfos noturnos a prova de que essas criaturas marinhas não encalharam por acidente.",h="Uma Caixa com Marcações Estranhas é uma peça de carga descoberta dentro dos arreios presos a...",kw={"auberdine","carroça","costa negra","greymist","gwennyth bly'leggonde","naga","tartaruga-marinha","caixa com marcações estranhas"},ang={["class:Priest"]="Proteger as relíquias da costa ajuda os estudiosos de Templo da Lua em Auberdine em seu trabalho para resguardar o litoral contra a corrupção marinha.",["race:NightElf"]="Encontrar caixas de suprimentos nagas amarradas a tartarugas-marinhas nativas ao longo de Costa Negra alerta os kaldorei de que seus antigos parentes mutantes estão avançando sistematicamente para a costa a partir do Grande Oceano."},sec={{t="Troféus das Profundezas",b="Enquanto várias tartarugas-marinhas gigantes e criaturas do mar simplesmente chegam à costa ao longo das praias encobertas de névoa de Costa Negra, outras contam uma história muito mais sinistra. Carcaças espalhadas trazem os restos estilhaçados de arreios de montaria e carroças abandonadas amarradas diretamente aos seus cascos. Dentro das ruínas dessas engenhocas retorcidas encontram-se recipientes selados cobertos por runas sinuosas e desconhecidas. Murlocs Greymist necrófagos frequentemente se estabelecem nas caixas torácicas ocas e nas carroças quebradas, bicando a carniça e guardando quaisquer vestígios que tenham sido deixados para trás."},{t="Evidência da Expansão Naga",b="Quando levadas a Gwennyth Bly'Leggonde, uma pesquisadora que representa Templo da Lua em Auberdine, as marcações na caixa revelam sua verdadeira origem. A escrita e as carroças amarradas pertencem aos nagas, que usam tartarugas enormes como bestas de carga para transportar suprimentos logísticos e equipamentos de guerra para a terra firme. A descoberta dessas caixas de suprimentos confirma que os nagas estão operando deliberadamente ao longo das praias do norte e podem estar conduzindo montarias para o sul em direção a Vale Gris, levando o sacerdócio em Auberdine a enviar as relíquias diretamente para Darnassus para estudos mais aprofundados."}},faq={{q="Onde a Caixa com Marcações Estranhas é encontrada?",a="A caixa é recuperada de carroças abandonadas presas aos cascos de carcaças de Beached Sea Turtle ao longo da costa de Costa Negra. Essas carcaças costumam estar cercadas e defendidas por murlocs Greymist que se alimentam da carniça.",al={"onde encontrar caixa com marcações estranhas","localização da caixa","caixa da carroça de tartaruga"}},{q="Quem fez a Caixa com Marcações Estranhas?",a="A caixa e suas inscrições foram criadas pelos nagas. Eles prendem carroças de carga a tartarugas-marinhas vivas para transportar mantimentos, armas e equipamentos das profundezas do oceano até a costa de Kalimdor.",al={"quem fez a caixa","marcações na caixa","runas da caixa","o que são as marcações"}},{q="Quem quer esta caixa em Auberdine?",a="Gwennyth Bly'Leggonde, uma pesquisadora que trabalha em Auberdine em nome de Templo da Lua, recolhe a caixa para analisar os estranhos encalhes e compreender a crescente ameaça naga.",al={"a quem entregar isto","entrega da caixa","quem quer a caixa"}},{q="Por que as tartarugas-marinhas estavam carregando essas caixas?",a="Os nagas domesticam ou escravizam tartarugas-marinhas gigantes como animais de carga, prendendo arreios e carroças às suas costas para a batalha e para carregar seus suprimentos para a terra firme. Gwennyth suspeita que uma dessas tartarugas foi morta enquanto seguia mais para o sul, talvez em direção a Vale Gris.",al={"por que tartarugas têm caixas","carroças de tartaruga","por que as tartarugas estão com arreios"}},{q="O que acontece com a caixa depois de entregá-la a Gwennyth?",a="Gwennyth Bly'Leggonde encaminha a caixa e o restante das descobertas do levantamento costeiro para Templo da Lua em Darnassus, para que a liderança dos elfos noturnos possa estudar a extensão da incursão naga.",al={"para onde vai a caixa","caixa enviada para darnassus"}}},fx={["981461f5"]={q="O que é a Caixa com Marcações Estranhas?",a="É uma carga descoberta dentro de uma carroça danificada amarrada à carapaça de uma Beached Sea Turtle na costa de Costa Negra. Marcado com runas peculiares, o caixote serve como prova física de transporte marítimo organizado ao longo da costa, abandonado depois que a criatura que o transportava morreu e foi posteriormente invadida por carniceiros.",al={"o que é a caixa marcada","o que é caixa com marcações estranhas","item caixa com marcações estranhas"}},b4ce745f={q="Por que Gwennyth Bly'Leggonde quer a Caixa com Marcações Estranhas?",a="Gwennyth Bly'Leggonde procura a caixa em nome do Templo da Lua para investigar por que criaturas marinhas enormes estão encalhando em Costa Negra. Decifrar as marcações confirma que as tartarugas eram arreadas e usadas como bestas de carga por naga hostis transportando suprimentos para o interior, pistas que ela encaminha diretamente para estudiosos em Darnassus.",al={"por que gwennyth quer a caixa","por que entregar caixa com marcações estranhas","propósito da caixa marcada"}}},fp="20,168,20.323.0,26.395.1,40.154.0,34.171.0,32.145.0,46.218.0,52.162.0"}
P.entries["item:strigid-owl-feather"] = {n="Pena Estrígida de Coruja",s="Strigid Owl Feathers são coletadas das corujas estrigídeas selvagens que fazem ninhos nos galhos de Teldrassil. Embora sejam penas naturais da floresta, elas são cobiçadas por figuras suspeitas em busca de matérias-primas para seus negócios escusos.",h="Strigid Owl Feathers são coletadas das corujas estrigídeas selvagens que fazem ninhos nos galhos de...",kw={"dolanaar","reagentes","coruja estrigídea","pena estrígida de coruja","gritadeira estrigídea","teldrassil","zenn cascovil"},ang={["class:Druid"]="Os druidas têm grande apreço pelos caçadores emplumados de Teldrassil, tornando perturbador ver sua plumagem recolhida sob falsos pretextos para reagentes suspeitos.",["race:NightElf"]="As corujas de Teldrassil são consideradas criaturas de Eluna, tornando sua exploração por um sátiro remanescente como Zenn Cascovil um insulto ao bosque sagrado."},sec={{t="Penugem da Floresta e Negócios Sombrios",b="As copas de Teldrassil abrigam corujas estrigídeas e gritadeiras, aves de rapina nativas que caçam por toda a Coroa da Terra. Embora sua penugem e suas penas sejam vestígios comuns no chão da floresta, elas ocasionalmente chamam a atenção de praticantes em busca de reagentes orgânicos. Nos arredores de Dolanaar, o sátiro renegado Zenn Cascovil se aproveita de viajantes inexperientes que descem pela estrada vinda de Umbravale, enganando-os para que coletem penas de estrigídeo junto com seda de aranha e presas de sabre-da-noite para seus próprios negócios escusos."}},faq={{q="Onde posso encontrar Strigid Owl Feathers?",a="Essas penas são obtidas de corujas estrigídeas e gritadeiras estrigídeas que habitam os bosques ao redor de Dolanaar e por toda Teldrassil.",al={"localização das penas","onde caem strigid owl feathers","farm de pena de coruja"}},{q="Quem quer Strigid Owl Feathers?",a="Um sátiro chamado Zenn Cascovil, à espreita ao longo da trilha que leva a Dolanaar, pede a aventureiros ingênuos que as tragam junto com teia de seda e presas de sabre-da-noite.",al={"quem precisa de penas de coruja","entrega de penas de coruja","pena de coruja zenn"}},{q="Para que Zenn Cascovil usa as penas?",a="Zenn afirma que elas são reagentes necessários para seus negócios secretos na floresta, embora ele aprecie principalmente enganar recrutas desavisados para que façam seu trabalho sujo.",al={"por que zenn quer penas","propósito do reagente de zenn"}}},fx={c56fcaa2={q="O que é uma Pena Estrígida de Coruja?",a="Uma Pena Estrígida de Coruja é uma pluma coletada das corujas estrígidas predatórias nativas dos galhos de Teldrassil. Embora pareçam penas comuns de pássaros, elas servem como potentes reagentes naturais para aqueles que se aventuram em ofícios, alquimia ou ritos florestais mais sombrios.",al={"pena estrígida de coruja","o que é a pena estrígida de coruja","pena de coruja de teldrassil"}},["91562481"]={q="De onde vem uma Pena Estrígida de Coruja?",a="Essas penas são colhidas diretamente de corujas estrígidas e gritadores estrígidos que fazem ninhos por todas as florestas de Teldrassil, particularmente nos arredores de Dolanaar. Como materiais biológicos naturais que caem ou são tirados dos predadores aviários da floresta, elas são produzidas pela natureza em vez de criadas por mãos mortais.",al={"de onde vêm as penas estrígidas de coruja","origem da pena estrígida de coruja","quem fez a pena estrígida de coruja"}}},fp="19,121,32.327.1,38.133.0,31.125.0,45.147.1"}
P.entries["item:sturdy-dragonmaw-shinbone"] = {n="Tíbia Firme de Presa do Dragão",s="Dragonmaw Shinbones são troféus esqueléticos duráveis obtidos dos orcs renegados Presa do Dragão no Pantanal. Requisitados pela criadora de armaduras Velora Noitile na Cidade Baixa, eles servem como suportes de reforço para armaduras sob medida de guerreiro.",h="Dragonmaw Shinbones são troféus esqueléticos duráveis obtidos dos orcs renegados Presa do Dragão no Pantanal.",kw={"acampamento presirada","tíbia de presa do dragão","perneiras","tíbia firme de presa do dragão","cidade baixa","velora noitile","pantanal"},ang={["class:Warrior"]="Obter e testar esses ossos densos de orc com as próprias mãos prova a força física de um guerreiro enquanto reúne as peças estruturais para uma armadura personalizada.",["race:Undead"]="Velora Noitile representa o pragmatismo típico dos Renegados, reaproveitando os ossos de seus inimigos em equipamentos funcionais para os campeões da Dama Sombria."},sec={{t="Ossos para a Estrutura",b="Ao forjar perneiras brutais para guerreiros da linha de frente, ferreiros necessitam de componentes brutos que possam suportar severas punições. Na Cidade Baixa, Velora Noitile valoriza a densidade esquelética dos orcs renegados Presa do Dragão entrincheirados no Acampamento Presirada, na região central do Pantanal. Os orcs Presa do Dragão são conhecidos por suas estruturas ósseas grossas e robustas, tornando suas canelas bem adequadas para servir como braçadeiras estruturais. No entanto, nem todo osso coletado suporta o esforço; os guerreiros devem testar cada peça com as próprias mãos, descartando aquelas que quebram sob pressão."}},faq={{q="O que torna essas tíbias resistentes em comparação com as normais?",a="Os orcs Presa do Dragão possuem estruturas esqueléticas naturalmente grossas, mas fraturas menores ou ossos quebradiços tornam muitas amostras inúteis para forjar armaduras. Para confirmar que uma é resistente, um guerreiro dobra o osso bruto com as próprias mãos; apenas aqueles que resistem à quebra são considerados fortes o suficiente para estruturar perneiras protetoras.",al={"por que tíbias resistentes","força dos ossos presa do dragão","testando tíbias"}},{q="Quem quer Sturdy Dragonmaw Shinbones?",a="Velora Noitile, uma armureira localizada na Cidade Baixa, está à procura deles. Ela os utiliza como suportes estruturais principais ao criar perneiras brutais para guerreiros promissores da Horda.",al={"quem precisa de tíbias","ossos de velora noitile","entregar dragonmaw shinbones"}},{q="Onde esses ossos são obtidos?",a="Eles são retirados dos orcs renegados Presa do Dragão que ocupam o Pantanal ao sul do Planalto Arathi, principalmente no Acampamento Presirada, situado nas colinas a sudoeste da Ponte Thandol.",al={"onde encontrar dragonmaw shinbones","localização da tíbia de presa do dragão","ossos de presirada"}},{q="Por que Velora Noitile usa ossos de orc para armaduras?",a="O artesanato dos Renegados frequentemente integra ossos, tendões e metal em equipamentos de guerra mórbidos, porém altamente duráveis. O clã Presa do Dragão permanece hostil à Horda de Thrall, tornando seus restos mortais alvos legítimos para ferreiros Renegados que procuram materiais de criação resistentes e pesados.",al={"por que ossos de orc","armadura de osso dos renegados","criação com ossos da velora"}}},fp="25,163,19.292.0,58.180.0,37.166.0,31.189.0,47.185.0"}
P.entries["item:sully-balloo-s-letter"] = {n="Carta de Floriano Caxias",s="A Carta de Floriano Caxias é uma missiva encharcada e afetuosa resgatada dos restos submersos de um soldado anão sob a Ponte Thandol. Endereçada à sua esposa Sara em Altaforja, ela representa as tragédias pessoais silenciosas que persistem sob os grandiosos conflitos de Khaz Modan.",h="A Carta de Floriano Caxias é uma missiva encharcada e afetuosa resgatada dos restos submersos de um soldado...",kw={"planalto arathi","altaforja","carta","sara caxias","sully balloo","ponte thandol","envelope encharcado","pantanal"},ang={["faction:Alliance"]="Entregar a carta oferece um momento solene de compaixão, garantindo que os últimos pensamentos de um soldado caído alcancem sua viúva em vez de serem esquecidos sob a ponte.",["race:Dwarf"]="Para os anões, a carta representa os sacrifícios dolorosos que montanheses e soldados comuns fazem para proteger as pontes altas e as passagens montanhosas de Khaz Modan."},sec={{t="Um Último Adeus Sob as Ondas",b="Sob os imensos pilares de pedra da Ponte Thandol, que liga o Pantanal ao Planalto Arathi, jazem os restos esqueléticos de um anão preso nas profundezas das águas turbulentas. Preso em suas mãos está um envelope frágil e encharcado que contém esta carta. Escrita com extremo cuidado em seus últimos dias ou horas, ela começa com as comoventes palavras: 'Minha querida Sara...'. Embora o pergaminho tenha sofrido com a submersão prolongada, a tinta ainda preserva o amor eterno de um defensor anão que nunca conseguiu voltar para casa, na cidade de Altaforja."},{t="Entrega em Altaforja",b="Levar a carta a Sara Caxias em Altaforja proporciona um desfecho sombrio e devastador. Morando na capital dos anões, Sara suporta a incerteza agonizante compartilhada por tantos cujos parentes marcharam para a guerra. Ler os últimos pensamentos de seu marido Sully confirma seus piores receios — de que ele pereceu longe de casa sob as correntes gélidas da travessia do norte —, mas preserva sua devoção para além da morte."}},faq={{q="Onde a Carta de Floriano Caxias é encontrada?",a="A carta é resgatada de um envelope encharcado segurado pela mão de um esqueleto de anão submerso no leito das águas sob a Ponte Thandol, que separa o Pantanal do Planalto Arathi.",al={"localização da carta","onde está a carta de sully","onde encontrar a carta de sully balloo"}},{q="Quem foi Sully Balloo?",a="Sully Balloo foi um soldado anão que perdeu a vida perto da Ponte Thandol durante a defesa da vital travessia do norte, deixando seus restos presos sob as correntes do rio.",al={"quem é sully balloo","história de sully balloo","o que aconteceu com sully"}},{q="A quem a carta é endereçada?",a="A carta é endereçada à Sra. Sara Caxias, a esposa em luto de Sully, que vive na grande cidade montanhosa dos anões de Altaforja.",al={"quem recebe a carta","quem é sara caxias","onde entregar a carta de sully"}},{q="O que acontece quando você entrega a carta a Sara Caxias?",a="Ao receber a carta, Sara Caxias fica com o coração partido ao saber que seu marido jaz morto sob as águas gélidas, mas valoriza imensamente a oportunidade de ler as últimas palavras que ele lhe escreveu com tanto amor.",al={"reação de sara caxias","entregando a carta","conclusão da missão da carta de sully"}}},fx={efe638b9={q="O que é a Carta de Floriano Caxias?",a="É uma carta terna e marcada pela guerra, escrita com extremo cuidado por um soldado anão chamado Sully Balloo. Encontrada preservada sob as águas geladas da The Thandol Span, ela contém as últimas palavras sinceras escritas para sua esposa em Altaforja antes de sua morte em batalha.",al={"o que é a carta de floriano","carta de floriano caxias","sobre a carta de floriano caxias"}},b8624ec6={q="De onde vem a Carta de Floriano Caxias e quem a fez?",a="A carta foi escrita por Sully Balloo, um soldado da Aliança servindo nas linhas de frente da The Thandol Span, entre o Pantanal e o Planalto Arathi. Ela sobreviveu submersa em um envelope encharcado, mantido na garra de seus restos mortais submersos sob a grande ponte.",al={"quem escreveu a carta de floriano caxias","de onde veio a carta de floriano","criador da carta de floriano caxias"}},b54d6872={q="Por que alguém quer a Carta de Floriano Caxias?",a="Sua destinatária, Sara Caxias, reside em Altaforja, sem saber da trágica morte de seu marido. Entregar a carta cumpre o último desejo de um soldado caído e traz um encerramento agridoce para uma viúva em luto que aguarda notícias de seu amado.",al={"por que entregar a carta de floriano caxias","quem quer a carta de floriano","por que levar a carta para sara caxias"}}},fp="21,158,34.417.0,21.302.1,37.168.0,21.155.0,31.82.0,56.160.1"}
P.entries["item:sundried-driftwood"] = {n="Sundried Driftwood",s="Sundried Driftwood se espalha pelo litoral do Pântano das Mágoas. Vigia Biggs precisa de madeira seca e resistente para consertar sua carroça.",h="Sundried Driftwood se espalha pelo litoral do Pântano das Mágoas.",kw={"litoral","madeira à deriva","etergarde","sundried driftwood","pântano das mágoas","carroça","vigia biggs"},sec={{t="Madeira do litoral",b="Vigia Biggs precisa de madeira para consertar a carroça, mas as árvores do pântano são encharcadas e retorcidas. No litoral leste, o sol seca a madeira à deriva, deixando-a leve e resistente para servir a esse propósito."}},faq={{q="Onde posso encontrar Sundried Driftwood?",a="Sundried Driftwood pode ser encontrada no litoral do Pântano das Mágoas. Vigia Biggs indica que você procure a leste.",al={"localização de sundried driftwood","onde encontrar madeira à deriva","madeira do litoral"}},{q="Quem precisa da madeira à deriva?",a="Vigia Biggs precisa de Sundried Driftwood para consertar sua carroça.",al={"quem quer madeira à deriva","madeira para biggs","quem precisa da madeira"}},{q="Por que Biggs precisa dessa madeira?",a="Vigia Biggs precisa de madeira seca e resistente para consertar sua carroça e chegar a Etergarde.",al={"por que biggs precisa de madeira","conserto de carroça","consertar a carroça de biggs"}},{q="Por que não usar as árvores do pântano?",a="Vigia Biggs diz que as árvores do pântano são encharcadas e retorcidas, então procura madeira seca à deriva no litoral.",al={"madeira das árvores do pântano","por que não usar madeira do pântano","madeira encharcada"}},{q="Como é essa madeira à deriva?",a="Vigia Biggs diz que a madeira é leve, mas resistente, e que servirá bem para sua carroça.",al={"a madeira à deriva é resistente","qualidade da madeira","madeira leve e resistente"}},{q="Quantos pedaços Biggs precisa?",a="Vigia Biggs pede oito pedaços de Sundried Driftwood.",al={"quanto de madeira à deriva","quantidade de pedaços","oito pedaços de madeira à deriva"}}},fp="18,115,19.189.0,36.111.0,24.59.0,30.85.0,28.102.0,27.89.0,32.58.0"}
P.entries["item:sunscorched-shell"] = {n="Casca Queimada de Sol",s="Cascas queimadas de sol são os restos resistentes de ovos de mantícora recolhidos sob os poleiros de Alcândora em Mil Agulhas. Endurecidas pelo calor inclemente do deserto, elas são muito valorizadas por armeiros habilidosos capazes de transformá-las em uma laca protetora para elos de cota de malha.",h="Cascas queimadas de sol são os restos resistentes de ovos de mantícora recolhidos sob os poleiros de...",kw={"darnassus","furen barbalonga","alcândora","cota de malha","mathiel","casca queimada de sol","mil agulhas","mantícora"},ang={["class:Warrior"]="Guerreiros em busca de uma proteção de malha sob medida ajudam Mathiel a recolher essas cascas de ovo duráveis para confeccionar armaduras reforçadas.",["profession:Blacksmithing"]="Essas cascas mostram como ferreiros astutos vão além dos minérios comuns, transformando revestimentos minerais naturais em lacas protetoras para armaduras de elos."},sec={{t="Ninhadas do Deserto",b="Aninhadas no alto das agulhas de platô do sul de Kalimdor, as mantícoras de Alcândora põem ovos que resistem ao sol implacável do deserto e aos ventos abrasadores. Os fragmentos de casca descartados se acumulam sob seus poleiros, cozidos até uma dureza notável pelo clima árido. Embora pareçam pouco mais do que refugo quebradiço para um viajante desavisado, esses restos queimados pelo sol possuem uma resiliência estrutural natural que os torna um reagente intrigante para artesãos especializados."},{t="A Laca do Artesão",b="Em Darnassus, o armeiro Mathiel estuda métodos de forja pioneirizados por seu colega, o ferreiro anão Furen Barbalonga. Intrigado com as descobertas de Furen, Mathiel usa essas cascas para criar uma laca fina capaz de reforçar cotas de malha. Quando devidamente processado e aplicado, o revestimento rico em minerais se fixa aos elos metálicos, adicionando uma resistência substancial sem sobrecarregar o usuário."}},faq={{q="Onde as Cascas Queimadas de Sol são encontradas?",a="Elas estão espalhadas pelo chão, sob os ninhos de mantícoras por toda Alcândora, uma alta elevação rochosa que desponta do fundo do desfiladeiro no oeste de Mil Agulhas.",al={"localização da casca queimada de sol","onde encontrar cascas","cascas de alcândora"}},{q="De qual criatura vêm essas cascas?",a="São as cascas de ovos quebradas das mantícoras de Alcândora que fazem seus poleiros no topo dos planaltos em Mil Agulhas.",al={"o que botou estes ovos","ovos de mantícora","origem das cascas"}},{q="Por que Mathiel quer as Cascas Queimadas de Sol?",a="Mathiel busca testar técnicas de forja de armaduras descobertas por Furen Barbalonga. Ele funde as cascas endurecidas até transformá-las em uma laca resistente para revestir e reforçar os elos de cotas de malha.",al={"cascas de mathiel","para que servem as cascas","laca de armadura"}},{q="Quem é Furen Barbalonga e como ele está envolvido?",a="Furen Barbalonga é um ferreiro colega de Mathiel estabelecido no Distrito dos Anões de Ventobravo. Seus experimentos com reagentes pouco ortodoxos e técnicas de têmpera inspiraram Mathiel a testar a laca feita a partir de cascas de ovos de mantícora.",al={"conexão com furen","cascas de furen barbalonga"}}},fx={f589915a={q="O que é uma Casca Queimada de Sol?",a="Uma Casca Queimada de Sol é a casca de ovo durável e descartada de um serpe de Alcândora. Encontradas assadas sob o sol forte das Mil Agulhas, abaixo dos ninhos elevados das criaturas, essas cascas resistentes possuem uma força natural notável que as torna valiosas para armeiros habilidosos.",al={"o que é a casca queimada de sol","item casca queimada de sol","casca de ovo queimada de sol"}}},fp="17,131,15.237.0,21.234.0,35.126.0,40.102.0,41.153.0,46.211.0"}
P.entries["item:super-reaper-6000-blueprints"] = {n="Diagramas do Super Ceifador 6000",s="Os Diagramas do Super Ceifador 6000 são os esquemas técnicos de um enorme lenhador mecanizado utilizado pela Empreendimentos S.A. na Cordilheira das Torres de Pedra. Projetados sob a supervisão do engenheiro gnomo Hanfritz Schaventorck, os planos são intensamente cobiçados por seus rivais goblins descontentes.",h="Os Diagramas do Super Ceifador 6000 são os esquemas técnicos de um enorme lenhador mecanizado utilizado pela...",kw={"diagramas","hanfritz","cobogó","cordilheira das torres de pedra","super ceifador 6000","empreendimentos s.a.","rochedo cortavento","zé fízzica"},ang={["profession:Engineering"]="Os diagramas refletem uma mistura bizarra entre a força corporativa rústica dos goblins e o design mecânico meticuloso dos gnomos, apresentando esquemas técnicos que desconcertam engenhoqueiros comuns.",["race:Gnome"]="Os diagramas de Hanfritz Schaventorck provam que até mesmo sindicatos implacáveis de goblins, como a Empreendimentos S.A., dependem em última análise da engenhosidade gnômica para construir maquinário pesado complexo."},sec={{t="Espionagem Industrial no Rochedo Cortavento",b="A implacável operação de desmatamento da Empreendimentos S.A. no Rochedo Cortavento depende de colheitadeiras de madeira mecanizadas massivas, conhecidas como Super Ceifadores. Para a total consternação dos engenheiros goblins tradicionais, a companhia colocou um gnomo chamado Hanfritz encarregado de projetar o modelo Super Ceifador 6000. Estes diagramas contêm os esquemas da engenhoca, carregados por operadores da Empreendimentos S.A. que operam o maquinário por todo o rochedo. Quando o engenheiro goblin Zé Fízzica foi expulso da operação, ele foi rapidamente contratado por Cobogó para roubar os projetos. No entanto, decifrar as anotações técnicas gnômicas densas e excêntricas de Hanfritz prova ser quase tão difícil quanto obter os diagramas à força."}},faq={{q="O que é o Super Ceifador 6000?",a="É um enorme dispositivo mecanizado de corte de madeira desenvolvido para as operações de corte raso da Empreendimentos S.A. na Cordilheira das Torres de Pedra, projetado para derrubar e processar madeira com eficiência industrial implacável.",al={"o que e super ceifador","maquina super ceifador"}},{q="Quem projetou o Super Ceifador 6000?",a="Os planos foram elaborados sob a liderança de Hanfritz Schaventorck, um engenheiro gnomo contratado pela Empreendimentos S.A. para liderar seus projetos mecânicos no Rochedo Cortavento, para desgosto dos mecânicos goblins locais.",al={"quem fez diagramas","quem projetou super ceifador"}},{q="Por que Zé Fízzica quer esses diagramas?",a="Zé foi demitido da Empreendimentos S.A. e imediatamente contratado por Cobogó. Roubar os projetos do Super Ceifador é a chance de Zé provar seu valor e genialidade mecânica para seu novo chefe.",al={"por que ze quer planos","quem quer diagramas"}},{q="Quem guarda os diagramas no Rochedo Cortavento?",a="Os esquemas físicos são transportados por Operadores da Empreendimentos S.A. que supervisionam ativamente o maquinário e o desmatamento ao longo do Rochedo Cortavento.",al={"onde caem diagramas","quem saqueia diagramas"}}},fp="28,235,38.481.0,30.131.0,35.214.0,43.156.0,43.120.0"}
P.entries["item:super-snapper-fx"] = {n="Superinstantânea FX",s="A Superinstantânea FX é a câmera de Curgle, emprestada a você por Daryn Aelumnis na Vila de Rut'theran. Ela quer uma foto de Gammerita, uma criatura das Terras Agrestes.",h="A Superinstantânea FX é a câmera de Curgle, emprestada a você por Daryn Aelumnis na Vila de Rut'theran.",kw={"c amate","c câmera","câmera","cargle","daryn aelumnis","gammerita","foto instantânea","superinstantânea","superinstantânea fx"},sec={{t="Uma Nova Invenção",b="Daryn Aelumnis manda você procurar Curgle para buscar sua nova invenção, a Superinstantânea FX. Ela pede uma foto de Gammerita, a criatura das Terras Agrestes, e espera que você leve a imagem de volta à Vila de Rut'theran. Curgle diz para mirar no seu alvo e apertar o botão."}},faq={{q="O que é a Superinstantânea FX?",a="A Superinstantânea FX é uma câmera feita por Curgle. Daryn Aelumnis a empresta a você para fotografar Gammerita.",al={"superinstantânea","câmera instantânea"}},{q="Quem quer uma foto de Gammerita?",a="Daryn Aelumnis, na Vila de Rut'theran, pede que você traga de volta uma foto de Gammerita, das Terras Agrestes.",al={"quem precisa da foto","foto de daryn"}},{q="Quem fez a Superinstantânea FX?",a="Curgle construiu a Superinstantânea FX para Daryn Aelumnis.",al={"quem construiu a câmera","invenção de curgle"}},{q="O que a Superinstantânea FX faz?",a="Aponte a Superinstantânea FX para o que você quer fotografar e aperte o botão.",al={"como funciona a câmera","botão da câmera"}}},fp="16,161,15.275.0,29.112.0,33.106.0,30.54.0,34.77.0"}
P.entries["item:super-sticky-tar"] = {n="Super Sticky Tar",s="No norte da Cratera Un’Goro, o alcatrão das feras perto dos poços gruda com força incomum. Tran'rek, em Geringontzan, quer amostras para uma ideia lucrativa de cola.",h="No norte da Cratera Un’Goro, o alcatrão das feras perto dos poços gruda com força incomum.",kw={"clorofila","geringontzan","cola","super sticky","super sticky tar","alcatrão","feras de alcatrão","tran'rek","cratera un’goro"},sec={{t="Alcatrão dos Poços",b="Tran'rek pede que você reúna alcatrão das feras perto dos poços ao norte da Cratera Un’Goro. A pele delas contém clorofila, que, segundo ele, deixa o alcatrão muito mais pegajoso que o alcatrão comum. Ele espera transformar a mistura em uma cola útil."}},faq={{q="De onde vem o Super Sticky Tar?",a="Você coleta Super Sticky Tar das feras de alcatrão perto dos poços ao norte da Cratera Un’Goro.",al={"de onde vem o alcatrão","origem do super sticky"}},{q="Quem quer o alcatrão?",a="Tran'rek, em Geringontzan, quer amostras de Super Sticky Tar para sua ideia de cola.",al={"quem precisa de alcatrão","tran'rek alcatrão"}},{q="Por que esse alcatrão é tão pegajoso?",a="Tran'rek diz que a pele das feras, rica em clorofila, se mistura ao alcatrão e o deixa excepcionalmente pegajoso.",al={"por que é pegajoso","motivo do alcatrão pegajoso"}},{q="O que Tran'rek planeja fazer com ele?",a="Tran'rek espera produzir uma cola lucrativa com o alcatrão e a clorofila da pele das feras.",al={"plano de tran'rek","para que serve a cola"}}},fp="16,152,17.228.0,38.90.0,18.74.0,26.97.0,38.94.0"}
P.entries["item:supplies-for-sven"] = {n="Suprimentos para Noel",s="Suprimentos para Noel é um pacote de provisões vitais empacotado em Vila Sombria e destinado ao acampamento isolado de Noel Figueira. Cercados pelos horrores da Floresta do Crepúsculo, Noel e seu pequeno bando dependem de habitantes compreensivos da vila, como a família Carevino, para sustentar sua vigília contra as sombras.",h="Suprimentos para Noel é um pacote de provisões vitais empacotado em Vila Sombria e destinado ao acampamento...",kw={"acampamento","carevino","vila sombria","floresta do crepúsculo","provisões","suprimentos para noel","noel figueira"},ang={["class:Paladin"]="A firme resistência de Noel contra a escuridão na Floresta do Crepúsculo é vista pelos piedosos como uma verdadeira obra da Luz, tornando estas provisões um serviço vital a um irmão de fé.",["faction:Alliance"]="Com a Vigília Noturna sobrecarregada defendendo Vila Sombria, viajantes da Aliança costumam servir como o único elo confiável de mensageiros para postos avançados isolados como o acampamento de Noel."},sec={{t="Uma Linha de Vida para o Acampamento",b="Carregar equipamentos de sobrevivência e itens de primeira necessidade pela Floresta do Crepúsculo não é uma tarefa simples. Noel Figueira e seu punhado de seguidores acampam na natureza selvagem a noroeste da floresta, longe da segurança de Vila Sombria. Seu número está tão reduzido e sua vigília é tão exigente que eles não podem dispensar um único combatente para fazer a viagem até a vila. Esta encomenda representa uma salvação enviada pela família Carevino, garantindo que o acampamento isolado tenha a comida, as bandagens e os materiais necessários para manter sua posição."}},faq={{q="Quem enviou estes suprimentos?",a="Os suprimentos são enviados por intermédio da família Carevino de Vila Sombria. Reconhecendo a luta desesperada que Noel Figueira enfrenta na selva, eles providenciam essas provisões para apoiar seu acampamento.",al={"quem enviou suprimentos para noel","quem embalou os suprimentos de noel","suprimentos da família carevino"}},{q="Por que Noel não pode buscar seus próprios suprimentos?",a="O grupo de Noel está sobrecarregado demais. Com apenas alguns companheiros sobreviventes vigiando o acampamento no noroeste da Floresta do Crepúsculo contra feras e mortos-vivos, eles não podem dispensar ninguém para percorrer as perigosas estradas até Vila Sombria.",al={"por que noel não busca comida","por que entrega para noel","por que precisa de suprimentos"}},{q="Onde fica o acampamento de Noel?",a="O acampamento de Noel fica situado ao longo do limite noroeste da Floresta do Crepúsculo, escondido nas colinas bem além da proteção direta da Vigília Noturna.",al={"onde fica noel figueira","localização do acampamento de noel","encontrar noel floresta do crepúsculo"}},{q="Quem é Noel Figueira?",a="Noel Figueira é um desbravador e devoto fervoroso da Luz que costumava cultivar na Floresta do Crepúsculo. Após uma tragédia atingir sua propriedade, ele estabeleceu um acampamento armado na fronteira para combater as forças sombrias que assolam a região.",al={"quem é noel","história de noel figueira"}}},fx={["0c0166a3"]={q="O que são os Suprimentos para Noel?",a="Esses suprimentos são um pacote de assistência reunido para apoiar Noel Figueira e seu pequeno grupo de seguidores que resistem na Floresta do Crepúsculo. A The Carevin Family prepara regularmente tal auxílio para que esses devotos cruzados possam continuar fazendo o trabalho da Luz contra os horrores que assombram a floresta sombria sem abandonar sua vigília.",al={"o que são os suprimentos para noel","quais são os suprimentos de noel","item suprimentos para noel"}}},fp="17,177,23.274.0,24.125.0,38.195.0,29.114.0,19.227.0"}
P.entries["item:supply-crate-blasted-lands"] = {n="Caixote de Suprimentos",s="O Caixote de Suprimentos é equipamento de escavação abandonado que Sigrun Derrubaferro procura nos Ermos. Seu conteúdo pode ajudar sua companhia faminta.",h="O Caixote de Suprimentos é equipamento de escavação abandonado que Sigrun Derrubaferro procura nos Ermos.",kw={"ermos","acampamento kosh","escavação","comida","mirages","sigrun derrubaferro","caixote de suprimentos","uldaman"},sec={{t="Deixado para Trás",b="Depois de deixar às pressas o sítio de escavação de Uldaman, a companhia de Sigrun Derrubaferro abandonou carroças e caixotes de suprimentos. Ogros do Acampamento Kosh tomaram seus equipamentos, incluindo um carrinho que transportava armas. A companhia ficou sem comida, e Sigrun pede que você recupere um Caixote de Suprimentos."}},faq={{q="Quem quer o Caixote de Suprimentos?",a="Sigrun Derrubaferro quer que você recupere o Caixote de Suprimentos para sua companhia nos Ermos.",al={"quem precisa do caixote","caixote da sigrun"}},{q="Onde o Caixote de Suprimentos foi deixado?",a="O caixote estava entre os suprimentos abandonados quando a companhia de Sigrun Derrubaferro fugiu do sítio de escavação de Uldaman.",al={"localização do caixote","onde está o caixote"}},{q="Por que Sigrun precisa do caixote?",a="A companhia de Sigrun perdeu seus suprimentos de comida depois que ogros do Acampamento Kosh tomaram seus equipamentos. Ela pede que você recupere um Caixote de Suprimentos.",al={"por que o caixote","precisam de suprimentos"}},{q="O que os ogros levaram?",a="Ogros do Acampamento Kosh tomaram os equipamentos abandonados da companhia, incluindo um carrinho que transportava armas.",al={"ogros do acampamento kosh","o que os ogros roubaram"}},{q="O que acontece quando você volta?",a="Sigrun agradece e diz que a companhia sairá naquela noite para procurar comida.",al={"conclusão do caixote","resposta da sigrun"}}},fp="12,131,11.279.0,27.86.0,32.106.0,31.130.0,24.97.0,29.77.1"}
P.entries["item:surena-s-choker"] = {n="Gargantilha de Surena",s="A Gargantilha de Surena é um colar encantado de pedra-sangrenta dado de presente por Gakin, o Neromante à sua antiga aprendiz, Surena Caledon. Após Surena trair Gakin e fugir para se juntar à Irmandade Défias, o mestre bruxo enviou acólitos aspirantes para recuperar a peça à força.",h="A Gargantilha de Surena é um colar encantado de pedra-sangrenta dado de presente por Gakin, o Neromante à sua...",kw={"gargantilha de pedra-sangrenta","plantação de abóboras dos braga","erlan drudgemoor","gakin, o neromante","slaughtered lamb","surena caledon","gargantilha de surena"},ang={["class:Warlock"]="Recuperar esta gargantilha de Surena Caledon é uma provação fundamental para bruxos Humanos e Gnomos, demonstrando que o sentimentalismo não tem lugar na busca pelo poder demoníaco."},sec={{t="O Investimento Perdido de um Mestre",b="Gakin, o Neromante, operando silenciosamente sob The Slaughtered Lamb em Ventobravo, acolheu Surena Caledon como uma estudante promissora nas artes sombrias. Encantado com seu charme juvenil e aptidão mágica, Gakin a presenteou com uma valiosa Gargantilha de Pedra-sangrenta para auxiliá-la em seus estudos. No entanto, Surena abandonou seu treinamento e fugiu com Erlan Drudgemoor, um ladino aliado à Irmandade Défias. Relutante em deixar um artefato tão potente nas mãos de uma traidora, Gakin incumbe os iniciados que buscam o domínio sobre o caos a rastrear Surena até a Plantação de Abóboras dos Braga, recuperar o colar e demonstrar onde reside a verdadeira lealdade."}},faq={{q="Por que Gakin, o Neromante quer a Gargantilha de Surena de volta?",a="Gakin presenteou Surena com a gargantilha de pedra-sangrenta quando ela ainda era sua aprendiz. Quando ela abandonou os estudos e fugiu com um membro da Irmandade Défias, Gakin recusou-se a permitir que uma traidora ficasse com um artefato tão valioso de magia sombria.",al={"por que gakin quer a gargantilha","colar gakin surena","por que recuperar a gargantilha"}},{q="Quem é Surena Caledon?",a="Surena Caledon é uma ex-aprendiz de bruxo em Ventobravo que demonstrou talento natural sob a tutela de Gakin, o Neromante. Ela virou as costas para seu tutor para fugir com Erlan Drudgemoor e se esconder entre os foras da lei Defias na Floresta de Elwynn.",al={"quem é surena","história de surena caledon","quem está com a gargantilha"}},{q="Onde a gargantilha pode ser encontrada?",a="A gargantilha é carregada pela própria Surena Caledon, que está escondida entre os bandidos Defias na Plantação de Abóboras dos Braga, no leste da Floresta de Elwynn.",al={"onde está surena","localização da gargantilha","onde fica surena caledon"}},{q="Para que a gargantilha é usada depois de ser recuperada?",a="Recuperar a gargantilha prova a crueldade e a lealdade de um acólito a Gakin, o Neromante. Gakin nunca diz o que fará com ela; ele apenas lamenta o talento desperdiçado de Surena e espera que seu investimento no novo estudante traga resultados diferentes.",al={"o que gakin faz com a gargantilha","propósito da gargantilha","por que os bruxos precisam da gargantilha"}}},fx={["195efbf9"]={q="O que é a Gargantilha de Surena?",a="É um colar de pedra-sangue ornamentado que pertencia originalmente a Gakin, o Neromante, o mestre bruxo que reside no The Slaughtered Lamb em Ventobravo. Gakin presenteou a preciosa joia à sua antiga aprendiz, Surena Caledon, quando ele estava fascinado pela juventude e beleza dela, antes de ela o trair.",al={"o que é a gargantilha de surena","gargantilha de surena o que é","gargantilha de pedra-sangrenta"}},["7b9593ae"]={q="De onde vem a Gargantilha de Surena e quem a fez?",a="O artesão preciso da gargantilha é desconhecido, mas ela estava originalmente sob a posse de Gakin, o Neromante. Gakin presenteou a jovem estudante Surena Caledon com o colar de pedra-sangue durante o tempo em que ela foi sua aprendiz, muito antes de ela fugir com um ladino da Defias para a plantação de abóboras em Elwynn.",al={"quem fez a gargantilha de surena","origem da gargantilha de surena","de onde veio a gargantilha"}}},fp="15,236,26.570.0,56.212.0,22.220.0,30.138.0,50.235.0"}
P.entries["item:swoop-gizzard"] = {n="Moela de Rapineiro",s="A Moela de Rapineiro é um órgão obtido das aves predatórias que sobrevoam Mulgore. Muito procurada para remédios populares tradicionais, ela serve como ingrediente crucial para purificar toxinas letais.",h="A Moela de Rapineiro é um órgão obtido das aves predatórias que sobrevoam Mulgore.",kw={"aldeia casco sangrento","moela","maur clamachuva","mazzranache","mulgore","remedio","rapineiro"},ang={["race:Tauren"]="Para caçadores e xamãs taurens, coletar essas partes honra a tradição de usar cada pedaço da vida selvagem de Mulgore para sustentar e curar a tribo."},sec={{t="Um Ingrediente Popular Raro",b="Os rapineiros são caçadores aviários predatórios nativos das planícies e platôs de Mulgore, conhecidos por sua visão aguçada e hábitos necrófagos. Enquanto suas penas e carne têm utilidades cotidianas para os taurens, seus órgãos internos — particularmente a moela — são muito valorizados por herboristas e curandeiros. Quando combinada a outros restos animais potentes, como ossos de puma e corações de lobo, esse órgão muscular denso ajuda a neutralizar mordidas de animais venenosos e a conter infecções sistêmicas purulentas."},{t="Um Remédio para a Mordida de Mazzranache",b="Na Aldeia Casco Sangrento, o curandeiro Maur Clamachuva tornou-se vítima do lendário pinote Mazzranache, sofrendo um ferimento atroz e venenoso no ombro. Entrando em delírio devido ao veneno progressivo, Maur depende de uma Moela de Rapineiro junto a um Coração de Lobo-da-pradaria, um Fêmur de Puma das Estepes e uma Escama de Pinote para preparar uma cataplasma curativa capaz de expelir o veneno letal da fera."}},faq={{q="Para que serve uma Moela de Rapineiro?",a="É um ingrediente medicinal essencial requisitado por Maur Clamachuva na Aldeia Casco Sangrento. Combinada a outras três partes de animais, ela forma um remédio capaz de purificar a infecção venenosa causada pelo feroz pinote Mazzranache.",al={"uso da moela de rapineiro","por que preciso de moela de rapineiro","utilidade do orgao de rapineiro"}},{q="De onde vêm as Moelas de Rapineiro?",a="Elas são obtidas das várias espécies de rapineiros que planam pelas planícies de Mulgore, incluindo rapineiros comuns, rapineiros esquálidos e rapineiros garraguda.",al={"onde encontrar moela de rapineiro","o que dropa moela de rapineiro","caçada ao rapineiro"}},{q="Por que Maur Clamachuva precisa dessa parte específica?",a="Maur foi mordido por Mazzranache, um pinote invulgarmente feroz cuja mordida inocula um veneno que causa febres violentas e pesadelos. A medicina tradicional tauren utiliza componentes animais potentes — incluindo a moela — para neutralizar as toxinas específicas que correm em suas veias.",al={"remedio de maur","por que uma moela","cura para mazzranache"}},{q="A moela é usada para mais alguma coisa além da cura de Maur?",a="Não. Fora do remédio popular especializado de Maur Clamachuva na Aldeia Casco Sangrento, as Moelas de Rapineiro não têm aplicações culinárias, alquímicas ou de criação convencionais.",al={"outros usos da moela de rapineiro","culinaria com moela de rapineiro","alquimia com moela de rapineiro"}}},fx={["8f6be1e3"]={q="O que é uma Moela de Rapineiro?",a="Uma Moela de Rapineiro é um órgão interno colhido das aves predatórias conhecidas como rapineiros que planam acima das planícies de Mulgore. Como muitos órgãos digestivos aviários, ela ajuda a processar presas resistentes. Na medicina tradicional tauren, tais partes animais potentes e especializadas são valorizadas por suas qualidades naturais brutas e usadas como ingredientes em remédios herbais e poções restauradoras.",al={"o que é moela de rapineiro","item moela de rapineiro","o que é uma moela de rapineiro"}}},fp="13,123,22.322.0,31.338.0,33.200.0,34.128.0,49.218.0,56.147.0"}
P.entries["item:symbol-of-ragnaros"] = {n="Símbolo de Ragnaros",s="O Símbolo de Ragnaros é uma relíquia do Twilight's Hammer encontrada na Garganta Abrasadora. Velarok busca sua magia profana para criar um invólucro para a Tocha da Retribuição.",h="O Símbolo de Ragnaros é uma relíquia do Twilight's Hammer encontrada na Garganta Abrasadora.",kw={"invólucro da chama","magia profana","ragnaros","garganta abrasadora","símbolo de ragnaros","tocha da retribuição","twilight's hammer","velarok"},sec={{t="Magia Profana",b="Velarok Windblade precisa de um Símbolo de Ragnaros para a Tocha da Retribuição. Ele acredita que o acampamento do Twilight's Hammer nas montanhas a noroeste daqui guarda símbolos e ídolos com poder suficiente para formar o invólucro da tocha. A magia do símbolo serve ao propósito dele."}},faq={{q="O que é o Símbolo de Ragnaros?",a="É um símbolo carregado pelo Twilight's Hammer, e sua magia pode ajudar a formar um invólucro para a Tocha da Retribuição.",al={"símbolo de ragnaros"}},{q="Quem quer o símbolo?",a="Velarok Windblade precisa do Símbolo de Ragnaros para criar o invólucro da Tocha da Retribuição.",al={"quem quer o símbolo","do que velarok precisa"}},{q="Por que Velarok precisa dele?",a="Velarok espera extrair sua magia profana e usá-la para formar um invólucro para a Tocha da Retribuição.",al={"por que precisa do símbolo","invólucro da tocha"}},{q="Onde posso encontrar um?",a="Há rumores de que o acampamento do Twilight's Hammer nas montanhas a noroeste daqui guarda símbolos e ídolos.",al={"onde encontrar o símbolo","encontrar símbolo de ragnaros"}}},fp="18,151,10.262.0,31.115.0,21.89.0,25.97.0,21.105.0"}
P.entries["item:tablet-of-verga"] = {n="Tabuleta de Verga",s="A Tabuleta de Verga é uma pedra arcana inscrita com runas demoníacas essenciais para aprisionar entidades sombrias. Roubada pelo sinistro culto da Lâmina Ardente, ela foi levada para o fundo de seu covil na Rocha da Caveira. Recuperar o artefato permite que praticantes das trevas em Orgrimmar decifrem os rituais necessários para subjugar um emissário do caos.",h="A Tabuleta de Verga é uma pedra arcana inscrita com runas demoníacas essenciais para aprisionar entidades...",kw={"lâmina ardente","antro das sombras","durotar","gan'rul olho de sangue","rocha da caveira","tabuleta de verga","emissário do caos"},ang={["class:Warlock"]="Para os bruxos em treinamento em Orgrimmar, recuperar esta tabuleta marca um marco crítico para provar seu valor à Horda, revelando os segredos necessários para subjugar um servo emissário do caos defensivo.",["faction:Horde"]="A presença da Lâmina Ardente tão perto dos portões de Orgrimmar é uma ameaça contínua à nação incipiente de Thrall; arrancar relíquias roubadas de suas garras revida a influência do culto."},sec={{t="Uma Relíquia Roubada",b="A Tabuleta de Verga contém runas rituais específicas necessárias para invocar e dobrar criaturas do Éter à vontade de um mestre. Quando o culto da Lâmina Ardente conseguiu roubar a tabuleta, eles a esconderam em um baú oculto dentro da Rocha da Caveira, logo a leste de Orgrimmar. Para os bruxos que trabalham discretamente nas sombras da Fenda das Sombras, recuperar a relíquia é crucial — não apenas para estudar suas marcas antigas para invocar um emissário do caos, mas também para negar aos cultistas fanáticos sua própria vantagem sombria."}},faq={{q="Onde fica a Tabuleta de Verga?",a="A tabuleta está guardada dentro de um Burning Blade Stash escondido dentro da Rocha da Caveira, um complexo de cavernas repleto de cultistas localizado logo a leste de Orgrimmar, em Durotar.",al={"localização da tabuleta de verga","onde encontrar a tabuleta de verga","onde fica a tabuleta de verga"}},{q="Quem deseja a recuperação da Tabuleta de Verga?",a="Gan'rul Olho de Sangue, um mestre bruxo que habita o Antro das Sombras sob Orgrimmar, incumbe os iniciados de recuperar a tabuleta para poder ensiná-los a invocar lacaios maiores.",al={"quem precisa da tabuleta de verga","para quem levar a tabuleta de verga","tabuleta de gan'rul"}},{q="Que poder a tabuleta contém?",a="A pedra está inscrita com runas antigas necessárias para completar o ritual de invocação e aprisionamento de um emissário do caos, uma criatura arrancada da Espiral Etérea.",al={"o que a tabuleta faz","história da tabuleta de verga","runas da tabuleta de verga"}},{q="Por que a Lâmina Ardente a roubou?",a="O culto da Lâmina Ardente trabalha incansavelmente para desestabilizar a Horda e expandir seu próprio poder demoníaco. Privar os praticantes de Orgrimmar de textos rituais essenciais enquanto acumulam o conhecimento para si mesmos serve diretamente aos seus objetivos.",al={"por que a lâmina ardente tem a tabuleta","lâmina ardente verga"}}},fx={["5fa1e5b5"]={q="O que é a Tabuleta de Verga?",a="A Tabuleta de Verga é uma relíquia inscrita com conhecimento arcano de bruxo, especificamente as runas e rituais necessários para invocar e prender um andarilho do vácuo. Roubada pelos cultistas da Lâmina Ardente, ela guarda segredos sombrios valorizados por bruxos que buscam avançar seu domínio sobre a Distorção do Nether e invocar servos demoníacos para cumprirem suas ordens.",al={"o que é a tabuleta de verga","tabuleta de verga"}}},fp="15,117,14.387.0,37.143.0,40.162.0,35.112.0,35.197.0"}
P.entries["item:tablet-shard"] = {n="Tablet Shard",s="Tablet Shard vem de uma antiga tabuleta troll sob o Arrecife Torpe. Kin'weelay busca o fragmento para um local sagrado em Orgrimmar, onde ele pode homenagear Gri'lek, herói da tribo Lançanegra.",h="Tablet Shard vem de uma antiga tabuleta troll sob o Arrecife Torpe.",kw={"lançanegra","gri'lek","gri'lek the wanderer","kin'weelay","costa selvagem","tablet shard","tabuleta troll","o arrecife torpe"},ang={["faction:Horde"]="A tribo Lançanegra busca Tablet Shard para um local sagrado em seu novo lar, em Orgrimmar.",["race:Troll"]="Como artefato troll, Tablet Shard carrega a história sagrada de Gri'lek, um herói das lendas troll, e deve homenageá-lo entre a tribo Lançanegra."},sec={{t="Um fragmento de Gri'lek",b="Sob as águas da Costa Selvagem, Tablet Shard é retirado de uma tabuleta que conta a história de Gri'lek the Wanderer. Kin'weelay quer um fragmento para o novo lar da tribo Lançanegra em Orgrimmar. Lá, ele lembrará a tribo da força e da honra de Gri'lek."}},faq={{q="O que é Tablet Shard?",a="Tablet Shard é um fragmento de uma antiga tabuleta troll sob o Arrecife Torpe. Ele conta a história de Gri'lek the Wanderer.",al={"tablet shard","que fragmento","pedaço de tabuleta troll"}},{q="Quem quer Tablet Shard?",a="Kin'weelay, no Acampamento Grom'gol, quer Tablet Shard para um local sagrado em Orgrimmar.",al={"quem quer o fragmento","fragmento de kin'weelay","para quem devo entregar"}},{q="Por que a tribo Lançanegra o quer?",a="O fragmento homenageará Gri'lek the Wanderer e lembrará a tribo Lançanegra de sua força e honra.",al={"por que o fragmento","tabuleta lançanegra","para que serve"}},{q="Onde fica a tabuleta?",a="A tabuleta fica sob as águas da Costa Selvagem, nas ruínas conhecidas como Arrecife Torpe.",al={"localização da tabuleta","de onde vem o fragmento","tabuleta do arrecife torpe"}}},fp="12,174,21.260.0,25.123.0,27.88.0,37.96.0,20.92.0"}
P.entries["item:tainted-heart"] = {n="Coração Maculado",s="O Coração Maculado é um núcleo floral pestilento extraído da flora corrompida de Teldrassil. Entregue aos aventureiros pelo botânico Denalan, ele necessita de uma purificação mágica e nutritiva para livrá-lo das energias vis residuais.",h="O Coração Maculado é um núcleo floral pestilento extraído da flora corrompida de Teldrassil.",kw={"purificação","corrupção","denalan","lago al'ameth","floreira","coração maculado","teldrassil"},ang={["class:Druid"]="Para os druidas cenarianos, trabalhar para purificar o Coração Maculado oferece uma percepção direta sobre a corrupção rastejante que ameaça a saúde da jovem Árvore do Mundo.",["profession:Herbalism"]="Herboristas e botânicos podem apreciar o ofício de Denalan em misturar solos especialmente enriquecidos, capazes de extrair o apodrecimento antinatural da matéria vegetal viva."},sec={{t="Um Núcleo Corrompido",b="O equilíbrio natural de Teldrassil sofre com uma enfermidade antinatural, deformando suas plantas e feras nativas. Após remover o musgo vil que se agarrava a uma excrescência pestilenta, Denalan apresenta este núcleo residual: o Coração Maculado. Embora liberto de seu apodrecimento externo, a escuridão ainda permeia o tecido. Denalan busca descobrir se uma terra especialmente preparada e rica em nutrientes pode neutralizar a mácula residual e restaurar a vida ao que foi corrompido."},{t="O Remédio de Denalan",b="Ao ser colocado na floreira encantada de Denalan, o coração exibe uma vitalidade estranha e persistente. Ele se enterra avidamente no solo rico, absorvendo os nutrientes curativos. Em instantes, a terra expurga a corrupção, e o coração purificado ressurge vivo e pulsando com energia límpida, ansioso para defender aqueles que o curaram."}},faq={{q="O que é o Coração Maculado?",a="É o núcleo interno de uma planta corrompida encontrada em Teldrassil. O botânico Denalan removeu o musgo vil externo, mas o próprio coração permanece impregnado de corrupção até ser purificado.",al={"o que é o coração maculado","item coração maculado"}},{q="Quem purifica o Coração Maculado?",a="Denalan orienta os aventureiros a plantá-lo dentro de sua floreira especialmente preparada no Lago Al'Ameth. O solo nutritivo purifica o coração naturalmente e expurga sua corrupção antinatural.",al={"quem o purifica","como purificar o coração maculado"}},{q="O que acontece depois que ele é plantado?",a="O coração se enterra ativamente no solo da floreira. Momentos depois, ele ressurge totalmente purificado e pulsando com vitalidade, pronto para se vincular a quem o restaurou.",al={"o que acontece com o coração","resultado do coração plantado"}},{q="Por que o coração está corrompido em primeiro lugar?",a="Uma praga estranha tem se espalhado pela Árvore do Mundo Teldrassil, corrompendo a flora nativa, os lenhantes e a vida selvagem por todos os galhos.",al={"por que corrompido","coração corrupção teldrassil"}}},fx={ae8829e0={q="Por que Denalan quer que você plante o Coração Maculado?",a="Denalan conseguiu remover o musgo imundo que se prendia ao coração, mas seu núcleo interno permanece profundamente maculado. Ele espera que o solo rico e nutritivo em seu plantador especialmente preparado cure a aflição, extraindo a corrupção e restaurando a semente viva à vitalidade.",al={"por que plantar o coração maculado","propósito do coração maculado","por que denalan quer o coração maculado"}}},fp="13,150,16.325.0,16.267.1,26.165.0,31.186.0,33.144.1,46.132.0"}
P.entries["item:tainted-keg"] = {n="Barril Estragado",s="O Barril Estragado é um barril de cerveja preta anã roubada, adulterada com uma poção letal dos Renegados inventada pelo Boticário Lindolfo. Entregue sob o disfarce de mantimentos para fazendeiros humanos aprisionados em Serraria Tarren, ele serve como um teste de campo horrendo para os venenos em desenvolvimento da Real Sociedade de Boticários.",h="O Barril Estragado é um barril de cerveja preta anã roubada, adulterada com uma poção letal dos Renegados...",kw={"boticário lindolfo","fazendeiros capturados","dun garok","o elixir da agonia","shindigger stout","barril estragado","serraria tarren"},ang={["race:Human"]="O massacre de trabalhadores rurais capturados por meio de cerveja adulterada demonstra as táticas angustiantes e impiedosas enfrentadas pelos remanescentes vivos por toda Eira dos Montes.",["race:Undead"]="Para a Real Sociedade de Boticários, a cerveja adulterada é um marco prático na engenharia de armas biológicas capazes de erradicar a humanidade."},sec={{t="Uma Safra Mortal",b="O barril começou sua existência como um barril de Shindigger Stout, saqueado dos fuzileiros anões entrincheirados em Dun Garok. Em vez de bebê-lo, o Boticário Lindolfo contaminou a encorpada cerveja com seu recém-refinado O elixir da agonia. Ao envenenar uma bebida comum, os Renegados criaram um vetor insidioso projetado para passar despercebido, transformando um conforto familiar dos vivos em uma sentença de morte rápida."},{t="Testes nos Condenados",b="Mantidos no andar de cima da estalagem de Serraria Tarren, vários fazendeiros humanos foram capturados após a Alta-executora Darthalia suspeitar que um estrategista militar de Ventobravo havia se escondido entre eles. Quando chegou a notícia de que o estrategista havia perecido em outro lugar, os trabalhadores cativos tornaram-se descartáveis. Darthalia os entregou a Lindolfo, que encenou uma celebração cruel ao mandar colocar o barril envenenado sobre o tapete na sala de detenção. Sedentos e desesperados, os prisioneiros beberam fartamente, comprovando a potência fatal e imediata do elixir."}},faq={{q="O que há dentro do Barril Estragado?",a="Ele contém Shindigger Stout — uma encorpada cerveja anã roubada de Dun Garok — misturada com O elixir da agonia, uma toxina experimental criada pelo Boticário Lindolfo em Serraria Tarren.",al={"conteúdo do barril estragado","qual veneno está no barril","o que está no barril"}},{q="De onde a cerveja veio originalmente?",a="A bebida base foi tomada dos montanhistas e fuzileiros anões que ocupavam Dun Garok, uma fortaleza anã fortemente defendida situada no sudeste de Contraforte de Eira dos Montes.",al={"quem fez a cerveja","de onde a cerveja preta foi roubada","fonte da shindigger stout"}},{q="Quem bebe do barril?",a="Um grupo de fazendeiros humanos mantidos como reféns no quarto do andar superior da estalagem de Serraria Tarren bebe do barril, caindo e morrendo quase que instantaneamente por causa da bebida contaminada.",al={"quem bebe","vítimas do barril estragado","fazendeiros capturados"}},{q="Por que os fazendeiros estavam presos?",a="A Alta-executora Darthalia os prendeu sob a suspeita de que um estrategista militar da Aliança de Ventobravo estivesse escondido entre eles. Uma vez confirmado que esse estrategista havia morrido nas Terras Pestilentas, os fazendeiros cativos foram considerados inúteis e entregues aos boticários.",al={"por que fazendeiros cativos","por que darthalia capturou fazendeiros","por que há fazendeiros em serraria tarren"}}},fx={fd5e0197={q="O que é o Barril Estragado?",a="O Barril Estragado é um recipiente de Stout de Escavador de anões roubado, que foi misturado com uma poção mortal preparada pelos Renegados. O Boticário Lindolfo criou este lote letal de bebida maculada para servir como um teste prático para sua pesquisa alquímica em andamento.",al={"o que é o barril estragado","item barril estragado","o que é este barril"}},["5c778a45"]={q="Por que o Boticário Lindolfo quer que o Barril Estragado seja usado?",a="O Boticário Lindolfo quer que o barril seja entregue para testar a eficácia de seu recém-terminado Elixir of Agony. Com os fazendeiros humanos capturados entregues à sua disposição pela Alta-executora Darthalia, oferecer-lhes a stout envenenada fornece à Real Sociedade de Boticários um meio conveniente de observar os efeitos fatais da toxina em primeira mão.",al={"por que usar o barril estragado","por que lindolfo quer o barril estragado","propósito do barril estragado"}}},fp="11,201,16.276.0,24.458.1,31.151.0,39.136.0,24.115.1,41.243.0"}
P.entries["item:tainted-letter"] = {n="Carta Conspurcada",s="A Tainted Letter é uma convocação entregue discretamente com o selo de Drusilla La Salle, uma instrutora de Bruxos à espreita nos arredores da Abadia de Vila Norte. Ela orienta aspirantes a praticantes humanos das artes sombrias a se apresentarem a ela para tutela especializada longe de olhos atentos.",h="A Tainted Letter é uma convocação entregue discretamente com o selo de Drusilla La Salle, uma instrutora de...",kw={"drusilla la salle","floresta de elwynn","abadia de vila norte","tainted letter","twisting nether","bruxo"},ang={["class:Warlock"]="A Tainted Letter marca sua introdução formal ao ofício sombrio no Reino de Ventobravo, estabelecendo que o poder sobre o Caos exige vigilância e discrição constantes.",["race:Human"]="A sociedade dos Humanos defende amplamente a Luz Sagrada, restando aos praticantes de magia sombria realizarem suas iniciações e treinamentos secretamente à margem de locais como a Abadia de Vila Norte."},sec={{t="Uma Convocação Secreta",b="Enquanto sacerdotes, paladinos e soldados comuns treinam abertamente pelos gramados bem-cuidados da Abadia de Vila Norte, praticantes de magia vil precisam agir com uma discrição muito maior. Entregue aos iniciados que retornam dos acampamentos de kobolds próximos, esta carta traz a insígnia pessoal de Drusilla La Salle. Carregando traços sutis de artifícios sombrios, a missiva instrui os Bruxos novatos a procurarem sua mentora discretamente perto dos terrenos da abadia antes que os guardas e clérigos locais comecem a suspeitar de seu caminho proibido."},{t="O Preço da Ambição",b="Encontrar Drusilla revela a necessidade de tais medidas secretas. Os Bruxos são vistos com profunda desconfiança pela população comum de Elwynn, forçando os mentores a permanecerem nas sombras e evitarem sentinelas vigilantes. Drusilla usa a carta entregue para iniciar uma lição crítica de disciplina: a magia arcana e a magia do caos convidam a uma corrupção implacável, exigindo que os praticantes moderem sua crescente ambição com paciência e autocontrole ao comungarem com habitantes da Twisting Nether."}},faq={{q="Quem enviou a Tainted Letter?",a="A carta foi escrita e selada por Drusilla La Salle, a instrutora de Bruxos local posicionada nos arredores do salão principal da Abadia de Vila Norte.",al={"quem escreveu a tainted letter","carta de drusilla","remetente da tainted letter"}},{q="Por que a carta é considerada corrompida?",a="A missiva é marcada por tons vis e selada com a insígnia de uma praticante de artes demoníacas, carregando uma aura de magia sombria que a diferencia de correspondências comuns.",al={"por que é maculada","o que torna a carta maculada","selo maculado"}},{q="Por que os guardas de Vila Norte estão vigiando Drusilla La Salle?",a="Os guardas e sacerdotes da Abadia de Vila Norte desconfiam da magia vil e da invocação demoníaca. Drusilla deve manter a discrição nos arredores da abadia para evitar provocar as autoridades civis, que vigiam de perto praticantes suspeitos.",al={"guardas de drusilla","por que os guardas suspeitam de drusilla","bruxo se escondendo em vila norte"}},{q="Que conselho Drusilla dá ao ler a carta?",a="Drusilla adverte o iniciado de que lidar com entidades da Twisting Nether traz intensa tentação e corrupção. Ela instrui seus alunos a exercerem autocontrole e prudência, sem permitir que a cautela apague sua ambição pessoal.",al={"conselho de drusilla","o que drusilla diz","treinamento de drusilla"}}},fx={["63258adc"]={q="O que é a Tainted Letter?",a="A Tainted Letter é uma mensagem selada deixada para você em seu retorno à Abadia de Vila Norte, marcada com a inconfundível insígnia pessoal de Drusilla La Salle. Endereçada aos praticantes iniciantes das artes sombrias, a correspondência serve como uma convocação urgente para falar com ela diretamente. Ela carrega a marca tênue da corrupção vil, destacando-a dos assuntos piedosos e ordenados da Sagrada Luz praticados dentro das muralhas da abadia.",al={"o que é a tainted letter","identidade da tainted letter","sobre a tainted letter"}},["3c923280"]={q="Por que a Tainted Letter é entregue a você?",a="A carta é entregue a você para que possa estabelecer contato com sua instrutora, Drusilla La Salle, assim que suas tarefas iniciais em Vila Norte forem concluídas. Drusilla opera silenciosamente nas margens da abadia, mantendo um olhar atento para bruxos emergentes. A carta direciona você a procurá-la antes que outros assuntos da abadia o distraiam, permitindo que ela transmita avisos vitais sobre autocontrole, ambição e a natureza corruptora da Distorção do Nether.",al={"por que preciso da tainted letter","quem quer a tainted letter","por que dar a tainted letter"}}},fp="14,130,16.336.0,21.323.0,28.78.0,37.117.0,53.145.0,55.187.0"}
P.entries["item:tainted-memorandum"] = {n="Memorando Maculado",s="O Memorando Maculado é uma nota discreta entregue a bruxos gnomos novatos que iniciam sua jornada no Vale Cristálgida. Escrito pelo instrutor de bruxos Alamar Carranca, ele incita o leitor a deixar de lado os caminhos tradicionais e buscar o verdadeiro poder oferecido pelas artes sombrias.",h="O Memorando Maculado é uma nota discreta entregue a bruxos gnomos novatos que iniciam sua jornada no Vale...",kw={"alamar carranca","sidermar","vale cristálgida","bruxo gnomo","gnomeregan","memorando maculado"},ang={["class:Warlock"]="A nota marca sua introdução formal ao treinamento de bruxo com Alamar Carranca, enquadrando a evocação sombria como uma busca necessária por controle e poder.",["race:Gnome"]="A mensagem de Carranca aproveita o ressentimento dos gnomos pela perda de Gnomeregan e pelo status que enxergam de si mesmos como refugiados dependentes em terras anãs."},sec={{t="Uma Convocação Discreta",b="No gélido entreposto anão de Sidermar, os praticantes de magia vil não são celebrados nem amplamente bem-vistos. Para jovens gnomos que se aventuram pelas artes proibidas, o Memorando Maculado serve como um convite de Alamar Carranca. A mensagem rejeita a dependência da Luz Sagrada ou do aço marcial mundano, apontando a queda de Gnomeregan como prova de que os métodos convencionais e a engenhosidade mecânica falharam com seu povo. Para Carranca, depender da caridade dos anões é um beco sem saída; os gnomos devem conquistar um poder inegável e evocar lacaios inquestionáveis se quiserem garantir seu próprio futuro."}},faq={{q="Quem escreveu o Memorando Maculado?",a="O memorando foi escrito por Alamar Carranca, o instrutor de bruxos gnomo situado no interior de Sidermar, no Vale Cristálgida.",al={"autor memorando maculado","quem enviou o memorando maculado","nota de alamar carranca"}},{q="Por que o memorando é considerado 'maculado'?",a="Ele lida diretamente com a magia proibida dos bruxos. O título reflete a desconfiança e o estigma em torno do poder vil e demoníaco em Dun Morogh, onde os praticantes são mantidos a uma distância segura por seus anfitriões anões.",al={"por que maculado","história da carta maculada"}},{q="O que Alamar Carranca diz sobre Gnomeregan?",a="Carranca guarda rancor da queda da capital gnoma, culpando a magia arcana tradicional e as invenções descuidadas por quase levarem sua raça à extinção. Ele acredita que os anões veem os gnomos como cidadãos de segunda classe e incita os bruxos a buscarem seu próprio poder absoluto em vez de esperarem pela ajuda da Aliança.",al={"alamar carranca gnomeregan","opiniões de alamar carranca"}}},fx={["0c729b68"]={q="O que é o Memorando Maculado?",a="O Memorando Maculado é uma mensagem pessoal e discreta destinada a bruxos gnomos promissores que estão apenas começando seu treinamento no Vale Cristálgida. Repassada silenciosamente por aliados na superfície, a nota serve como um convite para olhar além das tradições convencionais da Sagrada Luz ou do combate físico e buscar praticantes semelhantes e de mente aberta que abrigam artes mais sombrias.",al={"o que é o memorando maculado","memorando maculado","o que é esta nota"}},e7be2e4a={q="Por que alguém quer que você tenha o Memorando Maculado?",a="O memorando é dado para recrutá-lo para as artes de bruxo. O instrutor de bruxo Alamar Carranca o envia para identificar conjuradores novatos que rejeitam os dogmas comuns de anões e gnomos, incentivando você a encontrá-lo em Sidermar para dominar aliados invocados obedientes e desbloquear a verdadeira fonte do poder demoníaco.",al={"por que recebi o memorando","por que memorando maculado","quem quer o memorando maculado"}}},fp="18,125,18.486.0,33.82.0,43.180.0,44.277.0"}
P.entries["item:talisman-of-corruption"] = {n="Talismã de Corrupção",s="O Talismã de Corrupção é um vil berloque demoníaco usado pelo sátiro Xabraxxis para envenenar as mentes dos fúrbolgs Blackwood de Costa Negra. Carregado dentro da bolsa pessoal do sátiro, ele serve como um conduto mágico que prende a tribo à loucura vil.",h="O Talismã de Corrupção é um vil berloque demoníaco usado pelo sátiro Xabraxxis para envenenar as mentes dos...",kw={"auberdine","blackwood","costa negra","furbolg","satiro","talismã de corrupção","trovejius tecevento","xabraxxis"},ang={["class:Druid"]="Os druidas veem dispositivos como o talismã como perversões diretas da ordem natural, transformando feras sagradas em peões selvagens dos lacaios restantes da Legião Ardente.",["race:NightElf"]="Para os Kaldorei de Auberdine, recuperar o talismã é um passo vital para libertar seus ancestrais aliados fúrbolgs da degradação demoníaca e curar a terra."},sec={{t="Um Conduto de Loucura",b="Os elfos noturnos de Auberdine há muito lutam para entender por que os fúrbolgs Blackwood se voltaram com tanta agressividade contra seus antigos aliados. Trovejius Tecevento descobriu que a ruína da tribo não foi uma decadência natural, mas uma sabotagem deliberada orquestrada pelos sátiros. Usando talismãs como este, agentes demoníacos projetam feitiçaria corruptora pela natureza, contaminando suprimentos de comida e transformando espíritos pacíficos da floresta em feras frenéticas. Ao canalizar magias vis diretamente através desses dispositivos, os sátiros mantêm um controle inabalável sobre as mentes e vontades das tribos locais."},{t="Quebrando o Domínio",b="Para atrair o sátiro responsável, os aventureiros devem purificar amostras da comida dos fúrbolgs usando água abençoada do poço da lua, expurgando o acampamento por tempo suficiente para enfurecer seu feitor. Abater Xabraxxis quebra seu domínio imediato e rende sua bolsa demoníaca, dentro da qual repousa o talismã. Entregar o talismã a Trovejius Tecevento em Auberdine permite que os Kaldorei neutralizem suas emanações nefastas e estudem como desfazer permanentemente a aflição demoníaca que assola a floresta."}},faq={{q="O que é o Talismã de Corrupção?",a="É um dispositivo demoníaco usado pelo sátiro Xabraxxis para canalizar magia nefasta e corromper as mentes e as fontes de alimento dos fúrbolgs Blackwood em Costa Negra.",al={"o que e talisma de corrupcao","proposito do talisma","o que o talisma faz"}},{q="Quem carrega o talismã?",a="Ele é guardado dentro da bolsa demoníaca carregada por Xabraxxis, um sátiro que supervisiona o acampamento fúrbolg Blackwood do norte, perto do Rio Fontescarpa.",al={"quem dropa talisma de corrupcao","onde encontrar talisma de corrupcao","como conseguir talisma"}},{q="Como você atrai o dono do talismã?",a="Você deve coletar amostras das frutas, grãos e nozes dos fúrbolgs, combiná-los com água do poço da lua em uma tigela de purificação e colocar a oferenda perto da fogueira próxima ao rio. Purificar os fúrbolgs enfurece Xabraxxis, fazendo com que ele ataque.",al={"como evocar xabraxxis","como encontrar xabraxxis","invocar satiro costa negra"}},{q="O que acontece com o talismã depois de ser recuperado?",a="Ele é entregue a Trovejius Tecevento em Auberdine. Ele protege o artefato para descarte e o estuda para aprender como libertar permanentemente os fúrbolgs da corrupção demoníaca.",al={"para quem entregar o talisma","entregar talisma de corrupcao","trovejius tecevento talisma"}}},fp="22,194,20.379.0,17.350.1,35.126.0,25.134.0,46.205.0,51.160.0"}
P.entries["item:tallonkai-s-jewel"] = {n="Joia de Tallonkai",s="A Joia de Tallonkai é uma esmeralda luminosa roubada de um talismã druídico encantado em Teldrassil. Valorizada pelo místico ursoide Ferocitas the Dream Eater, ela serve como a peça central crucial necessária para consertar o Apanhador de Sonhos de Esmeralda.",h="A Joia de Tallonkai é uma esmeralda luminosa roubada de um talismã druídico encantado em Teldrassil.",kw={"dolanaar","apanhador de sonhos de esmeralda","ferocitas the dream eater","místicos pinheiro torpe","vilarejo brisastral","tallonkai radicélere","joia de tallonkai"},ang={["class:Druid"]="A esmeralda é um componente druídico sintonizado, projetado para ressoar com o Sonho Esmeralda, tornando seu mau uso por ursoides corrompidos uma afronta ao equilíbrio.",["race:NightElf"]="Recuperar a joia ajuda a restaurar a ordem em Teldrassil, arrancando um artefato sagrado das mãos dos invasores Gnarlpine."},sec={{t="Um Núcleo Roubado",b="Tallonkai Radicélere recebeu o Apanhador de Sonhos de Esmeralda de Gaerolas Talvethen, guardião dos druidas na Gruta de Ban'ethil, como um potente foco que canaliza energia do Sonho Esmeralda. Quando seu talismã foi danificado, a esmeralda radiante central foi desprendida e levada para as selvas do leste de Teldrassil. A joia caiu nas patas de Ferocitas the Dream Eater, um líder Gnarlpine corrompido que transformou a pedra brilhante em um colar pessoal. Embora a pedra verde emitisse um brilho misterioso na escuridão da floresta, sua verdadeira ressonância harmoniosa era totalmente inútil para o ursoide, servindo meramente como troféu até ser recuperada."}},faq={{q="O que é a Joia de Tallonkai?",a="É uma esmeralda brilhante encantada que serve como peça central para o Apanhador de Sonhos de Esmeralda, um foco druídico dado a Tallonkai Radicélere de Dolanaar por Gaerolas Talvethen.",al={"o que é a joia","história da joia de tallonkai"}},{q="Quem roubou a Joia de Tallonkai?",a="Ela foi roubada por Ferocitas the Dream Eater, um líder entre os místicos Gnarlpine corrompidos que residem ao norte do Vilarejo Brisastral.",al={"quem tem a joia","quem a roubou","quem pegou a joia de tallonkai"}},{q="Os ursoides Gnarlpine podem usar o poder da joia?",a="Não. Embora Ferocitas usasse a esmeralda no pescoço como um ornamento brilhante, Tallonkai observa que o poder druídico da pedra é completamente inútil para o ursoide corrompido.",al={"ferocitas pode usá-la","poder da esmeralda dos pinheiro torpe"}},{q="Para onde a joia vai após ser recuperada?",a="A pedra é devolvida a Tallonkai Radicélere no nível superior de Dolanaar, onde ele a usa para restaurar e consertar totalmente o Apanhador de Sonhos de Esmeralda danificado.",al={"o que acontece com a joia","consertando o apanhador de sonhos"}}},fx={["4dd99e12"]={q="Por que alguém quer a Joia de Tallonkai?",a="Tallonkai Radicélere precisa desesperadamente que esta esmeralda brilhante seja devolvida para que ele possa reparar seu Apanhador de Sonhos de Esmeralda danificado. O místico furbolg Gnarlpine corrompido, Ferocitas the Dream Eater, pegou-a para usar como um colar brilhante, atraído por seu brilho mágico sem entender que seu poder sintonizado com o sonho é totalmente inútil em suas mãos.",al={"por que a joia de tallonkai é procurada","por que tallonkai quer a joia","por que roubar a joia de tallonkai"}}},fp="17,157,13.586.0,26.159.0,28.119.0,49.113.0,46.135.0"}
P.entries["item:talon-of-tethis"] = {n="Talon of Tethis",s="Talon of Tethis é a prova de uma caçada na Selva do Espinhaço. Rosarães Guima pede que você o traga de volta após derrotar o raptor esquivo.",h="Talon of Tethis é a prova de uma caçada na Selva do Espinhaço.",kw={"arena de gurubashi","rosarães guima","raptor","raptor mastery","selva do espinhaço","talon of tethis","tethis"},ang={["class:Hunter"]="Como Caçador, você põe suas habilidades à prova contra Tethis, um raptor que Rosarães não conseguiu matar."},sec={{t="Prova de um Caçador",b="Rosarães Guima diz que poucos caçadores podem afirmar que mataram Tethis, um raptor. Traga a garra até ele, e ele chamará você de mestre em matar raptores."}},faq={{q="O que é Talon of Tethis?",a="Talon of Tethis prova que você derrotou o raptor Tethis para Rosarães Guima.",al={"garra de tethis","item garra","para que serve a garra"}},{q="Quem quer a garra de Tethis?",a="Rosarães Guima quer a garra de Tethis como prova da caçada.",al={"quem quer a garra","garra de roçarães","onde levar a garra de tethis"}},{q="Onde posso encontrar Tethis?",a="Tethis vagueia pelos arredores da Arena de Gurubashi, principalmente ao norte dela.",al={"onde fica tethis","localização de tethis","encontrar o raptor"}},{q="Por que Rosarães quer a garra?",a="Rosarães pede a garra como prova de que você matou Tethis, um raptor que ele próprio não conseguiu abater.",al={"por que a garra","motivo da caçada a tethis","o que rosarães quer"}}},fp="15,140,18.140.0,28.86.0,25.59.0,24.63.0,30.103.0"}
P.entries["item:taming-rod"] = {n="Bastão de Adestramento",s="Um Bastão de Adestramento é uma ferramenta instrutiva confiada a caçadores novatos por seus treinadores. Imbuído de uma magia de vinculação simples, ele permite que o aprendiz pacifique temporariamente e comande a fauna local para dominar os fundamentos do manejo de feras.",h="Um Bastão de Adestramento é uma ferramenta instrutiva confiada a caçadores novatos por seus treinadores.",kw={"escorpitídeo couraçado","javali malhado feroz","mascote de caçador","monte navalha","bastão de adestramento","domando a fera","thotar"},ang={["class:Hunter"]="O Bastão de Adestramento é a pedra fundamental do rito de passagem de todo jovem caçador, servindo como rodinhas de apoio até que ele possua a força de vontade inata para forjar laços perpétuos com feras selvagens.",["faction:Horde"]="Em Durotar e Mulgore, treinadores como Thotar usam esses bastões para testar se os jovens recrutas têm a disciplina necessária para dominar a implacável fauna de Kalimdor."},sec={{t="O Instrumento de Treinamento de um Instrutor",b="Caçadores novatos não conseguem exercer imediatamente a força mental necessária para vincular permanentemente uma criatura selvagem à sua vontade. Para preencher essa lacuna, treinadores veteranos fornecem Bastões de Adestramento especializados. Em locais como Monte Navalha, mentores como Thotar entregam esses implementos encantados a aspirantes a caçadores orcs e trolls para subjugar predadores regionais — como javalis malhados ferozes e escorpitídeos couraçados. O bastão pacifica temporariamente a fera, permitindo que o condutor pratique dar ordens e lutar ao lado de um companheiro animal sem o perigo de formar prematuramente um elo primal inquebrável."},{t="Um Passo Rumo à Maestria",b="O controle concedido por um Bastão de Adestramento é passageiro, durando tipicamente pouco tempo antes de a magia se dissipar. Cada bastão é sintonizado com tipos específicos de feras selvagens, servindo como um degrau através de provações sucessivas. Uma vez que o novato prova ser capaz de comandar vários temperamentos selvagens — de forrageadores dóceis a caçadores venenosos agressivos —, o bastão é devolvido ao treinador. Tendo demonstrado a técnica adequada, o aluno finalmente aprende a arte inata de domar, chamar e dispensar companheiros para a vida toda sem a necessidade de um artefato."}},faq={{q="Para que serve um Bastão de Adestramento?",a="Um Bastão de Adestramento é um instrumento de treinamento dado a jovens caçadores pelos treinadores de sua classe. Ele pacifica e encanta temporariamente uma fera-alvo para que o aprendiz possa praticar o comando de um animal em combate.",al={"o que o bastão de adestramento faz","uso do bastão de adestramento","por que tenho um bastão de adestramento"}},{q="Eu fico com o mascote que domo com o bastão?",a="Não. Criaturas domadas com um Bastão de Adestramento ficam apenas sob influência temporária para fins de treinamento. Quando o encantamento do bastão expira ou você o devolve ao seu treinador, o vínculo termina. Você aprende a domar permanentemente seu próprio companheiro apenas após concluir todas as suas provações.",al={"o mascote é permanente","eu fico com o javali","eu fico com o escorpitídeo"}},{q="Posso usar qualquer Bastão de Adestramento em qualquer animal?",a="Não. Cada bastão é encantado especificamente para uma etapa específica do treinamento e é sintonizado com uma criatura-alvo determinada, como um javali malhado feroz ou um escorpitídeo couraçado.",al={"o bastão funciona em qualquer coisa","alvos do bastão de adestramento"}},{q="Posso ficar com o Bastão de Adestramento após concluir o treinamento?",a="Não. O bastão deve ser devolvido ao seu treinador de caçadores após a conclusão da sua tarefa. Em troca da devolução dele após a sua provação final, o treinador ensina você a domar, evocar e dispensar feras por conta própria.",al={"ficar com o bastão de adestramento","posso guardar o bastão"}}},fx={da578f9f={q="Por que um caçador quer um Bastão de Adestramento?",a="Caçadores novatos precisam do bastão para provar sua autoridade em desenvolvimento sobre a natureza. Ao subjugar com sucesso feras perigosas, como javalis ou escorpiões, você demonstra a determinação e a compostura necessárias para controlar uma mente selvagem. Depois de mostrar ao seu treinador que consegue direcionar essas criaturas em combate, você aprende as verdadeiras e duradouras artes da companhia das feras.",al={"por que preciso do bastão de adestramento","propósito do bastão de adestramento","por que usar o bastão de adestramento"}},c3dba9d3={q="O que é um Bastão de Adestramento?",a="Um Bastão de Adestramento é um implemento instrucional confiado a caçadores novatos por seus instrutores. Encantado para dobrar temporariamente a vontade de uma criatura selvagem à sua, ele serve como um auxílio de treinamento. Empunhá-lo permite que um aspirante a caçador experimente a conexão delicada necessária para comandar a vida selvagem em batalha sem se vincular permanentemente antes que suas habilidades fundamentais sejam totalmente dominadas.",al={"o que é um bastão de adestramento","item bastão de adestramento","história do bastão de adestramento"}}},fp="10,164,28.377.0,21.391.0,30.160.0,38.189.0,39.141.0,56.172.0"}
P.entries["item:tapped-dowsing-widget"] = {n="Tapped Dowsing Widget",s="Um Tapped Dowsing Widget contém uma amostra de água de uma poça perto do Posto Silitriste, em Tanaris. A Gadgetzan Water Company precisa desses levantamentos, pois os poços do deserto estão secando.",h="Um Tapped Dowsing Widget contém uma amostra de água de uma poça perto do Posto Silitriste, em Tanaris.",kw={"fizzledowser","geringontzan","posto silitriste","tanaris","tapped dowsing widget","untapped dowsing widget","amostra de água","levantamento da água"},sec={{t="Uma amostra do deserto",b="Topógrafo Sênior Secamolha envia você de Geringontzan para testar a poça perto do Posto Silitriste. O dispositivo coleta uma amostra para a Gadgetzan Water Company, que busca fontes de água de acesso livre enquanto nômades tomam seus poços. Mas a poça fica à vista dos trolls, e o levantamento traz outro perigo do deserto."}},faq={{q="O que é o Tapped Dowsing Widget?",a="É um Untapped Dowsing Widget que coletou uma amostra de água da poça perto do Posto Silitriste, em Tanaris.",al={"dispositivo ativado","aparelho de amostra de água","dispositivo de prospecção"}},{q="Onde uso o dispositivo de prospecção?",a="Use o Untapped Dowsing Widget na poça perto do Posto Silitriste, a oeste de Geringontzan e ao sul de Zul'Farrak.",al={"onde usar o dispositivo","localização da poça","água do posto silitriste"}},{q="Quem quer a amostra de água?",a="Topógrafo Sênior Secamolha, em Geringontzan, pede que você leve o Tapped Dowsing Widget de volta para ele, em nome da Gadgetzan Water Company.",al={"quem precisa da amostra","fizzledowser","gadgetzan water company"}},{q="Por que a companhia está fazendo um levantamento da água?",a="A Gadgetzan Water Company busca fontes de água de acesso livre porque nômades estão tomando seus poços.",al={"por que fazer levantamento da água","sem poços","escassez de água"}},{q="Que perigo há perto da poça?",a="Há relatos de criaturas insetoides estranhas sugando a água do deserto. Os topógrafos também podem ficar à vista dos trolls que rondam a poça.",al={"perigo na poça","insetos no posto silitriste","criatura rastejante assustadora"}}},fp="21,172,15.314.0,34.114.0,34.109.0,27.130.0,35.90.0,29.131.1"}
P.entries["item:taragaman-the-hungerer-s-heart"] = {n="Coração de Taragaman, o Famélico",s="O Coração de Taragaman, o Famélico é o troféu macabro tirado do guarda apavorante que domina as profundezas das Cavernas Ígneas. Neeru Fireblade pede este órgão imundo como prova de que a presença demoníaca sob Orgrimmar foi expurgada.",h="O Coração de Taragaman, o Famélico é o troféu macabro tirado do guarda apavorante que domina as profundezas...",kw={"guarda apavorante","coração","famélico","neeru fireblade","orgrimmar","cavernas ígneas","lâmina ardente","taragaman"},ang={["class:Warlock"]="Lidar com Neeru Fireblade e manipular restos demoníacos colhidos é território familiar para bruxos, que compreendem a delicada teia de sombras e enganos que se desenrola no Antro das Sombras.",["faction:Horde"]="Purificar os túneis sob Orgrimmar protege a jovem capital de ser corrompida por dentro, tornando o coração extirpado da fera um símbolo da vigilância da Horda."},sec={{t="Um Troféu de Enganação",b="Arrancado do peito de Taragaman, o Famélico, este coração demoníaco fumegante serve como prova física da morte do brutamontes. Neeru Fireblade afirma tanto a Thrall quanto a aventureiros ansiosos que Taragaman é o mentor por trás dos cultistas da Lâmina Ardente à espreita nas Cavernas Ígneas. Apresentar o coração a Neeru ostensivamente cumpre a ordem do Chefe Guerreiro de proteger Orgrimmar da corrupção demoníaca, embora apresentar um guarda apavorante brutal como o verdadeiro arquiteto do culto oculte convenientemente as redes mortais mais profundas que operam sob a cidade."}},faq={{q="Quem quer o Coração de Taragaman, o Famélico?",a="Neeru Fireblade, um orc bruxo que reside no Antro das Sombras em Orgrimmar, pede que os aventureiros lhe tragam o coração como prova de que o demônio foi derrotado.",al={"quem fica com o coração de taragaman","entregar coração de taragaman","quem quer o coração"}},{q="Onde obtenho este coração?",a="O coração é saqueado diretamente do cadáver de Taragaman, o Famélico, um imponente guarda apavorante localizado nas câmaras centrais de magma das Cavernas Ígneas sob Orgrimmar.",al={"como conseguir o coração de taragaman","onde cai o coração de taragaman","localização do coração de taragaman"}},{q="Thrall chega a ver o coração?",a="Não. Você entrega o coração diretamente a Neeru Fireblade, que afirma que cuidará adequadamente dos restos demoníacos e informará o Chefe Guerreiro Thrall da vitória em seu nome.",al={"o thrall recebe o coração","dar coração para thrall","thrall coração de taragaman"}},{q="Taragaman era realmente o líder da Lâmina Ardente?",a="Neeru Fireblade aponta o guarda apavorante como o líder da Lâmina Ardente e insiste que matá-lo e trazer seu coração apaziguará Thrall.",al={"taragaman é o líder","quem lidera a lâmina ardente","taragaman verdadeiro chefe"}}},fx={a71e3ad9={q="O que é o Coração de Taragaman, o Famélico?",a="É o coração decepado de Taragaman, o Famélico, um enorme guarda do apocalipse que espreita nas profundezas ígneas das Cavernas Ígneas, sob Orgrimmar. Transportado para fora das cavernas por aventureiros, ele serve como prova física de que o demônio que Neeru Fireblade nomeia como o líder da Lâmina Ardente foi abatido.",al={"o que é o coração de taragaman","coração de taragaman o famélico","conhecimento sobre o coração de taragaman"}},d8388abb={q="De onde vem o Coração de Taragaman, o Famélico?",a="O coração é arrancado do peito de Taragaman, o Famélico, um enorme guarda do apocalipse estacionado nas profundezas das Cavernas Ígneas. Taragaman foi invocado e mantido nos túneis subterrâneos sob Orgrimmar pelos cultistas da Lâmina Ardente, tornando o coração uma relíquia orgânica da corrupção demoníaca que infesta o submundo da cidade.",al={"origem do coração de taragaman","de onde veio o coração","quem fez o coração de taragaman"}}},fp="30,182,18.408.1,41.130.0,29.153.0,31.144.0,52.144.1"}
P.entries["item:tattered-manuscript"] = {n="Manuscrito Rasgado",s="O Manuscrito Rasgado consiste em páginas avulsas e vandalizadas, arrancadas do exemplar único do Tomo do Conluio. Escondida nas profundezas empoeiradas do sul de Kalimdor, esta porção maltratada do texto guarda segredos arcanos vitais para bruxos que buscam o domínio sobre caçadores vis.",h="O Manuscrito Rasgado consiste em páginas avulsas e vandalizadas, arrancadas do exemplar único do Tomo do...",kw={"caçador vil","jonas anísio","krom braçoforte","tomo mofado","castelo do casco fendido","manuscrito rasgado","mil agulhas","tomo do conluio"},ang={["class:Warlock"]="Recuperar o manuscrito é um rito de passagem essencial para aspirantes a bruxos, concedendo o conhecimento necessário para submeter caçadores vis predatórios à sua vontade."},sec={{t="Um Grimório Vandalizado",b="O Tomo do Conluio já foi um volume intacto e exclusivo, protegido no reino decadente de Lordaeron. Em algum momento, um profanador desconhecido arrancou quase metade do tratado diretamente de sua encadernação. Enquanto a lombada sobrevivente e o restante do livro — hoje conhecido como o Tomo Mofado — foram enviados para o sul em direção a Khaz Modan e se perderam no mar, essas folhas de pergaminho rasgadas vagaram por O Grande Oceano até Kalimdor, caindo finalmente nas mãos dos centauros Galak no Castelo do Casco Fendido."},{t="Recuperando as Palavras",b="Guardado em um baú surrado nas profundezas das cavernas labirínticas do Castelo do Casco Fendido, o manuscrito sobreviveu aos ventos áridos e impiedosos de Mil Agulhas. Apesar de seu estado frágil e esfarrapado, praticantes das artes sombrias — tanto bruxos da Aliança trabalhando com Krom Braçoforte em Altaforja quanto praticantes da Horda ajudando Jonas Anísio na Cidade Baixa — enfrentam os centauros agressivos para reunir essas folhas perdidas com o Tomo Mofado. Uma vez combinados, o tratado completo contém os rituais sombrios necessários para evocar e prender um caçador vil demoníaco."}},faq={{q="O que é o Manuscrito Rasgado?",a="É uma coleção de folhas rasgadas de pergaminho que compõem aproximadamente metade do Tomo do Conluio, um grimório lendário e único sobre demonologia.",al={"história do manuscrito rasgado","o que é o manuscrito","páginas tomo do conluio"}},{q="Como essas páginas foram parar em Mil Agulhas?",a="Após o grimório ser vandalizado em Lordaeron, as páginas arrancadas de alguma forma cruzaram o oceano e caíram na posse dos centauros Galak, que as esconderam em um baú dentro do Castelo do Casco Fendido.",al={"por que no casco fendido","tomo dos centauros","manuscrito de mil agulhas"}},{q="Para que serve o manuscrito?",a="Os bruxos devem recombinar o Manuscrito Rasgado com o Tomo Mofado encharcado para reconstruir o texto completo do Tomo do Conluio, liberando o ritual para evocar um caçador vil.",al={"para que preciso do manuscrito","missão caçador vil páginas"}},{q="Quem foi o responsável por rasgar o livro original?",a="O culpado permanece desconhecido. Tanto Krom Braçoforte em Altaforja quanto Jonas Anísio na Cidade Baixa lamentam o vandalismo, perplexos sobre quem cometeria tal ato contra uma obra erudita única.",al={"quem rasgou o tomo","quem vandalizou o tomo do conluio"}}},fp="19,178,21.399.0,20.415.0,32.126.0,47.167.0,32.166.0,56.168.0"}
P.entries["item:tazan-s-satchel"] = {n="Algibeira de Tazan",s="A Algibeira de Tazan é uma bolsa trancada carregada pelo troll Tazan, que opera ao lado de piratas perto de Vila Catraca. Ela contém informações secretas cobiçadas pela Mão Despedaçada, a guilda secreta de ladinos baseada sob Orgrimmar.",h="A Algibeira de Tazan é uma bolsa trancada carregada pelo troll Tazan, que opera ao lado de piratas perto de...",kw={"sertões","antro das sombras","gamon","vila catraca","a mão despedaçada","tazan","algibeira de tazan","therzok"},ang={["class:Rogue"]="Obter a algibeira e surrupiar a chave de Gamon é um rito de passagem definitivo para os ladinos da Horda que conquistam seu lugar na Mão Despedaçada.",["faction:Horde"]="A busca pela algibeira evidencia a tensão dentro de Orgrimmar, onde a Mão Despedaçada busca vantagens veladas enquanto o Chefe Guerreiro Thrall segue um rumo mais comedido."},sec={{t="Segredos dos Sertões",b="Nas terras áridas e castigadas pelo sol dos Sertões, um troll chamado Tazan mantém negociações ilícitas com os piratas acampados ao longo da costa perto de Vila Catraca. Esses acordos por debaixo dos panos chamaram a atenção de Therzok, um mestre de guilda da Mão Despedaçada situado na escuridão subterrânea do Antro das Sombras. Buscando construir poder secreto longe da diplomacia cautelosa do Chefe Guerreiro Thrall, a Mão Despedaçada marcou Tazan para eliminação a fim de obter as informações valiosas contidas em sua algibeira."},{t="Uma Fechadura Complexa",b="Recuperar a algibeira é apenas metade da provação para um aspirante a ladino. Protegida por um mecanismo de tranca complexo, a algibeira não pode ser facilmente forçada em campo. Tazan confiou a chave ao seu comparsa Gamon, um frequentador ébrio das tavernas de Orgrimmar. Os aspirantes a iniciados precisam testar sua prestidigitação, batendo a carteira de Gamon para pegar a chave diretamente de seus bolsos sem soar o alarme, a fim de finalmente descobrir o diário de bordo de Tazan."}},faq={{q="A quem pertence esta algibeira?",a="A algibeira pertence a Tazan, um troll que opera nos Sertões e conduz negócios secretos com os piratas perto de Vila Catraca.",al={"quem é tazan","dono tazan","dono da algibeira"}},{q="Por que a Mão Despedaçada quer a Algibeira de Tazan?",a="Therzok e a Mão Despedaçada buscam expandir sua rede de informações e recuperar o orgulho marcial a partir das sombras. As negociações de Tazan com os piratas da costa contêm informações valiosas que os ladinos desejam explorar.",al={"por que therzok quer isso","algibeira a mão despedaçada","por que roubar a algibeira"}},{q="Onde está a chave para abrir a algibeira?",a="Tazan não carregava a chave consigo; em vez disso, ele a deixou sob os cuidados de seu comparsa, um cliente bêbado chamado Gamon, encontrado em uma taverna de Orgrimmar.",al={"como abrir algibeira","chave de tazan","onde fica a chave"}},{q="O que há dentro da Algibeira de Tazan?",a="Dentro da algibeira trancada repousa o diário de bordo de Tazan, detalhando suas transações clandestinas e ligações com os bucaneiros da costa.",al={"conteúdo da algibeira","o que há na bolsa","diário de bordo de tazan"}}},fp="15,130,22.331.0,14.260.1,32.87.0,49.170.0,37.85.1,31.108.1"}
P.entries["item:tear-of-the-moons"] = {n="Lágrima das Luas",s="A Lágrima das Luas é um cristal radiante e misterioso desenterrado por escavadores anões em Bael Modan, nos Sertões Meridionais. Embora valorizado pela expedição anã, ele carrega um poder volátil e corruptor que levou diretamente à obsessão, ao exílio e ao derramamento de sangue.",h="A Lágrima das Luas é um cristal radiante e misterioso desenterrado por escavadores anões em Bael Modan, nos...",kw={"bael modan","bastilha bael'dun","sertões","escavação","feegly","lágrima das luas","trogg","twinbraid"},ang={["faction:Horde"]="Infiltrar-se na Bastilha Bael'Dun para recuperar a relíquia desfere um golpe desestabilizador contra a presença militar de Altaforja que invade as terras ancestrais dos taurens.",["race:Dwarf"]="O destino trágico de Feegly serve como um aviso sombrio dos perigos que a expedição de Bael'dun corre o risco de despertar nas profundezas de Kalimdor."},sec={{t="Uma Relíquia Desenterrada",b="Descoberto durante as escavações iniciais de Bael Modan, o cristal foi celebrado como o primeiro grande triunfo do sítio de escavação. Seu estranho resplendor cativou os mineradores, mas nenhum mais intensamente do que Feegly. Afirmando que a relíquia lhe concedia uma força profunda, Feegly caiu sob sua influência. Temendo a influência sombria do artefato — e alarmado com o comportamento cada vez mais instável de Feegly em relação a seus companheiros —, o comandante da expedição, General Twinbraid, declarou a pedra amaldiçoada. Twinbraid confiscou a relíquia, trancou-a em segurança dentro de seu cofre pessoal na Bastilha Bael'Dun e expulsou Feegly para as terras devastadas dos Sertões."},{t="O Preço da Obsessão",b="Incapaz de superar seu anseio pelo poder do cristal, o exilado Feegly recorre a viajantes da Horda que passam para invadir a fortaleza anã e recuperá-lo do cofre de Twinbraid. Ao receber e esfregar o cristal, Feegly começa a fazer ruídos estranhos de grunhidos. A Lágrima cai de suas mãos e se estilhaça no chão; ele então se transforma em um trogg e morre pouco depois."}},faq={{q="De onde veio a Lágrima das Luas?",a="O cristal foi desenterrado pelos prospectores e escavadores anões no sítio arqueológico de escavação de Bael Modan, situado nos limites meridionais dos Sertões.",al={"origem da lágrima","onde a lágrima foi encontrada","histórico da lágrima das luas"}},{q="Por que o cristal foi trancado dentro da Bastilha Bael'Dun?",a="O General Twinbraid reconheceu que o artefato era amaldiçoado depois que Feegly começou a ficar obcecado por ele e a se voltar contra seus companheiros mineradores. Para proteger a expedição, Twinbraid o trancou dentro de seu cofre pessoal.",al={"por que foi trancada","lágrima no cofre de twinbraid","por que twinbraid a pegou"}},{q="O que acontece quando Feegly recupera a Lágrima?",a="Feegly recebe o cristal ansiosamente e começa a esfregá-lo. O que se segue é o final de sua história, descrito na seção protegida contra spoilers.",al={"feegly se transformando em trogg","o que acontece com feegly","transformação de feegly em trogg"}},{q="A Lágrima das Luas pode ser salva ou reparada?",a="O destino final da relíquia é revelado quando Feegly a recebe. A missão não oferece nenhum relato de alguém reparando-a depois.",al={"é possível ficar com a lágrima","lágrima estilhaçada","reparar a lágrima das luas"}}},fx={f703febe={q="O que é a Lágrima das Luas?",a="A Lágrima das Luas é um cristal misterioso e brilhante desenterrado por escavadores anões durante sua exploração em Bael Modan, nos Sertões Meridionais. Embora celebrada como a primeira grande descoberta do local, o artefato provou ser profundamente instável, irradiando um poder corruptor que distorceu a mente do anão que o segurava e levou a liderança da expedição a trancá-lo.",al={"lágrima das luas","o que é a lágrima das luas","o que é a lágrima"}}},fp="17,170,17.458.0,22.354.1,42.133.0,48.194.0,44.115.1,47.103.1"}
P.entries["item:tear-of-tilloa"] = {n="Lágrima de Tirsa",s="A Lágrima de Tirsa é uma flor delicada e pálida encontrada nas sombras da Floresta do Crepúsculo. Desejada por suas potentes propriedades alquímicas, ela cresce discretamente nos terrenos cobertos de vegetação da propriedade Mistmantle, perto de Vila Sombria.",h="A Lágrima de Tirsa é uma flor delicada e pálida encontrada nas sombras da Floresta do Crepúsculo.",kw={"uma bebida para poucos","vila sombria","mistmantle","stalvan","lágrima de tirsa","tirsa","wishock","zardeth"},ang={["class:Warlock"]="Cobiçada por agentes ocultistas sob a capital, esta flor inofensiva é um reagente valioso para o preparo de venenos destinados a silenciar nobres inquisitivos.",["profession:Herbalism"]="A Lágrima de Tirsa é uma rara curiosidade botânica, sobrevivendo exclusivamente no microclima maculado da Floresta do Crepúsculo em vez de campos verdejantes comuns."},sec={{t="Um Jardim na Penumbra",b="Crescendo em meio aos bosques maculados que avançam pelos arredores de Vila Sombria, a Lágrima de Tirsa cria raízes nos terrenos da propriedade de Galvão Brumanto. Embora o solo da Floresta do Crepúsculo tenha se tornado hostil à vegetação saudável, esta pequena flor branca resiste entre os canteiros sombrios. Seu crescimento escasso e sua localização isolada a tornam objeto de interesse para aqueles que buscam reagentes raros não encontrados facilmente em mercados legítimos."},{t="Uma Poção para os Nobres",b="Sob as ruas movimentadas de Ventobravo, a Lágrima de Tirsa serve a um propósito muito mais clandestino. Malvino da Garra Preta busca a flor para preparar uma poção especializada destinada a Lord Wishock, um membro da Casa dos Nobres que ameaça investigar operações sombrias sob a capital. Combinada com Raiz Almiscarada de baixo do Dique Lapidado, a planta é processada em uma mistura com a intenção de distrair e incapacitar Wishock antes que uma investigação oficial possa ocorrer."}},faq={{q="Onde a Lágrima de Tirsa cresce?",a="A flor é encontrada nos arredores de Vila Sombria, na Floresta do Crepúsculo, escondida no jardim tomado pela vegetação pertencente à propriedade da família Mistmantle.",al={"localização da lágrima de tirsa","onde fica a lágrima de tirsa","local de tirsa"}},{q="Quem quer a Lágrima de Tirsa?",a="Malvino da Garra Preta, operando secretamente sob Ventobravo, precisa da flor para preparar uma poção especial.",al={"quem precisa da lágrima de tirsa","quem dá a missão da lágrima de tirsa","quem quer isso"}},{q="Para que a flor é usada?",a="Ela serve como um ingrediente alquímico essencial ao lado da Raiz Almiscarada. Juntas, elas formam uma poção potente usada para incapacitar Lord Wishock e silenciar seus pedidos de investigação sobre negócios escusos sob a capital.",al={"para que serve a lágrima de tirsa","o que a lágrima de tirsa faz","flor da poção para nobres"}},{q="Quem é Lord Wishock?",a="Lord Wishock é um nobre da Casa dos Nobres de Ventobravo que descobriu operações subversivas sob a cidade e começou a pressionar o conselho por uma investigação completa.",al={"wishock","quem é wishock","lord wishock"}}},fx={e7b72a0d={q="O que é a Lágrima de Tirsa?",a="A Lágrima de Tirsa é uma flor branca, delicada e rara, que floresce na Floresta do Crepúsculo. Encontrada especificamente dentro do Jardim de Stalvan, um local negligenciado nos arredores de Vila Sombria, esta planta silenciosa possui propriedades potentes cobiçadas pelos praticantes de artes sombrias que operam longe, nos túneis sob Ventobravo.",al={"o que é a lágrima de tirsa","flor lágrima de tirsa","lágrima de tirsa"}},d8c5f010={q="De onde vem a Lágrima de Tirsa?",a="A flor cresce naturalmente no Jardim de Stalvan, coberto de vegetação, localizado logo após a segurança de Vila Sombria, na floresta sombreada da Floresta do Crepúsculo. Nenhum artesão mortal a criou; ela simplesmente floresce, sem ser perturbada, em meio aos terrenos trágicos da antiga casa de Mistmantle.",al={"de onde vem a lágrima de tirsa","quem fez a lágrima de tirsa","origem da lágrima de tirsa"}}},fp="14,135,21.284.0,27.398.1,35.115.0,29.124.0,28.155.1,20.162.0"}
P.entries["item:techbot-s-memory-core"] = {n="Núcleo de Memória do Tecnobô",s="O Núcleo de Memória do Tecnobô é o repositório central polarizado do assistente mecânico do Mestre-faz-tudo Superchispa, o Tecnobô. Recuperado do autômato defeituoso nas profundezas corrompidas de Gnomeregan, ele contém os dados cruciais que Superchispa espera usar para reverter o comportamento negatronico invertido da máquina.",h="O Núcleo de Memória do Tecnobô é o repositório central polarizado do assistente mecânico do Mestre-faz-tudo...",kw={"cerebro","gnomeregan","nucleo de memoria","negatronico","superchispa","positronico","tecnobo","beco da gambiarra"},ang={["profession:Engineering"]="Engenheiros conseguem compreender os perigos bizarros da polarização positrônica, em que um único curto elétrico pode inverter completamente as rotinas lógicas de um autômato.",["race:Gnome"]="Para os gnomos, o Tecnobô é mais uma baixa trágica da queda de Gnomeregan, representando a perda da brilhante engenharia dos tempos de paz para a ruína caótica."},sec={{t="Um Cérebro Polarizado",b="Antes da catástrofe que forçou os gnomos ao exílio, o Tecnobô servia ao Mestre-faz-tudo Superchispa e aos seus colegas inventores como um assistente indispensável, repleto de engenhocas e dados enciclopédicos. Quando Gnomeregan caiu, uma descarga elétrica desgovernada atingiu o autômato, invertendo seu cérebro positrônico para um estado negatronico hostil. Enlouquecido pela inversão, o Tecnobô agora vagueia pelos corredores contaminados da cidade atacando qualquer um à vista. Recuperar seu núcleo de memória é a única esperança de Superchispa para analisar o defeito e trazer sua prezada criação de volta aos sentidos."}},faq={{q="O que é o Núcleo de Memória do Tecnobô?",a="É o armazenamento de dados principal e o centro computacional do Tecnobô, um autômato construído pelo Mestre-faz-tudo Superchispa. Ele guarda o conhecimento da máquina e registra a perturbação elétrica que corrompeu seu comportamento durante a queda de Gnomeregan.",al={"nucleo de memoria do tecnobo","item cerebro do tecnobo","o que e o nucleo do tecnobo"}},{q="Quem quer o Núcleo de Memória do Tecnobô?",a="O Mestre-faz-tudo Superchispa busca o núcleo. Tendo se refugiado em Beco da Gambiarra, em Altaforja, ao lado de outros gnomos exilados, ele pede a aventureiros corajosos que se aventurem em Gnomeregan, desativem o Tecnobô e tragam o núcleo de volta para que ele possa tentar reparos.",al={"quem precisa do nucleo de memoria do tecnobo","quem entrega o nucleo do tecnobo","onde levar o nucleo do tecnobo"}},{q="Por que o Tecnobô ficou ensandecido?",a="Durante a queda de Gnomeregan, uma faísca elétrica perdida atingiu o cérebro positrônico do Tecnobô. A oscilação repentina polarizou o mecanismo, tornando-o negatronico e invertendo por completo a personalidade e os protocolos do autômato de prestativo para violentamente frenético.",al={"por que o tecnobo e hostil","o que aconteceu com o tecnobo","tecnobo enlouquecido"}},{q="Onde o núcleo é obtido?",a="O núcleo é resgatado do próprio Tecnobô, encontrado perambulando pelos corredores mecânicos superiores e pelas entradas da cidade decaída de Gnomeregan, em Dun Morogh.",al={"onde conseguir o nucleo de memoria do tecnobo","localizacao do tecnobo","como conseguir o cerebro do tecnobo"}}},fx={a503508b={q="De onde vem o Núcleo de Memória do Tecnobô e quem o fez?",a="O núcleo de memória vem do Tecnobô, um construto mecânico complexo construído por Tinkmaster Overspark em Gnomeregan. Overspark projetou a máquina para ajudá-lo e aos seus companheiros inventores com um estoque infinito de dados e engenhocas. No entanto, quando Gnomeregan caiu diante dos troggs, um surto elétrico rebelde atingiu o Tecnobô e polarizou seu cérebro positrônico para um estado negatrônico, enlouquecendo a máquina.",al={"quem fez o núcleo de memória do tecnobô","origem do tecnobô","quem construiu o tecnobô"}}},fp="21,108,17.433.0,30.204.0,32.231.0,27.207.0,27.116.0"}
P.entries["item:telescopic-lens"] = {n="Lente Telescópica",s="A Lente Telescópica é um componente óptico de precisão importado por Gasganete para concluir a construção do observatório de Vila Catraca. Interceptado ao longo da costa por piratas Southsea, o vidro frágil deve ser recuperado do acampamento deles ao sul da cidade antes que o grande telescópio do porto possa perscrutar os céus.",h="A Lente Telescópica é um componente óptico de precisão importado por Gasganete para concluir a construção do...",kw={"caixote","gasganete","observatório","vila catraca","southsea freebooters","stolen booty","lente telescópica"},ang={["profession:Engineering"]="Para um engenheiro, esta lente de precisão representa um trabalho óptico refinado, necessário para focar mecanismos de observação de longo alcance sem aberração esférica.",["race:Gnome"]="Engenhoqueiros gnômicos podem zombar da fogueteria goblin, mas a dedicação de Gasganete à astronomia óptica prova que a engenharia goblin não se resume apenas a explosivos pesados."},sec={{t="Olhos no Céu",b="Vila Catraca é conhecida principalmente como um porto de comércio impiedoso, mas seu engenheiro-chefe e superintendente, Gasganete, nutre ambições mecânicas ainda maiores. Destacando-se proeminentemente sobre o porto, seu observatório foi construído para abrigar um telescópio potente destinado a monitorar o tráfego marítimo e fenômenos astronômicos. Enquanto a lente maior chegou em segurança por meio de uma caravana terrestre de Durotar, a lente menor, vital, foi encaminhada por mar — tornando-se presa fácil para os Southsea Freebooters que infestam as rotas mercantes ao largo da costa dos Sertões."},{t="Saque Pirata",b="Quando os Freebooters atacaram o navio de transporte, eles levaram tudo o que tinha valor, guardando a óptica delicada em um caixote marcado com 'Frágil - Não Derrube'. Incapazes de apreciar o fino acabamento ou simplesmente em dúvida sobre como penhorá-la, os bucaneiros deixaram a lente guardada em meio à bagunça de seu acampamento na praia ao sul de Vila Catraca. Gasganete conta com aventureiros ousados para enfrentar os assassinos, proteger o vidro impecável e finalmente trazer nitidez ao seu deque de observação."}},faq={{q="Por que Gasganete precisa desta lente?",a="Gasganete precisa dela para terminar o telescópio no observatório de Vila Catraca. O observatório precisa de duas lentes para funcionar; enquanto a maior chegou em segurança por terra a partir de Durotar, a lente telescópica menor se perdeu no mar.",al={"lente de gasganete","para que serve a lente","por que a lente do telescópio"}},{q="Quem roubou a Lente Telescópica?",a="Ela foi saqueada por Southsea Freebooters, um bando de piratas oportunistas humanos e goblins que atacam navios mercantes que navegam perto da Costa dos Mercadores. Eles a mantêm guardada em um caixote marcado em seu acampamento costeiro ao sul de Vila Catraca.",al={"quem pegou a lente","quem está com a lente","localização da lente telescópica"}},{q="De onde a lente veio originalmente?",a="Ela foi enviada por mar para Vila Catraca, ao contrário da sua contraparte que veio por terra a partir de Durotar. As remessas que chegam ao porto frequentemente se originam do outro lado d'O Grande Oceano ou de propriedades goblins ao sul, como Angra do Butim.",al={"onde a lente foi feita","origem da lente","onde gasganete encomendou a lente"}},{q="A lente está intacta, apesar de ter sido roubada?",a="Milagrosamente, sim. A lente foi mantida em segurança dentro de um caixote rotulado 'Frágil - Não Derrube', protegendo o vidro de precisão do manuseio descuidado dos piratas Southsea.",al={"a lente está quebrada","caixote frágil não derrube"}}},fx={ddcd39c0={q="O que é a Lente Telescópica?",a="É uma lente óptica feita com precisão, projetada para um telescópio de observatório. Gazlowe encomendou duas lentes especializadas para completar o telescópio no topo de sua torre em Vila Catraca, e esta peça secundária menor foi enviada para o exterior antes de ser interceptada pelos Southsea Freebooters.",al={"o que é a lente telescópica","item lente telescópica","o que é esta lente"}}},fp="15,186,15.371.0,14.346.0,32.171.0,30.203.0,40.213.0,43.136.0"}
P.entries["item:teronis-journal"] = {n="Diário de Teronis",s="O Diário de Teronis é um caderno de campo recuperado dos restos mortais de um batedor elfo noturno em Vale Gris. Encontrado ao lado do investigador abatido, ele documenta sua busca por uma gema misteriosa e serve como evidência vital para as Sentinelas em Astranaar.",h="O Diário de Teronis é um caderno de campo recuperado dos restos mortais de um batedor elfo noturno em Vale...",kw={"vale gris","astranaar","gema faiscante","raene correlobos","o expurgo de raene","sentinelas","teronis","diário de teronis"},ang={["faction:Alliance"]="Levar as anotações de campo de Teronis de volta a Astranaar ajuda a guarnição a coordenar o socorro e a recuperar os restos mortais do batedor caído.",["race:NightElf"]="O diário representa os deveres perigosos assumidos pelos batedores elfos noturnos que lutam para proteger os bosques ancestrais de Vale Gris da corrupção que se aproxima."},sec={{t="O Registro Final de um Batedor",b="Um velho amigo de Raene Correlobos que ajudava as Sentinelas, Teronis aventurou-se pelas selvas de Vale Gris em busca de uma gema para um bastão que ele acreditava poder conter os ataques de ursobolas contra seu povo. Sua missão terminou abruptamente quando ele tombou em campo, cercado por criaturas agressivas perto da costa. Recuperado de seus pertences pessoais, este diário permanece em condições notavelmente boas, apesar da violência de sua morte. Ele detalha suas descobertas sobre uma gema radiante que outrora fez parte desse bastão, fornecendo aos defensores de Astranaar a pista vital necessária para concluir sua missão inacabada."}},faq={{q="A quem pertencia este diário?",a="O diário pertencia a Teronis, um elfo noturno amigo de Raene Correlobos em Astranaar que procurava em Vale Gris uma forma de conter os ataques de ursobolas. Ele foi morto na natureza antes que pudesse retornar com suas descobertas.",al={"quem escreveu o diário","quem é teronis","história de teronis"}},{q="Onde o diário é encontrado?",a="O diário é recuperado ao vasculhar os pertences de Teronis após descobrir seu corpo abatido nas terras selvagens de Vale Gris, perto das margens habitadas por murlocs locais.",al={"onde encontrar o diário","localização do diário de teronis","como obter o diário"}},{q="Qual é o propósito de levar o diário para Astranaar?",a="Devolver o diário a Raene Correlobos informa Astranaar da morte de Teronis e fornece às Sentinelas as anotações necessárias para continuar a busca pelo bastão com o qual ele esperava conter os ataques de ursobolas.",al={"por que levar o diário para raene","para quem entrego o diário","entrega do diário"}},{q="Que item Teronis estava procurando de acordo com sua missão?",a="Teronis estava procurando por uma gema faiscante, uma das peças de um bastão feito pelo falecido mago Dartol. Sua investigação indicou que os murlocs próximos poderiam ter saqueado o artefato.",al={"o que teronis estava caçando","qual gema ele estava procurando","gema de teronis"}}},fx={["5fb93f8f"]={q="O que é o Diário de Teronis?",a="O Diário de Teronis é um caderno pessoal mantido pelo batedor elfo noturno Teronis. Encontrado entre seus pertences ao lado de seu corpo em Vale Gris, ele detalha sua missão e os esforços iniciais de reconhecimento sobre uma gema estranha que ele foi enviado para encontrar antes de seu falecimento prematuro.",al={"o que é o diário de teronis","item diário de teronis","sobre o diário de teronis"}}},fp="16,115,22.463.0,31.224.0,27.158.0,57.192.0,59.156.0"}
P.entries["item:tharil-zun-s-head"] = {n="Cabeça do Tharil'zun",s="Este troféu macabro é a cabeça decepada de Tharil'zun, líder dos batedores orcs da Rocha Negra que ocupam Mirante de Pedra. O Oficial Marris a exige como prova irrefutável de que o comandante que aterroriza os acessos às Montanhas Cristarrubra foi derrotado.",h="Este troféu macabro é a cabeça decepada de Tharil'zun, líder dos batedores orcs da Rocha Negra que ocupam...",kw={"batedores da rocha negra","vila plácida","oficial marris","mirante de pedra","bastilha mirante de pedra","tharil'zun","cabeça do tharil'zun"},ang={["faction:Alliance"]="Cada chefe da Rocha Negra derrotado alivia a pressão sobre a sitiada Vila Plácida, que luta pela sua sobrevivência sem reforços oficiais de Ventobravo."},sec={{t="Troféu de Mirante de Pedra",b="Os orcs da Rocha Negra entrincheirados na Bastilha Mirante de Pedra exerceram uma pressão implacável sobre Vila Plácida, saqueando fazendas e emboscando viajantes pelas estradas. Na vanguarda desses grupos de saqueadores estavam os Batedores da Rocha Negra, orquestrados por Tharil'zun. Como a guarnição de Vila Plácida não pode se dar ao luxo de agir com base em boatos ou vitórias parciais, o Oficial Marris exige uma prova concreta da morte do líder. Trazer a ele a cabeça decepada de Tharil'zun demonstra que as emboscadas coordenadas a partir da bastilha sofreram um golpe devastador."}},faq={{q="Quem foi Tharil'zun?",a="Tharil'zun era um comandante orc da Rocha Negra astuto e cruel, estacionado na Bastilha Mirante de Pedra. Ele liderou os Batedores da Rocha Negra, que realizavam emboscadas implacáveis com os Renegados entre Vila Plácida e a bastilha.",al={"história de tharil'zun","quem é tharilzun","líder tharil'zun"}},{q="Por que o Oficial Marris quer a cabeça dele?",a="Com Ventobravo negando grande apoio militar às Montanhas Cristarrubra, o Oficial Marris e a guarda de Vila Plácida dependem de mercenários para eliminar ameaças cruciais. Marris exige uma prova absoluta da morte de Tharil'zun para garantir que a liderança dos batedores seja verdadeiramente desmantelada.",al={"por que a cabeça de tharil'zun","marris prova cabeça","recompensa de marris"}},{q="Onde Tharil'zun é encontrado?",a="Tharil'zun ocupa a Bastilha Mirante de Pedra nas colinas orientais das Montanhas Cristarrubra, cercado por orcs da Rocha Negra e gnolls.",al={"localização de tharil'zun","onde fica tharil'zun","encontrar tharil'zun"}},{q="Pegar a cabeça de Tharil'zun encerra a ameaça da Rocha Negra?",a="Não. Embora derrotar Tharil'zun desorganize as emboscadas dos batedores, o clã Rocha Negra mantém uma força maciça entrincheirada dentro da Bastilha Mirante de Pedra e por todas as Montanhas Cristarrubra.",al={"os orcs se foram","salvamos montanhas cristarrubra","após tharil'zun"}}},fx={a015b31b={q="O que é a Cabeça do Tharil'zun?",a="Esta cabeça decepada é a prova física de que Tharil'zun, o comandante que dirigia as emboscadas dos orcs Rocha Negra ao redor da Bastilha Mirante de Pedra, foi morto. Levada de volta para Vila Plácida, ela mostra à guarda da cidade sitiada que um dos líderes de campo mais perigosos do clã Rocha Negra nas Montanhas Cristarrubra não aterrorizará mais as estradas.",al={"item cabeça do tharil'zun","conhecimento sobre a cabeça do tharil'zun"}},f673cecf={q="De onde vem a Cabeça do Tharil'zun?",a="Ela é tirada diretamente do cadáver de Tharil'zun, um proeminente líder orc Rocha Negra operando a partir das ruínas da Bastilha Mirante de Pedra. Depois que ele cai em batalha diante de você ou dos defensores de Vila Plácida, a cabeça é reivindicada como um troféu inegável e uma verificação sombria de sua morte.",al={"quem pegou a cabeça do tharil'zun","origem da cabeça do tharil'zun","de onde veio a cabeça do tharil'zun"}}},fp="17,139,20.381.0,19.185.0,38.234.0,26.121.0,55.167.0"}
P.entries["item:tharnariun-s-hope"] = {n="Esperança de Tharnariun",s="A Esperança de Tharnariun é uma armadilha especializada criada pelo elfo noturno Tharnariun Tratárvore em Costa Negra. Projetado para pacificar animais doentes em vez de feri-los, o dispositivo projeta uma luz calmante destinada a amansar ursos-cardo raivosos para que possam ser examinados em busca de uma cura.",h="A Esperança de Tharnariun é uma armadilha especializada criada pelo elfo noturno Tharnariun Tratárvore em...",kw={"costa negra","terras pestilentas","urso-cardo raivoso","tharnariun","esperança de tharnariun","urso-cardo","armadilha"},ang={["class:Druid"]="A armadilha personifica o ideal cenariano de preservação em vez de extermínio, demonstrando a recusa em abater feras corrompidas quando ainda resta uma chance de redenção.",["race:NightElf"]="A degradação dos estimados ursos-cardo de Costa Negra atinge o cerne da ligação dos kaldorei com a natureza, tornando o dispositivo um símbolo comovente de compaixão desesperada."},sec={{t="Um Laço Suave",b="À medida que uma aflição misteriosa se espalha por Costa Negra, os ursos-cardo locais tornaram-se cada vez mais frenéticos e violentos. Em vez de autorizar o abate da fauna aflita, o druida Tharnariun Tratárvore criou esta armadilha única na esperança de estudar e curar a doença. Quando colocada no chão, a Esperança de Tharnariun emite um brilho calmante. Qualquer urso-cardo raivoso que pise na luz da armadilha tem seu frenesi temporariamente quebrado, tornando a fera dócil o suficiente para seguir um aventureiro de volta ao acampamento de Tharnariun para tratamento."},{t="O Remédio Esquivo",b="Embora a armadilha consiga subjugar as feras enfurecidas sem derramar sangue, a corrupção subjacente se mostra muito mais implacável do que o esperado. Quando Tharnariun canaliza sua magia de cura no urso capturado, o poder restaurador entra em violento conflito com a infecção virulenta, fazendo com que a criatura aflita sucumba e pereça. Apesar do fracasso desolador de sua tentativa inicial, Tharnariun insiste que sua determinação não vacilará até que a verdadeira natureza da doença da floresta seja descoberta."}},faq={{q="O que a Esperança de Tharnariun faz?",a="É uma armadilha de solo encantada projetada para pacificar um urso-cardo raivoso. Colocá-la no chão da floresta cria um campo de luz que acalma temporariamente um urso que atravessa seu perímetro, permitindo que a fera seja conduzida pacificamente de volta a Tharnariun Tratárvore.",al={"esperança de tharnariun uso","como a armadilha funciona","o que e esta armadilha"}},{q="Por que Tharnariun quer que um urso seja capturado vivo?",a="Tharnariun acredita que a doença que aflige a fauna de Costa Negra pode ser curada em vez de encerrada por meio do abate. Ele precisa de uma cobaia viva para testar seus remédios purificadores diretamente.",al={"por que capturar urso-cardo","por que capturar um urso raivoso","o que tharnariun quer"}},{q="Você pode conseguir outra armadilha se perdê-la?",a="Sim. Tharnariun garante aos viajantes que sua esperança é eterna. Se uma armadilha for acionada em vão ou perdida na natureza, retornar a ele fornecerá outro dispositivo para concluir a tarefa.",al={"perdi a esperança de tharnariun","armadilha falhou","armadilha desapareceu"}},{q="O que acontece com o urso assim que ele é trazido de volta?",a="Com a chegada do urso, Tharnariun lança um encantamento de cura para expurgar a corrupção. Tragicamente, a doença vil está enraizada demais; a magia sobrecarrega a fera, e ela morre em poucos instantes.",al={"o urso sobrevive","tharnariun consegue curar o urso","urso morre com tharnariun"}}},fx={["820181a1"]={q="O que é a Esperança de Tharnariun?",a="A Esperança de Tharnariun é uma armadilha encantada criada por Tharnariun Tratárvore. Quando colocada no chão, ela irradia uma luz calmante capaz de pacificar temporariamente os ursos-cardo raivosos e aflitos que vagam pela Costa Negra. O encantamento calmante torna uma fera frenética gentil e disposta a segui-lo de volta para Auberdine.",al={"o que é a esperança de tharnariun","item esperança de tharnariun","armadilha de tharnariun"}},["88ba9e19"]={q="De onde vem a Esperança de Tharnariun e quem a fez?",a="A armadilha foi criada e encantada por Tharnariun Tratárvore, um naturalista elfo noturno estacionado na Costa Negra. Horrorizado pela doença misteriosa que levava a vida selvagem da floresta à loucura, ele criou este dispositivo usando magia suave para subjugar as feras infectadas sem causar mais danos a elas.",al={"quem fez a esperança de tharnariun","origem da esperança de tharnariun","criador da armadilha de tharnariun"}},c80e933b={q="Por que alguém quer a Esperança de Tharnariun?",a="Tharnariun precisa da armadilha para capturar um urso-cardo raivoso vivo, para que ele possa estudar a corrupção que assola a Costa Negra. A caça comum apenas mataria a fera, mas esta armadilha pacifica o animal tempo o suficiente para você conduzi-lo com segurança até seus cuidados, na esperança de descobrir uma cura.",al={"por que usar a esperança de tharnariun","por que preciso da armadilha de tharnariun","propósito da esperança de tharnariun"}}},fp="17,135,14.402.0,18.413.1,31.184.0,46.168.0,40.122.0,49.144.1"}
P.entries["item:the-book-of-ur"] = {n="O Livro de Ur",s="O Livro de Ur é um tratado mágico acadêmico escrito pelo falecido mago de Dalaran Ur, detalhando suas pesquisas sobre estranhas entidades extradimensionais. Deixado para trás na Bastilha da Presa Negra, ele caiu nas mãos do Arquimago Arugal antes de despertar o grande interesse de pesquisadores Renegados na Cidade Baixa.",h="O Livro de Ur é um tratado mágico acadêmico escrito pelo falecido mago de Dalaran Ur, detalhando suas...",kw={"boticarium","arugal","o livro de ur","dalaran","guardião bel'dugur","bastilha da presa negra","floresta de pinhaprata","ur"},ang={["class:Mage"]="Os escritos de Ur são um lembrete contundente do alcance acadêmico de Dalaran em outros reinos — e das consequências letais quando magos ambiciosos como Arugal fazem mau uso desse conhecimento proibido.",["race:Undead"]="Garantir a posse da obra de Ur ajuda diretamente os eruditos da Dama Sombria no Boticarium, transformando a pesquisa cautelosa de um mago humano caído em poder prático para os Renegados."},sec={{t="O Mago de Dalaran",b="Antes de Dalaran cair perante o Flagelo, Ur era renomado entre o Kirin Tor por suas investigações esotéricas sobre outros planos de existência e criaturas de outros mundos. Apesar de seu fascínio pela magia extraplanar, Ur era guiado pela cautela e pela moderação ética, optando por registrar suas descobertas em vez de romper imprudentemente o véu entre os mundos. Tragicamente, quando o Flagelo atacou a cidade violeta, sua proeza mágica e suas hesitações morais não foram suficientes para salvá-lo."},{t="Ambição dos Renegados",b="Após a morte de Ur, seus escritos foram parar nas mãos do Arquimago Arugal, que utilizou a pesquisa para invocar os monstruosos worgens na Floresta de Pinhaprata. O tomo agora repousa nas prateleiras da Bastilha da Presa Negra. A notícia de sua existência chamou a atenção do Guardião Bel'dugur no Boticarium da Cidade Baixa. Ao contrário de seu autor original, os Renegados não têm reservas quanto ao uso de magia perigosa e irrestrita para garantir sua sobrevivência e conquista."}},faq={{q="Quem foi Ur?",a="Ur foi um proeminente mago humano de Dalaran antes da Terceira Guerra. Ele pesquisou extensivamente outras dimensões e criaturas extraplanares, embora tenha se recusado a invocá-las devido ao imenso perigo que representavam.",al={"quem escreveu o livro de ur","ur mago de dalaran"}},{q="Onde fica O Livro de Ur?",a="O livro repousa em uma estante dentro da Bastilha da Presa Negra, na Floresta de Pinhaprata, especificamente na câmara onde reside a enorme besta Fenrus.",al={"localização do livro de ur","onde fica o livro de ur"}},{q="Por que o Guardião Bel'dugur quer o livro?",a="O Guardião Bel'dugur recolhe os escritos de Ur em nome de partes interessadas na Cidade Baixa. Os Renegados acreditam que a consciência moral de Ur o impediu de alcançar o verdadeiro poder e buscam utilizar sua pesquisa extraplanar sem quaisquer limitações éticas para fortalecer suas próprias forças.",al={"guardião bel'dugur livro de ur","por que cidade baixa quer o livro"}},{q="Como o livro foi parar na Bastilha da Presa Negra?",a="Depois que Ur morreu durante a queda de Dalaran, o Arquimago Arugal adquiriu suas pesquisas. Levado a medidas desesperadas para se defender do Flagelo, Arugal levou as anotações para a Floresta de Pinhaprata e usou as teorias de invocação de Ur para atrair os worgens para Azeroth.",al={"arugal e o livro de ur","como arugal conseguiu o livro"}}},fx={["62a01830"]={q="O que é O Livro de Ur?",a="O Livro de Ur é um tomo acadêmico que contém a pesquisa esotérica de Ur, um mago talentoso de Dalaran. Ele detalha seus extensos estudos sobre outros mundos e fenômenos arcanos perigosos — conhecimento que provou ser tão potente que o Arquimago Arugal mais tarde usou os escritos de Ur para invocar os monstruosos worgens para a Floresta de Pinhaprata.",al={"o que é o livro de ur","conhecimento sobre o livro de ur"}},["905bb2c4"]={q="De onde vem O Livro de Ur e quem o fez?",a="O livro foi escrito no reino mágico de Dalaran pelo mago Ur antes da destruição da cidade pelo Flagelo. Ur documentou suas teorias arcanas e explorações em outras dimensões, embora seu trabalho tenha sido abandonado após seu falecimento durante a queda de Dalaran.",al={"quem escreveu o livro de ur","origem do livro de ur","de onde veio o livro de ur"}}},fp="14,174,19.378.0,17.359.1,11.167.0,32.128.0,40.215.0,43.216.0"}
P.entries["item:the-collector-s-schedule"] = {n="A Escala do Coletor",s="A Escala do Coletor é um itinerário manuscrito detalhando datas e horários para remessas ilícitas de ouro extraído das minas da Floresta de Elwynn. Recuperado de gnolls locais, o documento revela que uma figura esquiva conhecida apenas como \\\"The Collector\\\" está coordenando a operação perto da Plantação de Abóboras dos Braga.",h="A Escala do Coletor é um itinerário manuscrito detalhando datas e horários para remessas ilícitas de ouro...",kw={"plantação de abóboras dos braga","the collector","delegado durão","floresta de elwynn","ouro","vila d'ouro","minas","escala"},ang={["faction:Alliance"]="A escala expõe como o domínio de Ventobravo sobre seu próprio território se tornou frágil, com operações não autorizadas saqueando os recursos naturais do reino bem nos arredores da capital.",["profession:Mining"]="O documento prova que, apesar dos relatos de que as minas de Elwynn estão abandonadas, veios ricos de ouro estão sendo ativamente explorados e transportados."},sec={{t="Ouro Roubado e Remessas Secretas",b="A escala fornece provas alarmantes de atividade organizada bem debaixo do nariz da guarnição de Ventobravo. Embora o reino não opere formalmente as minas de Elwynn há meses devido ao banditismo e incursões de criaturas, o minério ainda está sendo sistematicamente extraído e transportado. O bilhete lista dias e horários específicos em que alguém chamado \\\"The Collector\\\" recebe remessas, apontando para um acampamento perto da Plantação de Abóboras dos Braga, no leste da Floresta de Elwynn. Ao ser apresentado ao documento, o Delegado Durão reconhece o nome do Collector, embora o verdadeiro mentor que paga pelo ouro roubado permaneça oculto."}},faq={{q="O que é a Escala do Coletor?",a="É um documento recuperado que define o cronograma para remessas de ouro saindo das minas abandonadas da Floresta de Elwynn para um agente chamado \\\"The Collector\\\".",al={"o que é este bilhete","item a escala do coletor","escala do ouro"}},{q="De onde veio a escala?",a="O bilhete é carregado pelos gnolls que infestam as margens dos rios e encostas da Floresta de Elwynn, sugerindo que eles interceptaram um mensageiro ou estão de alguma forma envolvidos no transporte do ouro.",al={"quem saqueia a escala","onde encontrar a escala"}},{q="Quem é o Collector?",a="O Collector é um agente posicionado perto da Plantação de Abóboras dos Braga, no leste da Floresta de Elwynn. A escala do Classic menciona a Irmandade Défias e seu quartel-general em Cerro Oeste, embora o Delegado Durão afirme que ainda não sabe para quem o Collector trabalha.",al={"quem é o collector","identidade do collector"}},{q="Por que o Delegado Durão está alarmado com esta escala?",a="Ventobravo não tem mineradores oficiais trabalhando nas minas de Elwynn há meses devido a ameaças à segurança. Descobrir que remessas substanciais de ouro ainda estão sendo transportadas revela uma operação de mineração ilícita e organizada funcionando bem dentro das fronteiras do reino.",al={"por que durão se importa","ouro das minas de elwynn"}}},fp="24,216,32.467.0,33.129.0,33.150.0,21.170.0,47.231.0"}
P.entries["item:the-embalmer-s-heart"] = {n="Coração do Embalsamador",s="O Coração do Embalsamador é uma relíquia profana que pulsa dentro do cadáver morto-vivo de Eliza, sepultada nas profundezas da Floresta do Crepúsculo. Antes pertencente a um alquimista consumido pelo luto conhecido como o Embalsamador, o órgão foi transplantado por meio de magia sombria para reviver sua falecida esposa, tornando-se a principal âncora de seu poder distorcido.",h="O Coração do Embalsamador é uma relíquia profana que pulsa dentro do cadáver morto-vivo de Eliza, sepultada...",kw={"a noiva do embalsamador","vila sombria","floresta do crepúsculo","eliza","ello ebonlocke","coração do embalsamador","o embalsamador"},ang={["class:Warlock"]="Transplantar um órgão ainda pulsante e vinculado à alma para ancorar a não-vida necromântica é um feito ambicioso, ainda que caótico, de modelagem de carne e manipulação de almas.",["race:Human"]="A trágica decadência do bondoso alquimista serve como um conto sombrio de advertência sussurrado entre o povo atormentado da Floresta do Crepúsculo."},sec={{t="Um amor que desafiou a morte",b="De acordo com o folclore de Vila Sombria, o Embalsamador já foi um alquimista gentil cuja mente se despedaçou com a morte de sua amada esposa, Eliza. Desesperado para resgatá-la da sepultura, ele recorreu a feitiçarias vis e arrancou o próprio coração, colocando-o dentro do peito sem vida de Eliza. Embora a transfusão profana tenha conseguido despertar o cadáver de volta à não-vida, a ressurreição a distorceu em uma criatura voraz consumida por uma fome insaciável de carne humana viva, forçando o aterrorizado alquimista a sepultá-la mais uma vez sob a terra."},{t="Um escudo para Vila Sombria",b="Apesar de arrancado do peito, o coração permanece como a fonte do duradouro poder sombrio do Embalsamador e continua a bater dentro da tumba de Eliza. O Prefeito Ello Ebonlocke percebe que destruir a noiva reanimada e reivindicar o órgão pulsante é a única maneira de despojar o Embalsamador de sua feitiçaria. Ao assegurar o coração enquanto ele ainda bate, a liderança de Vila Sombria espera voltar a própria magia malevolente do necromante contra ele, usando sua essência como uma proteção mágica contra seus terrores."}},faq={{q="Por que Eliza tem o coração do Embalsamador?",a="O Embalsamador, devastado pela morte de sua esposa Eliza, usou magia proibida para colocar seu próprio coração pulsante no cadáver dela a fim de ressuscitá-la. O ritual a reanimou, embora a tenha amaldiçoado com uma fome insaciável de carne humana.",al={"por que eliza tem o coração","coração do embalsamador em eliza","quem colocou o coração em eliza"}},{q="Por que o Prefeito Ebonlocke quer que o coração seja levado de volta a Vila Sombria?",a="O Prefeito Ello Ebonlocke pretende usar a magia sombria que ainda ressoa dentro do coração pulsante para criar uma égide defensiva sobre Vila Sombria, neutralizando o poder do Embalsamador e transformando-o em uma proteção para resguardar a cidade.",al={"por que ello quer o coração","plano de ebonlocke para o coração","o que vila sombria faz com o coração"}},{q="Como o Embalsamador sobrevive sem o coração?",a="Por meio das feitiçarias sombrias que praticava, o Embalsamador vinculou sua força vital e seu poder diretamente ao coração transplantado, permitindo que ele resista mesmo enquanto o órgão bate dentro dos restos mortais enterrados de sua esposa.",al={"o embalsamador está vivo","como o embalsamador vive sem coração"}},{q="Onde o coração pode ser encontrado?",a="O coração repousa dentro de Eliza, que permanece enterrada em uma sepultura oculta na Floresta do Crepúsculo. Ele só pode ser obtido ao confrontar e derrotar a voraz noiva reanimada.",al={"onde fica o coração do embalsamador","localização do túmulo de eliza","como obter o coração do embalsamador"}}},fx={cac9cdef={q="O que é o Coração do Embalsamador?",a="É o coração batendo literalmente, mantido magicamente, do alquimista renegado conhecido como o Embalsamador. Enlouquecido pelo luto pela morte de sua esposa, Eliza, ele arrancou seu próprio coração e o colocou dentro do cadáver dela para trazê-la de volta à vida. Mesmo separado de seu peito, o coração serve como receptáculo e condutor de seu poder necromântico, mantendo tanto o estado amaldiçoado de morta-viva de Eliza quanto sua própria vitalidade profana.",al={"o que é o coração do embalsamador","conhecimento sobre o coração do embalsamador","o coração do embalsamador"}}},fp="20,173,24.367.0,22.376.1,41.169.0,66.117.0,48.156.0,29.163.0"}
P.entries["item:the-first-troll-legend"] = {n="The First Troll Legend"}
P.entries["item:the-fourth-troll-legend"] = {n="The Fourth Troll Legend",s="Nas Ruínas de Zul'Kanda, a Fourth Troll Legend leva a busca do Irmão Nimetz às antigas pedras da Selva do Espinhaço. Suas inscrições podem ajudar a explicar a corrupção do Coronel Kurzen.",h="Nas Ruínas de Zul'Kanda, a Fourth Troll Legend leva a busca do Irmão Nimetz às antigas pedras da Selva do...",kw={"irmão nimetz","coronel kurzen","emperor's tomb","quarta lenda dos trolls","selva do espinhaço","tabuleta troll","zul'kanda"},ang={["faction:Alliance"]="Como viajante da Aliança, você pode ajudar o Irmão Nimetz a investigar a queda do Coronel Kurzen, levando a ele as inscrições de Zul'Kanda."},sec={{t="Uma tabuleta em Zul'Kanda",b="Entre as ruínas do norte de Zul'Kanda, a Emperor's Tomb guarda a Fourth Troll Legend. O Irmão Nimetz procura suas inscrições junto com outras três lendas dos trolls. Ele espera que as palavras antigas esclareçam a queda do Coronel Kurzen e enviou você para trazê-las para estudo."}},faq={{q="O que é a Fourth Troll Legend?",a="A Fourth Troll Legend é um conjunto de inscrições em uma tabuleta de pedra chamada Emperor's Tomb, nas Ruínas de Zul'Kanda.",al={"quarta lenda dos trolls","quarta tabuleta","lenda quatro dos trolls"}},{q="Onde posso encontrar a Fourth Troll Legend?",a="A Emperor's Tomb fica entre as Ruínas de Zul'Kanda, no noroeste da Selva do Espinhaço.",al={"localização da quarta lenda","onde fica emperor's tomb","tabuleta de zul'kanda"}},{q="Quem quer a Fourth Troll Legend?",a="O Irmão Nimetz, no Acampamento dos Rebeldes, quer as inscrições da Fourth Troll Legend para poder estudá-las.",al={"quem precisa da quarta lenda","tabuleta do irmão nimetz","lendas do nimetz"}},{q="Por que o Irmão Nimetz está estudando lendas dos trolls?",a="O Irmão Nimetz espera que as lendas dos trolls revelem o que causou a corrupção do Coronel Kurzen.",al={"mistério de kurzen","por que estudar lendas dos trolls","corrupção de kurzen"}},{q="Quais são as outras lendas dos trolls?",a="As outras tabuletas guardam a First Troll Legend, a Second Troll Legend e a Third Troll Legend. Elas ficam nas Ruínas de Bal'lal, no Arrecife Torpe e nas Ruínas de Zul'Kanda, na Selva do Espinhaço.",al={"primeira segunda terceira lendas","outras tabuletas","todas as quatro lendas"}}},fp="23,177,21.271.0,32.115.0,41.90.0,34.102.0,45.90.0,33.150.0"}
P.entries["item:the-general-s-response"] = {n="A Resposta do General",s="A Resposta do General é um despacho militar oficial escrito pelo General Marcus Jonas, comandante da guarda da cidade de Ventobravo. Destinado ao Magistrado Salomão em Vila Plácida, o comunicado reconhece o pedido de ajuda de Cristarrubra, ao mesmo tempo que revela que a capital não pode — ou não quer — enviar reforços reais imediatamente.",h="A Resposta do General é um despacho militar oficial escrito pelo General Marcus Jonas, comandante da guarda...",kw={"general marcus jonas","vila plácida","magistrado salomão","mensageiro para ventobravo","montanhas cristarrubra","ventobravo","a resposta do general"},ang={["faction:Alliance"]="A resposta destaca as bordas desgastadas da Grande Aliança: assentamentos externos como Vila Plácida sangram enquanto a corte de Ventobravo parece estranhamente indiferente ao seu sofrimento.",["race:Human"]="Para os humanos dos reinos do sul, essa correspondência estagnada mostra a crescente ruptura entre os cidadãos que lutam pela sobrevivência nas províncias e a nobreza reclusa em Bastilha Ventobravo."},sec={{t="Um Impasse Diplomático",b="Quando o Magistrado Salomão entra em contato com Ventobravo buscando desesperadamente tropas para repelir os clãs de orcs Rocha Negra e os bandos de guerra Gnoll que se reúnem em Cristarrubra, ele envia seu apelo diretamente ao alto comando. A resposta escrita do General Marcus Jonas traz pouco consolo: embora o apelo tenha sido encaminhado ao trono, nenhum soldado foi despachado no momento. Preso entre o protocolo e a política, o General ordena que a carta seja entregue de volta a Vila Plácida, deixando Salomão preocupado e desconfiado de que uma doença mais profunda paralisa a liderança da capital."}},faq={{q="O que está escrito em A Resposta do General?",a="O General Marcus Jonas lamenta as mortes e promete informar o Rei sobre a situação de Vila Plácida. Ele espera trazer reforços e confidencia que Sua Majestade tem estado ausente e agindo de forma estranha.",al={"conteúdo da carta","o que a carta diz","carta do general"}},{q="Por que o General Marcus Jonas não pode enviar tropas para Vila Plácida?",a="O General Jonas está aguardando uma resposta do Rei antes de poder prometer reforços. Em confidência, ele diz a Salomão que Sua Majestade tem estado ausente e agindo de forma estranha.",al={"por que sem reforços","por que ventobravo não ajuda vila plácida","por que sem ajuda"}},{q="Como o Magistrado Salomão reage à carta?",a="O Magistrado Salomão fica profundamente perturbado com o despacho. Ele acha a lentidão de Ventobravo inexplicável dada a terrível ameaça a Vila Plácida, concluindo que algo está profundamente errado no reino e temendo que esse descaso sinalize o início de calamidades piores.",al={"reação de salomão","o que salomão pensa","resposta de salomão"}}},fx={["3ebc4cbb"]={q="O que é A Resposta do General?",a="É um despacho oficial selado escrito pelo General Marcus Jonas, comandante da Guarda de Ventobravo, endereçado ao Magistrado Salomão em Montanhas Cristarrubra. Transportada por mensageiros entre a capital e Vila Plácida, a missiva entrega a resposta formal do alto comando referente ao pedido desesperado de reforços reais de Montanhas Cristarrubra.",al={"o que é a resposta do general","item resposta do general","o que é esta carta"}},["174955dc"]={q="De onde vem A Resposta do General e quem a fez?",a="A carta é escrita diretamente pelo General Marcus Jonas na cidade de Ventobravo. Após receber a petição urgente do Magistrado Salomão no Vale dos Heróis, Jonas redige esta resposta formal enquanto aguarda notícias da corte real, confiando a você a tarefa de levá-la de volta ao magistrado em Vila Plácida.",al={"quem escreveu a resposta do general","de onde veio a resposta do general","quem enviou a resposta do general"}},d0ef00e9={q="Por que alguém quer A Resposta do General?",a="O Magistrado Salomão aguarda ansiosamente por este despacho para saber se Ventobravo enviará soldados para resgatar Vila Plácida dos orcs Rocha Negra e dos gnolls. Entregá-la dá à liderança da cidade sitiada uma palavra clara sobre qual ajuda o reino pode — ou não pode — fornecer.",al={"por que salomão quer a carta","quem quer a resposta do general","por que entregar a resposta do general"}}},fp="22,247,21.365.0,42.193.0,59.176.0,48.190.0"}
P.entries["item:the-legacy-heart"] = {n="The Legacy Heart",s="Uma magia sombria envolve Legacy Heart, uma relíquia procurada junto com outros dois itens de poder. Gerrig Agarrosso, em Altaforja, a quer para um propósito ligado ao Compêndio de Yagyin.",h="Uma magia sombria envolve Legacy Heart, uma relíquia procurada junto com outros dois itens de poder.",kw={"anotação de bonegrip","magia sombria","gerrig agarrosso","mão de dagun","legacy heart","estrela de xil'yeh","compêndio de yagyin"},ang={["faction:Alliance"]="Como viajante da Aliança, você pode levar Legacy Heart e outras duas relíquias para Gerrig Agarrosso, em Altaforja, em troca do Compêndio de Yagyin."},sec={{t="Uma relíquia de poder",b="Gerrig Agarrosso pede Legacy Heart entre três relíquias que anotou em Bonegrip's Note. Ele trocará o compêndio por elas, mas não revela seus nomes em voz alta. O encantamento sombrio de Heart lhe rendeu uma reputação temível."}},faq={{q="O que é Legacy Heart?",a="Legacy Heart é uma relíquia de poder que Gerrig Agarrosso procura em troca do Compêndio de Yagyin.",al={"legacy heart","relíquia heart","heart de magia sombria"}},{q="Quem quer Legacy Heart?",a="Gerrig Agarrosso, em Altaforja, pede Legacy Heart e outras duas relíquias.",al={"quem quer heart","gerrig heart","relíquia de bonegrip"}},{q="Por que Gerrig a quer?",a="Gerrig precisa de Legacy Heart e de outras duas relíquias para entregar o Compêndio de Yagyin.",al={"por que bonegrip quer","propósito de heart","motivo de gerrig"}},{q="O que dizem que Heart faz?",a="Dizem que a magia sombria concede imortalidade a quem possuir Legacy Heart; seu dono atual carrega o título the Undying.",al={"poder de heart","magia de legacy heart","heart que nunca morre"}},{q="Que outras relíquias Gerrig procura?",a="Gerrig pede a Estrela de Xil'yeh, a Mão de Dagun e Legacy Heart.",al={"outras relíquias","estrela mão heart","lista de bonegrip"}}},fp="16,166,16.236.0,25.95.0,27.76.0,24.91.0,29.113.2,35.76.0"}
P.entries["item:the-lich-s-spellbook"] = {n="Grimório do Lich",s="O Grimório do Lich é um volume de conhecimentos necromânticos mantido dentro de um baú na ilha no Lago Águas Claras. Recuperado para Boanerges Stalactus na Cidade Baixa, o tomo revela a verdadeira identidade e o imenso poder mágico de um lich morto-vivo recluso que habita logo ao norte da capital dos Renegados.",h="O Grimório do Lich é um volume de conhecimentos necromânticos mantido dentro de um baú na ilha no Lago Águas...",kw={"boanerges stalactus","lago águas claras","tertuliano arcanus","lich","necromancia","grimório","clareiras de tirisfal","cidade baixa"},ang={["class:Mage"]="O grimório representa uma ponte extraordinária entre a feitiçaria clássica de Dalaran e a necromancia sombria, mostrando como os conjuradores mortais expandiram drasticamente seu ofício após sucumbirem à morte.",["race:Undead"]="O tomo prova que nem todos que se libertaram do Lich Rei se juntaram aos Renegados imediatamente, destacando a desconfiança persistente entre os mortos-vivos sobreviventes que vagam pelas Clareiras de Tirisfal."},sec={{t="Os Tomos de um Mestre Recluso",b="Em uma ilha isolada no Lago Águas Claras, encontra-se um lich enigmático cercado por guardiões esqueléticos. Embora tenha livre-arbítrio, este feiticeiro desconfia do mundo exterior, confundindo todos os outros mortos-vivos com escravos do Flagelo e ordenando que seus lacaios destruam qualquer um que se aproxime. Boanerges Stalactus, buscando necromantes talentosos para reforçar as fileiras dos Renegados sob o comando da Rainha Sylvana Correventos, encarregou um emissário de se infiltrar no acampamento da ilha para recuperar o Grimório do Lich. Por meio de seu estudo, Boanerges esperava discernir a aptidão mágica do mestre e descobrir quem ele era antes que a morte levasse Lordaeron."},{t="Desmascarando Tertuliano Arcanus",b="Ao abrir as páginas brilhantes do grimório recuperado, Boanerges Stalactus fez uma descoberta surpreendente: o recluso era seu velho amigo e companheiro de armas de antes da Terceira Guerra, Tertuliano Arcanus. Já um prodígio em necromancia em vida, os escritos de Tertuliano revelaram que suas artes se tornaram ainda mais formidáveis na morte. Boanerges reconheceu que garantir a lealdade de Tertuliano daria aos Renegados um mestre inestimável das artes sombrias, contanto que alguém pudesse convencer o lich desconfiado de que os Renegados estão verdadeiramente livres do controle do Lich Rei."}},faq={{q="Onde o Grimório do Lich é encontrado?",a="O grimório descansa dentro de um recipiente chamado Livros de Tertuliano, situado no acampamento na ilha central do Lago Águas Claras, no norte das Clareiras de Tirisfal.",al={"onde está o livro","localização do grimório","livros de tertuliano"}},{q="Quem é o dono deste grimório?",a="Ele pertence ao lich recluso e de livre-arbítrio na ilha no Lago Águas Claras. Boanerges Stalactus espera que o estudo de suas páginas revele a identidade e os talentos do proprietário.",al={"de quem é este livro","identidade do lich","quem escreveu o grimório"}},{q="Por que Boanerges Stalactus quer o livro?",a="Boanerges Stalactus procurou o livro para deduzir a identidade do misterioso lich e avaliar seu domínio da necromancia, esperando recrutar o recluso para o serviço da Lady Sylvanas e dos Renegados.",al={"por que pegar o livro","motivo da missão de boanerges","por que a cidade baixa quer isto"}},{q="Por que o lich ataca os visitantes de sua ilha?",a="O lich acredita que todos os outros mortos-vivos na região permanecem escravos do Flagelo com a mente controlada. Paralisado pela desconfiança, ele ordena que seus lacaios ataquem qualquer um que se aventure perto de seu santuário.",al={"por que tertuliano é hostil","por que os lacaios atacam","hostilidade no lago águas claras"}},{q="O que Boanerges espera aprender sobre o autor?",a="Boanerges espera descobrir quem era o lich isolado em vida e se seu conhecimento necromântico poderia ajudar os Renegados.",al={"o que boanerges aprenderá","estudo do autor lich","estudo do grimório por boanerges"}}},fx={["44ee6981"]={q="De onde vem o Grimório do Lich e quem o criou?",a="O grimório pertence ao lich recluso de vontade própria que vive na ilha do Lago Águas Claras. Ele próprio escreveu e manteve o tomo, preenchendo suas páginas luminosas com suas artes necromânticas tanto em vida quanto após sua transformação em lich. Boanerges Stalactus o quer para descobrir quem era o lich.",al={"quem criou o grimório do lich","origem do grimório do lich","de onde veio o grimório do lich"}}},fp="20,161,26.483.0,25.432.1,36.140.0,24.154.1,39.145.0,48.149.0,48.117.1"}
P.entries["item:the-second-troll-legend"] = {n="The Second Troll Legend"}
P.entries["item:the-state-of-lakeshire"] = {n="A Situação de Lago Plácido",s="A Situação de Lago Plácido é um relatório urgente por escrito redigido pelo Magistrado Salomão detalhando a crise militar desesperadora que assola a cidade de Vila Plácida. Destinado diretamente ao General Marcus Jonas em Ventobravo, o documento implora para que a capital envie reforços do exército real antes que o assentamento das Montanhas Cristarrubra caia.",h="A Situação de Lago Plácido é um relatório urgente por escrito redigido pelo Magistrado Salomão detalhando a...",kw={"despacho","magistrado salomão","marcus jonas","montanhas cristarrubra","reforços","relatório","a situação de lago plácido","ventobravo"},ang={["faction:Alliance"]="O relatório ilustra a fragilidade dos assentamentos periféricos e destaca a inércia política que atualmente atrasa a ajuda militar vinda da capital.",["race:Human"]="Para os humanos do reino, carregar este documento ressalta os laços enfraquecidos entre o povo comum das Montanhas Cristarrubra e a distante coroa em Ventobravo."},sec={{t="Um Clamor por Ajuda",b="Redigido pelo Magistrado Salomão em meio a ataques implacáveis nas Montanhas Cristarrubra, 'A Situação de Lago Plácido' descreve as circunstâncias terríveis que ameaçam o vilarejo. Cercada por orcs Blackrock hostis e gnolls, Vila Plácida não possui a mão de obra local necessária para manter suas fronteiras indefinidamente. Confiado a mensageiros de confiança que viajam pela estrada a oeste rumo à Floresta de Elwynn, este despacho carrega o pedido formal de Salomão para que o Exército de Ventobravo intervenha e preserve os limites orientais do reino."},{t="Burocracia e Impasse",b="Após ser entregue ao General Marcus Jonas nos portões de Ventobravo, o general reconhece a nobre posição de Salomão e a gravidade do relatório. No entanto, Jonas não pode mobilizar o exército unilateralmente. Desdobramentos militares exigem o consentimento explícito da coroa, forçando o apelo urgente de Vila Plácida a aguardar uma consulta de alto nível com o jovem Rei e o regente Bolvar Fordragon."}},faq={{q="O que é A Situação de Lago Plácido?",a="É um despacho oficial por escrito elaborado pelo Magistrado Salomão detalhando o perigo militar enfrentado por Vila Plácida e implorando a Ventobravo por reforços de tropas.",al={"documento a situação de lago plácido","o que é este relatório","mensagem de salomão"}},{q="Quem deve receber este despacho?",a="O relatório é endereçado diretamente ao General Marcus Jonas, comandante da guarda da cidade de Ventobravo e das forças reais, estacionado nos portões de Ventobravo.",al={"quem recebe o relatório","a quem entregar","relatório de marcus jonas"}},{q="Por que Vila Plácida precisa de reforços reais?",a="O assentamento enfrenta um cerco constante de orcs Blackrock, gnolls Shadowhide e murlocs locais, empurrando a guarda local da cidade além de seus limites.",al={"por que vila plácida está em perigo","o que ameaça as montanhas cristarrubra"}},{q="O General Marcus Jonas envia ajuda imediatamente?",a="Não. Embora o general concorde com a gravidade da crise, ele não pode mobilizar o exército sem a aprovação formal do Rei, o que significa que o pedido deve passar primeiro por uma análise real.",al={"ventobravo ajuda","jonas envia tropas"}}},fx={["629511cc"]={q="De onde vem A Situação de Lago Plácido e quem a criou?",a="O Magistrado Salomão, o líder civil e juiz de Vila Plácida, redigiu este relatório crítico. Enfrentando pressão implacável de forças hostis que cercam a cidade, Salomão escreveu o despacho pessoalmente para detalhar formalmente a situação perigosa das Montanhas Cristarrubra e solicitar ao alto comando de Ventobravo ajuda militar imediata.",al={"quem escreveu a situação de lago plácido","quem fez a situação de lago plácido","autor da situação de lago plácido"}},["09d61feb"]={q="Por que A Situação de Lago Plácido é necessária com tanta urgência?",a="Vila Plácida está sob cerco constante, e o Magistrado Salomão sabe que a cidade não pode resistir sozinha sem reforços reais. O General Marcus Jonas precisa desta contabilidade oficial em mãos para justificar o envio de elementos do Exército de Ventobravo e apresentar a situação terrível de Vila Plácida diretamente ao Rei e ao Grão-lorde Bolvar Fordragon.",al={"por que a situação de lago plácido é necessária","por que entregar a situação de lago plácido","por que marcus jonas quer a situação de lago plácido"}}},fp="22,188,13.289.0,24.301.0,31.130.0,41.150.0,45.150.0,51.161.0"}
P.entries["item:the-third-troll-legend"] = {n="The Third Troll Legend",s="Nas Ruínas de Zul'Kanda, a Terceira Lenda Troll é uma das quatro transcrições de tabuletas que o Irmão Nimetz procura. Ele espera que as antigas inscrições esclareçam a corrupção do Coronel Kurzen.",h="Nas Ruínas de Zul'Kanda, a Terceira Lenda Troll é uma das quatro transcrições de tabuletas que o Irmão Nimetz...",kw={"irmão nimetz","coronel kurzen","fall of gurubashi","kurzen's mystery","terceira lenda troll","tabuleta troll","zul'kanda"},ang={["faction:Alliance"]="A preocupação do Irmão Nimetz é o Coronel Kurzen, um oficial da Aliança cuja corrupção o alarmou. As lendas podem ajudar a explicar o que aconteceu com Kurzen."},sec={{t="Pedra em Zul'Kanda",b="Entre as salas sem teto das Ruínas de Zul'Kanda, a Terceira Lenda Troll está inscrita em uma tabuleta de pedra chamada Fall of Gurubashi. O Irmão Nimetz, no Acampamento dos Rebeldes, procura essas inscrições. Ele estuda quatro lendas troll em busca de uma possível ligação com a corrupção do Coronel Kurzen."}},faq={{q="O que é a Terceira Lenda Troll?",a="A Terceira Lenda Troll é uma transcrição das inscrições da tabuleta Fall of Gurubashi, nas Ruínas de Zul'Kanda.",al={"terceira lenda troll","tabuleta troll","lenda de zul'kanda"}},{q="Onde fica a tabuleta Fall of Gurubashi?",a="A tabuleta Fall of Gurubashi fica na sala sudoeste das Ruínas de Zul'Kanda, no platô.",al={"localização de fall of gurubashi","onde fica a terceira tabuleta","tabuleta de zul'kanda"}},{q="Quem procura a Terceira Lenda Troll?",a="O Irmão Nimetz, no Acampamento dos Rebeldes, procura as quatro lendas troll para estudar sua possível ligação com a corrupção do Coronel Kurzen.",al={"quem procura a tabuleta","lenda do irmão nimetz","mistério de kurzen"}},{q="Por que o Irmão Nimetz está coletando lendas troll?",a="O Irmão Nimetz suspeita que a magia troll possa estar ligada à corrupção do Coronel Kurzen e espera que as lendas ajudem em sua investigação.",al={"por que nimetz quer as lendas","magia troll de kurzen","por que o mistério de kurzen"}}},fp="22,182,18.270.0,31.114.0,38.99.0,33.128.0,47.138.0"}
P.entries["item:theramore-medal"] = {n="Medalha de Theramore",s="A Medalha de Theramore é uma insígnia militar portada pela guarnição da Aliança posicionada na Fortaleza da Guardanorte. Estampadas com o símbolo de Theramore, essas peças servem como comprovante de serviço para fuzileiros e oficiais que defendem o posto avançado ao longo da Costa dos Mercadores.",h="A Medalha de Theramore é uma insígnia militar portada pela guarnição da Aliança posicionada na Fortaleza da...",kw={"sertões","captain fairmount","costa dos mercadores","fortaleza da guardanorte","thalo'thas solaz","medalha de theramore"},ang={["faction:Alliance"]="Para os leais à Aliança, ver medalhas de Theramore sendo recolhidas como recompensas de sangue é um lembrete severo de quão isolada e agressiva a Fortaleza da Guardanorte se tornou na fronteira de Kalimdor.",["faction:Horde"]="Os aventureiros da Horda veem essas medalhas como prova física da crescente presença militar da Aliança que avança diretamente sobre as praias dos Sertões."},sec={{t="Símbolos da Guardanorte",b="Portadas por fuzileiros, atiradores, comandos e oficiais que servem a partir da Fortaleza da Guardanorte, essas medalhas cunhadas indicam a lealdade militar ao reino de Theramore de Grã-senhora Jaina Proudmore. Para os soldados humanos posicionados sobre as falésias com vista para os Sertões, elas representam serviço legítimo e autoridade soberana em uma fronteira hostil. Para forasteiros, no entanto, as medalhas são troféus de uma guarnição estrangeira e obstinada que encara qualquer embarcação que se aproxime da costa como uma ameaça mortal."},{t="Vingança dos Piratas",b="As baterias de artilharia da Fortaleza da Guardanorte representam um perigo letal para o tráfego marítimo que navega pela Costa dos Mercadores, bombardeando com frequência tanto corsários quanto navios mercantes. Em resposta aos navios afundados, o corsário de Vila Catraca, Capitão Thalo'thas Solaz, procura essas medalhas como prova de que as tropas de gatilho solto da Guardanorte pagaram com sangue por terem afundado seus navios."}},faq={{q="O que é uma Medalha de Theramore?",a="É uma insígnia portada pelo pessoal militar de Theramore alocado na Fortaleza da Guardanorte. Ela identifica quem a carrega como fuzileiro, marinheiro ou oficial ativo a serviço da guarnição da Aliança nos Sertões.",al={"medalha de theramore","o que são medalhas de theramore","medalha da guardanorte"}},{q="Quem carrega essas medalhas?",a="Elas são portadas pelos soldados da Fortaleza da Guardanorte ao longo da Costa dos Mercadores, incluindo fuzileiros, atiradores de elite, marujos de convés, comandos e os canhoneiros e oficiais superiores da guarnição.",al={"quem tem medalhas de theramore","quem concede medalhas de theramore","de onde vêm as medalhas de theramore"}},{q="Por que o Capitão Thalo'thas Solaz quer essas medalhas?",a="As baterias de artilharia da Fortaleza da Guardanorte têm bombardeado navios que passam, inclusive embarcações pertencentes à frota do Capitão Solaz. Ele exige as medalhas como prova inegável de que os soldados responsáveis foram eliminados em retaliação.",al={"por que vila catraca quer medalhas","medalhas do capitão solaz","por que coletar medalhas de theramore"}},{q="Por que a Fortaleza da Guardanorte está atacando navios que passam?",a="A guarnição da Guardanorte opera em um estado de intensa paranoia na fronteira do território da Horda. Seus canhoneiros tornaram-se imprudentes e de gatilho solto, disparando contra praticamente qualquer navio que se aproxime de seu enclave costeiro.",al={"por que a guardanorte atira em navios","agressão da guardanorte","por que a guardanorte ataca vila catraca"}}},fp="15,169,20.455.0,16.386.0,26.153.0,25.150.0,48.222.0,47.193.0"}
P.entries["item:thick-bear-fur"] = {n="Pele Grossa de Urso",s="A Pele Grossa de Urso é um couro valioso obtido dos ursos acostumados ao frio que vagam pelos bancos de neve de Dun Morogh. Cobiçada por sua retenção de calor, é comumente usada por batedores viajantes e soldados para confeccionar isolamento térmico e roupas de cama quentes contra o congelante frio alpino.",h="A Pele Grossa de Urso é um couro valioso obtido dos ursos acostumados ao frio que vagam pelos bancos de neve...",kw={"urrabolha","dun morogh","covil cinzento","ice claw bear","jetsteam","garagem do gradaço","pele grossa de urso"},ang={["class:Hunter"]="Aventurar-se pela vegetação rasteira e fria para caçar os ursos de Dun Morogh ensina aos jovens caçadores como lidar com perigosas feras das montanhas e coletar materiais duráveis da natureza selvagem.",["race:Gnome"]="Pilotos de tanques de cerco como Urrabolha operando ao redor da Garagem do Gradaço precisam contar com a caça prática das terras dos anões para manter suas máquinas habitáveis durante longas incursões alpinas."},sec={{t="Calor Contra a Geada das Montanhas",b="Os ursos que rondam as cordilheiras de Dun Morogh suportam alguns dos campos nevados mais rigorosos dos Reinos do Leste. Suas pelagens grossas e resistentes oferecem proteção vital contra nevascas, tornando o couro um recurso inestimável tanto para os habitantes locais quanto para viajantes. Em vez de serem descartados como refugo, esses couros pesados são regularmente recolhidos por caçadores e usados para forrar roupas, isolar postos avançados expostos a correntes de ar e acolchoar sacos de dormir frios."},{t="Roupas de Cama para a Brigada de Cerco",b="Quando o Piloto Urrabolha começou a equipar seu tanque de cerco, Jetsteam, na Garagem do Gradaço, ele enfrentou a dura perspectiva de passar um mês inteiro em campo em uma longa missão para a Siege Brigade. Como o ferro frio oferece pouco conforto em bancos de neve de grandes altitudes, ele encomendou a batedores locais que juntassem peles grossas de urso dos campos nevados ao sul do Covil Cinzento para confeccionar roupas de cama quentes para os aposentos da sua cabine."}},faq={{q="De onde vem a Pele Grossa de Urso?",a="A Pele Grossa de Urso é obtida dos ursos nativos de Dun Morogh, principalmente Young Black Bears e Ice Claw Bears. Eles podem ser encontrados caçando pelas tundras nevadas e pinheirais ao sul do Covil Cinzento.",al={"onde conseguir pele grossa de urso","quem saqueia pele grossa de urso","localização da pele de urso"}},{q="Por que o Piloto Urrabolha precisa dessa pele?",a="O Piloto Urrabolha está equipando seu tanque, Jetsteam, para uma missão prolongada de um mês em nome da Siege Brigade. Ele precisa de peles pesadas para confeccionar roupas de cama quentes dentro do chassi de metal para suportar as noites congelantes das montanhas.",al={"pele de urrabolha","por que urrabolha precisa de pele","pele para stocking jetsteam"}},{q="Quais criaturas em Dun Morogh fornecem esse couro?",a="Tanto os Young Black Bears quanto os maiores e mais ferozes Ice Claw Bears que vagam pelas neves das terras altas possuem a pelagem densa necessária para roupas de cama de inverno pesadas e isolamento térmico.",al={"quais ursos concedem pele","tipos de urso de dun morogh"}}},fx={a2edc513={q="O que é a Pele Grossa de Urso?",a="A Pele Grossa de Urso é a pelagem pesada e isolante colhida dos ursos selvagens que vagam pelos picos gélidos e pelos montes de neve de Dun Morogh. Adaptada para sobreviver a nevascas cortantes abaixo de zero, esta pele densa fornece calor vital e proteção contra o frio alpino implacável de Khaz Modan.",al={"pele grossa de urso","o que é esta pele","pele de urso de dun morogh"}}},fp="14,164,33.281.0,29.350.0,36.162.0,39.213.0,45.160.0"}
P.entries["item:thick-yeti-hide"] = {n="Thick Yeti Hide",s="Em Feralas, os couros de yeti atraem artesãos do couro que valorizam materiais finos. Pradal McGrubben e Jangdor Passo Veloz os procuram para seu trabalho.",h="Em Feralas, os couros de yeti atraem artesãos do couro que valorizam materiais finos.",kw={"vale dos abomináveis","feralas","costa esquecida","jangdor passo veloz","couraria","pradal mcgrubben","curtimento","thick yeti hide","yeti"},ang={["profession:Tailoring"]="Como artesão do couro, você talvez entenda por que Pradal McGrubben e Jangdor Passo Veloz valorizam couros que, acreditam, podem ser tratados para alcançar uma resistência extraordinária."},sec={{t="A marca de um artesão do couro",b="Os yetis de Feralas são cobiçados por dois artesãos do couro por seus couros espessos. Pradal McGrubben, no Domínio de Plumaluna, e Jangdor Passo Veloz, na Aldeia Mojache, pedem dez Thick Yeti Hides cada um. Em troca, prometem oferecer uma escolha entre seus artigos de couro. Ambos acreditam que um curtimento cuidadoso pode tornar esses couros incrivelmente resistentes."}},faq={{q="De onde vêm os Thick Yeti Hides?",a="Thick Yeti Hides vêm dos yetis de Feralas. Muitos podem ser encontrados no Vale dos Abomináveis, logo para dentro da Costa Esquecida.",al={"origem do couro espesso","onde encontrar couros de yeti","couro de yeti em feralas"}},{q="Quem quer Thick Yeti Hides?",a="Pradal McGrubben, no Domínio de Plumaluna, e Jangdor Passo Veloz, na Aldeia Mojache, procuram dez Thick Yeti Hides cada um.",al={"quem precisa de couros","couros para pradal","couros para jangdor"}},{q="Para que os couros são usados?",a="Pradal McGrubben e Jangdor Passo Veloz querem os couros para seu trabalho com couro. Eles acreditam que um curtimento habilidoso pode torná-los excepcionalmente resistentes.",al={"uso do couro de yeti","para que servem os couros","trabalho com couro"}},{q="O que os artesãos do couro oferecem?",a="Cada artesão do couro oferece uma escolha entre artigos de couro confeccionados em troca de uma pilha de dez Thick Yeti Hides.",al={"troca de couros","recompensa por dez couros","o que recebo"}}},fp="15,152,24.298.0,36.117.0,27.114.0,28.149.0,33.96.0"}
P.entries["item:thistlenettle-s-badge"] = {n="Distintivo de Cardurtiga",s="O distintivo do Encarregado Cardurtiga é tudo o que resta após o desabamento nas Minas Mortas.",h="O distintivo do Encarregado Cardurtiga é tudo o que resta após o desabamento nas Minas Mortas.",kw={"minas mortas","explorers' league","arroio da lua","oh brother","cardurtiga","distintivo de cardurtiga","cerro oeste","wilder"},ang={["faction:Alliance"]="Como membro da Aliança, você pode ajudar um anão enlutado do Distrito dos Anões de Ventobravo a encontrar paz.",["race:Dwarf"]="Como anão, você sabe que o Encarregado Cardurtiga levou o distintivo da Liga dos Exploradores para o Cerro Oeste. Recuperá-lo impede que um filho caído de Altaforja seja esquecido."},sec={{t="A Explorers' League nas Minas Mortas",b="Antes de a Irmandade Défias bloquear Arroio da Lua e os túneis sob a vila, garimpeiros anões da Liga dos Exploradores de Altaforja trabalhavam nas antigas minas de ouro do Cerro Oeste. O Encarregado Cardurtiga e sua equipe estavam no fundo da mina quando um túnel desabou e os separou. Seu irmão Wilder escapou para Ventobravo, mas o encarregado e vários trabalhadores ficaram presos lá embaixo."},{t="Uma Confirmação Sombria",b="O Encarregado Cardurtiga morreu nos túneis não soterrados e voltou como morto-vivo irracional entre os poços desabados fora da fundição principal. O distintivo da Liga dos Exploradores permaneceu com ele. Recuperado e levado ao irmão enlutado, ele comprova a morte do encarregado."}},faq={{q="A quem pertence este distintivo?",a="O distintivo pertencia ao Encarregado Cardurtiga, um minerador anão e membro da Liga dos Exploradores. Um desabamento repentino o prendeu nas profundezas subterrâneas do Cerro Oeste.",al={"quem era o dono do distintivo de cardurtiga","dono do distintivo de cardurtiga"}},{q="Onde o distintivo é encontrado?",a="O Encarregado Cardurtiga carrega o distintivo nos corredores superiores das Minas Mortas, infestados de monstros, fora da entrada principal da fortaleza dos Défias.",al={"localização do distintivo","como obter o distintivo de cardurtiga","onde encontrar cardurtiga"}},{q="Quem quer o Distintivo de Cardurtiga?",a="Wilder Urtigão quer o distintivo. Ele é irmão do encarregado e vive no Distrito dos Anões de Ventobravo, aguardando notícias sobre o destino de seu parente.",al={"quem recebe o distintivo de cardurtiga","quem entrega oh brother","localização de wilder urtigão"}},{q="Por que os irmãos Cardurtiga estavam nas Minas Mortas?",a="Os irmãos exploravam e prospectavam as cavernas ricas em minérios sob Arroio da Lua para a Liga dos Exploradores. Ladrões hostis e desabamentos arruinaram a expedição.",al={"por que os anões estavam nas minas mortas","missão de cardurtiga nas minas mortas"}}},fp="21,84,38.365.0,19.261.1,30.162.0,25.143.0,32.137.0,53.168.0"}
P.entries["item:thistleshrub-dew"] = {n="Orvalho Moitagulhas",s="Em Geringontzan, o Orvalho Moitagulhas deixa Marin Nublacuca com gosto amargo e uma nova ideia. Ele o envia a Pirigget, na esperança de que ela torne a mistura mais fácil de beber.",h="Em Geringontzan, o Orvalho Moitagulhas deixa Marin Nublacuca com gosto amargo e uma nova ideia.",kw={"mistura amarga","culinária","geringontzan","marin nublacuca","pirigget","orvalho moitagulhas"},ang={["profession:Cooking"]="Como alguém que cozinha, você entende por que Marin procura Pirigget: ele espera que a habilidade dela torne a mistura amarga mais fácil de beber."},sec={{t="Um gosto amargo",b="Marin Nublacuca provou o Orvalho Moitagulhas, e o gosto é terrível. Em vez de abandonar a ideia, ele pede que você o leve até Pirigget, sua amiga em Geringontzan. Ela é uma excelente cozinheira, e Marin espera que ela dê mais sabor à bebida."}},faq={{q="Para que serve o Orvalho Moitagulhas?",a="Marin Nublacuca quer que Pirigget use o orvalho para tornar sua mistura desagradável mais fácil de beber.",al={"uso do orvalho moitagulhas","para que serve o orvalho"}},{q="Por que Marin quer a ajuda de Pirigget?",a="Marin acha que a mistura tem um gosto terrível e acredita que Pirigget, uma excelente cozinheira, pode melhorá-la.",al={"por que pirigget","marin precisa de ajuda"}},{q="Quem é Pirigget?",a="Pirigget é cozinheira em Geringontzan e amiga de Marin Nublacuca.",al={"pirigget geringontzan","quem é pirigget"}},{q="Para onde vai o Orvalho Moitagulhas?",a="Marin pede que você leve o Orvalho Moitagulhas até Pirigget, em Geringontzan.",al={"entrega do orvalho","onde levar o orvalho"}}},fp="16,169,14.241.0,29.99.0,36.98.0,16.67.0,31.69.0"}
P.entries["item:thorium-plated-dagger"] = {n="Thorium Plated Dagger",s="Uma Thorium Plated Dagger é uma arma encantada usada por capatazes e escravistas Dark Iron no Caldeirão. Velarok Windblade precisa da liga de tório para criar uma haste resistente.",h="Uma Thorium Plated Dagger é uma arma encantada usada por capatazes e escravistas Dark Iron no Caldeirão.",kw={"caldeirão","escravista dark iron","capataz dark iron","liga encantada","tório","thorium plated dagger","velarok windblade"},sec={{t="Tório encantado",b="Capatazes e escravistas Dark Iron no Caldeirão usam Thorium Plated Daggers feitas de tório encantado. Velarok Windblade procura a liga resistente para reforjar uma haste para a Flawless Flame."}},faq={{q="Quem usa Thorium Plated Daggers?",a="Capatazes e escravistas Dark Iron no Caldeirão usam Thorium Plated Daggers.",al={"quem tem adagas de tório","usuários de adagas dark iron"}},{q="Por que Velarok quer as adagas?",a="Velarok Windblade pode decompor a liga de tório encantada e reforjar uma haste.",al={"por que velarok precisa de adagas","finalidade da adaga"}},{q="De que é feita a adaga?",a="A adaga é feita de tório encantado, uma liga extremamente resistente.",al={"material da adaga de tório","o que há na adaga"}},{q="De quantas adagas Velarok precisa?",a="Velarok Windblade precisa de oito Thorium Plated Daggers.",al={"quantidade de adagas","quantas adagas de tório"}}},fp="21,170,17.191.0,32.79.0,34.83.0,27.61.0,35.53.0"}
P.entries["item:thresher-eye"] = {n="Olho de Mangual",s="Olhos de Mangual são amostras de coleta orgânica obtidas de manguais que rondam as águas costeiras de Costa Negra. Eles são procurados pelo excêntrico engenheiro gnomo Xafetim Manigiro para fazer a manutenção de seus dispositivos de campo automatizados conhecidos como Buzzboxes.",h="Olhos de Mangual são amostras de coleta orgânica obtidas de manguais que rondam as águas costeiras de Costa...",kw={"auberdine","buzzbox 411","costa negra","mangual da costa negra","olho de mangual","xafetim manigiro"},ang={["profession:Engineering"]="A dependência de Xafetim de partes brutas de animais para consertar relés mecânicos complexos oferece um estudo desconcertante, embora bem-humorado, sobre engenhocas gnômicas pouco ortodoxas.",["race:Gnome"]="Xafetim Manigiro representa os limites mais selvagens da inventividade gnômica, fazendo ajustes em maquinários de campo na natureza selvagem de Kalimdor entre taças de vinho de rastejante."},sec={{t="Amostras Ecológicas para Engenhocas Gnômicas",b="Perto da costa enevoada de Costa Negra, predadores aquáticos conhecidos como Manguais da Costa Negra caçam ao longo da arrebentação e das áreas rasas externas. Embora sejam perigosas para os pescadores e viajantes locais, essas feras possuem grandes órgãos oculares que atraíram o interesse peculiar de Xafetim Manigiro. Posicionado por perto e profundamente apegado ao vinho de rastejante, o engenheiro gnômico exige esses olhos como componentes essenciais para consertar o Buzzbox 411, uma de suas máquinas de comunicação de longo alcance, posicionada na praia ao norte de Auberdine."},{t="O Propósito dos Olhos",b="Xafetim nunca explica totalmente como olhos viscosos de criaturas marinhas reparam aparelhos mecânicos delicados, seja funcionando como lentes ópticas rudimentares, agentes químicos ou engrenagens biológicas esotéricas. Independentemente da lógica de engenharia questionável, inserir três desses olhos coletados na escotilha de manutenção do Buzzbox 411 restaura com sucesso o canal de comunicação da máquina, permitindo que Xafetim distribua recompensas por meio de transmissões repletas de estática."}},faq={{q="De onde vêm os Olhos de Mangual?",a="Olhos de Mangual são coletados de Manguais da Costa Negra e Manguais da Costa Negra Anciões que nadam nas águas oceânicas da costa de Costa Negra, principalmente perto de Auberdine.",al={"onde caem olhos de mangual","como obter olho de mangual","fonte de olho de mangual"}},{q="Por que Xafetim Manigiro quer Olhos de Mangual?",a="Xafetim afirma que os olhos são necessários para consertar o Buzzbox 411, uma engenhoca gnômica localizada ao norte de Auberdine, na costa. Inseri-los na escotilha da máquina reativa seus sistemas.",al={"por que precisa de olhos de mangual","olhos do buzzbox 411","para que servem os olhos de mangual"}},{q="Como um olho conserta uma máquina?",a="A engenharia gnômica frequentemente desafia a lógica convencional, especialmente quando guiada pelos planos embriagados de Xafetim Manigiro. Quer ele use as retinas para foco óptico ou simplesmente incorpore partes orgânicas em seus projetos excêntricos, o dispositivo as aceita e volta a ligar.",al={"por que olhos para uma máquina","partes biológicas de máquina de gnomo"}},{q="O que é o Buzzbox 411?",a="O Buzzbox 411 é um de vários dispositivos de comunicação e monitoramento espalhados por Costa Negra por Xafetim Manigiro. Uma vez abastecido com os materiais solicitados, ele permite que Xafetim se comunique remotamente e distribua suprimentos.",al={"propósito do buzzbox 411","quem construiu o buzzbox 411"}}},fx={eb2ee385={q="O que é um Olho de Mangual?",a="Um Olho de Mangual é o órgão ocular colhido dos manguais predadores que nadam nas águas costeiras da Costa Negra. Embora seja matéria biológica mundana para a maioria, o excêntrico engenhoqueiro Xafetim Manigiro encontra neles uma utilidade mecânica ou química bizarra para consertar suas máquinas zumbicaixas de longo alcance.",al={"o que e olho de mangual","olhos de mangual"}}},fp="12,168,38.344.0,23.314.0,33.128.0,48.213.0,30.217.0,20.205.0"}
P.entries["item:thule-s-head"] = {n="Cabeça de Thule",s="A Cabeça de Thule é a prova horripilante exigida pelos Renegados para confirmar a morte de Thule Ravenclaw, comandante das forças do Flagelo na Ilha de Fenris. Trazer este troféu macabro de volta para o Alto-executor Hadrec no Sepulcro consolida o controle dos Renegados sobre a Floresta de Pinhaprata.",h="A Cabeça de Thule é a prova horripilante exigida pelos Renegados para confirmar a morte de Thule Ravenclaw...",kw={"fenris","hadrec","necromante","ravenclaw","flagelo","o sepulcro","thule"},ang={["faction:Horde"]="Eliminar Thule Ravenclaw protege as fronteiras orientais da Floresta de Pinhaprata, protegendo territórios recém-conquistados da Horda contra incursões do Flagelo.",["race:Undead"]="Para os Renegados, decepar a cabeça de Thule é tanto uma vitória militar quanto uma vingança pessoal contra o controle do Lich Rei sobre Lordaeron."},sec={{t="Troféu da Ilha de Fenris",b="A Ilha de Fenris serve como o principal bastião do Flagelo do Lich Rei dentro da Floresta de Pinhaprata. De dentro do Castelo Fenris, o necromante Thule Ravenclaw dirige suas legiões de peles apodrecidas e lacaios mortos-vivos, ameaçando diretamente postos avançados dos Renegados como O Sepulcro. O Alto-executor Hadrec exige certeza absoluta de que este comandante sombrio caiu, recusando-se a aceitar qualquer testemunho que não seja a cabeça decepada de Thule. A liberação violenta de magia sombria com a morte de Ravenclaw foi sentida por toda a floresta, mas sua cabeça permanece como a prova física que Hadrec exige para declarar a Ilha de Fenris derrotada."}},faq={{q="Quem quer a Cabeça de Thule?",a="O Alto-executor Hadrec, comandante das operações militares dos Renegados estacionado no Sepulcro na Floresta de Pinhaprata, exige a Cabeça de Thule para confirmar a eliminação do líder do Flagelo.",al={"quem precisa da cabeça de thule","quem entrega a cabeça de thule para","quem recebe a cabeça de thule"}},{q="Quem era Thule Ravenclaw?",a="Thule Ravenclaw é um poderoso necromante que comanda a presença do Flagelo na Ilha de Fenris. Do coração do Castelo Fenris, ele orquestra ataques contra os Renegados e empunha encantamentos sinistros como a Maldição de Ravenclaw.",al={"história de thule","quem é thule","histórico de thule ravenclaw"}},{q="Por que os Renegados exigem a cabeça dele especificamente?",a="Os Renegados não podem tolerar ameaças persistentes do Flagelo em Pinhaprata. Como os necromantes são notórios por engano e ressurreições sombrias, o Alto-executor Hadrec não aceita nada menos que uma prova física e irrefutável da destruição total de Thule.",al={"por que a cabeça de thule","por que eles querem a cabeça dele"}},{q="O que acontece quando Thule Ravenclaw é morto?",a="Após a derrota de Thule, uma explosão violenta de energia necrótica irradia pela região, potente o suficiente para que estudiosos e boticários dos Renegados no Sepulcro possam sentir a onda de choque mágica de longe.",al={"o que acontece depois que thule morre","energia liberada por thule"}}},fx={["3fe7e40b"]={q="De onde vem a Cabeça de Thule?",a="Esta cabeça decepada é tirada diretamente do necromante Thule Ravenclaw dentro dos salões do Castelo Fenris. Thule liderou as forças do Flagelo que tomaram a Ilha de Fenris na parte norte da Floresta de Pinhaprata, transformando a fortaleza em um bastião dos mortos-vivos até você derrotá-lo.",al={"origem da cabeça de thule","onde conseguir a cabeça de thule","fonte da cabeça de thule"}}},fp="12,201,21.432.1,23.152.0,24.198.0,49.193.0,43.163.1"}
P.entries["item:thunder-lizard-blood"] = {n="Sangue de Lagarto Trovejante",s="Sangue de Lagarto Trovejante é um fluido vital extraído dos enormes lagartos trovejantes que vagam pelos Sertões Meridionais. Ele serve como prova marcial de sobrevivência contra algumas das feras terrestres mais esmagadoras de Kalimdor.",h="Sangue de Lagarto Trovejante é um fluido vital extraído dos enormes lagartos trovejantes que vagam pelos...",kw={"sertões","acampamento taurajo","jorn vidente do céu","stormhide","stormsnout","sangue de lagarto trovejante","thunderhead"},ang={["class:Hunter"]="Superar um lagarto trovejante exige posicionamento firme e agilidade; coletar seu sangue comprova o domínio sobre as maiores feras da savana.",["race:Tauren"]="Para os caçadores taurens baseados no Acampamento Taurajo, enfrentar os lagartos trovejantes é um teste tradicional de sobrevivência ao lado dos formidáveis gigantes de sua terra natal."},sec={{t="Troféu da Caçada",b="Os lagartos trovejantes, conhecidos pelas planícies como Focinhos-de-tempestade, Couros-de-tempestade e Cabeças-de-trovão, são feras colossais cujas passadas pesadas estremecem a terra. Caçá-los é um exercício de pisada perigosa, já que seu peso esmagador achata com facilidade os caçadores incautos. Trazer seu sangue demonstra não apenas perícia de caça, mas a pura resistência necessária para sobreviver a um combate sob seus pés trovejantes."}},faq={{q="Quais criaturas fornecem esse sangue?",a="O sangue é coletado dos lagartos trovejantes adultos que vagam pela savana ao redor do Acampamento Taurajo, nos Sertões Meridionais, especificamente Focinhos-de-tempestade, Couros-de-tempestade e Cabeças-de-trovão.",al={"quem dropa sangue de lagarto trovejante","onde conseguir sangue de lagarto trovejante","quais lagartos trovejantes"}},{q="Por que o Sangue de Lagarto Trovejante é procurado?",a="Jorn Vidente do Céu, no Acampamento Taurajo, incumbe os caçadores de coletar o sangue como parte dos testes pelos Sertões. Retornar com ele intacto prova que um caçador pode enfrentar os maiores gigantes pisoteadores de Kalimdor.",al={"quem quer sangue de lagarto trovejante","para que serve sangue de lagarto trovejante"}},{q="Onde esses lagartos trovejantes são encontrados com mais frequência?",a="Eles vagam pelas pastagens que se estendem ao norte, leste e sul do Acampamento Taurajo, pastando ao lado da outra grande fauna dos Sertões Meridionais.",al={"localizações de lagartos trovejantes","onde encontrar focinhos-de-tempestade"}}},fx={["25735f1e"]={q="O que é o Sangue de Lagarto Trovejante?",a="O Sangue de Lagarto Trovejante é um fluido vital colhido dos enormes lagartos trovejantes que vagam pelos Sertões Meridionais. Essas bestas imponentes fazem as planícies tremerem a cada passo, e colher seu sangue serve como prova irrefutável de que um caçador possuía a habilidade e a resiliência para derrubar criaturas tão formidáveis sem ser esmagado sob os pés.",al={"o que é sangue de lagarto trovejante","item sangue de lagarto trovejante","sobre sangue de lagarto trovejante"}},d2820178={q="De onde vem o Sangue de Lagarto Trovejante e quem o fez?",a="Este sangue é naturalmente retirado dos poderosos lagartos trovejantes que habitam os Sertões Meridionais, especificamente as raças conhecidas como Stormsnouts, Stormhides e Thunderheads. Ele não é fabricado ou criado por mãos mortais, mas tirado diretamente dessas bestas colossais por caçadores que ousam enfrentar seus cascos pisoteadores pela savana.",al={"de onde vem o sangue de lagarto trovejante","quem fez o sangue de lagarto trovejante","origem do sangue de lagarto trovejante"}}},fp="20,118,18.304.0,34.152.0,41.186.0,46.152.0"}
P.entries["item:thunder-lizard-horn"] = {n="Cifre de Lagarto Trovejante",s="Um cifre de lagarto trovejante é um troféu resistente obtido dos enormes lagartos trovejantes sintonizados com relâmpagos que vagam pelos Sertões. O Cervejeiro Drohn, em Vila Catraca, procura este reagente incomum para recriar uma bebida lendária originalmente preparada por Chen Stormstout.",h="Um cifre de lagarto trovejante é um troféu resistente obtido dos enormes lagartos trovejantes sintonizados...",kw={"sertões","cervejeiro drohn","chen stormstout","owatanka","vila catraca","stormsnout","stormstout","cifre de lagarto trovejante","thunderhead"},ang={["class:Hunter"]="Rastrear lagartos trovejantes pela savana aberta exige cautela, pois suas descargas elétricas naturais os tornam muito mais mortais do que os kodos ou plainstriders comuns dos Sertões.",["profession:Cooking"]="Aventureiros da culinária frequentemente se maravilham com a receita incomum do Cervejeiro Drohn, que combina órgãos de plainstrider, presas de predadores e o chifre de uma fera para criar uma bebida inebriante."},sec={{t="Um Reagente de Cervejaria Potente",b="Os lagartos trovejantes vagam pelas planícies áridas dos Sertões, crepitando com relâmpagos puros e localizados que saltam de seus corpos com cristas. Embora caçadores ocasionalmente busquem seus couros grossos, o Cervejeiro Drohn, em Vila Catraca, valoriza seus chifres para um propósito muito diferente. Transmitida por um mentor que a aprendeu com o cervejeiro pandaren errante Chen Stormstout, a receita da cerveja Stormstout exige ingredientes locais incomuns e potentes. O chifre de um lagarto trovejante fornece o toque eletrizante que dá à lendária bebida seu trago ardente e inesquecível."}},faq={{q="Para que serve o chifre?",a="O chifre é usado pelo Cervejeiro Drohn em Vila Catraca como um ingrediente essencial para recriar a famosa bebida homônima de Chen Stormstout, conhecida por seu efeito potente.",al={"uso do cifre de lagarto trovejante","o que usa cifre de lagarto trovejante","por que preciso de cifre de lagarto trovejante"}},{q="Quais feras concedem um cifre de lagarto trovejante?",a="Qualquer uma das raças de lagartos trovejantes pelos Sertões pode conceder um chifre, incluindo thunderheads, stormsnouts, thunderstomps, stormhides e a fera esquiva Owatanka.",al={"onde conseguir cifre de lagarto trovejante","quem dropa cifre de lagarto trovejante","fontes de cifre de lagarto trovejante"}},{q="Quem é o Cervejeiro Drohn?",a="O Cervejeiro Drohn é um cervejeiro que atua no porto goblin de Vila Catraca. Seu antigo mentor aprendeu a receita da stormstout diretamente do famoso andarilho Chen Stormstout e a transmitiu a ele.",al={"quem é drohn","história cervejeiro drohn","drohn vila catraca"}},{q="É perigoso caçar lagartos trovejantes pelos seus chifres?",a="Os lagartos trovejantes são feras formidáveis que descarregam relâmpagos naturalmente e desferem pisadas estrondosas quando provocados, tornando a coleta de seus chifres uma empreitada perigosa para viajantes solitários.",al={"quão fortes são lagartos trovejantes","caçar lagartos trovejantes"}}},fx={["6ace69b3"]={q="O que é um Cifre de Lagarto Trovejante?",a="Um Cifre de Lagarto Trovejante é um troféu natural robusto colhido dos grandes lagartos trovejantes que vagam pelas planícies dos Sertões. Esses répteis imponentes e sintonizados com a tempestade canalizam energia elétrica através de seus corpos massivos, tornando seus chifres um componente natural potente, valorizado por artesãos raros com receitas não convencionais.",al={"o que é cifre de lagarto trovejante","informações sobre cifre de lagarto trovejante","sobre cifre de lagarto trovejante"}},["1dc3a738"]={q="De onde vem um Cifre de Lagarto Trovejante?",a="Não é uma criação artificial, mas um chifre tirado diretamente dos formidáveis lagartos trovejantes dos Sertões, incluindo criaturas como stormsnouts, thunderheads e o esquivo Owatanka. Matar uma dessas bestas massivas permite que você reivindique o chifre intacto.",al={"de onde vêm os cifres de lagarto trovejante","quem faz cifre de lagarto trovejante","fonte de cifre de lagarto trovejante"}}},fp="19,98,24.297.0,26.82.0,41.111.0,24.130.0,54.117.0"}
